(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("epictetus-discourses-b",[{"sp":"HDR","t":"Βιβλίον αʹ","st":"1.1"},{"sp":"N","t":"τῶν ἄλλων δυνάμεων οὐδεμίαν εὑρήσετε αὐτὴν αὑτῆς θεωρητικήν, οὐ τοίνυν οὐδὲ δοκιμαστικὴν ἢ ἀποδοκιμαστικήν. ἡ γραμματικὴ μέχρι τίνος κέκτηται τὸ θεωρητικόν; μέχρι τοῦ διαγνῶναι τὰ γράμματα. ἡ μουσική; μέχρι τοῦ διαγνῶναι τὸ μέλος.","st":"1.1"},{"sp":"N","t":"αὐτὴ οὖν αὑτὴν θεωρεῖ τις αὐτῶν; οὐδαμῶς. ἀλλ᾽ ὅτε μέν, ἄν τι γράφῃς τῷ ἑταίρῳ, δεῖ τούτων τῶν γραπτέων, ἡ γραμματικὴ ἐρεῖ: πότερον δὲ γραπτέον τῷ ἑταίρῳ ἢ οὐ γραπτέον, ἡ γραμματικὴ οὐκ ἐρεῖ. καὶ περὶ τῶν μελῶν ὡσαύτως ἡ μουσική: πότερον δ᾽ ᾀστέον νῦν καὶ κιθαριστέον ἢ οὔτε ᾀστέον οὔτε κιθαριστέον οὐκ ἐρεῖ.","st":"1.1"},{"sp":"N","t":"τίς οὖν ἐρεῖ; ἡ καὶ αὑτὴν θεωροῦσα καὶ τἆλλα πάντα. αὕτη δ᾽ ἐστὶ τίς; ἡ δύναμις ἡ λογική: μόνη γὰρ αὕτη καὶ αὑτὴν κατανοήσουσα παρείληπται, τίς τέ ἐστι καὶ τί δύναται καὶ πόσου ἀξία οὖσα ἐλήλυθεν, καὶ τὰς ἄλλας ἁπάσας.","st":"1.1"},{"sp":"N","t":"τί γάρ ἐστιν ἄλλο τὸ λέγον ὅτι χρυσίον καλόν ἐστιν; αὐτὸ γὰρ οὐ λέγει. δῆλον ὅτι ἡ χρηστικὴ δύναμις ταῖς φαντασίαις. τί ἄλλο τὸ μουσικήν,","st":"1.1"},{"sp":"N","t":"γραμματικήν, τὰς ἄλλας δυνάμεις διακρῖνον, δοκιμάζον τὰς χρήσεις αὐτῶν καὶ τοὺς καιροὺς παραδεικνύον; οὐδὲν ἄλλο.","st":"1.1"},{"sp":"N","t":"ὥσπερ οὖν ἦν ἄξιον, τὸ κράτιστον ἁπάντων καὶ κυριεῦον οἱ θεοὶ μόνον ἐφ᾽ ἡμῖν ἐποίησαν, τὴν χρῆσιν τὴν ὀρθὴν ταῖς φαντασίαις, τὰ δ᾽ ἄλλα οὐκ ἐφ᾽ ἡμῖν. ἆρά γε ὅτι οὐκ ἤθελον;","st":"1.1"},{"sp":"N","t":"ἐγὼ μὲν δοκῶ ὅτι, εἰ ἠδύναντο, κἀκεῖνα ἂν ἡμῖν ἐπέτρεψαν: ἀλλὰ πάντως οὐκ ἠδύναντο.","st":"1.1"},{"sp":"N","t":"ἐπὶ γῆς γὰρ ὄντας καὶ σώματι συνδεδεμένους τοιούτῳ καὶ κοινωνοῖς τοιούτοις πῶς οἷόν τ᾽ ἦν εἰς ταῦτα ὑπὸ τῶν ἐκτὸς μὴ ἐμποδίζεσθαι; ἀλλὰ τί λέγει ὁ Ζεύς;","st":"1.1"},{"sp":"N","t":"‘Ἐπίκτητε, εἰ οἷόν τε ἦν, καὶ τὸ σωμάτιον ἄν σου καὶ τὸ κτησίδιον ἐποίησα ἐλεύθερον καὶ ἀπαραπόδιστον.","st":"1.1"},{"sp":"N","t":"νῦν δέ, μή σε λανθανέτω, τοῦτο οὐκ ἔστιν σόν, ἀλλὰ πηλὸς κομψῶς πεφυραμένος.","st":"1.1"},{"sp":"N","t":"ἐπεὶ δὲ τοῦτο οὐκ ἠδυνάμην, ἐδώκαμέν σοι μέρος τι ἡμέτερον, τὴν δύναμιν ταύτην τὴν ὁρμητικήν τε καὶ ἀφορμητικὴν καὶ ὀρεκτικήν τε καὶ ἐκκλιτικὴν καὶ ἁπλῶς τὴν χρηστικὴν ταῖς φαντασίαις, ἧς ἐπιμελούμενος καὶ ἐν ᾗ τὰ σαυτοῦ τιθέμενος οὐδέποτε κωλυθήσῃ, οὐδέποτ᾽ ἐμποδισθήσῃ, οὐ στενάξεις, οὐ μέμψῃ, οὐ κολακεύσεις οὐδένα.","st":"1.1"},{"sp":"N","t":"τί οὖν; μή τι μικρά σοι φαίνεται ταῦτα;’ ‘μὴ γένοιτο.’ ‘ἀρκῇ οὖν αὐτοῖς;’ ‘εὔχομαι † δὲ τοῖς θεοῖς.’","st":"1.1"},{"sp":"N","t":"νῦν δ᾽ ἑνὸς δυνάμενοι ἐπιμελεῖσθαι καὶ ἑνὶ προσηρτηκέναι ἑαυτοὺς μᾶλλον θέλομεν πολλῶν ἐπιμελεῖσθαι καὶ πολλοῖς προσδεδέσθαι καὶ τῷ σώματι καὶ τῇ κτήσει καὶ ἀδελφῷ καὶ φίλῳ καὶ τέκνῳ καὶ δούλῳ.","st":"1.1"},{"sp":"N","t":"ἅτε οὖν πολλοῖς προσδεδεμένοι βαρούμεθα ὑπ᾽ αὐτῶν καὶ καθελκόμεθα.","st":"1.1"},{"sp":"N","t":"διὰ τοῦτο, ἂν ἄπλοια ᾖ, καθήμεθα σπώμενοι καὶ παρακύπτομεν συνεχῶς: ‘τίς ἄνεμος πνεῖ; βορέας.’ τί ἡμῖν καὶ αὐτῷ; ‘πότε ὁ ζέφυρος πνεύσει;’ ὅταν αὐτῷ δόξῃ, ὦ βέλτιστε, ἢ τῷ Αἰόλῳ. σὲ γὰρ οὐκ ἐποίησεν ὁ θεὸς ταμίαν τῶν ἀνέμων, ἀλλὰ τὸν Αἴολον.","st":"1.1"},{"sp":"N","t":"τί οὖν; δεῖ τὰ ἐφ᾽ ἡμῖν βέλτιστα κατασκευάζειν, τοῖς δ᾽ ἄλλοις χρῆσθαι ὡς πέφυκεν. ‘πῶς οὖν πέφυκεν;’ ὡς ἂν ὁ θεὸς θέλῃ.","st":"1.1"},{"sp":"N","t":"‘ἐμὲ οὖν νῦν τραχηλοκοπεῖσθαι μόνον;’ τί οὖν; ἤθελες πάντας τραχηλοκοπηθῆναι, ἵνα σὺ παραμυθίαν ἔχῃς; οὐ θέλεις οὕτως ἐκτεῖναι τὸν τράχηλον,","st":"1.1"},{"sp":"N","t":"ὡς Λατερανός τις ἐν τῇ Ῥώμῃ κελευσθεὶς ὑπὸ τοῦ Νέρωνος ἀποκεφαλισθῆναι; ἐκτείνας γὰρ τὸν τράχηλον καὶ πληγεὶς καὶ πρὸς αὐτὴν τὴν πληγὴν ἀσθενῆ γενομένην ἐπ᾽ ὀλίγον συνελκυσθεὶς πάλιν ἐξέτεινεν.","st":"1.1"},{"sp":"N","t":"ἀλλὰ καὶ ἔτι πρότερον προσελθόντι τις Ἐπαφροδίτῳ τῷ † κυρίῳ τοῦ Νέρωνος καὶ ἀνακρίνοντι αὐτὸν ὑπὲρ τοῦ συγκρουσθῆναι ‘ἄν τί θέλω,’ φησίν, ‘ἐρῶ σου τῷ κυρίῳ.’","st":"1.1"},{"sp":"N","t":"‘τί οὖν δεῖ πρόχειρον ἔχειν ἐν τοῖς τοιούτοις;’ τί γὰρ ἄλλο ἢ τί ἐμὸν καὶ τί οὐκ ἐμὸν καὶ τί μοι ἔξεστιν καὶ τί μοι οὐκ ἔξεστιν;","st":"1.1"},{"sp":"N","t":"ἀποθανεῖν με δεῖ: μή τι οὖν καὶ στένοντα; δεθῆναι: μή τι καὶ θρηνοῦντα; φυγαδευθῆναι: μή τις οὖν κωλύει γελῶντα καὶ εὐθυμοῦντα καὶ εὐροοῦντα;","st":"1.1"},{"sp":"N","t":"‘εἰπὲ τὰ ἀπόρρητα.’ οὐ λέγω: τοῦτο γὰρ ἐπ᾽ ἐμοί ἐστιν. ‘ἀλλὰ δήσω σε.’ ἄνθρωπε. τί λέγεις; ἐμέ; τὸ σκέλος μου δήσεις, τὴν προαίρεσιν δὲ οὐδ᾽ ὁ Ζεὺς νι","st":"1.1"},{"sp":"N","t":"κῆσαι δύναται. ‘εἰς φυλακήν σε βαλῶ.’ τὸ σωμάτιον. ‘ἀποκεφαλίσω σε.’ πότε οὖν σοὶ εἶπον, ὅτι μόνου ἐμοῦ ὁ τράχηλος ἀναπότμητός ἐστιν;","st":"1.1"},{"sp":"N","t":"ταῦτα ἔδει μελετᾶν τοὺς φιλοσοφοῦντας, ταῦτα καθ᾽ ἡμέραν γράφειν, ἐν τούτοις γυμνάζεσθαι. Θρασέας εἰώθει λέγειν","st":"1.1"},{"sp":"N","t":"‘σήμερον ἀναιρεθῆναι θέλω μᾶλλον ἢ αὔριον φυγαδευθῆναι’","st":"1.1"},{"sp":"N","t":"τί οὖν αὐτῷ Ῥοῦφος εἶπεν; ‘εἰ μὲν ὡς βαρύτερον ἐκλέγῃ, τίς ἡ μωρία τῆς ἐκλογῆς; εἰ δ᾽ ὡς κουφότερον, τίς σοι δέδωκεν; οὐ θέλεις μελετᾶν ἀρκεῖσθαι τῷ δεδομένῳ;’","st":"1.1"},{"sp":"N","t":"διὰ τοῦτο γὰρ Ἀγριππῖνος τί ἔλεγεν; ὅτι ‘ἐγὼ ἐμαυτῷ ἐμπόδιος οὐ γίνομαι.’ ἀπηγγέλη αὐτῷ ὅτι","st":"1.1"},{"sp":"N","t":"‘κρίνῃ ἐν συγκλήτῳ.’—’ἀγαθῇ τύχῃ. ἀλλὰ ἦλθεν ἡ πέμπτη’ （ ταύτῃ δ᾽ εἰώθει γυμνασάμενος ψυχρολουτρεῖν ） :","st":"1.1"},{"sp":"N","t":"‘ἀπέλθωμεν καὶ γυμνασθῶμεν.’ γυμνασαμένῳ λέγει τις, αὐτῷ ἐλθὼν ὅτι ‘Κατακέκρισαι.’—’φυγῇ,’, φησίν, ‘ἢ θανάτῳ;’—’φυγῇ.’—’τὰ ὑπάρχοντα τί;’—’οὐκ ἀφῃρέθη.’—’εἰς Ἀρίκειαν οὖν ἀπελθόντες ἀριστήσωμεν. ‘","st":"1.1"},{"sp":"N","t":"— τοῦτ᾽ ἔστι μεμελετηκέναι ἃ δεῖ μελετᾶν, ὄρεξιν ἔκκλισιν ἀκώλυτα ἀπερίπτωτα παρεσκευακέναι. ἀποθανεῖν με δεῖ.","st":"1.1"},{"sp":"N","t":"εἰ ἤδη, ἀποθνῄσκω: κἂν μετ᾽ ὀλίγον, νῦν ἀριστῶ τῆς ὥρας ἐλθούσης, εἶτα τότε τεθνήξομαι. πῶς; ὡς προσήκει τὸν τὰ ἀλλότρια ἀποδιδόντα. πῶς ἄν τις σῴζοι τὸ κατὰ πρόσωπον ἐν παντί. τῷ λογικῷ ζῴῳ μόνον ἀφόρητόν ἐστι τὸ ἄλογον, τὸ δ᾽ εὔλογον φορητόν.","st":"1.1"},{"sp":"N","t":"πληγαὶ οὐκ εἰσὶν ἀφόρητοι τῇ φύσει. — τίνα τρόπον; — ὅρα πῶς: Λακεδαιμόνιοι μαστιγοῦνται μαθόντες ὅτι εὔλογόν ἐστιν.","st":"1.2"},{"sp":"N","t":"— τὸ δ᾽ ἀπάγξασθαι οὐκ ἔστιν ἀφόρητον; — ὅταν γοῦν πάθῃ τις ὅτι εὔ","st":"1.2"},{"sp":"N","t":"λογον, ἀπελθὼν ἀπήγξατο. ἁπλῶς ἐὰν προσέχωμεν, ὑπ᾽ οὐδενὸς οὕτως εὑρήσομεν τὸ ζῷον θλιβόμενον ὡς ὑπὸ τοῦ ἀλόγου καὶ πάλιν ἐπ᾽ οὐδὲν οὕτως ἑλκόμενον ὡς ἐπὶ τὸ εὔλογον.","st":"1.2"},{"sp":"N","t":"ἄλλῳ δ᾽ ἄλλο προσπίπτει τὸ εὔλογον καὶ ἄλογον, καθάπερ καὶ ἀγαθὸν καὶ κακὸν ἄλλο ἄλλῳ καὶ συμφέρον καὶ ἀσύμφορον.","st":"1.2"},{"sp":"N","t":"διὰ τοῦτο μάλιστα παιδείας δεόμεθα, ὥστε μαθεῖν τοῦ εὐλόγου καὶ ἀλόγου πρόληψιν ταῖς ἐπὶ μέρους οὐσίαις ἐφαρμόζειν συμφώνως τῇ φύσει.","st":"1.2"},{"sp":"N","t":"εἰς δὲ τὴν τοῦ εὐλόγου καὶ ἀλόγου κρίσιν οὐ μόνον ταῖς τῶν ἐκτὸς ἀξίαις συγχρώμεθα, ἀλλὰ καὶ τῶν κατὰ τὸ πρόσωπον ἑαυτοῦ ἕκαστος.","st":"1.2"},{"sp":"N","t":"τῷ μὲν γάρ τινι εὔλογον τὸ ἀμίδα παρακρατεῖν αὐτὸ μόνον βλέποντι, ὅτι μὴ παρακρατήσας μὲν πληγὰς λήψεται καὶ τροφὰς οὐ λήψεται, παρακρατήσας δ᾽ οὐ πείσεταί τι τραχὺ ἢ ἀνιαρόν:","st":"1.2"},{"sp":"N","t":"ἄλλῳ δέ τινι οὐ μόνον τὸ αὐτὸν παρακρατῆσαι ἀφόρητον δοκεῖ, ἀλλὰ καὶ τὸ ἄλλου παρακρατοῦντος ἀνασχέσθαι.","st":"1.2"},{"sp":"N","t":"ἂν οὖν μου πυνθάνῃ ‘παρακρατήσω τὴν ἀμίδα ἢ μή;,’ ἐρῶ σοι ὅτι μείζονα ἀξίαν ἔχει τὸ λαβεῖν τροφὰς τοῦ μὴ λαβεῖν καὶ μείζονα ἀπαξίαν τὸ δαρῆναι τοῦ μὴ δαρῆναι: ὥστ᾽ εἰ τούτοις παραμετρεῖς τὰ σαυτοῦ, ἀπελθὼν παρακράτει.","st":"1.2"},{"sp":"N","t":"‘ἀλλ᾽ οὐκ ἂν κατ᾽ ἐμέ.’ τοῦτο σὲ δεῖ συνεισφέρειν εἰς τὴν σκέψιν, οὐκ ἐμέ. σὺ γὰρ εἶ ὁ σαυτὸν εἰδώς, πόσου ἄξιος εἶ σεαυτῷ καὶ πόσου σεαυτὸν πιπράσκεις: ἄλλοι γὰρ ἄλλων πιπράσκουσιν.","st":"1.2"},{"sp":"N","t":"διὰ τοῦτο Ἀγριππῖνος Φλώρῳ σκεπτομένῳ, εἰ καταβατέον αὐτῷ ἐστιν εἰς Νέρωνος θεωρίας, ὥστε καὶ αὐτόν τι λειτουργῆσαι, ἔφη","st":"1.2"},{"sp":"N","t":"‘κατάβηθι.’ πυθομένου δ᾽ αὐτοῦ ‘διὰ τί σὺ οὐ καταβαίνεις;’ ἔφη ὅτι ‘ἐγὼ οὐδὲ βουλεύομαι.’","st":"1.2"},{"sp":"N","t":"ὁ γὰρ ἅπαξ εἰς τὴν περὶ τῶν τοιούτων σκέψιν καὶ τὰς τῶν ἐκτὸς ἀξίας συγκαθεὶς καὶ ψηφίζων ἐγγύς ἐστι τῶν ἐπιλελησμένων τοῦ ἰδίου προσώπου.","st":"1.2"},{"sp":"N","t":"τί γάρ μου πυνθάνῃ; ‘θάνατος αἱρετώτερόν ἐστιν ἢ ζωή;’ λέγω ζωή.","st":"1.2"},{"sp":"N","t":"‘πόνος ἢ ἡδονή;’ λέγω ἡδονή. ‘ἀλλά, ἂν μὴ τραγῳδήσω, τραχηλοκοπηθήσομαι.’ ἄπελθε τοίνυν καὶ τραγῴδει, ἐγὼ δ᾽ οὐ τραγῳδήσω.","st":"1.2"},{"sp":"N","t":"‘διὰ τί;’ ὅτι σὺ σεαυτὸν ἡγῇ μίαν τινὰ εἶναι κρόκην τῶν ἐκ τοῦ χιτῶνος. τί οὖν; σὲ ἔδει φροντίζειν πῶς ἀνόμοιος ᾖς τοῖς ἄλλοις ἀνθρώποις, ὥσπερ οὐδ᾽ ἡ κρόκη πρὸς τὰς ἄλλας κρόκας θέλει τι ἔχειν ἐξαίρετον.","st":"1.2"},{"sp":"N","t":"ἐγὼ δὲ πορφύρα εἶναι βούλομαι, τὸ ὀλίγον ἐκεῖνο καὶ στιλπνὸν καὶ τοῖς ἄλλοις αἴτιον τοῦ εὐπρεπῆ φαίνεσθαι καὶ καλά. τί οὖν μοι λέγεις ὅτι ‘ἐξομοιώθητι τοῖς πολλοῖς;’ καὶ πῶς ἔτι πορφύρα ἔσομαι;","st":"1.2"},{"sp":"N","t":"ταῦτα εἶδεν καὶ Πρῖσκος Ἑλουίδιος καὶ ἰδὼν ἐποίησε. προσπέμψαντος αὐτῷ Οὐεσπασιανοῦ, ἵνα μὴ εἰσέλθῃ εἰς τὴν σύγκλητον, ἀπεκρίνατο ‘ἐπὶ σοί ἐστι μὴ ἐᾶσαί με εἶναι συγκλητικόν: μέχρι δὲ ἂν ὦ, δεῖ με εἰσέρχεσθαι.’","st":"1.2"},{"sp":"N","t":"‘ἄγε ἀλλ᾽ εἰσελθών,’ φησίν, ‘σιώπησον.’ ‘μή μ᾽ ἐξέταζε καὶ σιωπήσω.’ ‘ἀλλὰ δεῖ με ἐξετάσαι.’ ‘κἀμὲ εἰπεῖν τὸ φαινόμενον δίκαιον.’ ‘ἀλλ᾽ ἐὰν εἴπῃς, ἀποκτενῶ σε.’","st":"1.2"},{"sp":"N","t":"‘πότε οὖν σοι εἶπον, ὅτι ἀθάνατός εἰμι; καὶ σὺ τὸ σὸν ποιήσεις κἀγὼ τὸ ἐμόν. σόν ἐστιν ἀποκτεῖναι, ἐμὸν ἀποθανεῖν μὴ τρέμοντα: σὸν φυγαδεῦσαι, ἐμὸν ἐξελθεῖν μὴ λυπούμενον.’","st":"1.2"},{"sp":"N","t":"τί οὖν ὠφέλησε Πρῖσκος εἷς ὤν; τί δ᾽ ὠφελεῖ ἡ πορφύρα τὸ ἱμάτιον; τί γὰρ ἄλλο ἢ διαπρέπει ἐν αὐτῷ ὡς πορφύρα καὶ τοῖς ἄλλοις δὲ καλὸν παράδειγμα ἔκκειται;","st":"1.2"},{"sp":"N","t":"ἄλλος δ᾽ ἂν εἰπόντος αὐτῷ Καίσαρος ἐν τοιαύτῃ περὶ στάσει μὴ ἐλθεῖν εἰς σύγκλητον εἶπεν","st":"1.2"},{"sp":"N","t":"‘ἔχω χάριν, ὅτι μου φείδῃ.’ τὸν τοιοῦτον οὐδ᾽ ἂν ἐκώλυεν εἰσελθεῖν, ἀλλ᾽ ᾔδει, ὅτι ἢ καθεδεῖται ὡς κεράμιον ἢ λέγων ἐρεῖ, ἃ οἶδεν ὅτι ὁ Καῖσαρ θέλει, καὶ προσεπισωρεύσει ἔτι πλείονα.","st":"1.2"},{"sp":"N","t":"τοῦτον τὸν τρόπον καὶ ἀθλητής τις κινδυνεύων ἀποθανεῖν, εἰ μὴ ἀπεκόπη τὸ αἰδοῖον, ἐπελθόντος αὐτῷ τοῦ ἀδελφοῦ （ ἦν δ᾽ ἐκεῖνος φιλόσοφος ） καὶ εἰπόντος ‘ἄγε, ἀδελφέ, τί μέλλεις ποιεῖν; ἀποκόπτομεν τοῦτο τὸ μέρος καὶ ἔτι εἰς γυμνάσιον προερχόμεθα;’ οὐχ ὑπέμεινεν, ἀλλ᾽ ἐγκαρτερήσας ἀπέθανεν.","st":"1.2"},{"sp":"N","t":"πυθομένου δέ τινος: πῶς τοῦτο ἐποίησεν; ὡς ἀθλητὴς ἢ ὡς φιλόσοφος; ὡς ἀνήρ, ἔφη, ἀνὴρ δ᾽ Ὀλύμπια κεκηρυγμένος καὶ ἠγωνισμένος, ἐν τοιαύτῃ τινὶ χώρᾳ ἀνεστραμμένος, οὐχὶ παρὰ τῷ Βάτω","st":"1.2"},{"sp":"N","t":"νι ἀλειφόμενος. ἄλλος δὲ κἂν τὸν τράχηλον ἀπετμήθη, εἰ ζῆν ἠδύνατο δίχα τοῦ τραχήλου.","st":"1.2"},{"sp":"N","t":"τοιοῦτόν ἐστι τὸ κατὰ πρόσωπον: οὕτως ἰσχυρὸν παρὰ τοῖς εἰθισμένοις αὐτὸ συνεισφέρειν ἐξ αὐτῶν ἐν ταῖς σκέψεσιν.","st":"1.2"},{"sp":"N","t":"‘ἄγε οὖν, Ἐπίκτητε, διαξύρησαι.’ ἂν ὦ φιλόσοφος, λέγω ‘οὐ διαξυρῶμαι.’ ‘ἀλλ᾽ ἀφελῶ σου τὸν τράχηλον.’ εἰ σοὶ ἄμεινον, ἄφελε.","st":"1.2"},{"sp":"N","t":"ἐπύθετό τις: πόθεν οὖν αἰσθησόμεθα τοῦ κατὰ πρόσωπον ἕκαστος; — πόθεν δ᾽ ὁ ταῦρος, ἔφη, λέοντος ἐπελθόντος μόνος αἰσθάνεται τῆς αὑτοῦ παρασκευῆς καὶ προβέβληκεν ἑαυτὸν ὑπὲρ τῆς ἀγέλης πάσης; ἢ δῆλον ὅτι εὐθὺς ἅμα τῷ τὴν παρασκευὴν ἔχειν ἀπαντᾷ καὶ συναίσθησις αὐτῆς;","st":"1.2"},{"sp":"N","t":"καὶ ἡμῶν τοίνυν ὅστις ἂν ἔχῃ τοιαύτην παρασκευήν, οὐκ ἀγνοήσει αὐτήν.","st":"1.2"},{"sp":"N","t":"ἄφνω δὲ ταῦρος οὐ γίνεται οὐδὲ γενναῖος ἄνθρωπος, ἀλλὰ δεῖ χειμασκῆσαι, παρασκευάσασθαι καὶ μὴ εἰκῇ προσπηδᾶν ἐπὶ τὰ μηδὲν προσήκοντα.","st":"1.2"},{"sp":"N","t":"μόνον σκέψαι, πόσου πωλεῖς τὴν σεαυτοῦ προαίρεσιν. ἄνθρωπε, εἰ μηδὲν ἄλλο, μὴ ὀλίγου αὐτὴν πωλήσῃς. τὸ δὲ μέγα καὶ ἐξαίρετον ἄλλοις τάχα προσήκει, Σωκράτει καὶ τοῖς τοιούτοις.","st":"1.2"},{"sp":"N","t":"— διὰ τί οὖν, εἰ πρὸς τοῦτο πεφύκαμεν, οὐ πάντες ἢ πολλοὶ γίνονται τοιοῦτοι; — ἵπποι γὰρ ὠκεῖς ἅπαντες γίνονται, κύνες γὰρ ἰχνευτικοὶ πάντες;","st":"1.2"},{"sp":"N","t":"τί οὖν; ἐπειδὴ ἀφυής εἰμι, ἀποστῶ τῆς ἐπιμελείας τούτου ἕνεκα;","st":"1.2"},{"sp":"N","t":"μὴ γένοιτο. Ἐπίκτητος κρείσσων Σωκράτους οὐκ ἔσται: εἰ δὲ μή, οὐ χείρων, τοῦτό μοι ἱκανόν ἐστιν.","st":"1.2"},{"sp":"N","t":"οὐδὲ γὰρ Μίλων ἔσομαι καὶ ὅμως οὐκ ἀμελῶ τοῦ σώματος: οὐδὲ Κροῖσος καὶ ὅμως οὐκ ἀμελῶ τῆς κτήσεως: οὐδ᾽ ἁπλῶς ἄλλου τινὸς τῆς ἐπιμελείας διὰ τὴν ἀπόγνωσιν τῶν ἄκρων ἀφιστάμεθα. πῶς ἄν τις ἀπὸ τοῦ τὸν θεὸν πατέρα εἶναι τῶν ἀνθρώπων ἐπὶ τὰ ἑξῆς ἐπέλθοι. εἴ τις τῷ δόγματι τούτῳ συμπαθῆσαι κατ᾽ ἀξίαν δύναιτο, ὅτι γεγόναμεν ὑπὸ τοῦ θεοῦ πάντες προηγουμένως καὶ ὁ θεὸς πατήρ ἐστι τῶν τ᾽ ἀνθρώπων καὶ τῶν θεῶν, οἶμαι ὅτι οὐδὲν ἀγεννὲς οὐδὲ ταπεινὸν ἐνθυμηθήσεται περὶ ἑαυτοῦ.","st":"1.2"},{"sp":"N","t":"ἀλλ᾽ ἂν μὲν Καῖσαρ εἰσποιήσηταί σε, οὐδείς σου τὴν ὀφρῦν βαστάσει: ἂν δὲ γνῷς, ὅτι τοῦ Διὸς υἱὸς εἶ, οὐκ ἐπαρθήσῃ;","st":"1.3"},{"sp":"N","t":"νῦν δ᾽ οὐ ποιοῦμεν, ἀλλ᾽ ἐπειδὴ δύο ταῦτα ἐν τῇ γενέσει ἡμῶν ἐγκαταμέμικται, τὸ σῶμα μὲν κοινὸν πρὸς τὰ ζῷα, ὁ λόγος δὲ καὶ ἡ γνώμη κοινὸν πρὸς τοὺς θεούς, ἄλλοι μὲν ἐπὶ ταύτην ἀποκλίνουσιν τὴν συγγένειαν τὴν ἀτυχῆ καὶ νεκράν, ὀλίγοι δέ τινες ἐπὶ τὴν θείαν καὶ μακαρίαν.","st":"1.3"},{"sp":"N","t":"ἐπειδὴ τοίνυν ἀνάγκη πάνθ᾽ ὁντινοῦν οὕτως ἑκάστῳ χρῆσθαι ὡς ἂν περὶ αὐτοῦ ὑπολάβῃ, ἐκεῖνοι μὲν οἱ ὀλίγοι, ὅσοι πρὸς πίστιν οἴονται γεγονέναι καὶ πρὸς αἰδῶ καὶ πρὸς ἀσφάλειαν τῆς χρήσεως τῶν φαντασιῶν, οὐδὲν ταπεινὸν οὐδ᾽ ἀγεννὲς ἐνθυμοῦνται περὶ αὑτῶν, οἱ δὲ πολλοὶ τἀναντία.","st":"1.3"},{"sp":"N","t":"‘τί γὰρ εἰμί; ταλαίπωρον ἀνθρωπάριον’ καὶ","st":"1.3"},{"sp":"N","t":"‘τὰ δύστηνά μου σαρκίδια.’ τῷ μὲν ὄντι δύστηνα, ἀλλὰ ἔχεις τι καὶ κρεῖσσον τῶν σαρκιδίων. τί οὖν ἀφεὶς ἐκεῖνο τούτοις προστέτηκας;","st":"1.3"},{"sp":"N","t":"διὰ ταύτην τὴν συγγένειαν οἱ μὲν ἀποκλίναντες λύκοις ὅμοιοι γινόμεθα, ἄπιστοι καὶ ἐπίβουλοι καὶ βλαβεροί, οἱ δὲ λέουσιν, ἄγριοι καὶ θηριώδεις καὶ ἀνήμεροι, οἱ πλείους δ᾽ ἡμῶν ἀλώπεκες καὶ ὡς ἐν ζῴοις ἀτυχήματα.","st":"1.3"},{"sp":"N","t":"τί γάρ ἐστιν ἄλλο λοίδορος καὶ κακοήθης ἄνθρωπος ἢ ἀλώπηξ ἢ τί ἄλλο ἀτυχέστερον καὶ ταπεινότερον;","st":"1.3"},{"sp":"N","t":"ὁρᾶτε οὖν καὶ προσέχετε, μή τι τούτων ἀποβῆτε τῶν ἀτυχημάτων. περὶ προκοπῆς. ὁ προκόπτων μεμαθηκὼς παρὰ τῶν φιλοσόφων ὅτι ἡ μὲν ὄρεξις ἀγαθῶν ἐστιν, ἡ δ᾽ ἔκκλισις πρὸς κακά, μεμαθηκὼς δὲ καὶ ὅτι οὐκ ἄλλως τὸ εὔρουν καὶ ἀπαθὲς περιγίνεται τῷ ἀνθρώπῳ ἢ ἐν ὀρέξει μὲν μὴ ἀποτυγχάνοντι, ἐν ἐκκλίσει δὲ μὴ περιπίπτοντι, τὴν μὲν ὄρεξιν ἦρκεν ἐξ αὑτοῦ εἰσάπαν καὶ ὑπερτέθειται, τῇ ἐκκλίσει δὲ πρὸς μόνα χρῆται τὰ προαιρετικά.","st":"1.3"},{"sp":"N","t":"τῶν γὰρ ἀπροαιρέτων ἄν τι ἐκκλίνῃ, οἶδεν ὅτι περιπεσεῖταί ποτέ τινι παρὰ τὴν ἔκκλισιν τὴν αὑτοῦ καὶ δυστυχήσει.","st":"1.4"},{"sp":"N","t":"εἰ δ᾽ ἡ ἀρετὴ ταύτην ἔχει τὴν ἐπαγγελίαν εὐδαιμονίαν ποιῆσαι καὶ ἀπάθειαν καὶ εὔροιαν, πάντως καὶ ἡ προκοπὴ ἡ πρὸς αὐτὴν πρὸς ἕκαστον τούτων ἐστὶ προκοπή.","st":"1.4"},{"sp":"N","t":"ἀεὶ γὰρ πρὸς ὃ ἂν ἡ τελειότης τινὸς καθάπαξ ἄγῃ, πρὸς αὐτὸ ἡ προκοπὴ συνεγγισμός ἐστιν. πῶς οὖν τὴν μὲν ἀρετὴν τοιοῦτόν τι ὁμολογοῦμεν,","st":"1.4"},{"sp":"N","t":"τὴν προκοπὴν δ᾽ ἐν ἄλλοις ζητοῦμεν καὶ ἐπιδείκνυμεν; τί ἔργον ἀρετῆς;","st":"1.4"},{"sp":"N","t":"εὔροια. τίς οὖν προκόπτει; ὁ πολλὰς Χρυσίππου συντάξεις ἀνεγνωκώς;","st":"1.4"},{"sp":"N","t":"μὴ γὰρ ἡ ἀρετὴ τοῦτ᾽ ἔστι Χρύσιππον νενοηκέναι; εἰ γὰρ τοῦτ᾽ ἔστιν, ὁμολογουμένως ἡ προκοπὴ οὐδὲν ἄλλο ἐστὶν ἢ τὸ πολλὰ τῶν Χρυσίππου νοεῖν.","st":"1.4"},{"sp":"N","t":"νῦν δ᾽ ἄλλο μέν τι τὴν ἀρετὴν ἐπιφέρειν ὁμολογοῦμεν, ἄλλον δὲ τὸν συνεγγισμόν, τὴν προκοπὴν ἀποφαίνομεν.","st":"1.4"},{"sp":"N","t":"‘οὗτος,’ φησίν, ‘ἤδη καὶ δι᾽ αὑτοῦ δύναται Χρύσιππον ἀναγιγνώσκειν.’ εὖ, νὴ τοὺς θεούς, προκόπτεις, ἄνθρωπε: ποίαν προκοπήν.","st":"1.4"},{"sp":"N","t":"‘τί ἐμπαίζεις αὐτῷ;’ τί δ᾽ ἀπάγεις αὐτὸν τῆς συναισθήσεως τῶν αὑτοῦ κακῶν; οὐ θέλεις δεῖξαι αὐτῷ τὸ ἔργον τῆς ἀρετῆς, ἵνα μάθῃ ποῦ τὴν προκοπὴν ζητῇ;","st":"1.4"},{"sp":"N","t":"ἐκεῖ ζήτησον αὐτήν, ταλαίπωρε, ὅπου σου τὸ ἔργον. ποῦ δέ σου τὸ ἔργον; ἐν ὀρέξει καὶ ἐκκλίσει, ἵν᾽ ἀναπότευκτος ᾖς καὶ ἀπερίπτωτος, ἐν ὁρμαῖς καὶ ἀφορμαῖς, ἵν᾽ ἀναμάρτητος, ἐν προσθέσει καὶ ἐποχῇ, ἵν᾽ ἀνεξαπάτητος.","st":"1.4"},{"sp":"N","t":"πρῶτοι δ᾽ εἰσὶν οἱ πρῶτοι τόποι καὶ ἀναγκαιότατοι. ἂν δὲ τρέμων καὶ πενθῶν ζητῇς ἀπερίπτωτος εἶναι, ἄρα πῶς προκόπτεις;","st":"1.4"},{"sp":"N","t":"σὺ οὖν ἐνταῦθά μοι δεῖξόν σου τὴν προκοπήν. καθάπερ εἰ ἀθλητῇ διελεγόμην ‘δεῖξόν μοι τοὺς ὤμους,’ εἶτα ἔλεγεν ἐκεῖνος ‘ἴδε μου τοὺς ἁλτῆρας.’ ὄψει σὺ καὶ οἱ ἁλτῆρες, ἐγὼ τὸ ἀποτέλεσμα τῶν ἁλτήρων ἰδεῖν βούλομαι.","st":"1.4"},{"sp":"N","t":"‘λάβε τὴν περὶ ὁρμῆς σύνταξιν καὶ γνῶθι πῶς αὐτὴν ἀνέγνωκα.’ ἀνδράποδον, οὐ τοῦτο ζητῶ, ἀλλὰ πῶς ὁρμᾷς καὶ ἀφορμᾷς, πῶς ὀρέγῃ καὶ ἐκκλίνεις, πῶς ἐπιβάλλῃ καὶ προστίθεσαι καὶ παρασκευάζῃ, πότερα συμφώνως τῇ φύσει ἢ ἀσυμφώνως.","st":"1.4"},{"sp":"N","t":"εἰ γὰρ συμφώνως, τοῦτό μοι δείκνυε καὶ ἐρῶ σοι ὅτι προκόπτεις: εἰ δ᾽ ἀσυμφώνως, ἄπελθε καὶ μὴ μόνον ἐξηγοῦ τὰ βιβλία, ἀλλὰ καὶ γράφε αὐτὸς τοιαῦτα.","st":"1.4"},{"sp":"N","t":"καὶ τί σοι ὄφελος; οὐκ οἶδας ὅτι ὅλον τὸ βιβλίον πέντε δηναρίων ἐστίν; ὁ οὖν ἐξηγούμενος αὐτὸ δοκεῖ ὅτι πλείονος ἄξιός ἐστιν ἢ πέντε δηναρίων;","st":"1.4"},{"sp":"N","t":"μηδέποτε οὖν ἀλλαχοῦ τὸ ἔργον ζητεῖτε, ἀλλαχοῦ τὴν προκοπήν.","st":"1.4"},{"sp":"N","t":"ποῦ οὖν προκοπή; εἴ τις ὑμῶν ἀποστὰς τῶν ἐκτὸς ἐπὶ τὴν προαίρεσιν ἐπέστραπται τὴν αὑτοῦ, ταύτην ἐξεργάζεσθαι καὶ ἐκπονεῖν, ὥστε σύμφωνον ἀποτελέσαι τῇ φύσει, ὑψηλὴν ἐλευθέραν ἀκώλυτον ἀνεμπόδιστον πιστὴν αἰδήμονα:","st":"1.4"},{"sp":"N","t":"μεμάθηκέν τε, ὅτι ὁ τὰ μὴ ἐφ᾽ αὑτῷ ποθῶν ἢ φεύγων οὔτε πιστὸς εἶναι δύναται οὔτ᾽ ἐλεύθερος, ἀλλ᾽ ἀνάγκη μεταπίπτειν καὶ μεταρριπίζεσθαι ἅμα ἐκείνοις καὶ αὐτόν, ἀνάγκη δὲ καὶ ὑποτεταχέναι ἄλλοις ἑαυτόν, τοῖς ἐκεῖνα περιποιεῖν ἢ κωλύειν δυναμένοις:","st":"1.4"},{"sp":"N","t":"καὶ λοιπὸν ἕωθεν ἀνιστάμενος ταῦτα τηρεῖ καὶ φυλάσσει, λούεται ὡς πιστός, ὡς αἰδήμων ἐσθίει, ὡσαύτως ἐπὶ τῆς ἀεὶ παραπιπτούσης ὕλης τὰ προηγούμενα ἐκπονῶν, ὡς ὁ δρομεὺς δρομικῶς καὶ ὁ φώνασκος φωνασκικῶς:","st":"1.4"},{"sp":"N","t":"οὗτός ἐστιν ὁ προκόπτων ταῖς ἀληθείαις καὶ ὁ μὴ εἰκῇ ἀποδεδημηκὼς οὗτός ἐστιν.","st":"1.4"},{"sp":"N","t":"εἰ δ᾽ ἐπὶ τὴν ἐν τοῖς βιβλίοις ἕξιν τέταται καὶ ταύτην ἐκπονεῖ καὶ ἐπὶ τοῦτο ἐκδεδήμηκε, λέγω αὐτῷ αὐτόθεν πορεύεσθαι εἰς οἶκον καὶ μὴ ἀμελεῖν τῶν ἐκεῖ:","st":"1.4"},{"sp":"N","t":"τοῦτο γὰρ ἐφ᾽ ὃ ἀποδεδήμηκεν οὐδέν ἐστιν: ἀλλ᾽ ἐκεῖνο, μελετᾶν ἐξελεῖν τοῦ αὑτοῦ βίου πένθη καὶ οἰμωγὰς καὶ τὸ ‘οἴμοι’ καὶ τὸ ‘τάλας ἐγὼ’ καὶ δυστυχίαν καὶ ἀτυχίαν καὶ μαθεῖν,","st":"1.4"},{"sp":"N","t":"τί ἐστι θάνατος, τί φυγή, τί δεσμωτήριον, τί νοσκώνειον, ἵνα δύνηται λέγειν ἐν τῇ φυλακῇ ‘ὦ φίλε Κρίτων, εἰ ταύτῃ τοῖς θεοῖς φίλον, ταύτῃ γινέσθω’ καὶ μὴ ἐκεῖνα ‘τάλας ἐγώ, γέρων ἄνθρωπος, ἐπὶ ταῦτά μου τὰς πολιὰς ἐτήρησα.’","st":"1.4"},{"sp":"N","t":"τίς λέγει ταῦτα; δοκεῖτε ὅτι ὑμῖν ἄδοξόν τινα ἐρῶ καὶ ταπεινόν; Πρίαμος αὐτὰ οὐ λέγει; Οἰδίπους οὐ λέγει; ἀλλ᾽ ὁπόσοι βασιλεῖς λέγουσιν;","st":"1.4"},{"sp":"N","t":"τί γάρ εἰσιν ἄλλο τραγῳδίαι ἢ ἀνθρώπων πάθη τεθαυμακότων τὰ ἐκτὸς διὰ μέτρου τοιοῦδ᾽ ἐπιδεικνύμενα;","st":"1.4"},{"sp":"N","t":"εἰ γὰρ ἐξαπατηθέντα τινὰ ἔδει μαθεῖν, ὅτι τῶν ἐκτὸς καὶ ἀπροαιρέτων οὐδέν ἐστι πρὸς ἡμᾶς, ἐγὼ μὲν ἤθελον τὴν ἀπάτην ταύτην, ἐξ ἧς ἤμελλον εὐρόως καὶ ἀταράχως βιώσεσθαι, ὑμεῖς δ᾽ ὄψεσθ᾽ αὐτοὶ τί θέλετε.","st":"1.4"},{"sp":"N","t":"τί οὖν ἡμῖν παρέχει Χρύσιππος; ἵνα γνῷς, φησίν, ὅτι οὐ ψευδῆ ταῦτά ἐστιν, ἐξ ὧν ἡ εὔροιά ἐστι καὶ ἀπάθεια ἀπαντᾷ,","st":"1.4"},{"sp":"N","t":"λάβε μου τὰ βιβλία καὶ γνώσῃ ὡς ... τε καὶ σύμφωνά ἐστι τῇ φύσει τὰ ἀπαθῆ με ποιοῦντα. ὦ μεγάλης εὐτυχίας, ὦ μεγάλου εὐεργέτου τοῦ δεικνύοντος τὴν ὁδόν.","st":"1.4"},{"sp":"N","t":"εἶτα Τριπτολέμῳ μὲν ἱερὰ καὶ βωμοὺς πάντες ἄνθρωποι ἀνεστάκασιν,","st":"1.4"},{"sp":"N","t":"ὅτι τὰς ἡμέρους τροφὰς ἡμῖν ἔδωκεν, τῷ δὲ τὴν ἀλήθειαν εὑρόντι καὶ φωτίσαντι καὶ εἰς πάντας ἀνθρώπους ἐξενεγκόντι, οὐ τὴν περὶ τὸ ζῆν, ἀλλὰ τὴν πρὸς τὸ εὖ ζῆν, τίς ὑμῶν ἐπὶ τούτῳ βωμὸν ἱδρύσατο ἢ ναὸν ἢ ἄγαλμα ἀνέθηκεν ἢ τὸν θεὸν ἐπὶ τούτῳ προσκυνεῖ;","st":"1.4"},{"sp":"N","t":"ἀλλ᾽ ὅτι μὲν ἄμπελον ἔδωκαν ἢ πυρούς, ἐπιθύομεν τούτου ἕνεκα, ὅτι δὲ τοιοῦτον ἐξήνεγκαν καρπὸν ἐν ἀνθρωπίνῃ διανοίᾳ, δι᾽ οὗ τὴν ἀλήθειαν τὴν περὶ εὐδαιμονίας δείξειν ἡμῖν ἤμελλον, τούτου δ᾽ ἕνεκα οὐκ εὐχαριστήσωμεν τῷ θεῷ; πρὸς τοὺς Ἀκαδημαικούς. ἄν τις, φησίν, ἐνίστηται πρὸς τὰ ἄγαν ἐκφανῆ, πρὸς τοῦτον οὐ ῥᾴδιόν ἐστιν εὑρεῖν λόγον, δι᾽ οὗ μεταπείσει τις αὐτόν.","st":"1.4"},{"sp":"N","t":"τοῦτο δ᾽ οὔτε παρὰ τὴν ἐκείνου γίνεται δύναμιν οὔτε παρὰ τὴν τοῦ διδάσκοντος ἀσθένειαν, ἀλλ᾽ ὅταν ἀπαχθεὶς ἀπολιθωθῇ, πῶς ἔτι χρήσηταί τις αὐτῷ διὰ λόγου;","st":"1.5"},{"sp":"N","t":"Ἀπολιθώσεις δ᾽ εἰσὶ διτταί: ἡ μὲν τοῦ νοητικοῦ ἀπολίθωσις, ἡ δὲ τοῦ ἐντρεπτικοῦ, ὅταν τις παρατεταγμένος ᾖ μὴ ἐπινεύειν τοῖς ἐναργέσι μηδ᾽ ἀπὸ τῶν μαχομένων ἀφίστασθαι.","st":"1.5"},{"sp":"N","t":"οἱ δὲ πολλοὶ τὴν μὲν σωματικὴν ἀπονέκρωσιν φοβούμεθα καὶ πάντ᾽ ἂν μηχανησαίμεθα ὑπὲρ τοῦ μὴ περιπεσεῖν τοιούτῳ τινί, τῆς ψυχῆς δ᾽ ἀπονεκρουμένης οὐδὲν ἡμῖν μέλει.","st":"1.5"},{"sp":"N","t":"καὶ νὴ Δία ἐπὶ αὐτῆς τῆς ψυχῆς ἂν μὲν ᾖ οὕτως διακείμενος, ὥστε μηδενὶ παρακολουθεῖν μηδὲ συνιέναι μηδέν, καὶ τοῦτον κακῶς ἔχειν οἰόμεθα: ἂν δέ τινος τὸ ἐντρεπτικὸν καὶ αἰδῆμον ἀπονεκρωθῇ, τοῦτο ἔτι καὶ δύναμιν καλοῦμεν. Καταλαμβάνεις ὅτι ἐγρήγορας;","st":"1.5"},{"sp":"N","t":"‘οὔ,’ φησίν: ‘οὐδὲ γάρ, ὅταν ἐν τοῖς ὕπνοις φαντάζωμαι, ὅτι ἐγρήγορα.’ οὐδὲν οὖν διαφέρει αὕτη ἡ φαντασία ἐκείνης; ‘οὐδέν.’ ἔτι τούτῳ διαλέγομαι;","st":"1.5"},{"sp":"N","t":"καὶ ποῖον αὐτῷ πῦρ ἢ ποῖον σίδηρον προσαγάγω, ἵν᾽ αἴσθηται ὅτι νενέκρωται; αἰσθανόμενος οὐ προσποιεῖται: ἔτι χείρων ἐστὶ τοῦ νεκροῦ. μάχην οὗτος οὐ συνορᾷ: κακῶς ἔχει.","st":"1.5"},{"sp":"N","t":"συνορῶν οὗτος οὐ κινεῖται οὐδὲ προκόπτει: ἔτι ἀθλιώτερον ἔχει.","st":"1.5"},{"sp":"N","t":"ἐκτέτμηται τὸ αἰδῆμον αὐτοῦ καὶ ἐντρεπτικὸν καὶ τὸ λογικὸν οὐκ ἀποτέτμηται, ἀλλ᾽ ἀποτεθηρίωται.","st":"1.5"},{"sp":"N","t":"ταύτην ἐγὼ δύναμιν εἴπω; μὴ γένοιτο, εἰ μὴ καὶ τὴν τῶν κιναίδων, καθ᾽ ἣν πᾶν τὸ ἐπελθὸν ἐν μέσῳ καὶ ποιοῦσι καὶ λέγουσι. περὶ προνοίας. ἀφ᾽ ἑκάστου τῶν ἐν τῷ κόσμῳ γινομένων ῥᾴδιόν ἐστιν ἐγκωμιάσαι τὴν πρόνοιαν, ἂν δύο ἔχῃ τις ταῦτα ἐν ἑαυτῷ, δύναμίν τε συνορατικὴν τῶν γεγονότων ἑκάστῳ καὶ τὸ εὐχάριστον.","st":"1.5"},{"sp":"N","t":"εἰ δὲ μή, ὁ μὲν οὐκ ὄψεται τὴν εὐχρηστίαν τῶν γεγονότων, ὁ δ᾽ οὐκ εὐχαριστήσει ἐπ᾽ αὐτοῖς οὐδ᾽ ἂν","st":"1.6"},{"sp":"N","t":"ἴδῃ. χρώματα ὁ θεὸς εἰ πεποιήκει, δύναμιν δὲ θεατικὴν αὐτῶν μὴ πεποιήκει, τί ἂν ἦν ὄφελος;","st":"1.6"},{"sp":"N","t":"— οὐδ᾽ ὁτιοῦν. — ἀλλ᾽ ἀνάπαλιν εἰ τὴν μὲν δύναμιν πεποιήκει, τὰ ὄντα δὲ μὴ τοιαῦτα οἷα ὑποπίπτειν τῇ δυνάμει τῇ ὁρατικῇ, καὶ οὕτως τί ὄφελος;","st":"1.6"},{"sp":"N","t":"— οὐδ᾽ ὁτιοῦν.","st":"1.6"},{"sp":"N","t":"— τί δ᾽, εἰ καὶ ἀμφότερα ταῦτα πεποιήκει, φῶς δὲ μὴ πεποιήκει; — οὐδ᾽ οὕτως τι ὄφελος. — τίς οὖν ὁ ἁρμόσας τοῦτο πρὸς ἐκεῖνο κἀκεῖνο πρὸς τοῦτο; τίς δ᾽ ὁ ἁρμόσας τὴν μάχαιραν πρὸς τὸ κολεὸν καὶ τὸ κολεὸν πρὸς τὴν μάχαιραν;","st":"1.6"},{"sp":"N","t":"οὐδείς; καὶ μὴν ἐξ αὐτῆς τῆς κατασκευῆς τῶν ἐπιτετελεσμένων ἀποφαίνεσθαι εἰώθαμεν, ὅτι τεχνίτου τινὸς πάντως τὸ ἔργον, οὐχὶ δ᾽ εἰκῇ κατεσκευασμένον.","st":"1.6"},{"sp":"N","t":"ἆρ᾽ οὖν τούτων μὲν ἕκαστον ἐμφαίνει τὸν τεχνίτην, τὰ δ᾽ ὁρατὰ καὶ ὅρασεις καὶ φῶς οὐκ ἐμφαίνει;","st":"1.6"},{"sp":"N","t":"τὸ δ᾽ ἄρρεν καὶ τὸ θῆλυ καὶ ἡ προθυμία ἡ πρὸς τὴν συνουσίαν ἑκατέρου καὶ δύναμις ἡ χρηστικὴ τοῖς μορίοις τοῖς κατεσκευασμένοις οὐδὲ ταῦτα ἐμφαίνει τὸν τεχνίτην;","st":"1.6"},{"sp":"N","t":"ἀλλὰ ταῦτα μέν: ἡ δὲ τοιαύτη τῆς διανοίας κατασκευή, καθ᾽ ἣν οὐχ ἁπλῶς ὑποπίπτοντες τοῖς αἰσθητοῖς τυπούμεθα ὑπ᾽ αὐτῶν, ἀλλὰ καὶ ἐκλαμβάνομέν τι καὶ ἀφαιροῦμεν καὶ προστίθεμεν καὶ συντίθεμεν τάδε τινὰ δι᾽ αὐτῶν καὶ νὴ Δία μεταβαίνομεν ἀπ᾽ ἄλλων ἐπ᾽ ἄλλα τινὰ οὕτω πως παρακείμενα, οὐδὲ ταῦτα ἱκανὰ κινῆσαί τινας καὶ διατρέψαι πρὸς τὸ ἀπολιπεῖν τὸν τεχνίτην;","st":"1.6"},{"sp":"N","t":"ἢ ἐξηγησάσθωσαν ἡμῖν τί τὸ ποιοῦν ἐστιν ἕκαστον τούτων ἢ πῶς οἷόν τε τὰ οὕτω θαυμαστὰ καὶ τεχνικὰ εἰκῇ καὶ ἀπὸ ταὐτομάτου γίνεσθαι.","st":"1.6"},{"sp":"N","t":"τί οὖν; ἐφ᾽ ἡμῶν μόνων γίνεται ταῦτα; πολλὰ μὲν ἐπὶ μόνων, ὧν ἐξαιρέτως χρείαν εἶχεν τὸ λογικὸν ζῷον, πολλὰ δὲ κοινὰ εὑρήσεις ἡμῖν καὶ πρὸς τὰ ἄλογα.","st":"1.6"},{"sp":"N","t":"ἆρ᾽ οὖν καὶ παρακολουθεῖ τοῖς γινομένοις ἐκεῖνα; οὐδαμῶς. ἄλλο γάρ ἐστι χρῆσις καὶ ἄλλο παρακολούθησις. ἐκείνων χρείαν εἶχεν ὁ θεὸς χρωμένων ταῖς φαντασίαις, ἡμῶν δὲ παρακολουθούντων τῇ χρήσει.","st":"1.6"},{"sp":"N","t":"διὰ τοῦτο ἐκείνοις μὲν ἀρκεῖ τὸ ἐσθίειν καὶ πίνειν καὶ τὸ ἀναπαύεσθαι καὶ ὀχεύειν καὶ τἆλλ᾽ ὅσα ἐπιτελεῖ τῶν αὑτῶν ἕκαστον, ἡμῖν δ᾽, οἷς καὶ τὴν παρακολουθητικὴν δύναμιν ἔδωκεν,","st":"1.6"},{"sp":"N","t":"οὐκέτι ταῦτ᾽ ἀπαρκεῖ, ἀλλ᾽ ἂν μὴ κατὰ τρόπον καὶ τεταγμένως καὶ ἀκολούθως τῇ ἑκάστου φύσει καὶ κατασκευῇ πράττωμεν, οὐκέτι τοῦ τέλους τευξόμεθα τοῦ ἑαυτῶν.","st":"1.6"},{"sp":"N","t":"ὧν γὰρ αἱ κατασκευαὶ διάφοροι, τούτων καὶ τὰ ἔργα καὶ τὰ τέλη.","st":"1.6"},{"sp":"N","t":"οὗ τοίνυν ἡ κατασκευὴ μόνον χρηστική, τούτῳ χρῆσθαι ὁπωσοῦν ἀπαρκεῖ: οὗ δὲ καὶ παρακολουθητικὴ τῇ χρήσει, τούτῳ τὸ κατὰ τρόπον ἂν μὴ προσῇ οὐδέποτε τεύξεται τοῦ τέλους.","st":"1.6"},{"sp":"N","t":"τί οὖν; ἐκείνων ἕκαστον κατασκευάζει τὸ μὲν ὥστ᾽ ἐσθίεσθαι, τὸ δ᾽ ὥστε ὑπηρετεῖν εἰς γεωργίαν, τὸ δ᾽ ὥστε τυρὸν φέρειν, τὸ δ᾽ ἄλλο ἐπ᾽ ἄλλῃ χρείᾳ παραπλησίῳ, πρὸς ἃ τίς χρεία τοῦ παρακολουθεῖν ταῖς φαντασίαις καὶ ταύτας διακρίνειν δύνασθαι;","st":"1.6"},{"sp":"N","t":"τὸν δ᾽ ἄνθρωπον θεατὴν εἰσήγαγεν αὐτοῦ τε καὶ τῶν ἔργων τῶν αὐτοῦ, καὶ οὐ μόνον θεατήν, ἀλλὰ καὶ ἐξηγητὴν αὐτῶν.","st":"1.6"},{"sp":"N","t":"διὰ τοῦτο αἰσχρόν ἐστι τῷ ἀνθρώπῳ ἄρχεσθαι καὶ καταλήγειν ὅπου καὶ τὰ ἄλογα, ἀλλὰ μᾶλλον ἔνθεν μὲν ἄρχεσθαι, καταλήγειν δὲ ἐφ᾽ ὃ κατέληξεν ἐφ᾽ ἡμῶν καὶ ἡ φύσις.","st":"1.6"},{"sp":"N","t":"κατέληξεν δ᾽ ἐπὶ θεωρίαν καὶ παρακολούθησιν καὶ σύμφωνον διεξαγωγὴν τῇ φύσει. ὁρᾶτε οὖν, μὴ ἀθέατοι τούτων ἀποθάνητε.","st":"1.6"},{"sp":"N","t":"ἀλλ᾽ εἰς Ὀλυμπίαν μὲν ἀποδημεῖτε, ἵν᾽ εἴδητε τὸ ἔργον τοῦ Φειδίου, καὶ ἀτύχημα ἕκαστος ὑμῶν οἴεται τὸ ἀνιστόρητος τούτων ἀποθανεῖν:","st":"1.6"},{"sp":"N","t":"ὅπου δ᾽ οὐδ᾽ ἀποδημῆσαι χρεία ἐστίν, ἀλλ᾽ ἐστὲ ἤδη καὶ πάρεστε τοῖς ἔργοις, ταῦτα δὲ θεάσασθαι καὶ κατανοῆσαι οὐκ ἐπιθυμήσετε;","st":"1.6"},{"sp":"N","t":"οὐκ αἰσθήσεσθε τοίνυν, οὔτε τίνες ἐστὲ οὔτ᾽ ἐπὶ τί γεγόνατε οὔτε ἐπὶ τί τοῦτό ἐστιν, ἐφ᾽ οὗ τὴν θέαν παρείληφθε;","st":"1.6"},{"sp":"N","t":"— ἀλλὰ γίνεταί τινα ἀηδῆ καὶ χαλεπὰ ἐν τῷ βίῳ. — ἐν Ὀλυμπίᾳ δ᾽ οὐ γίνεται; οὐ καυματίζεσθε; οὐ στενοχωρεῖσθε; οὐ κακῶς λούεσθε; οὐ καταβρέχεσθε, ὅταν βρέχῃ; θορύβου δὲ καὶ βοῆς καὶ τῶν ἄλλων χαλεπῶν οὐκ ἀπολαύετε;","st":"1.6"},{"sp":"N","t":"ἀλλ᾽ οἶμαι ὅτι ταῦτα πάντα ἀντιτιθέντες πρὸς τὸ ἀξιόλογον τῆς θέας φέρετε καὶ ἀνέχεσθε. ἄγε δυνάμεις δ᾽ οὐκ εἰλήφατε,","st":"1.6"},{"sp":"N","t":"καθ᾽ ἃς οἴσετε πᾶν τὸ συμβαῖνον; μεγαλοψυχίαν οὐκ εἰλήφατε; ἀνδρείαν οὐκ εἰλήφατε;","st":"1.6"},{"sp":"N","t":"καρτερίαν οὐκ εἰλήφατε; καὶ τί ἔτι μοι μέλει μεγαλοψύχῳ ὄντι τῶν ἀποβῆναι δυναμένων; τί μ᾽ ἐκστήσει ἢ ταράξει ἢ τί ὀδυνηρὸν φανεῖται; οὐ χρήσομαι τῇ δυνάμει πρὸς ἃ εἴληφα αὐτήν, ἀλλ᾽ ἐπὶ τοῖς ἀποβαίνουσιν πενθήσω καὶ στενάξω;","st":"1.6"},{"sp":"N","t":"‘ναί: ἀλλ᾽ αἱ μύξαι μου ῥέουσιν.’ τίνος οὖν ἕνεκα χεῖρας ἔχεις, ἀνδράποδον; οὐχ ἵνα καὶ ἀπομύσσῃς σεαυτόν;","st":"1.6"},{"sp":"N","t":"— τοῦτο οὖν εὔλογον μύξας γίνεσθαι ἐν τῷ κόσμῳ;","st":"1.6"},{"sp":"N","t":"— καὶ πόσῳ κρεῖττον ἀπομύξασθαί σε ἢ ἐγκαλεῖν; ἢ τί οἴει ὅτι ὁ Ἡρακλῆς ἂν ἀπέβη, εἰ μὴ λέων τοιοῦτος ἐγένετο καὶ ὕδρα καὶ ἔλαφρος καὶ σῦς καὶ ἄδικοί τινες ἄνθρωποι καὶ θηριώδεις, οὓς ἐκεῖνος ἐξήλαυνεν καὶ ἐκάθαιρεν;","st":"1.6"},{"sp":"N","t":"καὶ τί ἂν ἐποίει μηδενὸς τοιούτου γεγονότος; ἢ δῆλον ὅτι ἐντετυλιγμένος ἂν ἐκάθευδεν; οὐκοῦν πρῶτον μὲν οὐκ ἂν ἐγένετο Ἡρακλῆς ἐν τρυφῇ τοιαύτῃ καὶ ἡσυχίᾳ νυστάζων ὅλον τὸν βίον: εἰ δ᾽ ἄρα καὶ ἐγένετο, τί ὄφελος αὐτοῦ;","st":"1.6"},{"sp":"N","t":"τίς δὲ χρῆσις τῶν βραχιόνων τῶν ἐκείνου καὶ τῆς ἄλλης ἀλκῆς καὶ καρτερίας καὶ γενναιότητος, εἰ μὴ τοιαῦταί τινες αὐτὸν περιστάσεις καὶ ὗλαι διέσεισαν καὶ ἐγύμνασαν;","st":"1.6"},{"sp":"N","t":"τί οὖν; αὑτῷ ταύτας ἔδει κατασκευάζειν καὶ ζητεῖν ποθεν λέοντα εἰσαγαγεῖν εἰς τὴν χώραν τὴν αὑτοῦ καὶ σῦν καὶ ὕδραν;","st":"1.6"},{"sp":"N","t":"μωρία τοῦτο καὶ μανία. γενόμενα δὲ καὶ εὑρεθέντα εὔχρηστα ἦν πρὸς τὸ δεῖξαι καὶ γυμνάσαι τὸν Ἡρακλέα.","st":"1.6"},{"sp":"N","t":"ἄγε οὖν καὶ σὺ τούτων αἰσθόμενος ἀπόβλεψον εἰς τὰς δυνάμεις ἃς ἔχεις καὶ ἀπιδὼν εἰπὲ ‘φέρε νῦν, ὦ Ζεῦ, ἣν θέλεις περίστασιν: ἔχω γὰρ παρασκευὴν ἐκ σοῦ μοι δεδομένην καὶ ἀφορμὰς πρὸς τὸ κοσμῆσαι διὰ τῶν ἀποβαινόντων ἐμαυτόν’","st":"1.6"},{"sp":"N","t":"οὔ: ἀλλὰ κάθησθε τὰ μὲν μὴ συμβῇ τρέμοντες, τῶν δὲ συμβαινόντων ὀδυρόμενοι καὶ πενθοῦντες καὶ στένοντες: εἶτα τοῖς θεοῖς ἐγκαλεῖτε.","st":"1.6"},{"sp":"N","t":"τί γάρ ἐστιν ἄλλο ἀκόλουθον τῇ τοιαύτῃ ἀγεννείᾳ ἢ καὶ ἀσέβεια;","st":"1.6"},{"sp":"N","t":"καίτοι ὅ γε θεὸς οὐ μόνον ἔδωκεν ἡμῖν τὰς δυνάμεις ταύτας, καθ᾽ ἃς οἴσομεν πᾶν τὸ ἀποβαῖνον μὴ ταπεινούμενοι μηδὲ συγκλώμενοι ὑπ᾽ αὐτοῦ, ἀλλ᾽ ὃ ἦν ἀγαθοῦ βασιλέως καὶ ταῖς ἀληθείαις πατρός, ἀκώλυτον τοῦτο ἔδωκεν, ἀνανάγκαστον, ἀπαραπόδιστον, ὅλον αὐτὸ ἐφ᾽ ἡμῖν ἐποίησεν οὐδ᾽ αὑτῷ τινα πρὸς τοῦτο ἰσχὺν ἀπολιπών, ὥστε κωλῦσαι ἢ ἐμποδίσαι.","st":"1.6"},{"sp":"N","t":"ταῦτα ἔχοντες ἐλεύθερα καὶ ὑμέτερα μὴ χρῆσθε αὐτοῖς μηδ᾽ αἰσθάνεσθε τίνα εἰλήφατε καὶ παρὰ τίνος,","st":"1.6"},{"sp":"N","t":"ἀλλὰ κάθησθε πενθοῦντες καὶ στένοντες οἱ μὲν πρὸς αὐτὸν τὸν δόντα ἀποτετυφλωμένοι μηδ᾽ ἐπιγινώσκοντες τὸν εὐεργέτην, οἱ δ᾽ ὑπ᾽ ἀγεννείας εἰς μέμψεις καὶ τὰ ἐγκλήματα τῷ θεῷ ἐκτρεπόμενοι.","st":"1.6"},{"sp":"N","t":"καίτοι πρὸς μεγαλοψυχίαν μὲν καὶ ἀνδρείαν ἐγὼ σοὶ δείξω ὅτι ἀφορμὰς καὶ παρασκευὴν ἔχεις, πρὸς δὲ τὸ μέμφεσθαι καὶ ἐγκαλεῖν ποίας ἀφορμὰς ἔχεις σὺ δ᾽ ἐμοὶ δείκνυε. περὶ τῆς χρείας τῶν μεταπιπτόντων καὶ ὑποθετικῶν καὶ τῶν ὁμοίων. ἡ περὶ τοὺς μεταπίπτοντας καὶ ὑποθετικούς, ἔτι δὲ ἠρωτῆσθαι περαίνοντας καὶ πάντας ἁπλῶς τοὺς τοιούτους λόγους πραγματεία λανθάνει τοὺς πολλοὺς περὶ καθήκοντος οὖσα.","st":"1.6"},{"sp":"N","t":"ζητοῦμεν γὰρ ἐπὶ πάσης ὕλης πῶς ἂν εὕροοι ὁ καλὸς καὶ ἀγαθὸς τὴν διέξοδον καὶ ἀναστροφὴν τὴν ἐν αὐτῇ καθήκουσαν.","st":"1.7"},{"sp":"N","t":"οὐκοῦν ἢ τοῦτο λεγέτωσαν, ὅτι οὐ συγκαθήσει εἰς ἐρώτησιν καὶ ἀπόκρισιν ὁ σπουδαῖος ἢ ὅτι συγκαθεὶς οὐκ ἐπιμελήσεται τοῦ μὴ εἰκῇ μηδ᾽ ὡς ἔτυχεν ἐν ἐρωτήσει καὶ ἀποκρίσει ἀναστρέφεσθαι,","st":"1.7"},{"sp":"N","t":"μἢ τούτων μηδέτερον προσδεχομένοις ἀναγκαῖον ὁμολογεῖν, ὅτι ἐπίσκεψίν τινα ποιητέον τῶν τόπων τούτων, περὶ οὓς μάλιστα στρέφεται ἐρώτησις καὶ ἀπόκρισις.","st":"1.7"},{"sp":"N","t":"τί γὰρ ἐπαγγέλλεται ἐν λόγῳ; τἀληθῆ τιθέναι, τὰ ψευδῆ αἴρειν, πρὸς τὰ ἄδηλα ἐπέχειν.","st":"1.7"},{"sp":"N","t":"ἆρ᾽ οὖν ἀρκεῖ τοῦτο μόνον μαθεῖν; — ἀρκεῖ, φησίν. — οὐκοῦν καὶ τῷ βουλομένῳ ἐν χρήσει νομίσματος μὴ διαπίπτειν ἀρκεῖ τοῦτο ἀκοῦσαι, διὰ τί τὰς μὲν δοκίμους δραχμὰς παραδέχῃ, τὰς δ᾽ ἀδοκίμους ἀποδοκιμάζεις;","st":"1.7"},{"sp":"N","t":"— οὐκ ἀρκεῖ. — τί οὖν δεῖ τούτῳ προσλαβεῖν; τί γὰρ ἄλλο ἢ δύναμιν δοκιμαστικήν τε καὶ διακριτικὴν τῶν δοκίμων τε καὶ ἀδοκίμων δραχμῶν; οὐκοῦν καὶ ἐπὶ λόγου οὐκ ἀρκεῖ τὸ λεχθέν,","st":"1.7"},{"sp":"N","t":"ἀλλ᾽ ἀνάγκη δοκιμαστικὸν γενέσθαι καὶ διακριτικὸν τοῦ ἀληθοῦς καὶ τοῦ ψεύδους καὶ τοῦ ἀδήλου;","st":"1.7"},{"sp":"N","t":"— ἀνάγκη. — ἐπὶ τούτοις τί παραγγέλλεται ἐν λόγῳ; τὸ ἀκόλουθον τοῖς δοθεῖσιν ὑπὸ σοῦ καλῶς παραδέχου.","st":"1.7"},{"sp":"N","t":"ἄγε ἀρκεῖ οὖν κἀνταῦθα γνῶναι τοῦτο; οὐκ ἀρκεῖ, δεῖ δὲ μαθεῖν πῶς τί τισιν ἀκόλουθον γίνεται καὶ ποτὲ μὲν ἓν ἑνὶ ἀκολουθεῖ, ποτὲ δὲ πλείοσιν κοινῇ.","st":"1.7"},{"sp":"N","t":"μή ποτε οὖν καὶ τοῦτο ἀνάγκη προσλαβεῖν τὸν μέλλοντα ἐν λόγῳ συνετῶς ἀναστραφήσεσθαι καὶ αὐτόν τ᾽ ἀποδείξειν ἕκαστα ἀποδόντα καὶ τοῖς ἀποδεικνύουσι παρακολουθήσειν μηδ᾽ ὑπὸ τῶν σοφιζομένων διαπλανηθήσεσθαι ὡς ἀποδεικνυόντων;","st":"1.7"},{"sp":"N","t":"οὐκοῦν ἐλήλυθεν ἡμῖν περὶ τῶν συναγόντων λόγων καὶ τρόπων πραγματεία καὶ γυμνασία καὶ ἀναγκαία πέφηνεν.","st":"1.7"},{"sp":"N","t":"ἀλλὰ δὴ ἔστιν ἐφ᾽ ὧν δεδώκαμεν ὑγιῶς τὰ λήμματα καὶ συμβαίνει τουτὶ ἐξ αὐτῶν: ψεῦδος δὲ ὂν οὐδὲν ἧττον συμβαίνει.","st":"1.7"},{"sp":"N","t":"τί οὖν μοι καθήκει ποιεῖν; προσδέχεσθαι τὸ ψεῦδος;","st":"1.7"},{"sp":"N","t":"καὶ πῶς οἷόν τ᾽; ἀλλὰ λέγειν ὅτι ‘οὐχ ὑγιῶς παρεχώρησα τὰ ὡμολογημένα;’ καὶ μὴν οὐδὲ τοῦτο δίδοται. ἀλλ᾽ ὅτι ‘οὐ συμβαίνει διὰ τῶν παρακεχωρημένων;’ ἀλλ᾽ οὐδὲ τοῦτο δίδοται.","st":"1.7"},{"sp":"N","t":"τί οὖν ἐπὶ τούτων ποιητέον; ἢ μή ποτε ὡς οὐκ ἀρκεῖ τὸ δανείσασθαι πρὸς τὸ ἔτι ὀφείλειν, ἀλλὰ δεῖ προσεῖναι καὶ τὸ ἐπιμένειν ἐπὶ τοῦ δανείου καὶ μὴ διαλελύσθαι αὐτό, οὕτως οὐκ ἀρκεῖ πρὸς τὸ δεῖν παραχωρεῖν τὸ ἐπιφερόμενον τὸ δεδωκέναι τὰ λήμματα, δεῖ δ᾽ ἐπιμένειν ἐπὶ τῆς παραχωρήσεως αὐτῶν.","st":"1.7"},{"sp":"N","t":"καὶ δὴ μενόντων μὲν αὐτῶν εἰς τέλος ὁποῖα παρεχωρήθη πᾶσα ἀνάγκη ἡμᾶς ἐπὶ τῆς παραχωρήσεως ἐπιμένειν καὶ","st":"1.7"},{"sp":"N","t":"τὸ ἀκόλουθον αὐτοῖς προσδέχεσθαι ... οὐδὲ γὰρ ἡμῖν ἔτι οὐδὲ καθ᾽ ἡμᾶς συμβαίνει τοῦτο τὸ ἐπιφερόμενον, ἐπειδὴ τῆς συγχωρήσεως τῶν λημμάτων ἀπέστημεν.","st":"1.7"},{"sp":"N","t":"δεῖ οὖν καὶ τὰ τοιαῦτα τῶν λημμάτων ἱστορῆσαι καὶ τὴν τοιαύτην μεταβολήν τε καὶ μετάπτωσιν αὐτῶν, καθ᾽ ἣν ἐν αὐτῇ τῇ ἐρωτήσει ἢ τῇ ἀποκρίσει ἢ τῷ συλλελογίσθαι ἤ τινι ἄλλῳ τοιούτῳ † λαμβάνοντα τὰς μεταπτώσεις ἀφορμὴν παρέχει τοῖς ἀνοήτοις τοῦ ταράσσεσθαι μὴ βλέπουσι τὸ ἀκόλουθον. τίνος ἕνεκα; ἵν᾽ ἐν τῷ τόπῳ","st":"1.7"},{"sp":"N","t":"τούτῳ μὴ παρὰ τὸ καθῆκον μηδ᾽ εἰκῇ μηδὲ συγκεχυμένως ἀναστρεφώμεθα.","st":"1.7"},{"sp":"N","t":"καὶ τὸ αὐτὸ ἐπί τε τῶν ὑποθέσεων καὶ τῶν ὑποθετικῶν λόγων. ἀναγκαῖον γὰρ ἔστιν ὅτ᾽ αἰτῆσαί τινα ὑπόθεσιν ὥσπερ ἐπιβάθραν τῷ ἑξῆς λόγῳ.","st":"1.7"},{"sp":"N","t":"πᾶσαν οὖν τὴν δοθεῖσαν παραχωρητέον ἢ οὐ πᾶσαν; καὶ εἰ οὐ πᾶσαν, τίνα;","st":"1.7"},{"sp":"N","t":"περὶ τίνος ἡ σκέψις; περὶ καθήκοντος. παραχωρήσαντι δὲ μενετέον εἰς ἅπαν ἐπὶ τῆς τηρήσεως ἢ ἔστιν ὅτε ἀποστατέον, τὰ δ᾽ ἀκόλουθα προσδεκτέον καὶ τὰ μαχόμενα οὐ προσδεκτέον;","st":"1.7"},{"sp":"N","t":"— ναί. — ἀλλὰ λέγει τις ὅτι ‘ποιήσω σε δυνατοῦ δεξάμενον ὑπόθεσιν ἐπ᾽ ἀδύνατον ἀπαχθῆναι.’ πρὸς τοῦτον οὐ συγκαθήσει ὁ φρόνιμος, ἀλλὰ φεύξεται ἐξέτασιν καὶ κοινολογίαν;","st":"1.7"},{"sp":"N","t":"καὶ τίς ἔτι ἄλλος ἐστὶ λόγῳ χρηστικὸς καὶ δεινὸς ἐρωτήσει καὶ ἀποκρίσει καὶ νὴ Δία ἀνεξαπάτητός τε καὶ ἀσόφιστος;","st":"1.7"},{"sp":"N","t":"ἀλλὰ συγκαθήσει μέν, οὐκ ἐπιστραφήσεται δὲ τοῦ μὴ εἰκῇ καὶ ὡς ἔτυχεν ἀναστρέφεσθαι ἐν λόγῳ; καὶ πῶς ἔτι ἔσται τοιοῦτος οἷον αὐτὸν ἐπινοοῦμεν;","st":"1.7"},{"sp":"N","t":"ἀλλ᾽ ἄνευ τινὸς τοιαύτης γυμνασίας καὶ παρασκευῆς φυλάττειν οἷός τ᾽ ἐστὶ τὸ ἑξῆς;","st":"1.7"},{"sp":"N","t":"τοῦτο δεικνύτωσαν καὶ παρέλκει τὰ θεωρήματα ταῦτα πάντα, ἄτοπα ἦν καὶ ἀνακόλουθα τῇ προλήψει τοῦ σπουδαίου.","st":"1.7"},{"sp":"N","t":"τί ἔτι ἀργοὶ καὶ ῥᾴθυμοι καὶ νωθροί ἐσμεν καὶ προφάσεις ζητοῦμεν, καθ᾽ ἃς οὐ πονήσομεν οὐδ᾽ ἀγρυπνήσομεν ἐξεργαζόμενοι τὸν αὑτῶν λόγον;","st":"1.7"},{"sp":"N","t":"— ἂν οὖν ἐν τούτοις πλανηθῶ, μή τι τὸν πατέρα ἀπέκτεινα; — ἀνδράποδον, ποῦ γὰρ ἐνθάδε πατὴρ ἦν, ἵν᾽ αὐτὸν ἀποκτείνῃς; τί οὖν ἐποίησας; ὃ μόνον ἦν κατὰ τὸν τόπον ἁμάρτημα, τοῦτο ἡμάρτηκας.","st":"1.7"},{"sp":"N","t":"ἐπεί τοι τοῦτ᾽ αὐτὸ καὶ ἐγὼ Ῥούφῳ εἶπον ἐπιτιμῶντί μοι ὅτι τὸ παραλειπόμενον ἓν ἐν συλλογισμῷ τινι οὐχ εὕρισκον. ‘οὐχ οἷον μέν,’ φημί, ‘εἰ τὸ Καπιτώλιον κατέκαυσα,’ ὁ δ᾽ ‘ἀνδράποδον,’ ἔφη,","st":"1.7"},{"sp":"N","t":"‘ἐνθάδε τὸ παραλειπόμενον Καπιτώλιόν ἐστιν.’ ἢ ταῦτα μόνα ἁμαρτήματά ἐστι τὸ Καπιτώλιον ἐμπρῆσαι καὶ τὸν πατέρα ἀποκτεῖναι, τὸ δ᾽ εἰκῇ καὶ μάτην καὶ ὡς ἔτυχεν χρῆσθαι ταῖς φαντασίαις ταῖς αὑτοῦ καὶ μὴ παρακολουθεῖν λόγῳ μηδ᾽ ἀποδείξει μηδὲ σοφίσματι μηδ᾽ ἁπλῶς βλέπειν τὸ καθ᾽ αὑτὸν καὶ οὐ καθ᾽ αὑτὸν ἐν ἐρωτήσει καὶ ἀποκρίσει, τούτων δ᾽ οὐδέν ἐστιν ἁμάρτημα; ὅτι αἱ δυνάμεις τοῖς ἀπαιδεύτοις οὐκ ἀσφαλεῖς. καθ᾽ ὅσους τρόπους μεταλαμβάνειν ἔστι τὰ ἰσοδυναμοῦντα ἀλλήλοις, κατὰ τοσούτους καὶ τὰ εἴδη τῶν ἐπιχειρημάτων τε καὶ ἐνθυμημάτων ἐν τοῖς λόγοις ἐκποιεῖ μεταλαμβάνειν.","st":"1.7"},{"sp":"N","t":"οἷον φέρε τὸν τρόπον τοῦτον: εἰ ἐδανείσω καὶ μὴ ἀπέδωκας, ὀφείλεις μοι τὸ ἀργύριον: οὐχὶ ἐδανείσω μὲν καὶ οὐκ ἀπέδωκας: οὐ μὴν ὀφείλεις μοι τὸ ἀργύριον.","st":"1.8"},{"sp":"N","t":"καὶ τοῦτο οὐδενὶ μᾶλλον προσήκει ἢ τῷ φιλοσόφῳ ἐμπείρως ποιεῖν. εἴπερ γὰρ ἀτελὴς συλλογισμός ἐστι τὸ ἐνθύμημα, δῆλον ὅτι ὁ περὶ τὸν τέλειον συλλογισμὸν γεγυμνασμένος οὗτος ἂν ἱκανὸς εἴη καὶ περὶ τὸν ἀτελῆ οὐδὲν ἧττον.","st":"1.8"},{"sp":"N","t":"τί ποτ᾽ οὖν οὐ γυμνάζομεν αὑτούς τε καὶ ἀλλήλους τὸν τρόπον τοῦτον;","st":"1.8"},{"sp":"N","t":"ὅτι νῦν καίτοι μὴ γυμναζόμενοι περὶ ταῦτα μηδ᾽ ἀπὸ τῆς ἐπιμελείας τοῦ ἤθους ὑπό γε ἐμοῦ περισπώμενοι ὅμως οὐδὲν ἐπιδίδομεν εἰς καλοκἀγαθίαν.","st":"1.8"},{"sp":"N","t":"τί οὖν χρὴ προσδοκᾶν, εἰ καὶ ταύτην τὴν ἀσχολίαν προσλάβοιμεν; καὶ μάλισθ᾽, ὅτι οὐ μόνον ἀσχολία τις ἀπὸ τῶν ἀναγκαιοτέρων αὐτὴ προσγένοιτ᾽ ἄν, ἀλλὰ καὶ οἰήσεως ἀφορμὴ καὶ τύφου οὐχ ἡ τυχοῦσα.","st":"1.8"},{"sp":"N","t":"μεγάλη γάρ ἐστι δύναμις ἡ ἐπιχειρητικὴ καὶ πιθανολογική, καὶ μάλιστ᾽ εἰ τύχοι γυμνασίας ἐπιπλέον καί τινα καὶ εὐπρέπειαν ἀπὸ τῶν ὀνομάτων προσλάβοι.","st":"1.8"},{"sp":"N","t":"ὅτι καὶ ἐν τῷ καθόλου πᾶσα δύναμις ἐπισφαλὴς τοῖς ἀπαιδεύτοις καὶ ἀσθενέσι προσγενομένη πρὸς τὸ ἐπᾶραι καὶ χαυνῶσαι ἐπ᾽ αὐτῇ.","st":"1.8"},{"sp":"N","t":"ποίᾳ γὰρ ἄν τις ἔτι μηχανῇ πείσαι τὸν νέον τὸν ἐν τούτοις διαφέροντα, ὅτι οὐ δεῖ προσθήκην αὐτὸν ἐκείνων γενέσθαι, ἀλλ᾽ ἐκεῖνα αὐτῷ προσθεῖναι;","st":"1.8"},{"sp":"N","t":"οὐχὶ δὲ πάντας τοὺς λόγους τούτους καταπατήσας ἐπηρμένος ἡμῖν καὶ πεφυσημένος περιπατεῖ μηδ᾽ ἀνεχόμενος, ἄν τις ἅπτηται τι αὐτοῦ ὑπομιμνῄσκων, τίνος ἀπολελειμμένος ποῦ ἀποκέκλικεν;","st":"1.8"},{"sp":"N","t":"τί οὖν; Πλάτων φιλόσοφος οὐκ ἦν; — Ἱπποκράτης γὰρ ἰατρὸς οὐκ ἦν; ἀλλ᾽ ὁρᾷς πῶς φράζει Ἱπποκράτης. μή τι οὖν Ἱπποκράτης οὕτω φράζει, καθὸ ἰατρός ἐστιν;","st":"1.8"},{"sp":"N","t":"τί οὖν μιγνύεις πράγματα ἄλλως ἐπὶ τῶν αὐτῶν ἀνθρώπων συνδραμόντα;","st":"1.8"},{"sp":"N","t":"εἰ δὲ καλὸς ἦν Πλάτων καὶ ἰσχυρός, ἔδει κἀμὲ καθήμενον ἐκπονεῖν, ἵνα καλὸς γένωμαι ἢ ἵνα ἰσχυρός, ὡς τοῦτο ἀναγκαῖον πρὸς φιλοσοφίαν, ἐπεί τις φιλόσοφος ἅμα καὶ καλὸς ἦν καὶ φιλόσοφος;","st":"1.8"},{"sp":"N","t":"οὐ θέλεις αἰσθάνεσθαι καὶ διακρῖναι κατὰ τί οἱ ἄνθρωποι γίνονται φιλόσοφοι καὶ τίνα ἄλλως αὐτοῖς πάρεστιν; ἄγε εἰ δ᾽ ἐγὼ φιλόσοφος ἤμην, ἔδει ὑμᾶς καὶ χωλοὺς γενέσθαι; τί οὖν;","st":"1.8"},{"sp":"N","t":"αἴρω τὰς δυνάμεις ταύτας; μὴ γένοιτο: οὐδὲ γὰρ τὴν ὁρατικήν.","st":"1.8"},{"sp":"N","t":"ὅμως δ᾽, ἄν μου πυνθάνῃ τί ἐστιν ἀγαθὸν τοῦ ἀνθρώπου, οὐκ ἔχω σοι ἄλλο εἰπεῖν ἢ ὅτι ποιὰ προαίρεσις φαντασιῶν. πῶς ἀπὸ τοῦ συγγενεῖς ἡμᾶς εἶναι τῷ θεῷ ἐπέλθοι ἄν τις ἐπὶ τὰ ἑξῆς. εἰ ταῦτά ἐστιν ἀληθῆ τὰ περὶ τῆς συγγενείας τοῦ θεοῦ καὶ ἀνθρώπων λεγόμενα ὑπὸ τῶν φιλοσόφων, τί ἄλλο ἀπολείπεται τοῖς ἀνθρώποις ἢ τὸ τοῦ Σωκράτους, μηδέποτε πρὸς τὸν πυθόμενον ποδαπός ἐστιν εἰπεῖν ὅτι Ἀθηναῖος ἢ Κορίνθιος, ἀλλ᾽ ὅτι κόσμιος;","st":"1.8"},{"sp":"N","t":"διὰ τί γὰρ λέγεις Ἀθηναῖον εἶναι σεαυτόν, οὐχὶ δ᾽ ἐξ ἐκείνης μόνον τῆς γωνίας, εἰς ἣν ἐρρίφη γεννηθέν σου τὸ σωμάτιον;","st":"1.9"},{"sp":"N","t":"ἢ δῆλον ὅτι ἀπὸ τοῦ κυριωτέρου καὶ περιέχοντος οὐ μόνον αὐτὴν ἐκείνην τὴν γωνίαν, ἀλλὰ καὶ ὅλην σου τὴν οἰκίαν καὶ ἁπλῶς ὅθεν σου τὸ γένος τῶν προγόνων εἰς σὲ κατελήλυθεν ἐντεῦθέν ποθεν καλεῖς σεαυτὸν Ἀθηναῖον καὶ Κορίνθιον;","st":"1.9"},{"sp":"N","t":"ὁ τοίνυν τῇ διοικήσει τοῦ κόσμου παρηκολουθηκὼς καὶ μεμαθηκώς, ὅτι ‘τὸ μέγιστον καὶ κυριώτατον καὶ περιεκτικώτατον πάντων τοῦτό ἐστι τὸ σύστημα τὸ ἐξ ἀνθρώπων καὶ θεοῦ, ἀπ᾽ ἐκείνου δὲ τὰ σπέρματα καταπέπτωκεν οὐκ εἰς τὸν πατέρα τὸν ἐμὸν μόνον οὐδ᾽ εἰς τὸν πάππον, ἀλλ᾽ εἰς ἅπαντα μὲν τὰ ἐπὶ γῆς γεννώμενά τε καὶ φυόμενα, προηγουμένως δ᾽ εἰς τὰ λογικά,","st":"1.9"},{"sp":"N","t":"ὅτι κοινωνεῖν μόνον ταῦτα πέφυκεν τῷ θεῷ τῆς συναναστροφῆς κατὰ τὸν λόγον ἐπι","st":"1.9"},{"sp":"N","t":"πεπλεγμένα,’ διὰ τί μὴ εἴπῃ τις αὑτὸν κόσμιον; διὰ τί μὴ υἱὸν τοῦ θεοῦ; διὰ τί δὲ φοβηθήσεταί τι τῶν γιγνομένων ἐν ἀνθρώποις;","st":"1.9"},{"sp":"N","t":"ἀλλὰ πρὸς μὲν τὸν Καίσαρα ἡ συγγένεια ἢ ἄλλον τινὰ τῶν μέγα δυναμένων ἐν Ῥώμῃ ἱκανὴ παρέχειν ἐν ἀσφαλείᾳ διάγοντας καὶ ἀκαταφρονήτους καὶ δεδοικότας μηδ᾽ ὁτιοῦν, τὸ δὲ τὸν θεὸν ποιητὴν ἔχειν καὶ πατέρα καὶ κηδεμόνα οὐκέτι ἡμᾶς ἐξαιρήσεται λυπῶν καὶ φόβων;","st":"1.9"},{"sp":"N","t":"— καὶ πόθεν φάγω, φησίν, μηδὲν ἔχων; — καὶ πῶς οἱ δοῦλοι, πῶς οἱ δραπέται, τίνι πεποιθότες ἐκεῖνοι ἀπαλλάττονται τῶν δεσποτῶν; τοῖς ἀγροῖς. ἢ τοῖς οἰκέταις ἢ τοῖς ἀργυρώμασιν; οὐδενί, ἀλλ᾽ ἑαυτοῖς: καὶ ὅμως οὐκ ἐπιλείπουσιν αὐτοὺς τροφαί.","st":"1.9"},{"sp":"N","t":"τὸν δὲ φιλόσοφον ἡμῖν δεήσει ἄλλοις θαρροῦντα καὶ ἐπαναπαυόμενον ἀποδημεῖν καὶ μὴ ἐπιμελεῖσθαι αὐτὸν αὑτοῦ καὶ τῶν θηρίων τῶν ἀλόγων εἶναι χείρονα καὶ δειλότερον, ὧν ἕκαστον αὐτὸ αὑτῷ ἀρκούμενον οὔτε τροφῆς ἀπορεῖ τῆς οἰκείας οὔτε διεξαγωγῆς τῆς καταλλήλους καὶ κατὰ φύσιν;","st":"1.9"},{"sp":"N","t":"ἐγὼ μὲν οἶμαι, ὅτι ἔδει καθῆσθαι τὸν πρεσβύτερον ἐνταῦθα οὐ τοῦτο μηχανώμενον, ὅπως μὴ ταπεινοφρονήσητε μηδὲ ταπεινοὺς μηδ᾽ ἀγεννεῖς τινας διαλογισμοὺς διαλογιεῖσθε αὐτοὶ περὶ ἑαυτῶν,","st":"1.9"},{"sp":"N","t":"ἀλλὰ μή τινες ἐμπίπτωσιν τοιοῦτοι νέοι, οἳ ἐπιγνόντες τὴν πρὸς τοὺς θεοὺς συγγένειαν καὶ ὅτι δεσμά τινα ταῦτα προσηρτήμεθα τὸ σῶμα καὶ τὴν κτῆσιν αὐτοῦ καὶ ὅσα τούτων ἕνεκα ἀναγκαῖα ἡμῖν γίνεται εἰς οἰκονομίαν καὶ ἀναστροφὴν τὴν ἐν τῷ βίῳ, ὡς βάρη τινὰ καὶ ἀνιαρὰ καὶ ἄχρηστα ἀπορρῖψαι θέλωσιν καὶ ἀπελθεῖν πρὸς τοὺς συγγενεῖς.","st":"1.9"},{"sp":"N","t":"καὶ τοῦτον ἔδει τὸν ἀγῶνα ἀγωνίζεσθαι τὸν διδάσκαλον ὑμῶν καὶ παιδευτήν, εἴ τις ἄρα ἦν: ὑμᾶς μὲν ἔρχεσθαι λέγοντας ‘Ἐπίκτητε, οὐκέτι ἀνεχόμεθα μετὰ τοῦ σωματίου τούτου δεδεμένοι καὶ τοῦτο τρέφοντες καὶ ποτίζοντες καὶ ἀναπαύοντες καὶ καθαίροντες, εἶτα δι᾽ αὐτὸ συμπεριφερόμενοι τοῖσδε καὶ τοῖσδε.","st":"1.9"},{"sp":"N","t":"οὐκ ἀδιάφορα ταῦτα καὶ οὐδὲν πρὸς ἡμᾶς καὶ ὁ θάνατος οὐ κακόν; καὶ συγγενεῖς τινες τοῦ θεοῦ ἐσμεν κἀκεῖθεν ἐληλύθαμεν;","st":"1.9"},{"sp":"N","t":"ἄφες ἡμᾶς ἀπελθεῖν ὅθεν ἐληλύθαμεν, ἄφες λυθῆναί ποτε τῶν δεσμῶν τούτων τῶν ἐξηρτημένων καὶ βαρούντων.","st":"1.9"},{"sp":"N","t":"ἐνταῦθα λῃσταὶ καὶ κλέπται καὶ δικαστήρια καὶ οἱ καλούμενοι τύραννοι δοκοῦντες ἔχειν τινὰ ἐφ᾽ ἡμῖν ἐξουσίαν διὰ τὸ σωμάτιον καὶ τὰ τούτου κτήματα. ἄφες δείξωμεν αὐτοῖς, ὅτι οὐδενὸς ἔχουσιν ἐξουσίαν:’","st":"1.9"},{"sp":"N","t":"ἐμὲ δ᾽ ἐν τῷδε λέγειν ὅτι ‘ἄνθρωποι, ἐκδέξασθε τὸν θεόν. ὅταν ἐκεῖνος σημήνῃ καὶ ἀπολύσῃ ὑμᾶς ταύτης τῆς ὑπηρεσίας, τότ᾽ ἀπολύεσθε πρὸς αὐτόν: ἐπὶ δὲ τοῦ παρόντος ἀνάσχεσθε ἐνοικοῦντες ταύτην τὴν χώραν, εἰς ἣν ἐκεῖνος ὑμᾶς ἔταξεν.","st":"1.9"},{"sp":"N","t":"ὀλίγος ἄρα χρόνος οὗτος ὁ τῆς οἰκήσεως καὶ ῥᾴδιος τοῖς οὕτω διακειμένοις. ποῖος γὰρ ἔτι τύραννος ἢ ποῖος κλέπτης ἢ ποῖα δικαστήρια φοβερὰ τοῖς οὕτως παρ᾽ οὐδὲν πεποιημένοις τὸ σῶμα καὶ τὰ τούτου κτήματα; μείνατε, μὴ ἀλογίστως ἀπέλθητε.’","st":"1.9"},{"sp":"N","t":"τοιοῦτόν τι ἔδει γίνεσθαι παρὰ τοῦ παιδευτοῦ πρὸς τοὺς εὐφυεῖς τῶν νέων.","st":"1.9"},{"sp":"N","t":"νῦν δὲ τί γίνεται; νεκρὸς μὲν ὁ παιδευτής, νεκροὶ δ᾽ ὑμεῖς. ὅταν χορτασθῆτε σήμερον, κάθησθε κλάοντες περὶ τῆς αὔριον, πόθεν φάγητε.","st":"1.9"},{"sp":"N","t":"ἀνδράποδον, ἂν σχῇς, ἕξεις: ἂν μὴ σχῇς, ἐξελεύσῃ: ἤνοικται ἡ θύρα. τί πενθεῖς; ποῦ ἔτι τόπος δακρύοις; τίς ἔτι κολακείας ἀφορμή; διὰ τί ἄλλος ἄλλῳ φθονήσει; διὰ τί πολλὰ κεκτημένους θαυμάσει ἢ τοὺς ἐν δυνάμει τεταγμένους, μάλιστ᾽ ἂν καὶ ἰσχυροὶ ὦσιν καὶ ὀργίλοι;","st":"1.9"},{"sp":"N","t":"τί γὰρ ἡμῖν ποιήσουσιν; ἃ δύνανται ποιῆσαι, τούτων οὐκ ἐπιστρεψόμεθα: ὧν ἡμῖν μέλει, ταῦτα οὐ δύνανται. τίς οὖν ἔτι ἄρξει τοῦ οὕτως διακειμένου;","st":"1.9"},{"sp":"N","t":"πῶς Σωκράτης εἶχεν πρὸς ταῦτα; πῶς γὰρ ἄλλως ἢ ὡς ἔδει τὸν πεπεισμένον ὅτι ἐστὶ τῶν θεῶν συγγενής;","st":"1.9"},{"sp":"N","t":"‘ἄν μοι λέγητε,’ φησίν, ‘νῦν ὅτι ‘ἀφίεμέν σε ἐπὶ τούτοις, ὅπως μηκέτι διαλέξῃ τούτους τοὺς λόγους οὓς μέχρι νῦν διελέγου μηδὲ παρενοχλήσεις ἡμῶν τοῖς νέοις μηδὲ τοῖς γέρουσιν’","st":"1.9"},{"sp":"N","t":", ἀποκρινοῦμαι ὅτι γελοῖοί ἐστε, οἵτινες ἀξιοῦτε, εἰ μέν με ὁ στρατηγὸς ὁ ὑμέτερος ἔταξεν εἴς τινα τάξιν, ὅτι ἔδει με τηρεῖν αὐτὴν καὶ φυλάττειν καὶ μυριάκις πρότερον αἱρεῖσθαι ἀποθνῄσκειν ἢ ἐγκαταλιπεῖν αὐτήν, εἰ δ᾽ ὁ θεὸς ἔν τινι χώρᾳ καὶ ἀναστροφῇ κατατέταχεν, ταύτην δ᾽ ἐγκαταλιπεῖν δεῖ ἡμᾶς.’ τοῦτ᾽ ἔστιν ἄνθρωπος ταῖς ἀληθείαις συγγενὴς τῶν θεῶν.","st":"1.9"},{"sp":"N","t":"ἡμεῖς οὖν ὡς κοιλίαι,","st":"1.9"},{"sp":"N","t":"ὡς ἔντερα, ὡς αἰδοῖα, οὕτω περὶ αὑτῶν διανοούμεθα, ὅτι φοβούμεθα, ὅτι ἐπιθυμοῦμεν: τοὺς εἰς ταῦτα συνεργεῖν δυναμένους κολακεύομεν, τοὺς αὐτοὺς τούτους δεδοίκαμεν.","st":"1.9"},{"sp":"N","t":"ἐμέ τις ἠξίωκεν ὑπὲρ αὐτοῦ γράψαι εἰς τὴν Ῥώμην ὡς ἐδόκει τοῖς πολλοῖς ἠτυχηκὼς καὶ πρότερον μὲν ἐπιφανὴς ὢν καὶ πλούσιος, ὕστερον δ᾽ ἐκπεπτωκὼς ἁπάντων καὶ διάγων ἐνταῦθα.","st":"1.9"},{"sp":"N","t":"κἀγὼ ἔγραψα ὑπὲρ αὐτοῦ ταπεινῶς. ὁ δ᾽ ἀναγνοὺς τὴν ἐπιστολὴν ἀπέδωκέν μοι αὐτὴν καὶ ἔφη ὅτι ‘ἐγὼ βοηθηθῆναί τι ὑπὸ σοῦ ἤθελον, οὐχὶ ἐλεηθῆναι: κακὸν δέ μοι οὐθέν ἐστιν.’ οὕτως καὶ Ῥοῦφος πειράζων μ᾽ εἰώθει λέγειν","st":"1.9"},{"sp":"N","t":"‘συμβήσεταί σοι τοῦτο καὶ τοῦτο ὑπὸ τοῦ δεσπότου.’","st":"1.9"},{"sp":"N","t":"κἀμοῦ πρὸς αὐτὸν ἀποκριναμένου ὅτι ‘ἀνθρώπινα’ ‘τί οὖν ἔτι ἐκεῖνον παρακαλῶ παρὰ σοῦ αὐτὰ λαβεῖν δυνάμενος;’ τῷ γὰρ ὄντι,","st":"1.9"},{"sp":"N","t":"ὃ ἐξ αὑτοῦ τις ἔχει, περισσὸς καὶ μάταιος παρ᾽ ἄλλου λαμβάνων.","st":"1.9"},{"sp":"N","t":"ἐγὼ οὖν ἔχων ἐξ ἐμαυτοῦ λαβεῖν τὸ μεγαλόψυχον καὶ γενναῖον, ἀγρὸν παρὰ σοῦ λάβω καὶ ἀργύριον ἢ ἀρχήν τινα; μὴ γένοιτο. οὐχ οὕτως ἀναίσθητος ἔσομαι τῶν ἐμῶν κτημάτων.","st":"1.9"},{"sp":"N","t":"ἀλλ᾽ ὅταν τις ᾖ δειλὸς καὶ ταπεινός, ὑπὲρ τούτου τί ἄλλο ἢ ἀνάγκη γράφειν ἐπιστολὰς ὡς ὑπὲρ νεκροῦ ‘τὸ πτῶμα ἡμῖν χάρισαι τοῦ δεῖνος καὶ ξέστην αἱματίου;’","st":"1.9"},{"sp":"N","t":"τῷ γὰρ ὄντι πτῶμα ὁ τοιοῦτός ἐστι καὶ ξέστης αἱματίου, πλέον δ᾽ οὐδέν. εἰ δ᾽ ἦν πλέον τι, ᾐσθάνετ᾽ ἄν, ὅτι ἄλλος δι᾽ ἄλλον οὐ δυστυχεῖ. πρὸς τοὺς περὶ τὰς ἐν Ῥώμῃ προαγωγὰς ἐσπουδακότας. εἰ οὕτως σφοδρῶς συνετετάγμεθα περὶ τὸ ἔργον τὸ ἑαυτῶν ὡς οἱ ἐν Ῥώμῃ γέροντες περὶ ἃ ἐσπουδάκασιν, τάχα ἄν τι ἠνύομεν καὶ αὐτοί.","st":"1.9"},{"sp":"N","t":"οἶδα ἐγὼ πρεσβύτερον ἄνθρωπον ἐμοῦ τὸν νῦν ἐπὶ τοῦ σίτου ὄντα ἐν Ῥώμῃ, ὅτε ταύτῃ παρῆγεν ἀπὸ τῆς φυγῆς ἀναστρέφων, οἷα εἶπέν μοι, κατατρέχων τοῦ προτέρου ἑαυτοῦ βίου καὶ περὶ τῶν ἑξῆς ἐπαγγελλόμενος, ὅτι ἄλλο οὐδὲν ἀναβὰς σπουδάσει ἢ ἐν ἡσυχίᾳ καὶ ἀταραξίᾳ διεξαγαγεῖν τὸ λοιπὸν τοῦ βίου: ‘πόσον γὰρ ἔτι ἐστὶν ἐμοὶ τὸ λοιπόν;’","st":"1.10"},{"sp":"N","t":"— κἀγὼ ἔλεγον αὐτῷ ὅτι ‘οὐ ποιήσεις, ἀλλ᾽ ὀσφρανθεὶς μόνον τῆς Ῥώμης ἁπάντων τούτων ἐπιλήσῃ.’ ἂν δὲ καὶ εἰς αὐλὴν πάροδός τις δίδωται, ὅτι χαίρων καὶ τῷ θεῷ εὐχαριστῶν ὤσεται.","st":"1.10"},{"sp":"N","t":"—’ἄν μ᾽ εὕρῃς,’ ἔφη, ‘Ἐπίκτητε, τὸν ἕτερον πόδα εἰς τὴν αὐλὴν τιθέντα, ὃ βούλει ὑπολάμβανε.’","st":"1.10"},{"sp":"N","t":"νῦν οὖν τί ἐποίησεν; πρὶν ἐλθεῖν εἰς τὴν Ῥώμην, ἀπήντησαν αὐτῷ παρὰ Καίσαρος πινακίδες: ὁ δὲ λαβὼν πάντων ἐκείνων ἐξελάθετο καὶ λοιπὸν ἓν ἐξ ἑνὸς ἐπισεσώρευκεν.","st":"1.10"},{"sp":"N","t":"ἤθελον αὐτὸν νῦν παραστὰς ὑπομνῆσαι τῶν λόγων, οὓς ἔλεγεν παρερχόμενος, καὶ εἰπεῖν ὅτι ‘πόσῳ σοῦ ἐγὼ κομψότερος μάντις εἰμί.’","st":"1.10"},{"sp":"N","t":"τί οὖν; ἐγὼ λέγω, ὅτι ἄπρακτόν ἐστι τὸ ζῷον; μὴ γένοιτο. ἀλλὰ διὰ τί ἡμεῖς οὐκ ἐσμὲν πρακτικοί; εὐθὺς ἐγὼ πρῶτος,","st":"1.10"},{"sp":"N","t":"ὅταν ἡμέρα γένηται, μικρὰ ὑπομιμνῄσκομαι, τίνα ἐπαναγνῶναί με δεῖ. εἶτα εὐθὺς ἐμαυτῷ: ‘τί δέ μοι καὶ μέλει πῶς ὁ δεῖνα ἀναγνῷ; πρῶτόν ἐστιν, ἵνα ἐγὼ κοιμηθῶ.’","st":"1.10"},{"sp":"N","t":"καίτοι τί ὅμοια τὰ ἐκείνων πράγματα τοῖς ἡμετέροις; ἂν ἐπιστῆτε, τί ἐκεῖνοι ποιοῦσιν, αἰσθήσεσθε. τί γὰρ ἄλλο ἢ ὅλην τὴν ἡμέραν ψηφίζουσιν, συζητοῦσι, συμβουλεύουσι περὶ σιταρίου, περὶ ἀγριδίου, περί τινων προκοπῶν τοιούτων;","st":"1.10"},{"sp":"N","t":"ὅμοιον οὖν ἐστιν ἐντευξίδιον παρά τινος λαβόντα ἀναγιγνώσκειν ‘παρακαλῶ σε ἐπιτρέψαι μοι σιτάριον ἐξαγαγεῖν’ ἢ ‘παρακαλῶ σε παρὰ Χρυσίππου ἐπισκέψασθαι τίς ἐστιν ἡ τοῦ κόσμου διοίκησις καὶ ποίαν τινὰ χώραν ἐν αὐτῷ ἔχει τὸ λογικὸν ζῷον: ἐπίσκεψαι δὲ καὶ τίς εἶ σὺ καὶ ποῖόν τι σοῦ τὸ ἀγαθὸν καὶ τὸ κακόν;’","st":"1.10"},{"sp":"N","t":"ταῦτα ἐκείνοις ὅμοιά ἐστιν; ἀλλ᾽ ὁμοίας σπουδῆς χρείαν ἔχοντα; ἀλλ᾽ ὡσαύτως ἀμελεῖν αἰσχρὸν τούτων κἀκείνων;","st":"1.10"},{"sp":"N","t":"τί οὖν; ἡμεῖς μόνοι ῥᾳθυμοῦμεν καὶ νυστάζομεν; οὔ: ἀλλὰ πολὺ πρότερον ὑμεῖς οἱ νέοι.","st":"1.10"},{"sp":"N","t":"ἐπεί τοι καὶ ἡμεῖς οἱ γέροντες, ὅταν παίζοντας ὁρῶμεν νέους, συμπροθυμούμεθα καὶ αὐτοὶ συμπαίζειν. πολὺ δὲ πλέον, εἰ ἑώρων διεγηγερμένους καὶ συμπροθυμουμένους, προεθυμούμην ἂν συσπουδάζειν καὶ αὐτός. περὶ φιλοστοργίας. ἀφικομένου δέ τινος πρὸς αὐτὸν τῶν ἐν τέλει πυθόμενος παρ᾽ αὐτοῦ τὰ ἐπὶ μέρους ἠρώτησεν, εἰ καὶ τέκνα εἴη αὐτῷ καὶ γυνή.","st":"1.10"},{"sp":"N","t":"τοῦ δ᾽ ὁμολογήσαντος προσεπύθετο: πῶς τι οὖν χρῇ τῷ πράγματι; — ἀθλίως, ἔφη.","st":"1.11"},{"sp":"N","t":"— καὶ ὅς: τίνα τρόπον; οὐ γὰρ δὴ τούτου γ᾽ ἕνεκα γαμοῦσιν ἄνθρωποι καὶ παιδοποιοῦνται, ὅπως ἄθλιοι ὦσιν, ἀλλὰ μᾶλλον ὅπως εὐδαίμονες.","st":"1.11"},{"sp":"N","t":"— ἀλλ᾽ ἐγώ, ἔφη, οὕτως ἀθλίως ἔχω περὶ τὰ παιδάρια, ὥστε πρῴην νοσοῦντός μου τοῦ θυγατρίου καὶ δόξαντος κινδυνεύειν οὐχ ὑπέμεινα οὐδὲ παρεῖναι αὐτῷ νοσοῦντι, φυγὼν δ᾽ ᾠχόμην, μέχρις οὗ προσήγγειλέ τις μοι ὅτι ἔχει καλῶς.","st":"1.11"},{"sp":"N","t":"— τί οὖν; ὀρθῶς φαίνει σαυτῷ ταῦτα πεποιηκέναι; — φυσικῶς, ἔφη. — ἀλλὰ μὴν τοῦτό με πεῖσον, ἔφη, σύ, διότι φυσικῶς, καὶ ἐγώ σε πείσω, ὅτι πᾶν τὸ κατὰ φύσιν γινόμενον ὀρθῶς γίνεται.","st":"1.11"},{"sp":"N","t":"— τοῦτο, ἔφη, πάντες ἢ οἵ γε πλεῖστοι πατέρες πάσχομεν. — οὐδ᾽ ἐγώ σοι ἀντιλέγω, ἔφη, ὅτι οὐ γίνεται, τὸ δ᾽ ἀμφισβητούμενον ἡμῖν ἐκεῖνό ἐστιν, εἰ ὀρθῶς.","st":"1.11"},{"sp":"N","t":"ἐπεὶ τούτου γ᾽ ἕνεκα καὶ τὰ φύματα δεῖ λέγειν ἐπ᾽ ἀγαθῷ γίνεσθαι τοῦ σώματος, ὅτι γίνεται, καὶ ἁπλῶς τὸ ἁμαρτάνειν εἶναι κατὰ φύσιν, ὅτι πάντες σχεδὸν ἢ οἵ γε πλεῖστοι ἁμαρτάνομεν.","st":"1.11"},{"sp":"N","t":"δεῖξον οὖν μοι σύ, πῶς κατὰ φύσιν ἐστίν. — οὐ δύναμαι, ἔφη: ἀλλὰ σύ μοι μᾶλλον δεῖξον, πῶς οὐκ ἔστι κατὰ φύσιν οὐδ᾽ ὀρθῶς γίνεται.","st":"1.11"},{"sp":"N","t":"— καὶ ὅς: ἀλλ᾽ εἰ ἐζητοῦμεν, ἔφη, περὶ λευκῶν καὶ μελάνων, ποῖον ἂν κριτήριον παρεκαλοῦμεν πρὸς διάγνωσιν αὐτῶν; — τὴν ὅρασιν, ἔφη. — τί δ᾽ εἰ περὶ θερμῶν καὶ ψυχρῶν καὶ σκληρῶν καὶ μαλακῶν, ποῖόν τι; — τὴν ἁφήν. — οὐκοῦν,","st":"1.11"},{"sp":"N","t":"ἐπειδὴ περὶ τῶν κατὰ φύσιν καὶ τῶν ὀρθῶς ἢ οὐκ ὀρθῶς γινομένων ἀμφισβητοῦμεν, ποῖον θέλεις κριτήριον παραλάβωμεν;","st":"1.11"},{"sp":"N","t":"— οὐκ οἶδ᾽, ἔφη. — καὶ μὴν τὸ μὲν τῶν χρωμάτων καὶ ὀσμῶν, ἔτι δὲ χυλῶν κριτήριον ἀγνοεῖν τυχὸν οὐ μεγάλη ζημία, τὸ δὲ τῶν ἀγαθῶν καὶ τῶν κακῶν καὶ τῶν κατὰ φύσιν καὶ παρὰ φύσιν τῷ ἀνθρώπῳ δοκεῖ σοι μικρὰ ζημία εἶναι τῷ ἀγνοοῦντι;","st":"1.11"},{"sp":"N","t":"— ἡ μεγίστη μὲν οὖν. — φέρε, εἰπέ μοι, πάντα ἃ δοκεῖ τισιν εἶναι καλὰ καὶ προσήκοντα, ὀρθῶς δοκεῖ; καὶ νῦν Ἰουδαίοις καὶ Σύροις καὶ Αἰγυπτίοις καὶ Ῥωμαίοις οἷόν τε πάντα τὰ δοκοῦντα περὶ τροφῆς ὀρθῶς δοκεῖν;","st":"1.11"},{"sp":"N","t":"— καὶ πῶς οἷόν τε; — ἀλλ᾽ οἶμαι πᾶσα ἀνάγκη, εἰ ὀρθά ἐστι τὰ Αἰγυπτίων, μὴ ὀρθὰ εἶναι τὰ τῶν ἄλλων, εἰ καλῶς ἔχει τὰ Ἰουδαίων, μὴ καλῶς ἔχειν τὰ τῶν ἄλλων.","st":"1.11"},{"sp":"N","t":"— πῶς γὰρ οὔ; — ὅπου δ᾽ ἄγνοια, ἐκεῖ καὶ ἀμαθία καὶ ἡ περὶ τὰ ἀναγκαῖα ἀπαιδευσία.","st":"1.11"},{"sp":"N","t":"— συνεχώρει. — σὺ οὖν, ἔφη, τούτων αἰσθόμενος οὐδὲν ἄλλο τοῦ λοιποῦ σπουδάσεις οὐδὲ πρὸς ἄλλῳ τινὶ τὴν γνώμην. ἕξεις ἢ ὅπως τὸ κριτήριον τῶν κατὰ φύσιν καταμαθὼν τούτῳ προσχρώμενος διακρινεῖς τῶν ἐπὶ μέρους ἕκαστον.","st":"1.11"},{"sp":"N","t":"ἐπὶ δὲ τοῦ παρόντος τὰ τοσαῦτα ἔχω σοι πρὸς ὃ βούλει βοηθῆσαι.","st":"1.11"},{"sp":"N","t":"τὸ φιλόστοργον δοκεῖ σοι κατὰ φύσιν τ᾽ εἶναι καὶ καλόν; — πῶς γὰρ οὔ; — τί δέ; τὸ μὲν φιλόστοργον κατὰ φύσιν τ᾽ ἐστὶ καὶ καλόν, τὸ δ᾽ εὐλόγιστον οὐ καλόν;","st":"1.11"},{"sp":"N","t":"— οὐδαμῶς. — μὴ τοίνυν μάχην ἔχει τῷ φιλοστόργῳ τὸ εὐλόγιστον; — οὐ δοκεῖ μοι. — εἰ δὲ μή, τῶν μαχομένων ἀνάγκη θατέρου κατὰ φύσιν ὄντος θάτερον εἶναι παρὰ φύσιν; ἢ γὰρ οὔ; — οὕτως, ἔφη.","st":"1.11"},{"sp":"N","t":"— οὐκοῦν ὅ τι ἂν εὑρίσκωμεν ὁμοῦ μὲν φιλόστοργον ὁμοῦ δ᾽ εὐλόγιστον, τοῦτο θαρροῦντες ἀποφαινόμεθα ὀρθόν τε εἶναι καὶ καλόν;","st":"1.11"},{"sp":"N","t":"— ἔστω, ἔφη. — τί οὖν; ἀφεῖναι νοσοῦν τὸ παιδίον καὶ ἀφέντα ἀπελθεῖν ὅτι μὲν οὐκ εὐλόγιστον οὐκ οἶμαί σ᾽ ἀντερεῖν. ὑπολείπεται δ᾽ ἡμᾶς σκοπεῖν εἰ φιλόστοργον. — σκοπῶμεν δή. —","st":"1.11"},{"sp":"N","t":"ἆρ᾽ οὖν σὺ μὲν ἐπειδὴ φιλοστόργως διέκεισο πρὸς τὸ παιδίον, ὀρθῶς ἐποίεις φεύγων καὶ ἀπολείπων αὐτό; ἡ μήτηρ δ᾽ οὐ φιλοστοργεῖ τὸ παιδίον; — Φιλοστοργεῖ μὲν οὖν.","st":"1.11"},{"sp":"N","t":"— οὐκοῦν ἔδει καὶ τὴν μητέρα ἀφεῖναι αὐτὸ ἢ οὐκ ἔδει; — οὐκ ἔδει. — τί δ᾽ ἡ τιτθή; στέργει αὐτό; — στέργει, ἔφη. — ἔδει οὖν κἀκείνην ἀφεῖναι αὐτό; — οὐδαμῶς. — τί δ᾽ ὁ παιδαγωγός; οὐ στέργει αὐτό;","st":"1.11"},{"sp":"N","t":"— στέργει. — ἔδει οὖν κἀκεῖνον ἀφέντα ἀπελθεῖν, εἶθ᾽ οὕτως ἔρημον καὶ ἀβοήθητον ἀπολειφθῆναι τὸ παιδίον διὰ τὴν πολλὴν φιλοστοργίαν τῶν γονέων ὑμῶν καὶ τῶν περὶ αὐτὸ ἢ ἐν ταῖς χερσὶν τῶν οὔτε στεργόντων οὔτε κηδομένων ἀποθανεῖν; — μὴ γένοιτο.","st":"1.11"},{"sp":"N","t":"— καὶ μὴν ἐκεῖνό γε ἄνισον καὶ ἄγνωμον, ὅ τις αὑτῷ προσῆκον οἴεται διὰ τὸ φιλόστοργος εἶναι, τοῦτο τοῖς ὁμοίως φιλοστοργοῦσιν μὴ ἐφιέναι;","st":"1.11"},{"sp":"N","t":"— ἄτοπον. — ἄγε, σὺ δ᾽ ἂν νοσῶν ἠβούλου φιλοστόργους οὕτως ἔχειν τοὺς προσήκοντας τούς τ᾽ ἄλλους καὶ αὐτὰ τὰ τέκνα καὶ τὴν γυναῖκα, ὥστ᾽ ἀφεθῆναι μόνος ὑπ᾽ αὐτῶν καὶ ἔρημος;","st":"1.11"},{"sp":"N","t":"— οὐδαμῶς. — εὔξαιο δ᾽ ἂν οὕτως στερχθῆναι ὑπὸ τῶν σαυτοῦ, ὥστε διὰ τὴν ἄγαν αὐτῶν φιλοστοργίαν ἀεὶ μόνος ἀπολείπεσθαι ἐν ταῖς νόσοις, ἢ τούτου γ᾽ ἕνεκα μᾶλλον ἂν ὑπὸ τῶν ἐχθρῶν, εἰ δυνατὸν ἦν, φιλοστοργεῖσθαι ηὔχου, ὥστ᾽ ἀπολείπεσθαι ὑπ᾽ αὐτῶν; εἰ δὲ ταῦτα, ὑπολείπεται μηδαμῶς ἔτι φιλόστοργον εἶναι τὸ πραχθέν.","st":"1.11"},{"sp":"N","t":"τί οὖν; οὐδὲν ἦν τὸ κινῆσάν σε καὶ ἐξορμῆσαν πρὸς τὸ ἀφεῖναι τὸ παιδίον; καὶ πῶς οἷόν τε; ἀλλὰ τοιοῦτόν τι ἄν, οἷον καὶ ἐν Ῥώμῃ τινὰ ἦν τὸ κινοῦν, ὥστ᾽ ἐγκαλύπτεσθαι τοῦ ἵππου τρέχοντος ᾧ ἐσπουδάκει, εἶτα νικήσαντός ποτε παραλόγως σπόγγων δεῆσαι αὐτῷ πρὸς τὸ ἀναληφθῆναι λιποψυχοῦντα.","st":"1.11"},{"sp":"N","t":"τί οὖν τοῦτό ἐστιν; τὸ μὲν ἀκριβὲς οὐ τοῦ παρόντος καιροῦ τυχόν: ἐκεῖνο δ᾽ ἀπαρκεῖ πεισθῆναι, εἴπερ ὑγιές ἐστι τὸ ὑπὸ τῶν φιλοσόφων λεγόμενον, ὅτι οὐκ ἔξω που δεῖ ζητεῖν αὐτό, ἀλλ᾽ ἓν καὶ ταὐτόν ἐστιν ἐπὶ πάντων τὸ αἴτιον τοῦ ποιεῖν τι ἡμᾶς ἢ μὴ ποιεῖν, τοῦ λέγειν τινὰ ἢ μὴ λέγειν, τοῦ ἐπαίρεσθαι ἢ συστέλλεσθαι ἢ φεύγειν τινὰ ἢ διώκειν,","st":"1.11"},{"sp":"N","t":"τοῦθ᾽ ὅπερ καὶ νῦν ἐμοί τε καὶ σοὶ γέγονεν αἴτιον, σοὶ μὲν τοῦ ἐλθεῖν πρὸς ἐμὲ καὶ καθῆσθαι νῦν ἀκούοντα, ἐμοὶ δὲ τοῦ λέγειν ταῦτα.","st":"1.11"},{"sp":"N","t":"τί δ᾽ ἐστὶ τοῦτο; ἆρά γε ἄλλο ἢ ὅτι ἔδοξεν ἡμῖν; — οὐδέν. — εἰ δ᾽ ἄλλως ἡμῖν ἐφάνη, τί ἂν ἄλλο ἢ τὸ δόξαν ἐπράττομεν;","st":"1.11"},{"sp":"N","t":"οὐκ οὖν καὶ τῷ Ἀχιλλεῖ τοῦτο αἴτιον τοῦ πενθεῖν, οὐχ ὁ τοῦ Πατρόκλου θάνατος （ ἄλλος γάρ τις οὐ πάσχει ταῦτα τοῦ ἑταίρου ἀποθανόντος ）","st":"1.11"},{"sp":"N","t":", ἀλλ᾽ ὅτι ἔδοξεν αὐτῷ. καὶ σοὶ τότε φεύγειν τοῦτο αὐτὸ ὅτι ἔδοξέν σοι: καὶ πάλιν, ἐὰν μείνῃς, ὅτι ἔδοξέν σοι. καὶ νῦν ἐν Ῥώμῃ ἀνέρχῃ, ὅτι δοκεῖ σοι: κἂν μεταδόξῃ, οὐκ ἂν ἀπελεύσῃ.","st":"1.11"},{"sp":"N","t":"καὶ ἁπλῶς οὔτε θάνατος οὔτε φυγὴ οὔτε πόνος οὔτε ἄλλο τι τῶν τοιούτων αἴτιόν ἐστι τοῦ πράττειν τι ἢ μὴ πράττειν ἡμᾶς, ἀλλ᾽ ὑπολήψεις καὶ δόγματα. τοῦτό σε πείθω ἢ οὐχί;","st":"1.11"},{"sp":"N","t":"— Πείσθεις, ἔφη. — οἷα δὴ τὰ αἴτια ἐφ᾽ ἑκάστου, τοιαῦτα καὶ τὰ ἀποτελούμενα. οὐκοῦν ὅταν μὴ ὀρθῶς τι πράττωμεν,","st":"1.11"},{"sp":"N","t":"ἀπὸ ταύτης τῆς ἡμέρας οὐδὲν ἄλλο αἰτιασόμεθα ἢ τὸ δόγμα, ἀφ᾽ οὗ αὐτὸ ἐπράξαμεν, κἀκεῖνο ἐξαίρειν καὶ ἐκτέμνειν πειρασόμεθα μᾶλλον ἢ τὰ φύματα καὶ τὰ ἀποστήματα ἐκ τοῦ σώματος.","st":"1.11"},{"sp":"N","t":"ὡσαύτως δὲ καὶ τῶν ὀρθῶς πραττομένων ταὐτὸν τοῦτο αἴτιον ἀποφανοῦμεν.","st":"1.11"},{"sp":"N","t":"καὶ οὔτ᾽ οἰκέτην ἔτι αἰτιασόμεθα οὔτε γείτονα οὔτε γυναῖκα οὔτε τέκνα ὡς αἴτιά τινων κακῶν ἡμῖν γινόμενα πεπεισμένοι ὅτι, ἂν μὴ ἡμῖν δόξῃ τοιαῦτά τινα εἶναι, οὐ πράττομεν τὰ ἀκόλουθα: τοῦ δόξαι δὲ ἢ μὴ δόξαι, ἡμεῖς κύριοι καὶ οὐ τὰ ἐκτός.","st":"1.11"},{"sp":"N","t":"— οὕτως, ἔφη. — ἀπὸ τῆς σήμερον τοίνυν ἡμέρας οὐδὲν ἄλλο ἐπισκοπήσομεν οὐδ᾽ ἐξετάσομεν, ποῖόν τι ἐστὶν ἢ πῶς ἔχει, οὔτε τὸν ἀγρὸν οὔτε τὰ ἀνδράποδα οὔτε τοὺς ἵππους ἢ κύνας, ἀλλὰ τὰ δόγματα. — εὔχομαι, ἔφη.","st":"1.11"},{"sp":"N","t":"— ὁρᾷς οὖν, ὅτι σχολαστικόν σε δεῖ γενέσθαι, τοῦτο τὸ ζῷον οὗ πάντες καταγελῶσιν, εἴπερ ἄρα θέλεις ἐπίσκεψιν τῶν σαυτοῦ δογμάτων ποιεῖσθαι.","st":"1.11"},{"sp":"N","t":"τοῦτο δ᾽ ὅτι μιᾶς ὥρας ἢ ἡμέρας οὐκ ἔστιν, ἐπινοεῖς καὶ αὐτός. περὶ εὐαρεστήσεως. περὶ θεῶν οἱ μέν τινές εἰσιν οἱ λέγοντες μηδ᾽ εἶναι τὸ θεῖον, οἱ δ᾽ εἶναι μέν, ἀργὸν δὲ καὶ ἀμελὲς καὶ μὴ προνοεῖν μηδενός:","st":"1.11"},{"sp":"N","t":"τρίτοι δ᾽ οἱ καὶ εἶναι καὶ προνοεῖν, ἀλλὰ τῶν μεγάλων καὶ οὐρανίων, τῶν δὲ ἐπὶ γῆς μηδενός: τέταρτοι δ᾽ οἱ καὶ τῶν ἐπὶ γῆς καὶ τῶν ἀνθρωπίνων, εἰς κοινὸν δὲ μόνον καὶ οὐχὶ δὲ καὶ κατ᾽ ἰδίαν ἑκάστου:","st":"1.12"},{"sp":"N","t":"πέμπτοι δ᾽, ὧν ἦν καὶ Ὀδυσσεὺς καὶ Σωκράτης, οἱ λέγοντες ὅτι οὐδέ σε λήθω κινύμενος.","st":"1.12"},{"sp":"N","t":"πολὺ πρότερον οὖν ἀναγκαῖόν ἐστι περὶ ἑκάστου τούτων ἐπεσκέφθαι, πότερα ὑγιῶς ἢ οὐχ ὑγιῶς λεγόμενόν ἐστιν. εἰ γὰρ μὴ εἰσὶν θεοί, πῶς ἐστι τέλος ἕπεσθαι θεοῖς;","st":"1.12"},{"sp":"N","t":"εἰ δ᾽ εἰσὶν μέν, μηδενὸς δ᾽ ἐπιμελούμενοι, καὶ οὕτως πῶς ὑγιὲς ἔσται;","st":"1.12"},{"sp":"N","t":"ἀλλὰ δὴ καὶ ὄντων καὶ ἐπιμελομένων εἰ μηδεμία διάδοσις εἰς ἀνθρώπους ἐστὶν ἐξ αὐτῶν καὶ νὴ Δία γε καὶ εἰς ἐμέ, πῶς ἔτι καὶ οὕτως ὑγιές ἐστιν;","st":"1.12"},{"sp":"N","t":"πάντα οὖν ταῦτα ὁ καλὸς καὶ ἀγαθὸς ἐπεσκεμμένος τὴν αὑτοῦ γνώμην ὑποτέταχεν τῷ διοικοῦντι τὰ ὅλα καθάπερ οἱ ἀγαθοὶ πολῖται τῷ νόμῳ τῆς πόλεως.","st":"1.12"},{"sp":"N","t":"ὁ δὲ παιδευόμενος ταύτην ὀφείλει τὴν ἐπιβολὴν ἔχων ἐλθεῖν ἐπὶ τὸ παιδεύεσθαι ‘πῶς ἂν ἑποίμην ἐγὼ ἐν παντὶ τοῖς θεοῖς καὶ πῶς ἂν εὐαρεστοίην τῇ θείᾳ διοικήσει καὶ πῶς ἂν γενοίμην ἐλεύθερος;’","st":"1.12"},{"sp":"N","t":"ἐλεύθερος γάρ ἐστιν, ᾧ γίνεται πάντα κατὰ προαίρεσιν καὶ ὃν οὐδεὶς δύναται κωλῦσαι.","st":"1.12"},{"sp":"N","t":"τί οὖν; ἀπόνοιά ἐστιν ἡ ἐλευθερία; μὴ γένοιτο. μανία γὰρ καὶ ἐλευθερία εἰς ταὐτὸν οὐκ ἔρχεται.","st":"1.12"},{"sp":"N","t":"‘ἀλλ᾽ ἐγὼ θέλω πᾶν τὸ δοκοῦν μοι ἀποβαίνειν, κἂν ὁπωσοῦν δοκῇ.’","st":"1.12"},{"sp":"N","t":"μαινόμενος εἶ, παραφρονεῖς. οὐκ οἶδας, ὅτι καλόν τι ἐλευθερία ἐστὶ καὶ ἀξιόλογον; τὸ δ᾽ ὡς ἔτυχέν με βούλεσθαι τὰ δ᾽ ὡς ἔτυχεν δόξαντα γίνεσθαι, τοῦτο κινδυνεύει οὐ μόνον οὐκ εἶναι καλόν, ἀλλὰ καὶ πάντων αἴσχιστον εἶναι.","st":"1.12"},{"sp":"N","t":"πῶς γὰρ ἐπὶ γραμματικῶν ποιοῦμεν; βούλομαι γράφειν ὡς θέλω τὸ Δίωνος ὄνομα; οὔ: ἀλλὰ διδάσκομαι θέλειν, ὡς δεῖ γράφεσθαι. τί ἐπὶ μουσικῶν; ὡσαύτως.","st":"1.12"},{"sp":"N","t":"τί ἐν τῷ καθόλου, ὅπου τέχνη τις ἢ ἐπιστήμη ἐστίν; εἰ δὲ μή, οὐδενὸς ἦν ἄξιον τὸ ἐπίστασθαί τι, εἰ ταῖς ἑκάστων βουλήσεσι προσηρμόζετο.","st":"1.12"},{"sp":"N","t":"ἐνταῦθα οὖν μόνον ἐπὶ τοῦ μεγίστου καὶ κυριωτάτου, τῆς ἐλευθερίας, ὡς ἔτυχεν ἐφεῖταί μοι θέλειν; οὐδαμῶς, ἀλλὰ τὸ παιδεύεσθαι τοῦτ᾽ ἔστι μανθάνειν ἕκαστα οὕτω θέλειν ὡς γίνεται. πῶς δὲ γίνεται; ὡς διέταξεν αὐτὰ ὁ διατάσσων.","st":"1.12"},{"sp":"N","t":"διέταξε δὲ θέρος εἶναι καὶ χειμῶνα καὶ φορὰν καὶ ἀφορίαν καὶ ἀρετὴν καὶ κακίαν καὶ πάσας τὰς τοιαύτας ἐναντιότητας ὑπὲρ συμφωνίας τῶν ὅλων ἡμῶν θ᾽ ἑκάστῳ σῶμα καὶ μέρη τοῦ σώματος καὶ κτῆσιν καὶ κοινωνοὺς ἔδωκεν.","st":"1.12"},{"sp":"N","t":"ταύτης οὖν τῆς διατάξεως μεμνημένους ἔρχεσθαι δεῖ ἐπὶ τὸ παιδεύεσθαι, οὐχ ἵν᾽ ἀλλάξωμεν τὰς ὑποθέσεις （ οὔτε γὰρ δίδοται ἡμῖν οὔτ᾽ ἄμεινον ） , ἀλλ᾽ ἵνα οὕτως ἐχόντων τῶν περὶ ἡμᾶς ὡς ἔχει καὶ πέφυκεν αὐτοὶ τὴν γνώμην τὴν αὑτῶν συνηρμοσμένην τοῖς γινομένοις ἔχωμεν.","st":"1.12"},{"sp":"N","t":"τί γάρ; ἐνδέχεται φυγεῖν ἀνθρώπους; καὶ πῶς οἷόν τε; ἀλλὰ συνόντας αὐτοῖς ἐκείνους ἀλλάξαι; καὶ τίς ἡμῖν δίδωσιν;","st":"1.12"},{"sp":"N","t":"τί οὖν ἀπολείπεται ἢ τίς εὑρίσκεται μηχανὴ πρὸς τὴν χρῆσιν αὐτῶν; τοιαύτη, δι᾽ ἧς ἐκεῖνοι μὲν ποιήσουσι τὰ φαινόμενα αὐτοῖς, ἡμεῖς δ᾽ οὐδὲν ἧττον κατὰ φύσιν ἕξομεν.","st":"1.12"},{"sp":"N","t":"σὺ δ᾽ ἀταλαίπωρος εἶ καὶ δυσάρεστος κἂν μὲν μόνος ᾖς, ἐρημίαν καλεῖς τοῦτο, ἂν δὲ μετὰ ἀνθρώπων, ἐπιβούλους λέγεις καὶ λῃστάς, μέμφῃ δὲ καὶ γονεῖς τοὺς σεαυτοῦ καὶ τέκνα καὶ ἀδελφοὺς καὶ γείτονας.","st":"1.12"},{"sp":"N","t":"ἔδει δὲ μόνον μένοντα ἡσυχίαν καλεῖν αὐτὸ καὶ ἐλευθερίαν καὶ ὅμοιον τοῖς θεοῖς ἡγεῖσθαι αὑτόν, μετὰ πολλῶν δ᾽ ὄντα μὴ ὄχλον καλεῖν μηδὲ θόρυβον μηδ᾽ ἀηδίαν, ἀλλ᾽ ἑορτὴν καὶ πανήγυριν καὶ οὕτως πάντα εὐαρέστως δέχεσθαι. τίς οὖν ἡ κόλασις τοῖς οὐ προσδεχομένοις;","st":"1.12"},{"sp":"N","t":"τὸ οὕτως ἔχειν ὡς ἔχουσιν. δυσαρεστεῖ τις τῷ μόνος εἶναι; ἔστω ἐν ἐρημίᾳ. δυσαρεστεῖ τις τοῖς γονεῦσιν; ἔστω κακὸς υἱὸς καὶ πενθείτω. δυσαρεστεῖ τοῖς τέκνοις;","st":"1.12"},{"sp":"N","t":"ἔστω κακὸς πατήρ. ‘βάλε αὐτὸν εἰς φυλακήν.’ ποίαν φυλακήν; ὅπου νῦν ἐστιν. ἄκων γάρ ἐστιν: ὅπου δέ τις ἄκων ἐστίν, ἐκεῖνο φυλακὴ αὐτῷ ἐστιν. καθὸ καὶ Σωκράτης οὐκ ἦν ἐν φυλακῇ, ἑκὼν γὰρ ἦν.","st":"1.12"},{"sp":"N","t":"‘σκέλος οὖν μοι γενέσθαι πεπηρωμένον.’ ἀνδράποδον, εἶτα δι᾽ ἓν σκελύδριον τῷ κόσμῳ ἐγκαλεῖς; οὐκ ἐπιδώσεις αὐτὸ τοῖς ὅλοις; οὐκ ἀποστήσῃ; οὐ χαίρων παραχωρήσεις τῷ δεδωκότι;","st":"1.12"},{"sp":"N","t":"ἀγανακτήσεις δὲ καὶ δυσαρεστήσεις τοῖς ὑπὸ τοῦ Διὸς διατεταγμένοις, ἃ ἐκεῖνος μετὰ τῶν Μοιρῶν παρουσῶν καὶ ἐπικλωθουσῶν σου τὴν γένεσιν ὥρισεν καὶ διέταξεν;","st":"1.12"},{"sp":"N","t":"οὐκ οἶσθας, ἡλίκον μέρος πρὸς τὰ ὅλα; τοῦτο δὲ κατὰ τὸ σῶμα, ὡς κατά γε τὸν λόγον οὐδὲν χείρων τῶν θεῶν οὐδὲ μικρότερος: λόγου γὰρ μέγεθος οὐ μήκει οὐδ᾽ ὕψει κρίνεται, ἀλλὰ δόγμασιν.","st":"1.12"},{"sp":"N","t":"οὐ θέλεις οὖν, καθ᾽ ἃ ἴσος εἶ τοῖς θεοῖς, ἐκεῖ που τίθεσθαι τὸ ἀγαθόν;","st":"1.12"},{"sp":"N","t":"‘τάλας ἐγώ, τὸν πατέρα ἔχω τοιοῦτον καὶ τὴν μητέρα.’ τί οὖν; ἐδίδοτό σοι προελθόντι ἐκλέξασθαι καὶ εἰπεῖν ‘ὁ δεῖνα τῇ δεῖνι συνελθέτω τῇδε τῇ ὥρᾳ, ἵνα ἐγὼ γένωμαι;’","st":"1.12"},{"sp":"N","t":"οὐκ ἐδίδοτο. ἀλλ᾽ ἔδει προυποστῆναί σου τοὺς γονεῖς, εἶτα οὕτως γεννηθῆναι. ἐκ ποίων τινῶν;","st":"1.12"},{"sp":"N","t":"ἐκ τοιούτων, ὁποῖοι ἦσαν. τί οὖν; τοιούτων αὐτῶν ὄντων οὐδεμία σοι δίδοται μηχανή; εἶτ᾽ εἰ μὲν τὴν ὁρατικὴν δύναμιν ἠγνόεις πρὸς τί κέκτησαι, δυστυχὴς ἂν ἦς καὶ ἄθλιος, εἰ κατέμυες, προσαγόντων σοι τῶν χρωμάτων: ὅτι δὲ μεγαλοψυχίαν ἔχων καὶ γενναιότητα πρὸς ἕκαστα τούτων ἀγνοεῖς, οὐ δυστυχέστερος εἶ καὶ ἀθλιώτερος; προσάγεταί σοι τὰ κατάλληλα τῇ δυνάμει ἣν ἔχεις:","st":"1.12"},{"sp":"N","t":"σὺ δ᾽ αὐτὴν τότε μάλιστα ἀποστρέφεις, ὁπότε ἠνοιγμένην καὶ βλέπουσαν ἔχειν ἔδει.","st":"1.12"},{"sp":"N","t":"οὐ μᾶλλον εὐχαριστεῖς τοῖς θεοῖς, ὅτι σε ἐπάνω τούτων ἀφῆκαν ὅσα μηδ᾽ ἐποίησαν ἐπὶ σοί, μόνον δ᾽ ὑπεύθυνον ἀπέφηναν τῶν ἐπὶ σοί; γονέων ἕνεκα ἀνυπεύθυνον ἀφῆκαν:","st":"1.12"},{"sp":"N","t":"ἀδελφῶν ἕνεκα ἀφῆκαν, σώματος ἕνεκα ἀφῆκαν, κτήσεως, θανάτου, ζωῆς.","st":"1.12"},{"sp":"N","t":"τίνος οὖν ὑπεύθυνόν σε ἐποίησαν; τοῦ μόνου ὄντος ἐπὶ σοί, χρήσεως οἵας δεῖ φαντασιῶν.","st":"1.12"},{"sp":"N","t":"τί οὖν ἐπισπᾷς σεαυτῷ ταῦτα ὧν ἀνυπεύθυνος εἶ; τοῦτό ἐστιν ἑαυτῷ παρέχειν πράγματα. πῶς ἕκαστα ἔστιν ποιεῖν ἀρεστῶς θεοῖς. πυθομένου δέ τινος, πῶς ἔστιν ἐσθίειν ἀρεστῶς θεοῖς, Εἰ δικαίως ἔστιν, ἔφη, καὶ εὐγνωμόνως καὶ ἴσως ἐγκρατῶς καὶ κοσμίως, οὐκ ἔστι καὶ ἀρεστῶς τοῖς θεοῖς;","st":"1.12"},{"sp":"N","t":"ὅταν δὲ θερμὸν αἰτήσαντός σου μὴ ὑπακούσῃ ὁ παῖς ἢ ὑπακούσας χλιαρώτερον ἐνέγκῃ ἢ μηδ᾽ εὑρεθῇ ἐν τῇ οἰκίᾳ, τὸ μὴ χαλεπαίνειν μηδὲ ῥήγνυσθαι οὐκ ἔστιν ἀρεστὸν τοῖς θεοῖς;","st":"1.13"},{"sp":"N","t":"— πῶς οὖν τις ἀνάσχηται τῶν τοιούτων; — ἀνδράποδον, οὐκ ἀνέξῃ τοῦ ἀδελφοῦ τοῦ σαυτοῦ, ὃς ἔχει τὸν Δία πρόγονον, ὥσπερ υἱὸς ἐκ τῶν αὐτῶν σπερμάτων γέγονεν καὶ τῆς αὐτῆς ἄνωθεν καταβολῆς,","st":"1.13"},{"sp":"N","t":"ἀλλ᾽ εἰ ἔν τινι τοιαύτῃ χώρᾳ κατετάγης ὑπερεχούσῃ, εὐθὺς τύραννον καταστήσεις σεαυτόν; οὐ μεμνήσῃ τί εἶ καὶ τίνων ἄρχεις; ὅτι συγγενῶν, ὅτι ἀδελφῶν φύσει, ὅτι τοῦ Διὸς ἀπογόνων;","st":"1.13"},{"sp":"N","t":"— ἀλλ᾽ ὠνὴν αὐτῶν ἔχω, ἐκεῖνοι δ᾽ ἐμοῦ οὐκ ἔχουσιν. — ὁρᾷς ποῦ βλέπεις; ὅτι εἰς τὴν γῆν, ὅτι εἰς τὸ βάραθρον, ὅτι εἰς τοὺς ταλαιπώρους τούτους νόμους τοὺς τῶν νεκρῶν, εἰς δὲ τοὺς τῶν θεῶν οὐ βλέπεις; ὅτι πάντας ἐφορᾷ τὸ θεῖον. πυθομένου δέ τινος, πῶς ἄν τις πεισθείη, ὅτι ἕκαστον τῶν ὑπ᾽ αὐτοῦ πραττομένων ἐφορᾶται ὑπὸ τοῦ θεοῦ, Οὐ δοκεῖ σοι, ἔφη, ἡνῶσθαι τὰ πάντα;","st":"1.13"},{"sp":"N","t":"— δοκεῖ, ἔφη. — τί δέ; συμπαθεῖν τὰ ἐπίγεια τοῖς οὐρανίοις οὐ δοκεῖ σοι;","st":"1.14"},{"sp":"N","t":"— δοκεῖ, ἔφη. — πόθεν γὰρ οὕτω τεταγμένως καθάπερ ἐκ προστάγματος τοῦ θεοῦ, ὅταν ἐκεῖνος εἴπῃ τοῖς φυτοῖς ἀνθεῖν, ἀνθεῖ, ὅταν εἴπῃ βλαστάνειν, βλαστάνει, ὅταν ἐκφέρειν τὸν καρπόν, ἐκφέρει, ὅταν πεπαίνειν, πεπαίνει, ὅταν πάλιν ἀποβάλλειν καὶ φυλλορροεῖν καὶ αὐτὰ εἰς αὑτὰ συνειλούμενα ἐφ᾽ ἡσυχίας μένειν καὶ ἀναπαύεσθαι, μένει καὶ ἀναπαύεται;","st":"1.14"},{"sp":"N","t":"πόθεν δὲ πρὸς τὴν αὔξησιν καὶ μείωσιν τῆς σελήνης καὶ τὴν τοῦ ἡλίου πρόσοδον καὶ ἄφοδον τοσαύτη παραλλαγὴ καὶ ἐπὶ τὰ ἐναντία μεταβολὴ τῶν ἐπιγείων θεωρεῖται;","st":"1.14"},{"sp":"N","t":"ἀλλὰ τὰ φυτὰ μὲν καὶ τὰ ἡμέτερα σώματα οὕτως ἐνδέδεται τοῖς ὅλοις καὶ συμπέπονθεν, αἱ ψυχαὶ δ᾽ αἱ ἡμέτεραι οὐ πολὺ πλέον;","st":"1.14"},{"sp":"N","t":"ἀλλ᾽ αἱ ψυχαὶ μὲν οὕτως εἰσὶν ἐνδεδεμέναι καὶ συναφεῖς τῷ θεῷ ἅτε αὐτοῦ μόρια οὖσαι καὶ ἀποσπάσματα, οὐ παντὸς δ᾽ αὐτῶν κινήματος ἅτε οἰκείου καὶ συμφυοῦς ὁ θεὸς αἰσθάνεται;","st":"1.14"},{"sp":"N","t":"ἀλλὰ σὺ μὲν περὶ τῆς θείας διοικήσεως καὶ περὶ ἑκάστου τῶν θείων, ὁμοῦ δὲ καὶ περὶ τῶν ἀνθρωπίνων πραγμάτων ἐνθυμεῖσθαι δύνασαι καὶ ἅμα μὲν αἰσθητικῶς ἀπὸ μυρίων πραγμάτων κινεῖσθαι, ἅμα δὲ διανοητικῶς, ἅμα δὲ συγκαταθετικῶς, τοῖς δ᾽ ἀνανευστικῶς ἢ ἐφεκτικῶς,","st":"1.14"},{"sp":"N","t":"τύπους δὲ τοσούτους ἀφ᾽ οὕτω πολλῶν καὶ ποικίλων πραγμάτων ἐν τῇ σαυτοῦ ψυχῇ φυλάττεις καὶ ἀπ᾽ αὐτῶν κινούμενος εἰς ἐπινοίας ὁμοειδεῖς ἐμπίπτεις τοῖς πρώτως τετυπωκόσι τέχνας τ᾽ ἄλλην ἐπ᾽ ἄλλῃ καὶ μνήμας ἀπὸ μυρίων πραγμάτων διασῴζεις:","st":"1.14"},{"sp":"N","t":"ὁ δὲ θεὸς οὐχ οἷός τ᾽ ἐστὶ πάντα ἐφορᾶν καὶ πᾶσιν συμπαρεῖναι καὶ ἀπὸ πάντων τινὰ ἴσχειν διάδοσιν;","st":"1.14"},{"sp":"N","t":"ἀλλὰ φωτίζειν οἷός τ᾽ ἐστὶν ὁ ἥλιος τηλικοῦτον μέρος τοῦ παντός, ὀλίγον δὲ τὸ ἀφώτιστον ἀπολιπεῖν ὅσον οἷόν τ᾽ ἐπέχεσθαι ὑπὸ σκιᾶς, ἣν ἡ γῆ ποιεῖ: ὁ δὲ καὶ τὸν ἥλιον αὐτὸν πεποιηκὼς καὶ περιάγων μέρος ὄντ᾽ αὐτοῦ μικρὸν ὡς πρὸς τὸ ὅλον, οὗτος δ᾽ οὐ δύναται πάντων αἰσθάνεσθαι;","st":"1.14"},{"sp":"N","t":"ἀλλ᾽ ἐγώ, φησίν, οὐ δύναμαι πᾶσιν ἅμα τούτοις παρακολουθεῖν. — τοῦτο δέ σοι καὶ λέγει τις, ὅτι ἴσην ἔχεις δύναμιν τῷ Διί;","st":"1.14"},{"sp":"N","t":"ἀλλ᾽ οὖν οὐδὲν ἧττον καὶ ἐπίτροπον ἑκάστῳ παρέστησεν τὸν ἑκάστου δαίμονα καὶ παρέδωκεν φυλάσσειν αὐτὸν αὐτῷ καὶ τοῦτον ἀκοίμητον καὶ ἀπαραλόγιστον.","st":"1.14"},{"sp":"N","t":"τίνι γὰρ ἄλλῳ κρείττονι καὶ ἐπιμελεστέρῳ φύλακι παρέδωκεν ἡμῶν ἕκαστον; ὥσθ᾽, ὅταν κλείσητε τὰς θύρας καὶ σκότος ἔνδον ποιήσητε, μέμνησθε μηδέποτε λέγειν ὅτι μόνοι ἐστέ:","st":"1.14"},{"sp":"N","t":"οὐ γὰρ ἐστέ, ἀλλ᾽ ὁ θεὸς ἔνδον ἐστὶ καὶ ὁ ὑμέτερος δαίμων ἐστίν. καὶ τίς τούτοις χρεία φωτὸς εἰς τὸ βλέπειν τί ποιεῖτε;","st":"1.14"},{"sp":"N","t":"τούτῳ τῷ θεῷ ἔδει καὶ ὑμᾶς ὀμνύειν ὅρκον, οἷον οἱ στρατιῶται τῷ Καίσαρι. ἀλλ᾽ ἐκεῖνοι μὲν τὴν μισθοφορίαν λαμβάνοντες ὀμνύουσιν πάντων προτιμήσειν τὴν τοῦ Καίσαρος σωτηρίαν, ὑμεῖς δὲ † δε τοσούτων καὶ τηλικούτων ἠξιωμένοι οὐκ ὀμόσετε ἢ ὀμόσαντες οὐκ ἐμμενεῖτε;","st":"1.14"},{"sp":"N","t":"καὶ τί ὀμόσετε; μὴ ἀπειθήσειν μηδέποτε μηδ᾽ ἐγκαλέσειν μηδὲ μέμψεσθαί τινι τῶν ὑπ᾽ ἐκείνου δεδομένων μηδ᾽ ἄκοντες ποιήσειν τι ἢ πείσεσθαι τῶν ἀναγκαίων.","st":"1.14"},{"sp":"N","t":"ὅμοιός γε ὅρκος οὗτος ἐκείνῳ; ἐκεῖ μὲν ὀμνύουσιν αὐτοῦ μὴ προτιμήσειν ἕτερον, ἐνταῦθα δ᾽ αὑτοὺς ἁπάντων. τί ἐπαγγέλλεται φιλοσοφία. συμβουλευομένου τινός, πῶς τὸν ἀδελφὸν πείσῃ μηκέτι χαλεπῶς αὐτῷ ἔχειν,","st":"1.14"},{"sp":"N","t":"οὐκ ἐπαγγέλλεται, ἔφη, φιλοσοφία τῶν ἐκτός τι περιποιήσειν τῷ ἀνθρώπῳ: εἰ δὲ μή, ἔξω τι τῆς ἰδίας ὕλης ἀναδέξεται. ὡς γὰρ τέκτονος ὕλη τὰ ξύλα, ἀνδριαντοποιοῦ ὁ χαλκός, οὕτως τῆς περὶ βίον τέχνης ὕλη ὁ βίος αὐτοῦ ἑκάστου.","st":"1.15"},{"sp":"N","t":"— τί οὖν ὁ τοῦ ἀδελφοῦ; — πάλιν τῆς αὐτοῦ ἐκείνου τέχνης ἐστίν, πρὸς δὲ τὴν σὴν τῶν ἐκτός ἐστιν, ὅμοιον ἀγρῷ, ὅμοιον ὑγείᾳ, ὅμοιον εὐδοξίᾳ. τούτων δ᾽ οὐδὲν ἐπαγγέλλεται: φιλοσοφία.","st":"1.15"},{"sp":"N","t":"‘ἐν πάσῃ περιστάσει τηρήσω τὸ ἡγεμονικὸν κατὰ φύσιν ἔχον.’ — τὸ τίνος;—’τὸ ἐκείνου, ἐν ᾧ εἰμί.’","st":"1.15"},{"sp":"N","t":"— πῶς οὖν ἐκεῖνός μοι μὴ ὀργίζηται;—’φέρε μοι ἐκεῖνον κἀκείνῳ ἐρῶ, σοὶ δὲ περὶ τῆς ἐκείνου ὀργῆς οὐδὲν ἔχω λέγειν.’","st":"1.15"},{"sp":"N","t":"εἰπόντος δὲ τοῦ συμβουλευομένου ὅτι Τοῦτο ζητῶ, πῶς ἂν ἐκείνου καὶ μὴ διαλλασσομένου κατὰ φύσιν ἔχοιμι,","st":"1.15"},{"sp":"N","t":"οὐδέν, ἔφη, τῶν μεγάλων ἄφνω γίνεται, ὅπου γε οὐδ᾽ ὁ βότρυς οὐδὲ σῦκον. ἄν μοι νῦν λέγῃς ὅτι ‘θέλω σῦκον,’ ἀποκρινοῦμαί σοι ὅτι ‘χρόνου δεῖ.’ ἄφες ἀνθήσῃ πρῶτον, εἶτα προβάλῃ τὸν καρπόν, εἶτα πεπανθῇ.","st":"1.15"},{"sp":"N","t":"εἶτα συκῆς μὲν καρπὸς ἄφνω καὶ μιᾷ ὥρᾳ οὐ τελειοῦται, γνώμης δ᾽ ἀνθρώπου καρπὸν θέλεις οὕτως δι᾽ ὀλίγου καὶ εὐκόλως κτήσασθαι; μηδ᾽ ἂν ἐγώ σοι λέγω, προσδόκα. περὶ προνοίας. μὴ θαυμάζετ᾽ εἰ τοῖς μὲν ἄλλοις ζῴοις τὰ πρὸς τὸ σῶμα ἕτοιμα γέγονεν, οὐ μόνον τροφαὶ καὶ πόμα, ἀλλὰ καὶ κοίτη καὶ τὸ μὴ δεῖσθαι ὑποδημάτων, μὴ ὑποστρωμάτων, μὴ ἐσθῆτος, ἡμεῖς δὲ πάντων τούτων προσδεόμεθα.","st":"1.15"},{"sp":"N","t":"τὰ γὰρ οὐκ αὐτῶν ἕνεκα, ἀλλὰ πρὸς ὑπηρεσίαν γεγονότα οὐκ ἐλυσιτέλει προσδεόμενα ἄλλων πεποιηκέναι.","st":"1.16"},{"sp":"N","t":"ἐπεὶ ὅρα οἷον ἦν ἡμᾶς φροντίζειν μὴ περὶ αὑτῶν μόνον ἀλλὰ καὶ περὶ τῶν προβάτων καὶ τῶν ὄνων, πῶς ἐνδύσηται καὶ πῶς ὑποδήσηται, πῶς φάγῃ, πῶς πίῃ.","st":"1.16"},{"sp":"N","t":"ἀλλ᾽ ὥσπερ οἱ στρατιῶται ἕτοιμοί εἰσι τῷ στρατηγῷ ὑποδεδεμένοι ἐνδεδυμένοι ὡπλισμένοι, εἰ δ᾽ ἔδει περιερχόμενον τὸν χιλίαρχον ὑποδεῖν ἢ ἐνδύειν τοὺς χιλίους, δεινὸν ἂν ἦν, οὕτω καὶ ἡ φύσις πεποίηκε τὰ πρὸς ὑπηρεσίαν γεγονότα ἕτοιμα παρεσκευασμένα μηδεμιᾶς ἐπιμελείας ἔτι προσδεόμενα.","st":"1.16"},{"sp":"N","t":"οὕτως ἓν παιδίον μικρὸν καὶ ῥάβδῳ ἐλαύνει τὰ πρόβατα.","st":"1.16"},{"sp":"N","t":"νῦν δ᾽ ἡμεῖς ἀφέντες ἐπὶ τούτοις εὐχαριστεῖν, ὅτι μὴ καὶ αὐτῶν τὴν ἴσην ἐπιμέλειαν ἐπιμελούμεθα, ἐφ᾽ αὑτοῖς ἐγκαλοῦμεν τῷ θεῷ.","st":"1.16"},{"sp":"N","t":"καίτοι νὴ τὸν Δία καὶ τοὺς θεοὺς ἓν τῶν γεγονότων ἀπήρκει πρὸς τὸ αἰσθέσθαι τῆς προνοίας τῷ γε αἰδήμονι καὶ εὐχαρίστῳ.","st":"1.16"},{"sp":"N","t":"καὶ μή μοι νῦν τὰ μεγάλα: αὐτὸ τοῦτο τὸ ἐκ πτόας γάλα γεννᾶσθαι καὶ ἐκ γάλακτος τυρὸν καὶ ἐκ δέρματος ἔρια τίς ἐστιν ὁ πεποιηκὼς ταῦτα ἢ ἐπινενοηκώς; ‘οὐδὲ εἷς’ φησίν. ὦ μεγάλης ἀναισθησίας καὶ ἀναισχυντίας.","st":"1.16"},{"sp":"N","t":"ἄγε ἀφῶμεν τὰ ἔργα τῆς φύσεως, τὰ πάρεργα αὐτῆς θεασώμεθα.","st":"1.16"},{"sp":"N","t":"μή τι ἀχρηστότερον τριχῶν τῶν ἐπὶ γενείου; τί οὖν; οὐ συνεχρήσατο καὶ ταύταις ὡς μάλιστα πρεπόντως ἐδύνατο; οὐ διέκρινεν δι᾽ αὐτῶν τὸ ἄρρεν καὶ τὸ θῆλυ;","st":"1.16"},{"sp":"N","t":"οὐκ εὐθὺς μακρόθεν κέκραγεν ἡμῶν ἑκάστου ἡ φύσις ‘ἀνήρ εἰμι: οὕτω μοι προσέρχου, οὕτω μοι λάλει, ἄλλο μηδὲν ζήτει: ἰδοὺ τὰ σύμβολα;’","st":"1.16"},{"sp":"N","t":"πάλιν ἐπὶ τῶν γυναικῶν ὥσπερ ἐν φωνῇ τι ἐγκατέμιξεν ἁπαλώτερον, οὕτως καὶ τὰς τρίχας ἀφεῖλεν. οὔ: ἀλλ᾽ ἀδιάκριτον ἔδει τὸ ζῷον ἀπολειφθῆναι καὶ κηρύσσειν ἕκαστον ἡμῶν ὅτι","st":"1.16"},{"sp":"N","t":"‘ἀνήρ εἰμι.’ πῶς δὲ καλὸν τὸ σύμβολον καὶ εὐπρεπὲς καὶ σεμνόν, πόσῳ κάλλιον τοῦ τῶν ἀλεκτρυόνων λόφου, πόσῳ μεγαλοπρεπέστερον τῆς χαίτης τῶν λεόντων.","st":"1.16"},{"sp":"N","t":"διὰ τοῦτο ἔδει σῴζειν τὰ σύμβολα τοῦ θεοῦ, ἔδει αὐτὰ μὴ καταπροίεσθαι, μὴ συγχεῖν ὅσον ἐφ᾽ ἑαυτοῖς τὰ γένη τὰ διῃρημένα.","st":"1.16"},{"sp":"N","t":"ταῦτα μόνα ἐστὶν ἔργα ἐφ᾽ ἡμῶν τῆς προνοίας; καὶ τίς ἐξαρκεῖ λόγος ὁμοίως αὐτὰ ἐπαινέσαι ἢ παραστῆσαι; εἰ γὰρ νοῦν εἴχομεν, ἄλλο τι ἔδει ἡμᾶς ποιεῖν καὶ κοινῇ καὶ ἰδίᾳ ἢ ὑμνεῖν τὸ θεῖον καὶ εὐφημεῖν καὶ ἐπεξέρχεσθαι τὰς χάριτας;","st":"1.16"},{"sp":"N","t":"οὐκ ἔδει καὶ σκάπτοντας καὶ ἀροῦντας καὶ ἐσθίοντας ᾁδειν τὸν ὕμνον τὸν εἰς τὸν θεόν; ‘μέγας ὁ θεὸς, ὅτι ἡμῖν παρέσχεν ὄργανα ταῦτα δι᾽ ὧν τὴν γῆν ἐργασόμεθα:","st":"1.16"},{"sp":"N","t":"μέγας ὁ θεός, ὅτι χεῖρας δέδωκεν, ὅτι κατάποσιν, ὅτι κοιλίαν, ὅτι αὔξεσθαι λεληθότως, ὅτι καθεύδοντας ἀναπνεῖν.’","st":"1.16"},{"sp":"N","t":"ταῦτα ἐφ᾽ ἑκάστου ἐφυμνεῖν ἔδει καὶ τὸν μέγιστον καὶ θειότατον ὕμνον ἐφυμνεῖν, ὅτι τὴν δύναμιν ἔδωκεν τὴν παρακολουθητικὴν τούτοις καὶ ὁδῷ χρηστικήν.","st":"1.16"},{"sp":"N","t":"τί οὖν; ἐπεὶ οἱ πολλοὶ ἀποτετύφλωσθε, οὐκ ἔδει τινὰ εἶναι τὸν ταύτην ἐκπληροῦντα τὴν χώραν καὶ ὑπὲρ πάντων ᾁδοντα τὸν ὕμνον τὸν εἰς τὸν θεόν;","st":"1.16"},{"sp":"N","t":"τί γὰρ ἄλλο δύναμαι γέρων χωλὸς εἰ μὴ ὑμνεῖν τὸν θεόν; εἰ γοῦν ἀηδὼν ἤμην, ἐποίουν τὰ τῆς ἀηδόνος, εἰ κύκνος, τὰ τοῦ κύκνου.","st":"1.16"},{"sp":"N","t":"νῦν δὲ λογικός εἰμι: ὑμνεῖν με δεῖ τὸν θεόν. τοῦτό μου τὸ ἔργον ἐστίν, ποιῶ αὐτὸ οὐδ᾽ ἐγκαταλείψω τὴν τάξιν ταύτην, ἐφ᾽ ὅσον ἂν διδῶται, καὶ ὑμᾶς ἐπὶ τὴν αὐτὴν ταύτην ᾠδὴν παρακαλῶ. ὅτι ἀναγκαῖα τὰ λογικά. ἐπειδὴ λόγος ἐστὶν ὁ διαρθρῶν καὶ ἐξεργαζόμενος τὰ λοιπά, ἔδει δ᾽ αὐτὸν μὴ ἀδιάρθρωτον εἶναι, ὑπὸ τίνος διαρθρωθῇ;","st":"1.16"},{"sp":"N","t":"δῆλον γὰρ ὅτι ἢ ὑφ᾽ αὑτοῦ ἢ ὑπ᾽ ἄλλου. ἤ τοι λόγος ἐστὶν ἐκεῖνος ἢ ἄλλο τι κρεῖσσον ἔσται τοῦ λόγου, ὅπερ ἀδύνατον.","st":"1.17"},{"sp":"N","t":"εἰ λόγος, ἐκεῖνον πάλιν τίς διαρθρώσει; εἰ γὰρ αὐτὸς ἑαυτόν, δύναται καὶ οὗτος. εἰ ἄλλου δεησόμεθα, ἄπειρον ἔσται τοῦτο καὶ ἀκατάληκτον.","st":"1.17"},{"sp":"N","t":"‘εἰναί, ἀλλ᾽ ἐπείγει μᾶλλον θεραπεύειν’ καὶ τὰ ὅμοια. θέλεις οὖν περὶ ἐκείνων ἀκούειν; ἄκουε.","st":"1.17"},{"sp":"N","t":"ἀλλ᾽ ἄν μοι λέγῃς ὅτι ‘οὐκ οἶδα πότερον ἀληθῶς ἢ ψευδῶς διαλέγῃ,’ κἄν τι κατ᾽ ἀμφίβολον φωνὴν εἴπω καὶ λέγῃς μοι ‘διάστιξον,’ οὐκ ἔτι ἀνέξομαί σου, ἀλλ᾽ ἐρῶ σοι:","st":"1.17"},{"sp":"N","t":"‘ἀλλ᾽ ἐπείγει μᾶλλον.’ διὰ τοῦτο γὰρ οἶμαι προστάσσουσιν τὰ λογικά, καθάπερ τῆς μετρήσεως τοῦ σίτου προτάσσομεν τὴν τοῦ μέτρου ἐπίσκεψιν.","st":"1.17"},{"sp":"N","t":"ἂν δὲ μὴ διαλάβωμεν πρῶτον τί ἐστι μόδιος μηδὲ διαλάβωμεν πρῶτον τί ἐστι ζυγός, πῶς ἔτι μετρῆσαί τι ἢ στῆσαι δυνησόμεθα;","st":"1.17"},{"sp":"N","t":"ἐνταῦθα οὖν τὸ τῶν ἄλλων κριτήριον καὶ δι᾽ οὗ τἆλλα καταμανθάνεται μὴ καταμεμαθηκότες μηδ᾽ ἠκριβωκότες δυνησόμεθά τι τῶν ἄλλων ἀκριβῶσαι καὶ καταμαθεῖν;","st":"1.17"},{"sp":"N","t":"καὶ πῶς οἷόν τε; ‘ναί: ἀλλ᾽ ὁ μόδιος ξύλον ἐστὶ καὶ ἄκαρπον.’","st":"1.17"},{"sp":"N","t":"ἀλλὰ μετρητικὸν σίτου. ‘καὶ τὰ λογικὰ ἄκαρπά ἐστι.’ καὶ περὶ τούτου μὲν ὀψόμεθα. εἰ δ᾽ οὖν καὶ τοῦτο δοίη τις, ἐκεῖνο ἀπαρκεῖ ὅτι τῶν ἄλλων ἐστὶ διακριτικὰ καὶ ἐπισκεπτικὰ καὶ ὡς ἄν τις εἴποι μετρητικὰ καὶ στατικά.","st":"1.17"},{"sp":"N","t":"τίς λέγει ταῦτα; μόνος Χρύσιππος καὶ Ζήνων καὶ Κλεάνθης;","st":"1.17"},{"sp":"N","t":"Ἀντισθένης δ᾽ οὐ λέγει; καὶ τίς ἐστιν ὁ γεγραφὼς ὅτι ‘ἀρχὴ παιδεύσεως ἡ τῶν ὀνομάτων ἐπίσκεψις;’ Σωκράτης δ᾽ οὐ λέγει; καὶ περὶ τίνος γράφει Ξενοφῶν, ὅτι ἤρχετο ἀπὸ τῆς τῶν ὀνομάτων ἐπισκέψεως, τί σημαίνει ἕκαστον;","st":"1.17"},{"sp":"N","t":"ἆρ᾽ οὖν τοῦτό ἐστι τὸ μέγα καὶ τὸ θαυμαστὸν νοῆσαι Χρύσιππον ἢ ἐξηγήσασθαι; καὶ τίς λέγει τοῦτο; τί οὖν τὸ θαυμαστόν ἐστιν;","st":"1.17"},{"sp":"N","t":"νοῆσαι τὸ βούλημα τῆς φύσεως. τί οὖν; αὐτὸς διὰ σεαυτοῦ παρακολουθεῖς; καὶ τίνος ἔτι χρείαν ἔχεις; εἰ γὰρ ἀληθές ἐστι τὸ πάντας ἄκοντας ἁμαρτάνειν, σὺ δὲ καταμεμάθηκας τὴν ἀλήθειαν, ἀνάγκη σε ἤδη κατορθοῦν.","st":"1.17"},{"sp":"N","t":"ἀλλὰ νὴ Δία οὐ παρακολουθῶ τῷ βουλήματι τῆς φύσεως. τίς οὖν ἐξηγεῖται αὐτό; λέγουσιν ὅτι Χρύσιππος.","st":"1.17"},{"sp":"N","t":"ἔρχομαι καὶ ἐπιζητῶ τί λέγει οὗτος ὁ ἐξηγητὴς τῆς φύσεως. ἄρχομαι μὴ νοεῖν τί λέγει, ζητῶ τὸν ἐξηγούμενον. ‘ἴδε ἐπίσκεψαι, πῶς τοῦτο λέγεται, καθάπερ εἰ Ῥωμαϊστί.’","st":"1.17"},{"sp":"N","t":"ποία οὖν ἐνθάδ᾽ ὀφρὺς τοῦ ἐξηγουμένου; οὐδ᾽ αὐτοῦ Χρυσίππου δικαίως, εἰ μόνον ἐξηγεῖται τὸ βούλημα τῆς φύσεως, αὐτὸς δ᾽ οὐκ ἀκολουθεῖ: πόσῳ πλέον τοῦ ἐκεῖνον ἐξηγουμένου;","st":"1.17"},{"sp":"N","t":"οὐδὲ γὰρ Χρυσίππου χρείαν ἔχομεν δι᾽ αὐτόν, ἀλλ᾽ ἵνα παρακολουθήσωμεν τῇ φύσει. οὐδὲ γὰρ τοῦ θύτου δι᾽ αὐτόν, ἀλλ᾽ ὅτι δι᾽ ἐκείνου κατανοήσειν οἰόμεθα τὰ μέλλοντα καὶ σημαινόμενα ὑπὸ τῶν θεῶν, οὐδὲ τῶν σπλάγχνων δι᾽ αὐτά,","st":"1.17"},{"sp":"N","t":"ἀλλ᾽ ὅτι δι᾽ ἐκείνων σημαίνεται, οὐδὲ τὸν κόρακα θαυμάζομεν ἢ τὴν κορώνην, ἀλλὰ τὸν θεὸν σημαίνοντα διὰ τούτων.","st":"1.17"},{"sp":"N","t":"ἔρχομαι τοίνυν ἐπὶ τὸν ἐξηγητὴν τοῦτον καὶ θύτην καὶ λέγω ὅτι ‘ἐπίσκεψαί μοι τὰ σπλάγχνα, τί μοι σημαίνεται.’","st":"1.17"},{"sp":"N","t":"λαβὼν καὶ ἀναπτύξας ἐκεῖνος ἐξηγεῖται ὅτι ‘ἄνθρωπε, προαίρεσιν ἔχεις ἀκώλυτον φύσει καὶ ἀνανάγκαστον. τοῦτο ἐνταῦθα ἐν τοῖς σπλάγχνοις γέγραπται.","st":"1.17"},{"sp":"N","t":"δείξω σοι αὐτὸ πρῶτον ἐπὶ τοῦ συγκαταθετικοῦ τόπου. μή τίς σε κωλῦσαι δύναται ἐπινεῦσαι ἀληθεῖ; οὐδὲ εἷς. μή τίς σε ἀναγκάσαι δύναται παραδέξασθαι τὸ ψεῦδος;","st":"1.17"},{"sp":"N","t":"οὐδὲ εἷς. ὁρᾷς ὅτι ἐν τούτῳ τῷ τόπῳ τὸ προαιρετικὸν ἔχεις ἀκώλυτον ἀνανάγκαστον ἀπαραπόδιστον;","st":"1.17"},{"sp":"N","t":"ἄγε ἐπὶ δὲ τοῦ ὀρεκτικοῦ καὶ ὁρμητικοῦ ἄλλως ἔχει; καὶ τίς ὁρμὴν νικῆσαι δύναται ἢ ἄλλη ὁρμή; τίς δ᾽ ὄρεξιν καὶ ἔκκλισιν ἢ ἄλλη ὄρεξις καὶ ἔκκλισις;’","st":"1.17"},{"sp":"N","t":"‘ ἄν μοι,’ φησί, ‘προσάγῃ θανάτου φόβον, ἀναγκάζει με.’ ‘οὐ τὸ προσαγόμενον, ἀλλ᾽ ὅτι δοκεῖ σοι κρεῖττον εἶναι ποιῆσαί τι τούτων ἢ ἀποθανεῖν.","st":"1.17"},{"sp":"N","t":"πάλιν οὖν τὸ σὸν δόγμα σε ἠνάγκασεν, τοῦτ᾽ ἔστι προαίρεσιν προαίρεσις.","st":"1.17"},{"sp":"N","t":"εἰ γὰρ τὸ ἴδιον μέρος, ὃ ἡμῖν ἔδωκεν ἀποσπάσας ὁ θεός, ὑπ᾽ αὐτοῦ ἢ ὑπ᾽ ἄλλου τινὸς κωλυτὸν ἢ ἀναγκαστὸν κατεσκευάκει, οὐκέτι ἂν ἦν θεὸς οὐδ᾽ ἐπεμελεῖτο ἡμῶν ὃν δεῖ τρόπον.","st":"1.17"},{"sp":"N","t":"ταῦτα εὑρίσκω,’ φησίν, ‘ἐν τοῖς ἱεροῖς. ταῦτά σοι σημαίνεται. ἐὰν θέλῃς, ἐλεύθερος εἶ: ἐὰν θέλῃς, μέμψῃ οὐδένα, ἐγκαλέσεις οὐδενί, πάντα κατὰ γνώμην ἔσται ἅμα τὴν σὴν καὶ τὴν τοῦ θεοῦ.’","st":"1.17"},{"sp":"N","t":"διὰ ταύτην τὴν μαντείαν ἔρχομαι ἐπὶ τὸν θύτην τοῦτον καὶ τὸν φιλόσοφον, οὐκ αὐτὸν θαυμάσας ἕνεκά γε τῆς ἐξηγήσεως, ἀλλὰ ἐκεῖνα ἃ ἐξηγεῖται. ὅτι οὐ δεῖ χαλεπαίνειν τοῖς ἁμαρτανομένοις. εἰ ἀληθές ἐστι τὸ ὑπὸ τῶν φιλοσόφων λεγόμενον ὅτι πᾶσιν ἀνθρώποις μία ἀρχὴ καθάπερ τοῦ συγκαταθέσθαι τὸ παθεῖν ὅτι ὑπάρχει καὶ τοῦ ἀνανεῦσαι τὸ παθεῖν ὅτι οὐχ ὑπάρχει καὶ νὴ Δία τοῦ ἐπισχεῖν τὸ παθεῖν ὅτι ἄδηλόν ἐστιν, οὕτως καὶ τοῦ ὁρμῆσαι ἐπί","st":"1.17"},{"sp":"N","t":"τι τὸ παθεῖν ὅτι ἐμοὶ συμφέρει, ἀμήχανον δ᾽ ἄλλο μὲν κρίνειν τὸ συμφέρον, ἄλλου δ᾽ ὀρέγεσθαι καὶ ἄλλο μὲν κρίνειν καθῆκον, ἐπ᾽ ἄλλο δὲ ὁρμᾶν, τί ἔτι τοῖς πολλοῖς χαλεπαίνομεν;","st":"1.18"},{"sp":"N","t":"— κλέπται, φησίν, εἰσὶ καὶ λωποδύται. — τί ἐστι τὸ κλέπται καὶ λωποδύται; πεπλάνηνται περὶ ἀγαθῶν καὶ κακῶν. χαλεπαίνειν οὖν δεῖ αὐτοῖς ἢ ἐλεεῖν αὐτούς;","st":"1.18"},{"sp":"N","t":"ἀλλὰ δεῖξον τὴν πλάνην καὶ ὄψει πῶς ἀφίστανται τῶν ἁμαρτημάτων. ἂν δὲ μὴ βλέπωσιν, οὐδὲν ἔχουσιν ἀνώτερον τοῦ δοκοῦντος αὐτοῖς.","st":"1.18"},{"sp":"N","t":"τοῦτον οὖν τὸν λῃστὴν καὶ τοῦτον τὸν μοιχὸν οὐκ ἔδει ἀπολωλέναι;","st":"1.18"},{"sp":"N","t":"— μηδαμῶς, ἀλλ᾽ ἐκεῖνο μᾶλλον ‘τοῦτον τὸν πεπλανημένον καὶ ἐξηπατημένον περὶ τῶν μεγίστων καὶ ἀποτετυφλωμένον οὐ τὴν ὄψιν τὴν διακριτικὴν τῶν λευκῶν καὶ μελάνων, ἀλλὰ τὴν γνώμην τὴν διακριτικὴν τῶν ἀγαθῶν καὶ τῶν κακῶν μὴ ἀπολλύναι;’ κἂν οὕτως λέγῃς,","st":"1.18"},{"sp":"N","t":"γνώσῃ πῶς ἀπάνθρωπόν ἐστιν ὃ λέγεις καὶ ὅτι ἐκείνῳ ὅμοιον ‘τοῦτον οὖν τὸν τυφλὸν μὴ ἀπολλύναι καὶ τὸν κωφόν;’","st":"1.18"},{"sp":"N","t":"εἰ γὰρ μεγίστη βλάβη ἡ τῶν μεγίστων ἀπώλειά ἐστιν, μέγιστον δ᾽ ἐν ἑκάστῳ προαίρεσις οἵα δεῖ καὶ τούτου στέρεταί τις, τί ἔτι χαλεπαίνεις αὐτῷ;","st":"1.18"},{"sp":"N","t":"ἄνθρωπε, εἰ σὲ δεῖ παρὰ φύσιν ἐπὶ τοῖς ἀλλοτρίοις κακοῖς διατίθεσθαι, ἐλέει αὐτὸν μᾶλλον ἢ μίσει: ἄφες τοῦτο τὸ προσκοπτικὸν καὶ μισητικόν:","st":"1.18"},{"sp":"N","t":"μὴ ἐ̣ ... π̣ῃς τὰς φωνὰς ταύτας ἃς οἱ πολλοὶ τῶν φ ... των ‘τούτους οὖν τοὺς καταράτους καὶ μιαροὺς ... ‘ ἔστω: σὺ πῶς ποτ᾽ ἀπεσοφώθης ἄφνω ... ν̣ .","st":"1.18"},{"sp":"N","t":"ἀ̣λ̣λ̣ω̣ς̣ χαλεπὸς εἶ. διὰ τί οὖν χαλεπαίνομεν; ὅτι τὰς ὕλας θαυμάζομεν, ὧν ἡμᾶς ἀφαιροῦνται. ἐπεί τοι μὴ θαύμαζέ σου τὰ ἱμάτια καὶ τῷ κλέπτῃ οὐ χαλεπαίνεις: μὴ θαύμαζε τὸ κάλλος τῆς γυναικὸς καὶ τῷ μοιχῷ οὐ χαλεπαίνεις.","st":"1.18"},{"sp":"N","t":"γνῶθι ὅτι κλέπτης καὶ μοιχὸς ἐν τοῖς σοῖς τόπον οὐκ ἔχει, ἐν δὲ τοῖς ἀλλοτρίοις καὶ τοῖς οὐκ ἐπὶ σοί. ταῦτα ἂν ἀφῇς καὶ παρὰ μηδὲν ἡγήσῃ, τίνι ἔτι χαλεπαίνεις; μέχρι δ᾽ ἂν ταῦτα θαυμάζῃς, σεαυτῷ χαλέπαινε μᾶλλον ἢ ἐκείνοις. σκόπει γάρ:","st":"1.18"},{"sp":"N","t":"ἔχεις καλὰ ἱμάτια, ὁ γείτων σου οὐκ ἔχει: θυρίδα ἔχεις, θέλεις αὐτὰ ψῦξαι. οὐκ οἶδεν ἐκεῖνος τί τὸ ἀγαθόν ἐστι τοῦ ἀνθρώπου, ἀλλὰ φαντάζεται ὅτι τὸ ἔχειν καλὰ ἱμάτια, τοῦτο ὃ καὶ σὺ φαντάζῃ.","st":"1.18"},{"sp":"N","t":"εἶτα μὴ ἔλθῃ καὶ ἄρῃ αὐτά; ἀλλὰ σὺ πλακοῦντα δεικνύων ἀνθρώποις λίχνοις καὶ μόνος αὐτὸν καταπίνων οὐ θέλεις ἵνα αὐτὸν ἁρπάσωσι; μὴ ἐρέθιζε αὐτούς, θυρίδα μὴ ἔχε, μὴ ψῦχέ σου τὰ ἱμάτια.","st":"1.18"},{"sp":"N","t":"κἀγὼ πρῴην σιδηροῦν λύχνον ἔχων παρὰ τοῖς θεοῖς ἀκούσας ψόφον τῆς θυρίδος κατέδραμον. εὗρον ἡρπασμένον τὸν λύχνον. ἐπελογισάμην, ὅτι ἔπαθέν τι ὁ ἄρας οὐκ ἀπίθανον. τί οὖν; αὔριον, φημί, ὀστράκινον εὑρήσεις.","st":"1.18"},{"sp":"N","t":"ἐκεῖνα γὰρ ἀπολλύει, ἃ ἔχει. ‘ἀπώλεσά μου τὸ ἱμάτιον.’ εἶχες γὰρ ἱμάτιον. ‘ἀλγῶ τὴν κεφαλήν.’ μή τι κέρατα ἀλγεῖς; τί οὖν ἀγανακτεῖς; τούτων γὰρ αἱ ἀπώλειαι, τούτων οἱ πόνοι, ὧν καὶ αἱ κτήσεις.","st":"1.18"},{"sp":"N","t":"‘ἀλλ᾽ ὁ τύραννος δήσει.’ τί; τὸ σκέλος. ‘ἀλλ᾽ ἀφελεῖ.’ τί; τὸν τράχηλον. τί οὖν οὐ δήσει οὐδ᾽ ἀφελεῖ; τὴν προαίρεσιν. διὰ τοῦτο παρήγγελλον οἱ παλαιοὶ τὸ Γνῶθι σαυτόν.","st":"1.18"},{"sp":"N","t":"τί οὖν; ἔδει νὴ τοὺς θεοὺς μελετᾶν ἐπὶ τῶν μικρῶν καὶ ἀπ᾽ ἐκείνων ἀρχομένους διαβαίνειν ἐπὶ τὰ μείζω.","st":"1.18"},{"sp":"N","t":"‘κεφαλὴν ἀλγῶ.’ ‘οἴμοι’ μὴ λέγε. ‘ὠτίον ἀλγῶ.’ ‘οἴμοι’ μὴ λέγε. καὶ οὐ λέγω ὅτι οὐ δέδοται στενάξαι, ἀλλὰ ἔσωθεν μὴ στενάξῃς. μηδ᾽ ἂν βραδέως τὸν ἐπίδεσμον ὁ παῖς φέρῃ, κραύγαζε καὶ σπῶ καὶ λέγε ‘πάντες με μισοῦσιν.’ τίς γὰρ μὴ μισήσῃ τὸν τοιοῦτον;","st":"1.18"},{"sp":"N","t":"τούτοις τὸ λοιπὸν πεποιθὼς τοῖς δόγμασιν ὀρθὸς περιπάτει, ἐλεύθερος, οὐχὶ τῷ μεγέθει πεποιθὼς τοῦ σώματος ὥσπερ ἀθλητής: οὐ γὰρ † ὡς ὄνον ἀήττητον εἶναι.","st":"1.18"},{"sp":"N","t":"τίς οὖν ὁ ἀήττητος; ὃν οὐκ ἐξίστησιν οὐδὲν τῶν ἀπροαιρέτων. εἶτα λοιπὸν ἑκάστην τῶν περιστάσεων ἐπερχόμενος καταμανθάνω ὡς ἐπὶ τοῦ ἀθλητοῦ. ‘οὗτος ἐξεβίασε τὸν πρῶτον κλῆρον. τί οὖν τὸν δεύτερον; τί δ᾽ ἂν καῦμα ᾖ;","st":"1.18"},{"sp":"N","t":"τί δ᾽ ἐν Ὀλυμπίᾳ;’ καὶ ἐνταῦθα ὡσαύτως. ἂν ἀργυρίδιον προβάλῃς, καταφρονήσει. τί οὖν ἂν κορασίδιον; τί οὖν ἂν ἐν σκότῳ; τί οὖν ἂν δοξάριον; τί οὖν ἂν λοιδορίαν; τί οὖν ἂν ἔπαινον; τί δ᾽ ἂν θάνατον;","st":"1.18"},{"sp":"N","t":"δύναται ταῦτα πάντα νικῆσαι. τί οὖν ἂν καῦμα ᾖ, τοῦτό ἐστι: τί, ἂν οἰνωμένος ᾖ; τί ἂν μελαγχολῶν; τί ἐν ὕπνοις; οὗτός μοί ἐστιν ὁ ἀνίκητος ἀθλητής. πῶς ἔχειν δεῖ πρὸς τοὺς τυράννους. ὅτι ἄν τινι προσῇ τι πλεονέκτημα ἢ δοκῇ γε προσεῖναι μὴ προσόν, τοῦτον πᾶσα ἀνάγκη, ἐὰν ἀπαίδευτος ᾖ, πεφυσῆσθαι δι᾽ αὐτό.","st":"1.18"},{"sp":"N","t":"εὐθὺς ὁ τύραννος λέγει ‘ἐγώ εἰμι ὁ πάντων κράτιστος.’ καὶ τί μοι δύνασαι παρασχεῖν; ὄρεξίν μοι δύνασαι περιποιῆσαι ἀκώλυτον; πόθεν σοι; σὺ γὰρ ἔχεις; ἔκκλισιν ἀπερίπτωτον; σὺ γὰρ ἔχεις; ὁρμὴν ἀναμάρτητον;","st":"1.19"},{"sp":"N","t":"καὶ ποῦ σοι μέτεστιν; ἄγε, ἐν νηὶ δὲ σαυτῷ θαρρεῖς ἢ τῷ εἰδότι; ἐπὶ δ᾽ ἅρματος τίνι ἢ τῷ εἰδότι;","st":"1.19"},{"sp":"N","t":"τί δ᾽ ἐν ταῖς ἄλλαις τέχναις; ὡσαύτως. τί οὖν δύνασαι; ‘πάντες με θεραπεύουσιν.’ καὶ γὰρ ἐγὼ τὸ πινάκιον θεραπεύω καὶ πλύνω αὐτὸ καὶ ἐκμάσσω καὶ τῆς ληκύθου ἕνεκα πάσσαλον πήσσω. τί οὖν; ταῦτά μου κρείττονά ἐστιν; οὔ: ἀλλὰ χρείαν μοι παρέχει τινά. ταύτης οὖν ἕνεκα θεραπεύω αὐτά. τί δέ; τὸν ὄνον οὐ θεραπεύω;","st":"1.19"},{"sp":"N","t":"οὐ νίπτω αὐτοῦ τοὺς πόδας; οὐ περικαθαίρω; οὐκ οἶδας ὅτι πᾶς ἄνθρωπος ἑαυτὸν θεραπεύει, σὲ δ᾽ οὕτως ὡς τὸν ὄνον; ἐπεὶ τίς σε θεραπεύει ὡς ἄνθρωπον; δείκνυε.","st":"1.19"},{"sp":"N","t":"τίς σοι θέλει ὅμοιος γενέσθαι, τίς σου ζηλωτὴς γίνεται ὡς Σωκράτους; ‘ἀλλὰ δύναμαί σε τραχηλοκοπῆσαι.’ καλῶς λέγεις. ἐξελαθόμην ὅτι σε δεῖ θεραπεύειν καὶ ὡς πυρετὸν καὶ ὡς χολέραν καὶ βωμὸν στῆσαι, ὡς ἐν Ῥώμῃ Πυρετοῦ βωμός ἐστιν.","st":"1.19"},{"sp":"N","t":"τί οὖν ἐστι τὸ ταράσσον καὶ καταπλῆττον τοὺς πολλούς; ὁ τύραννος καὶ οἱ δορυφόροι; πόθεν; μὴ γένοιτο: οὐκ ἐνδέχεται τὸ φύσει ἐλεύθερον ὑπ᾽ ἄλλου τινὸς ταραχθῆναι ἢ κωλυθῆναι πλὴν ὑφ᾽ ἑαυτοῦ.","st":"1.19"},{"sp":"N","t":"ἀλλὰ τὰ δόγματα αὐτὸν ταράσσει. ὅταν γὰρ ὁ τύραννος εἴπῃ τινὶ ‘δήσω σου τὸ σκέλος,’ ὁ μὲν τὸ σκέλος τετιμηκὼς λέγει ‘μή: ἐλέησον,’ ὁ δὲ τὴν προαίρεσιν τὴν ἑαυτοῦ λέγει ‘εἴ σοι λυσιτελέστερον φαίνεται, δῆσον.’ ‘οὐκ ἐπιστρέφῃ;’","st":"1.19"},{"sp":"N","t":"‘οὐκ ἐπιστρέφομαι.’ ‘ἐγώ σοι δείξω ὅτι κύριός εἰμι.’ ‘πόθεν σύ; ἐμὲ ὁ Ζεὺς ἐλεύθερον ἀφῆκεν. ἢ δοκεῖς ὅτι ἔμελλεν τὸν ἴδιον υἱὸν ἐᾶν καταδουλοῦσθαι; τοῦ νεκροῦ δέ μου κύριος εἶ, λάβε αὐτόν.’","st":"1.19"},{"sp":"N","t":"‘ὥσθ᾽ ὅταν μοι προσίῃς, ἐμὲ οὐ θεραπεύεις;’ ‘οὐ: ἀλλ᾽ ἐμαυτόν. εἰ δὲ θέλεις με λέγειν ὅτι καὶ σέ, λέγω σοι οὕτως ὡς τὴν χύτραν.’","st":"1.19"},{"sp":"N","t":"τοῦτο οὐκ ἔστιν φίλαυτον: γέγονε γὰρ οὕτως τὸ ζῷον: αὑτοῦ ἕνεκα πάντα ποιεῖ. καὶ γὰρ ὁ ἥλιος αὑτοῦ ἕνεκα πάντα ποιεῖ καὶ τὸ λοιπὸν αὐτὸς ὁ Ζεύς.","st":"1.19"},{"sp":"N","t":"ἀλλ᾽ ὅταν θέλῃ εἶναι Ὑέτιος καὶ Ἐπικάρπιος καὶ πατὴρ ἀνδρῶν τε θεῶν τε, ὁρᾷς ὅτι τούτων τῶν ἔργων καὶ τῶν προσηγοριῶν οὐ δύναται τυχεῖν, ἂν μὴ εἰς τὸ κοινὸν ὠφέλιμος ᾖ.","st":"1.19"},{"sp":"N","t":"καθόλου τε τοιαύτην τὴν φύσιν τοῦ λογικοῦ ζῴου κατεσκεύασεν, ἵνα μηδενὸς τῶν ἰδίων ἀγαθῶν δύνηται τυγχάνειν, ἂν μή τι εἰς τὸ κοινὸν ὠφέλιμον προσφέρηται.","st":"1.19"},{"sp":"N","t":"οὕτως οὐκέτι ἀκοινώνητον γίνεται τὸ πάντα αὑτοῦ ἕνεκα ποιεῖν.","st":"1.19"},{"sp":"N","t":"ἐπεὶ τί ἐκδέχῃ; ἵνα τις ἀποστῇ αὑτοῦ καὶ τοῦ ἰδίου συμφέροντος; καὶ πῶς ἔτι μία καὶ ἡ αὐτὴ ἀρχὴ πᾶσιν ἔσται ἡ πρὸς αὐτὰ οἰκείωσις;","st":"1.19"},{"sp":"N","t":"τί οὖν; ὅταν ὑπῇ δόγματα ἀλλόκοτα περὶ τῶν ἀπροαιρέτων πὡς ὄντων ἀγαθῶν καὶ κακῶν, πᾶσα ἀνάγκη θεραπεύει","st":"1.19"},{"sp":"N","t":"ν τοὺς τυράννους. ὤφελον γὰρ τοὺς τυράννους μόνον, τοὺς κοιτωνίτας δ᾽ οὔ. πῶς δὲ καὶ φρόνιμος γίνεται ἐξαίφνης ὁ ἄνθρωπος, ὅταν Καῖσαρ αὐτὸν ἐπὶ τοῦ λασάνου ποιήσῃ: πῶς εὐθὺς λέγομεν ‘φρονίμως μοι λελάληκεν Φηλικίων.’","st":"1.19"},{"sp":"N","t":"ἤθελον αὐτὸν ἀποβληθῆναι τοῦ κοπρῶνος, ἵνα πάλιν ἄφρων σοι δοκῇ.","st":"1.19"},{"sp":"N","t":"εἶχέν τινα Ἐπαφρόδιτος σκυτέα, ὃν διὰ τὸ ἄχρηστον εἶναι ἐπώλησεν. εἶτα ἐκεῖνος κατά τινα δαίμονα ἀγορασθεὶς ὑπό τινος τῶν Καισαριανῶν τοῦ Καίσαρος σκυτεὺς ἐγένετο. εἶδες ἂν πῶς αὐτὸν ἐτίμα ὁ Ἐπαφρόδιτος: ‘","st":"1.19"},{"sp":"N","t":"‘τί πράσσει Φηλικίων ὁ ἀγαθός;","st":"1.19"},{"sp":"N","t":"φιλῶ σε.’ εἶτα εἴ τις ἡμῶν ἐπύθετο ‘τί ποιεῖ αὐτός;’ ἐλέγετο ὅτι ‘μετὰ Φηλικίωνος βουλεύεται περί τινος.’","st":"1.19"},{"sp":"N","t":"οὐχὶ γὰρ πεπράκει αὐτὸν ὡς ἄχρηστον; τίς οὖν αὐτὸν ἄφνω φρόνιμον ἐποίησεν;","st":"1.19"},{"sp":"N","t":"τοῦτ᾽ ἔστι τὸ τιμᾶν ἄλλο τι ἢ τὰ προαιρετικά.’","st":"1.19"},{"sp":"N","t":"‘ἠξίωται δημαρχίας.’ πάντες οἱ ἀπαντῶντες συνήδονται: ἄλλος τοὺς ὀφθαλμοὺς καταφιλεῖ, ἄλλος τὸν τράχηλον, οἱ δοῦλοι τὰς χεῖρας. ἔρχεται εἰς οἶκον, εὑρίσκει λύχνους ἁπτομένους. ἀναβαίνει εἰς τὸ Καπιτώλιον, ἐπιθύει.","st":"1.19"},{"sp":"N","t":"τίς οὖν πώποτε ὑπὲρ τοῦ ὀρεχθῆναι καλῶς ἔθυσεν; ὑπὲρ τοῦ ὁρμῆσαι κατὰ φύσιν; ἐκεῖ γὰρ καὶ θεοῖς εὐχαριστοῦμεν, ὅπου τὸ ἀγαθὸν τιθέμεθα.","st":"1.19"},{"sp":"N","t":"σήμερόν τις ὑπὲρ ἱερωσύνης ἐλάλει μοι τοῦ Αὐγούστου. λέγω αὐτῷ ‘ἄνθρωπε, ἄφες τὸ πρᾶγμα: δαπανήσεις πολλὰ εἰς οὐδέν.’","st":"1.19"},{"sp":"N","t":"—’ἀλλ᾽ οἱ τὰς φὠνάς,’ φησί, ‘γράφοντες γράψουσι τὸ ἐμὸν ὄνομα.’—’μή τι οὖν σὺ τοῖς ἀναγιγνώσκουσι λέγεις παρών: ἐμὲ γεγράφασιν;","st":"1.19"},{"sp":"N","t":"εἰ δὲ καὶ νῦν δύνασαι παρεῖναι πᾶσιν, ἐὰν ἀποθάνῃς, τί ποιήσεις;’—’μενεῖ μου τὸ ὄνομα.’—’γράψον αὐτὸ εἰς λίθον καὶ μενεῖ. ἄγε ἔξω δὲ Νικοπόλεως τίς σου μνεία;’","st":"1.19"},{"sp":"N","t":"—’ἀλλὰ χρυσοῦν στέφανον φορήσω.’—’εἰ ἅπαξ ἐπιθυμεῖς στεφάνου, ῥόδινον λαβὼν περίθου: ὄψει γὰρ κομψότερον.’ περὶ τοῦ λόγου πῶς αὑτοῦ θεωρητικός ἐστιν. πᾶσα τέχνη καὶ δύναμις προηγουμένων τινῶν ἐστι θεωρητική.","st":"1.19"},{"sp":"N","t":"ὅταν μὲν οὖν ὁμοειδὴς τοῖς θεωρουμένοις καὶ αὐτή, ἀναγκαίως καὶ αὑτῆς γίνεται θεωρητική: ὅταν δ᾽ ἀνομογενής, οὐ δύναται θεωρεῖν ἑαυτήν.","st":"1.20"},{"sp":"N","t":"οἷον σκυτικὴ περὶ δέρματα ἀναστρέφεται, αὐτὴ δὲ παντελῶς ἀπήλλακται τῆς ὕλης τῶν δερμάτων: διὰ τοῦτο οὐκ ἔστιν αὑτῆς θεωρητική.","st":"1.20"},{"sp":"N","t":"γραμματικὴ πάλιν περὶ τὴν ἐγγράμματον φωνήν: μή τι οὖν ἐστι καὶ αὐτὴ ἐγγράμματος φωνή; οὐδαμῶς. διὰ τοῦτο οὐ δύναται θεωρεῖν ἑαυτήν. ὁ οὖν λόγος πρὸς τί ποτε ὑπὸ τῆς φύσεως παρείληπται;","st":"1.20"},{"sp":"N","t":"πρὸς χρῆσιν φαντασιῶν οἵαν δεῖ. αὐτὸς οὖν τί ἐστιν; σύστημα ἐκ ποιῶν φαντασιῶν. οὕτως γίνεται φύσει καὶ αὑτοῦ θεωρητικός.","st":"1.20"},{"sp":"N","t":"πάλιν ἡ φρόνησις τίνα θεωρήσουσα παρελήλυθεν; ἀγαθὰ καὶ κακὰ καὶ οὐδέτερα. αὐτὴ οὖν τί ἐστιν; ἀγαθόν. ἡ δ᾽ ἀφροσύνη τί ἐστιν; κακόν. ὁρᾷς οὖν ὅτι ἀναγκαίως καὶ αὑτῆς γίνεται καὶ τῆς ἐναντίας θεωρητική;","st":"1.20"},{"sp":"N","t":"διὰ τοῦτο ἔργον τοῦ φιλοσόφου τὸ μέγιστον καὶ πρῶτον δοκιμάζειν τὰς φαντασίας καὶ διακρίνειν καὶ μηδεμίαν ἀδοκίμαστον προσφέρεσθαι.","st":"1.20"},{"sp":"N","t":"ὁρᾶτε ἐπὶ τοῦ νομίσματος, ὅπου δοκεῖ τι εἶναι πρὸς ἡμᾶς, πῶς καὶ τέχνην ἐξευρήκαμεν καὶ ὅσοις ὁ ἀργυρογνώμων προσχρῆται πρὸς δοκιμασίαν τοῦ νομίσματος, τῇ ὄψει, τῇ ἁφῇ, τῇ ὀσφρασίᾳ, τὰ τελευταῖα τῇ ἀκοῇ:","st":"1.20"},{"sp":"N","t":"ῥήξας τὸ δηνάριον τῷ ψόφῳ προσέχει καὶ οὐχ ἅπαξ ἀρκεῖται ψοφήσαντος, ἀλλ᾽ ὑπὸ τῆς πολλῆς προσοχῆς μουσικὸς γίνεται.","st":"1.20"},{"sp":"N","t":"οὕτως ὅπου διαφέρειν οἰόμεθα τὸ πλανᾶσθαι τοῦ μὴ πλανᾶσθαι, ἐνταῦθα πολλὴν προσοχὴν εἰσφέρομεν εἰς διάκρισιν τῶν διαπλανᾶν δυναμένων,","st":"1.20"},{"sp":"N","t":"ἐπὶ δὲ ταλαιπώρου ἡγεμονικοῦ χάσκοντες καὶ καθεύδοντες, πᾶσαν φαντασίαν παραπροσδεχόμεθα: ἡ γὰρ ζημία οὐ προσπίπτει.","st":"1.20"},{"sp":"N","t":"ὅταν οὖν θέλῃς γνῶναι, πῶς ἔχεις περὶ μὲν τἀγαθὰ καὶ κακὰ ἀνειμένως, περὶ τἀδιάφορα δ᾽ ἐσπευσμένως, ἐπίστησον πῶς ἔχεις πρὸς τὸ ἐκτυφλωθῆναι καὶ πῶς πρὸς τὸ ἐξαπατηθῆναι καὶ γνώσῃ ὅτι μακρὰν εἶ τοῦ ὡς δεῖ πεπονθέναι περὶ ἀγαθῶν καὶ κακῶν.","st":"1.20"},{"sp":"N","t":"‘ἀλλὰ πολλῆς ἔχει χρείαν παρασκευῆς καὶ πόνου πολλοῦ καὶ μαθημάτων.’ τί οὖν; ἐλπίζεις ὅτι τὴν μεγίστην τέχνην ἀπὸ ὀλίγων ἔστιν ἀναλαβεῖν;","st":"1.20"},{"sp":"N","t":"καίτοι αὐτὸς μὲν ὁ προηγούμενος λόγος τῶν φιλοσόφων λίαν ἐστὶν ὀλίγος. εἰ θέλεις γνῶναι, ἀνάγνωθι τὰ Ζήνωνος καὶ ὄψει.","st":"1.20"},{"sp":"N","t":"τί γὰρ ἔχει μακρὸν εἰπεῖν ὅτι τέλος ἐστὶ τὸ ἕπεσθαι θεοῖς, οὐσία δ᾽ ἀγαθοῦ χρῆσις οἵα δεῖ φαντασιῶν;","st":"1.20"},{"sp":"N","t":"λέγε ‘τί οὖν ἐστι θεὸς καὶ τί φαντασία; καὶ τί ἐστι φύσις ἡ ἐπὶ μέρους καὶ τί ἐστι φύσις ἡ τῶν ὅλων;’","st":"1.20"},{"sp":"N","t":"ἤδη μακρόν. ἂν οὖν ἐλθὼν Ἐπίκουρος εἴπῃ, ὅτι ἐν σαρκὶ δεῖ εἶναι τὸ ἀγαθόν, πάλιν μακρὸν γίνεται καὶ ἀνάγκη ἀκοῦσαι τί τὸ προηγούμενόν ἐστιν ἐφ᾽ ἡμῶν, τί τὸ ὑποστατικὸν καὶ οὐσιῶδες. ὅτι τὸ κοχλίου ἀγαθὸν οὐκ εἰκὸς εἶναι ἐν τῷ κελύφει, τὸ οὖν τοῦ ἀνθρώπου εἰκός;","st":"1.20"},{"sp":"N","t":"σὺ δ᾽ αὐτὸς τί κυριώτερον ἔχεις, Ἐπίκουρε; τί ἐστιν ἐν σοὶ τὸ βουλευόμενον, τὸ ἐπισκεπτόμενον ἕκαστα, τὸ περὶ τῆς σαρκὸς αὐτῆς ὅτι τὸ προηγούμενόν ἐστιν τὸ ἐπικρῖνον;","st":"1.20"},{"sp":"N","t":"τί δὲ καὶ λύχνον ἅπτεις καὶ πονεῖς ὑπὲρ ἡμῶν καὶ τηλικαῦτα βιβλία γράφεις; ἵνα μὴ ἀγνοήσωμεν ἡμεῖς τὴν ἀλήθειαν; τίνες ἡμεῖς; τί πρὸς σὲ ὄντες; οὕτω μακρὸς ὁ λόγος γίνεται. πρὸς τοὺς θαυμάζεσθαι θέλοντας.","st":"1.20"},{"sp":"N","t":"ὅταν τις ἣν δεῖ στάσιν ἔχῃ ἐν τῷ βίῳ, ἔξω οὐ κέχηνεν. ἄνθρωπε, τί θέλεις σοι γενέσθαι; ἐγὼ μὲν ἀρκοῦμαι, ἂν ὀρέγωμαι καὶ ἐκκλίνω κατὰ φύσιν, ἂν ὁρμῇ καὶ ἀφορμῇ χρῶμαι ὡς πέφυκα, ἂν προσθέσει, ἂν ἐπιβολῇ, ἂν συγκαταθέσει. τί οὖν ἡμῖν ὀβελίσκον καταπιὼν περιπατεῖς;","st":"1.21"},{"sp":"N","t":"‘ἤθελον, ἵνα με καὶ οἱ ἀπαντῶντες θαυμάζωσιν καὶ ἐπακολουθοῦντες ἐπικραυγάζωσιν: ὦ μεγάλου φιλοσόφου.’","st":"1.21"},{"sp":"N","t":"τίνες εἰσὶν οὗτοι, ὑφ᾽ ὧν θαυμάζεσθαι θέλεις; οὐχ οὗτοί εἰσι, περὶ ὧν εἴωθας λέγειν ὅτι μαίνονται; τί οὖν; ὑπὸ τῶν μαινομένων θαυμάζεσθαι θέλεις; περὶ τῶν προλήψεων. προλήψεις κοιναὶ πᾶσιν ἀνθρώποις εἰσίν: καὶ πρόληψις προλήψει οὐ μάχεται. τίς γὰρ ἡμῶν οὐ τίθησιν, ὅτι τὸ ἀγαθὸν συμφέρον ἐστὶ † ἐστι καὶ αἱρετὸν καὶ ἐκ πάσης αὐτὸ περιστάσεως δεῖ μετιέναι καὶ διώκειν; τίς δ᾽ ἡμῶν οὐ τίθησιν, ὅτι τὸ δίκαιον καλόν ἐστι καὶ πρέπον;","st":"1.21"},{"sp":"N","t":"πότ᾽ οὖν ἡ μάχη γίνεται; περὶ τὴν ἐφαρμογὴν τῶν προλήψεων ταῖς ἐπὶ μέρους οὐσίαις,","st":"1.22"},{"sp":"N","t":"ὅταν ὁ μὲν εἴπῃ ‘καλῶς ἐποίησεν, ἀνδρεῖός ἐστιν:’ ‘οὔ, ἀλλ᾽ ἀπονενοημένος.’ ἔνθεν ἡ μάχη γίνεται τοῖς ἀνθρώποις πρὸς ἀλλήλους.","st":"1.22"},{"sp":"N","t":"αὕτη ἐστὶν ἡ Ἰουδαίων καὶ Σύρων καὶ Αἰγυπτίων καὶ Ῥωμαίων μάχη, οὐ περὶ τοῦ ὅτι τὸ ὅσιον πάντων προτιμητέον καὶ ἐν παντὶ μεταδιωκτέον, ἀλλὰ πότερόν ἐστιν ὅσιον τοῦτο τὸ χοιρείου φαγεῖν ἢ ἀνόσιον.","st":"1.22"},{"sp":"N","t":"ταύτην τὴν μάχην εὑρήσετε καὶ Ἀγαμέμνονος καὶ Ἀχιλλέως. κάλει γὰρ αὐτοὺς εἰς τὸ μέσον. τί λέγεις σύ, ὦ Ἀγάμεμνον; οὐ δεῖ γενέσθαι τὰ δέοντα καὶ τὰ καλῶς ἔχοντα;","st":"1.22"},{"sp":"N","t":"‘δεῖ μὲν οὖν.’ σὺ δὲ τί λέγεις, ὦ Ἀχιλλεῦ; οὐκ ἀρέσκει σοι γίνεσθαι τὰ καλῶς ἔχοντα; ‘ἐμοὶ μὲν οὖν πάντων μάλιστα ἀρέσκει.’ ἐφαρμόσατε οὖν τὰς προλήψεις. ἐντεῦθεν ἡ ἀρχὴ μάχης.","st":"1.22"},{"sp":"N","t":"ὁ μὲν λέγει ‘οὐ χρὴ ἀποδιδόναι με τὴν Χρυσηίδα τῷ πατρί,’ ὁ δὲ λέγει ‘δεῖ μὲν οὖν.’ πάντως ὁ ἕτερος αὐτῶν κακῶς ἐφαρμόζει τὴν πρόληψιν τοῦ δέοντος.","st":"1.22"},{"sp":"N","t":"πάλιν ὁ μὲν λέγει ‘οὐκοῦν, εἴ με δεῖ ἀποδοῦναι τὴν Χρυσηίδα, δεῖ με λαβεῖν ὑμῶν τινος τὸ γέρας,’ ὁ δέ ‘τὴν ἐμὴν οὖν λάβῃς ἐρωμένην;.’ ‘τὴν σήν’ φησίν. ‘ἐγὼ οὖν μόνος—’ ‘ἀλλ᾽ ἐγὼ μόνος μὴ ἔχω;’ οὕτως μάχη γίνεται.","st":"1.22"},{"sp":"N","t":"τί οὖν ἐστι τὸ παιδεύεσθαι; μανθάνειν τὰς φυσικὰς προλήψεις ἐφαρμόζειν ταῖς ἐπὶ μέρους οὐσίαις καταλλήλως τῇ φύσει καὶ λοιπὸν διελεῖν,","st":"1.22"},{"sp":"N","t":"ὅτι τῶν ὄντων τὰ μέν ἐστιν ἐφ᾽ ἡμῖν, τὰ δὲ οὐκ ἐφ᾽ ἡμῖν: ἐφ᾽ ἡμῖν μὲν προαίρεσις καὶ πάντα τὰ προαιρετικὰ ἔργα, οὐκ ἐφ᾽ ἡμῖν δὲ τὸ σῶμα, τὰ μέρη τοῦ σώματος, κτήσεις, γονεῖς, ἀδελφοὶ, τέκνα, πατρίς, ἁπλῶς οἱ κοινωνοί.","st":"1.22"},{"sp":"N","t":"ποῦ οὖν θῶμεν τὸ ἀγαθόν; ποίᾳ οὐσίᾳ αὐτὸ ἐφαρμόσομεν; τῇ ἐφ᾽ ἡμῖν;","st":"1.22"},{"sp":"N","t":"— εἶτα οὐκ ἔστιν ἀγαθὸν ὑγίεια καὶ ἀρτιότης καὶ ζωή, ἀλλ᾽ οὐδὲ τέκνα οὐδὲ γονεῖς οὐδὲ πατρίς; — καὶ τίς σου ἀνέξεται;","st":"1.22"},{"sp":"N","t":"μεταθῶμεν οὖν αὐτὸ πάλιν ἐνθάδε. ἐνδέχεται οὖν βλαπτόμενον καὶ ἀποτυγχάνοντα τῶν ἀγαθῶν εὐδαιμονεῖν; — οὐκ ἐνδέχεται. — καὶ τὴν πρὸς τοὺς κοινωνοὺς οἵαν δεῖ ... ἀναστροφήν; καὶ πῶς ἐνδέχεται;","st":"1.22"},{"sp":"N","t":"ἐγὼ γὰρ πέφυκα πρὸς τὸ ἐμὸν συμφέρον. εἰ συμφέρει μοι ἀγρὸν ἔχειν, συμφέρει μοι καὶ ἀφελέσθαι αὐτὸν τοῦ πλησίον: εἰ συμφέρει μοι ἱμάτιον ἔχειν, συμφέρει μοι καὶ κλέψαι αὐτὸ ἐκ βαλανείου. ἔνθεν πόλεμοι, στάσεις, τυραννίδες, ἐπιβουλαί.","st":"1.22"},{"sp":"N","t":"πῶς δ᾽ ἔτι δυνήσομαι τὸ πρὸς τὸν Δία καθῆκον; εἰ γὰρ βλάπτομαι καὶ ἀτυχῶ, οὐκ ἐπιστρέφεταί μου. καὶ ‘τί μοι καὶ αὐτῷ, εἰ οὐ δύναταί μοι βοηθῆσαι;’ καὶ πάλιν ‘τί μοι καὶ αὐτῷ, εἰ θέλει μ᾽ ἐν τοιούτοις εἶναι ἐν οἷς εἰμι;’ ἄρχομαι λοιπὸν μισεῖν αὐτόν.","st":"1.22"},{"sp":"N","t":"τί οὖν ναοὺς ποιοῦμεν, τί οὖν ἀγάλματα, ὡς κακοῖς δαίμοσιν, ὡς πυρετῷ τῷ Διί; καὶ πῶς ἔτι Σωτὴρ καὶ πῶς Ὑέτιος καὶ πῶς Ἐπικάρπιος; καὶ μήν, ἂν ἐνταῦθά που θῶμεν τὴν οὐσίαν τοῦ ἀγαθοῦ, πάντα ταῦτα ἐξακολουθεῖ. τί οὖν ποιήσωμεν;","st":"1.22"},{"sp":"N","t":"— αὕτη ἐστὶ ζήτησις τοῦ φιλοσοφοῦντος τῷ ὄντι καὶ ὠδίνοντος: νῦν ἐγὼ οὐχ ὁρῶ τί ἐστι τὸ ἀγαθὸν καὶ τὸ κακόν: οὐ μαίνομαι;","st":"1.22"},{"sp":"N","t":"ναί: ἀλλ᾽ ἂν ἐνταῦθά που θῶ τὸ ἀγαθόν, ἐν τοῖς προαιρετικοῖς, πάντες μου καταγελάσονται. ἥξει τις γέρων πολιὸς χρυσοῦς δακτυλίους ἔχων πολλούς, εἶτα ἐπισείσας τὴν κεφαλὴν ἐρεῖ ‘ἄκουσόν μου, τέκνον: δεῖ μὲν καὶ φιλοσοφεῖν, δεῖ δὲ καὶ ἐγκέφαλον ἔχειν: ταῦτα μωρά ἐστιν. σὺ παρὰ τῶν φιλοσόφων μανθάνεις συλλογισμόν,","st":"1.22"},{"sp":"N","t":"τί δέ σοι ποιητέον ἐστίν, σὺ κάλλιον οἶδας ἢ οἱ φιλόσοφοι.’ ἄνθρωπε, τί οὖν μοι ἐπιτιμᾷς, εἰ οἶδα;","st":"1.22"},{"sp":"N","t":"τούτῳ τῷ ἀνδραπόδῳ τί εἴπω;","st":"1.22"},{"sp":"N","t":"ἂν σιωπῶ, ῥήγνυται ἐκεῖνος. ὡς δεῖ λέγειν ὅτι ‘σύγγνωθί μοι ὡς τοῖς ἐρῶσιν: οὐκ εἰμὶ ἐμαυτοῦ, μαίνομαι.’ πρὸς Ἐπίκουρον. ἐπινοεῖ καὶ Ἐπίκουρος ὅτι φύσει ἐσμὲν κοινωνικοί, ἀλλ᾽ ἅπαξ ἐν τῷ κελύφει θεὶς τὸ ἀγαθὸν ἡμῶν οὐκέτι δύναται ἄλλο οὐδὲν εἰπεῖν.","st":"1.22"},{"sp":"N","t":"πάλιν γὰρ ἐκείνου λίαν κρατεῖ, ὅτι οὐ δεῖ ἀπεσπασμένον οὐδὲν τῆς τοῦ ἀγαθοῦ οὐσίας οὔτε θαυμάζειν οὔτ᾽ ἀποδέχεσθαι: καὶ καλῶς αὐτοῦ κρατεῖ.","st":"1.23"},{"sp":"N","t":"πῶς οὖν ὑπονοητικοί ἐσμεν, οἷς μὴ φυσικὴ ἔστι πρὸς τὰ ἔγγονα φιλοστοργία; διὰ τί ἀποσυμβουλεύεις τῷ σοφῷ τεκνοτροφεῖν; τί φοβῇ μὴ διὰ ταῦτα εἰς λύπας ἐμπέσῃ;","st":"1.23"},{"sp":"N","t":"διὰ γὰρ τὸν μῦν τὸν ἔσω τρεφόμενον ἐμπίπτει; τί οὖν αὐτῷ μέλει, ἂν μυίδιον μικρὸν ἔσω κατακλαίῃ αὐτοῦ;","st":"1.23"},{"sp":"N","t":"ἀλλ᾽ οἶδεν, ὅτι, ἂν ἅπαξ γένηται παιδίον, οὐκέτι ἐφ᾽ ἡμῖν ἐστι μὴ στέργειν μηδὲ φροντίζειν ἐπ᾽ αὐτῷ.","st":"1.23"},{"sp":"N","t":"διὰ τοῦτο φησὶν οὐδὲ πολιτεύσεσθαι τὸν νοῦν ἔχοντα: οἶδεν γὰρ τίνα δεῖ ποιεῖν τὸν πολιτευόμενον: ἐπείτοι εἰ ὡς ἐν μυίαις μέλλεις ἀναστρέφεσθαι, τί κωλύει;","st":"1.23"},{"sp":"N","t":"ἀλλ᾽ ὅμως εἰδὼς ταῦτα τολμᾷ λέγειν ὅτι ‘μὴ ἀναιρώμεθα τέκνα.’ ἀλλὰ πρόβατον μὲν οὐκ ἀπολείπει τὸ αὑτοῦ ἔγγονον οὐδὲ λύκος, ἄνθρωπος δ᾽ ἀπολείπει;","st":"1.23"},{"sp":"N","t":"τί θέλεις; μωροὺς ἡμᾶς εἶναι ὡς τὰ πρόβατα; οὐδ᾽ ἐκεῖνα ἀπολείπει. θηριώδεις ὡς τοὺς λύκους; οὐδ᾽ ἐκεῖνοι ἀπολ","st":"1.23"},{"sp":"N","t":"είπουσιν. ἄγε, τίς δέ σοι πείθεται ἰδὼν παιδίον αὐτοῦ κλαῖον ἐπὶ τὴν γῆν πεπτωκός;","st":"1.23"},{"sp":"N","t":"ἐγὼ μὲν οἶμαι ὅτι εἰ καὶ ἐμαντεύσατο ἡ μήτηρ σου καὶ ὁ πατήρ, ὅτι μέλλεις ταῦτα λέγειν, οὐκ ἄν σε ἔρριψαν. πῶς πρὸς τὰς περιστάσεις ἀγωνιστέον. αἱ περιστάσεις εἰσὶν αἱ τοὺς ἄνδρας δεικνύουσαι. λοιπὸν ὅταν ἐμπέσῃ περίστασις, μέμνησο ὅτι ὁ θεός σε ὡς ἀλείπτης τραχεῖ νεανίσκῳ","st":"1.23"},{"sp":"N","t":"συμβέβληκεν. — ἵνα τί; φησίν. — ἵνα Ὀλυμπιονίκης γένῃ: δίχα δ᾽ ἱδρῶτος οὐ γίγνεται. ἐμοὶ μὲν οὐδεὶς δοκεῖ κρείσσονα ἐσχηκέναι περίστασιν ἧς σὺ ἔσχηκας, ἂν θέλῃς ὡς ἀθλητὴς νεανίσκῳ χρῆσθαι.","st":"1.24"},{"sp":"N","t":"καὶ νῦν ἡμεῖς γε εἰς τὴν Ῥώμην κατάσκοπον πέμπομεν. οὐδεὶς δὲ δειλὸν κατάσκοπον πέμπει, ἵν᾽, ἂν μόνον ἀκούσῃ ψόφου καὶ σκιάν ποθεν ἴδῃ, τρέχων ἔλθῃ τεταραγμένος καὶ λέγων ἤδη παρεῖναι τοὺς πολεμίους.","st":"1.24"},{"sp":"N","t":"οὕτως νῦν καὶ σὺ ἂν ἐλθὼν ἡμῖν εἴπῃς ‘φοβερὰ τὰ ἐν Ῥώμῃ πράγματα, δεινόν ἐστι θάνατος, δεινόν ἐστι φυγή, δεινὸν λοιδορία, δεινὸν πενία: φεύγετε ἄνδρες, πάρεισιν οἱ πολέμιοι,’","st":"1.24"},{"sp":"N","t":"ἐροῦμέν σοι ‘ἄπελθε, σεαυτῷ μαντεύου: ἡμεῖς τοῦτο μόνον ἡμάρτομεν, ὅτι τοιοῦτον κατάσκοπον ἐπέμπομεν.’","st":"1.24"},{"sp":"N","t":"πρὸ σοῦ κατάσκοπος ἀποσταλεὶς Διογένης ἄλλα ἡμῖν ἀπήγγελκεν. λέγει ὅτι ὁ θάνατος οὐκ ἔστι κακόν, οὐδὲ γὰρ αἰσχρόν: λέγει ὅτι ἀδοξία ψόφος ἐστὶ μαινομένων ἀνθρώπων.","st":"1.24"},{"sp":"N","t":"οἷα δὲ περὶ πόνου, οἷα δὲ περὶ ἡδονῆς, οἷα περὶ πενίας εἴρηκεν οὗτος ὁ κατάσκοπος. τὸ δὲ γυμνασιὸν εἶναι λέγει ὅτι κρεῖσσόν ἐστι πάσης περιπορφύρου: τὸ δ᾽ ἐπ᾽ ἀστρώτῳ πέδῳ καθεύδειν λέγει ὅτι μαλακωτάτη κοίτη ἐστίν.","st":"1.24"},{"sp":"N","t":"καὶ ἀπόδειξιν φέρει περὶ ἑκάστου τὸ θάρσος τὸ αὑτοῦ, τὴν ἀταραξίαν, τὴν ἐλευθερίαν, εἶτα καὶ τὸ σωμάτιον στίλβον καὶ συνεστραμμένον.","st":"1.24"},{"sp":"N","t":"‘οὐδείς,’ φησίν, ‘πολέμιος ἐγγύς ἐστιν: πάντα εἰρήνης γέμει.’ πῶς, ὦ Διόγενες; ‘ἰδού,’ φησίν, ‘μή τι βέβλημαι, μή τι τέτρωμαι, μή τινα πέφευγα;’","st":"1.24"},{"sp":"N","t":"τοῦτ᾽ ἔστιν οἷος δεῖ κατάσκοπος, σὺ δ᾽ ἡμῖν ἐλθὼν ἄλλα ἐξ ἄλλων λέγεις. οὐκ ἀπελεύσῃ πάλιν καὶ ὄψει ἀκριβέστερον δίχα τῆς δειλίας; τί οὖν ποιήσω;","st":"1.24"},{"sp":"N","t":"— τί ποιεῖς, ἐκ πλοίου ὅταν ἐξίῃς; μή τι τὸ πηδάλιον αἴρεις, μή τι τὰς κώπας; τί οὖν αἴρεις; τὰ σά, τὴν λήκυθον, τὴν πήραν. καὶ νῦν ἂν ᾖς μεμνημένος τῶν σῶν, οὐδέποτε τῶν ἀλλοτρίων ἀντιποιήσῃ.","st":"1.24"},{"sp":"N","t":"λέγει σοι ‘θὲς τὴν πλατύσημον:’ ἰδοὺ στενόσημος. ‘θὲς καὶ ταύτην:’ ἰδοὺ ἱμάτιον μόνον. ‘θὲς τὸ ἱμάτιον:’","st":"1.24"},{"sp":"N","t":"‘ ἰδοὺ γυμνός.’ ‘ἀλλὰ φθόνον μοι κινεῖς.’ λάβε τοίνυν ὅλον τὸ σωμάτιον. ᾧ δύναμαι ῥῖψαι τὸ σωμάτιον, ἔτι τοῦτο","st":"1.24"},{"sp":"N","t":"ν φοβοῦμαι; ἀλλὰ κληρονόμον μ᾽ οὐκ ἀπολείψει. τί οὖν; ἐπελαθόμην ὅτι τούτων οὐδὲν ἐμὸν ἦν; πῶς οὖν ἐμὰ αὐτὰ λέγομεν; ὡς τὸν κράβαττον ἐν τῷ πανδοκείῳ. ἂν οὖν ὁ πανδοκεὺς ἀποθανὼν ἀπολίπῃ σοι τοὺς κραβάττους: ἂν δ᾽ ἄλλῳ, ἐκεῖνος ἕξει, σὺ δ᾽ ἄλλον ζητήσεις:","st":"1.24"},{"sp":"N","t":"ἂν οὖν μὴ εὕρῃς, χαμαὶ κοιμήσῃ μόνον θαρρῶν καὶ ῥέγκων καὶ μεμνημένος ὅτι ἐν τοῖς πλουσίοις καὶ βασιλεῦσι καὶ τυράννοις αἱ τραγῳδίαι τόπον ἔχουσιν, οὐδεὶς δὲ πένης τραγῳδίαν συμπληροῖ εἰ μὴ ὡς χορευτής.","st":"1.24"},{"sp":"N","t":"οἱ δὲ βασιλεῖς ἄρχονται μὲν ἀπ᾽ ἀγαθῶν: στέψατε δώματα: εἶτα περὶ τρίτον ἢ τέταρτον μέρος: ἰὼ Κιθαιρών, τί μ᾽ ἐδέχου; ἀνδράποδον, ποῦ οἱ στέφανοι, ποῦ τὸ διάδημα;","st":"1.24"},{"sp":"N","t":"οὐδέν σε ὠφελοῦσιν οἱ δορυφόροι;","st":"1.24"},{"sp":"N","t":"ὅταν οὖν ἐκείνων τινὶ προσίῃς, τούτων μέμνησο, ὅτι τραγῳδῷ προσέρχῃ, οὐ τῷ ὑποκριτῇ, ἀλλ᾽ αὐτῷ τῷ Οἰδίποδι.","st":"1.24"},{"sp":"N","t":"‘ἀλλὰ μακάριος ὁ δεῖνα: μετὰ πολλῶν γὰρ περιπατεῖ.’ κἀγὼ συγκατατάττω ἐμαυτὸν σὺν τοῖς πολλοῖς καὶ μετὰ πολλῶν περιπατῶ.","st":"1.24"},{"sp":"N","t":"τὸ δὲ κεφάλαιον: μέμνησο ὅτι ἡ θύρα ἤνοικται. μὴ γίνου τῶν παιδίων δειλότερος, ἀλλ᾽ ὡς ἐκεῖνα, ὅταν αὐτοῖς μὴ ἀρέσκῃ τὸ πρᾶγμα, λέγει ‘οὐκέτι παίξω,’ καὶ σύ, ὅταν σοι φαίνηταί τινα εἶναι τοιαῦτα, εἰπὼν ‘οὐκέτι παίξω’ ἀπαλλάσσου, μένων δὲ μὴ θρήνει. πρὸς τὸ αὐτό. εἰ ταῦτα ἀληθῆ ἐστι καὶ μὴ βλακεύομεν μηδ᾽ ὑποκρινόμεθα ὅτι τὸ ἀγαθὸν τοῦ ἀνθρώπου ἐν προαιρέσει καὶ τὸ κακόν, τὰ δ᾽ ἄλλα πάντα οὐδὲν πρὸς ἡμᾶς, τί ἔτι ταρασσόμεθα, τί ἔτι φοβούμεθα; περὶ ἃ ἐσπουδάκαμεν, τούτων ἐξουσίαν οὐδεὶς ἔχει:","st":"1.24"},{"sp":"N","t":"ὧν ἐξουσίαν οἱ ἄλλοι ἔχουσιν, τούτων οὐκ ἐπιστρεφόμεθα. ποῖον ἔτι πρᾶγμα ἔχομεν;","st":"1.25"},{"sp":"N","t":"— ἀλλὰ ἔντειλαί μοι. — τί σοι ἐντείλωμαι; ὁ Ζεύς σοι οὐκ ἐντέταλται; οὐ δέδωκέν σοι τὰ μὲν σὰ ἀκώλυστα καὶ ἀπαραπόδιστα, τὰ δὲ μὴ σὰ κωλυτὰ καὶ παραποδιστά;","st":"1.25"},{"sp":"N","t":"τίνα οὖν ἐντολὴν ἔχων ἐκεῖθεν ἐλήλυθας, ποῖον διάταγμα; τὰ σὰ τήρει ἐκ παντὸς τρόπου, τῶν ἀλλοτρίων μὴ ἐφίεσο. τὸ πιστὸν σόν ... : τίς οὖν ἀφελέσθαι δύναταί σου ταῦτα; τίς κωλύσει χρῆσθαι αὐτοῖς ἄλλος εἰ μὴ σύ; σὺ δὲ πῶς; ὅταν περὶ τὰ μὴ σαυτοῦ σπουδάσῃς, τὰ σαυτοῦ ἀπώλεσας.","st":"1.25"},{"sp":"N","t":"τοιαύτας ἔχων ὑποθήκας καὶ ἐντολὰς παρὰ τοῦ Διὸς ποίας ἔτι παρ᾽ ἐμοῦ θέλεις; κρείσσων εἰμὶ ἐκείνου, ἀξιοπιστότερος;","st":"1.25"},{"sp":"N","t":"ἀλλὰ ταύτας τηρῶν ἄλλων τινῶν προσδέῃ; ἀλλ᾽ ἐκεῖνος οὐκ ἐντέταλται ταῦτα; φέρε τὰς προλήψεις, φέρε τὰς ἀποδείξεις τὰς τῶν φιλοσόφων, φέρε ἃ πολλάκις ἤκουσας, φέρε δ᾽ ἃ εἶπας αὐτός, φέρε ἃ ἀνέγνως, φέρε ἃ ἐμελέτησας.","st":"1.25"},{"sp":"N","t":"μέχρις οὖ ν τίνος ταῦτα τηρεῖν καλῶς ἔχεις καὶ τὴν παιδιὰν μὴ λύειν;","st":"1.25"},{"sp":"N","t":"μέχρις ἂν κομψῶς διεξάγηται. ἐν Σατορναλίοις λέλογχεν βασιλεύς: ἔδοξε γὰρ παῖξαι ταύτην τὴν παιδιάν. προστάσσει ‘σὺ πίε, σὺ κέρασον, σὺ ᾆσον, σὺ ἄπελθε, σὺ ἐλθέ.’ ὑπακούω, ἵνα μὴ παρ᾽ ἐμὲ λύηται ἡ παιδιά.","st":"1.25"},{"sp":"N","t":"‘ἀλλὰ σὺ ὑπολάμβανε ὅτι ἐν κακοῖς εἶ.’ οὐχ ὑπολαμβάνω: καὶ τίς μ᾽ ἀναγκάσει ὑπολαμβάνειν;","st":"1.25"},{"sp":"N","t":"πάλιν συνεθέμεθα παῖξαι τὰ περὶ Ἀγαμέμνονα καὶ Ἀχιλλέα. καταταγεὶς Ἀγαμέμνων λέγει μοι ‘πορεύου πρὸς τὸν Ἀχιλλέα καὶ ἀπόσπασον τὴν Βρισηίδα.’ πορεύο","st":"1.25"},{"sp":"N","t":"μαι. ‘ἔρχου.’ ἔρχομαι. ὡς γὰρ ἐπὶ τῶν ὑποθετικῶν λόγων ἀναστρεφόμεθα, οὕτως δεῖ καὶ ἐπὶ τοῦ βίου. ‘ἔστω νύξ.’ ἔστω. ‘τί οὖν; ἡμέρα ἐστίν;’ οὔ: ἔλαβον γὰρ ὑπόθεσιν τοῦ νύκτα εἶναι.","st":"1.25"},{"sp":"N","t":"‘ἔστω σε ὑπολαμβάνειν ὅτι νύξ ἐστιν.’ ἔστω. ‘ἀλλὰ καὶ ὑπόλαβε ὅτι νύξ ἐστιν.’ οὐκ ἀκολουθεῖ τῇ ὑποθέσει.","st":"1.25"},{"sp":"N","t":"οὕτως καὶ ἐνταῦθα. ‘ἔστω σε εἶναι δυστυχῆ.’ ἔστω. ‘ἆρ᾽ οὖν ἀτυχὴς εἶ;’ ναί. ‘τί οὖν; κακοδαιμονεῖς;’ ναί. ‘ἀλλὰ καὶ ὑπόλαβε ὅτι ἐν κακοῖς εἶ.’ οὐκ ἀκολουθεῖ τῇ ὑποθέσει: καὶ ἄλλος με κωλύει.","st":"1.25"},{"sp":"N","t":"μέχρι πόσου οὖν ὑπακουστέον τοῖς τοιούτοις; μέχρις ἂν οὗ λυσιτελῇ, τοῦτο δ᾽ ἔστιν μέχρις ἂν οὗ σῴζω τὸ πρέπον καὶ κατάλληλον.","st":"1.25"},{"sp":"N","t":"λοιπὸν οἱ μέν εἰσι κακαύστηροι καὶ κακοστόμαχοι καὶ λέγουσιν ‘ἐγὼ οὐ δύναμαι παρὰ τούτῳ δειπνεῖν, ἵν᾽ αὐτοῦ ἀνέχομαι καθ᾽ ἡμέραν διηγουμένου, πῶς ἐν Μυσίᾳ ἐπολέμησεν: διηγησάμην σοι, ἀδελφέ, πῶς ἐπὶ τὸν λόφον ἀνέβην: πάλιν ἄρχομαι πολιορκεῖσθαι.’","st":"1.25"},{"sp":"N","t":"ἄλλος λέγει ‘ἐγὼ δειπνῆσαι θέλω μᾶλλον καὶ ἀκούειν αὐτοῦ ὅσα θέλει ἀδολεσχοῦντος.’","st":"1.25"},{"sp":"N","t":"καὶ σὺ σύγκρινε ταύτας τὰς ἀξίας: μόνον μηδὲν βαρούμενος ποίει, μὴ θλιβόμενος μηδ᾽ ὑπολαμβάνων ἐν κακοῖς εἶναι: τοῦτο γὰρ οὐδείς σε ἀναγκάζει.","st":"1.25"},{"sp":"N","t":"καπνὸν πεποίηκεν ἐν τῷ οἰκήματι; ἂν μέτριον, μενῶ: ἂν λίαν πολύν, ἐξέρχομαι. τούτου γὰρ μεμνῆσθαι καὶ κρατεῖν, ὅτι ἡ θύρα ἤνοικται.","st":"1.25"},{"sp":"N","t":"ἀλλὰ ‘μὴ οἴκει ἐν Νικοπόλει.’ οὐκ οἰκῶ. ‘μηδ᾽ ἐν Ἀθήναις.’ οὐδ᾽ ἐν Ἀθήναις. ‘μηδ᾽ ἐν Ῥώμῃ.’ οὐδ᾽ ἐν Ῥώμῃ. ‘ἐν Γυάροις οἴκει.’ οἰκῶ. ἀλλὰ πολύς μοι καπνὸς φαίνεται τὸ ἐν Γυάροις οἰκεῖν.","st":"1.25"},{"sp":"N","t":"ἀποχωρῶ, ὅπου μ᾽ οὐδεὶς κωλύσει οἰκεῖν: ἐκείνη γὰρ ἡ οἴκησις παντὶ ἤνοικται.","st":"1.25"},{"sp":"N","t":"καὶ τὸ τελευταῖον χιτωνάριον, τοῦτ᾽ ἔστι τὸ σωμάτιον, τούτου ἀνωτέρω οὐδενὶ οὐδὲν εἰς ἐμὲ ἔξεστιν.","st":"1.25"},{"sp":"N","t":"διὰ τοῦτο ὁ Δημήτριος εἶπεν τῷ Νέρωνι","st":"1.25"},{"sp":"N","t":"‘ἀπειλεῖς μοι θάνατον, σοὶ δ᾽ ἡ φύσις.’ ἂν δὲ τὸ σωμάτιον θαυμάσω, δοῦλον ἐμαυτὸν παραδέδωκα: ἂν τὸ κτησείδιον, δοῦλον.","st":"1.25"},{"sp":"N","t":"εὐθὺς γὰρ ἐμαὐτὸς κατ᾽ ἐμαυτοῦ δηλῶ, τίνι ἁλωτός εἰμι. ὡς ὁ ὄφις ἐὰν συσπᾷ τὴν κεφαλήν, λέγω ‘ἐκεῖνο αὐτοῦ τύπτε ὃ φυλάσσει.’ καὶ σὺ γίγνωσκε, ὅτι ὃ ἂν φυλάσσειν ἐθέλῃς, κατ᾽ ἐκεῖνο ἐπιβήσεταί σοι ὁ κύριος.","st":"1.25"},{"sp":"N","t":"τούτων μεμνημένος τίνα ἔτι κολακεύσεις ἢ φοβήσῃ; ἀλλὰ θέλω καθῆσθαι ὅπου οἱ συγκλητικοί.","st":"1.25"},{"sp":"N","t":"— ὁρᾷς ὅτι σὺ σαυτῷ στενοχωρίαν παρέχεις, σὺ σαυτὸν θλίβεις;","st":"1.25"},{"sp":"N","t":"— πῶς οὖν ἄλλως θεωρήσω καλῶς ἐν τῷ ἀμφιθεάτρῳ; — ἄνθρωπε, καὶ μὴ θεώρει καὶ οὐ μὴ θλιβῇς. τί πράγματα ἔχεις; ἢ μικρὸν ἔκδεξαι καὶ ἀχθείσης τῆς θεωρίας κάθισον εἰς τοὺς τῶν συγκλητικῶν τόπους καὶ ἡλιάζου.","st":"1.25"},{"sp":"N","t":"καθόλου γὰρ ἐκείνου μέμνησο, ὅτι ἑαυτοὺς θλίβομεν, ἑαυτοὺς στενοχωροῦμεν, τοῦτ᾽ ἔστιν τὰ δόγματα ἡμᾶς θλίβει καὶ στενοχωρεῖ.","st":"1.25"},{"sp":"N","t":"ἐπεὶ τί ἐστιν αὐτὸ τὸ λοιδορεῖσθαι; παραστὰς λίθον λοιδόρει: καὶ τί ποιήσεις; ἂν οὖν τις ὡς λίθος ἀκούῃ, τί ὄφελος τῷ λοιδοροῦντι; ἂν δ᾽ ἔχῃ τὴν ἀσθένειαν τοῦ λοιδορουμένου ὁ λοιδορῶν ἐπιβάθραν, τότε ἀνύει τι.","st":"1.25"},{"sp":"N","t":"‘περίσχισον αὐτόν.’ τί λέγεις αὐτόν; τὸ ἱμάτιον λάβε, περίσχισον.","st":"1.25"},{"sp":"N","t":"‘ὕβριν σοι πεποίηκα.’ καλῶς σοι γένοιτο. ταῦτα ἐμελέτα Σωκράτης, διὰ τοῦτο ἓν ἔχων πρόσωπον ἀεὶ διετέλει. ἡμεῖς δὲ θέλομεν πάντα μᾶλλον ἀσκεῖν καὶ μελετᾶν ἢ ὅπως ἀπαραπόδιστοι καὶ ἐλεύθεροι ἐσόμεθα.","st":"1.25"},{"sp":"N","t":"‘παράδοξα λέγουσιν οἱ φιλόσοφοι.’ ἐν δὲ ταῖς ἄλλαις τέχναις οὐκ ἔστι παράδοξα; καὶ τί παραδοξότερόν ἐστιν ἢ κεντεῖν τινος τὸν ὀφθαλμόν, ἵνα ἴδῃ; εἴ τις ἀπείρῳ τῶν ἰατρικῶν τοῦτο εἶπεν, οὐκ ἂν κατεγέλα τοῦ λέγοντος;","st":"1.25"},{"sp":"N","t":"τί οὖν θαυμαστὸν εἰ καὶ ἐν φιλοσοφίᾳ πολλὰ τῶν ἀληθῶν παράδοξα φαίνεται τοῖς ἀπείροις; τίς ὁ βιωτικὸς νόμος. ἀναγιγνώσκοντος δὲ τοὺς ὑποθετικοὺς ἔφη Νόμος ὑποθετικός ἐστι καὶ οὗτος τὸ ἀκόλουθον τῇ ὑποθέσει παραδέχεσθαι. πολὺ πρότερον δὲ νόμος βιωτικός ἐστιν οὗτος τὸ ἀκόλουθον τῇ φύσει πράττειν.","st":"1.25"},{"sp":"N","t":"εἰ γὰρ ἐπὶ πάσης ὕλης καὶ περιστάσεως βουλόμεθα τηρῆσαι τὸ κατὰ φύσιν, δῆλον ὅτι ἐν παντὶ στοχαστέον τοῦ μήτε τὸ ἀκόλουθον ἡμᾶς ἐκφυγεῖν μήτε παραδέξασθαι τὸ μαχόμενον.","st":"1.26"},{"sp":"N","t":"πρῶτον οὖν ἐπὶ τῆς θεωρίας γυμνάζουσιν ἡμᾶς οἱ φιλόσοφοι ὅπου ῥᾷον, εἶτα οὕτως ἐπὶ τὰ χαλεπώτερα ἄγουσιν: ἐνταῦθα γὰρ οὐδέν ἐστι τὸ ἀνθέλκον ὡς πρὸς τὸ ἀκολουθῆσαι τοῖς διδασκομένοις, ἐπὶ δὲ τῶν βιωτικῶν πολλὰ τὰ περισπῶντα. γελοῖος οὖν ὁ λέγων πρῶτον βούλεσθαι ἐπ᾽ ἐκείνων:","st":"1.26"},{"sp":"N","t":"οὐ γὰρ ῥᾴδιον ἄρχεσθαι ἀπὸ τῶν χαλεπωτέρων.","st":"1.26"},{"sp":"N","t":"καὶ τοῦτον ἀπολογισμὸν ἔδει φέρειν πρὸς τοὺς γονεῖς τοὺς ἀγανακτοῦντας ἐπὶ τῷ φιλοσοφεῖν τὰ τέκνα. ‘οὐκοῦν ἁμαρτάνω, πάτερ, καὶ οὐκ οἶδα τὸ ἐπιβάλλον ἐμαυτῷ καὶ προσῆκον: εἰ μὲν οὐδὲ μαθητόν ἐστιν οὐδὲ διδακτόν, τί μοι ἐγκαλεῖς; εἰ δὲ διδακτόν, δίδασκε: εἰ δὲ σὺ μὴ δύνασαι, ἄφες με μαθεῖν παρὰ τῶν λεγόντων εἰδέναι.","st":"1.26"},{"sp":"N","t":"ἐπεὶ τί δοκεῖς; ὅτι θέλων περιπίπτω κακῷ καὶ ἀποτυγχάνω τοῦ ἀγαθοῦ; μὴ γένοιτο. τί οὖν ἐστι τὸ αἴτιον τοῦ ἁμαρτάνειν με;","st":"1.26"},{"sp":"N","t":"ἡ ἄγνοια. οὐ θέλεις οὖν ἀποθῶμαι τὴν ἄγνοιαν; τίνα πώποτε ὀργὴν ἐδίδαξε τὰ κυβερνητικά, τὰ μουσικά; τὰ βιωτικὰ οὖν διὰ τὴν ὀργήν σου δοκεῖς ὅτι μαθήσομαι;’","st":"1.26"},{"sp":"N","t":"ταῦτα ἐκείνῳ μόνῳ λέγειν ἔξεστι τῷ τοιαύτην ἐπιβολὴν ἐνηνοχότι. εἰ δέ τις μόνον ἐπιδείκνυσθαι θέλων ἐν συμποσίῳ ὅτι οἶδεν τοὺς ὑποθετικοὺς ἀναγιγνώσκει ταῦτα καὶ προσέρχεται τοῖς φιλοσόφοις, οὗτος ἄλλο τι πράσσει † ἵνα αὐτὸν συγκλητικὸς παρακατακείμενος θαυμάσει;","st":"1.26"},{"sp":"N","t":"ἐκεῖ γὰρ τῷ ὄντι αἱ μεγάλαι ὗλαί εἰσι καὶ οἱ ἐνθάδε πλοῦτοι ἐκεῖ παίγνια δοκοῦσιν. διὰ τοῦτο ἐκεῖ δύσκολον κρατῆσαι τῶν αὑτοῦ φαντασιῶν, ὅπου τὰ ἐκ","st":"1.26"},{"sp":"N","t":"σείοντα μεγάλα. ἐγώ τινα οἶδα κλαίοντα Ἐπαφροδίτου τῶν γονάτων ἁπτόμενον καὶ λέγοντα ταλαιπωρεῖν: ἀπολελεῖφθαι γὰρ αὐτῷ μηδέν, εἰ μὴ ἑκατὸν πεντήκοντα μυριάδας.","st":"1.26"},{"sp":"N","t":"τί οὖν ὁ Ἐπαφρόδιτος; κατεγέλασεν ὡς ὑμεῖς; οὔ: ἀλλ᾽ ἐπιθαυμάσας λέγει ‘τάλας, πῶς οὖν ἐσιώπας, πῶς ἐκαρτέρεις;’","st":"1.26"},{"sp":"N","t":"ταράξας δὲ τὸν ἀναγιγνώσκοντα τοὺς ὑποθετικοὺς καὶ γελάσαντος τοῦ ὑποθεμένου αὐτῷ τὴν ἀνάγνωσιν Σεαυτοῦ, ἔφη, καταγελᾷς: οὐ προεγύμνασας τὸν νεανίσκον οὐδ᾽ ἔγνως εἰ δύναται τούτοις παρακολουθεῖν, ἀλλ᾽ ὡς ἀναγνώστῃ αὐτῷ χρῇ.","st":"1.26"},{"sp":"N","t":"τί οὖν, ἔφη, μὴ δυναμένῃ διανοίᾳ συμπεπλεγμένου ἐπικρίσει παρακολουθεῖν ἔπαινον πιστεύομεν, ψόγον πιστεύομεν, ἐπίκρισιν περὶ τῶν καλῶς ἢ κακῶς γινομένων; κἄν τινα κακῶς λέγῃ, οὗτος ἐπιστρέφεται, κἂν ἐπαινῇ τινα, ἐπαίρεται; ἐν τοῖς οὕτως μικροῖς μὴ εὑρίσκων τὸ ἑξῆς;","st":"1.26"},{"sp":"N","t":"αὕτη οὖν ἀρχὴ τοῦ φιλοσοφεῖν, αἴσθησις τοῦ ἰδίου ἡγεμονικοῦ πῶς ἔχει: μετὰ γὰρ τὸ γνῶναι ὅτι ἀσθενῶς οὐκ ἔτι θελήσει χρῆσθαι αὐτῷ πρὸς τὰ μεγάλα.","st":"1.26"},{"sp":"N","t":"νῦν δὲ μὴ δυνάμενοί τινες τὸν ψωμὸν καταπίνειν σύνταξιν ἀγοράσαντες ἐπιβάλλονται ἐσθίειν. διὰ τοῦτο ἐμοῦσιν ἢ ἀπεπτοῦσιν: εἶτα στρόφοι καὶ κατάρροιαι καὶ πυρετοί. ἔδει δ᾽ ἐφιστάνειν, εἰ δύνανται.","st":"1.26"},{"sp":"N","t":"ἀλλ᾽ ἐν μὲν θεωρίᾳ ῥᾴδιον ἐξελέγξαι τὸν οὐκ εἰδότα, ἐν δὲ τοῖς κατὰ τὸν βίον οὔτε παρέχει ἑαυτόν τις ἐλέγχῳ τόν τ᾽ ἐξελέγξαντα μισοῦμεν. ὁ δὲ Σωκράτης ἔλεγεν ἀνεξέταστον βίον μὴ ζῆν.","st":"1.26"},{"sp":"N","t":"ποσαχῶς αἱ φαντασίαι γίνονται καὶ τίνα πρόχειρα πρὸς αὐτὰς βοηθήματα παρασκευαστέον. τετραχῶς αἱ φαντασίαι γίνονται ἡμῖν: ἢ γὰρ ἔστι τινὰ καὶ οὕτως φαίνεται ἢ οὐκ ὄντα οὐδὲ φαίνεται ὅτι ἔστιν ἢ ἔστι καὶ οὐ φαίνεται ἢ οὐκ ἔστι καὶ φαίνεται.","st":"1.26"},{"sp":"N","t":"λοιπὸν ἐν πᾶσι τούτοις εὐστοχεῖν ἔργον ἐστὶ τοῦ πεπαιδευμένου. ὅ τι δ᾽ ἂν ᾖ τὸ θλῖβον, ἐκείνῳ δεῖ προσάγειν τὴν βοήθειαν. εἰ σοφίσματα ἡμᾶς Πυρρώνεια καὶ Ἀκαδημαικὰ τὰ θλίβοντά ἐστιν, ἐκείνοις προσάγωμεν τὴν βοήθειαν:","st":"1.27"},{"sp":"N","t":"εἰ αἱ τῶν πραγμάτων πιθανότητες, καθ᾽ ἃς φαίνεταί τινα ἀγαθὰ οὐκ ὄντα, ἐκεῖ τὴν βοήθειαν ζητῶμεν: εἰ ἔθος ἐστὶ τὸ θλῖβον, πρὸς ἐκεῖνο τὴν βοήθειαν ἀνευρίσκειν πειρατέον.","st":"1.27"},{"sp":"N","t":"τί οὖν πρὸς ἔθος ἔστιν εὑρίσκειν βοήθημα;","st":"1.27"},{"sp":"N","t":"τὸ ἐναντίον ἔθος. ἀκούεις τῶν ἰδιωτῶν λεγόντων ‘τάλας ἐκεῖνος, ἀπέθανεν: ἀπώλετο ὁ πατὴρ αὐτοῦ, ἡ μήτηρ: ἐξεκόπη, ἀλλὰ καὶ ἄωρος καὶ ἐπὶ ξένης.’","st":"1.27"},{"sp":"N","t":"ἄκουσον τῶν ἐναντίων λόγων, ἀπόσπασον σεαυτὸν τούτων τῶν φωνῶν, ἀντίθες τῷ ἔθει τὸ ἐναντίον ἔθος. πρὸς τοὺς σοφιστικοὺς λόγους τὰ λογικὰ καὶ τὴν ἐν τούτοις γυμνασίαν καὶ τριβήν, πρὸς τὰς τῶν πραγμάτων πιθανότητας τὰς προλήψεις ἐναργεῖς ἐσμηγμένας καὶ προχείρους ἔχειν δεῖ.","st":"1.27"},{"sp":"N","t":"ὅταν θάνατος φαίνηται κακόν, πρόχειρον ἔχειν ὅτι τὰ κακὰ ἐκκλίνειν καθήκει καὶ ἀναγκαῖον ὁ θάνατος. τί γὰρ ποιήσω;","st":"1.27"},{"sp":"N","t":"ποῦ γὰρ αὐτὸν φύγω; ἔστω ἐμὲ εἶναι Σαρπηδόνα τὸν τοῦ Διός, ἵν᾽ οὕτως γενναίως εἴπω ‘ἀπελθὼν ἢ αὐτὸς ἀριστεῦσαι θέλω ἢ ἄλλῳ παρασχεῖν ἀφορμὴν τοῦ ἀριστεῦσαι: εἰ μὴ δύναμαι κατορθῶσαί τι αὐτός, οὐ φθονήσω ἄλλῳ τοῦ ποιῆσαί τι γενναῖον:’ ἔστω ταῦτα ὑπὲρ ἡμᾶς, ἐκεῖνο οὐ πίπτει εἰς ἡμᾶς;","st":"1.27"},{"sp":"N","t":"καὶ ποῦ φύγω τὸν θάνατον; μηνύσατέ μοι τὴν χώραν, μηνύσατε ἀνθρώπους, εἰς οὓς ἀπέλθω, εἰς οὓς οὐ παραβάλλει, μηνύσατε ἐπαοιδήν: εἰ μὴ ἔχω, τί με θέλετε ποιεῖν;","st":"1.27"},{"sp":"N","t":"οὐ δύναμαι τὸν θάνατον ἀποφυγεῖν: τὸ φοβεῖσθαι αὐτὸν μὴ ἀποφύγω, ἀλλ᾽ ἀποθάνω πενθῶν καὶ τρέμων; αὕτη γὰρ γένεσις πάθους θέλειν τι καὶ μὴ γίνεσθαι.","st":"1.27"},{"sp":"N","t":"ἔνθεν ἂν μὲν δύνωμαι τὰ ἐκτὸς μετατιθέναι πρὸς τὴν βούλησιν τὴν ἐμαυτοῦ, μετατίθημι: εἰ δὲ μή, τὸν ἐμποδίζοντα ἐκτυφλῶσαι θέλω.","st":"1.27"},{"sp":"N","t":"πέφυκε γὰρ ὁ ἄνθρωπος μὴ ὑπομένειν ἀφαιρεῖσθαι τοῦ ἀγαθοῦ, μὴ ὑπομένειν περιπίπτειν τῷ κακῷ.","st":"1.27"},{"sp":"N","t":"εἶτα τὸ τελευταῖον, ὅταν μήτε τὰ πράγματα μεταθεῖναι δυνηθῶ μήτε τὸν ἐμποδίζοντα ἐκτυφλῶσαι, κάθημαι καὶ στένω καὶ ὃν δύναμαι λοιδορῶ, τὸν Δία καὶ τοὺς θεοὺς τοὺς ἄλλους: εἰ γὰρ μὴ ἐπιστρέφονταί μου, τί ἐμοὶ καὶ αὐτοῖς;","st":"1.27"},{"sp":"N","t":"‘ναί: ἀλλ᾽ ἀσεβὴς ἔσῃ.’ τί οὖν μοι χεῖρον ἔσται, ὧν ἔστι μοι νῦν; τὸ σύνολον ἐκείνου μεμνῆσθαι, ὅτι, ἐὰν μὴ ἐν τῷ αὐτῷ ᾖ τὸ εὐσεβὲς καὶ συμφέρον, οὐ δύναται σωθῆναι τὸ εὐσεβὲς ἔν τινι. ταῦτα οὐ δοκεῖ ἐπείγοντα;","st":"1.27"},{"sp":"N","t":"ἐρχέσθω καὶ ἀπαντάτω Πυρρώνειος καὶ Ἀκαδημαικός. ἐγὼ μὲν γὰρ τὸ ἐμὸν μέρος οὐκ ἄγω σχολὴν πρὸς ταῦτα οὐδὲ δύναμαι συνηγορῆσαι τῇ συνηθείᾳ.","st":"1.27"},{"sp":"N","t":"εἰ καὶ περὶ ἀγριδίου πραγμάτιον εἶχον, ἄλλον ἂν παρεκάλεσα τὸν συνηγορήσοντα: τίνι οὖν ἀρκοῦμαι κατὰ τὸν τόπον; πῶς μὲν αἴσθησις γίνεται,","st":"1.27"},{"sp":"N","t":"πρότερον δι᾽ ὅλων ἢ ἀπὸ μέρους, ἴσως οὐκ οἶδα ἀπολογίσασθαι, ταράσσει δέ με ἀμφότερα. ὅτι δ᾽ ἐγὼ καὶ σὺ οὐκ ἐσμὲν οἱ αὐτοί, λίαν ἀκριβῶς οἶδα.","st":"1.27"},{"sp":"N","t":"πόθεν τοῦτο; οὐδέποτε καταπίνειν τι θέλων ἐκεῖ φέρω τὸν ψωμόν, ἀλλ᾽ ὧδε: οὐδέποτ᾽ ἄρτον θέλων λαβεῖν τὸ σάρον ἔλαβον, ἀλλ᾽ ἀεὶ ἐπὶ τὸν ἄρτον ἔρχομαι ὡς πρὸς σκοπόν.","st":"1.27"},{"sp":"N","t":"ὑμεῖς δ᾽ αὐτοὶ οἱ τὰς αἰσθήσεις ἀναιροῦντες ἄλλο τι ποιεῖτε; τίς ὑμῶν εἰς βαλανεῖον ἀπελθεῖν θέλων εἰς μυλῶνα ἀπῆλθεν;","st":"1.27"},{"sp":"N","t":"— τί οὖν; οὐ δεῖ κατὰ δύναμιν καὶ τούτων ἀντέχεσθαι, τοῦ τηρῆσαι τὴν συνήθειαν, τοῦ πεφράχθαι πρὸς τὰ κατ᾽ αὐτῆς;","st":"1.27"},{"sp":"N","t":"— καὶ τίς ἀντιλέγει; ἀλλὰ τὸν δυνάμενον, τὸν σχολάζοντα: τὸν δὲ τρέμοντα καὶ ταρασσόμενον καὶ ῥηγνύμενον ἔσωθεν τὴν καρδίαν ἄλλῳ τινὶ δεῖ προσευκαιρεῖν. ὅτι οὐ δεῖ χαλεπαίνειν ἀνθρώποις καὶ τίνα τὰ μικρὰ καὶ μεγάλα ἐν ἀνθρώποις.","st":"1.27"},{"sp":"N","t":"τί ἐστιν αἴτιον τοῦ συγκατατίθεσθαί τινι; τὸ φαίνεσθαι ὅτι ὑπάρχει. τῷ οὖν φαινομένῳ ὅτι οὐχ ὑπάρχει συγκατατίθεσθαι οὐχ οἷόν τε. διὰ τί; ὅτι ἡ φύσις αὕτη ἐστὶ τῆς διανοίας τοῖς μὲν ἀληθέσιν ἐπινεύειν, τοῖς δὲ ψευδέσι δυσαρεστεῖν, πρὸς δὲ τὰ ἄδηλα ἐπέχειν.","st":"1.28"},{"sp":"N","t":"τίς τούτου πίστις; ‘πάθε, εἰ δύνασαι, νῦν ὅτι νύξ ἐστιν.’ οὐχ οἷόν τε. ‘ἀπόπαθε ὅτι ἡμέρα ἐστίν.’ οὐχ οἷόν τε. ‘πάθε ἢ ἀπόπαθε ἀπὸ τοῦ ἀρτίους εἶναι τοὺς ἀστέρας.’ οὐχ οἷόν τε.","st":"1.28"},{"sp":"N","t":"ὅταν οὖν τις συγκατατίθηται τῷ ψεύδει, ἴσθι ὅτι οὐκ ἤθελεν ψεύδει συγκαταθέσθαι: πᾶσα γὰρ ψυχὴ ἄκουσα στέρεται τῆς ἀληθείας, ὡς λέγει Πλάτων: ἀλλὰ ἔδοξεν αὐτῷ τὸ ψεῦδος ἀληθές.","st":"1.28"},{"sp":"N","t":"ἄγε ἐπὶ δὲ τῶν πράξεων τί ἔχομεν τοιοῦτον οἷον ἐνθάδε τὸ ἀληθὲς ἢ τὸ ψεῦδος; τὸ καθῆκον καὶ παρὰ τὸ καθῆκον, τὸ συμφέρον καὶ τὸ ἀσύμφορον, τὸ κατ᾽ ἐμὲ καὶ οὐ κατ᾽ ἐμὲ καὶ ὅσα τούτοις ὅμοια.","st":"1.28"},{"sp":"N","t":"‘οὐ δύναται οὖν τις δοκεῖν μέν, ὅτι συμφέρει αὐτῷ, μὴ αἱρεῖσθαι δ᾽ αὐτό;’ οὐ δύναται.","st":"1.28"},{"sp":"N","t":"πῶς ἡ λέγουσα καὶ μανθάνω μὲν οἷα δρᾶν μέλλω κακά, θυμὸς δὲ κρείσσων τῶν ἐμῶν βουλευμάτων; ὅτι αὐτὸ τοῦτο, τῷ θυμῷ χαρίσασθαι καὶ τιμωρήσασθαι τὸν ἄνδρα, συμφορώτερον ἡγεῖται τοῦ σῶσαι τὰ τέκνα.","st":"1.28"},{"sp":"N","t":"‘ναί: ἀλλ᾽ ἐξηπάτηται.’ δεῖξον αὐτῇ ἐναργῶς ὅτι ἐξηπάτηται καὶ οὐ ποιήσει: μέχρι δ᾽ ἂν οὗ μὴ δεικνύῃς, τίνι ἔχει ἀκολουθῆσαι ἢ τῷ φαινομένῳ;","st":"1.28"},{"sp":"N","t":"οὐδενί. τί οὖν χαλεπαίνεις αὐτῇ, ὅτι πεπλάνηται ἡ ταλαίπωρος περὶ τῶν μεγίστων καὶ ἔχις ἀντὶ ἀνθρώπου γέγονεν; οὐχὶ δ᾽, εἴπερ ἄρα, μᾶλλον ἐλεεῖς, ὡς τοὺς τυφλοὺς ἐλεοῦμεν, ὡς τοὺς χωλούς, οὕτως τοὺς τὰ κυριώτατα τετυφλωμένους καὶ ἀποκεχωλωμένους;","st":"1.28"},{"sp":"N","t":"ὅστις οὖν τούτου μέμνηται καθαρῶς ὅτι ἀνθρώπῳ μέτρον πάσης πράξεως τὸ φαινόμενον （ λοιπὸν ἢ καλῶς φαίνεται ἢ κακῶς: εἰ καλῶς, ἀνέγκλητός ἐστιν: εἰ κακῶς, αὐτὸς ἐζημίωται: οὐ δύναται γὰρ ἄλλος μὲν εἶναι ὁ πεπλανημένος, ἄλλος δ᾽ ὁ βλαπτόμενος ） , οὐδενὶ ὀργισθήσεται, οὐδενὶ χαλεπανεῖ, οὐδένα λοιδορήσει, οὐδένα μέμψεται, οὐ μισήσει, οὐ προσκόψει οὐδενί.","st":"1.28"},{"sp":"N","t":"ὥστε καὶ τὰ οὕτω μεγάλα καὶ δεινὰ ἔργα ταύτην ἔχει τὴν ἀρχήν, τὸ φαινόμενον; ταύτην οὐδ᾽ ἄλλην.","st":"1.28"},{"sp":"N","t":"ἡ Ἰλιὰς οὐδέν ἐστιν ἢ φαντασία καὶ χρῆσις φαντασιῶν. ἐφάνη τῷ Ἀλεξάνδρῳ ἀπάγειν τοῦ Μενελάου τὴν γυναῖκα, ἐφάνη τῇ Ἑλένῃ ἀκολουθῆσαι αὐτῷ.","st":"1.28"},{"sp":"N","t":"εἰ οὖν ἐφάνη τῷ Μενελάῳ παθεῖν ὅτι κέρδος ἐστὶ τοιαύτης γυναικὸς στερηθῆναι, τί ἂν ἐγένετο; ἀπολώλει ἡ Ἰλιὰς οὐ μόνον ἀλλὰ καὶ ἡ Ὀδύσσεια. —","st":"1.28"},{"sp":"N","t":"ἐκ τοιούτου οὖν μικροῦ πράγματος ἤρτηται τὰ τηλικαῦτα; — τίνα δὲ καὶ λέγεις τὰ τηλικαῦτα; πολέμους καὶ στάσεις καὶ ἀπωλείας πολλῶν ἀνθρώπων καὶ κατασκαφὰς πόλεων; καὶ τί μέγα ἔχει ταῦτα; — οὐδέν; —","st":"1.28"},{"sp":"N","t":"τί δ᾽ ἔχει μέγα πολλοὺς βοῦς ἀποθανεῖν καὶ πολλὰ πρόβατα καὶ πολλὰς καλιὰς χελιδόνων ἢ πελαργῶν ἐμπρησθῆναι καὶ κατασκαφῆναι;","st":"1.28"},{"sp":"N","t":"— ὅμοια οὖν ἐστι ταῦτα ἐκείνοις; — ὁμοιότατα. σώματα ἀπώλετο ἀνθρώπων: καὶ βοῶν καὶ προβάτων. οἰκημάτια ἐνεπρήσθη ἀνθρώπων: καὶ πελαργῶν νεοσσιαί.","st":"1.28"},{"sp":"N","t":"τί μέγα ἢ δεινόν; ἢ δεῖξόν μοι τί διαφέρει οἰκία ἀνθρώπου καὶ νεοσσιὰ πελαργοῦ ὡς οἴκησις.","st":"1.28"},{"sp":"N","t":"— ὅμοιον οὖν ἐστι πελαργὸς καὶ ἄνθρωπος; — τί λέγεις; κατὰ τὸ σῶμα ὁμοιότατον. πλὴν ὅτι μὲν ἐκ δοκῶν καὶ κεραμίδων καὶ πλίνθων οἰκοδομεῖται τὰ οἰκίδια, ἡ δ᾽ ἐκ ῥάβδων καὶ πηλοῦ. οὐδενὶ οὖν διαφέρει ἄνθρωπος πελαργοῦ;","st":"1.28"},{"sp":"N","t":"— μὴ γένοιτο: ἀλλὰ τούτοις οὐ διαφέρει. — τίνι οὖν διαφέρει;","st":"1.28"},{"sp":"N","t":"— ζήτει καὶ εὑρήσεις, ὅτι ἄλλῳ διαφέρει. ὅρα μὴ τῷ παρακολουθεῖν οἷς ποιεῖ, ὅρα μὴ τῷ κοινωνικῷ, μὴ τῷ πιστῷ, τῷ αἰδήμονι, τῷ ἀσφαλεῖ, τῷ συνετῷ.","st":"1.28"},{"sp":"N","t":"ποῦ οὖν τὸ μέγα ἐν ἀνθρώποις κακὸν καὶ ἀγαθόν; ὅπου ἡ διαφορά. ἂν σῴζηται τοῦτο καὶ περιτετειχισμένον μένῃ καὶ μὴ διαφθείρηται τὸ αἰδῆμον μηδὲ τὸ πιστὸν μηδὲ τὸ συνετόν, τότε σῴζεται καὶ αὐτός: ἂν δ᾽ ἀπολλύηταί τι τούτων καὶ ἐκπολιορκῆται, τότε καὶ αὐτὸς ἀπόλλυται. καὶ τὰ μεγάλα πράγματα ἐν τούτῳ ἐστίν.","st":"1.28"},{"sp":"N","t":"ἔπταισεν μεγάλα ὁ Ἀλέξανδρος, ὅτ᾽ ἐπῆλθον † φασιν οἱ Ἕλληνες καὶ ὅτε ἐπόρθουν τὴν Τροίαν καὶ ὅτε οἱ ἀδελφοὶ αὐτοῦ ἀπώλλυντο;","st":"1.28"},{"sp":"N","t":"οὐδαμῶς: δι᾽ ἀλλότριον γὰρ ἔργον πταίει οὐδείς: ἀλλὰ τότε πελαργῶν νεοσσιαὶ ἐπορθοῦντο. πταῖσμα δ᾽ ἦν, ὅτε ἀπώλεσε τὸν αἰδήμονα, τὸν πιστόν, τὸν φιλόξενον, τὸν κόσμιον.","st":"1.28"},{"sp":"N","t":"πότ᾽ ἔπταισεν ὁ Ἀχιλλεύς; ὅτε ἀπέθανεν ὁ Πάτροκλος; μὴ γένοιτο: ἀλλ᾽ ὅτε ὠργίζετο, ὅτε κορασίδιον ἔκλαεν, ὅτ᾽ ἐπελάθετο ὅτι πάρεστιν οὐκ ἐπὶ τὸ ἐρωμένας κτᾶσθαι, ἀλλ᾽ ἐπὶ τὸ πολεμεῖν.","st":"1.28"},{"sp":"N","t":"ταῦτ᾽ ἐστὶ τὰ ἀνθρωπικὰ πταίσματα, τοῦτό ἐστιν ἡ πολιορκία, τοῦτό ἐστι κατασκαφή, ὅταν τὰ δόγματα τὰ ὀρθὰ καθαιρῆται, ὅταν ἐκεῖνα διαφθείρηται.","st":"1.28"},{"sp":"N","t":"— ὅταν οὖν γυναῖκες ἄγωνται καὶ παιδία αἰχμαλωτίζηται καὶ ὅταν αὐτοὶ κατασφάζωνται, ταῦτα οὐκ ἔστι κακά;","st":"1.28"},{"sp":"N","t":"— πόθεν τοῦτο προσδοξάζεις; κἀμὲ δίδαξον. — οὔ: ἀλλὰ πόθεν σὺ λέγεις ὅτι οὐκ ἔστι κακά;","st":"1.28"},{"sp":"N","t":"— ἔλθωμεν ἐπὶ τοὺς κανόνας, φέρε τὰς προλήψεις. διὰ τοῦτο γὰρ οὐκ ἔστιν ἱκανῶς θαυμάσαι τὸ γινόμενον. ὅπου βάρη κρῖναι θέλομεν, οὐκ εἰκῇ κρίνομεν: ὅπου τὰ εὐθέα καὶ στρεβλά, οὐκ εἰκῇ:","st":"1.28"},{"sp":"N","t":"ἁπλῶς ὅπου διαφέρει ἡμῖν γνῶναι τὸ κατὰ τὸν τόπον ἀληθές, οὐδέποθ᾽ ἡμῶν οὐδεὶς οὐδὲν εἰκῇ ποιήσει.","st":"1.28"},{"sp":"N","t":"ὅπου δὲ τὸ πρῶτον καὶ μόνον αἴτιόν ἐστι τοῦ κατορθοῦν ἢ ἁμαρτάνειν, τοῦ εὐροεῖν ἢ δυσροεῖν, τοῦ ἀτυχεῖν ἢ εὐτυχεῖν, ἐνθάδε μόνον εἰκαῖοι καὶ προπετεῖς. οὐδαμοῦ ὅμοιόν τι ζυγῷ, οὐδαμοῦ ὅμοιόν τι κανόνι, ἀλλά τι ἐφάνη καὶ εὐθὺς ποιῶ τὸ φανέν.","st":"1.28"},{"sp":"N","t":"κρείσσων γάρ εἰμι τοῦ Ἀγαμέμνονος ἢ τοῦ Ἀχιλλέως, ἵν᾽ ἐκεῖνοι μὲν διὰ τὸ ἀκολουθῆσαι τοῖς φαινομένοις τοιαῦτα κακὰ ποιήσωσι καὶ πάθωσιν, ἐμοὶ δὲ μὴ ἀρκῇ τὸ φαινόμενον;","st":"1.28"},{"sp":"N","t":"καὶ ποία τραγῳδία ἄλλην ἀρχὴν ἔχει; Ἀτρεὺς Εὐριπίδου τί ἐστιν; τὸ φαινόμενον. Οἰδίπους Σοφοκλέους τί ἐστιν; τὸ φαινόμενον. Φοῖνιξ;","st":"1.28"},{"sp":"N","t":"τὸ φαινόμενον. Ἱππόλυτος; τὸ φαινόμενον. τούτου οὖν μηδεμίαν ἐπιμέλειαν ποιεῖσθαι τίνος ὑμῖν δοκεῖ; τίνες δὲ λέγονται οἱ παντὶ τῷ φαινομένῳ ἀκολουθοῦντες; — μαινόμενοι. — ἡμεῖς οὖν ἄλλο τι ποιοῦμεν; περὶ εὐσταθείας. οὐσία τοῦ ἀγαθοῦ προαίρεσις ποιά, τοῦ κακοῦ προαίρεσις ποιά.","st":"1.28"},{"sp":"N","t":"τί οὖν τὰ ἐκτός; ὗλαι τῇ προαιρέσει, περὶ ἃς ἀναστρεφομένη τεύξεται τοῦ ἰδίου ἀγαθοῦ ἢ κακοῦ. πῶς τοῦ ἀγαθοῦ τεύξεται;","st":"1.29"},{"sp":"N","t":"ἂν τὰς ὕλας μὴ θαυμάσῃ. τὰ γὰρ περὶ τῶν ὑλῶν δόγματα ὀρθὰ μὲν ὄντα ἀγαθὴν ποιεῖ τὴν προαίρεσιν, στρεβλὰ δὲ καὶ διεστραμμένα κακήν.","st":"1.29"},{"sp":"N","t":"τοῦτον τὸν νόμον ὁ θεὸς τέθεικεν καὶ φησίν ‘εἰ τι ἀγαθὸν θέλεις, παρὰ σεαυτοῦ λάβε.’ σὺ λέγεις ‘οὔ: ἀλλὰ παρ᾽ ἄλλου.’ μή, ἀλλὰ παρὰ σεαυτοῦ. λοιπὸν ὅταν ἀπειλῇ ὁ τύραννος καὶ μὴ καλῇ, λέγω","st":"1.29"},{"sp":"N","t":"‘τίνι ἀπειλεῖ;’ ἂν λέγῃ ‘δήσω σε,’ φημὶ ὅτι ‘ταῖς χερσὶν ἀπειλεῖ καὶ τοῖς ποσίν.’","st":"1.29"},{"sp":"N","t":"ἂν λέγῃ ‘τραχηλοκοπήσω σε,’ λέγω ‘τῷ τραχήλῳ ἀπειλεῖ.’ ἂν λέγῃ ‘εἰς φυλακήν σε βαλῶ,’ ‘ὅλῳ τῷ σαρκιδίῳ:’ κἂν ἐξορισμὸν ἀπειλῇ, τὸ αὐτό.","st":"1.29"},{"sp":"N","t":"— σοὶ οὖν οὐδὲν ἀπειλεῖ; — εἰ πέπονθα ὅτι ταῦτα οὐδέν ἐστι πρὸς ἐμέ, οὐδέν: εἰ δὲ φοβοῦμαί τι τούτων, ἐμοὶ ἀπειλεῖ.","st":"1.29"},{"sp":"N","t":"τίνα λοιπὸν δέδοικα; τὸν τίνων ὄντα κύριον; τῶν ἐπ᾽ ἐμοί; οὐδὲ εἷς ἐστιν. τῶν οὐκ ἐπ᾽ ἐμοί; καὶ τί μοι αὐτῶν μέλει;","st":"1.29"},{"sp":"N","t":"ὑμεῖς οὖν οἱ φιλόσοφοι διδάσκετε καταφρονεῖν τῶν βασιλέων; — μὴ γένοιτο. τίς ἡμῶν διδάσκει ἀντιποιεῖσθαι πρὸς αὐτούς, ὧν ἐκεῖνοι ἔχουσιν ἐξουσίαν;","st":"1.29"},{"sp":"N","t":"τὸ σωμάτιον λάβε, τὴν κτῆσιν λάβε, τὴν φήμην λάβε, τοὺς περὶ ἐμὲ λάβε. ἄν τινας τούτων ἀναπείθω ἀντιποιεῖσθαι, τῷ ὄντι ἐγκαλείτω μοι.","st":"1.29"},{"sp":"N","t":"‘ναί: ἀλλὰ καὶ τῶν δογμάτων ἄρχειν θέλω.’ καὶ τίς σοι ταύτην τὴν ἐξουσίαν δέδωκεν;","st":"1.29"},{"sp":"N","t":"ποῦ δύνασαι νικῆσαι δόγμα ἀλλότριον; ‘προσάγων,’ φησίν, ‘αὐτῷ φόβον νικήσω.’ ἀγνοεῖς ὅτι αὐτὸ αὑτὸ ἐνίκησεν, οὐχ ὑπ᾽ ἄλλου ἐνικήθη: προαίρεσιν δὲ οὐδὲν ἄλλο νικῆσαι δύναται, πλὴν αὐτὴ ἑαυτήν.","st":"1.29"},{"sp":"N","t":"διὰ τοῦτο καὶ ὁ τοῦ θεοῦ νόμος κράτιστός ἐστι καὶ δικαιότατος: τὸ κρεῖσσον ἀεὶ περιγινέσθω τοῦ χείρονος.","st":"1.29"},{"sp":"N","t":"‘κρείττονές εἰσιν οἱ δέκα τοῦ ἑνός.’ πρὸς τί; πρὸς τὸ δῆσαι, πρὸς τὸ ἀποκτεῖναι, πρὸς τὸ ἀπαγαγεῖν ὅπου θέλουσιν, πρὸς τὸ ἀφελέσθαι τὰ ὄντα. νικῶσιν τοίνυν οἱ δέκα τὸν ἕνα ἐν τούτῳ, ἐν ᾧ κρείσσονές εἰσιν.","st":"1.29"},{"sp":"N","t":"ἐν τίνι οὖν χείρονές εἰσιν; ἂν ὁ μὲν ἔχῃ δόγματα ὀρθά, οἱ δὲ μή. τί οὖν; ἐν τούτῳ δύνανται νικῆσαι; πόθεν; εἰ δ᾽ ἱστάμεθα ἐπὶ ζυγοῦ, οὐκ ἔδει τὸν βαρύτερον καθελκύσαι; Σωκράτης οὖν ἵνα πάθῃ ταῦτα ὑπ᾽ Ἀθηναίων;","st":"1.29"},{"sp":"N","t":"— ἀνδράποδον, τί λέγεις τὸ Σωκράτης; ὡς ἔχει τὸ πρᾶγμα λέγε: ἵν᾽ οὖν τὸ Σωκράτους σωμάτιον ἀπαχθῇ καὶ συρῇ ὑπὸ τῶν ἰσχυροτέρων εἰς δεσμωτήριον καὶ κώνειόν τις δῷ τῷ σωματίῳ τῷ Σωκράτους κἀκεῖνο ἀποψυγῇ;","st":"1.29"},{"sp":"N","t":"ταῦτά σοι φαίνεται θαυμαστά, ταῦτα ἄδικα, ἐπὶ τούτοις ἐγκαλεῖς τῷ θεῷ; οὐδὲν οὖν εἶχε Σωκράτης ἀντὶ τούτων; ποῦ ἦν ἡ οὐσία αὐτῷ τοῦ ἀγαθοῦ;","st":"1.29"},{"sp":"N","t":"τίνι προσσχῶμεν; σοὶ ἢ αὐτῷ; καὶ τί λέγει ἐκεῖνος; ‘ἐμὲ δ᾽ Ἄνυτος καὶ Μέλητος ἀποκτεῖναι μὲν δύνανται, βλάψαι δ᾽ οὔ.’ καὶ πάλιν ‘εἰ ταύτῃ τῷ θεῷ φίλον, ταύτῃ γινέσθω.’","st":"1.29"},{"sp":"N","t":"ἀλλὰ δεῖξον ὅτι χείρονα ἔχων δόγματα κρατεῖ τοῦ κρείττονος ἐν δόγμασιν. οὐ δείξεις: οὐδ᾽ ἐγγύς. νόμος γὰρ τῆς φύσεως. καὶ τοῦ θεοῦ οὗτος τὸ κρεῖσσον ἀεὶ περιγινέσθω τοῦ χείρονος. ἐν τίνι; ἐν ᾧ κρεῖσσόν ἐστιν.","st":"1.29"},{"sp":"N","t":"σῶμα σώματος ἰσχυρότερον, οἱ πλείονες τοῦ ἑνός, ὁ κλέπτης τοῦ μὴ κλέπτου.","st":"1.29"},{"sp":"N","t":"διὰ τοῦτο κἀγὼ τὸν λύχνον ἀπώλεσα, ὅτι ἐν τῷ ἀγρυπνεῖν μου κρείσσων ἦν ὁ κλέπτης. ἀλλ᾽ ἐκεῖνος τοσούτου ὠνήσατο λύχνον: ἀντὶ λύχνου κλέπτης ἐγένετο, ἀντὶ λύχνου ἄπιστος, ἀντὶ λύχνου θηριώδης. τοῦτο ἔδοξεν αὐτῷ λυσιτελεῖν.","st":"1.29"},{"sp":"N","t":"ἔστω: ἀλλ᾽ εἴληπταί μού τις τοῦ ἱματίου καὶ ἕλκει μ᾽ εἰς τὴν ἀγοράν, εἶτα ἐπικραυγάζουσιν ἄλλοι ‘φιλόσοφε, τί σε ὠφέληκε τὰ δόγματα; ἰδοὺ σύρῃ εἰς τὸ δεσμωτήριον, ἰδοὺ μέλλεις τραχηλοκοπεῖσθαι.’","st":"1.29"},{"sp":"N","t":"καὶ ποίαν ἔπραξα ἂν εἰσαγωγήν, ἵν᾽, ἂν ἰσχυρότερος ἐπιλάβηταί μου τοῦ ἱματίου, μὴ σύρωμαι; ἵνα, ἄν με δέκα περισπάσαντες εἰς τὸ δεσμωτήριον ἐμβάλωσιν, μὴ ἐμβληθῶ;","st":"1.29"},{"sp":"N","t":"ἄλλο οὖν οὐδὲν ἔμαθον; ἔμαθον, ἵνα: πᾶν τὸ γινόμενον ἴδω ὅτι, ἂν ἀπροαίρετον ᾖ, οὐδέν ἐστι πρὸς ἐμέ.","st":"1.29"},{"sp":"N","t":"πρὸς τοῦτο οὖν οὐκ ὠφέλησαι; τί οὖν ἐν ἄλλῳ ζητεῖς τὴν ὠφέλειαν ἢ ἐν ᾧ ἔμαθες;","st":"1.29"},{"sp":"N","t":"καθήμενος λοιπὸν ἐν τῇ φυλακῇ λέγω ‘οὗτος ὁ ταῦτα κραυγάζων οὔτε τοῦ σημαινομένου ἀκούει οὔτε τῷ λεγομένῳ παρακολουθεῖ οὔτε ὅλως μεμέληκεν αὐτῷ εἰδέναι περὶ τῶν φιλοσόφων τί λέγουσιν ἢ τί ποιοῦσιν. ἄφες αὐτόν.’","st":"1.29"},{"sp":"N","t":"‘ἀλλ᾽ ἔξελθε πάλιν ἀπὸ τῆς φυλακῆς.’ εἰ μηκέτι χρείαν ἔχητέ μου ἐν τῇ φυλακῇ, ἐξέρχομαι: ἂν πάλιν σχῆτε, εἰσελεύσομαι.","st":"1.29"},{"sp":"N","t":"μέχρι τίνος; μέχρις ἂν οὗ λόγος αἱρῇ συνεῖναί με τῷ σωματίῳ: ὅταν δὲ μὴ αἱρῇ, λάβετε αὐτὸ καὶ ὑγιαίνετε.","st":"1.29"},{"sp":"N","t":"μόνον μὴ ἀλογίστως, μόνον μὴ μαλακῶς, μὴ ἐκ τῆς τυχούσης προφάσεως. πάλιν γὰρ ὁ θεὸς οὐ βούλεται: χρείαν γὰρ ἔχει κόσμου τοιούτου, τῶν ἐπὶ γῆς ἀναστρεφομένων τοιούτων. ἐὰν δὲ σημήνῃ τὸ ἀνακλητικὸν ὡς τῷ Σωκράτει, πείθεσθαι δεῖ τῷ σημαίνοντι ὡς στρατηγῷ.","st":"1.29"},{"sp":"N","t":"τί οὖν; λέγειν δεῖ ταῦτα πρὸς τοὺς πολλούς; — ἵνα τί;","st":"1.29"},{"sp":"N","t":"οὐ γὰρ ἀρκεῖ τὸ αὐτὸν πείθεσθαι; τοῖς γὰρ παιδίοις, ὅταν προσελθόντα κροτῇ καὶ λέγῃ ‘σήμερον Σατορνάλια ἀγαθά,’ λέγομεν ‘οὐκ ἔστιν ἀγαθὰ ταῦτα;’ οὐδαμῶς: ἀλλὰ καὶ αὐτοὶ ἐπικροτοῦμεν.","st":"1.29"},{"sp":"N","t":"καὶ σὺ τοίνυν, ὅταν μεταπεῖσαί τινα μὴ δύνῃ, γίγνωσκε ὅτι παιδίον ἐστὶ καὶ ἐπικρότει αὐτῷ: ἂν δὲ μὴ τοῦτο θέλῃς, σιώπα λοιπόν.","st":"1.29"},{"sp":"N","t":"τούτων δεῖ μεμνῆσθαι καὶ κληθέντα εἴς τινα τοιαύτην περίστασιν εἰδέναι, ὅτι ἐλήλυθεν ὁ καιρὸς τοῦ ἀποδεῖξαι, εἰ πεπαιδεύμεθα. νέος γὰρ ἀπὸ σχολῆς ἀπιὼν εἰς περίστασιν ὅμοιός ἐστι τῷ μεμελετηκότι συλλογισμοὺς ἀναλύειν, κἄν τις εὔλυτον αὐτῷ προτείνῃ, λέγει ‘μᾶλλόν μοι πεπλεγμένον κομψῶς προτείνατε, ἵνα γυμνασθῶ.’ καὶ οἱ ἀθληταὶ τοῖς κούφοις νεανίσκοις δυσαρεστοῦσιν:","st":"1.29"},{"sp":"N","t":"‘οὐ βαστάζει με,’ φησίν. οὗτός ἐστιν εὐφυὴς νέος. οὔ: ἀλλὰ καλέσαντος τοῦ καιροῦ κλάειν δεῖ καὶ λέγειν ‘ἤθελον ἔτι μανθάνειν.’ τίνα; εἰ ταῦτα οὐκ ἔμαθες οὐχ ὥστ᾽ ἔργῳ δεῖξαι, πρὸς τί αὐτὰ ἔμαθες;","st":"1.29"},{"sp":"N","t":"ἐγώ τινα οἶμαι τῶν καθημένων ἐνταῦθα ὠδίνειν αὐτὸν ἐφ᾽ ἑαυτοῦ καὶ λέγειν ‘ἐμοὶ νῦν περίστασιν μὴ ἔρχεσθαι τοιαύτην, ὁποία τούτῳ ἐλήλυθεν; ἐμὲ νῦν κατατριβῆναι καθήμενον ἐν γωνίᾳ δυνάμενον στεφανωθῆναι Ὀλύμπια; πότε τις ἐμοὶ καταγγελεῖ τοιοῦτον ἀγῶνα;’ οὕτως ἔχειν ἔδει πάντας ὑμᾶς.","st":"1.29"},{"sp":"N","t":"ἀλλ᾽ ἐν μὲν τοῖς Καίσαρος μονομάχοις εἰσί τινες οἱ ἀγανακτοῦντες ὅτι οὐδεὶς αὐτοὺς προάγει οὐδὲ ζευγνύει καὶ εὔχονται τῷ θεῷ καὶ προσέρχονται τοῖς ἐπιτρόποις δεόμενοι μονομαχῆσαι, ἐξ ὑμῶν δ᾽ οὐδεὶς φανήσεται τοιοῦτος;","st":"1.29"},{"sp":"N","t":"ἤθελον πλεῦσαι ἐπ᾽ αὐτὸ τοῦτο καὶ ἰδεῖν, τί μου ποιεῖ ὁ ἀθλητής, πῶς μελετᾷ τὴν ὑπόθεσιν.","st":"1.29"},{"sp":"N","t":"‘οὐ θέλω,’ φησίν, ‘τοιαύτην.’ ἐπὶ σοὶ γάρ ἐστι λαβεῖν ἣν θέλεις ὑπόθεσιν; δέδοταί σοι σῶμα τοιοῦτον, γονεῖς τοιοῦτοι, ἀδελφοὶ τοιοῦτοι, πατρὶς τοιαύτη, τάξις ἐν αὐτῇ τοιαύτη: εἶτά μοι λέγεις ἐλθὼν ‘ἄλλαξόν μοι τὴν ὑπόθεσιν.’ εἶτα οὐκ ἔχεις ἀφορμὰς πρὸς τὸ χρήσασθαι","st":"1.29"},{"sp":"N","t":"τοῖς δοθεῖσιν; σόν ἐστι προτεῖναι, ἐμὸν μελετῆσαι καλῶς. οὔ: ἀλλὰ ‘μὴ τοιοῦτό μοι προβάλῃς τροπικόν, ἀλλὰ τοιοῦτον: μὴ τοιαύτην ἐπενέγκῃς τὴν ἐπιφοράν, ἀλλὰ τοιαύτην.’","st":"1.29"},{"sp":"N","t":"ἔσται χρόνος τάχα, ἐν ᾧ οἱ τραγῳδοὶ οἰήσονται ἑαυτοὺς εἶναι προσωπεῖα καὶ ἐμβάδας καὶ τὸ σύρμα. ἄνθρωπε, ταῦτα ὕλην ἔχεις καὶ ὑπόθεσιν.","st":"1.29"},{"sp":"N","t":"φθέγξαι τι, ἵνα εἰδῶμεν πότερον τραγῳδὸς εἶ ἢ γελωτοποιός: κοινὰ γὰρ ἔχουσι τὰ ἄλλα ἀμφότεροι.","st":"1.29"},{"sp":"N","t":"διὰ τοῦτο ἂν ἀφέλῃ τις αὐτοῦ καὶ τὰς ἐμβάδας καὶ τὸ προσωπεῖον καὶ ἐν εἰδώλῳ αὐτὸν προαγάγῃ, ἀπώλετο ὁ τραγῳδὸς ἢ μένει; ἂν φωνὴν ἔχῃ, μένει. καὶ ἐνθάδε.","st":"1.29"},{"sp":"N","t":"‘λάβε ἡγεμονίαν.’ λαμβάνω καὶ λαβὼν δεικνύω, πῶς ἄνθρωπος ἀναστρέφεται πεπαιδευμένος.","st":"1.29"},{"sp":"N","t":"‘θὲς τὴν πλατύσημον καὶ ἀναλαβὼν ῥάκη πρόσελθε ἐν προσώπῳ τοιούτῳ.’ τί οὖν; οὐ δέδοταί μοι καλὴν φωνὴν εἰσενεγκεῖν;","st":"1.29"},{"sp":"N","t":"‘πῶς οὖν ἀναβαίνεις νῦν;’ ὡς μάρτυς ὑπὸ τοῦ θεοῦ κεκλημένος.","st":"1.29"},{"sp":"N","t":"‘ἔρχου σὺ καὶ μαρτύρησόν μοι: σὺ γὰρ ἄξιος εἶ προαχθῆναι μάρτυς. ὑπ᾽ ἐμοῦ. μή τι τῶν ἐκτὸς τῆς προαιρέσεως ἀγαθόν ἐστιν ἢ κακόν; μή τινα βλάπτω; μή τι ἐπ᾽ ἄλλῳ τὴν ὠφέλειαν ἐποίησα τὴν ἑκάστου ἢ ἐπ᾽ αὐτῷ;’","st":"1.29"},{"sp":"N","t":"τίνα μαρτυρίαν δίδως τῷ θεῷ; ‘ἐν δεινοῖς εἰμι, κύριε, καὶ δυστυχῶ, οὐδείς μου ἐπιστρέφεται, οὐδείς μοι δίδωσιν οὐδέν, πάντες ψέγουσιν, κακολογοῦσιν.’","st":"1.29"},{"sp":"N","t":"ταῦτα μέλλεις μαρτυρεῖν καὶ καταισχύνειν τὴν κλῆσιν ἣν κέκληκεν, ὅτι σε ἐτίμησεν ταύτην τὴν τιμὴν καὶ ἄξιον ἡγήσατο προσαγαγεῖν εἰς μαρτυρίαν τηλικαύτην; ἀλλ᾽ ἀπεφήνατο ὁ ἔχων τὴν ἐξουσίαν","st":"1.29"},{"sp":"N","t":"‘κρίνω σε ἀσεβῆ καὶ ἀνόσιον εἶναι.’ τί σοι γέγονεν; ‘ἐκρίθην ἀσεβὴς καὶ ἀνόσιος εἶναι.’","st":"1.29"},{"sp":"N","t":"ἄλλο οὐδέν; ‘οὐδέν.’ εἰ δὲ περὶ συνημμένου τινὸς ἐπικεκρίκει καὶ ἐδεδώκει ἀπόφασιν ‘τὸ εἰ ἡμέρα ἐστίν, φῶς ἐστιν κρίνω ψεῦδος εἶναι,’ τί ἐγεγόνει τῷ συνημμένῳ; τίς ἐνθάδε κρίνεται, τίς κατακέκριται; τὸ συνημμένον ἢ ὁ ἐξαπατηθεὶς περὶ αὐτοῦ;","st":"1.29"},{"sp":"N","t":"οὗτος οὖν τίς ποτε ὁ ἔχων ἐξουσίαν τοῦ ἀποφήνασθαί τι περὶ σοῦ; οἶδεν τί ἐστι τὸ εὐσεβὲς ἢ τὸ ἀσεβές; μεμελέτηκεν αὐτό; μεμάθηκεν; ποῦ; παρὰ τίνι;","st":"1.29"},{"sp":"N","t":"εἶτα μουσικὸς μὲν οὐκ ἐπιστρέφεται αὐτοῦ ἀποφαινομένου περὶ τῆς νήτης ὅτι ἐστὶν ὑπάτη οὐδὲ γεωμετρικός, ἂν ἐπικρίνῃ τὰς ἀπὸ κέντρου πρὸς τὸν κύκλον προσπιπτούσας μὴ εἶναι ἴσας:","st":"1.29"},{"sp":"N","t":"ὁ δὲ ταῖς ἀληθείαις πεπαιδευμένος ἀνθρώπου ἀπαιδεύτου ἐπιστραφήσεται ἐπικρίνοντός τι περὶ ὁσίου καὶ ἀνοσίου καὶ ἀδίκου καὶ δικαίου; ὦ πολλῆς ἀδικίας τῶν πεπαιδευμένων. ταῦτα οὖν ἔμαθες ἐνταῦθα;","st":"1.29"},{"sp":"N","t":"οὐ θέλεις τὰ μὲν λογάρια τὰ περὶ τούτων ἄλλοις ἀφεῖναι, ἀταλαιπώροις ἀνθρωπαρίοις, ἵν᾽ ἐν γωνίᾳ καθεζόμενοι μισθάρια λαμβάνωσιν ἢ γογγρύζωσιν, ὅτι οὐδεὶς αὐτοῖς παρέχει οὐδέν, σὺ δὲ χρῆσθαι παρελθὼν οἷς ἔμαθες;","st":"1.29"},{"sp":"N","t":"οὐ γὰρ λογάριά ἐστι τὰ λείποντα νῦν, ἀλλὰ γέμει τὰ βιβλία τῶν Στωικῶν λογαρίων. τί οὖν τὸ λεῖπόν ἐστιν; ὁ χρησόμενος, ὁ ἔργῳ μαρτυρήσων τοῖς λόγοις.","st":"1.29"},{"sp":"N","t":"τοῦτό μοι τὸ πρόσωπον ἀνάλαβε, ἵνα μηκέτι παλαιοῖς ἐν τῇ σχολῇ παραδείγμασι χρώμεθα, ἀλλὰ ἔχωμέν τι καὶ καθ᾽ ἡμᾶς παράδειγμα.","st":"1.29"},{"sp":"N","t":"ταῦτα οὖν τίνος ἐστὶ θεωρεῖν; τοῦ σχολάζοντος. ἔστι γὰρ φιλοθέωρόν τι ζῷον ὁ ἄνθρωπος.","st":"1.29"},{"sp":"N","t":"ἀλλ᾽ αἰσχρόν ἐστι θεωρεῖν ταῦτα οὕτως ὡς οἱ δραπέται: ἀλλ᾽ ἀπερισπάστως καθῆσθαι καὶ ἀκούειν νῦν μὲν τραγῳδοῦ νῦν δὲ κιθαρῳδοῦ, οὐχ ὡς ἐκεῖνοι ποιοῦσιν. ἅμα μὲν ἐπέστη καὶ ἐπῄνεσεν τὸν τραγῳδόν, ἅμα δὲ περιεβλέψατο: εἶτα ἄν τις φθέγξηται κύριον, εὐθὺς σεσόβηνται, ταράσσονται.","st":"1.29"},{"sp":"N","t":"αἰσχρόν ἐστιν οὕτως καὶ τοὺς φιλοσόφους θεωρεῖν τὰ ἔργα τῆς φύσεως. τί γάρ ἐστι κύριος; ἄνθρωπος ἀνθρώπου κύριος οὐκ ἔστιν, ἀλλὰ θάνατος καὶ ζωὴ καὶ ἡδονὴ καὶ πόνος.","st":"1.29"},{"sp":"N","t":"ἐπεὶ χωρὶς τούτων ἄγαγέ μοι τὸν Καίσαρα καὶ ὄψει πῶς εὐσταθῶ. ὅταν δὲ μετὰ τούτων ἔλθῃ βροντῶν καὶ ἀστράπτων, ἐγὼ δὲ ταῦτα φοβῶμαι, τί ἄλλο ἢ ἐπέγνωκα τὸν κύριον ὡς ὁ δραπέτης;","st":"1.29"},{"sp":"N","t":"μέχρι δ᾽ ἂν οὗ τινα ἀνοχὴν ἀπὸ τούτων ἔχω, ὡς δραπέτης ἐφίσταται θεάτρῳ οὕτως κἀγώ: λούομαι, πίνω, ᾁδω, πάντα δὲ μετὰ φόβου καὶ ταλαιπωρίας.","st":"1.29"},{"sp":"N","t":"ἐὰν δ᾽ ἐμαυτὸν ἀπολύσω τῶν δεσποτῶν, τοῦτ᾽ ἔστιν ἐκείνων, δι᾽ ἃ οἱ δεσπόται εἰσὶ φοβεροί, ποῖον ἔτι πρᾶγμα ἔχω, ποῖον ἔτι κύριον;","st":"1.29"},{"sp":"N","t":"τί οὖν; κηρύσσειν δεῖ ταῦτα πρὸς πάντας; — οὔ, ἀλλὰ τοῖς ἰδιώταις συμπεριφέρεσθαι καὶ λέγειν ‘οὗτος ὃ αὑτῷ ἀγαθὸν οἴεται τοῦτο κἀμοὶ συμβουλεύει: συγγιγνώσκω αὐτῷ.’","st":"1.29"},{"sp":"N","t":"καὶ γὰρ Σωκράτης συνεγίγνωσκεν τῷ ἐπὶ τῆς φυλακῆς κλάοντι, ὅτι ἔμελλεν πίνειν τὸ φάρμακον, καὶ λέγει ‘ὡς γενναίως ἡμᾶς ἀποδεδάκρυκεν.’","st":"1.29"},{"sp":"N","t":"μή τι οὖν ἐκείνῳ λέγει ὅτι ‘διὰ τοῦτο τὰς γυναῖκας ἀπελύσαμεν;’ ἀλλὰ τοῖς γνωρίμοις, τοῖς δυναμένοις αὐτὰ ἀκοῦσαι: ἐκείνῳ δὲ συμπεριφέρεται ὡς παιδίῳ. τί δεῖ πρόχειρον ἔχειν ἐν ταῖς περιστάσεσιν. ὅταν εἰσίῃς πρός τινα τῶν ὑπερεχόντων, μέμνησο ὅτι καὶ ἄλλος ἄνωθεν βλέπει τὰ γιγνόμενα καὶ ὅτι ἐκείνῳ σε δεῖ μᾶλλον ἀρέσκειν ἢ τούτῳ.","st":"1.29"},{"sp":"N","t":"ἐκεῖνος οὖν σου πυνθάνεται ‘φυγὴν καὶ φυλακὴν καὶ δεσμὰ καὶ θάνατον καὶ ἀδοξίαν τί ἔλεγες ἐν τῇ σχολῇ;’ ‘ἐγὼ ἀδιάφορα.’","st":"1.30"},{"sp":"N","t":"‘νῦν οὖν τίνα αὐτὰ λέγεις; μή τι ἐκεῖνα ἠλλάγη;’ ‘οὔ.’ ‘σὺ οὖν ἠλλάγης;’ ‘οὔ.’ ‘λέγε οὖν τίνα ἐστὶν ἀδιάφορα.’ ‘τὰ ἀπροαίρετα.’ ‘λέγε καὶ τὰ ἑξῆς.’","st":"1.30"},{"sp":"N","t":"‘ἀπροαίρετα οὐδὲν πρὸς ἐμέ.’ ‘λέγε καὶ τὰ ἀγαθὰ τίνα ὑμῖν ἐδόκει;’ ‘προαίρεσις οἵα δεῖ καὶ χρῆσις φαντασιῶν.’ ‘τέλος δὲ τί;’ ‘τὸ σοὶ ἀκολουθεῖν.’","st":"1.30"},{"sp":"N","t":"‘ταῦτα καὶ νῦν λέγεις;’ ‘ταὐτὰ καὶ νῦν λέγω.’ ἄπειθι λοιπὸν ἔσω θαρρῶν καὶ μεμνημένος τούτων καὶ ὄψει τί ἐστι νέος μεμελετηκὼς ἃ δεῖ ἐν ἀνθρώποις ἀμελετήτοις.","st":"1.30"},{"sp":"N","t":"ἐγὼ μὲν νὴ τοὺς θεοὺς φαντάζομαι ὅτι πείσῃ τὸ τοιοῦτον ‘τί οὕτως μεγάλα καὶ πολλὰ παρασκευαζόμεθα πρὸς τὸ μηδέν;","st":"1.30"},{"sp":"N","t":"τοῦτο ἦν ἡ ἐξουσία; τοῦτο τὰ πρόθυρα, οἱ κοιτωνῖται, οἱ ἐπὶ τῆς μαχαίρας; τούτων ἕνεκα τοὺς πολλοὺς λόγους ἤκουον; ταῦτα οὐδὲν ἦν, ἐγὼ δ᾽ ὡς μεγάλα παρεσκευαζόμην.’","st":"1.30"},{"sp":"HDR","t":"Βιβλίον βʹ","st":"2.1"},{"sp":"N","t":"ἐναντίον γάρ πως δοκεῖ τῷ θαρραλέῳ τὸ εὐλαβές, τὰ δ᾽ ἐναντία οὐδαμῶς συνυπάρχει.","st":"2.1"},{"sp":"N","t":"τὸ δὲ φαινόμενον πολλοῖς ἐν τῷ τόπῳ παράδοξον δοκεῖ μοι τοιούτου τινὸς ἔχεσθαι: εἰ μὲν γὰρ πρὸς ταὐτὰ ἠξιοῦμεν χρῆσθαι τῇ τ᾽ εὐλαβείᾳ καὶ τῷ θάρσει, δικαίως ἂν ἡμᾶς ᾐτιῶντο ὡς τὰ ἀσύνακτα συνάγοντας.","st":"2.1"},{"sp":"N","t":"νῦν δὲ τί δεινὸν ἔχει τὸ λεγόμενον; εἰ γὰρ ὑγιῆ ταῦτ᾽ ἐστι τὰ πολλάκις μὲν εἰρημένα, πολλάκις δ᾽ ἀποδεδειγμένα, ὅτι ἡ οὐσία τοῦ ἀγαθοῦ ἔστιν ἐν χρήσει φαντασιῶν καὶ τοῦ κακοῦ ὡσαύτως, τὰ δ᾽ ἀπροαίρετα οὔτε τὴν τοῦ κακοῦ δέχεται φύσιν οὔτε τὴν τοῦ ἀγαθοῦ,","st":"2.1"},{"sp":"N","t":"τί παράδοξον ἀξιοῦσιν οἱ φιλόσοφοι, εἰ λέγουσιν ‘ὅπου μὲν τὰ ἀπροαίρετα, ἐκεῖ τὸ θάρσος ἔστω σοι, ὅπου δὲ τὰ προαιρετικά, ἐκεῖ ἡ εὐλάβεια;’","st":"2.1"},{"sp":"N","t":"εἰ γὰρ ἐν κακῇ προαιρέσει τὸ κακόν, πρὸς μόνα ταῦτα χρῆσθαι ἄξιον εὐλαβείᾳ: εἰ δὲ τὰ ἀπροαίρετα καὶ μὴ ἐφ᾽ ἡμῖν οὐδὲν πρὸς ἡμᾶς, πρὸς ταῦτα τῷ θάρσει χρηστέον.","st":"2.1"},{"sp":"N","t":"καὶ οὕτως ἅμα μὲν εὐλαβεῖς ἅμα δὲ θαρραλέοι ἐσόμεθα καὶ νὴ Δία διὰ τὴν εὐλάβειαν θαρραλέοι. διὰ γὰρ τὸ εὐλαβεῖσθαι τὰ ὄντως κακὰ συμβήσεται θαρρεῖν ἡμῖν πρὸς τὰ μὴ οὕτως ἔχοντα.","st":"2.1"},{"sp":"N","t":"λοιπὸν ἡμεῖς τὸ τῶν ἐλάφων πάσχομεν: ὅτε φοβοῦνται καὶ φεύγουσιν αἱ ἔλαφοι τὰ πτερά, ποῦ τρέπονται καὶ πρὸς τίνα ἀναχωροῦσιν ὡς ἀσφαλῆ; πρὸς τὰ δίκτυα: καὶ οὕτως ἀπόλλυνται ἐναλλάξασαι τὰ φοβερὰ καὶ τὰ θαρραλέα.","st":"2.1"},{"sp":"N","t":"οὕτως καὶ ἡμεῖς ποῦ χρώμεθα τῷ φόβῳ; πρὸς τὰ ἀπροαίρετα. ἐν τίσιν πάλιν θαρροῦντες ἀναστρεφόμεθα ὡς οὐδενὸς ὄντος δεινοῦ; ἐν τοῖς προαιρετικοῖς.","st":"2.1"},{"sp":"N","t":"ἐξαπατηθῆναι ἢ προπεσεῖν ἢ ἀναίσχυντόν τι ποιῆσαι ἢ μετ᾽ ἐπιθυμίας αἰσχρᾶς ὀρεχθῆναί τινος οὐδὲν διαφέρει ἡμῖν, ἂν μόνον ἐν τοῖς ἀπροαιρέτικοις εὐστοχῶμεν. ὅπου δὲ θάνατος ἢ φυγὴ ἢ πόνος ἢ ἀδοξία, ἐκεῖ τὸ ἀναχωρητικόν, ἐκεῖ τὸ σεσοβημένον.","st":"2.1"},{"sp":"N","t":"τοιγαροῦν ὥσπερ εἰκὸς τοὺς περὶ τὰ μέγιστα διαμαρτάνοντας τὸ μὲν φύσει θαρραλέον θρασὺ κατασκευάζομεν, ἀπονενοημένον, ἰταμόν, ἀναίσχυντον, τὸ δ᾽ εὐλαβὲς φύσει καὶ αἰδῆμον δειλὸν καὶ ταπεινόν, φόβων καὶ ταραχῶν μεστόν.","st":"2.1"},{"sp":"N","t":"ἂν γάρ τις ἐκεῖ μεταθῇ τὸ εὐλαβές, ὅπου προαίρεσις καὶ ἔργα προαιρέσεως, εὐθὺς ἅμα τῷ θέλειν εὐλαβεῖσθαι καὶ ἐπ᾽ αὐτῷ κειμένην ἕξει τὴν ἔκκλισιν: ἂν δ᾽ ὅπου τὰ μὴ ἐφ᾽ ἡμῖν ἐστι καὶ ἀπροαίρετα, πρὸς τὰ ἐπ᾽ ἄλλοις ὄντα τὴν ἔκκλισιν ἔχων ἀναγκαίως φοβήσεται, ἀκαταστατήσει, ταραχθήσεται.","st":"2.1"},{"sp":"N","t":"οὐ γὰρ θάνατος ἢ πόνος φοβερόν, ἀλλὰ τὸ φοβεῖσθαι πόνον ἢ θάνατον. διὰ τοῦτο ἐπαινοῦμεν τὸν εἰπόντα ὅτι οὐ κατθανεῖν γὰρ δεινόν, ἀλλ᾽ αἰσχρῶς θανεῖν.","st":"2.1"},{"sp":"N","t":"ἔδει οὖν πρὸς μὲν τὸν θάνατον τὸ θάρσος ἐστράφθαι, πρὸς δὲ τὸν φόβον τοῦ θανάτου τὴν εὐλάβειαν: νῦν δὲ τὸ ἐναντίον πρὸς μὲν τὸν θάνατον τὴν φυγήν, πρὸς δὲ τὸ περὶ αὐτοῦ δόγμα τὴν ἀνεπιστρεψίαν καὶ τὸ †","st":"2.1"},{"sp":"N","t":"ἀφειδὲς καὶ τὸ ἀδιαφορητικόν. ταῦτα δ᾽ ὁ Σωκράτης καλῶς ποιῶν μορμολύκεια ἐκάλει. ὡς γὰρ τοῖς παιδίοις τὰ προσωπεῖα φαίνεται δεινὰ καὶ φοβερὰ δι᾽ ἀπειρίαν, τοιοῦτόν τι καὶ ἡμεῖς πάσχομεν πρὸς τὰ πράγματα δι᾽ οὐδὲν ἄλλο ἢ ὥσπερ καὶ τὰ παιδία πρὸς τὰς μορμολυκείας.","st":"2.1"},{"sp":"N","t":"τί γάρ ἐστι παιδίον; ἄγνοια. τί ἐστι παιδίον; ἀμαθία. ἐπεὶ ὅπου οἶδεν, κἀκεῖνα οὐδὲν ἡμῶν ἔλαττον ἔχει.","st":"2.1"},{"sp":"N","t":"θάνατος τί ἐστιν; μορμολύκειον. στρέψας αὐτὸ κατάμαθε: ἰδοῦ, πῶς οὐ δάκνει. τὸ σωμάτιον δεῖ χωρισθῆναι τοῦ πνευματίου, ὡς πρότερον ἐκεχώριστο, ἢ νῦν ἢ ὕστερον. τί οὖν ἀγανακτεῖς, εἰ νῦν; εἰ γὰρ μὴ νῦν, ὕστερον.","st":"2.1"},{"sp":"N","t":"διὰ τί; ἵνα ἡ περίοδος ἀνύηται τοῦ κόσμου: χρείαν γὰρ ἔχει τῶν μὲν ἐνισταμένων, τῶν δὲ μελλόντων, τῶν δ᾽ ἠνυσμένων.","st":"2.1"},{"sp":"N","t":"πόνος τί ἐστιν; μορμολύκειον. στρέψον αὐτὸ καὶ κατάμαθε. τραχέως κινεῖται τὸ σαρκίδιον, εἶτα πάλιν λείως. ἄν σοι μὴ λυσιτελῇ, ἡ θύρα ἤνοικται: ἂν λυσιτελῇ, φέρε.","st":"2.1"},{"sp":"N","t":"πρὸς πάντα γὰρ ἠνοῖχθαι δεῖ τὴν θύραν: καὶ πρᾶγμα οὐκ ἔχομεν.","st":"2.1"},{"sp":"N","t":"τίς οὖν τούτων τῶν δογμάτων καρπός; ὅνπερ δεῖ κάλλιστόν τ᾽ εἶναι καὶ πρεπωδέστατον τοῖς τῷ ὄντι παιδευομένοις, ἀταραξία ἀφοβία ἐλευθερία.","st":"2.1"},{"sp":"N","t":"οὐ γὰρ τοῖς πολλοῖς περὶ τούτων πιστευτέον, οἳ λέγουσιν μόνοις ἐξεῖναι παιδεύεσθαι τοῖς ἐλευθέροις, ἀλλὰ τοῖς φιλοσόφοις μᾶλλον, οἳ λέγουσι μόνους τοὺς παιδευθέντας ἐλευθέρους εἶναι.","st":"2.1"},{"sp":"N","t":"— πῶς τοῦτο; — οὕτως: νῦν ἄλλο τί ἐστιν ἐλευθερία ἢ τὸ ἐξεῖναι ὡς βουλόμεθα διεξάγειν; ‘οὐδέν.’ λέγετε δή μοι, ὦ ἄνθρωποι, βούλεσθε ζῆν ἁμαρτάνοντες; ‘οὐ βουλόμεθα.’ οὐδεὶς τοίνυν ἁμαρτάνων ἐλεύθερός ἐστιν.","st":"2.1"},{"sp":"N","t":"βούλεσθε ζῆν φοβούμενοι, βούλεσθε λυπούμενοι, βούλεσθε ταρασσόμενοι; ‘οὐδαμῶς.’ οὐδεὶς ἄρα οὔτε φοβούμενος οὔτε λυπούμενος οὔτε ταρασσόμενος ἐλεύθερός ἐστιν, ὅστις δ᾽ ἀπήλλακται λυπῶν καὶ φόβων καὶ ταραχῶν, οὗτος τῇ αὐτῇ ὁδῷ καὶ τοῦ δουλεύειν ἀπήλλακται.","st":"2.1"},{"sp":"N","t":"πῶς οὖν ἔτι ὑμῖν πιστεύσομεν, ὦ φίλτατοι νομοθέται; οὐκ ἐπιτρέπομεν παιδεύεσθαι, εἰ μὴ τοῖς ἐλευθέροις; οἱ φιλόσοφοι γὰρ λέγουσιν ὅτι οὐκ ἐπιτρέπομεν ἐλευθέροις εἶναι εἰ μὴ τοῖς πεπαιδευμένοις, τοῦτό ἐστιν ὁ θεὸς οὐκ ἐπιτρέπει.","st":"2.1"},{"sp":"N","t":"— ὅταν οὖν στρέψῃ τις ἐπὶ στρατηγοῦ τὸν αὑτοῦ δοῦλον, οὐδὲν ἐποίησεν; — ἐποίησεν. — τί; — ἔστρεψεν τὸν αὑτοῦ δοῦλον ἐπὶ στρατηγοῦ. — ἄλλο οὐδέν; — ναί: καὶ εἰκοστὴν αὐτοῦ δοῦναι ὀφείλει.","st":"2.1"},{"sp":"N","t":"— τί οὖν; ὁ ταῦτα παθὼν οὐ γέγονεν ἐλεύθερος; — οὐ μᾶλλον ἢ ἀτάραχος.","st":"2.1"},{"sp":"N","t":"ἐπεὶ σὺ ὁ ἄλλους στρέφειν δυνάμενος οὐδένα ἔχεις κύριον; οὐκ ἀργύριον, οὐ κοράσιον, οὐ παιδάριον, οὐ τὸν τύραννον, οὐ φίλον τινὰ τοῦ τυράννου; τί οὖν τρέμεις ἐπί τινα τοιαύτην ἀπιὼν περίστασιν; διὰ τοῦτο λέγω πολλάκις","st":"2.1"},{"sp":"N","t":"‘ταῦτα μελετᾶτε καὶ ταῦτα πρόχειρα ἔχετε, πρὸς τίνα δεῖ τεθαρρηκέναι καὶ πρὸς τίνα εὐλαβῶς διακεῖσθαι, ὅτι πρὸς τὰ ἀπροαίρετα θαρρεῖν, εὐλαβεῖσθαι τὰ προαιρετικά.’","st":"2.1"},{"sp":"N","t":"— ἀλλ᾽ οὐκ ἀνέγνων σοι οὐδ᾽ ἔγνως τί ποιῶ.","st":"2.1"},{"sp":"N","t":"— ἐν τίνι; ἐν λεξειδίοις. ἔχε σου τὰ λεξείδια: δεῖξον, πῶς ἔχεις πρὸς ὄρεξιν καὶ ἔκκλισιν, εἰ μὴ ἀποτυγχάνεις ὧν θέλεις, εἰ μὴ περιπίπτεις οἷς οὐ θέλεις. ἐκεῖνα δὲ τὰ περιόδια, ἂν νοῦν ἔχῃς, ἄρας πού ποτε ἀπαλείψεις.","st":"2.1"},{"sp":"N","t":"— τί οὖν; Σωκράτης οὐκ ἔγραφεν; — καὶ τίς τοσαῦτα; ἀλλὰ πῶς; ἐπεὶ μὴ ἐδύνατο ἔχειν ἀεὶ τὸν ἐλέγχοντα αὐτοῦ τὰ δόγματα ἢ ἐλεγχθησόμενον ἐν τῷ μέρει, αὐτὸς ἑαυτὸν ἤλεγχεν καὶ ἐξήταζεν καὶ ἀεὶ μίαν γέ τινα πρόληψιν ἐγύμναζεν χρηστικῶς.","st":"2.1"},{"sp":"N","t":"ταῦτα γράφει φιλόσοφος: λεξείδια δὲ καὶ † ἡ ὁδός, ἣν λέγω, ἄλλοις ἀφίησι, τοῖς ἀναισθήτοις ἢ τοῖς μακαρίοις, τοῖς σχολὴν ἄγουσιν ὑπὸ ἀταραξίας ἢ τοῖς μηδὲν τῶν ἑξῆς ὑπολογιζομένοις διὰ μωρίαν.","st":"2.1"},{"sp":"N","t":"καὶ νῦν καιροῦ καλοῦντος ἐκεῖνα δείξεις ἀπελθὼν καὶ ἀναγνώσῃ καὶ ἐμπερπερεύσῃ; ‘ἰδοῦ, πῶς διαλόγους συντίθημι.’","st":"2.1"},{"sp":"N","t":"μή, ἄνθρωπε, ἀλλ᾽ ἐκεῖνα μᾶλλον ‘ἰδοῦ, πῶς ὀρεγόμενος οὐκ ἀποτυγχάνω. ἰδοῦ, πῶς ἐκκλίνων οὐ περιπίπτω. φέρε θάνατον καὶ γνώσῃ: φέρε πόνους, φέρε δεσμωτήριον, φέρε ἀδοξίαν, φέρε καταδίκην.’","st":"2.1"},{"sp":"N","t":"αὕτη ἐπίδειξις νέου ἐκ σχολῆς ἐληλυθότος. τἆλλα δ᾽ ἄλλοις ἄφες, μηδὲ φωνήν τις ἀκούσῃ σου περὶ αὐτῶν ποτε μηδ᾽, ἂν ἐπαινέσῃ τις ἐπ᾽ αὐτοῖς, ἀνέχου, δόξον δὲ μηδεὶς εἶναι καὶ εἰδέναι μηδέν.","st":"2.1"},{"sp":"N","t":"μόνον τοῦτο εἰδὼς φαίνου, πῶς μήτ᾽ ἀποτύχῃς ποτὲ μήτε περιπέσῃς.","st":"2.1"},{"sp":"N","t":"ἄλλοι μελετάτωσαν δίκας, ἄλλοι προβλήματα, ἄλλοι συλλογισμούς: σὺ ἀποθνῄσκειν, σὺ δεδέσθαι, σὺ στρεβλοῦσθαι, σὺ ἐξορίζεσθαι.","st":"2.1"},{"sp":"N","t":"πάντα ταῦτα θαρρούντως, πεποιθότως τῷ κεκληκότι σε ἐπ᾽ αὐτά, τῷ ἄξιον τῆς χώρας ταύτης κεκρικότι, ἐν ᾗ καταταχθεὶς ἐπιδείξεις, τίνα δύναται λογικὸν ἡγεμονικὸν πρὸς τὰς ἀπροαιρέτους δυνάμεις ἀντιταξάμενον.","st":"2.1"},{"sp":"N","t":"καὶ οὕτως τὸ παράδοξον ἐκεῖνο οὐκέτι οὔτ᾽ ἀδύνατον φανεῖται οὔτε παράδοξον, ὅτι ἅμα μὲν εὐλαβεῖσθαι δεῖ ἅμα δὲ θαρρεῖν, πρὸς μὲν τὰ ἀπροαίρετα θαρρεῖν, ἐν δὲ τοῖς προαιρετικοῖς εὐλαβεῖσθαι. περὶ ἀταραξίας. ὅρα σὺ ὁ ἀπιὼν ἐπὶ τὴν δίκην, τί θέλεις τηρῆσαι καὶ ποῦ θέλεις ἀνύσαι.","st":"2.1"},{"sp":"N","t":"εἰ γὰρ προαίρεσιν θέλεις τηρῆσαι κατὰ φύσιν ἔχουσαν, πᾶσά σοι ἀσφάλεια, πᾶσά σοι εὐμάρεια, πρᾶγμα οὐκ ἔχεις.","st":"2.2"},{"sp":"N","t":"τὰ γὰρ ἐπὶ σοὶ αὐτεξούσια καὶ φύσει ἐλεύθερα θέλων τηρῆσαι καὶ τούτοις ἀρκούμενος τίνος ἔτι ἐπιστρέφῃ; τίς γὰρ αὐτῶν κύριος, τίς αὐτὰ δύναται ἀφελέσθαι;","st":"2.2"},{"sp":"N","t":"εἰ θέλεις αἰδήμων εἶναι καὶ πιστός, τίς οὐκ ἐάσει σε; εἰ θέλεις μὴ κωλύεσθαι μηδ᾽ ἀναγκάζεσθαι, τίς σε ἀναγκάσει ὀρέγεσθαι ὧν οὐ δοκεῖ σοι, τίς ἐκκλίνειν ἃ μὴ φαίνεταί σοι;","st":"2.2"},{"sp":"N","t":"ἀλλὰ τί; πράξει μέν σοί τινα ἃ δοκεῖ φοβερὰ εἶναι: ἵνα δὲ καὶ ἐκκλίνων αὐτὰ πάθῃς, πῶς δύναται ποιῆσαι;","st":"2.2"},{"sp":"N","t":"ὅταν οὖν ἐπὶ σοὶ ᾖ τὸ ὀρέγεσθαι καὶ ἐκκλίνειν, τίνος ἔτι ἐπιστρέφῃ;","st":"2.2"},{"sp":"N","t":"τοῦτό σοι προοίμιον, τοῦτο διήγησις, τοῦτο πίστις, τοῦτο νίκη, τοῦτο ἐπίλογος, τοῦτο εὐδοκίμησις.","st":"2.2"},{"sp":"N","t":"διὰ τοῦτο ὁ Σωκράτης πρὸς τὸν ὑπομιμνῄσκοντα, ἵνα παρασκευάζηται πρὸς τὴν δίκην, ἔφη ‘οὐ δοκῶ οὖν σοι ἅπαντι τῷ βίῳ πρὸς τοῦτο παρασκευάζεσθαι;’","st":"2.2"},{"sp":"N","t":"—’ποίαν παρασκευήν;’—’τετήρηκα,’ φησίν, ‘τὸ ἐπ᾽ ἐμοί.’—’πῶς οὖν;’—’οὐδὲν οὐδέποτ᾽ ἄδικον οὔτ᾽ ἰδίᾳ οὔτε δημοσίᾳ ἔπραξα.’","st":"2.2"},{"sp":"N","t":"εἰ δὲ θέλεις καὶ τὰ ἐκτὸς τηρῆσαι, τὸ σωμάτιον καὶ τὸ οὐσίδιον καὶ τὸ ἀξιωμάτιον, λέγω σοι: ἤδη αὐτόθεν παρασκευάζου τὴν δυνατὴν παρασκευὴν πᾶσαν καὶ λοιπὸν σκέπτου καὶ τὴν φύσιν τοῦ δικαστοῦ καὶ τὸν ἀντίδικον.","st":"2.2"},{"sp":"N","t":"εἰ γονάτων ἅψασθαι δεῖ, γονάτων ἅψαι: εἰ κλαῦσαι, κλαῦσον: εἰ οἰμῶξαι, οἴμωξον.","st":"2.2"},{"sp":"N","t":"ὅταν γὰρ ὑποθῇς τὰ σὰ τοῖς ἐκτός, δούλευε τὸ λοιπὸν καὶ μὴ ἀντισπῶ καὶ ποτὲ μὲν θέλε δουλεύειν, ποτὲ δὲ μὴ θέλε,","st":"2.2"},{"sp":"N","t":"ἀλλ᾽ ἁπλῶς καὶ ἐξ ὅλης τῆς διανοίας ἢ ταῦτα ἢ ἐκεῖνα: ἢ ἐλεύθερος ἢ δοῦλος, ἢ πεπαιδευμένος ἢ ἀπαίδευτος, ἢ γενναῖος ἀλεκτρυὼν ἢ ἀγεννής, ἢ ὑπόμενε τυπτόμενος, μέχρις ἂν ἀποθάνῃς, ἢ ἀπαγόρευσον εὐθύς. μή σοι γένοιτο πληγὰς πολλὰς λαβεῖν καὶ ὕστερον ἀπαγορεῦσαι.","st":"2.2"},{"sp":"N","t":"εἰ δ᾽ αἰσχρὰ ταῦτα, αὐτόθεν ἤδη δίελε ‘ποῦ φύσις κακῶν καὶ ἀγαθῶν; οὗ καὶ ἀλήθεια. ὅπου ἀλήθεια καὶ οὗ φύσις, ἐκεῖ τὸ εὐλαβές: ὅπου ἡ ἀλήθεια, ἐκεῖ τὸ θαρραλέον, ὅπου ἡ φύσις.’","st":"2.2"},{"sp":"N","t":"ἐπεί τ οι δοκεῖς, ὅτι τὰ ἐκτὸς τηρῆσαι θέλων Σωκράτης παρελθὼν ἂν ἔλεγε ‘ἐμὲ δ᾽ Ἄνυτος καὶ Μέλητος ἀποκτεῖναι μὲν δύνανται, βλάψαι δ᾽ οὔ;’ οὕτω μωρὸς ἦν,","st":"2.2"},{"sp":"N","t":"ἵνα μὴ ἴδῃ ὅτι αὕτη ἡ ὁδὸς ἐνταῦθα οὐ φέρει, ἀλλ᾽ ἄλλῃ; τί οὖν ἐστιν, ὅτι οὐκ ἔχει λόγον καὶ προσερεθίζει;","st":"2.2"},{"sp":"N","t":"ὡς ὁ ἐμὸς Ἡράκλειτος περὶ ἀγριδίου πραγμάτιον ἔχων ἐν Ῥόδῳ καὶ ἀποδείξας τοῖς δικασταῖς ὅτι δίκαια λέγει ἐλθὼν ἐπὶ τὸν ἐπίλογον ἔφη ὅτι ‘ἀλλ᾽ οὔτε δεήσομαι ὑμῶν οὔτ᾽ ἐπιστρέφομαι, τί μέλλετε κρίνειν: ὑμεῖς τε μᾶλλον οἱ κρινόμενοί ἐστε ἢ ἐγώ.’","st":"2.2"},{"sp":"N","t":"καὶ οὕτως κατέστρεψε τὸ πραγμάτιον. τίς χρεία; μόνον μὴ δέου, μὴ προστίθει δ᾽ ὅτι ‘καὶ οὐ δέομαι.’ εἰ μή τι καιρός ἐστιν ἐπίτηδες ἐρεθίσαι τοὺς δικαστὰς ὡς Σωκράτει.","st":"2.2"},{"sp":"N","t":"καὶ σὺ εἰ τοιοῦτον ἐπίλογον παρασκευάζῃ, τί ἀναβαίνεις, τί ὑπακούεις;","st":"2.2"},{"sp":"N","t":"εἰ γὰρ σταυρωθῆναι θέλεις, ἔκδεξαι καὶ ἥξει ὁ σταυρός: εἰ δ᾽ ὑπακοῦσαι λόγος αἱρεῖ καὶ πεῖσαι τό γε παρ᾽ αὐτόν, τὰ ἑξῆς τούτῳ ποιητέον τηροῦντι μέντοι τὰ ἴδια. ταύτῃ καὶ γελοῖόν ἐστι τὸ λέγειν","st":"2.2"},{"sp":"N","t":"‘ὑπόθου μοι.’ τί σοι ὑποθῶμαι; ἀλλὰ ‘ποίησόν μου τὴν διάνοιαν ὅ τι ἂν ἀποβαίνῃ πρὸς τοῦτο ἁρμόσασθαι.’","st":"2.2"},{"sp":"N","t":"ἐπεὶ ἐκεῖνό γε ὅμοιόν ἐστιν οἷον εἰ ἀγράμματος λέγοι ‘εἰπέ μοι τί γράψω, ὅταν μοι προβληθῇ τι ὄνομα.’","st":"2.2"},{"sp":"N","t":"ἂν γὰρ εἴπω ὅτι Δίων, εἶτα παρελθὼν ἐκεῖνος αὐτῷ προβάλῃ μὴ τὸ Δίωνος ὄνομα, ἀλλὰ τὸ Θέωνος, τί γένηται;","st":"2.2"},{"sp":"N","t":"τί γράψῃ; ἀλλ᾽ εἰ μὲν μεμελέτηκας γράφειν, ἔχεις καὶ παρασκευάσασθαι πρὸς πάντα τὰ ὑπαγορευόμενα: εἰ δὲ μή, τί σοι ἐγὼ νῦν ὑποθῶμαι; ἂν γὰρ ἄλλο τι ὑπαγορεύῃ τὰ πράγματα, τί ἐρεῖς ἢ τί πράξεις;","st":"2.2"},{"sp":"N","t":"τούτου οὖν τοῦ καθολικοῦ μέμνησο καὶ ὑποθήκης οὐκ ἀπορήσεις. ἐὰν δὲ πρὸς τὰ ἔξω χάσκῃς, ἀνάγκη σε ἄνω καὶ κάτω κυλίεσθαι πρὸς τὸ βούλημα τοῦ κυρίου.","st":"2.2"},{"sp":"N","t":"τίς δ᾽ ἐστὶ κύριος; ὁ τῶν ὑπὸ σοῦ τινος σπουδαζομένων ἢ ἐκκλινομένων ἔχων ἐξουσίαν. πρὸς τοὺς συνιστάντας τινὰς τοῖς φιλοσόφοις. καλῶς ὁ Διογένης πρὸς τὸν ἀξιοῦντα γράμματα παρ᾽ αὐτοῦ λαβεῖν συστατικὰ ‘ὅτι μὲν ἄνθρωπος,’ φησίν, ‘εἶ, καὶ ἰδὼν γνώσεται: εἰ δ᾽ ἀγαθὸς ἢ κακός, εἰ μὲν ἔμπειρός ἐστι διαγνῶναι τοὺς ἀγαθοὺς καὶ κακούς, γνώσεται, εἰ δ᾽ ἄπειρος, οὐδ᾽ ἂν μυριάκις γράψω αὐτῷ.’","st":"2.2"},{"sp":"N","t":"ὅμοιον γὰρ ὥσπερ εἰ δραχμὴ συσταθῆναί τινι ἠξίου, ἵνα δοκιμασθῇ. εἰ ἀργυρογνωμονικός ἐστιν, σὺ σαυτὴν συστήσεις.","st":"2.3"},{"sp":"N","t":"ἔδει οὖν τοιοῦτόν τι ἔχειν ἡμᾶς καὶ ἐν τῷ βίῳ οἷον ἐπ᾽ ἀργυρίου, ἵν᾽ εἰπεῖν δύνωμαι καθάπερ ὁ ἀργυρογνώμων λέγει ‘φέρε ἣν θέλεις δραχμὴν καὶ διαγνώσομαι.’","st":"2.3"},{"sp":"N","t":"ἀλλ᾽ ἐπὶ συλλογισμῶν ‘φέρε ὃν θέλεις καὶ διακρινῶ σοι τὸν ἀναλυτικόν τε καὶ μή.’ διὰ τί; οἶδα γὰρ ἀναλύειν συλλογισμούς: ἔχω τὴν δύναμιν, ἣν ἔχειν δεῖ τὸν ἐπιγνωστικὸν τῶν περὶ συλλογισμοὺς κατορθούντων.","st":"2.3"},{"sp":"N","t":"ἐπὶ δὲ τοῦ βίου τί ποιῶ; νῦν μὲν λέγω ἀγαθόν, νῦν δὲ κακόν. τί τὸ αἴτιον; τὸ ἐναντίον ἢ ἐπὶ τῶν συλλογισμῶν, ἀμαθία καὶ ἀπειρία. πρὸς τὸν ἐπὶ μοιχείᾳ ποτὲ κατειλημμένον. λέγοντος αὐτοῦ ὅτι Ὁ ἄνθρωπος πρὸς πίστιν γέγονεν καὶ τοῦτο ὁ ἀνατρέπων ἀνατρέπει τὸ ἴδιον τοῦ ἀνθρώπου ἐπεισῆλθέν τις τῶν δοκούντων φιλολόγων, ὃς κατείληπτό ποτε μοιχὸς ἐν τῇ πόλει.","st":"2.3"},{"sp":"N","t":"ὁ δ᾽ Ἀλλ᾽ ἄν, φησίν, ἀφέντες τοῦτο τὸ πιστόν, πρὸς ὃ πεφύκαμεν, ἐπιβουλεύωμεν τῇ γυναικὶ τοῦ γείτονος, τί ποιοῦμεν; τί γὰρ ἄλλο ἢ ἀπόλλυμεν καὶ ἀναιροῦμεν; τίνα; τὸν πιστόν, τὸν αἰδήμονα, τὸν ὅσιον.","st":"2.4"},{"sp":"N","t":"ταῦτα μόνα; γειτνίασιν δ᾽ οὐκ ἀναιροῦμεν, φιλίαν δ᾽ οὔ, πόλιν δ᾽ οὔ; εἰς τίνα δὲ χώραν αὑτοὺς κατατάσσομεν; ὡς τίνι σοι χρῶμαι, ἄνθρωπε; ὡς γείτονι, ὡς φίλῳ; ποίῳ τινί; ὡς πολίτῃ; τί σοι πιστεύσω;","st":"2.4"},{"sp":"N","t":"εἶτα σκευάριον μὲν εἰ ἦς οὕτως σαπρόν, ὥστε σοι πρὸς μηδὲν δύνασθαι χρῆσθαι, ἔξω ἂν ἐπὶ τὰς κοπρίας ἐρρίπτου καὶ οὐδ᾽ ἐκεῖθεν ἄν τίς σε ἀνῃρεῖτο:","st":"2.4"},{"sp":"N","t":"εἰ δ᾽ ἄνθρωπος ὢν οὐδεμίαν χώραν δύνασαι ἀποπληρῶσαι ἀνθρωπικήν, τί σε ποιήσομεν; ἔστω γάρ, φίλου οὐ δύνασαι τόπον ἔχειν: δούλου δύνασαι; καὶ τίς σοι πιστεύσει; οὐ θέλεις οὖν ῥιφῆναί που καὶ αὐτὸς ἐπὶ κοπρίαν ὡς σκεῦος ἄχρηστον, ὡς κόπριον;","st":"2.4"},{"sp":"N","t":"εἶτα ἐρεῖς ‘οὐδείς μου ἐπιστρέφεται, ἀνθρώπου φιλολόγου;’ κακὸς γὰρ εἶ καὶ ἄχρηστος. οἷον εἰ οἱ σφῆκες ἠγανάκτουν, ὅτι οὐδεὶς αὐτῶν ἐπιστρέφεται, ἀλλὰ φεύγουσι πάντες κἄν τις δύνηται, πλήξας κατέβαλεν.","st":"2.4"},{"sp":"N","t":"σὺ κέντρον ἔχεις τοιοῦτον, ὥστε ὃν ἂν πλήξῃς εἰς πράγματα καὶ ὀδύνας ἐμβάλλειν. τί σε θέλεις ποιήσωμεν; οὐκ ἔχεις ποῦ τεθῇς.","st":"2.4"},{"sp":"N","t":"τί οὖν; οὐκ εἰσὶν αἱ γυναῖκες κοιναὶ φύσει; κἀγὼ λέγω. καὶ γὰρ τὸ χοιρίδιον κοινὸν τῶν κεκλημένων: ἀλλ᾽ ὅταν μέρη γένηται, ἄν σοι φανῇ, ἀνάρπασον ἀπελθὼν τὸ τοῦ παρακατακειμένου μέρος, λάθρᾳ κλέψον ἢ παρακαθεὶς τὴν χεῖρα λίχνευε, κἂν μὴ δύνῃ τοῦ κρέως ἀποσπάσαι, λίπαινε τοὺς δακτύλους καὶ περίλειχε. καλὸς συμπότης καὶ σύνδειπνος Σωκρατικός.","st":"2.4"},{"sp":"N","t":"ἄγε, τὸ δὲ θέατρον οὐκ ἔστι κοινὸν τῶν πολιτῶν; ὅταν οὖν καθίσωσιν, ἐλθών, ἄν σοι φανῇ, ἔκβαλέ τινα αὐτῶν.","st":"2.4"},{"sp":"N","t":"οὕτως καὶ αἱ γυναῖκες φύσει κοιναί. ὅταν δ᾽ ὁ νομοθέτης ὡς ἑστιάτωρ διέλῃ αὐτάς, οὐ θέλεις καὶ αὐτὸς ἴδιον μέρος ζητεῖν, ἀλλὰ τὸ ἀλλότριον ὑφαρπάζεις καὶ λιχνεύεις;","st":"2.4"},{"sp":"N","t":"‘ἀλλὰ φιλόλογός εἰμι καὶ Ἀρχέδημον νοῶ.’ Ἀρχέδημον τοίνυν νοῶν μοιχὸς ἴσθι καὶ ἄπιστος καὶ ἀντὶ ἀνθρώπου λύκος ἢ πίθηκος. τί γὰρ κωλύει; πῶς συνυπάρχει μεγαλοφροσύνη καὶ ἐπιμέλεια. αἱ ὗλαι ἀδιάφοροι, ἡ δὲ χρῆσις αὐτῶν οὐκ ἀδιάφορος.","st":"2.4"},{"sp":"N","t":"πῶς οὖν τηρήσῃ τις ἅμα μὲν τὸ εὐσταθὲς καὶ ἀτάραχον, ἅμα δὲ τὸ ἐπιμελὲς καὶ μὴ εἰκαῖον μηδ᾽ ἐπισεσυρμένον;","st":"2.5"},{"sp":"N","t":"ἂν μιμῆται τοὺς κυβεύοντας. αἱ ψῆφοι ἀδιάφοροι, οἱ κύβοι ἀδιάφοροι: πόθεν οἶδα, τί μέλλει πίπτειν; τῷ πεσόντι δ᾽ ἐπιμελῶς καὶ τεχνικῶς χρῆσθαι, τοῦτο ἤδη ἐμὸν ἔργον ἐστίν.","st":"2.5"},{"sp":"N","t":"οὕτως τοίνυν τὸ μὲν προηγούμενον καὶ ἐπὶ τοῦ βίου ἔργον ἐκεῖνο: δίελε τὰ πράγματα καὶ διάστησον καὶ εἰπὲ ‘τὰ ἔξω οὐκ ἐπ᾽ ἐμοί: προαίρεσις ἐπ᾽ ἐμοί.","st":"2.5"},{"sp":"N","t":"ποῦ ζητήσω τὸ ἀγαθὸν καὶ τὸ κακόν; ἔσω ἐν τοῖς ἐμοῖς.’ ἐν δὲ τοῖς ἀλλοτρίοις μηδέποτε μήτ᾽ ἀγαθὸν ὀνομάσῃς μήτε κακὸν μήτ᾽ ὠφέλειαν μήτε βλάβην μήτ᾽ ἄλλο τι τῶν τοιούτων.","st":"2.5"},{"sp":"N","t":"τί οὖν; ἀμελῶς τούτοις χρηστέον; οὐδαμῶς. τοῦτο γὰρ πάλιν τῇ προαιρέσει κακόν ἐστι καὶ ταύτῃ τὴν παρὰ φύσιν.","st":"2.5"},{"sp":"N","t":"ἀλλ᾽ ἅμα μὲν ἐπιμελῶς, ὅτι ἡ χρῆσις οὐκ ἀδιάφορον, ἅμα δ᾽ εὐσταθῶς καὶ ἀταράχως, ὅτι ἡ ὕλη οὐ διαφέρουσα.","st":"2.5"},{"sp":"N","t":"ὅπου γὰρ τὸ διαφέρον, ἐκεῖ οὔτε κωλῦσαί μέ τις δύναται οὔτ᾽ ἀναγκάσαι. ὅπου κωλυτὸς καὶ ἀναγκαστός εἰμι, ἐκείνων ἡ μὲν τεῦξις οὐκ ἐπ᾽ ἐμοὶ οὐδ᾽ ἀγαθὸν ἢ κακόν, ἡ χρῆσις δ᾽ ἢ κακὸν ἢ ἀγαθόν, ἀλλ᾽ ἐπ᾽ ἐμοί.","st":"2.5"},{"sp":"N","t":"δύσκολον δὲ μῖξαι καὶ συναγαγεῖν ταῦτα, ἐπιμέλειαν τοῦ προσπεπονθότος ταῖς ὕλαις καὶ εὐστάθειαν τοῦ ἀνεπιστρεπτοῦντος, πλὴν οὐκ ἀδύνατον. εἰ δὲ μή, ἀδύνατον τὸ εὐδαιμονῆσαι.","st":"2.5"},{"sp":"N","t":"ἀλλ᾽ οἷόν τι ἐπὶ τοῦ πλοῦ ποιοῦμεν. τί μοι δύναται; τὸ ἐκλέξασθαι τὸν κυβερνήτην, τοὺς ναύτας, τὴν ἡμέραν, τὸν καιρόν.","st":"2.5"},{"sp":"N","t":"εἶτα χειμὼν ἐμπέπτωκεν. τί οὖν ἔτι μοι μέλει; τὰ γὰρ ἐμὰ ἐκπεπλήρωται. ἄλλου ἐστὶν ἡ ὑπόθεσις, τοῦ κυβερνήτου. ἀλλὰ καὶ ἡ ναῦς καταδύεται.","st":"2.5"},{"sp":"N","t":"τί οὖν ἔχω ποιῆσαι; ὃ δύναμαι, τοῦτο μόνον ποιῶ: μὴ φοβούμενος ἀποπνίγομαι οὐδὲ κεκραγὼς οὐδ᾽ ἐγκαλῶν τῷ θεῷ, ἀλλ᾽ εἰδώς, ὅτι τὸ γενόμενον καὶ φθαρῆναι δεῖ.","st":"2.5"},{"sp":"N","t":"οὐ γάρ εἰμι αἰών, ἀλλ᾽ ἄνθρωπος, μέρος τῶν πάντων ὡς ὥρα ἡμέρας. ἐνστῆναί με δεῖ ὡς τὴν ὥραν καὶ παρελθεῖν ὡς ὥραν. τί οὖν μοι διαφέρει πῶς παρέλθω,","st":"2.5"},{"sp":"N","t":"πότερον πνιγεὶς ἢ πυρέξας; διὰ γὰρ τοιούτου τινὸς δεῖ παρελθεῖν με.","st":"2.5"},{"sp":"N","t":"τοῦτο ὄψει ποιοῦντας καὶ τοὺς σφαιρίζοντας ἐμπείρως. οὐδεὶς αὐτῶν διαφέρεται περὶ τοῦ ἁρπαστοῦ ὡς περὶ ἀγαθοῦ ἢ κακοῦ, περὶ δὲ τοῦ βάλλειν καὶ δέχεσθαι.","st":"2.5"},{"sp":"N","t":"λοιπὸν ἐν τούτῳ ἡ εὐρυθμία, ἐν τούτῳ ἡ τέχνη, τὸ τάχος, ἡ εὐγνωμοσύνη, ἵν᾽ ἐγώ, μηδ᾽ ἂν τὸν κόλπον ἐκτείνω, δύναμαι λαβεῖν αὐτό, ὁ δέ, ἂν βάλω, λαμβάνει.","st":"2.5"},{"sp":"N","t":"ἂν δὲ μετὰ ταραχῆς καὶ φόβου δεχώμεθα ἢ βάλλωμεν αὐτό, ποία ἔτι παιδιά, ποῦ δέ τις εὐσταθήσει, ποῦ δέ τις τὸ ἑξῆς ὄψεται ἐν αὐτῇ; ἀλλ᾽ ὁ μὲν ἐρεῖ ‘βάλε,’ ὁ δὲ ‘μὴ βάλῃς,’ ὁ δὲ † ‘μὴ ἀνέβαλες.’ τοῦτο δὴ μάχη ἐστὶ καὶ οὐ παιδιά.","st":"2.5"},{"sp":"N","t":"τοιγαροῦν Σωκράτης ᾔδει σφαιρίζειν. πῶς; παίζειν ἐν τῷ δικαστηρίῳ. ‘λέγε μοι,’ φησίν, ‘Ἄνυτε, πῶς με φῂς θεὸν οὐ νομίζειν; οἱ δαίμονές σοι τίνες εἶναι δοκοῦσιν; οὐχὶ ἤτοι θεῶν παῖδές εἰσιν ἢ ἐξ ἀνθρώπων καὶ θεῶν μεμιγμένοι τινές;’","st":"2.5"},{"sp":"N","t":"ὁμολογήσαντος δὲ ‘τίς οὖν σοι δοκεῖ δύνασθαι ἡμιόνους μὲν ἡγεῖσθαι εἶναι, ὄνους δὲ μή;’ ὡς ἁρπαστίῳ παίζων. καὶ τί ἐκεῖ ἐν μέσῳ ἁρπάστιον τότ᾽ ἦν; τὸ δεδέσθαι, τὸ φυγαδευθῆναι, τὸ πιεῖν φάρμακον, τὸ γυναικὸς ἀφαιρεθῆναι, τὸ τέκνα ὀρφανὰ καταλιπεῖν.","st":"2.5"},{"sp":"N","t":"ταῦτα ἦν ἐν μέσῳ οἷς ἔπαιζεν, ἀλλ᾽ οὐδὲν ἧττον ἔπαιζεν καὶ ἐσφαίριζεν εὐρύθμως. οὕτως καὶ ἡμεῖς τὴν μὲν ἐπιμέλειαν σφαιριστικωτάτην, τὴν δ᾽ ἀδιαφορίαν ὡς ὑπὲρ ἁρπαστίου.","st":"2.5"},{"sp":"N","t":"δεῖ γὰρ πάντως περί τινα τῶν ἐκτὸς ὑλῶν φιλοτεχνεῖν, ἀλλ᾽ οὐκ ἐκείνην ἀποδεχόμενον, ἀλλ᾽ οἵα ἂν ᾖ ἐκείνη, τὴν περὶ αὐτὴν φιλοτεχνίαν ἐπιδεικνύοντα. οὕτως καὶ ὁ ὑφάντης οὐκ ἔρια ποιεῖ, ἀλλ᾽ οἷα ἂν παραλάβῃ περὶ αὐτὰ φιλοτεχνεῖ.","st":"2.5"},{"sp":"N","t":"ἄλλος σοι δίδωσι τροφὰς καὶ κτῆσιν καὶ αὐτὰ ταῦτα δύναται ἀφελέσθαι καὶ τὸ σωμάτιον αὐτό. σὺ λοιπὸν παραλαβὼν τὴν ὕλην ἐργάζου. εἶτα ἂν ἐξέλθῃς μηδὲν παθών,","st":"2.5"},{"sp":"N","t":"οἱ μὲν ἄλλοι ἀπαντῶντές σοι συγχαρήσονται ὅτι ἐσώθης, ὁ δ᾽ εἰδὼς βλέπειν τὰ τοιαῦτα, ἂν μὲν ἴδῃ ὅτι εὐσχημόνως ἀνεστράφης ἐν τούτῳ, ἐπαινέσει καὶ συνησθήσεται: ἂν δὲ δι᾽ ἀσχημοσύνην τινὰ διασεσωσμένον, τὰ ἐναντία. ὅπου γὰρ τὸ χαίρειν εὐλόγως, ἐκεῖ καὶ τὸ συγχαίρειν.","st":"2.5"},{"sp":"N","t":"πῶς οὖν λέγεται τῶν ἐκτός τινα κατὰ φύσιν καὶ παρὰ φύσιν; ὥσπερ ἂν εἰ ἀπόλυτοι ἦμεν. τῷ γὰρ ποδὶ κατὰ φύσιν εἶναι ἐρῶ τὸ καθαρῷ εἶναι, ἀλλ᾽, ἂν αὐτὸν ὡς πόδα λάβῃς καὶ ὡς μὴ ἀπόλυτον, καθήξει αὐτὸν καὶ εἰς πηλὸν ἐμβαίνειν καὶ ἀκάνθας πατῆσαι καὶ ἔστιν ὅτε ἀποκοπῆναι ὑπὲρ τοῦ ὅλου: εἰ δὲ μή, οὐκέτι ἔσται πούς. τοιοῦτόν τι καὶ ἐφ᾽ ἡμῶν ὑπολαβεῖν δεῖ.","st":"2.5"},{"sp":"N","t":"τί εἶ; ἄνθρωπος. εἰ μὲν ὡς ἀπόλυτον σκοπεῖς, κατὰ φύσιν ἐστὶ ζῆσαι μέχρι γήρως, πλουτεῖν, ὑγιαίνειν. εἰ δ᾽ ὡς ἄνθρωπον σκοπεῖς καὶ μέρος ὅλου τινός, δι᾽ ἐκεῖνο τὸ ὅλον νῦν μέν σοι νοσῆσαι καθήκει, νῦν δὲ πλεῦσαι καὶ κινδυνεῦσαι, νῦν δ᾽ ἀπορηθῆναι, πρὸ ὥρας δ᾽ ἔστιν ὅτ᾽ ἀποθανεῖν.","st":"2.5"},{"sp":"N","t":"τί οὖν ἀγανακτεῖς; οὐκ οἶδας ὅτι ὡς ἐκεῖνος οὐκέτι ἔσται πούς, οὕτως οὐδὲ σὺ ἄνθρωπος; τί γάρ ἐστιν ἄνθρωπος; μέρος πόλεως, πρώτης μὲν τῆς ἐκ θεῶν καὶ ἀνθρώπων, μετὰ ταῦτα δὲ τῆς ὡς ἔγγιστα λεγομένης, ἥ τί ἐστι μικρὸν τῆς ὅλης μίμημα.","st":"2.5"},{"sp":"N","t":"‘νῦν οὖν ἐμὲ κρίνεσθαι;’ νῦν οὖν ἄλλον πυρέσσειν, ἄλλον πλεῖν, ἄλλον ἀποθνῄσκειν, ἄλλον κατακεκρίσθαι; ἀδύνατον γὰρ ἐν τοιούτῳ σώματι, ἐν τούτῳ τῷ περιέχοντι, τούτοις τοῖς συζῶσιν μὴ συμπίπτειν ἄλλοις ἄλλα τοιαῦτα.","st":"2.5"},{"sp":"N","t":"σὸν οὖν ἔργον ἐλθόντα εἰπεῖν ἃ δεῖ, διαθέσθαι ταῦτα ὡς ἐπιβάλλει.","st":"2.5"},{"sp":"N","t":"εἶτα ἐκεῖνος λέγει ‘κρίνω σε ἀδικεῖν.’ ‘εὖ σοι γένοιτο. ἐποίησα ἐγὼ τὸ ἐμόν, εἰ δὲ καὶ σὺ τὸ σὸν ἐποίησας, ὄψει αὐτός.’ ἔστι γάρ τις κἀκείνου κίνδυνος, μή σε λανθανέτω. περὶ ἀδιαφορίας. τὸ συνημμένον ἀδιάφορον: ἡ κρίσις ἡ περὶ αὐτοῦ οὐκ ἀδιάφορος, ἀλλ᾽ ἢ ἐπιστήμη ἢ δόξα ἢ ἀπάτη. οὕτως τὸ ζῆν ἀδιάφορον, ἡ χρῆσις οὐκ ἀδιάφορος.","st":"2.5"},{"sp":"N","t":"μή ποτ᾽ οὖν, ὅταν εἴπῃ τις ὑμῖν ἀδιαφορεῖν καὶ ταῦτα, ἀμελεῖς γίνεσθε, μήθ᾽ ὅταν εἰς ἐπιμέλειάν τις ὑμᾶς παρακαλῇ, ταπεινοὶ καὶ τᾶς ὕλας τεθαυμακότες.","st":"2.6"},{"sp":"N","t":"καλὸν δὲ καὶ τὸ εἰδέναι τὴν αὑτοῦ παρασκευὴν καὶ δύναμιν, ἵν᾽ ἐν οἷς μὴ παρεσκεύασαι, ἡσυχίαν ἄγῃς μηδ᾽ ἀγανακτῇς, εἴ τινες ἄλλοι πλεῖόν σου ἔχουσιν ἐν ἐκείνοις.","st":"2.6"},{"sp":"N","t":"καὶ γὰρ σὺ ἐν συλλογισμοῖς πλεῖον ἀξιώσεις σεαυτὸν ἔχειν κἂν ἀγανακτῶσιν ἐπὶ τούτῳ, παραμυθήσῃ αὐτούς: ‘ἐγὼ ἔμαθον, ὑμεῖς δ᾽ οὔ.’","st":"2.6"},{"sp":"N","t":"οὕτως καί, ὅπου τινὸς χρεία τριβῆς, μὴ ζήτει τὸ ἀπὸ τῆς χρείας περιγινόμενον, ἀλλ᾽ ἐκείνου μὲν παραχώρει τοῖς περιτετριμμένοις, σοὶ δ᾽ ἀρκείτω τὸ εὐσταθεῖν.","st":"2.6"},{"sp":"N","t":"‘ἄπελθε καὶ ἄσπασαι τὸν δεῖνα.’ ‘ἀσπάζομαι.’ ‘πῶς;’ ‘οὐ ταπεινῶς.’ ‘ἀλλ᾽ ἐξεκλείσθης.’ ‘διὰ θυρίδος γὰρ οὐκ ἔμαθον εἰσέρχεσθαι. ὅταν δὲ κεκλειμένην εὕρω τὴν θύραν, ἀνάγκη μ᾽ ἢ ἀποχωρῆσαι ἢ διὰ τῆς θυρίδος εἰσελθεῖν.’","st":"2.6"},{"sp":"N","t":"‘ἀλλὰ καὶ λάλησον αὐτῷ.’ ‘λαλῶ.’","st":"2.6"},{"sp":"N","t":"‘τίνα τρόπον;’ ‘οὐ ταπεινῶς.’ ‘ἀλλ᾽ οὐκ ἐπέτυχες.’ μὴ γὰρ σὸν τοῦτο τὸ ἔργον ἦν; ἀλλ᾽ ἐκείνου. τί οὖν ἀντιποιῇ τοῦ ἀλλοτρίου; ἀεὶ μεμνημένος ὅ τι σὸν καὶ τί ἀλλότριον καὶ οὐ ταραχθήσῃ.","st":"2.6"},{"sp":"N","t":"διὰ τοῦτο καλῶς ὁ Χρύσιππος λέγει ὅτι ‘μέχρις ἂν ἄδηλά μοι ᾖ τὰ ἑξῆς, ἀεὶ τῶν εὐφυεστέρων ἔχομαι πρὸς τὸ τυγχάνειν τῶν κατὰ φύσιν: αὐτὸς γάρ μ᾽ ὁ θεὸς ἐποίησεν τούτων ἐκλεκτικόν.","st":"2.6"},{"sp":"N","t":"εἰ δέ γε ᾔδειν ὅτι νοσεῖν μοι καθείμαρται νῦν, καὶ ὥρμων ἂν ἐπ᾽ αὐτό: καὶ γὰρ ὁ πούς, εἰ φρένας εἶχεν, ὥρμα ἂν ἐπὶ τὸ πηλοῦσθαι.’","st":"2.6"},{"sp":"N","t":"ἐπεί τοι τίνος ἕνεκα γίνονται στάχυες; οὐχ ἵνα καὶ ξηρανθῶσιν; ἀλλὰ ξηραίνονται μέν, οὐχ ἵνα δὲ καὶ θερισθῶσιν;","st":"2.6"},{"sp":"N","t":"οὐ γὰρ ἀπόλυτοι γίνονται. εἰ οὖν αἴσθησιν εἶχον, εὔχεσθαι αὐτοὺς ἔδει, ἵνα μὴ θερισθῶσιν μηδέποτε; τοῦτο δὲ κατάρα ἐστὶν ἐπὶ σταχύων τὸ μηδέποτε θερισθῆναι.","st":"2.6"},{"sp":"N","t":"οὕτως ἴστε ὅτι καὶ ἐπ᾽ ἀνθρώπων κατάρα ἐστὶ τὸ μὴ ἀποθανεῖν: ὅμοιον τῷ μὴ πεπανθῆναι, μὴ θερισθῆναι.","st":"2.6"},{"sp":"N","t":"ἡμεῖς δ᾽ ἐπειδὴ οἱ αὐτοί ἐσμεν, ἅμα μὲν οὓς δεῖ θερισθῆναι, ἅμα δὲ καὶ αὐτῷ τούτῳ παρακολουθοῦντες ὅτι θεριζόμεθα, διὰ τοῦτο ἀγανακτοῦμεν. οὔτε γὰρ ἴσμεν τίνες ἐσμὲν οὔτε μεμελετήκαμεν τὰ ἀνθρωπικὰ ὡς ἱππικοὶ τὰ ἱππικά.","st":"2.6"},{"sp":"N","t":"ἀλλὰ Χρυσάντας μὲν παίειν μέλλων τὸν πολέμιον, ἐπειδὴ τῆς σάλπιγγος ἤκουσεν ἀνακαλούσης, ἀνέσχεν: οὕτως προυργιαίτερον ἔδοξεν αὐτῷ τὸ τοῦ στρατηγοῦ πρόσταγμα ἢ τὸ ἴδιον ποιεῖν:","st":"2.6"},{"sp":"N","t":"ἡμῶν δ᾽ οὐδεὶς θέλει οὐδὲ τῆς ἀνάγκης καλούσης εὐλύτως ὑπακοῦσαι αὐτῇ, ἀλλὰ κλάοντες καὶ στένοντες πάσχομεν ἃ πάσχομεν καὶ περιστάσεις αὐτὰ καλοῦντες.","st":"2.6"},{"sp":"N","t":"ποίας περιστάσεις, ἄνθρωπε; εἰ περιστάσεις λέγεις τὰ περιεστηκότα, πάντα περιστάσεις εἰσίν: εἰ δ᾽ ὡς δύσκολα καλεῖς, ποίαν δυσκολίαν ἔχει τὸ γενόμενον φθαρῆναι;","st":"2.6"},{"sp":"N","t":"τὸ δὲ φθεῖρον ἢ μάχαιρά ἐστιν ἢ τροχὸς ἢ θάλασσα ἢ κεραμὶς ἢ τύραννος. τί σοι μέλει, ποίᾳ ὁδῷ καταβῇς εἰς Ἅιδου;","st":"2.6"},{"sp":"N","t":"ἴσαι πᾶσαί εἰσιν. εἰ δὲ θέλεις ἀκοῦσαι τἀληθῆ, συντομωτέρα ἣν πέμπει ὁ τύραννος. οὐδέποτ᾽ οὐδεὶς τύραννος ἓξ μησίν τινα ἔσφαξεν, πυρετὸς δὲ καὶ ἐνιαυτῷ πολλάκις. ψόφος ἐστὶ πάντα ταῦτα καὶ κόμπος κενῶν ὀνομάτων.","st":"2.6"},{"sp":"N","t":"‘τῇ κεφαλῇ κινδυνεύω ἐπὶ Καίσαρος.’ ἐγὼ δ᾽ οὐ κινδυνεύω, ὃς οἰκῶ ἐν Νικοπόλει, ὅπου σεισμοὶ τοσοῦτοι; σὺ δ᾽ αὐτὸς ὅταν διαπλέῃς τὸν Ἀδρίαν, τί κινδυνεύεις; οὐ τῇ κεφαλῇ;","st":"2.6"},{"sp":"N","t":"‘ἀλλὰ καὶ τῇ ὑπολήψει κινδυνεύω.’ τῇ σῇ; πῶς; τίς γάρ σε ἀναγκάσαι δύναται ὑπολαβεῖν τι ὧν οὐ θέλεις; ἀλλὰ τῇ ἀλλοτρίᾳ; καὶ ποῖός ἐστι κίνδυνος σὸς ἄλλους τὰ ψεύδη ὑπολαβεῖν;","st":"2.6"},{"sp":"N","t":"‘ἀλλ᾽ ἐξορισθῆναι κινδυνεύω.’ τί ἐστιν ἐξορισθῆναι; ἀλλαχοῦ εἶναι ἢ ἐν Ῥώμῃ; ‘ναί. τί οὖν; ἂν εἰς Γύαρα πεμφθῶ;’ ἄν σοι ποιῇ, ἀπελεύσῃ: εἰ δὲ μή, ἔχεις ποῦ ἀντὶ Γυάρων ἀπέλθῃς, ὅπου κἀκεῖνος ἐλεύσεται, ἄν τε θέλῃ ἄν τε μή, ὁ πέμπων σε εἰς Γύαρα.","st":"2.6"},{"sp":"N","t":"τί λοιπὸν ὡς ἐπὶ μεγάλα ἀνέρχῃ; μικρότερά ἐστι τῆς παρασκευῆς, ἵν᾽ εἴπῃ νέος εὐφυὴς ὅτι ‘οὐκ ἦν τοσούτου τοσούτων μὲν ἀκηκοέναι, τοσαῦτα δὲ γεγραφέναι, τοσούτῳ δὲ χρόνῳ παρακεκαθικέναι γεροντίῳ οὐ πολλοῦ ἀξίῳ.’","st":"2.6"},{"sp":"N","t":"μόνον ἐκείνης τῆς διαιρέσεως μέμνησο, καθ᾽ ἣν διορίζεται τὰ σὰ καὶ οὐ τὰ σά. μή ποτ᾽ ἀντιποιήσῃ τινὸς τῶν ἀλλοτρίων.","st":"2.6"},{"sp":"N","t":"βῆμα καὶ φυλακὴ τόπος ἐστὶν ἑκάτερον, ὁ μὲν ὑψηλός, ὁ δὲ ταπεινός: ἡ προαίρεσις δ᾽ ἴση, ἂν ἴσην αὐτὴν ἐν ἑκατέρῳ φυλάξαι θέλῃς, δύναται φυλαχθῆναι.","st":"2.6"},{"sp":"N","t":"καὶ τότ᾽ ἐσόμεθα ζηλωταὶ Σωκράτους, ὅταν ἐν φυλακῇ δυνώμεθα παιᾶνας γράφειν.","st":"2.6"},{"sp":"N","t":"μέχρι δὲ νῦν ὡς ἔχομεν, ὅρα εἰ ἠνεσχόμεθ᾽ ἂν ἐν τῇ φυλακῇ ἄλλου τινὸς ἡμῖν λέγοντος ‘θέλεις ἀναγνῶ σοι παιᾶνας;’ ‘τί μοι πράγματα παρέχεις; οὐκ οἶδας τὰ ἔχοντά με κακά; ἐν τούτοις γάρ μοι ἔστιν—’ ἐν τίσιν οὖν; ‘ἀποθνῄσκειν μέλλω.’ ἄνθρωποι δ᾽ ἄλλοι ἀθάνατοι ἔσονται; πῶς μαντευτέον. διὰ τὸ ἀκαίρως μαντεύεσθαι πολλοὶ καθήκοντα πολλὰ παραλείπομεν.","st":"2.6"},{"sp":"N","t":"τί γὰρ ὁ μάντις δύναται πλέον ἰδεῖν θανάτου ἢ κινδύνου ἢ νόσου ἢ ὅλως τῶν τοιούτων;","st":"2.7"},{"sp":"N","t":"ἂν οὖν δέῃ κινδυνεῦσαι ὑπὲρ τοῦ φίλου, ἂν δὲ καὶ ἀποθανεῖν ὑπὲρ αὐτοῦ καθήκῃ, ποῦ μοι καιρὸς ἔτι μαντεύεσθαι; οὐκ ἔχω τὸν μάντιν ἔσω τὸν εἰρηκότα μοι τὴν οὐσίαν τοῦ ἀγαθοῦ καὶ τοῦ κακοῦ, τὸν ἐξηγημένον τὰ σημεῖα ἀμφοτέρων;","st":"2.7"},{"sp":"N","t":"τί οὖν ἔτι χρείαν ἔχω τῶν σπλάγχνων ἢ τῶν οἰωνῶν; ἀλλ᾽ ἀνέχομαι λέγοντος ἐκείνου ‘συμφέρει σοι;’ τί γάρ ἐστι συμφέρον οἶδεν;","st":"2.7"},{"sp":"N","t":"τί ἐστιν ἀγαθὸν οἶδεν; μεμάθηκεν ὥσπερ τὰ σημεῖα τῶν σπλάγχνων οὕτως σημεῖα τίνα ἀγαθῶν καὶ κακῶν; εἰ γὰρ τούτων οἶδεν σημεῖα, καὶ καλῶν καὶ αἰσχρῶν οἶδεν καὶ δικαίων καὶ ἀδίκων.","st":"2.7"},{"sp":"N","t":"ἄνθρωπε, σύ μοι λέγε τί σημαίνεται, ζωὴ ἢ θάνατος, πενία ἢ πλοῦτος: πότερον δὲ συμφέρει ταῦτα ἢ ἀσύμφορά ἐστιν, σοῦ μέλλω πυνθάνεσθαι;","st":"2.7"},{"sp":"N","t":"διὰ τί ἐν γραμματικοῖς οὐ λέγεις; ἐνθάδ᾽ οὖν, ὅπου πάντες ἄνθρωποι πλανώμεθα καὶ πρὸς ἀλλήλους μαχόμεθα;","st":"2.7"},{"sp":"N","t":"διὰ τοῦτο ἡ γυνὴ καλῶς εἶπεν ἡ πέμψαι θέλουσα τῇ Γρατίλλῃ ἐξωρισμένῃ τὸ πλοῖον τῶν ἐπιμηνίων κατὰ τὸν εἰπόντα ὅτι ‘ἀφαιρήσεται αὐτὰ Δομιτιανὸς’ ‘μᾶλλον θέλω,’ φησίν, ‘ἵν᾽ ἐκεῖνος αὐτὰ ἀφέληται ἢ ἵν᾽ ἐγὼ μὴ πέμψω.’","st":"2.7"},{"sp":"N","t":"τί οὖν ἡμᾶς ἐπὶ τὸ οὕτω συνεχῶς μαντεύεσθαι ἄγει; ἡ δειλία, τὸ φοβεῖσθαι τὰς ἐκβάσεις. διὰ τοῦτο κολακεύομεν τοὺς μάντεις: ‘κληρονομήσω, κύριε, τὸν πατέρα;’ ‘ἴδωμεν: ἐπεκθυσώμεθα.’ ‘ναί, κύριε, ὡς ἡ τύχη θέλει.’ εἶτ᾽ ἂν εἴπῃ ‘κληρονομήσεις,’ ὡς παρ᾽ αὐτοῦ τὴν κληρονομίαν εἰληφότες εὐχαριστοῦμεν αὐτῷ. διὰ τοῦτο κἀκεῖνοι λοιπὸν ἐμπαίζουσιν ἡμῖν.","st":"2.7"},{"sp":"N","t":"τί οὖν; δεῖ δίχα ὀρέξεως ἔρχεσθαι καὶ ἐκκλίσεως, ὡς ὁ ὁδοιπόρος πυνθάνεται παρὰ τοῦ ἀπαντήσαντος, ποτέραν τῶν ὁδῶν φέρει, οὐκ ἔχων ὄρεξιν πρὸς τὸ τὴν δεξιὰν μᾶλλον φέρειν ἢ τὴν ἀριστεράν: οὐ γὰρ τούτων τινὰ ἀπελθεῖν θέλει, ἀλλὰ τὴν φέρουσαν.","st":"2.7"},{"sp":"N","t":"οὕτως ἔδει καὶ ἐπὶ τὸν θεὸν ἔρχεσθαι ὡς ὁδηγόν, ὡς τοῖς ὀφθαλμοῖς χρώμεθα, οὐ παρακαλοῦντες αὐτοὺς ἵνα τὰ τοιαῦτα μᾶλλον ἡμῖν δεικνύωσιν, ἀλλ᾽ οἷα ἐνδείκνυνται τούτων τὰς φαντασίας δεχόμενοι.","st":"2.7"},{"sp":"N","t":"νῦν δὲ τρέμοντες τὸ ὀρνιθάριον κρατοῦμεν καὶ τὸν θεὸν ἐπικαλούμενοι δεόμεθα αὐτοῦ:","st":"2.7"},{"sp":"N","t":"‘κύριε, ἐλέησον: ἐπίτρεψόν μοι ἐξελθεῖν.’ ἀνδράποδον, ἄλλο γάρ τι θέλεις ἢ τὸ ἄμεινον; ἄλλο οὖν τι ἄμεινον ἢ τὸ τῷ θεῷ δοκοῦν;","st":"2.7"},{"sp":"N","t":"τί τὸ ὅσον ἐπὶ σοὶ διαφθείρεις τὸν κριτήν, παράγεις τὸν σύμβουλον; τίς οὐσία τοῦ ἀγαθοῦ. ὁ θεὸς ὠφέλιμος: ἀλλὰ καὶ τἀγαθὸν ὠφέλιμον. εἰκὸς οὖν, ὅπου ἡ οὐσία τοῦ θεοῦ, ἐκεῖ εἶναι καὶ τὴν τοῦ ἀγαθοῦ.","st":"2.7"},{"sp":"N","t":"τίς οὖν οὐσία θεοῦ; σάρξ; μὴ γένοιτο. ἀγρός; μὴ γένοιτο. φήμη; μὴ γένοιτο. νοῦς, ἐπιστήμη, λόγος ὀρθός.","st":"2.8"},{"sp":"N","t":"ἐνταῦθα τοίνυν ἁπλῶς ζήτει τὴν οὐσίαν τοῦ ἀγαθοῦ. ἐπεί τοι μή τι αὐτὴν ἐν φυτῷ ζητεῖς; οὔ. μή τι ἐν ἀλόγῳ; οὔ. ἐν λογικῷ οὖν ζητῶν τί ἔτι ἀλλαχοῦ ζητεῖς ἢ ἐν τῇ παραλλαγῇ τῇ πρὸς τὰ ἄλογα;","st":"2.8"},{"sp":"N","t":"τὰ φυτὰ οὐδὲ φαντασίαις χρηστικά ἐστιν: διὰ τοῦτο οὐ λέγεις ἐπ᾽ αὐτῶν τὸ ἀγαθόν. δεῖται οὖν τὸ ἀγαθὸν χρήσεως φαντασιῶν.","st":"2.8"},{"sp":"N","t":"ἆρά γε μόνης; εἰ γὰρ μόνης, λέγε καὶ ἐν τοῖς ἄλλοις ζῴοις τὰ ἀγαθὰ εἶναι καὶ εὐδαιμονίαν καὶ κακοδαιμονίαν.","st":"2.8"},{"sp":"N","t":"νῦν δ᾽ οὐ λέγεις καὶ καλῶς ποιεῖς: εἰ γὰρ καὶ τὰ μάλιστα χρῆσιν φαντασιῶν ἔχει, ἀλλὰ παρακολούθησίν γε τῇ χρήσει τῶν φαντασιῶν οὐκ ἔχει. καὶ εἰκότως. ὑπηρετικὰ γὰρ γέγονεν ἄλλοις, οὐκ αὐτὰ προηγούμενα.","st":"2.8"},{"sp":"N","t":"ὁ ὄνος ἐπεὶ γέγονεν μή τι προηγουμένως; οὔ: ἀλλ᾽ ὅτι νώτου χρείαν. εἴχομεν βαστάζειν τι δυναμένου. ἀλλὰ νὴ Δία καὶ περιπατοῦντος αὐτοῦ χρείαν εἴχομεν: διὰ τοῦτο προσείληφε καὶ τὸ χρῆσθαι φαντασίαις: ἄλλως γὰρ περιπατεῖν οὐκ ἐδύνατο.","st":"2.8"},{"sp":"N","t":"καὶ λοιπὸν αὐτοῦ που πέπαυται. εἰ δὲ καὶ αὐτός που προσειλήφει παρακολούθησιν τῇ χρήσει τῶν φαντασιῶν, καὶ δῆλον ὅτι κατὰ λόγον οὐκέτ᾽ ἂν ἡμῖν ὑπετέτακτο οὐδὲ τὰς χρείας ταύτας παρεῖχεν, ἀλλ᾽ ἦν ἂν ἴσος ἡμῖν καὶ ὅμοιος.","st":"2.8"},{"sp":"N","t":"οὐ θέλεις οὖν ἐκεῖ ζητεῖν τὴν οὐσίαν τοῦ ἀγαθοῦ, οὗ μὴ παρόντος ἐπ᾽ οὐδενὸς τῶν ἄλλων θέλεις λέγειν τὸ ἀγαθόν;","st":"2.8"},{"sp":"N","t":"‘τί οὖν; οὐκ ἔστι θεῶν ἔργα κἀκεῖνα;’ ἔστιν, ἀλλ᾽ οὐ προηγούμενα οὐδὲ μέρη θεῶν.","st":"2.8"},{"sp":"N","t":"σὺ δὲ προηγούμενον εἶ, σὺ ἀπόσπασμα εἶ τοῦ θεοῦ: ἔχεις τι ἐν σεαυτῷ μέρος ἐκείνου. τί οὖν ἀγνοεῖς σου τὴν συγγένειαν; τί οὐκ οἶδας, πόθεν ἐλήλυθας;","st":"2.8"},{"sp":"N","t":"οὐ θέλεις μεμνῆσθαι, ὅταν ἐσθίῃς, τίς ὢν ἐσθίεις καὶ τίνα τρέφεις; ὅταν συνουσίᾳ χρῇ, τίς ὢν χρῇ; ὅταν ὁμιλίᾳ; ὅταν γυμνάζῃ, ὅταν διαλέγῃ, οὐκ οἶδας ὅτι θεὸν τρέφεις, θεὸν γυμνάζεις; θεὸν περιφέρεις, τάλας, καὶ ἀγνοεῖς.","st":"2.8"},{"sp":"N","t":"δοκεῖς με λέγειν ἀργυροῦν τινα ἢ χρυσοῦν ἔξωθεν; ἐν σαυτῷ φέρεις αὐτὸν καὶ μολύνων οὐκ αἰσθάνῃ ἀκαθάρτοις μὲν διανοήμασι, ῥυπαραῖς δὲ πράξεσι.","st":"2.8"},{"sp":"N","t":"καὶ ἀγάλματος μὲν τοῦ θεοῦ παρόντος οὐκ ἂν τολμήσαις τι τούτων ποιεῖν ὧν ποιεῖς. αὐτοῦ δὲ τοῦ θεοῦ παρόντος ἔσωθεν καὶ ἐφορῶντος πάντα καὶ ἐπακούοντος οὐκ αἰσχύνῃ ταῦτα ἐνθυμούμενος καὶ ποιῶν, ἀναίσθητε τῆς αὑτοῦ φύσεως καὶ θεοχόλωτε;","st":"2.8"},{"sp":"N","t":"λοιπὸν ἡμεῖς τί φοβούμεθα ἐκπέμποντες νέον ἐπί τινας πράξεις ἐκ τῆς σχολῆς, μὴ ἄλλως ποιήσῃ τι, μὴ ἄλλως φάγῃ, μὴ ἄλλως συνουσιάσῃ, μὴ ταπεινώσῃ αὐτὸν ῥάκη περιτεθέντα, μὴ ἐπάρῃ κομψὰ ἱμάτια;","st":"2.8"},{"sp":"N","t":"οὗτος οὐκ οἶδεν αὑτοῦ θεόν, οὗτος οὐκ οἶδεν, μετὰ τίνος ἀπέρχεται. ἀλλ᾽ ἀνεχόμεθα λέγοντος αὐτοῦ ‘σὲ ἤθελον ἔχειν;’","st":"2.8"},{"sp":"N","t":"ἐκεῖ τὸν θεὸν οὐκ ἔχεις; εἶτ᾽ ἄλλον τινὰ ζητεῖς ἐκεῖνον ἔχων;","st":"2.8"},{"sp":"N","t":"ἢ ἄλλα σοι ἐρεῖ ἐκεῖνος ἢ ταῦτα; ἀλλ᾽ εἰ μὲν τὸ ἄγαλμα ἦς τὸ Φειδίου, ἡ Ἀθηνᾶ ἢ ὁ Ζεύς, ἐμέμνησο ἂν καὶ σαυτοῦ καὶ τοῦ τεχνίτου καὶ εἴ τινα αἴσθησιν εἶχες, ἐπειρῶ ἂν μηδὲν ἂν ἀνάξιον ποιεῖν τοῦ κατασκευάσαντος μηδὲ σεαυτοῦ μηδ᾽ ἐν ἀπρεπεῖ σχήματι φαίνεσθαι τοῖς ὁρῶσι:","st":"2.8"},{"sp":"N","t":"νῦν δέ σε ὅτι ὁ Ζεὺς πεποίηκεν, διὰ τοῦτο ἀμελεῖς οἷόν τινα δείξεις σεαυτόν; καὶ τί ὁ τεχνίτης τῷ τεχνίτῃ ὅμοιος ἢ τὸ κατασκεύασμα τῷ κατασκευάσματι;","st":"2.8"},{"sp":"N","t":"καὶ ποῖον ἔργον τεχνίτου εὐθὺς ἔχει τὰς δυνάμεις ἐν ἑαυτῷ, ἃς ἐμφαίνει διὰ τῆς κατασκευῆς; οὐχὶ λίθος ἐστὶν ἢ χαλκὸς ἢ χρυσὸς ἢ ἐλέφας; καὶ ἡ Ἀθηνᾶ ἡ Φειδίου ἅπαξ ἐκτείνασα τὴν χεῖρα καὶ τὴν Νίκην ἐπ᾽ αὐτῆς δεξαμένη ἕστηκεν οὕτως ὅλῳ τῷ αἰῶνι, τὰ δὲ τοῦ θεοῦ κινούμενα, ἔμπνοα, χρηστικὰ φαντασιῶν, δοκιμαστικά.","st":"2.8"},{"sp":"N","t":"τούτου τοῦ δημιουργοῦ κατασκεύασμα ὢν καταισχύνεις αὐτό; τί δ᾽; ὅτι οὐ μόνον σε κατεσκεύασεν, ἀλλὰ καὶ σοὶ μόνῳ ἐπίστευσεν καὶ παρακατέθετο,","st":"2.8"},{"sp":"N","t":"οὐδὲ τούτου μεμνήσῃ, ἀλλὰ καὶ καταισχυνεῖς τὴν ἐπιτροπήν; εἰ δέ σοι ὀρφανόν τινα ὁ θεὸς παρέθετο, οὕτως ἂν αὐτοῦ ἠμέλεις;","st":"2.8"},{"sp":"N","t":"παραδέδωκέ σοι σεαυτὸν καὶ λέγει ‘οὐκ εἶχον ἄλλον πιστότερόν σου: τοῦτόν μοι φύλασσε τοιοῦτον οἷος πέφυκεν, αἰδήμονα, πιστόν, ὑψηλόν, ἀκατάπληκτον, ἀπαθῆ, ἀτάραχον.’ εἶτα σὺ οὐ φυλάσσεις;","st":"2.8"},{"sp":"N","t":"‘ἀλλ᾽ ἐροῦσιν: ‘πόθεν ἡμῖν οὗτος ὀφρῦν ἐνήνοχεν καὶ σεμνοπροσωπεῖ;’’ οὔπω κατ᾽ ἀξίαν. ‘ἔτι γὰρ οὐ θαρρῶ οἷς ἔμαθον καὶ συγκατεθέμην: ἔτι τὴν ἀσθένειαν τὴν ἐμαυτοῦ φοβοῦμαι.","st":"2.8"},{"sp":"N","t":"ἐπεί τοι ἄφετέ με θαρρῆσαι καὶ τότε ὄψεσθε βλέμμα οἷον δεῖ καὶ σχῆμα οἷον δεῖ, τότε ὑμῖν δείξω τὸ ἄγαλμα, ὅταν τελειωθῇ, ὅταν στιλπνωθῇ.","st":"2.8"},{"sp":"N","t":"τί δοκεῖτε; ὀφρῦν; μὴ γένοιτο. μὴ γὰρ ὁ Ζεὺς ὁ ἐν Ὀλυμπίᾳ ὀφρῦν ἀνέσπακεν; ἀλλὰ πέπηγεν αὐτοῦ τὸ βλέμμα, οἷον δεῖ εἶναι τοῦ ἐροῦντος οὐ γὰρ ἐμὸν παλινάγρετον οὐδ᾽ ἀπατηλόν. τοιοῦτον ὑμῖν δείξω ἐμαυτόν,","st":"2.8"},{"sp":"N","t":"πιστόν, αἰδήμονα, γενναῖον, ἀτάραχον.","st":"2.8"},{"sp":"N","t":"μή τι οὖν ἀθάνατον ἀγήρων, μή τι ἄνοσον; ἀλλ᾽ ἀποθνῄσκοντα θείως, νοσοῦντα θείως. ταῦτα ἔχω, ταῦτα δύναμαι: τὰ δ᾽ ἄλλα οὔτ᾽ ἔχω οὔτε δύναμαι.","st":"2.8"},{"sp":"N","t":"δείξω ὑμῖν νεῦρα φιλοσόφου. ποῖα νεῦρα; ὄρεξιν ἀναπότευκτον, ἔκκλισιν ἀπερίπτωτον, ὁρμὴν καθήκουσαν, πρόθεσιν ἐπιμελῆ, συγκατάθεσιν ἀπρόπτωτον. ταῦτα ὄψεσθε.’ ὅτι οὐ δυνάμενοι τὴν ἀνθρώπου ἐπαγγελίαν πληρῶσαι τὴν φιλοσόφου προσλαμβάνομεν. οὐκ ἔστι τὸ τυχὸν αὐτὸ μόνον ἀνθρώπου ἐπαγγελίαν πληρῶσαι.","st":"2.8"},{"sp":"N","t":"τί γάρ ἐστιν ἄνθρωπος; — ζῷον, φησί, λογικὸν θνητόν. — εὐθὺς ἐν τῷ λογικῷ τίνων χωριζόμεθα; — τῶν θηρίων. — καὶ τίνων ἄλλων;","st":"2.9"},{"sp":"N","t":"— τῶν προβάτων καὶ τῶν ὁμοίων. — ὅρα οὖν μή τί πως ὡς θηρίον ποιήσῃς: εἰ δὲ μή, ἀπώλεσας τὸν ἄνθρωπον, οὐκ ἐπλήρωσας τὴν ἐπαγγελίαν. ὅρα μή τι ὡς πρόβατον: εἰ δὲ μή, καὶ οὕτως ἀπώλετο ὁ ἄνθρωπος.","st":"2.9"},{"sp":"N","t":"τίνα οὖν ποιοῦμεν ὡς πρόβατα; ὅταν τῆς γαστρὸς ἕνεκα, ὅταν τῶν αἰδοίων, ὅταν εἰκῇ, ὅταν ῥυπαρῶς, ὅταν ἀνεπιστρέπτως, ποῦ ἀπεκλίναμεν; ἐπὶ τὰ πρόβατα.","st":"2.9"},{"sp":"N","t":"τί ἀπωλέσαμεν; τὸ λογικόν. ὅταν μαχίμως καὶ βλαβερῶς καὶ θυμικῶς καὶ ὠστικῶς, ποῦ ἀπεκλίναμεν;","st":"2.9"},{"sp":"N","t":"ἐπὶ τὰ θηρία. λοιπὸν οἱ μὲν ἡμῶν μεγάλα θηρία εἰσίν, οἱ δὲ θηρίδια κακοήθη καὶ μικρά, ἀφ᾽ ὧν ἔστιν εἰπεῖν","st":"2.9"},{"sp":"N","t":"‘λέων με καὶ φαγέτω.’ διὰ πάντων δὲ τούτων ἀπόλλυται ἡ τοῦ ἀνθρώπου ἐπαγγελία.","st":"2.9"},{"sp":"N","t":"πότε γὰρ σῴζεται συμπεπλεγμένον; ὅταν τὴν ἐπαγγελίαν πληρώσῃ, ὥστε σωτηρία συμπεπλεγμένου ἐστὶ τὸ ἐξ ἀληθῶν συμπεπλέχθαι. πότε διεζευγμένον; ὅταν τὴν ἐπαγγελίαν πληρώσῃ. πότε αὐλοί, πότε λύρα, πότε ἵππος, πότε κύων;","st":"2.9"},{"sp":"N","t":"τί οὖν θαυμαστόν, εἰ καὶ ἄνθρωπος ὡσαύτως μὲν σῴζεται, ὡσαύτως δ᾽ ἀπόλλυται;","st":"2.9"},{"sp":"N","t":"αὔξει δ᾽ ἕκαστον καὶ σῴζει τὰ κατάλληλα ἔργα: τὸν τέκτονα τὰ τεκτονικά, τὸν γραμματικὸν τὰ γραμματικά. ἂν δ᾽ ἐθίσῃ γράφειν ἀγραμμάτως, ἀνάγκη καταφθείρεσθαι καὶ ἀπόλλυσθαι τὴν τέχνην.","st":"2.9"},{"sp":"N","t":"οὕτως τὸν μὲν αἰδήμονα σῴζει τὰ αἰδήμονα ἔργα, ἀπολλύει δὲ τὰ ἀναιδῆ: τὸν δὲ πιστὸν τὰ πιστὰ καὶ τὰ ἐναντία ἀπολλύει.","st":"2.9"},{"sp":"N","t":"καὶ τοὺς ἐναντίους πάλιν ἐπαύξει τὰ ἐναντία: τὸν ἀναίσχυντον ἀναισχυντία, τὸν ἄπιστον ἀπιστία, τὸν λοίδορον λοιδορία, τὸν ὀργίλον ὀργή, τὸν φιλάργυρον αἱ ἀκατάλληλοι λήψεις καὶ δόσεις.","st":"2.9"},{"sp":"N","t":"διὰ τοῦτο παραγγέλλουσιν οἱ φιλόσοφοι μὴ ἀρκεῖσθαι μόνῳ τῷ μαθεῖν, ἀλλὰ καὶ μελέτην προσλαμβάνειν, εἶτα ἄσκησιν.","st":"2.9"},{"sp":"N","t":"πολλῷ γὰρ χρόνῳ τὰ ἐναντία ποιεῖν εἰθίσμεθα καὶ τὰς ὑπολήψεις τὰς ἐναντίας ταῖς ὀρθαῖς χρηστικὰς ἔχομεν. ἂν οὖν μὴ καὶ τὰς ὀρθὰς χρηστικὰς ποιήσωμεν, οὐδὲν ἄλλο ἢ ἐξηγηταὶ ἐσόμεθα ἀλλοτρίων δογμάτων.","st":"2.9"},{"sp":"N","t":"ἄρτι γὰρ τίς ἡμῶν οὐ δύναται τεχνολογῆσαι περὶ ἀγαθῶν καὶ κακῶν; ὅτι τῶν ὄντων τὰ μὲν ἀγαθά, τὰ δὲ κακά, τὰ δ᾽ ἀδιάφορα: ἀγαθὰ μὲν οὖν ἀρεταὶ καὶ τὰ μετέχοντα τῶν ἀρετῶν: κακὰ τὰ δ᾽ ἐναντία: ἀδιάφορα δὲ πλοῦτος, ὑγεία, δόξα.","st":"2.9"},{"sp":"N","t":"εἶτ᾽ ἂν μεταξὺ λεγόντων ἡμῶν ψόφος μείζων γένηται ἢ τῶν παρόντων τις καταγελάσῃ ἡμῶν, ἐξεπλάγημεν.","st":"2.9"},{"sp":"N","t":"ποῦ ἐστιν, φιλόσοφε, ἐκεῖνα ἃ ἔλεγες; πόθεν αὐτὰ προφερόμενος ἔλεγες; ἀπὸ τῶν χειλῶν αὐτόθεν. τί οὖν ἀλλότρια βοηθήματα μολύνεις; τί κυβεύεις περὶ τὰ μέγιστα;","st":"2.9"},{"sp":"N","t":"ἄλλο γάρ ἐστιν ὡς εἰς ταμιεῖον ἀποθέσθαι ἄρτους καὶ οἶνον, ἄλλο ἐστὶ φαγεῖν. τὸ βρωθὲν ἐπέφθη, ἀνεδόθη, νεῦρα ἐγένετο, σάρκες, ὀστέα, αἷμα, εὔχροια, εὔπνοια. τὰ ἀποκείμενα ὅταν μὲν θελήσῃς ἐκ προχείρου λαβὼν δεῖξαι δύνασαι, ἀπ᾽ αὐτῶν δέ σοι ὄφελος οὐδὲν εἰ μὴ μέχρι τοῦ δοκεῖν ὅτι ἔχεις. τί γὰρ διαφέρει ταῦτα ἐξηγεῖσθαι ἢ τὰ τῶν ἑτεροδόξων;","st":"2.9"},{"sp":"N","t":"τεχνολόγει νῦν καθίσας τὰ Ἐπικούρου καὶ τάχα ἐκείνου χρηστικώτερον τεχνολογήσεις. τί οὖν Στωικὸν λέγεις σεαυτόν, τί ἐξαπατᾷς τοὺς πολλούς, τί ὑποκρίνῃ Ἰουδαῖον ὢν Ἕλλην;","st":"2.9"},{"sp":"N","t":"οὐχ ὁρᾷς, πῶς ἕκαστος λέγεται Ἰουδαῖος, πῶς Σύρος, πῶς Αἰγύπτιος; καὶ ὅταν τινὰ ἐπαμφοτερίζοντα ἴδωμεν, εἰώθαμεν λέγειν ‘οὐκ ἔστιν Ἰουδαῖος, ἀλλ᾽ ὑποκρίνεται.’ ὅταν δ᾽ ἀναλάβῃ τὸ πάθος τὸ τοῦ βεβαμμένου καὶ ᾑρημένου, τότε καὶ ἔστι τῷ ὄντι καὶ καλεῖται Ἰουδαῖος.","st":"2.9"},{"sp":"N","t":"οὕτως καὶ ἡμεῖς παραβαπτισταί, λόγῳ μὲν Ἰουδαῖοι, ἔργῳ δ᾽ ἄλλο τι, ἀσυμπαθεῖς πρὸς τὸν λόγον, μακρὰν ἀπὸ τοῦ χρῆσθαι τούτοις ἃ λέγομεν, ἐφ᾽ οἷς ὡς εἰδότες αὐτὰ ἐπαιρόμεθα.","st":"2.9"},{"sp":"N","t":"οὕτως οὐδὲ τὴν τοῦ ἀνθρώπου ἐπαγγελίαν πληρῶσαι δυνάμενοι προσλαμβάνομεν τὴν τοῦ φιλοσόφου, τηλικοῦτο φορτίον οἷον εἴ τις δέκα λίτρας ἆραι μὴ δυνάμενος τὸν τοῦ Αἴαντος λίθον βαστάζειν ἤθελεν. πῶς ἀπὸ τῶν ὀνομάτων τὰ καθήκοντα ἔστιν εὑρίσκειν. σκέψαι τίς εἶ. τὸ πρῶτον ἄνθρωπος, τοῦτο δ᾽ ἔστιν οὐδὲν ἔχων κυριώτερον προαιρέσεως, ἀλλὰ ταύτῃ τὰ ἄλλα ὑποτεταγμένα, αὐτὴν δ᾽ ἀδούλευτον καὶ ἀνυπότακτον.","st":"2.9"},{"sp":"N","t":"σκόπει οὖν, τίνων κεχώρισαι κατὰ λόγον. κεχώρισαι θηρίων, κεχώρισαι προβάτων.","st":"2.10"},{"sp":"N","t":"ἐπὶ τούτοις πολίτης εἶ τοῦ κόσμου καὶ μέρος αὐτοῦ, οὐχ ἓν τῶν ὑπηρετικῶν, ἀλλὰ τῶν προηγουμένων: παρακολουθητικὸς γὰρ εἶ τῇ θείᾳ διοικήσει καὶ τοῦ ἑξῆς ἐπιλογιστικός.","st":"2.10"},{"sp":"N","t":"τίς οὖν ἐπαγγελία πολίτου; μηδὲν ἔχειν ἰδίᾳ συμφέρον, περὶ μηδενὸς βουλεύεσθαι ὡς ἀπόλυτον, ἀλλ᾽ ὥσπερ ἄν, εἰ ἡ χεὶρ ἢ ὁ ποὺς λογισμὸν εἶχον καὶ παρηκολούθουν τῇ φυσικῇ κατασκευῇ, οὐδέποτ᾽ ἂν ἄλλως ὥρμησαν ἢ ὠρέχθησαν ἢ ἐπανενεγκόντες ἐπὶ τὸ ὅλον.","st":"2.10"},{"sp":"N","t":"διὰ τοῦτο καλῶς λέγουσιν οἱ φιλόσοφοι ὅτι εἰ προῄδει ὁ καλὸς καὶ ἀγαθὸς τὰ ἐσόμενα, συνήργει ἂν καὶ τῷ νοσεῖν καὶ τῷ ἀποθνῄσκειν καὶ τῷ πηροῦσθαι, αἰσθανόμενός γε, ὅτι ἀπὸ τῆς τῶν ὅλων διατάξεως τοῦτο ἀπονέμεται, κυριώτερον δὲ τὸ ὅλον τοῦ μέρους καὶ ἡ πόλις τοῦ πολίτου.","st":"2.10"},{"sp":"N","t":"νῦν δ᾽ ὅτι οὐ προγιγνώσκομεν, καθήκει τῶν πρὸς ἐκλογὴν εὐφυεστέρων ἔχεσθαι, ὅτι καὶ πρὸς τοῦτο γεγόναμεν.","st":"2.10"},{"sp":"N","t":"μετὰ τοῦτο μέμνησο, ὅτι υ ἱὸς εἶ. τίς τούτου τοῦ προσώπου ἐπαγγελία; πάντα τὰ αὑτοῦ ἡγεῖσθαι τοῦ πατρός, πάντα ὑπακούειν, μηδέποτε ψέξαι πρός τινα μηδὲ βλαβερόν τι αὐτῷ εἰπεῖν ἢ πρᾶξαι, ἐξίστασθαι ἐν πᾶσιν καὶ παραχωρεῖν συνεργοῦντα κατὰ δύναμιν. μετὰ τοῦτο ἴσθι ὅτι καὶ ἀδελφὸς εἶ.","st":"2.10"},{"sp":"N","t":"καὶ πρὸς τοῦτο δὲ τὸ πρόσωπον ὀφείλεται παραχώρησις, εὐπείθεια, εὐφημία, μηδέποτ᾽ ἀντιποιήσασθαί τινος πρὸς ἑαὐτὸν τῶν ἀπροαιρέτων, ἀλλ᾽ ἡδέως ἐκεῖνα προίεσθαι, ἵν᾽ ἐν τοῖς προαιρετικοῖς πλέον ἔχῃς.","st":"2.10"},{"sp":"N","t":"ὅρα γὰρ οἷόν ἐστιν ἀντὶ θίδρακος, ἂν οὕτως τύχῃ, καὶ καθέδρας αὐτὸν εὐγνωμοσύνην κτήσασθαι, ὅση ἡ πλεονεξία.","st":"2.10"},{"sp":"N","t":"μετὰ ταῦτα εἰ βουλευτὴς πόλεώς τινος, ὅτι βουλευτής: εἰ νέος, ὅτι νέος: εἰ πρεσβύτης, ὅτι πρεσβύτης: εἰ πατήρ, ὅτι πατήρ.","st":"2.10"},{"sp":"N","t":"ἀεὶ γὰρ ἕκαστον τῶν τοιούτων ὀνομάτων εἰς ἐπιλογισμὸν ἐρχόμενον ὑπογράφει τὰ οἰκεῖα ἔργα.","st":"2.10"},{"sp":"N","t":"ἐὰν δ᾽ ἀπελθὼν ψέγῃς σου τὸν ἀδελφόν, λέγω σοι ‘ἐπελάθου, τίς εἶ καὶ τί σοι ὄνομα.’","st":"2.10"},{"sp":"N","t":"εἶτα εἰ μὲν χαλκεὺς ὢν ἐχρῶ τῇ σφύρᾳ ἄλλως, ἐπιλελησμένος ἂν ἦς τοῦ χαλκέως: εἰ δὲ τοῦ ἀδελφοῦ ἐπελάθου καὶ ἀντὶ ἀδελφοῦ ἐχθρὸς ἐγένου, οὐδὲν ἀντ᾽ οὐδενὸς ἠλλάχθαι φανεῖ σεαυτῷ;","st":"2.10"},{"sp":"N","t":"εἰ δ᾽ ἀντὶ ἀνθρώπου, ἡμέρου ζῴου καὶ κοινωνικοῦ, θηρίον γέγονας βλαβερόν, ἐπίβουλον, δηκτικόν, οὐδὲν ἀπολώλεκας; ἀλλὰ δεῖ σε κέρμα ἀπολέσαι, ἵνα ζημιωθῆς, ἄλλου δ᾽ οὐδενὸς ἀπώλεια ζημιοῖ τὸν ἄνθρωπον;","st":"2.10"},{"sp":"N","t":"εἶτα γραμματικὴν μὲν ἀποβαλὼν ἢ μουσικὴν ζημίαν ἂν ἡγοῦ τὴν ἀπώλειαν αὐτῆς: εἰ δ᾽ αἰδῶ καὶ καταστολὴν καὶ ἡμερότητα ἀποβαλεῖς, οὐδὲν ἡγῇ τὸ πρᾶγμα;","st":"2.10"},{"sp":"N","t":"καίτοι ἐκεῖνα μὲν παρ᾽ ἔξωθέν τινα καὶ ἀπροαίρετον αἰτίαν ἀπόλλυται, ταῦτα δὲ παρ᾽ ἡμᾶς: καὶ ἐκεῖνα μὲν οὔτ᾽ ἔχειν καλόν ἐστιν οὔτ᾽ ἀπολλύειν αἰσχρόν ἐστιν, ταῦτα δὲ καὶ μὴ ἔχειν καὶ ἀπολλύειν καὶ αἰσχρόν ἐστι καὶ ἐπονείδιστον καὶ ἀτύχημα. τί ἀπολλύει ὁ τὰ τοῦ κιναίδου πάσχων;","st":"2.10"},{"sp":"N","t":"τὸν ἄνδρα. ὁ δὲ διατιθείς; πολλὰ μὲν καὶ ἄλλα καὶ αὐτὸς δ᾽ οὐδὲν ἧττον","st":"2.10"},{"sp":"N","t":"τὸν ἄνδρα. τί ἀπολλύει ὁ μοιχεύων; τὸν αἰδήμονα, τὸν ἐγκρατῆ, τὸν κόσμιον, τὸν πολίτην, τὸν γείτονα. τί ἀπολλύει ὁ ὀργιζόμενος; ἄλλο τι. ὁ φοβούμενος;","st":"2.10"},{"sp":"N","t":"ἄλλο τι. οὐδεὶς δίχα ἀπωλείας καὶ ζημίας κακός ἐστιν. λοιπὸν εἰ τὴν ζημίαν ζητεῖς ἐν κέρματι, πάντες οὗτοι ἀβλαβεῖς, ἀζήμιοι, ἂν οὕτως τύχῃ, καὶ ὠφελούμενοι καὶ κερδαίνοντες, ὅταν διά τινος τούτων τῶν ἔργων κέρμα αὐτοῖς προσγένηται.","st":"2.10"},{"sp":"N","t":"ὅρα δ᾽ εἰ ἐπὶ κερμάτιον πάντα ἀνάγεις, ὅτι οὐδ᾽ ὁ τὴν ῥῖνά σοι ἀπολλύων ἔσται βεβλαμμένος. — ναί, φησίν, κεκολόβωται γὰρ τὸ σῶμα.","st":"2.10"},{"sp":"N","t":"— ἄγε, ὁ δὲ τὴν ὀσφρασίαν αὐτὴν ἀπολωλεκὼς οὐδὲν ἀπολλύει; ψυχῆς οὖν δύναμις οὐκ ἔστιν οὐδεμία, ἣν ὁ μὲν κτησάμενος ὠφελεῖται, ὁ δ᾽ ἀποβαλὼν ζημιοῦται;","st":"2.10"},{"sp":"N","t":"— ποίαν καὶ λέγεις; — οὐδὲν ἔχομεν αἰδῆμον φύσει; — ἔχομεν. — ὁ τοῦτο ἀπολλύων οὐ ζημιοῦται, οὐδενὸς στερίσκεται, οὐδὲν ἀποβάλλει τῶν πρὸς αὑτόν;","st":"2.10"},{"sp":"N","t":"οὐκ ἔχομεν φύσει τι πιστόν, φύσει στερκτικόν, φύσει ὠφελητικόν, ἀλλήλων φύσει ἀνεκτικόν; ὅστις οὖν εἰς ταῦτα περιορᾷ ζημιούμενον ἑαυτόν, οὗτος ᾖ ἀβλαβὴς καὶ ἀζήμιος;","st":"2.10"},{"sp":"N","t":"τί οὖν; μὴ βλάψω τὸν βλάψαντα; — πρῶτον μὲν ἰδού, τί ἐστι βλάβη καὶ μνήσθητι ὧν ἤκουσας παρὰ τῶν φιλοσόφων.","st":"2.10"},{"sp":"N","t":"εἰ γὰρ τὸ ἀγαθὸν ἐν προαιρέσει καὶ τὸ κακὸν ὡσαύτως ἐν προαιρέσει, βλέπε μὴ τοιοῦτ᾽ ἐστιν ὃ λέγεις","st":"2.10"},{"sp":"N","t":"‘τί οὖν; ἐπειδὴ ἐκεῖνος ἑαυτὸν ἔβλαψεν πρὸς ἐμέ τι ἄδικον ποιήσας, ἐγὼ ἐμαυτὸν μὴ βλάψω πρὸς ἐκεῖνον ἄδικόν τι ποιήσας;’","st":"2.10"},{"sp":"N","t":"τί οὖν οὐ τοιοῦτόν τι φανταζόμεθα, ἀλλ᾽ ὅπου τι σωματικὸν ἐλάττωμα ἢ εἰς κτῆσιν, ἐκεῖ ἡ βλάβη, ὅπου εἰς τὴν προαίρεσιν, οὐδεμία βλάβη;","st":"2.10"},{"sp":"N","t":"οὔτε γὰρ τὴν κεφαλὴν ἀλγεῖ ὁ ἐξαπατηθεὶς ἢ ἀδικήσας οὔτε τὸν ὀφθαλμὸν οὔτε τὸ ἰσχίον οὔτε τὸν ἀγρὸν ἀπολλύει.","st":"2.10"},{"sp":"N","t":"ἡμεῖς δ᾽ ἄλλο οὐδὲν ἐθέλομεν ἢ ταῦτα: τὴν προαίρεσιν δὲ πρότερον αἰδήμονα καὶ πιστὴν ἕξομεν ἢ ἀναίσχυντον καὶ ἄπιστον, οὐδ᾽ ἐγγὺς διαφερόμεθα πλὴν μόνον ἐν τῇ σχολῇ μέχρι τῶν λογαρίων.","st":"2.10"},{"sp":"N","t":"τοιγαροῦν μέχρι τῶν λογαρίων προκόπτομεν, ἔξω δ᾽ αὐτῶν οὐδὲ τὸ ἐλάχιστον. τίς ἀρχὴ φιλοσοφίας. ἀρχὴ φιλοσοφίας παρά γε τοῖς ὡς δεῖ καὶ κατὰ θύραν ἁπτομένοις αὐτῆς συναίσθησις τῆς αὑτοῦ ἀσθενείας καὶ ἀδυναμίας περὶ τὰ ἀναγκαῖα.","st":"2.10"},{"sp":"N","t":"ὀρθογωνίου μὲν γὰρ τριγώνου ἢ διέσεως ἡμιτονίου οὐδεμίαν φύσει ἔννοιαν ἥκομεν ἔχοντες, ἀλλ᾽ ἔκ τινος τεχνικῆς παραλήψεως διδασκόμεθα ἕκαστον αὐτῶν καὶ διὰ τοῦτο οἱ μὴ εἰδότες αὐτὰ οὐδ᾽ οἴονται εἰδέναι.","st":"2.11"},{"sp":"N","t":"ἀγαθοῦ δὲ καὶ κακοῦ καὶ καλοῦ καὶ αἰσχροῦ καὶ πρέποντος καὶ ἀπρεποῦς καὶ εὐδαιμονίας καὶ προσήκοντος καὶ ἐπιβάλλοντος καὶ ὅ τι δεῖ ποιῆσαι καὶ ὅ τι οὐ δεῖ ποιῆσαι τίς οὐκ ἔχων ἔμφυτον ἔννοιαν ἐλήλυθεν;","st":"2.11"},{"sp":"N","t":"διὰ τοῦτο πάντες χρώμεθα τοῖς ὀνόμασιν καὶ ἐφαρμόζειν πειρώμεθα τὰς προλήψεις ταῖς ἐπὶ μέρους οὐσίαις.","st":"2.11"},{"sp":"N","t":"καλῶς ἐποίησεν, δεόντως, οὐ δεόντως: ἠτύχησεν, εὐτύχησεν: ἄδικός ἐστιν, δίκαιός ἐστιν. τίς ἡμῶν φείδεται τούτων τῶν ὀνομάτων; τίς ἡμῶν ἀναβάλλεται τὴν χρῆσιν αὐτῶν μέχρι μάθῃ καθάπερ τῶν περὶ τὰς γραμμὰς ἢ τοὺς φθόγγους οἱ οὐκ εἰδότες;","st":"2.11"},{"sp":"N","t":"τούτου δ᾽ αἴτιον τὸ ἥκειν ἤδη τινὰ ὑπὸ τῆς φύσεως κατὰ τὸν τόπον ὥσπερ δεδιδαγμένους, ἀφ᾽ ὧν ὁρμώμενοι καὶ τὴν οἴησιν προσειλήφαμεν.","st":"2.11"},{"sp":"N","t":"— † διὰ γάρ, φησίν, οὐκ οἶδα ἐγὼ τὸ καλὸν καὶ τὸ αἰσχρόν; οὐκ ἔχω ἔννοιαν αὐτοῦ; — ἔχεις. — οὐκ ἐφαρμόζω τοῖς ἐπὶ μέρους; — ἐφαρμόζεις. — οὐ καλῶς οὖν ἐφαρμόζω;","st":"2.11"},{"sp":"N","t":"— ἐνταῦθά ἐστι τὸ ζήτημα πᾶν καὶ οἴησις ἐνταῦθα προσγίνεται. ἀφ᾽ ὁμολογουμένων γὰρ ὁρμώμενοι τούτων ἐπὶ τὸ ἀμφισβητούμενον προάγουσιν ὑπὸ τῆς ἀκαταλλήλου ἐφαρμογῆς.","st":"2.11"},{"sp":"N","t":"ὡς εἴ γε καὶ τοῦτο ἔτι πρὸς ἐκείνοις ἐκέκτηντο, τί ἐκώλυεν αὐτοὺς εἶναι τελείους;","st":"2.11"},{"sp":"N","t":"νῦν δ᾽ ἐπεὶ δοκεῖς ὅτι καὶ καταλλήλως ἐφαρμόζεις τὰς προλήψεις τοῖς ἐπὶ μέρους, εἰπέ μοι, πόθεν τοῦτο λαμβάνεις; — ὅτι δοκεῖ μοι. — τουτὶ οὖν ᾧτινι οὐ δοκεῖ, καὶ οἴεται καὶ αὐτὸς ἐφαρμόζειν καλῶς: ἢ οὐκ οἴεται;","st":"2.11"},{"sp":"N","t":"— οἴεται. — δύνασθε οὖν περὶ ὧν τὰ μαχόμενα δοξάζετε ἀμφότεροι καταλλήλως ἐφαρμόζειν τὰς προλήψεις;","st":"2.11"},{"sp":"N","t":"— οὐ δυνάμεθα. — ἔχεις οὖν δεῖξαί τι ἡμῖν πρὸς τὸ αὐτὰς ἐφαρμόζειν ἄμεινον ἀνωτέρω τοῦ δοκεῖν σοι; ὁ δὲ μαινόμενος ἄλλα τινὰ ποιεῖ ἢ τὰ δοκοῦντά οἱ καλά; κἀκείνῳ οὖν ἀρκεῖ τοῦτο τὸ κριτήριον; — οὐκ ἀρκεῖ. — ἐλθὼν οὖν ἐπί τι ἀνωτέρω τοῦ δοκεῖν τί τοῦτό ἐστιν †","st":"2.11"},{"sp":"N","t":"ἴδ᾽ ἀρχὴ φιλοσοφίας: αἴσθησις μάχης τῆς πρὸς ἀλλήλους τῶν ἀνθρώπων καὶ ζήτησις τοῦ παρ᾽ ὃ γίνεται ἡ μάχη καὶ κατάγνωσις καὶ ἀπιστία πρὸς τὸ ψιλῶς δοκοῦν, ἔρευνα δέ τις περὶ τὸ δοκοῦν εἰ ὀρθῶς δοκεῖ καὶ εὕρεσις κανόνος τινός, οἷον ἐπὶ βαρῶν τὸν ζυγὸν εὕρομεν, οἷον ἐπὶ εὐθέων καὶ στρεβλῶν τὴν στάθμην.","st":"2.11"},{"sp":"N","t":"— τοῦτ᾽ ἔστιν ἀρχὴ φιλοσοφίας; πάντα καλῶς ἔχει τὰ δοκοῦντα ἅπασι; — καὶ πῶς δυνατὸν τὰ μαχόμενα καλῶς ἔχειν; οὐκοῦν οὐ πάντα, ἀλλὰ τὰ ἡμῖν δοκοῦντα.","st":"2.11"},{"sp":"N","t":"τί μᾶλλον ἢ τὰ Σύροις, τί μᾶλλον ἢ τὰ Αἰγυπτίοις, τί μᾶλλον ἢ τὰ ἐμοὶ φαινόμενα ἢ τὰ τῷ δεῖνι; — οὐδὲν μᾶλλον. — οὐκ ἄρα ἀρκεῖ τὸ δοκοῦν ἑκάστῳ πρὸς τὸ εἶναι: οὐδὲ γὰρ ἐπὶ βαρῶν ἢ μέτρων ψιλῇ τῇ ἐμφάσει ἀρκούμεθα, ἀλλὰ κανόνα τινὰ ἐφ᾽ ἑκάστου εὕρομεν.","st":"2.11"},{"sp":"N","t":"ἐνταῦθ᾽ οὖν οὐδεὶς κανὼν ἀνωτέρω τοῦ δοκεῖν; καὶ πῶς οἷόν τε ἀτέκμαρτα εἶναι καὶ ἀνεύρετα τὰ ἀναγκαιότατα ἐν ἀνθρώποις; — ἔστιν οὖν.","st":"2.11"},{"sp":"N","t":"— καὶ διὰ τί οὐ ζητοῦμεν αὐτὸν καὶ ἀνευρίσκομεν καὶ ἀνευρόντες λοιπὸν ἀπαραβάτως χρώμεθα δίχα αὐτοῦ μηδὲ τὸν δάκτυλον ἐκτείνοντες;","st":"2.11"},{"sp":"N","t":"τοῦτο γάρ, οἶμαι, ἐστὶν ὃ εὑρεθὲν ἀπαλλάσσει μανίας τοὺς μόνῳ τῷ δοκεῖν μέτρῳ πάντων χρωμένους, ἵνα λοιπὸν ἀπό τινων γνωρίμων καὶ διευκρινημένων ὁρμώμενοι χρώμεθα ἐπὶ τῶν ἐπὶ μέρους διηρθρωμέναις ταῖς προλήψεσι. τίς ὑποπέπτωκεν οὐσία περὶ ἧς ζητοῦμεν;","st":"2.11"},{"sp":"N","t":"— ἡδονή.","st":"2.11"},{"sp":"N","t":"— ὕπαγε αὐτὴν τῷ κανόνι, βάλε εἰς τὸν ζυγόν. τὸ ἀγαθὸν δεῖ εἶναι τοιοῦτον, ἐφ᾽ ᾧ θαρρεῖν ἄξιον καὶ ᾧ πεποιθέναι; — δεῖ. — ἀβεβαίῳ οὖν τινι θαρρεῖν ἄξιον;","st":"2.11"},{"sp":"N","t":"— οὔ. — μή τι οὖν βέβαιον ἡ ἡδονή; — οὔ. — ἆρον οὖν καὶ βάλε ἔξω ἐκ τοῦ ζυγοῦ καὶ ἀπέλασον τῆς χώρας τῶν ἀγαθῶν μακράν.","st":"2.11"},{"sp":"N","t":"εἰ δ᾽ οὐκ ὀξυβλεπτεῖς καὶ ἕν σοι ζυγὸν οὐκ ἀρκεῖ, φέρε ἄλλο. ἐπὶ τῷ ἀγαθῷ ἄξιον ἐπαίρεσθαι; — ναί. — ἐφ᾽ ἡδονῇ οὖν παρούσῃ ἄξιον ἐπαίρεσθαι; βλέπε μὴ εἴπῃς ὅτι ἄξιον: εἰ δὲ μή, οὐκέτι σε οὐδὲ τοῦ ζυγοῦ ἄξιον ἡγήσομαι.","st":"2.11"},{"sp":"N","t":"οὕτως κρίνεται τὰ πράγματα καὶ ἵσταται τῶν κανόνων ἡτοιμασμένων:","st":"2.11"},{"sp":"N","t":"καὶ τὸ φιλοσοφεῖν τοῦτό ἐστιν, ἐπισκέπτεσθαι καὶ βεβαιοῦν τοὺς κανόνας,","st":"2.11"},{"sp":"N","t":"τὸ δ᾽ ἤδη χρῆσθαι τοῖς ἐγνωσμένοις τοῦτο τοῦ καλοῦ καὶ ἀγαθοῦ ἔργον ἐστίν. περὶ τοῦ διαλέγεσθαι. ἃ μὲν δεῖ μαθόντα εἰδέναι χρῆσθαι λόγῳ, ἠκρίβωται ὑπὸ τῶν ἡμετέρων. περὶ δὲ τὴν χρῆσιν αὐτῶν τὴν προσήκουσαν τελέως ἀγύμναστοί ἐσμεν.","st":"2.11"},{"sp":"N","t":"δὸς γοῦν ᾧ θέλεις ἡμῶν ἰδιώτην τινὰ τὸν προσδιαλεγόμενον: καὶ οὐχ εὑρίσκει χρήσασθαι αὐτῷ, ἀλλὰ μικρὰ κινήσας τὸν ἄνθρωπον, ἂν παρὰ σκέλος ἀπαντᾷ ἐκεῖνος, οὐκέτι δύναται μεταχειρίσασθαι, ἀλλ᾽ ἢ λοιδορεῖ λοιπὸν ἢ καταγελᾷ καὶ λέγει ‘ἰδιώτης ἐστίν: οὐκ ἔστιν αὐτῷ χρήσασθαι.’","st":"2.12"},{"sp":"N","t":"ὁ δ᾽ ὁδηγός, ὅταν λάβῃ τινὰ πλανώμενον, ἤγαγεν ἐπὶ τὴν ὁδὸν τὴν δέουσαν, οὐχὶ καταγελάσας ἢ λοιδορησάμενος ἀπῆλθεν.","st":"2.12"},{"sp":"N","t":"καὶ σὺ δεῖξον αὐτῷ τὴν ἀλήθειαν καὶ ὄψει ὅτι ἀκολουθεῖ. μέχρι δ᾽ ἂν οὗ μὴ δεικνύῃς, μὴ ἐκείνου καταγέλα, ἀλλὰ μᾶλλον αἰσθάνου τῆς ἀδυναμίας τῆς αὑτοῦ.","st":"2.12"},{"sp":"N","t":"πῶς οὖν ἐποίει Σωκράτης; αὐτὸν ἠνάγκαζεν τὸν προσδιαλεγόμενον αὐτῷ μαρτυρεῖν, ἄλλου δ᾽ οὐδενὸς ἐδεῖτο μάρτυρος. τοιγαροῦν ἐξῆν αὐτῷ λέγειν ὅτι ‘τοὺς μὲν ἄλλους ἐῶ χαίρειν, ἀεὶ δὲ τῷ ἀντιλέγοντι ἀρκοῦμαι μάρτυρι: καὶ τοὺς μὲν ἄλλους οὐκ ἐπιψηφίζω, τὸν δὲ προσδιαλεγόμενον μόνον.’","st":"2.12"},{"sp":"N","t":"οὕτω γὰρ ἐναργῆ ἐτίθει τὰ ἀπὸ τῶν ἐννοιῶν, ὥστε πάνθ᾽ ὁντιναοῦν συναισθανόμενον τῆς μάχης ἀναχωρεῖν ἀπ᾽ αὐτῆς.","st":"2.12"},{"sp":"N","t":"‘ἆρά γε ὁ φθονῶν χαίρει;’—’οὐδαμῶς, ἀλλὰ μᾶλλον λυπεῖται.’ ἀπὸ τοῦ ἐναντίου ἐκίνησε τὸν πλησίον. ‘τί δ᾽; ἐπὶ κακοῖς δοκεῖ σοι εἶναι λύπη ὁ φθόνος; καὶ τί ὁ φθόνος ἐστὶ κακῶν;’","st":"2.12"},{"sp":"N","t":"οὐκοῦν ἐκεῖνον ἐποίησεν εἰπεῖν ὅτι λύπη ἐστὶν ἐπ᾽ ἀγαθοῖς ὁ φθόνος. ‘τί δέ; φθονοίη ἄν τις τοῖς οὐδὲν πρὸς αὐτόν;’","st":"2.12"},{"sp":"N","t":"—’οὐδαμῶς.’ καὶ οὕτως ἐκπεπληρωκὼς τὴν ἔννοιαν καὶ διηρθρωκὼς ἀπηλλάσσετο, οὐ λέγων ὅτι ‘ὅρισαί μοι τὸν φθόνον,’ εἶτα ὁρισαμένου ‘κακῶς ὡρίσω: οὐ γὰρ ἀντακολουθεῖ τῷ κεφαλαιώδει τὸ ὁρικόν:’","st":"2.12"},{"sp":"N","t":"ῥήματα τεχνικὰ καὶ διὰ τοῦτο τοῖς ἰδιώταις φορτικὰ καὶ δυσπαρακολούθητα, ὧν ἡμεῖς ἀποστῆναι οὐ δυνάμεθα.","st":"2.12"},{"sp":"N","t":"ἐξ ὧν δ᾽ αὐτὸς ὁ ἰδιώτης ἐπακολουθῶν ταῖς αὑτοῦ φαντασίαις παραχωρῆσαι δύναιτ᾽ ἄν τι ἢ ἀθετῆσαι, οὐδαμῶς διὰ τούτων αὐτὸν κινῆσαι δυνάμεθα.","st":"2.12"},{"sp":"N","t":"καὶ λοιπὸν εἰκότως συναισθανόμενοι ταύτης ἡμῶν τῆς ἀδυναμίας ἀπεχόμεθα τοῦ πράγματος, ὅσοις γ᾽ ἐστί τι εὐλαβείας.","st":"2.12"},{"sp":"N","t":"οἱ δὲ πολλοὶ καὶ εἰκαῖοι συγκαθέντες εἴς τι τοιοῦτον φύρονται καὶ φύρουσι καὶ τὰ τελευταῖα λοιδορήσαντες καὶ λοιδορηθέντες ἀπέρχονται.","st":"2.12"},{"sp":"N","t":"τὸ πρῶτον δὲ τοῦτο καὶ μάλιστα ἴδιον Σωκράτους μηδέποτε παροξυνθῆναι ἐν λόγῳ, μηδέποτε λοίδορον προενέγκασθαι μηδέν, μηδέποθ᾽ ὑβριστικόν, ἀλλὰ τῶν λοιδορούντων ἀνέχεσθαι καὶ παύειν μάχην.","st":"2.12"},{"sp":"N","t":"εἰ θέλετε γνῶναι, πόσην ἐν τούτῳ δύναμιν εἶχεν, ἀνάγνωτε τὸ Ξενοφῶντος Συμπόσιον καὶ ὄψεσθε πόσας μάχας διαλέλυκεν.","st":"2.12"},{"sp":"N","t":"διὰ τοῦτο εἰκότως καὶ παρὰ τοῖς ποιηταῖς ἐν μεγίστῳ ἐπαίνῳ λέλεκται τὸ αἶψά τε καὶ μέγα νεῖκος ἐπισταμένως κατέπαυσεν.","st":"2.12"},{"sp":"N","t":"τί οὖν; οὐ λίαν ἐστὶ νῦν ἀσφαλὲς τὸ πρᾶγμα καὶ μάλιστα ἐν Ῥώμῃ. τὸν γὰρ ποιοῦντα αὐτὸ οὐκ ἐν γωνίᾳ δηλονότι δεήσει ποιεῖν, ἀλλὰ προσελθόντα ὑπατικῷ τινι, ἂν οὕτως τύχῃ, πλουσίῳ πυθέσθαι αὐτοῦ","st":"2.12"},{"sp":"N","t":"‘ἔχεις μοι εἰπεῖν, ὦ οὗτος, ᾧ τινι τοὺς ἵππους τοὺς σεαυτοῦ παρέδωκας;’ ‘ἔγωγε.’ ‘ἆρα τῷ τυχόντι καὶ ἀπείρῳ ἱππικῆς;’ ‘οὐδαμῶς.’ ‘τί δ᾽; ᾧ τινι τὸ χρυσίον ἢ τὸ ἀργύριον ἢ τὴν ἐσθῆτα;’ ‘οὐδὲ ταῦτα τῷ τυχόντι.’","st":"2.12"},{"sp":"N","t":"‘τὸ σῶμα δὲ τὸ σαυτοῦ ἤδη τινὶ ἔσκεψαι ἐπιτρέψαι εἰς ἐπιμέλειαν αὐτοῦ;’ ‘πῶς γὰρ οὔ;’ ‘ἐμπείρῳ δηλονότι καὶ τούτῳ ἀλειπτικῆς ἢ ἰατρικῆς;’ ‘πάνυ μὲν οὖν.’","st":"2.12"},{"sp":"N","t":"‘πότερον ταῦτά σοι τὰ κράτιστά ἐστιν ἢ καὶ ἄλλο τι ἐκτήσω πάντων ἄμεινον;’ ‘ποῖον καὶ λέγεις;’ ‘τὸ αὐτοῖς νὴ Δία τούτοις χρώμενον καὶ δοκιμάζον ἕκαστον καὶ βουλευόμενον.’","st":"2.12"},{"sp":"N","t":"‘ἆρά γε τὴν ψυχὴν λέγεις;’ ‘ὀρθῶς ὑπέλαβες: ταύτην γάρ τοι καὶ λέγω.’ ‘πολὺ νὴ Δία τῶν ἄλλων τοῦτο ἄμεινον δοκῶ μοι κεκτῆσθαι.’","st":"2.12"},{"sp":"N","t":"‘ἔχεις οὖν εἰπεῖν, ὅτῳ τρόπῳ τῆς ψυχῆς ἐπιμεμέλησαι; οὐ γὰρ εἰκῇ χὠς ἔτυχεν εἰκός σε οὕτως σοφὸν ὄντα καὶ ἐν τῇ πόλει δόκιμον τὸ κράτιστον τῶν σεαυτοῦ περιορᾶν ἀμελούμενον καὶ ἀπολλύμενον.’","st":"2.12"},{"sp":"N","t":"‘οὐδαμῶς.’ ‘ἀλλ᾽ αὐτὸς ἐπιμεμέλησαι αὐτοῦ; πότερον μαθὼν παρά του ἢ εὑρὼν αὐτός;’ ὧδε λοιπὸν ὁ κίνδυνος, μὴ πρῶτον μὲν εἴπῃ","st":"2.12"},{"sp":"N","t":"‘τί δέ σοι μέλει, βέλτιστε; κύριός μου εἶ;’ εἶτ᾽ ἂν ἐπιμείνῃς πράγματα παρέχων, διαράμενος κονδύλους σοι δῷ.","st":"2.12"},{"sp":"N","t":"τούτου τοῦ πράγματος ἤμην ποτὲ ζηλωτὴς καὶ αὐτός, πρὶν εἰς ταῦτα ἐμπεσεῖν. περὶ τοῦ ἀγωνιᾶν. ὅταν ἀγωνιῶντα ἴδω ἄνθρωπον, λέγω: οὗτος τί ποτε θέλει; εἰ μὴ τῶν οὐκ ἐφ᾽ αὑτῷ τι ἤθελεν, πῶς ἂν ἔτι ἠγωνία;","st":"2.12"},{"sp":"N","t":"διὰ τοῦτο καὶ ὁ κιθαρῳδὸς μόνος μὲν ᾁδων οὐκ ἀγωνιᾷ, εἰς θέατρον δ᾽ εἰσερχόμενος, κἂν λίαν εὔφωνος ᾖ καὶ καλῶς κιθαρίζῃ: οὐ γὰρ ᾆσαι μόνον θέλει καλῶς, ἀλλὰ καὶ εὐδοκιμῆσαι, τοῦτο δ᾽ οὐκέτι ἐστὶν ἐπ᾽ αὐτῷ.","st":"2.13"},{"sp":"N","t":"λοιπὸν οὗ μὲν ἡ ἐπιστήμη αὐτῷ πρόσεστιν, ἐκεῖ τὸ θάρσος: φέρε ὃν θέλεις ἰδιώτην καὶ οὐκ ἐπιστρέφεται: ὅπου δ᾽ οὐκ οἶδεν οὐδὲ μεμελέτηκεν, ἐκεῖ ἀγωνιᾷ.","st":"2.13"},{"sp":"N","t":"τί δ᾽ ἔστι τοῦτο; οὐκ οἶδεν, τί ἐστιν ὄχλος οὐδὲ τί ὄχλου ἔπαινος: ἀλλὰ τὴν νήτην μὲν τύπτειν ἔμαθεν καὶ τὴν ὑπάτην, ἔπαινος δ᾽ ὁ παρὰ τῶν πολλῶν τί ἐστι καὶ τίνα δύναμιν ἔχει ἐν βίῳ οὔτε οἶδεν οὔτε μεμελέτηκεν αὐτό.","st":"2.13"},{"sp":"N","t":"ἀνάγκη λοιπὸν τρέμειν καὶ ὠχριᾶν. κιθαρῳδὸν μὲν οὖν οὐ δύναμαι εἰπεῖν μὴ εἶναι, ὅταν ἴδω τινὰ φοβούμενον, ἄλλο δέ τι δύναμαι εἰπεῖν καὶ οὐδὲ ἕν, ἀλλὰ πολλά.","st":"2.13"},{"sp":"N","t":"καὶ πρῶτον πάντων ξένον αὐτὸν καλῶ καὶ λέγω: οὗτος ὁ ἄνθρωπος οὐκ οἶδεν ποῦ τῆς γῆς ἐστιν, ἀλλ᾽ ἐκ τοσούτου χρόνου ἐπιδημῶν ἀγνοεῖ τοὺς νόμους τῆς πόλεως καὶ τὰ ἔθη καὶ τί ἔξεστι καὶ τί οὐκ ἔξεστιν. ἀλλ᾽ οὐδὲ νομικόν τινα παρέλαβεν πώποτε τὸν ἐροῦντα αὐτῷ καὶ ἐξηγησόμενον τὰ νόμιμα:","st":"2.13"},{"sp":"N","t":"ἀλλὰ διαθήκην μὲν οὐ γράφει μὴ εἰδὼς πῶς δεῖ γράφειν ἢ παραλαβὼν τὸν εἰδότα οὐδ᾽ ἐγγύην ἄλλως σφραγίζεται ἢ ἀσφάλειαν γράφει, ὀρέξει δὲ χρῆται δίχα νομικοῦ καὶ ἐκκλίσει καὶ ὁρμῇ καὶ ἐπιβολῇ καὶ προθέσει.","st":"2.13"},{"sp":"N","t":"πῶς δίχα νομικοῦ; οὐκ οἶδεν ὅτι θέλει τὰ μὴ διδόμενα καὶ οὐ θέλει τὰ ἀναγκαῖα καὶ οὐκ οἶδεν οὔτε τὰ ἴδια οὔτε τὰ ἀλλότρια. εἰ δέ γ᾽ ᾔδει, οὐδέποτ᾽ ἂν ἐνεποδίζετο, οὐδέποτ᾽ ἐκωλύετο, οὐκ ἂν ἠγωνία.","st":"2.13"},{"sp":"N","t":"πῶς γὰρ οὔ; φοβεῖταί τις οὖν ὑπὲρ τῶν μὴ κακῶν; — οὔ. — τί δ᾽; ὑπὲρ τῶν κακῶν μέν, ἐπ᾽ αὐτῷ δ᾽ ὄντων ὥστε μὴ συμβῆναι;","st":"2.13"},{"sp":"N","t":"— οὐδαμῶς. — εἰ οὖν τὰ μὲν ἀπροαίρετα οὔτ᾽ ἀγαθὰ οὔτε κακά, τὰ προαιρετικὰ δὲ πάντα ἐφ᾽ ἡμῖν καὶ οὔτ᾽ ἀφελέσθαι τις ἡμῶν αὐτὰ δύναται οὔτε περιποιῆσαι ἃ οὐ θέλομεν αὐτῶν, ποῦ ἔτι τόπος ἀγωνίας;","st":"2.13"},{"sp":"N","t":"ἀλλὰ περὶ τοῦ σωματίου ἀγωνιῶμεν, ὑπὲρ τοῦ κτησιδίου, περὶ τοῦ τί δόξει τῷ Καίσαρι, περὶ τῶν ἔσω δ᾽ οὐδενός. μή τι περὶ τοῦ μὴ ψεῦδος ὑπολαβεῖν; — οὔ: ἐπ᾽ ἐμοὶ γάρ ἐστιν. — μή τι τοῦ ὁρμῆσαι παρὰ φύσιν; — οὐδὲ περὶ τούτου. — ὅταν οὖν ἴδῃς τινὰ ὠχριῶντα,","st":"2.13"},{"sp":"N","t":"ὡς ὁ ἰατρὸς ἀπὸ τοῦ χρώματος λέγει ‘τούτου ὁ σπλὴν πέπονθε, τούτου δὲ τὸ ἧπαρ,’ οὕτως καὶ σὺ λέγε ‘τούτου ὄρεξις καὶ ἔκκλισις πέπονθεν, οὐκ εὐοδεῖ, φλεγμαίνει.’","st":"2.13"},{"sp":"N","t":"χρῶμα γὰρ οὐ μεταβάλλει οὐδὲν ἄλλο οὐδὲ τρόμον ποιεῖ οὐδὲ ψόφον τῶν ὀδόντων οὐδὲ μετοκλάζει καὶ ἐπ᾽ ἀμφοτέρους πόδας ἵζει.","st":"2.13"},{"sp":"N","t":"διὰ τοῦτο Ζήνων μὲν Ἀντιγόνῳ μέλλων ἐντυγχάνειν οὐκ ἠγωνία: ἃ γὰρ οὗτος ἐθαύμαζεν, τούτων οὐδενὸς εἶχεν ἐκεῖνος ἐξουσίαν, ὧν δ᾽ εἶχεν ἐκεῖνος οὐκ ἐπεστρέφετο οὗτος:","st":"2.13"},{"sp":"N","t":"Ἀντίγονος δὲ Ζήνωνι μέλλων ἐντυγχάνειν ἠγωνία, καὶ εἰκότως: ἤθελε γὰρ ἀρέσκειν αὐτῷ, τοῦτο δ᾽ ἔξω ἔκειτο: οὗτος δ᾽ ἐκείνῳ οὐκ ἤθελεν, οὐδὲ γὰρ ἄλλος τις τεχνίτης τῷ ἀτέχνῳ.","st":"2.13"},{"sp":"N","t":"ἐγώ σοι ἀρέσαι θέλω; ἀντὶ τίνος; οἶδας γὰρ τὰ μέτρα, καθ᾽ ἃ κρίνεται ἄνθρωπος ὑπ᾽ ἀνθρώπου; μεμέλετηκέ σοι γνῶναι, τί ἐστιν ἀγαθὸς ἄνθρωπος καὶ τί κακὸς καὶ πῶς ἑκάτερον γίγνεται; διὰ τί οὖν σὺ αὐτὸς ἀγαθὸς οὐκ εἶ;","st":"2.13"},{"sp":"N","t":"— πῶς, φησίν, οὐκ εἰμί; — ὅτι οὐδεὶς ἀγαθὸς πενθεῖ οὐδὲ στενάζει, οὐδεὶς οἰμώζει, οὐδεὶς ὠχριᾷ καὶ τρέμει οὐδὲ λέγει ‘πῶς μ᾽ ἀποδέξεται, πῶς μου ἀκούσει;’","st":"2.13"},{"sp":"N","t":"ἀνδράποδον, ὡς ἂν αὐτῷ δοκῇ. τί οὖν σοὶ μέλει περὶ τῶν ἀλλοτρίων; νῦν οὐκ ἐκείνου ἁμάρτημά ἐστι τὸ κακῶς ἀποδέξασθαι τὰ παρὰ σοῦ; — πῶς γὰρ οὔ; — δύναται δ᾽ ἄλλου μὲν εἶναι ἁμάρτημα, ἄλλου δὲ κακόν; — οὔ. — τί οὖν ἀγωνιᾷς ὑπὲρ τῶν ἀλλοτρίων;","st":"2.13"},{"sp":"N","t":"— ναί: ἀλλ᾽ ἀγωνιῶ, πῶς ἐγὼ αὐτῷ λαλήσω. — εἶτ᾽ οὐκ ἔξεστι γὰρ ὡς θέλεις αὐτῷ λαλῆσαι; — ἀλλὰ δέδοικα μὴ ἐκκρουσθῶ.","st":"2.13"},{"sp":"N","t":"— μή τι γράφειν μέλλων τὸ Δίωνος ὄνομα δέδοικας μὴ ἐκκρουσθῇς; — οὐδαμῶς. — τί τὸ αἴτιον; οὐχ ὅτι μεμελέτηκας γράφειν; — πῶς γὰρ οὔ; — τί δ᾽; ἀναγιγνώσκειν μέλλων οὐχ ὡσαύτως ἂν εἶχες; — ὡσαύτως. — τί τὸ αἴτιον; ὅτι πᾶσα τέχνη ἰσχυρόν τι ἔχει καὶ θαρραλέον ἐν τοῖς ἑαυτῆς.","st":"2.13"},{"sp":"N","t":"λαλεῖν οὖν οὐ μεμελέτηκας; καὶ τί ἄλλο ἐμελέτας ἐν τῇ σχολῇ; — συλλογισμοὺς καὶ μεταπίπτοντας. — ἐπὶ τί; οὐχ ὥστε ἐμπείρως διαλέγεσθαι; τὸ δ᾽ ἐμπείρως ἐστὶν οὐχὶ εὐκαίρως καὶ ἀσφαλῶς καὶ συνετῶς, ἔτι δ᾽ ἀπταίστως καὶ ἀπαραποδίστως, ἐπὶ πᾶσι δὲ τούτοις τεθαρρηκότως; — ναί.","st":"2.13"},{"sp":"N","t":"— ἱππεὺς οὖν ὢν εἰς πεδίον ἐληλυθὼς πρὸς πεζὸν ἀγωνιᾶς, ὅπου σὺ μεμελέτηκας, ἐκεῖνος δ᾽ ἀμελέτητός ἐστιν; — ναί: ἀλλὰ ἐξουσίαν ἔχει ἀποκτεῖναί με.","st":"2.13"},{"sp":"N","t":"— λέγε οὖν τὰ ἀληθῆ, δύστηνε, καὶ μὴ ἀλαζονεύου μηδὲ φιλόσοφος εἶναι ἀξίου μηδὲ ἀγνόει σου τοὺς κυρίους, ἀλλὰ μέχρις ἂν ἔχῃς ταύτην τὴν λαβὴν τὴν ἀπὸ τοῦ σώματος, ἀκολούθει παντὶ τῷ ἰσχυροτέρῳ.","st":"2.13"},{"sp":"N","t":"λέγειν δὲ Σωκράτης ἐμελέτα ὁ πρὸς τοὺς τυράννους οὕτως διαλεγόμενος, ὁ πρὸς τοὺς δικαστάς, ὁ ἐν τῷ δεσμωτηρίῳ. λέγειν Διογένης μεμελετήκει ὁ πρὸς Ἀλέξανδρον οὕτως λαλῶν, ὁ πρὸς Φίλιππον, ὁ πρὸς τοὺς πειρατάς, ὁ πρὸς τὸν ὠνησάμενον αὐτόν ... ἐκείνοις, οἷς μεμέλετηκεν, τοῖς θαρροῦσι: σὺ δ᾽ ἐπὶ τὰ σαυτοῦ βάδιζε καὶ ἐκείνων ἀποστῇς μηδέποτε: εἰς τὴν γωνίαν ἀπελθὼν κάθησο καὶ πλέκε συλλογισμοὺς καὶ ἄλλῳ πρότεινε:” οὐκ ἔστι δ᾽ ἐν σοὶ πόλεος ἡγεμὼν ἀνήρ.”","st":"2.13"},{"sp":"N","t":"πρὸς Νάσωνα. εἰσελθόντος τινὸς τῶν Ῥωμαικῶν μετὰ υἱοῦ καὶ ἐπακούοντος ἑνὸς ἀναγνώσματος Οὗτος, ἔφη, ὁ τρόπος ἐστὶ τῆς διδασκαλίας καὶ ἀπεσιώπησεν.","st":"2.13"},{"sp":"N","t":"ἀξιοῦντος δ᾽ ἐκείνου εὑρεῖν τὰ ἑξῆς Κόπον ἔχει, ἔφη, πᾶσα τέχνη τῷ ἰδιώτῃ καὶ ἀπείρῳ αὐτῆς, ὅταν παραδιδῶται.","st":"2.14"},{"sp":"N","t":"καὶ τὰ μὲν ἀπὸ τῶν τεχνῶν γινόμενα τήν τε χρείαν εὐθὺς ἐνδείκνυται πρὸς ὃ γέγονεν καὶ τὰ πλεῖστα αὐτῶν ἔχει τι καὶ ἀγωγὸν καὶ ἐπίχαρι.","st":"2.14"},{"sp":"N","t":"καὶ γὰρ σκυτεὺς πῶς μὲν μανθάνει τις παρεῖναι καὶ παρακολουθεῖν ἀτερπές, τὸ δ᾽ ὑπόδημα χρήσιμον καὶ ἰδεῖν ἄλλως οὐκ ἀηδές.","st":"2.14"},{"sp":"N","t":"καὶ τέκτονος ἡ μὲν μάθησις ἀνιαρὰ μάλιστα τῷ ἰδιώτῃ παρατυγχάνοντι, τὸ δ᾽ ἔργον ἐπιδείκνυσι τὴν χρείαν τῆς τέχνης.","st":"2.14"},{"sp":"N","t":"πολὺ δὲ μᾶλλον ἐπὶ μουσικῆς ὄψει αὐτό: ἂν γὰρ παρῇς τῷ διδασκομένῳ, φανεῖταί σοι πάντων ἀτερπέστατον τὸ μάθημα, τὰ μέντοι ἀπὸ τῆς μουσικῆς ἡδέα καὶ ἐπιτερπῆ τοῖς ἰδιώταις ἀκούειν.","st":"2.14"},{"sp":"N","t":"καὶ ἐνταῦθα τὸ μὲν ἔργον τοῦ φιλοσοφοῦντος τοιοῦτόν τι φανταζόμεθα, ὅτι δεῖ τὴν αὑτοῦ βούλησιν συναρμόσαι τοῖς γινομένοις, ὡς μήτε τι τῶν γινομένων ἀκόντων ἡμῶν γίνεσθαι μήτε τῶν μὴ γινομένων θελόντων ἡμῶν μὴ γίνεσθαι.","st":"2.14"},{"sp":"N","t":"ἐξ οὗ περίεστι τοῖς συστησαμένοις αὐτὸ ἐν ὀρέξει μὴ ἀποτυγχάνειν, ἐν ἐκκλίσει δὲ μὴ περιπίπτειν, ἀλύπως, ἀφόβως, ἀταράχως διεξάγειν καθ᾽ αὑτὸν μετὰ τῶν κοινωνῶν τηροῦντα τὰς σχέσεις τάς τε φυσικὰς καὶ ἐπιθέτους, τὸν υἱόν, τὸν πατέρα, τὸν ἀδελφόν, τὸν πολίτην, τὸν ἄνδρα, τὴν γυναῖκα, τὸν γείτονα, τὸν σύνοδον, τὸν ἄρχοντα, τὸν ἀρχόμενον.","st":"2.14"},{"sp":"N","t":"τὸ ἔργον τοῦ φιλοσοφοῦντος τοιοῦτόν τι φανταζόμεθα. λοιπὸν ἐφεξῆς τούτῳ ζητοῦμεν, πῶς ἔσται τοῦτο. ὁρῶμεν οὖν ὅτι ὁ τέκτων μαθών τινα γίνεται τέκτων,","st":"2.14"},{"sp":"N","t":"ὁ κυβερνήτης μαθών τινα γίνεται κυβερνήτης. μή ποτ᾽ οὖν καὶ ἐνθάδε οὐκ ἀπαρκεῖ τὸ βούλεσθαι καλὸν καὶ ἀγαθὸν γενέσθαι, χρεία δὲ καὶ μαθεῖν τινα; ζητοῦμεν οὖν τίνα ταῦτα.","st":"2.14"},{"sp":"N","t":"λέγουσιν οἱ φιλόσοφοι, ὅτι μαθεῖν δεῖ πρῶτον τοῦτο, ὅτι ἔστι θεὸς καὶ προνοεῖ τῶν ὅλων καὶ οὐκ ἔστι λαθεῖν αὐτὸν οὐ μόνον ποιοῦντα, ἀλλ᾽ οὐδὲ διανοούμενον ἢ ἐνθυμούμενον: εἶτα ποῖοί τινες εἰσίν.","st":"2.14"},{"sp":"N","t":"οἷοι γὰρ ἂν ἐκεῖνοι εὑρεθῶσιν, τὸν ἐκείνοις ἀρέσοντα καὶ πεισθησόμενον ἀνάγκη πειρᾶσθαι κατὰ δύναμιν ἐξομοιοῦσθαι ἐκείνοις:","st":"2.14"},{"sp":"N","t":"εἰ πιστόν ἐστι τὸ θεῖον, καὶ τοῦτον εἶναι πιστόν: εἰ ἐλεύθερον, καὶ τοῦτον ἐλεύθερον: εἰ εὐεργετικόν, καὶ τοῦτον εὐεργετικόν: εἰ μεγαλόφρον, καὶ τοῦτον μεγαλόφρονα: ὡς θεοῦ τοίνυν ζηλωτὴν τὰ ἑξῆς πάντα καὶ ποιεῖν καὶ λέγειν. πόθεν οὖν ἄρξασθαι δεῖ;","st":"2.14"},{"sp":"N","t":"— ἂν συγκαθῇς, ἐρῶ σοι ὅτι πρῶτον δεῖ σε τοῖς ὀνόμασι παρακολουθεῖν. — ὥστ᾽ ἐγὼ νῦν οὐ παρακολουθῶ τοῖς ὀνόμασιν;","st":"2.14"},{"sp":"N","t":"— οὐ παρακολουθεῖς. — πῶς οὖν χρῶμαι αὐτοῖς; — οὕτως ὡς οἱ ἀγράμματοι ταῖς ἐγγραμμάτοις φωναῖς, ὡς τὰ κτήνη ταῖς φαντασίαις: ἄλλο γάρ ἐστι χρῆσις, ἄλλο παρακολούθησις.","st":"2.14"},{"sp":"N","t":"εἰ δ᾽ οἴει παρακολουθεῖν, φέρε ὃ θέλεις ὄνομα καὶ βασανίσωμεν αὑτούς, εἰ παρακολουθοῦμεν.","st":"2.14"},{"sp":"N","t":"— ἀλλ᾽ ἀνιαρὸν τὸ ἐξελέγχεσθαι πρεσβύτερον ἄνθρωπον ἤδη κἂν οὕτως τύχῃ τὰς τρεῖς στρατείας ἐστρατευμένον.","st":"2.14"},{"sp":"N","t":"— οἶδα κἀγώ. νῦν γὰρ σὺ ἐλήλυθας πρὸς ἐμὲ ὡς μηδενὸς δεόμενος. τίνος δ᾽ ἂν καὶ φαντασθείης ὡς ἐνδέοντος; πλουτεῖς, τέκνα ἔχεις τυχὸν καὶ γυναῖκα καὶ οἰκέτας πολλούς, ὁ Καῖσάρ σε οἶδεν, ἐν Ῥώμῃ πολλοὺς φίλους κέκτησαι, τὰ καθήκοντα ἀποδίδως, οἶδας τὸν εὖ ποιοῦντα ἀντευποιῆσαι καὶ τὸν κακῶς ποιοῦντα κακῶς ποιῆσαι.","st":"2.14"},{"sp":"N","t":"τί σοι λείπει; ἂν οὖν σοι δείξω, ὅτι τὰ ἀναγκαιότατα καὶ μέγιστα πρὸς εὐδαιμονίαν καὶ ὅτι μέχρι δεῦρο πάντων μᾶλλον ἢ τῶν προσηκόντων ἐπιμεμέλησαι, καὶ τὸν κολοφῶνα ἐπιθῶ: οὔτε τί θεός ἐστιν οἶδας οὔτε τί ἄνθρωπος οὔτε τί ἀγαθὸν οὔτε τί κακόν,","st":"2.14"},{"sp":"N","t":"καὶ τὸ μὲν τῶν ἄλλων ἴσως ἀνεκτόν, ὅτι δ᾽ αὐτὸς αὑτὸν ἀγνοεῖς, πῶς δύνασαι ἀνασχέσθαι μου καὶ ὑποσχεῖν τὸν ἔλεγχον καὶ παραμεῖναι;","st":"2.14"},{"sp":"N","t":"οὐδαμῶς, ἀλλ᾽ εὐθὺς ἀπαλλάσσῃ χαλεπῶς ἔχων. καίτοι τί σοι ἐγὼ κακὸν πεποίηκα; εἰ μὴ καὶ τὸ ἔσοπτρον τῷ αἰσχρῷ, ὅτι δεικνύει αὐτὸν αὐτῷ οἷός ἐστιν: εἰ μὴ καὶ ὁ ἰατρὸς τὸν νοσοῦντα ὅταν αὐτὸν ὑβρίζει, ὅταν εἴπῃ αὐτῷ ‘ἄνθρωπε, δοκεῖς μηδὲν ἔχειν, πυρέσσεις δέ: ἀσίτησον σήμερον, ὕδωρ πίε:’ καὶ οὐδεὶς λέγει ‘ὦ δεινῆς ὕβρεως.’","st":"2.14"},{"sp":"N","t":"ἐὰν δέ τινι εἴπῃς ‘αἱ ὀρέξεις σου φλεγμαίνουσιν, αἱ ἐκκλίσεις ταπειναί εἰσιν, αἱ ἐπιβολαὶ ἀνομολογούμεναι, αἱ ὁρμαὶ ἀσύμφωνοι τῇ φύσει, αἱ ὑπολήψεις εἰκαῖαι καὶ ἐψευσμέναι,’ εὐθὺς ἐξελθὼν λέγει ‘ὕβρισέν με.’","st":"2.14"},{"sp":"N","t":"τοιαῦτά ἐστι τὰ ἡμέτερα ὡς ἐν πανηγύρει. τὰ μὲν κτήνη παραθησόμενα ἄγεται καὶ οἱ βόες, οἱ δὲ πολλοὶ τῶν ἀνθρώπων οἱ μὲν ὠνησόμενοι οἱ δὲ πωλήσοντες: ὀλίγοι δέ τινές εἰσιν οἱ κατὰ θέαν ἐρχόμενοι τῆς πανηγύρεως, πῶς τοῦτο γίνεται καὶ διὰ τί καὶ τίνες οἱ τιθέντες τὴν πανήγυριν καὶ ἐπὶ τίνι.","st":"2.14"},{"sp":"N","t":"οὕτως καὶ ἐνθάδ᾽ ἐν τῇ πανηγύρει ταύτῃ: οἱ μέν τινες ὡς κτήνη οὐδὲν πλέον πολυπραγμονοῦσι τοῦ χόρτου: ὅσοι γὰρ περὶ κτῆσιν καὶ ἀγροὺς καὶ οἰκέτας καὶ ἀρχάς τινας ἀναστρέφεσθε, ταῦτα οὐδὲν ἄλλο ἢ χόρτος ἐστίν:","st":"2.14"},{"sp":"N","t":"ὀλίγοι δ᾽ εἰσὶν οἱ πανηγυρίζοντες ἄνθρωποι φιλοθεάμονες. τί ποτ᾽ οὖν ἐστιν ὁ κόσμος, τίς αὐτὸν διοικεῖ. οὐδείς;","st":"2.14"},{"sp":"N","t":"καὶ πῶς οἷόν τε πόλιν μὲν ἢ οἶκον μὴ δύνασθαι διαμένειν μηδ᾽ ὀλιγοστὸν χρόνον δίχα τοῦ διοικοῦντος καὶ ἐπιμελομένου, τὸ δ᾽ οὕτως μέγα καὶ καλὸν κατασκεύασμα εἰκῇ καὶ ὡς ἔτυχεν οὕτως εὐτάκτως οἰκονομεῖσθαι;","st":"2.14"},{"sp":"N","t":"ἔστιν οὖν ὁ διοικῶν. ποῖός τις καὶ πῶς ὁ διοικῶν; ἡμεῖς δὲ τίνες ὄντες ὑπ᾽ αὐτοῦ γεγόναμεν καὶ πρὸς τί ἔργον; ἆρά γ᾽ ἔχομέν τινα ἐπιπλοκὴν πρὸς αὐτὸν καὶ σχέσιν ἢ οὐδεμίαν;","st":"2.14"},{"sp":"N","t":"ταῦτ᾽ ἔστιν ἃ πάσχουσιν οὗτοι οἱ ὀλίγοι: καὶ λοιπὸν τούτῳ μόνῳ σχολάζουσι τῷ τὴν πανήγυριν ἱστορήσαντας ἀπελθεῖν.","st":"2.14"},{"sp":"N","t":"τί οὖν; καταγελῶνται ὑπὸ τῶν πολλῶν: καὶ γὰρ ἐκεῖ οἱ θεαταὶ ὑπὸ τῶν ἐμπόρων: καὶ εἰ τὰ κτήνη συναίσθησίν τινα εἶχεν, κατεγέλα τῶν ἄλλο τι τεθαυμακότων ἢ τὸν χόρτον. πρὸς τοὺς σκληρῶς τισιν ὧν ἔκριναν ἐμμένοντας. ὅταν ἀκούσωσί τινες τούτων τῶν λόγων, ὅτι βέβαιον εἶναι δεῖ καὶ ἡ μὲν προαίρεσις ἐλεύθερον φύσει καὶ ἀνανάγκαστον, τὰ δ᾽ ἄλλα κωλυτά, ἀναγκαστά, δοῦλα, ἀλλότρια, φαντάζονται ὅτι δεῖ παντὶ τῷ κριθέντι ὑπ᾽ αὐτῶν ἀπαραβάτως ἐμμένειν.","st":"2.14"},{"sp":"N","t":"ἀλλὰ πρῶτον ὑγιὲς εἶναι δεῖ τὸ κεκριμένον. θέλω γὰρ εἶναι τόνους ἐν σώματι, ἀλλ᾽ ὡς ὑγιαίνοντι, ὡς ἀθλοῦντι:","st":"2.15"},{"sp":"N","t":"ἂν δέ μοι φρενιτικοῦ τόνους ἔχων ἐνδεικνύῃς καὶ ἀλαζονεύῃ ἐπ᾽ αὐτοῖς, ἐρῶ σοι ὅτι ‘ἄνθρωπε, ζήτει τὸν θεραπεύσοντα. τοῦτο οὐκ εἰσὶ τόνοι, ἀλλ᾽ ἀτονία.’","st":"2.15"},{"sp":"N","t":"ἕτερον τρόπον τοιοῦτόν τι καὶ ἐπὶ τῆς ψυχῆς πάσχουσιν οἱ παρακούοντες τῶν λόγων τούτων. οἷον καὶ ἐμός τις ἑταῖρος ἐξ οὐδεμιᾶς αἰτίας ἔκρινεν ἀποκαρτερεῖν.","st":"2.15"},{"sp":"N","t":"ἔγνων ἐγὼ ἤδη τρίτην ἡμέραν ἔχοντος αὐτοῦ τῆς ἀποχῆς καὶ ἐλθὼν ἐπυνθανόμην τί ἐγένετο.","st":"2.15"},{"sp":"N","t":"— κέκρικα, φησίν. — ἀλλ᾽ ὅμως τί σε ἦν τὸ ἀναπεῖσαν; εἰ γὰρ ὀρθῶς ἔκρινας, ἰδοὺ παρακαθήμεθά σοι καὶ συνεργοῦμεν, ἵν᾽ ἐξέλθῃς: εἰ δ᾽ ἀλόγως ἔκρινας, μετάθου.","st":"2.15"},{"sp":"N","t":"— τοῖς κριθεῖσιν ἐμμένειν δεῖ. — τί ποιεῖς, ἄνθρωπε; οὐ πᾶσιν, ἀλλὰ τοῖς ὀρθῶς. ἐπεὶ παθὼν ἄρτι ὅτι νύξ ἐστιν, ἄν σοι δοκῇ, μὴ μετατίθεσο, ἀλλ᾽ ἔμμενε καὶ λέγε ὅτι τοῖς κριθεῖσιν ἐμμένειν δεῖ.","st":"2.15"},{"sp":"N","t":"τί ποιεῖς, ἄνθρωπε; οὐ πᾶσιν. οὐ θέλεις τὴν ἀρχὴν στῆσαι καὶ τὸν θεμέλιον, τὸ κρίμα σκέψασθαι πότερον ὑγιὲς ἢ οὐχ ὑγιές, καὶ οὕτως λοιπὸν ἐποικοδομεῖν αὐτῷ τὴν εὐτονίαν, τὴν ἀσφάλειαν;","st":"2.15"},{"sp":"N","t":"ἂν δὲ σαπρὸν ὑποστήσῃ καὶ καταπῖπτον, οὐκ † οἰκοδόμημά τι ὄν, ὅσῳ δ᾽ ἂν πλείονα καὶ ἰσχυρότερα ἐπιθῇς, τοσούτῳ θᾶττον θᾶττον κατενεχθήσεται.","st":"2.15"},{"sp":"N","t":"ἄνευ πάσης αἰτίας ἐξάγεις ἡμῖν ἄνθρωπον ἐκ τοῦ ζῆν φίλον καὶ συνήθη, τῆς αὐτῆς πόλεως πολίτην καὶ τῆς μεγάλης καὶ τῆς μικρᾶς:","st":"2.15"},{"sp":"N","t":"εἶτα φόνον ἐργαζόμενος καὶ ἀπολλύων ἄνθρωπον μηδὲν ἠδικηκότα λέγεις ὅτι τοῖς κριθεῖσιν ἐμμένειν δεῖ.","st":"2.15"},{"sp":"N","t":"εἰ δ᾽ ἐπῆλθέν σοί πώς ποτ᾽ ἐμὲ ἀποκτεῖναι, ἔδει σε ἐμμένειν τοῖς κριθεῖσιν;","st":"2.15"},{"sp":"N","t":"ἐκεῖνος μὲν οὖν μόγις μετεπείσθη. τῶν δὲ νῦν τινας οὐκ ἔστι μεταθεῖναι. ὥστε μοι δοκῶ ὃ πρότερον ἠγνόουν νῦν εἰδέναι, τί ἐστι τὸ ἐν τῇ συνηθείᾳ λεγόμενον: μωρὸν οὔτε πεῖσαι οὔτε ῥῆξαι ἔστιν.","st":"2.15"},{"sp":"N","t":"μή μοι γένοιτο φίλον ἔχειν σοφὸν μωρόν. δυσμεταχειριστότερον οὐδέν ἐστιν. ‘κέκρικα.’ καὶ γὰρ οἱ μαινόμενοι: ἀλλ᾽ ὅσῳ βεβαιότερον κρίνουσι τὰ οὐκ ὄντα, τοσούτῳ πλείονος ἐλλεβόρου δέονται.","st":"2.15"},{"sp":"N","t":"οὐ θέλεις τὰ τοῦ νοσοῦντος ποιεῖν καὶ τὸν ἰατρὸν παρακαλεῖν; ‘νοσῶ, κύριε: βοήθησόν μοι. τί με δεῖ ποιεῖν σκέψαι: ἐμόν ἐστι πείθεσθαί σοι.’","st":"2.15"},{"sp":"N","t":"οὕτως καὶ ἐνταῦθ᾽. ‘ἃ δεῖ με ποιεῖν οὐκ οἶδα, ἐλήλυθα δὲ μαθησόμενος.’ οὔ, ἀλλὰ ‘περὶ τῶν ἄλλων μοι λέγε.","st":"2.15"},{"sp":"N","t":"τοῦτο δὲ κέκρικα.’ περὶ ποίων ἄλλων; τί γάρ ἐστι μεῖζον ἢ προὐργιαίτερον τοῦ πεισθῆναί σε, ὅτι οὐκ ἀρκεῖ τὸ κεκρικέναι καὶ τὸ μὴ μεταθέσθαι;","st":"2.15"},{"sp":"N","t":"οὗτοι οἱ μανικοὶ τόνοι, οὐχ ὑγιεινοί. ‘ἀποθανεῖν θέλω, ἄν με τοῦτο ἀναγκάσῃς.’ διὰ τί, ἄνθρωπε; τί ἐγένετο; ‘κέκρικα.’ ἐσώθην, ὅτι οὐ κέκρικας ἐμὲ ἀποκτεῖναι.","st":"2.15"},{"sp":"N","t":"‘ἀργύριον οὐ λαμβάνω.’ διὰ τί; ‘κέκρικα.’ ἴσθι ὅτι ᾧ τόνῳ νῦν χρῇ πρὸς τὸ μὴ λαμβάνειν, οὐδὲν κωλύει σε ἀλόγως ποτὲ ῥέψαι πρὸς τὸ λαμβάνειν καὶ πάλιν λέγειν ὅτι","st":"2.15"},{"sp":"N","t":"‘κέκρικα,’ ὥσπερ ἐν νοσοῦντι καὶ ῥευματιζομένῳ σώματι ποτὲ μὲν ἐπὶ ταῦτα ποτὲ δ᾽ ἐπ᾽ ἐκεῖνα ῥέπει τὸ ῥεῦμα. οὕτως καὶ ἀσθενὴς ψυχή, ὅπου μὲν κλίνει, ἄδηλον ἔχει: ὅταν δὲ καὶ τόνος προσῇ τῷ κλίματι τούτῳ καὶ τῇ φορᾷ, τότε γίνεται τὸ κακὸν ἀβοήθητον καὶ ἀθεράπευτον. ὅτι οὐ μελετῶμεν χρῆσθαι τοῖς περὶ ἀγαθῶν καὶ κακῶν δόγμασιν. ποῦ τὸ ἀγαθόν; — ἐν προαιρέσει. — ποῦ τὸ κακόν; — ἐν προαιρέσει. — ποῦ τὸ οὐδέτερον; — ἐν τοῖς ἀπροαιρέτοις.","st":"2.15"},{"sp":"N","t":"— τί οὖν; μέμνηταί τις ἡμῶν ἔξω τούτων τῶν λόγων; μελετᾷ τις αὐτὸς ἐφ᾽ αὑτοῦ τοῦτον τὸν τρόπον ἀποκρίνεσθαι τοῖς πράγμασιν ὡς ἐπὶ τῶν ἐρωτημάτων: ‘ἆρά γε ἡμέρα ἐστίν;’ ‘ναί.’ ‘τί δέ; νύξ ἐστιν;’ ‘οὔ.’ ‘τί δ᾽; ἄρτιοί εἰσιν οἱ ἀστέρες;’ ‘οὐκ ἔχω λέγειν.’","st":"2.16"},{"sp":"N","t":"ὅταν σοι προφαίνηται ἀργύριον, μεμελέτηκας ἀποκρίνεσθαι τὴν δέουσαν ἀπόκρισιν, ὅτι ‘οὐκ ἀγαθόν;’ ἤσκηκας ἐν ταύταις ταῖς ἀποκρίσεσιν ἢ πρὸς μόνα: τὰ σοφίσματα;","st":"2.16"},{"sp":"N","t":"τί οὖν θαυμάζεις, εἰ, ὅπου μὲν μεμελέτηκας, ἐκεῖ κρείττων γένῃ σεαυτοῦ, ὅπου δ᾽ ἀμελετήτως ἔχεις, ἐκεῖ δ᾽ ὁ αὐτὸς διαμένεις;","st":"2.16"},{"sp":"N","t":"ἐπεὶ διὰ τί ὁ ῥήτωρ εἰδὼς ὅτι γέγραφε καλῶς, ὅτι ἀνείληφε τὰ γεγραμμένα, φωνὴν εἰσφέρων ἡδεῖαν ὅμως ἔτι ἀγωνιᾷ; ὅτι οὐκ ἀρκεῖται τῷ μελετῆσαι.","st":"2.16"},{"sp":"N","t":"τί οὖν θέλεις; ἐπαινεθῆναι ὑπὸ τῶν παρόντων. πρὸς μὲν οὖν τὸ δύνασθαι μελετᾶν ἤσκηται, πρὸς ἔπαινον δὲ καὶ ψόγον οὐκ ἤσκηται.","st":"2.16"},{"sp":"N","t":"πότε γὰρ ἤκουσεν παρά τινος, τί ἐστιν ἔπαινος, τί ἐστι ψόγος, τίς ἑκατέρου φύσις; τοὺς ποίους τῶν ἐπαίνων διωκτέον ἢ τοὺς ποίους τῶν ψόγων φευκτέον; πότε δ᾽ ἐμελέτησεν ταύτην τὴν μελέτην ἀκόλουθον τούτοις τοῖς λόγοις;","st":"2.16"},{"sp":"N","t":"τί οὖν ἔτι θαυμάζεις, εἰ, ὅπου μὲν ἔμαθεν, ἐκεῖ διαφέρει τῶν ἄλλων, ὅπου δ᾽ οὐ μεμελέτηκεν, ἐκεῖ τοῖς πολλοῖς ὁ αὐτός ἐστιν;","st":"2.16"},{"sp":"N","t":"ὡς ὁ κιθαρῳδὸς οἶδεν κιθαρίζειν, ᾁδει καλῶς, στατὸν ἔχει καλὸν καὶ ὅμως εἰσερχόμενος τρέμει: ταῦτα γὰρ οἶδεν, ὄχλος δὲ τί ἐστιν οὐκ οἶδεν οὐδ᾽ ὄχλου βοὴ οὐδὲ κατάγελως.","st":"2.16"},{"sp":"N","t":"ἀλλ᾽ οὐδ᾽ αὐτὸ τὸ ἀγωνιᾶν τί ἐστιν οἶδεν, πότερον ἡμέτερον ἔργον ἐστὶν ἢ ἀλλότριον, ἔστιν αὐτὸ παῦσαι ἢ οὐκ ἔστιν. διὰ τοῦτο ἐὰν μὲν ἐπαινεθῇ, φυσηθεὶς ἐξῆλθεν: ἐὰν δὲ καταγελασθῇ, τὸ φυσημάτιον ἐκεῖνο ἐκεντήθη καὶ προσεκάθισεν.","st":"2.16"},{"sp":"N","t":"τοιοῦτόν τι καὶ ἡμεῖς πάσχομεν. τίνα θαυμάζομεν; τὰ ἐκτός. περὶ τίνα σπουδάζομεν; περὶ τὰ ἐκτός. εἶτ᾽ ἀποροῦμεν, πῶς φοβούμεθα ἢ πῶς ἀγωνιῶμεν;","st":"2.16"},{"sp":"N","t":"τί οὖν ἐνδέχεται, ὅταν τὰ ἐπιφερόμενα κακὰ ἡγώμεθα; οὐ δυνάμεθα μὴ φοβεῖσθαι, οὐ δυνάμεθα μὴ ἀγωνιᾶν.","st":"2.16"},{"sp":"N","t":"εἶτα λέγομεν ‘κύριε ὁ θεός, πῶς μὴ ἀγωνιῶ;’ μωρέ, χεῖρας οὐκ ἔχεις; οὐκ ἐποίησέν σοι αὐτὰς ὁ θεός; εὔχου νῦν καθήμενος, ὅπως αἱ μύξαι σου μὴ ῥέωσιν: ἀπόμυξαι μᾶλλον καὶ μὴ ἐγκάλει.","st":"2.16"},{"sp":"N","t":"τί οὖν; ἐνταῦθά σοι οὐδὲν δέδωκεν; οὐ δέδωκέ σοι καρτερίαν, οὐ δέδωκέ σοι μεγαλοψυχίαν, οὐ δέδωκεν ἀνδρείαν; τηλικαύτας ἔχων χεῖρας ἔτι ζητεῖς τὸν ἀπομύξοντα;","st":"2.16"},{"sp":"N","t":"ἀλλ᾽ οὐδὲ μελετῶμεν ταῦτα οὐδ᾽ ἐπιστρεφόμεθα. ἐπεὶ δότε μοι ἕνα, ᾧ μέλει πῶς τι ποιήσῃ, ὃς ἐπιστρέφεται οὐ τοῦ τυχεῖν τινος, ἀλλὰ τῆς ἐνεργείας τῆς αὑτοῦ: τίς περιπατῶν τῆς ἐνεργείας τῆς αὑτοῦ ἐπιστρέφεται; τίς βουλευόμενος αὐτῆς τῆς βουλῆς, οὐχὶ δὲ τοῦ τυχεῖν ἐκείνου περὶ οὗ βουλεύεται;","st":"2.16"},{"sp":"N","t":"κἂν μὲν τύχῃ, ἐπῆρται καὶ λέγει ‘πῶς γὰρ ἡμεῖς καλῶς ἐβουλευσάμεθα; οὐκ ἔλεγόν σοι, ἀδελφέ, ὅτι ἀδύνατόν ἐστιν ἡμῶν τι σκεψαμένων μὴ οὕτως ἐκβῆναι;’ ἂν δ᾽ ἑτέρως χωρήσῃ, τεταπείνωται τάλας, οὐχ εὑρίσκει οὐδὲ τί εἴπῃ περὶ τῶν γεγονότων. τίς ἡμῶν τούτου ἕνεκα μάντιν παρέλαβεν;","st":"2.16"},{"sp":"N","t":"τίς ἡμῶν † οὐκ ἐνεκοιμήθη † ὑπὲρ ἐνεργείας; τίς; ἕνα μοι δότε, ἵνα ἴδω τοῦτον, ὃν ἐκ πολλοῦ χρόνου ζητῶ, τὸν ταῖς ἀληθείαις εὐγενῆ καὶ εὐφυᾶ: εἴτε νέον εἴτε πρεσβύτερον, δότε.","st":"2.16"},{"sp":"N","t":"τί οὖν ἔτι θαυμάζομεν εἰ περὶ μὲν τὰς ὕλας τετρίμμεθα, ἐν δὲ ταῖς ἐνεργείαις ταπεινοί, ἀσχήμονες, οὐδενὸς ἄξιοι, δειλοί, ἀταλαίπωροι, ὅλοι ἀτυχήματα; οὐ γὰρ μεμέληκεν ἡμῖν οὐδὲ μελετῶμεν.","st":"2.16"},{"sp":"N","t":"εἰ δὲ μὴ τὸν θάνατον ἢ τὴν φυγὴν ἐφοβούμεθα, ἀλλὰ τὸν φόβον, ἐμελετῶμεν ἂν ἐκείνοις μὴ περιπίπτειν ἃ φαίνεται ἡμῖν κακά.","st":"2.16"},{"sp":"N","t":"νῦν δ᾽ ἐν μὲν τῇ σχολῇ γοργοὶ καὶ κατάγλωσσοι, κἂν ζητημάτιον ἐμπέσῃ περί τινος τούτων, ἱκανοὶ τὰ ἑξῆς ἐπελθεῖν: ἕλκυσον δ᾽ εἰς χρῆσιν καὶ εὑρήσεις τάλανας ναυαγούς. προσπεσέτω φαντασία ταρακτικὴ καὶ γνώσῃ, τί ἐμελετῶμεν καὶ πρὸς τί ἐγυμναζόμεθα.","st":"2.16"},{"sp":"N","t":"λοιπὸν ὑπὸ τῆς ἀμελετησίας προσεπισωρεύομεν ἀεί τινα καὶ προσπλάσσομεν μείζονα τῶν καθεστώτων. εὐθὺς ἐγώ,","st":"2.16"},{"sp":"N","t":"ὅταν πλέω, κατακύψας εἰς τὸν βυθὸν ἢ τὸ πέλαγος περιβλεψάμενος καὶ μὴ ἰδὼν γῆν ἐξίσταμαι καὶ φανταζόμενος, ὅτι ὅλον με δεῖ τὸ πέλαγος τοῦτο ἐκπιεῖν, ἂν ναυαγήσω, οὐκ ἐπέρχεταί μοι, ὅτι μοι τρεῖς ξέσται ἀρκοῦσιν. τί οὖν με ταράσσει; τὸ πέλαγος; οὔ, ἀλλὰ τὸ δόγμα.","st":"2.16"},{"sp":"N","t":"πάλιν ὅταν σεισμὸς γένηται, φαντάζομαι ὅτι ἡ πόλις ἐπιπίπτειν μοι μέλλει: οὐ γὰρ ἀρκεῖ μικρὸν λιθάριον, ἵν᾽ ἔξω μου τὸν ἐγκέφαλον βάλῃ;","st":"2.16"},{"sp":"N","t":"τίνα οὖν ἐστι τὰ βαροῦντα καὶ ἐξιστάντα ἡμᾶς; τίνα γὰρ ἄλλα ἢ τὰ δόγματα; τὸν γὰρ ἐξιόντα καὶ ἀπαλλαττόμενον τῶν συνήθων καὶ ἑταίρων καὶ τόπων καὶ συναναστροφῆς τί ἐστι τὸ βαροῦν ἄλλο ἢ δόγμα;","st":"2.16"},{"sp":"N","t":"τὰ γοῦν παιδία εὐθὺς ὅταν κλαύσῃ μικρὰ τῆς τιτθῆς ἀπελθούσης, πλακούντιον λαβόντα ἐπιλέλησται.","st":"2.16"},{"sp":"N","t":"θέλεις οὖν καὶ ἡμεῖς τοῖς παιδίοις ὁμοιῶμεν; οὔ, νὴ τὸν Δία. οὐ γὰρ ὑπὸ πλακουντίου τοῦτο πάσχειν ἀξιῶ, ἀλλ᾽ ὑπὸ δογμάτων ὀρθῶν.","st":"2.16"},{"sp":"N","t":"τίνα δ᾽ ἐστὶ ταῦτα; ἃ δεῖ τὸν ἄνθρωπον ὅλην τὴν ἡμέραν μελετῶντα μηδενὶ προσπάσχειν τῶν ἀλλοτρίων, μηθ᾽ ἑταίρῳ μήτε τόπῳ μήτε γυμνασίοις, ἀλλὰ μηδὲ τῷ σώματι τῷ αὑτοῦ, μεμνῆσθαι δὲ τοῦ νόμου καὶ τοῦτον πρὸ ὀφθαλμῶν ἔχειν. τίς δ᾽ ὁ νόμος ὁ θεῖος;","st":"2.16"},{"sp":"N","t":"τὰ ἴδια τηρεῖν, τῶν ἀλλοτρίων μὴ ἀντιποιεῖσθαι, ἀλλὰ διδομένοις μὲν χρῆσθαι, μὴ διδόμενα δὲ μὴ ποθεῖν, ἀφαιρουμένου δέ τινος ἀποδιδόναι εὐλύτως καὶ αὐτόθεν, χάριν εἰδότα οὗ ἐχρήσατο χρόνου, εἰ θέλεις μὴ κλάειν τὴν τιτθὴν καὶ μάμμην.","st":"2.16"},{"sp":"N","t":"τί γὰρ διαφέρει, τίνος ἥττων ἐστὶ καὶ ἐκ τίνος κρέμαται; τί κρείττων εἶ τοῦ διὰ κοράσιον κλάοντος, εἰ διὰ γυμνασίδιον καὶ στωίδια καὶ νεανισκάρια καὶ τοιαύτην διατριβὴν πενθεῖς;","st":"2.16"},{"sp":"N","t":"ἄλλος ἐλθὼν ὅτι οὐκέτι τὸ τῆς Δίρκης ὕδωρ πίνειν μέλλει. τὸ γὰρ Μάρκιον χεῖρόν ἐστι τοῦ τῆς Δίρκης; ‘ἀλλ᾽ ἐκεῖνό μοι σύνηθες ἦν.’","st":"2.16"},{"sp":"N","t":"καὶ τοῦτο πάλιν ἔσται σοι σύνηθες. εἶτ᾽ ἂν μὲν τοιούτῳ προσπάθῃς, καὶ τοῦτο πάλιν κλαῖε καὶ ζήτει στίχον ὅμοιον τῷ Εὐριπίδου ποιῆσαι θερμάς τε τὰς Νέρωνος Μάρκιόν θ᾽ ὕδωρ. ἴδε πῶς τραγῳδία γίνεται, ὅταν εἰς μωροὺς ἀνθρώπους πράγματα τὰ τυγχάνοντ᾽ ἐμπέσῃ.","st":"2.16"},{"sp":"N","t":"‘πότε οὖν Ἀθήνας πάλιν ὄψομαι καὶ τὴν ἀκρόπολιν;’ τάλας, οὐκ ἀρκεῖ σοι ἃ βλέπεις καθ᾽ ἡμέραν; κρεῖττόν τι ἔχεις ἢ μεῖζον ἰδεῖν τοῦ ἡλίου, τῆς σελήνης, τῶν ἄστρων, τῆς γῆς ὅλης, τῆς θαλάσσης;","st":"2.16"},{"sp":"N","t":"εἰ δὲ δὴ παρακολουθεῖς τῷ διοικοῦντι τὰ ὅλα κἀκεῖνον ἐν σαυτῷ περιφέρεις, ἔτι ποθεῖς λιθάρια καὶ πέτραν κομψήν; ὅταν οὖν μέλλῃς ἀπολιπεῖν αὐτὸν τὸν ἥλιον καὶ τὴν σελήνην, τί ποιήσεις;","st":"2.16"},{"sp":"N","t":"κλαύσεις καθήμενος ὡς τὰ παιδία; τί οὖν ἐν τῇ σχολῇ ἐποίεις, τί ἤκουες, τί ἐμάνθανες; τί σαυτὸν φιλόσοφον ἐπέγραφες ἐξὸν τὰ ὄντα ἐπιγράφειν; ὅτι ‘εἰσαγωγὰς ἔπραξάς τινας καὶ Χρυσίππεια ἀνέγνων, φιλοσόφου δ᾽ οὐδὲ θύραν παρῆλθον.","st":"2.16"},{"sp":"N","t":"ποῦ γάρ μοι μέτεστι τούτου τοῦ πράγματος, οὗ Σωκράτει μετῆν τῷ οὕτως ἀποθανόντι, οὕτως ζήσαντι; οὗ Διογένει μετῆν;’ ἐπινοεῖς τούτων τινὰ κλάοντα ἢ ἀγανακτοῦντα,","st":"2.16"},{"sp":"N","t":"ὅτι τὸν δεῖνα οὐ μέλλει βλέπειν οὐδὲ τὴν δεῖνα οὐδ᾽ ἐν Ἀθήναις ἔσεσθαι ἢ ἐν Κορίνθῳ, ἀλλ᾽, ἂν οὕτως τύχῃ, ἐν Σούσοις ἢ ἐν Ἐκβατάνοις;","st":"2.16"},{"sp":"N","t":"ᾧ γὰρ ἔξεστιν ἐξελθεῖν, ὅταν θέλῃ, τοῦ συμποσίου καὶ μηκέτι παίζειν, ἔτι οὗτος ἀνιᾶται μένων; οὐχὶ δ᾽ ὡς παιδιᾷ παραμένει, μέχρις ἂν ψυχαγωγῆται;","st":"2.16"},{"sp":"N","t":"ταχύ γ᾽ ἂν ὁ τοιοῦτος ὑπομείναι φυγήν τινα φυγεῖν εἰς ἅπαντα ἢ τὴν ἐπὶ θανάτῳ κατακριθείς.","st":"2.16"},{"sp":"N","t":"οὐ θέλεις ἤδη ὡς τὰ παιδία ἀπογαλακτισθῆναι καὶ ἅπτεσθαι τροφῆς στερεωτέρας μηδὲ κλάειν μάμμας καὶ τιτθάς, γραῶν ἀποκλαύματα;","st":"2.16"},{"sp":"N","t":"‘ἀλλ᾽ ἐκείνας ἀπαλλασσόμενος ἀνιάσω.’ σὺ αὐτὰς ἀνιάσεις; οὐδαμῶς, ἀλλ᾽ ὅπερ καὶ σέ, τὸ δόγμα. τί οὖν ἔχεις ποιῆσαι; ἔξελε, τὸ δ᾽ ἐκείνων, ἂν εὖ ποιῶσιν, αὐταὶ ἐξελοῦσιν: εἰ δὲ μή, οἰμώξουσι δι᾽ αὑτάς.","st":"2.16"},{"sp":"N","t":"ἄνθρωπε, τὸ λεγόμενον τοῦτο ἀπονοήθητι ἤδη ὑπὲρ εὐροίας, ὑπὲρ ἐλευθερίας, ὑπὲρ μεγαλοψυχίας. ἀνάτεινόν ποτε τὸν τράχηλον ὡς ἀπηλλαγμένος δουλείας,","st":"2.16"},{"sp":"N","t":"τόλμησον ἀναβλέψας πρὸς τὸν θεὸν εἰπεῖν ὅτι ‘χρῶ μοι λοιπὸν εἰς ὃ ἂν θέλῃς: ὁμογνωμονῶ σοι, ἰσός εἰμι: οὐδὲν παραιτοῦμαι τῶν σοὶ δοκούντων: ὅπου θέλεις, ἄγε: ἣν θέλεις ἐσθῆτα περίθες. ἄρχειν με θέλεις, ἰδιωτεύειν, μένειν, φεύγειν, πένεσθαι, πλουτεῖν; ἐγώ σοι ὑπὲρ ἁπάντων τούτων πρὸς τοὺς ἀνθρώπους ἀπολογήσομαι: δείξω τὴν ἑκάστου φύσιν οἵα ἐστίν.’","st":"2.16"},{"sp":"N","t":"οὔ:","st":"2.16"},{"sp":"N","t":"ἀλλ᾽ ἐν βοὸς κοιλίᾳ καθήμενος ἐκδέχου σου τὴν μάμμην, μέχρις σε χορτάσῃ. ὁ Ἡρακλῆς εἰ τοῖς ἐν οἴκῳ παρεκάθητο, τίς ἂν ἦν; Εὐρυσθεὺς καὶ οὐχὶ Ἡρακλῆς. ἄγε, πόσους δὲ περιερχόμενος τὴν οἰκουμένην συνήθεις ἔσχεν, φίλους; ἀλλ᾽ οὐδὲν φίλτερον τοῦ θεοῦ: διὰ τοῦτο ἐπιστεύθη Διὸς υἱὸς εἶναι καὶ ἦν. ἐκείνῳ τοίνυν πειθόμενος περιῄει καθαίρων ἀδικίαν καὶ ἀνομίαν.","st":"2.16"},{"sp":"N","t":"ἀλλ᾽ οὐκ εἶ Ἡρακλῆς καὶ οὐ δύνασαι καθαίρειν τὰ ἀλλότρια κακά, ἀλλ᾽ οὐδὲ Θησεύς, ἵνα τὰ τῆς Ἀττικῆς καθάρῃς: τὰ σαυτοῦ κάθαρον. ἐντεῦθεν ἐκ τῆς διανοίας ἔκβαλε ἀντὶ Προκρούστου καὶ Σκίρωνος λύπην, φόβον, ἐπιθυμίαν, φθόνον, ἐπιχαιρεκακίαν, φιλαργυρίαν, μαλακίαν, ἀκρασίαν.","st":"2.16"},{"sp":"N","t":"ταῦτα δ᾽ οὐκ ἔστιν ἄλλως ἐκβαλεῖν, εἰ μὴ πρὸς μόνον τὸν θεὸν ἀποβλέποντα, ἐκείνῳ μόνῳ προσπεπονθότα, τοῖς ἐκείνου προστάγμασι καθωσιωμένον. ἂν δ᾽ ἄλλο τι θέλῃς,","st":"2.16"},{"sp":"N","t":"οἰμώζων καὶ στένων ἀκολουθήσεις τῷ ἰσχυροτέρῳ ἔξω ζητῶν ἀεὶ τὴν εὔροιαν καὶ μηδέποτ᾽ εὐροεῖν δυνάμενος. ἐκεῖ γὰρ αὐτὴν ζητεῖς, οὗ μή ἐστιν, ἀφεὶς ἐκεῖ ζητεῖν, ὅπου ἐστίν. πῶς ἐφαρμοστέον τὰς προλήψεις τοῖς ἐπὶ μέρους. τί πρῶτόν ἐστιν ἔργον τοῦ φιλοσοφοῦντος; ἀποβαλεῖν οἴησιν: ἀμήχανον γάρ, ἅ τις εἰδέναι οἴεται, ταῦτα ἄρξασθαι μανθάνειν.","st":"2.16"},{"sp":"N","t":"τὰ μὲν οὖν ποιητέα καὶ οὐ ποιητέα καὶ ἀγαθὰ καὶ κακὰ καὶ καλὰ καὶ αἰσχρὰ πάντες ἄνω καὶ κάτω λαλοῦντες ἐρχόμεθα πρὸς τοὺς φιλοσόφους, ἐπὶ τούτοις ἐπαινοῦντες ψέγοντες, ἐγκαλοῦντες μεμφόμενοι, περὶ ἐπιτηδευμάτων καλῶν καὶ αἰσχρῶν ἐπικρίνοντες καὶ διαλαμβάνοντες.","st":"2.17"},{"sp":"N","t":"τίνος δ᾽ ἕνεκα προσερχόμεθα τοῖς φιλοσόφοις; † ἃ οὐκ οἰόμεθα εἰδέναι. τίνα δ᾽ ἐστὶ ταῦτα; τὰ θεωρήματα. ἃ γὰρ λαλοῦσιν οἱ φιλόσοφοι, μαθεῖν θέλομεν ὡς κομψὰ καὶ δριμέα, οἱ δ᾽, ἵν᾽ ἀπ᾽ αὐτῶν περιποιήσωνται.","st":"2.17"},{"sp":"N","t":"γελοῖον οὖν τὸ οἴεσθαι, ὅτι ἄλλα μέν τις μαθεῖν βούλεται, ἄλλα δὲ μαθήσεται, ἢ λοιπὸν ὅτι προκόψει τις ἐν οἷς οὐ μανθάνει.","st":"2.17"},{"sp":"N","t":"τὸ δ᾽ ἐξαπατῶν τοὺς πολλοὺς τοῦτ᾽ ἔστιν, ὅπερ καὶ Θεόπομπον τὸν ῥήτορα, ὅπου καὶ Πλάτωνι ἐγκαλεῖ ἐπὶ τῷ βούλεσθαι ἕκαστα ὁρίζεσθαι.","st":"2.17"},{"sp":"N","t":"τί γὰρ λέγει; ‘οὐδεὶς ἡμῶν πρὸ σοῦ ἔλεγεν ἀγαθὸν ἢ δίκαιον; ἢ μὴ παρακολουθοῦντες τί ἐστι τούτων ἕκαστον ἀσήμως καὶ κενῶς","st":"2.17"},{"sp":"N","t":"ἐφθεγγόμεθα τὰς φωνάς;’ τίς γάρ σοι λέγει, Θεόπομπε, ὅτι ἐννοίας οὐκ εἴχομεν ἑκάστου τούτων φυσικὰς καὶ προλήψεις; ἀλλ᾽ οὐχ οἷόν τ᾽ ἐφαρμόζειν τὰς προλήψεις ταῖς καταλλήλοις οὐσίαις μὴ διαρθρώσαντα αὐτὰς καὶ αὐτὸ τοῦτο σκεψάμενον, ποίαν τινὰ ἑκάστῃ αὐτῶν οὐσίαν ὑποτακτέον.","st":"2.17"},{"sp":"N","t":"ἐπεὶ τοιαῦτα λέγε καὶ πρὸς τοὺς ἰατρούς: ‘τίς γὰρ ἡμῶν οὐκ ἔλεγεν ὑγιεινόν τι καὶ νοσερόν, πρὶν Ἱπποκράτη γενέσθαι; ἢ κενῶς τὰς φωνὰς ταύτας ἀπηχοῦμεν;’","st":"2.17"},{"sp":"N","t":"ἔχομεν γάρ τινα καὶ ὑγιεινοῦ πρόληψιν, ἀλλ᾽ ἐφαρμόσαι οὐ δυνάμεθα. διὰ τοῦτο ὁ μὲν λέγει ‘ἀνάτεινον,’ ὁ δὲ λέγει ‘δὸς τροφήν:’ καὶ ὁ μὲν λέγει ‘φλεβοτόμησον,’ ὁ δὲ λέγει ‘σικύασον.’ τί τὸ αἴτιον; ἄλλο γε ἢ ὅτι τὴν τοῦ ὑγιεινοῦ πρόληψιν οὐ δύναται καλῶς ἐφαρμόσαι τοῖς ἐπὶ μέρους;","st":"2.17"},{"sp":"N","t":"οὕτως ἔχει καὶ ἐνθάδ᾽ ἐπὶ τῶν κατὰ τὸν βίον. ἀγαθὸν καὶ κακὸν καὶ συμφέρον καὶ ἀσύμφορον τίς ἡμῶν οὐ λαλεῖ; τίς γὰρ ἡμῶν οὐκ ἔχει τούτων ἑκάστου πρόληψιν; ἆρ᾽ οὖν διηρθρωμένην καὶ τελείαν;","st":"2.17"},{"sp":"N","t":"τοῦτο δεῖξον. ‘πῶς δείξω;’ ἐφάρμοσον αὐτὴν καλῶς ταῖς ἐπὶ μέρους οὐσίαις. εὐθὺς τοὺς ὅρους Πλάτων μὲν ὑποτάσσει τῇ τοῦ χρησίμου προλήψει, σὺ δὲ τῇ τοῦ ἀχρήστου.","st":"2.17"},{"sp":"N","t":"δυνατὸν οὖν ἐστιν ἀμφοτέρους ὑμᾶς ἐπιτυγχάνειν; πῶς οἷόν τε; τῇ δὲ τοῦ πλούτου οὐσίᾳ οὐχ ὁ μέν τις ἐφαρμόζει τὴν τοῦ ἀγαθοῦ πρόληψιν, ὁ δ᾽ οὔ; τῇ δὲ τῆς ἡδονῆς, τῇ δὲ τῆς ὑγείας;","st":"2.17"},{"sp":"N","t":"καθόλου γὰρ εἰ πάντες οἱ τὰ ὀνόματα λαλοῦντες μὴ κενῶς ἴσμεν ἕκαστα τούτων καὶ μηδεμιᾶς ἐπιμελείας περὶ τὴν διάρθρωσιν τῶν προλήψεων δεόμεθα, τί διαφερόμεθα, τί πολεμοῦμεν, τί ψέγομεν ἀλλήλους;","st":"2.17"},{"sp":"N","t":"καὶ τί μοι νῦν τὴν πρὸς ἀλλήλους μάχην παραφέρειν καὶ ταύτης μεμνῆσθαι; σὺ αὐτὸς εἰ ἐφαρμόζεις καλῶς τὰς προλήψεις, διὰ τί δυσροεῖς, διὰ τί ἐμποδίζῃ;","st":"2.17"},{"sp":"N","t":"ἀφῶμεν ἄρτι τὸν δεύτερον τόπον τὸν περὶ τὰς ὁρμὰς καὶ τὴν κατὰ ταύτας περὶ τὸ καθῆκον φιλοτεχνίαν. ἀφῶμεν καὶ τὸν τρίτον τὸν περὶ τὰς συγκαταθέσεις.","st":"2.17"},{"sp":"N","t":"χαρίζομαί σοι ταῦτα πάντα. στῶμεν ἐπὶ τοῦ πρώτου καὶ σχεδὸν αἰσθητὴν παρέχοντος τὴν ἀπόδειξιν τοῦ μὴ ἐφαρμόζειν καλῶς τὰς προλήψεις.","st":"2.17"},{"sp":"N","t":"νῦν σὺ θέλεις τὰ δυνατὰ καὶ τὰ σοὶ δυνατά; τί οὖν ἐμποδίζῃ; διὰ τί δυσροεῖς; νῦν οὐ φεύγεις τὰ ἀναγκαῖα; διὰ τί οὖν περιπίπτεις τινί, διὰ τί δυστυχεῖς; διὰ τί θέλοντός σού τι οὐ γίνεται καὶ μὴ θέλοντος γίνεται;","st":"2.17"},{"sp":"N","t":"ἀπόδειξις γὰρ αὕτη μεγίστη δυσροίας καὶ κακοδαιμονίας. θέλω τι καὶ οὐ γίνεται: καὶ τί ἐστιν ἀθλιώτερον ἐμοῦ; οὐ θέλω τι καὶ γίνεται: καὶ τί ἐστιν ἀθλιώτερον ἐμοῦ;","st":"2.17"},{"sp":"N","t":"τοῦτο καὶ ἡ Μήδεια οὐχ ὑπομείνασα ἦλθεν ἐπὶ τὸ ἀποκτεῖναι τὰ τέκνα. μεγαλοφυῶς κατά γε τοῦτο. εἶχε γὰρ ἣν δεῖ φαντασίαν, οἷόν ἐστι τὸ ἃ θέλει τινὶ μὴ προχωρεῖν.","st":"2.17"},{"sp":"N","t":"‘εἶτα οὕτως τιμωρήσομαι τὸν ἀδικήσαντά με καὶ ὑβρίσαντα. καὶ τί ὄφελος τοῦ κακῶς οὕτως διακειμένου; πῶς οὖν γένηται; ἀποκτείνω μὲν τὰ τέκνα. ἀλλὰ καὶ ἐμα","st":"2.17"},{"sp":"N","t":"υτὴν τιμωρήσομαι. καὶ τί μοι μέλει;’ τοῦτ᾽ ἔστιν ἔκπτωσις ψυχῆς μεγάλα νεῦρα ἐχούσης. οὐ γὰρ ᾔδει, ποῦ κεῖται τὸ ποιεῖν ἃ θέλομεν, ὅτι τοῦτο οὐκ ἔξωθεν δεῖ λαμβάνειν οὐδὲ τὰ πράγματα μετατιθέντα καὶ μεθαρμοζόμενον.","st":"2.17"},{"sp":"N","t":"μὴ θέλε τὸν ἄνδρα, καὶ οὐδὲν ὧν θέλεις οὐ γίνεται. μὴ θέλε αὐτὸν ἐξ ἅπαντός σοι συνοικεῖν, μὴ θέλε μένειν ἐν Κορίνθῳ καὶ ἁπλῶς μηδὲν ἄλλο θέλε ἢ ἃ ὁ θεὸς θέλει. καὶ τίς σε κωλύσει, τίς ἀναγκάσει; οὐ μᾶλλον ἢ τὸν Δία.","st":"2.17"},{"sp":"N","t":"ὅταν τοιοῦτον ἔχῃς ἡγεμόνα καὶ τοιούτῳ συνθέλῃς καὶ συνορέγῃ, τί φοβῇ ἔτι μὴ ἀποτύχῃς;","st":"2.17"},{"sp":"N","t":"χάρισαί σου τὴν ὄρεξιν καὶ τὴν ἔκκλισιν πενίᾳ καὶ πλούτῳ: ἀποτεύξῃ, περιπεσῇ. ἀλλ᾽ ὑγιείᾳ: δυστυχήσεις: ἀρχαῖς, τιμαῖς, πατρίδι, φίλοις, τέκνοις, ἁπλῶς ἄν τινι τῶν ἀπροαιρέτων. ἀλλὰ τῷ Διὶ χάρισαι αὐτά","st":"2.17"},{"sp":"N","t":"ς, τοῖς ἄλλοις θεοῖς: ἐκείνοις παράδος, ἐκεῖνοι κυβερνάτωσαν, μετ᾽ ἐκείνων τετάχθωσαν: καὶ ποῦ ἔτι δυσροήσεις;","st":"2.17"},{"sp":"N","t":"εἰ δὲ φθονεῖς, ἀταλαίπωρε, καὶ ἐλεεῖς καὶ ζηλοτυπεῖς καὶ τρέμεις καὶ μίαν ἡμέραν οὐ διαλείπεις, ἐν ᾗ οὐ κατακλάεις καὶ σαυτοῦ καὶ τῶν θεῶν, καὶ τί ἔτι λέγεις πεπαιδεῦσθαι;","st":"2.17"},{"sp":"N","t":"ποίαν παιδείαν, ἄνθρωπε; ὅτι συλλογισμοὺς ἔπραξας, μεταπίπτοντας; οὐ θέλεις ἀπομαθεῖν, εἰ δυνατόν, πάντα ταῦτα καὶ ἄνωθεν ἄρξασθαι συναισθανόμενος ὅτι μέχρι νῦν οὐδ᾽ ἥψω τοῦ πράγματος,","st":"2.17"},{"sp":"N","t":"καὶ λοιπὸν ἔνθεν ἀρξάμενος προσοικοδομεῖν τὰ ἑξῆς, πῶς μηδὲν ἔσται σοῦ μὴ θέλοντος, θέλοντος μηδὲν οὐκ ἔσται;","st":"2.17"},{"sp":"N","t":"δότε μοι ἕνα νέον κατὰ ταύτην τὴν ἐπιβολὴν ἐληλυθότα εἰς σχολήν, τούτου τοῦ πράγματος ἀθλητὴν γενόμενον καὶ λέγοντα ὅτι ‘ἐμοὶ τὰ μὲν ἄλλα πάντα χαιρέτω, ἀρκεῖ δ᾽ εἰ ἐξέσται ποτὲ ἀπαραποδίστῳ καὶ ἀλύπῳ διαγαγεῖν καὶ ἀνατεῖναι τὸν τράχηλον πρὸς τὰ πράγματα ὡς ἐλεύθερον καὶ εἰς τὸν οὐρανὸν ἀναβλέπειν ὡς φίλον τοῦ θεοῦ μηδὲν φοβούμενον τῶν συμβῆναι δυναμένων.’ δειξάτω τις ὑμῶν αὐτὸν τοιοῦτον, ἵνα εἴπω:","st":"2.17"},{"sp":"N","t":"ἔρχου, νεανίσκε, εἰς τὰ σά: σοὶ γὰρ εἵμαρται κοσμῆσαι φιλοσοφίαν, σά ἐστι ταῦτα τὰ κτήματα, σὰ τὰ βιβλία, σοὶ οἱ λόγοι.","st":"2.17"},{"sp":"N","t":"εἶθ᾽, ὅταν τοιοῦτον ἐκπονήσῃ καὶ καταθλήσῃ τὸν τόπον, πάλιν ἐλθών μοι εἰπάτω ‘ἐγὼ θέλω μὲν καὶ ἀπαθὴς εἶναι καὶ ἀτάραχος, θέλω δ᾽ ὡς εὐσεβὴς καὶ φιλόσοφος καὶ ἐπιμελὴς εἰδέναι τί μοι πρὸς θεούς ἐστι καθῆκον, τί πρὸς γονεῖς, τί πρὸς ἀδελφούς, τί πρὸς τὴν πατρίδα, τί πρὸς ξένους.’","st":"2.17"},{"sp":"N","t":"ἔρχου καὶ ἐπὶ τὸν δεύτερον τόπον: σός ἐστι καὶ οὗτος.","st":"2.17"},{"sp":"N","t":"‘ἀλλ᾽ ἤδη καὶ τὸν δεύτερον τόπον ἐκμεμελέτηκα. ἤθελον δ᾽ ἀσφαλῶς καὶ ἀσείστως καὶ οὐ μόνον ἐγρηγορώς, ἀλλὰ καὶ καθεύδων καὶ οἰνωμένος καὶ ἐν μελαγχολίᾳ.’ σὺ θεὸς εἶ, ὦ ἄνθρωπε, σὺ μεγάλας ἔχεις ἐπιβολάς. οὔ: ἀλλ᾽","st":"2.17"},{"sp":"N","t":"‘ἐγὼ θέλω γνῶναι, τί λέγει Χρύσιππος ἐν τοῖς περὶ τοῦ Ψευδομένου.’ οὐκ ἀπάγξῃ μετὰ τῆς ἐπιβολῆς ταύτης, τάλας; καὶ τί σοι ὄφελος ἔσται; πενθῶν ἅπαν ἀναγνώσῃ καὶ τρέμων πρὸς ἄλλους ἐρεῖς.","st":"2.17"},{"sp":"N","t":"οὕτως καὶ ὑμεῖς ποιεῖτε. ‘θέλεις ἀναγνῶ σοι, ἀδελφέ;’ ‘καὶ σὺ ἐμοί.’ ‘θαυμαστῶς, ἄνθρωπε, γράφεις:’ καὶ ‘σὺ μεγάλως εἰς τὸν Ξενοφῶντος χαρακτῆρα,’ ‘σὺ εἰς τὸν Πλάτωνος,’","st":"2.17"},{"sp":"N","t":"‘σὺ εἰς τὸν Ἀντισθένους.’ εἶτ᾽ ἀλλήλοις ὀνείρους διηγησάμενοι πάλιν ἐπὶ ταὐτὰ ἐπανέρχεσθε: ὡσαύτως ὀρέγεσθε, ὡσαύτως ἐκκλίνετε, ὁμοίως ὁρμᾶτε, ἐπιβάλλεσθε, προστίθεσθε, ταὐτὰ εὔχεσθε, περὶ ταὐτὰ σπουδάζετε. εἶτα οὐδὲ ζητεῖτε τὸν ὑπομνήσοντα ὑμᾶς,","st":"2.17"},{"sp":"N","t":"ἀλλ᾽ ἄχθεσθε, ἐὰν ἀκούητε τούτων. εἶτα λέγετε ‘ἀφιλόστοργος γέρων: ἐξερχομένου μου οὐκ ἔκλαυσεν οὐδ᾽ εἶπεν ‘εἰς οἵαν περίστασιν ἀπέρχῃ μοι, τέκνον: ἂν σωθῇς, ἅψω λύχνους’.’ ταῦτ᾽ ἔστι τὰ τοῦ φιλοστόργου;","st":"2.17"},{"sp":"N","t":"μέγα σοι ἀγαθὸν ἔσται σωθέντι τοιούτῳ καὶ λύχνων ἄξιον. ἀθάνατον γὰρ εἶναί σε δεῖ καὶ ἄνοσον.","st":"2.17"},{"sp":"N","t":"ταύτην οὖν, ὅπερ λέγω, τὴν οἴησιν τὴν τοῦ δοκεῖν εἰδέναι τι τῶν χρησίμων ἀποβάλλοντας ἔρχεσθαι δεῖ πρὸς τὸν λόγον, ὡς πρὸς τὰ γεωμετρικὰ προσάγομεν, ὡ","st":"2.17"},{"sp":"N","t":"ς πρὸς τὰ μουσικά: εἰ δὲ μή, οὐδ᾽ ἐγγὺς ἐσόμεθα τῷ προκόψαι, κἂν πάσας τὰς εἰσαγωγὰς καὶ τὰς συντάξεις τὰς Χρυσίππου μετὰ τῶν Ἀντιπάτρου καὶ Ἀρχεδήμου διέλθωμεν. πῶς ἀγωνιστέον πρὸς τὰς φαντασίας. πᾶσα ἕξις καὶ δύναμις ὑπὸ τῶν καταλλήλων ἔργων συνέχεται καὶ αὔξεται, ἡ περιπατητικὴ ὑπὸ τοῦ περιπατεῖν, ἡ τροχαστικὴ ὑπὸ τοῦ τρέχειν.","st":"2.17"},{"sp":"N","t":"ἂν θέλῃς ἀναγνωστικὸς εἶναι, ἀναγίγνωσκε: ἂν γραφικός, γράφε. ὅταν δὲ τριάκοντα ἐφεξῆς ἡμέρας μὴ ἀναγνῷς, ἀλλ᾽ ἄλλο τι πράξῃς, γνώσῃ τὸ γινόμενον.","st":"2.18"},{"sp":"N","t":"οὕτως κἂν ἀναπέσῃς δέκα ἡμέρας, ἀναστὰς ἐπιχείρησον μακροτέραν ὁδὸν περιπατῆσαι καὶ ὄψει, πῶς σου τὰ σκέλη παραλύεται.","st":"2.18"},{"sp":"N","t":"καθόλου οὖν εἴ τι ποιεῖν ἐθέλῃς, ἑκτικὸν ποίει αὐτό: εἴ τι μὴ ποιεῖν ἐθέλῃς, μὴ ποίει αὐτό, ἀλλ᾽ ἔθισον ἄλλο τι πράττειν μᾶλλον ἀντ᾽ αὐτοῦ.","st":"2.18"},{"sp":"N","t":"οὕτως ἔχει καὶ ἐπὶ τῶν ψυχικῶν: ὅταν ὀργισθῇς, γίγνωσκε ὅτι οὐ μόνον σοι τοῦτο γέγονεν κακόν, ἀλλ᾽ ὅτι καὶ τὴν ἕξιν ηὔξησας καὶ ὡς πυρὶ φρύγανα παρέβαλες.","st":"2.18"},{"sp":"N","t":"ὅταν ἡττηθῇς τινος ἐν συνουσίᾳ, μὴ τὴν μίαν ἧτταν ταύτην λογίζου, ἀλλ᾽ ὅτι καὶ τὴν ἀκρασίαν σου τέτροφας, ἐπηύξησας.","st":"2.18"},{"sp":"N","t":"ἀδύνατον γὰρ ἀπὸ τῶν καταλλήλων ἔργων μὴ καὶ τὰς ἕξεις καὶ τὰς δυνάμεις τὰς μὲν ἐμφύεσθαι μὴ πρότερον οὔσας, τὰς δ᾽ ἐπιτείνεσθαι καὶ ἰσχυροποιεῖσθαι.","st":"2.18"},{"sp":"N","t":"οὕτως ἀμέλει καὶ τὰ ἀρρωστήματα ὑποφύεσθαι λέγουσιν οἱ φιλόσοφοι. ὅταν γὰρ ἅπαξ ἐπιθυμήσῃς ἀργυρίου, ἂν μὲν προσαχθῇ λόγος εἰς αἴσθησιν ἄξιων τοῦ κακοῦ, πέπαυταί τε ἡ ἐπιθυμία καὶ τὸ ἡγεμονικὸν ἡμῶν εἰς τὸ ἐξαρχῆς ἀποκατέστη:","st":"2.18"},{"sp":"N","t":"ἐὰν δὲ μηδὲν προσαγάγῃς εἰς θεραπείαν, οὐκέτι εἰς ταὐτὰ ἐπάνεισιν, ἀλλὰ πάλιν ἐρεθισθὲν ὑπὸ τῆς καταλλήλου φαντασίας θᾶττον ἢ πρότερον ἐξήφθη πρὸς τὴν ἐπιθυμίαν. καὶ τούτου συνεχῶς γινομένου τυλοῦται λοιπὸν καὶ τὸ ἀρρώστημα βεβαιοῖ τὴν φιλαργυρίαν.","st":"2.18"},{"sp":"N","t":"ὁ γὰρ πυρέξας, εἶτα παυσάμενος οὐχ ὁμοίως ἔχει τῷ πρὸ τοῦ πυρέξαι, ἂν μή τι θεραπευθῇ εἰς ἅπαν.","st":"2.18"},{"sp":"N","t":"τοιοῦτόν τι καὶ ἐπὶ τῶν τῆς ψυχῆς παθῶν γίνεται. ἴχνη τινὰ καὶ μώλωπες ἀπολείπονται ἐν αὐτῇ, οὓς εἰ μή τις ἐξαλείψῃ καλῶς, πάλιν κατὰ τῶν αὐτῶν μαστιγωθεὶς οὐκέτι μώλωπας, ἀλλ᾽ ἕλκη ποιεῖ. εἰ οὖν θέλεις μὴ εἶναι ὀργίλος,","st":"2.18"},{"sp":"N","t":"μὴ τρέφε σου τὴν ἕξιν, μηδὲν αὐτῇ παράβαλλε αὐξητικόν. τὴν πρώτην ἡσύχασον καὶ τὰς ἡμέρας ἀρίθμει ἃς οὐκ ὠργίσθης.","st":"2.18"},{"sp":"N","t":"‘καθ᾽ ἡμέραν εἰώθειν ὀργίζεσθαι, νῦν παρ᾽ ἡμέραν, εἶτα παρὰ δύο, εἶτα παρὰ τρεῖς.’ ἂν δὲ καὶ τριάκοντα παραλίπῃς, ἐπίθυσον τῷ θεῷ. ἡ γὰρ ἕξις ἐκλύεται τὴν πρώτην, εἶτα καὶ παντελῶς ἀναιρεῖται.","st":"2.18"},{"sp":"N","t":"‘σήμερον οὐκ ἐλυπήθην οὐδ᾽ αὔριον οὐδ᾽ ἐφεξῆς διμήνῳ καὶ τριμήνῳ: ἀλλὰ προσέσχον γενομένων τινῶν ἐρεθιστικῶν.’ γίγνωσκε ὅτι κομψῶς σοί ἐστιν.","st":"2.18"},{"sp":"N","t":"‘σήμερον καλὸν ἰδὼν ἢ καλὴν’ οὐκ εἶπον αὐτὸς ἐμαυτῷ ὅτι ‘ὤφελόν τις μετὰ ταύτης ἐκοιμήθη’ καὶ ‘μακάριος ὁ ἀνὴρ αὐτῆς:’ ὁ γὰρ τοῦτ᾽ εἰπὼν ‘μακάριος’ καὶ","st":"2.18"},{"sp":"N","t":"‘ὁ μοιχός:’ οὐδὲ τὰ ἑξῆς ἀναζωγραφῶ, παροῦσαν αὐτὴν καὶ ἀποδυομένην καὶ παρακατακλινομένην.","st":"2.18"},{"sp":"N","t":"καταψῶ τὴν κορυφήν μου καὶ λέγω: εὖ, Ἐπίκτητε, κομψὸν σοφισμάτιον ἔλυσας, πολλῷ κομψότερον τοῦ Κυριεύοντος.","st":"2.18"},{"sp":"N","t":"ἂν δὲ καὶ βουλομένου τοῦ γυναικαρίου καὶ νεύοντος καὶ προσπέμποντος, ἂν δὲ καὶ ἁπτομένου καὶ συνεγγίζοντος ἀπόσχωμαι καὶ νικήσω, τοῦτο μὲν ἤδη τὸ σόφισμα ὑπὲρ τὸν Ψευδόμενον, ὑπὲρ τὸν Ἡσυχάζοντα. ἐπὶ τούτῳ καὶ μέγα φρονεῖν ἄξιον, οὐκ ἐπὶ τῷ τὸν Κυριεύοντα ἐρωτῆσαι.","st":"2.18"},{"sp":"N","t":"πῶς οὖν γένηται τοῦτο; θέλησον ἀρέσαι αὐτός ποτε σεαυτῷ, θέλησον καλὸς φανῆναι τῷ θεῷ: ἐπιθύμησον καθαρὸς μετὰ καθαροῦ σαυτοῦ γενέσθαι καὶ μετὰ τοῦ θεοῦ.","st":"2.18"},{"sp":"N","t":"εἶθ᾽ ὅταν προσπίπτῃ σοί τις φαντασία τοιαύτη, Πλάτων μὲν ὅτι ἴθι ἐπὶ τὰς ἀποδιοπομπήσεις, ἴθι ἐπὶ θεῶν ἀποτροπαίων ἱερὰ ἱκέτης:","st":"2.18"},{"sp":"N","t":"ἀρκεῖ κἂν ἐπὶ τὰς τῶν καλῶν καὶ ἀγαθῶν ἀνδρῶν συνουσίας ἀποχωρήσας πρὸς τούτῳ γίνῃ ἀντεξετάζων, ἄν τε τῶν ζώντων τινὰ ἔχῃς ἄν τε τῶν ἀποθανόντων.","st":"2.18"},{"sp":"N","t":"ἄπελθε πρὸς Σωκράτη καὶ ἴδε αὐτὸν συγκατακείμενον Ἀλκιβιάδῃ καὶ διαπαίζοντα αὐτοῦ τὴν ὥραν. ἐνθυμήθητι οἵαν νίκην ποτὲ ἔγνω ἐκεῖνος νενικηκότα ἑαυτόν, οἷα Ὀλύμπια, πόστος ἀφ᾽ Ἡρακλέους ἐγένετο: ἵνα τις, νὴ τοὺς θεούς, δικαίως ἀσπάζηται αὐτὸν ‘χαῖρε, παράδοξε,’ οὐχὶ τοὺς σαπροὺς τούτους πύκτας καὶ παγκρατιαστὰς οὐδὲ τοὺς ὁμοίους αὐτοῖς, τοὺς μονομάχους.","st":"2.18"},{"sp":"N","t":"ταῦτα ἀντιθεὶς νικήσεις τὴν φαντασίαν, οὐχ ἑλκυσθήσῃ ὑπ᾽ αὐτῆς.","st":"2.18"},{"sp":"N","t":"τὸ πρῶτον δ᾽ ὑπὸ τῆς ὀξύτητος μὴ συναρπασθῇς, ἀλλ᾽ εἰπὲ ‘ἔκδεξαί με μικρόν, φαντασία: ἄφες ἴδω τίς εἶ καὶ περὶ τίνος, ἄφες σε δοκιμάσω.’","st":"2.18"},{"sp":"N","t":"καὶ τὸ λοιπὸν μὴ ἐφῇς αὐτῇ προάγειν ἀναζωγραφούσῃ τὰ ἑξῆς. εἰ δὲ μή, οἴχεταί σε ἔχουσα ὅπου ἂν θέλῃ. ἀλλὰ μᾶλλον ἄλλην τινὰ ἀντεισάγαγε καλὴν καὶ γενναίαν φαντασίαν καὶ ταύτην τὴν ῥυπαρὰν ἔκβαλε.","st":"2.18"},{"sp":"N","t":"κἂν ἐθισθῇς οὕτως γυμνάζεσθαι, ὄψει, οἷοι ὦμοι γίνονται, οἷα νεῦρα, οἷοι τόνοι: νῦν δὲ μόνον τὰ λογάρια καὶ πλέον οὐδὲ ἕν.","st":"2.18"},{"sp":"N","t":"οὗτός ἐστιν ὁ ταῖς ἀληθείαις ἀσκητὴς ὁ πρὸς τὰς τοιαύτας φαντασίας γυμνάζων ἑαυτόν.","st":"2.18"},{"sp":"N","t":"μεῖνον, τάλας, μὴ συναρπασθῇς. μέγας ὁ ἀγών ἐστιν, θεῖον τὸ ἔργον, ὑπὲρ βασιλείας, ὑπὲρ ἐλευθερίας, ὑπὲρ εὐροίας, ὑπὲρ ἀταραξίας.","st":"2.18"},{"sp":"N","t":"τοῦ θεοῦ μέμνησο, ἐκεῖνον ἐπικαλοῦ βοηθὸν καὶ παραστάτην ὡς τοὺς Διοσκόρους ἐν χειμῶνι οἱ πλέοντες. ποῖος γὰρ μείζων χειμὼν ἢ ὁ ἐκ φαντασιῶν ἰσχυρῶν καὶ ἐκκρουστικῶν τοῦ λόγου; αὐτὸς γὰρ ὁ χειμὼν τί ἄλλο ἐστὶν ἢ φαντασία;","st":"2.18"},{"sp":"N","t":"ἐπεί τοι ἆρον τὸν φόβον τοῦ θανάτου καὶ φέρε ὅσας θέλεις βροντὰς καὶ ἀστραπὰς καὶ γνώσῃ, ὅση γαλήνη ἐστὶν ἐν τῷ ἡγεμονικῷ καὶ εὐδία.","st":"2.18"},{"sp":"N","t":"ἂν δ᾽ ἅπαξ ἡττηθεὶς εἴπῃς ὅτι ὕστερον νικήσεις, εἶτα πάλιν τὸ αὐτό, ἴσθι ὅτι οὕτως ποθ᾽ ἕξεις κακῶς καὶ ἀσθενῶς, ὥστε μηδ᾽ ἐφιστάνειν ὕστερον ὅτι ἁμαρτάνεις, ἀλλὰ καὶ ἀπολογίας ἄρξῃ πορίζειν ὑπὲρ τοῦ πράγματος:","st":"2.18"},{"sp":"N","t":"καὶ τότε βεβαιώσεις τὸ τοῦ Ἡσιόδου, ὅτι ἀληθές ἐστιν αἰεὶ δ᾽ ἀμβολιεργὸς ἀνὴρ ἄτῃσι παλαίει. πρὸς τοὺς μέχρι λόγου μόνον ἀναλαμβάνοντας τὰ τῶν φιλοσόφων. ὁ κυριεύων λόγος ἀπὸ τοιούτων τινῶν ἀφορμῶν ἠρωτῆσθαι φαίνεται: κοινῆς γὰρ οὔσης μάχης τοῖς τρισὶ τούτοις πρὸς ἄλληλα, τῷ τὸ πᾶν παρεληλυθὸς ἀληθὲς ἀναγκαῖον εἶναι καὶ τῷ ἀδυνατῷ ἀδύνατον μὴ ἀκολουθεῖν καὶ τῷ * * δυνατὸν εἶναι ὃ οὔτ᾽ ἔστιν ἀληθὲς οὔτ᾽ ἔσται, συνιδὼν τὴν μάχην ταύτην ὁ Διόδωρος τῇ τῶν πρώτων δυεῖν πιθανότητι συνεχρήσατο πρὸς παράστασιν τοῦ μηδὲν εἶναι δυνατόν, ὃ οὔτ᾽ ἔστιν ἀληθὲς οὔτ᾽ ἔσται.","st":"2.18"},{"sp":"N","t":"λοιπὸν ὁ μέν τις ταῦτα τηρήσει τῶν δυεῖν, ὅτι ἔστι τέ τι δυνατόν, ὃ οὔτ᾽ ἔστιν ἀληθὲς οὔτ᾽ ἔσται, καὶ δυνατῷ ἀδύνατον οὐκ ἀκολουθεῖ: οὐ πᾶν δὲ παρεληλυθὸς ἀληθὲς ἀναγκαῖόν ἐστιν, καθάπερ οἱ περὶ Κλεάνθην φέρεσθαι δοκοῦσιν, οἷς ἐπὶ πολὺ συνηγόρησεν Ἀντίπατρος.","st":"2.19"},{"sp":"N","t":"οἱ δὲ τἆλλα δύο, ὅτι δυνατόν τ᾽ ἐστίν, ὃ οὔτ᾽ ἔστιν ἀληθὲς οὔτ᾽ ἔσται, καὶ πᾶν παρεληλυθὸς ἀληθὲς ἀναγκαῖόν ἐστιν, δυνατῷ δ᾽ ἀδύνατον ἀκολουθεῖ.","st":"2.19"},{"sp":"N","t":"τὰ τρία δ᾽ ἐκεῖνα τηρῆσαι ἀμήχανον διὰ τὸ κοινὴν εἶναι αὐτῶν μάχην. ἂν οὖν τίς μου πύθηται","st":"2.19"},{"sp":"N","t":"‘σὺ δὲ ποῖα αὐτῶν τηρεῖς;’ ἀποκρινοῦμαι πρὸς αὐτὸν ὅτι οὐκ οἶδα: παρείληφα δ᾽ ἱστορίαν τοιαύτην, ὅτι Διόδωρος μὲν ἐκεῖνα ἐτήρει, οἱ δὲ περὶ Πανθοίδην οἶμαι καὶ Κλεάνθην τὰ ἄλλα, οἱ δὲ περὶ Χρύσιππον τὰ ἄλλα.","st":"2.19"},{"sp":"N","t":"‘σὺ οὖν τί;’ οὐδὲ γέγονα πρὸς τούτῳ, τῷ βασανίσαι τὴν ἐμαυτοῦ φαντασίαν καὶ συγκρῖναι τὰ λεγόμενα καὶ δόγμα τι ἐμαυτοῦ ποιήσασθαι κατὰ τὸν τόπον. διὰ τοῦτο οὐδὲν διαφέρω τοῦ γραμματικοῦ.","st":"2.19"},{"sp":"N","t":"‘τίς ἦν ὁ τοῦ Ἕκτορος πατήρ;’ ‘Πρίαμος.’ ‘τίνες ἀδελφοί;’ ‘Ἀλέξανδρος καὶ Δηίφοβος.’ ‘μήτηρ δ᾽ αὐτῶν τίς;’ ‘Ἑκάβη. παρείληφα ταύτην τὴν ἱστορίαν.’ ‘παρὰ τίνος;’ ‘παρ᾽ Ὁμήρου. γράφει δὲ περὶ τῶν αὐτῶν δοκῶ καὶ Ἑλλάνικος καὶ εἴ τις ἄλλος τοιοῦτος.’","st":"2.19"},{"sp":"N","t":"κἀγὼ περὶ τοῦ Κυριεύοντος τί ἄλλο ἔχω ἀνωτέρω; ἀλλ᾽ ἂν ὦ κενός, μάλιστα ἐπὶ συμποσίῳ καταπλήσσομαι τοὺς παρόντας ἐξαριθμούμενος τοὺς γεγραφότας.","st":"2.19"},{"sp":"N","t":"‘γέγραφεν δὲ καὶ Χρύσιππος θαυμαστῶς ἐν τῷ πρώτῳ περὶ Δυνατῶν. καὶ Κλεάνθης δ᾽ ἰδίᾳ γέγραφεν περὶ τούτου καὶ Ἀρχέδημος. γέγραφεν δὲ καὶ Ἀντίπατρος, οὐ μόνον δ᾽ ἐν τοῖς περὶ Δυνατῶν, ἀλλὰ καὶ κατ᾽ ἰδίαν ἐν τοῖς περὶ τοῦ Κυριεύοντος.","st":"2.19"},{"sp":"N","t":"οὐκ ἀνέγνωκας τὴν σύνταξιν;’ ‘οὐκ ἀνέγνωκα.’ ‘ἀνάγνωθι.’ καὶ τί ὠφεληθήσεται; φλυαρότερος ἔσται καὶ ἀκαιρότερος ἢ νῦν ἐστιν. σοὶ γὰρ τί ἄλλο προσγέγονεν ἀναγνόντι; ποῖον δόγμα πεποίησαι κατὰ τὸν τόπον; ἀλλ᾽ ἐρεῖς ἡμῖν Ἑλένην καὶ Πρίαμον καὶ τὴν τῆς Καλυψοῦς νῆσον τὴν οὔτε γενομένην οὔτ᾽ ἐσομένην.","st":"2.19"},{"sp":"N","t":"καὶ ἐνταῦθα μὲν οὐδὲν μέγα τῆς ἱστορίας κρατεῖν, ἴδιον δὲ δόγμα μηδὲν πεποιῆσθαι. ἐπὶ τῶν ἠθικῶν δὲ πάσχομεν αὐτὸ πολὺ μᾶλλον ἢ ἐπὶ τούτων.","st":"2.19"},{"sp":"N","t":"‘εἰπέ μοι περὶ ἀγαθῶν καὶ κακῶν.’ ‘ἄκουε: Ἰλιόθεν με φέρων ἄνεμος Κικόνεσσι πέλασσεν. τῶν ὄντων τὰ μέν ἐστιν ἀγαθά,","st":"2.19"},{"sp":"N","t":"τὰ δὲ κακά, τὰ δ᾽ ἀδιάφορα. ἀγαθὰ μὲν οὖν αἱ ἀρεταὶ καὶ τὰ μετέχοντα αὐτῶν, κακὰ δὲ κακίαι καὶ τὰ μετέχοντα κακίας, ἀδιάφορα δὲ τὰ μεταξὺ τούτων, πλοῦτος, ὑγίεια, ζωή, θάνατος, ἡδονή, πόνος.’","st":"2.19"},{"sp":"N","t":"‘πόθεν οἶδας;’ ‘Ἑλλάνικος λέγει ἐν τοῖς Αἰγυπτιακοῖς.’ τί γὰρ διαφέρει τοῦτο εἰπεῖν ἢ ὅτι Διογένης ἐν τῇ Ἠθικῇ ἢ Χρύσιππος ἢ Κλεάνθης; βεβασάνικας οὖν τι αὐτῶν καὶ δόγμα σεαυτοῦ πεποίησαι;","st":"2.19"},{"sp":"N","t":"δείκνυε πῶς εἴωθας ἐν πλοίῳ χειμάζεσθαι. μέμνησαι ταύτης τῆς διαιρέσεως, ὅταν ψοφήσῃ τὸ ἱστίον καὶ ἀνακραυγάσαντί σοι κακόσχολός πως παραστὰς εἴπῃ ‘λέγε μοι τοὺς θεούς σοι ἃ πρῴην ἔλεγες: μή τι κακίας ἐστὶ τὸ ναυαγῆσαι, μή τι κακίας μετέχον;’","st":"2.19"},{"sp":"N","t":"οὐκ ἄρας ξύλον ἐνσείσεις αὐτῷ; ‘τί ἡμῖν καὶ σοί, ἄνθρωπε; ἀπολλύμεθα καὶ σὺ ἐλθὼν παίζεις.’","st":"2.19"},{"sp":"N","t":"ἂν δέ σε ὁ Καῖσαρ μεταπέμψηται κατηγορούμενον, μέμνησαι τῆς διαιρέσεως, ἄν τίς σοι εἰσιόντι καὶ ὠχριῶντι ἅμα καὶ τρέμοντι προσελθὼν εἴπῃ ‘τί τρέμεις, ἄνθρωπε; περὶ τίνων σοί ἐστιν ὁ λόγος; μή τι ἔσω ὁ Καῖσαρ ἀρετὴν καὶ κακίαν τοῖς εἰσερχομένοις δίδωσι;’","st":"2.19"},{"sp":"N","t":"‘τί μοι ἐμπαίζεις καὶ σὺ πρὸς τοῖς ἐμοῖς κακοῖς;’ ‘ὅμως, φιλόσοφε, εἰπέ μοι, τί τρέμεις; οὐχὶ θάνατός ἐστι τὸ κινδυνευόμενον ἢ δεσμωτήριον ἢ πόνος τοῦ σώματος ἢ φυγὴ ἢ ἀδοξία; τί γὰρ ἄλλο; μή τι κακία, μή τι μέτοχον κακίας;","st":"2.19"},{"sp":"N","t":"σὺ οὖν τίνα ταῦτα ἔλεγες;’ ‘τί ἐμοὶ καὶ σοί, ἄνθρωπε; ἀρκεῖ ἐμοὶ τὰ ἐμὰ κακά.’ καὶ καλῶς λέγεις. ἀρκεῖ γάρ σοι τὰ σὰ κακά, ἡ ἀγέννεια, ἡ δειλία, ἡ ἀλαζονεία, ἣν ἠλαζονεύου ἐν τῇ σχολῇ καθήμενος. τί τοῖς ἀλλοτρίοις ἐκαλλωπίζου; τί Στωικὸν ἔλεγες σεαυτόν;","st":"2.19"},{"sp":"N","t":"Τηρεῖτε οὕτως ἑαυτοὺς ἐν οἷς ἐπράσσετε καὶ εὑρήσετε τίνος ἔσθ᾽ αἱρέσεως. τοὺς πλείστους ὑμῶν Ἐπικουρείους εὑρήσετε, ὀλίγους τινὰς Περιπατητικοὺς καὶ τούτους ἐκλελυμένους.","st":"2.19"},{"sp":"N","t":"ποῦ γὰρ ἵν᾽ ὑμεῖς τὴν ἀρετὴν πᾶσιν τοῖς ἄλλοις ἴσην ἢ καὶ κρείττονα ἔργῳ ὑπολάβητε; Στωικὸν δὲ δείξατέ μοι, εἴ τινα ἔχητε.","st":"2.19"},{"sp":"N","t":"ποῦ ἢ πῶς; ἀλλὰ τὰ λογάρια τὰ Στωικὰ λέγοντας μυρίους. τὰ γὰρ Ἐπικούρεια αὐτοὶ οὗτοι χεῖρον λέγουσι; τὰ γὰρ Περιπατητικὰ οὐ καὶ αὐτὰ ὁμοίως ἀκριβοῦσιν;","st":"2.19"},{"sp":"N","t":"τίς οὖν ἐστι Στωικός; ὡς λέγομεν ἀνδριάντα Φειδιακὸν τὸν τετυπωμένον κατὰ τὴν τέχνην τὴν Φειδίου, οὕτως τινά μοι δείξατε κατὰ τὰ δόγματα ἃ λαλεῖ τετυπωμένον.","st":"2.19"},{"sp":"N","t":"δείξατέ μοί τινα νοσοῦντα καὶ εὐτυχοῦντα, κινδυνεύοντα καὶ εὐτυχοῦντα, ἀποθνῄσκοντα καὶ εὐτυχοῦντα, πεφυγαδευμένον καὶ εὐτυχοῦντα, ἀδοξοῦντα καὶ εὐτυχοῦντα. δείξατ᾽: ἐπιθυμῶ τινα νὴ τοὺς θεοὺς ἰδεῖν Στωικόν.","st":"2.19"},{"sp":"N","t":"ἀλλ᾽ οὐκ ἔχετε τὸν τετυπωμένον δεῖξαι: τόν γε τυπούμενον δείξατε, τὸν ἐπὶ ταῦτα κεκλικότα. εὐεργετήσατέ με: μὴ φθονήσητε ἀνθρώπῳ γέροντι ἰδεῖν θέαμα, ὃ μέχρι νῦν οὐκ εἶδον.","st":"2.19"},{"sp":"N","t":"οἴεσθε ὅτι τὸν Δία τὸν Φειδίου δείξετε ἢ τὴν Ἀθηνᾶν, ἐλεφάντινον καὶ χρυσοῦν κατασκεύασμα. ψυχὴν δειξάτω τις ὑμῶν ἀνθρώπου θέλοντος ὁμογνωμονῆσαι τῷ θεῷ καὶ μηκέτι μήτε θεὸν μήτ᾽ ἄνθρωπον μέμφεσθαι, μὴ ἀποτυχεῖν τινος, μὴ περιπεσεῖν τινι, μὴ ὀργισθῆναι, μὴ φθονῆσαι, μὴ ζηλοτυπῆσαι （ τί γὰρ δεῖ περιπλέκειν;","st":"2.19"},{"sp":"N","t":"） , θεὸν ἐξ ἀνθρώπου ἐπιθυμοῦντα γενέσθαι καὶ ἐν τῷ σωματίῳ τούτῳ τῷ νεκρῷ περὶ τῆς πρὸς τὸν Δία κοινωνίας βουλευόμενον. δείξατε. ἀλλὰ οὐκ ἔχετε. τί οὖν αὑτοῖς ἐμπαίζετε καὶ τοὺς ἄλλους κυβεύετε;","st":"2.19"},{"sp":"N","t":"καὶ περιθέμενοι σχῆμα ἀλλότριον περιπατεῖτε κλέπται καὶ λωποδύται τούτων τῶν οὐδὲν προσηκόντων ὀνομάτων καὶ πραγμάτων;","st":"2.19"},{"sp":"N","t":"καὶ νῦν ἐγὼ μὲν παιδευτής εἰμι ὑμέτερος, ὑμεῖς δὲ παρ᾽ ἐμοὶ παιδεύεσθε. κἀγὼ μὲν ἔχω ταύτην τὴν ἐπιβολήν, ἀποτελέσαι ὑμᾶς ἀκωλύτους, ἀναναγκάστους, ἀπαραποδίστους, ἐλευθέρους, εὐροοῦντας, εὐδαιμονοῦντας, εἰς τὸν θεὸν ἀφορῶντας ἐν παντὶ καὶ μικρῷ καὶ μεγάλῳ: ὑμεῖς δὲ ταῦτα μαθησόμενοι καὶ μελετήσοντες πάρεστε.","st":"2.19"},{"sp":"N","t":"διὰ τί οὖν οὐκ ἀνύετε τὸ ἔργον, εἰ καὶ ὑμεῖς ἔχετ᾽ ἐπιβολὴν οἵαν δεῖ κἀγὼ πρὸς τῇ ἐπιβολῇ καὶ παρασκευὴν οἵαν δεῖ;","st":"2.19"},{"sp":"N","t":"τί τὸ λεῖπόν ἐστιν; ὅταν ἴδω τέκτονα, ὅτῳ ὕλη πάρεστιν παρακειμένη, ἐκδέχομαι τὸ ἔργον. καὶ ἐνθάδε τοίνυν ὁ τέκτων ἐστίν, ἡ ὕλη ἐστίν: τί ἡμῖν λείπει;","st":"2.19"},{"sp":"N","t":"οὐκ ἔστι διδακτὸν τὸ πρᾶγμα; διδακτόν. οὐκ ἔστιν οὖν ἐφ᾽ ἡμῖν; μόνον μὲν οὖν τῶν ἄλλων πάντων. οὔτε πλοῦτός ἐστιν ἐφ᾽ ἡμῖν οὔθ᾽ ὑγίεια οὔτε δόξα οὔτε ἄλλο τι ἁπλῶς πλὴν ὀρθὴ χρῆσις φαντασιῶν. τοῦτο ἀκώλυτον φύσει μόνον, τοῦτο ἀνεμπόδιστον.","st":"2.19"},{"sp":"N","t":"διὰ τί οὖν οὐκ ἀνύετε; εἴπατέ μοι τὴν αἰτίαν. ἢ γὰρ παρ᾽ ἐμὲ γίνεται ἢ παρ᾽ ὑμᾶς ἢ παρὰ τὴν φύσιν τοῦ πράγματος. αὐτὸ τὸ πρᾶγμα ἐνδεχόμενον καὶ μόνον ἐφ᾽ ἡμῖν. λοιπὸν οὖν ἢ παρ᾽ ἐμέ ἐστιν ἢ παρ᾽ ὑμᾶς ἤ, ὅπερ ἀληθέστερον, παρ᾽ ἀμφοτέρους. τί οὖν;","st":"2.19"},{"sp":"N","t":"θέλετε ἀρξώμεθά ποτε τοιαύτην ἐπιβολὴν κομίζειν ἐνταῦθα; τὰ μέχρι νῦν ἀφῶμεν. ἀρξώμεθα μόνον, πιστεύσατέ μοι, καὶ ὄψεσθε. πρὸς Ἐπικουρείους καὶ Ἀκαδημαικούς. τοῖς ὑγιέσι καὶ ἐναργέσιν ἐξ ἀνάγκης καὶ οἱ ἀντιλέγοντες προσχρῶνται. καὶ σχεδὸν τοῦτο μέγιστον ἄν τις ποιήσαιτο τεκμήριον τοῦ ἐναργές τι εἶναι, τὸ ἐπάναγκες εὑρίσκεσθαι καὶ τῷ ἀντιλέγοντι συγχρήσασθαι αὐτῷ: οἷον εἴ τις ἀντιλέγοι τῷ εἶναί τι καθολικὸν ἀληθές,","st":"2.19"},{"sp":"N","t":"δῆλον ὅτι τὴν ἐναντίαν ἀπόφασιν οὗτος ὀφείλει ποιήσασθαι: οὐδέν ἐστι καθολικὸν ἀληθές. ἀνδράποδον, οὐδὲ τοῦτο.","st":"2.20"},{"sp":"N","t":"τί γὰρ ἄλλο ἐστὶ τοῦτο ἢ οἷον εἴ τι ἔστι καθολικόν, ψεῦδός ἐστιν;","st":"2.20"},{"sp":"N","t":"πάλιν ἄν τις παρελθὼν λέγῃ ‘γίγνωσκε, ὅτι οὐδέν ἐστι γνωστόν, ἀλλὰ πάντα ἀτέκμαρτα’ ἢ ἄλλος ὅτι ‘πίστευσόν μοι καὶ ὠφεληθήσῃ: οὐδὲν δεῖ ἀνθρώπῳ πιστεύειν’ ἢ πάλιν ἄλλος ‘μάθε παρ᾽ ἐμοῦ, ἄνθρωπε, ὅτι οὐδὲν ἐνδέχεται μαθεῖν: ἐγώ σοι λέγω τοῦτο καὶ διδάξω σε, ἐὰν θέλῃς:’","st":"2.20"},{"sp":"N","t":"τίνι οὖν τούτων διαφέρουσιν οὗτοι — τίνες ποτέ; — οἱ Ἀκαδημαικοὺς αὑτοὺς λέγοντες; ‘ὦ ἄνθρωποι, συγκατάθεσθε ὅτι οὐδεὶς συγκατατίθεται: πιστεύσατε ἡμῖν ὅτι οὐδεὶς πιστεύει οὐδενί.’","st":"2.20"},{"sp":"N","t":"οὕτως καὶ Ἐπίκουρος, ὅταν ἀναιρεῖν θέλῃ τὴν φυσικὴν κοινωνίαν ἀνθρώποις πρὸς ἀλλήλους, αὐτῷ τῷ ἀναιρουμένῳ συγχρῆται.","st":"2.20"},{"sp":"N","t":"τί γὰρ λέγει; ‘μὴ ἐξαπατᾶσθε, ἄνθρωποι, μηδὲ παράγεσθε μηδὲ διαπίπτετε: οὐκ ἔστι φυσικὴ κοινωνία τοῖς λογικοῖς πρὸς ἀλλήλους: πιστεύσατέ μοι. οἱ δὲ τὰ ἕτερα λέγοντες ἐξαπατῶσιν ὑμᾶς καὶ παραλογίζονται.’","st":"2.20"},{"sp":"N","t":"τί οὖν σοι μέλει; ἄφες ἡμᾶς ἐξαπατηθῆναι. μή τι χεῖρον ἀπαλλάξεις, ἂν πάντες οἱ ἄλλοι πεισθῶμεν, ὅτι φυσική ἐστιν ἡμῖν κοινωνία πρὸς ἀλλήλους καὶ ταύτην δεῖ παντὶ τρόπῳ φυλάσσειν; καὶ πολὺ κρεῖσσον καὶ ἀσφαλέστερον.","st":"2.20"},{"sp":"N","t":"ἄνθρωπε, τί ὑπὲρ ἡμῶν φροντίζεις, τί δι᾽ ἡμᾶς ἀγρυπνεῖς, τί λύχνον ἅπτεις, τί ἐπανίστασαι, τί τηλικαῦτα βιβλία συγγράφεις; μή τις ἡμῶν ἐξαπατηθῇ περὶ θεῶν ὡς ἐπιμελουμένων ἀνθρώπων ἢ μή τις ἄλλην οὐσίαν ὑπολάβῃ τοῦ ἀγαθοῦ ἢ ἡδονήν;","st":"2.20"},{"sp":"N","t":"εἰ γὰρ οὕτως ταῦτα ἔχει, βαλὼν κάθευδε καὶ τὰ τοῦ σκώληκος ποίει, ὧν ἄξιον ἔκρινας σεαυτόν: ἔσθιε καὶ πῖνε καὶ συνουσίαζε καὶ ἀφόδευε καὶ ῥέγκε.","st":"2.20"},{"sp":"N","t":"τί δὲ σοὶ μέλει, πῶς οἱ ἄλλοι ὑπολήψονται περὶ τούτων, πότερον ὑγιῶς ἢ οὐχ ὑγιῶς; τί γὰρ σοὶ καὶ ἡμῖν; τῶν γὰρ προβάτων σοι μέλει, ὅτι παρέχει ἡμῖν αὑτὰ καρησόμενα καὶ ἀμελχθησόμενα καὶ τὸ τελευταῖον κατακοπησόμενα;","st":"2.20"},{"sp":"N","t":"οὐχὶ δ᾽ εὐκταῖον ἦν, εἰ ἐδύναντο οἱ ἄνθρωποι κατακηληθέντες καὶ ἐπᾳσθέντες ὑπὸ τῶν Στωικῶν ἀπονυστάζειν καὶ παρέχειν σοι καὶ τοῖς ὁμοίοις καρησομένους καὶ ἀμελχθησομένους ἑαυτούς;","st":"2.20"},{"sp":"N","t":"πρὸς γὰρ τοὺς Συνεπικουρείους ἔδει σε ταῦτα λέγειν, οὐχὶ δὲ πρὸς ἐκείνους † ἀποκρύπτεσθαι, πολὺ μάλιστ᾽ ἐκείνους πρὸ πάντων ἀναπείθειν, ὅτι φύσει κοινωνικοὶ γεγόναμεν, ὅτι ἀγαθὸν ἡ ἐγκράτεια, ἵνα σοι πάντα τηρῆται;","st":"2.20"},{"sp":"N","t":"ἢ πρός τινας μὲν δεῖ φυλάττειν ταύτην τὴν κοινωνίαν, πρός τινας δ᾽ οὔ; πρὸς τίνας οὖν δεῖ τηρεῖν; πρὸς τοὺς ἀντιτηροῦντας ἢ πρὸς τοὺς παραβατικῶς αὐτῆς ἔχοντας; καὶ τίνες παραβατικώτερον αὐτῆς ἔχουσιν ὑμῶν τῶν ταῦτα διειληφότων;","st":"2.20"},{"sp":"N","t":"τί οὖν ἦν τὸ ἐγεῖρον αὐτὸν ἐκ τῶν ὕπνων καὶ ἀναγκάζον γράφειν ἃ ἔγραφεν; τί γὰρ ἄλλο ἢ τὸ πάντων τῶν ἐν ἀνθρώποις ἰσχυρότατον, ἡ φύσις ἕλκουσα ἐπὶ τὸ αὑτῆς βούλημα ἄκοντα καὶ στένοντα;","st":"2.20"},{"sp":"N","t":"‘ὅτι γὰρ δοκεῖ σοι ταῦτα τὰ ἀκοινώνητα, γράψον αὐτὰ καὶ ἄλλοις ἀπόλιπε καὶ ἀγρύπνησον δι᾽ αὐτὰ καὶ αὐτὸς ἔργῳ κατήγορος γενοῦ τῶν σαυτοῦ δογμάτων.’","st":"2.20"},{"sp":"N","t":"εἶτα Ὀρέστην μὲν ὑπὸ Ἐρινύων ἐλαυνόμενον φῶμεν ἐκ τῶν ὕπνων ἐξεγείρεσθαι: τούτῳ δ᾽ οὐ χαλεπώτεραι αἱ Ἐρινύες καὶ Ποιναί; ἐξήγειρον καθεύδοντα καὶ οὐκ εἴων ἠρεμεῖν, ἀλλ᾽ ἠνάγκαζον ἐξαγγέλλειν τὰ αὑτοῦ κακὰ ὥσπερ τοὺς Γάλλους ἡ μανία καὶ ὁ οἶνος.","st":"2.20"},{"sp":"N","t":"οὕτως ἰσχυρόν τι καὶ ἀνίκητόν ἐστιν ἡ φύσις ἡ ἀνθρωπίνη. πῶς γὰρ δύναται ἄμπελος μὴ ἀμπελικῶς κινεῖσθαι, ἀλλ᾽ ἐλαικῶς, ἢ ἐλαία πάλιν μὴ ἐλαικῶς, ἀλλ᾽ ἀμπελικῶς; ἀμήχανον, ἀδιανόητον.","st":"2.20"},{"sp":"N","t":"οὐ τοίνυν οὐδ᾽ ἄνθρωπον οἷόν τε παντελῶς ἀπολέσαι τὰς κινήσεις τὰς ἀνθρωπικὰς καὶ οἱ ἀποκοπτόμενοι τάς γε προθυμίας τὰς τῶν ἀνδρῶν ἀποκόψασθαι οὐ δύνανται.","st":"2.20"},{"sp":"N","t":"οὕτως καὶ Ἐπίκουρος τὰ μὲν ἀνδρὸς πάντ᾽ ἀπεκόψατο καὶ τὰ οἰκοδεσπότου καὶ πολίτου καὶ φίλου, τὰς δὲ προθυμίας τὰς ἀνθρωπικὰς οὐκ ἀπεκόψατο: οὐ γὰρ ἠδύνατο, οὐ μᾶλλον ἢ οἱ ἀταλαίπωροι Ἀκαδημαικοὶ τὰς αἰσθήσεις τὰς αὑτῶν ἀποβαλεῖν ἢ ἀποτυφλῶσαι δύνανται καίτοι τοῦτο μάλιστα πάντων ἐσπουδακότες.","st":"2.20"},{"sp":"N","t":"† τίς ἢ ἀτυχίας; λαβών τις παρὰ τῆς φύσεως μέτρα καὶ κανόνας εἰς ἐπίγνωσιν τῆς ἀληθείας οὐ προσφιλοτεχνεῖ τούτοις προσθεῖναι καὶ προσεξεργάσασθαι τὰ λείποντα, ἀλλὰ πᾶν τοὐναντίον, εἴ τι καὶ ἔχει γνωριστικὸν τῆς ἀληθείας, ἐξαιρεῖν πειρᾶται καὶ ἀπολλύειν.","st":"2.20"},{"sp":"N","t":"τί λέγεις, φιλόσοφε; τὸ εὐσεβὲς καὶ τὸ ὅσιον ποῖόν τί σοι φαίνεται; ‘ἂν θέλῃς, κατασκευάσω ὅτι ἀγαθόν.’ ναὶ κατασκεύασον, ἵν᾽ οἱ πολῖται ἡμῶν ἐπιστραφέντες τιμῶσι τὸ θεῖον καὶ παύσωνταί ποτε ῥᾳθυμοῦντες περὶ τὰ μέγιστα. ‘ἔχεις οὖν τὰς κατασκευάς;’ ἔχω καὶ χάριν οἶδα.","st":"2.20"},{"sp":"N","t":"‘ἐπεὶ οὖν ταῦτά σοι λίαν ἀρέσκει, λάβε τὰ ἐναντία: ὅτι θεοὶ οὔτ᾽ εἰσίν, εἴ τε καὶ εἰσίν, οὐκ ἐπιμελοῦνται ἀνθρώπων οὐδὲ κοινόν τι ἡμῖν ἐστι πρὸς αὐτοὺς τό τ᾽ εὐσεβὲς τοῦτο καὶ ὅσιον παρὰ τοῖς πολλοῖς ἀνθρώποις λαλούμενον κατάψευσμά ἐστιν ἀλαζόνων ἀνθρώπων καὶ σοφιστῶν ἢ νὴ Δία νομοθετῶν εἰς φόβον καὶ ἐπίσχεσιν τῶν ἀδικούντων.’","st":"2.20"},{"sp":"N","t":"εὖ, φιλόσοφε: ὠφέλησας ἡμῶν τοὺς πολίτας, ἀνεκτήσω τοὺς νέους ῥέποντας ἤδη πρὸς καταφρόνησιν τῶν θείων.","st":"2.20"},{"sp":"N","t":"‘τί οὖν; οὐκ ἀρέσκει σοι ταῦτα; λάβε νῦν, πῶς ἡ δικαιοσύνη οὐδέν ἐστιν, πῶς ἡ αἰδὼς μωρία ἐστίν, πῶς πατὴρ οὐδέν ἐστιν, πῶς ὁ υἱὸς οὐδέν ἐστιν.’","st":"2.20"},{"sp":"N","t":"εὖ, φιλόσοφε: ἐπίμενε, πεῖθε τοὺς νέους, ἵνα πλείονας ἔχωμεν ταὐτά σοι πεπονθότας καὶ λέγοντας. ἐκ τούτων τῶν λόγων ηὐξήθησαν ἡμῖν αἱ εὐνομούμεναι πόλεις, Λακεδαίμων διὰ τούτους τοὺς λόγους ἐγένετο, Λυκοῦργος ταῦτα τὰ πείσματα ἐνεποίησεν αὐτοῖς διὰ τῶν νόμων αὐτοῦ καὶ τῆς παιδείας, ὅτι οὔτε τὸ δουλεύειν αἰσχρόν ἐστι μᾶλλον ἢ καλὸν οὔτε τὸ ἐλευθέρους εἶναι καλὸν μᾶλλον ἢ αἰσχρόν, οἱ ἐν Θερμοπύλαις ἀποθανόντες διὰ ταῦτα τὰ δόγματα ἀπέθανον, Ἀθηναῖοι δὲ τὴν πόλιν διὰ ποίους ἄλλους λόγους ἀπέλιπον;","st":"2.20"},{"sp":"N","t":"εἶτα οἱ λέγοντες ταῦτα γαμοῦσι καὶ παιδοποιοῦνται καὶ πολιτεύονται καὶ ἱερεῖς καθιστᾶσιν αὑτοὺς καὶ προφήτας. τίνων; τῶν οὐκ ὄντων: καὶ τὴν Πυθίαν ἀνακρίνουσιν αὐτοί, ἵνα τὰ ψευδῆ πύθωνται, καὶ ἄλλοις τοὺς χρησμοὺς ἐξηγοῦνται. ὦ μεγάλης ἀναισχυντίας καὶ γοητείας.","st":"2.20"},{"sp":"N","t":"ἄνθρωπε, τί ποιεῖς; αὐτὸς σεαυτὸν ἐξελέγχεις καθ᾽ ἡμέραν καὶ οὐ θέλεις ἀφεῖναι τὰ ψυχρὰ ταῦτα ἐπιχειρήματα; ἐσθίων ποῦ φέρεις τὴν χεῖρα; εἰς τὸ στόμα ἢ εἰς τὸν ὀφθαλμόν; λουόμενος ποῦ ἐμβαίνεις; πότε τὴν χύτραν εἶπες λουπάδα ἢ τὴν τορύνην ὀβελίσκον;","st":"2.20"},{"sp":"N","t":"εἴ τινος αὐτῶν δοῦλος ἤμην, εἰ καὶ ἔδει με καθ᾽ ἡμέραν ὑπ᾽ αὐτοῦ ἐκδέρεσθαι, ἐγὼ ἂν αὐτὸν ἐστρέβλουν. ‘βάλε ἐλάδιον, παιδάριον, εἰς τὸ βαλανεῖον.’ ἔβαλον ἂν γάριον καὶ ἀπελθὼν κατὰ τῆς κεφαλῆς αὐτοῦ κατέχεον. ‘τί τοῦτο;’ ‘φαντασία μοι ἐγένετο ἐλαίου ἀδιάκριτος, ὁμοιοτάτη, νὴ τὴν σὴν τύχην.’","st":"2.20"},{"sp":"N","t":"‘δὸς ὧδε τὴν πτισάνην.’ ἤνεγκα ἂν αὐτῷ γεμίσας παροψίδα ὀξογάρου. ‘οὐκ ᾔτησα τὴν πτισάνην;’ ‘ναὶ κύριε: τοῦτο πτισάνη ἐστίν.’ ‘τοῦτο οὐκ ἔστιν ὀξόγαρον;’ ‘τί μᾶλλον ἢ πτισάνη;’ ‘λάβε καὶ ὀσφράνθητι, λάβε καὶ γεῦσαι.’ ‘πόθεν οὖν οἶδας, εἰ αἱ αἰσθήσεις ἡμᾶς ψεύδονται;’","st":"2.20"},{"sp":"N","t":"τρεῖς, τέσσαρας τῶν συνδούλων εἰ ἔσχον ὁμονοοῦντας, ἀπάγξασθαι ἂν αὐτὸν ἐποίησα ῥηγνύμενον ἢ μεταθέσθαι. νῦν δ᾽ ἐντρυφῶσιν ἡμῖν τοῖς μὲν παρὰ τῆς φύσεως διδομένοις πᾶσι χρώμενοι, λόγῳ δ᾽ αὐτὰ ἀναιροῦντες.","st":"2.20"},{"sp":"N","t":"εὐχάριστοί γ᾽ ἄνθρωποι καὶ αἰδήμονες. εἰ μηδὲν ἄλλο καθ᾽ ἡμέραν ἄρτους ἐσθίοντες τολμῶσι λέγειν ὅτι ‘οὐκ οἴδαμεν, εἰ ἔστι τις Δημήτηρ ἢ Κόρη ἢ Πλούτων:’ ἵνα μὴ λέγω,","st":"2.20"},{"sp":"N","t":"ὅτι νυκτὸς καὶ ἡμέρας ἀπολαύοντες καὶ μεταβολῶν τοῦ ἔτους καὶ ἄστρων καὶ θαλάσσης καὶ γῆς καὶ τῆς παρ᾽ ἀνθρώπων συνεργείας ὑπ᾽ οὐδενὸς τούτων οὐδὲ κατὰ ποσὸν ἐπιστρέφονται, ἀλλὰ μόνον ἐξεμέσαι τὸ προβλημάτιον ζητοῦσι καὶ τὸν στόμαχον γυμνάσαντες ἀπελθεῖν εἰς βαλανεῖον.","st":"2.20"},{"sp":"N","t":"τί δ᾽ ἐροῦσι καὶ περὶ τίνων ἢ πρὸς τίνας καὶ τί ἔσται αὐτοῖς ἐκ τῶν λόγων τούτων, οὐδὲ κατὰ βραχὺ πεφροντίκασι: μή τι νέος εὐγενὴς ἀκούσας τῶν λόγων τούτων πάθῃ τι ὑπ᾽ αὐτῶν ἢ καὶ παθὼν πάντ᾽ ἀπολέσῃ τὰ τῆς εὐγενείας σπέρματα:","st":"2.20"},{"sp":"N","t":"μή τινι μοιχεύοντι ἀφορμὰς παράσχωμεν τοῦ ἀπαναισχυντῆσαι πρὸς τὰ γινόμενα: μή τις τῶν νοσφιζομένων τὰ δημόσια εὑρεσιλογίας τινὸς ἐπιλάβηται ἀπὸ τῶν λόγων τούτων: μή τις τῶν αὑτοῦ γονέων ἀμελῶν θράσος τι καὶ ἀπὸ τούτων προσλάβῃ. τί οὖν κατὰ σὲ ἀγαθὸν ἢ κακόν,","st":"2.20"},{"sp":"N","t":"αἰσχρὸν ἢ καλόν; ταῦτα ἢ ταῦτα; τί οὖν; ἔτι τούτων τις ἀντιλέγει τινὶ ἢ λόγον δίδωσιν ἢ λαμβάνει ἢ μεταπείθειν πειρᾶται;","st":"2.20"},{"sp":"N","t":"πολὺ νὴ Δία μᾶλλον τοὺς κιναίδους ἐλπίσαι τις ἂν μεταπείσειν ἢ τοὺς ἐπὶ τοσοῦτον ἀποκεκωφωμένους καὶ ἀποτετυφλωμένους. περὶ ἀνομολογίας. τῶν περὶ αὑτοὺς κακῶν τὰ μὲν ῥᾳδίως ὁμολογοῦσιν ἄνθρωποι, τὰ δ᾽ οὐ ῥᾳδίως. οὐδεὶς οὖν ὁμολογήσει ὅτι ἄφρων ἐστὶν ἢ ἀνόητος, ἀλλὰ πᾶν τοὐναντίον πάντων ἀκούσεις λεγόντων ‘ὤφελον ὡς φρένας ἔχω οὕτως καὶ τύχην εἶχον.’","st":"2.20"},{"sp":"N","t":"δειλοὺς δὲ ῥᾳδίως ἑαυτοὺς ὁμολογοῦσι καὶ λέγουσιν ‘ἐγὼ δειλότερός εἰμι, ὁμολογῶ: τὰ δ᾽ ἄλλ᾽ οὐχ εὑρήσεις με μωρὸν ἄνθρωπον.’","st":"2.21"},{"sp":"N","t":"ἀκρατῆ οὐ ῥᾳδίως ὁμολογήσει τις, ἄδικον οὐδ᾽ ὅλως, φθονερὸν οὐ πάνυ ἢ περίεργον, ἐλεήμονα οἱ πλεῖστοι.","st":"2.21"},{"sp":"N","t":"τί οὖν τὸ αἴτιον; τὸ μὲν κυριώτατον ἀνομολογία καὶ ταραχὴ ἐν τοῖς περὶ ἀγαθῶν καὶ κακῶν, ἄλλοις δ᾽ ἄλλα αἴτια καὶ σχεδὸν ὅσα ἂν αἰσχρὰ φαντάζωνται, ταῦτα οὐ πάνυ ὁμολογοῦσι:","st":"2.21"},{"sp":"N","t":"τὸ δὲ δειλὸν εἶναι εὐγνώμονος ἤθους φαντάζονται καὶ τὸ ἐλεήμονα, τὸ δ᾽ ἠλίθιον εἶναι παντελῶς ἀνδραπόδου: καὶ τὰ περὶ κοινωνίαν δὲ πλημμελήματα οὐ πάνυ προσίενται.","st":"2.21"},{"sp":"N","t":"ἐπὶ δὲ τῶν πλείστων ἁμαρτημάτων κατὰ τοῦτο μάλιστα φέρονται ἐπὶ τὸ ὁμολογεῖν αὐτά, ὅτι φαντάζονταί τι ἐν αὐτοῖς εἶναι ἀκούσιον καθάπερ ἐν τῷ δειλῷ καὶ ἐλεήμονι.","st":"2.21"},{"sp":"N","t":"κἂν ἀκρατῆ που παρομολογῇ τις αὑτόν, ἔρωτα προσέθηκεν, ὥστε συγγνωσθῆναι ὡς ἐπ᾽ ἀκουσίῳ. τὸ δ᾽ ἄδικον οὐδαμῶς φαντάζονται ἀκούσιον. ἔνι τι καὶ τῷ ζηλοτύπῳ, ὡς οἴονται, τοῦ ἀκουσίου: διὰ τοῦτο καὶ περὶ τούτου παρομολογοῦσιν.","st":"2.21"},{"sp":"N","t":"ἐν οὖν τοιούτοις ἀνθρώποις ἀναστρεφόμενον, οὕτως τεταραγμένοις, οὕτως οὐκ εἰδόσιν οὔθ᾽ ὅ τι λέγουσιν οὔθ᾽ ὅ τι ἔχουσιν κακὸν ἢ εἰ ἔχουσιν ἢ παρὰ τί ἔχουσιν ἢ πῶς παύσονται αὐτῶν, καὶ αὐτὸν οἶμαι ἐφιστάνειν ἄξιον συνεχὲς","st":"2.21"},{"sp":"N","t":"‘μή που καὶ αὐτὸς εἷς εἰμι ἐκείνων; τίνα φαντασίαν ἔχω περὶ ἐμαυτοῦ; πῶς ἐμαυτῷ χρῶμαι; μή τι καὶ αὐτὸς ὡς φρονίμῳ, μή τι καὶ αὐτὸς ὡς ἐγκρατεῖ; μὴ καὶ αὐτὸς λέγω ποτὲ ταῦτα, ὅτι εἰς τὸ ἐπιὸν πεπαίδευμαι;","st":"2.21"},{"sp":"N","t":"ἔχω ἣν δεῖ συναίσθησιν τὸν μηδὲν εἰδότα, ὅτι οὐδὲν οἶδα; ἔρχομαι πρὸς τὸν διδάσκαλον ὡς ἐπὶ τὰ χρηστήρια πείθεσθαι παρεσκευασμένος; ἢ καὶ αὐτὸς κορύζης μεστὸς εἰς τὴν σχολὴν εἰσέρχομαι μόνην τὴν ἱστορίαν μαθησόμενος καὶ τὰ βιβλία νοήσων, ἃ πρότερον οὐκ ἐνόουν, ἂν δ᾽ οὕτως τύχῃ, καὶ ἄλλοις ἐξηγησόμενος;’","st":"2.21"},{"sp":"N","t":"ἄνθρωπ᾽, ἐν οἴκῳ διαπεπύκτευκας τῷ δουλαρίῳ, τὴν οἰκίαν ἀνάστατον πεποίηκας, τοὺς γείτονας συντετάραχας: καὶ ἔρχῃ μοι καταστολὰς ποιήσας ὡς σοφὸς καὶ καθήμενος κρίνεις, πῶς ἐξηγησάμην τὴν λέξιν, πῶς τί ποτ᾽ ἐφλυάρησα τὰ ἐπελθόντα μοι;","st":"2.21"},{"sp":"N","t":"φθονῶν ἐλήλυθας, τεταπεινωμένος, ὅτι σοι ἐξ οἴκου φέρεται οὐδέν, καὶ κάθῃ μεταξὺ λεγομένων τῶν λόγων αὐτὸς οὐδὲν ἄλλο ἐνθυμούμενος ἢ πῶς ὁ πατὴρ τὰ πρός σε ἢ πῶς ὁ ἀδελφός;","st":"2.21"},{"sp":"N","t":"‘τί λέγουσιν οἱ ἐκεῖ ἄνθρωποι περὶ ἐμοῦ; νῦν οἴονταί με προκόπτειν καὶ λέγουσιν ὅτι ‘ἥξει ἐκεῖνος πάντα εἰδώς’","st":"2.21"},{"sp":"N","t":"ἤθελόν πώς ποτε πάντα μαθὼν ἐπανελθεῖν, ἀλλὰ πολλοῦ πόνου χρεία καὶ οὐδεὶς οὐδὲν πέμπει καὶ ἐν Νικοπόλει σαπρῶς λούει τὰ βαλανεῖα καὶ ἐν οἴκῳ κακῶς καὶ ὧδε κακῶς.’ εἶτα λέγουσιν","st":"2.21"},{"sp":"N","t":"‘οὐδεὶς ὠφελεῖται ἐκ τῆς σχολῆς.’ τίς γὰρ ἔρχεται εἰς σχολήν, τίς γάρ, ὡς θεραπευθησόμενος; τίς ὡς παρέξων αὑτοῦ τὰ δόγματα ἐκκαθαρθησόμενα, τίς συναισθησόμενος τίνων δεῖται;","st":"2.21"},{"sp":"N","t":"τί οὖν θαυμάζετ᾽, εἰ ἃ φέρετ᾽ εἰς τὴν σχολήν, αὐτὰ ταῦτα ἀποφέρετε πάλιν; οὐ γὰρ ὡς ἀποθησόμενοι ἢ ἐπανορθώσοντες ἢ ἄλλ᾽ ἀντ᾽ αὐτῶν ληψόμενοι ἔρχεσθε.","st":"2.21"},{"sp":"N","t":"πόθεν; οὐδ᾽ ἐγγύς. ἐκεῖνο γοῦν βλέπετε μᾶλλον, εἰ ἐφ᾽ ὃ ἔρχεσθε τοῦτο ὑμῖν γίνεται. θέλετε λαλεῖν περὶ τῶν θεωρημάτων. τί οὖν; οὐ φλυαρότεροι γίνεσθε; οὐχὶ δὲ παρέχει τινὰ ὕλην ὑμῖν πρὸς τὸ ἐπιδείκνυσθαι τὰ θεωρημάτια; οὐ συλλογισμοὺς ἀναλύετε, μεταπίπτοντας; οὐκ ἐφοδεύετε Ψευδομένου λήμματα, ὑποθετικούς; τί οὖν ἔτι ἀγανακτεῖτε εἰ ἐφ᾽ ἃ πάρεστε, ταῦτα λαμβάνετε;","st":"2.21"},{"sp":"N","t":"‘ναί: ἀλλ᾽ ἂν ἀποθάνῃ μου τὸ παιδίον ἢ ὁ ἀδελφὸς ἢ ἐμὲ ἀποθνῄσκειν δέῃ ἢ στρεβλοῦσθαι, τί με τὰ τ","st":"2.21"},{"sp":"N","t":"οιαῦτα ὠφελήσει;’ μὴ γὰρ ἐπὶ τοῦτο ἦλθες, μὴ γὰρ τούτου ἕνεκά μοι παρακάθησαι, μὴ γὰρ διὰ τοῦτό ποτε λύχνον ἧψας ἢ ἠγρύπνησας; ἢ εἰς τὸν περίπατον ἐξελθὼν προέβαλές ποτε σαυτῷ φαντασίαν τινὰ ἀντὶ συλλογισμοῦ καὶ ταύτην κοινῇ ἐφωδεύσατε;","st":"2.21"},{"sp":"N","t":"ποῦ ποτε; εἶτα λέγετε ‘ἄχρηστα τὰ θεωρήματα.’ τίσιν; τοῖς οὐχ ὡς δεῖ χρωμένοις. τὰ γὰρ κολλύρια οὐκ ἄχρηστα τοῖς ὅτε δεῖ καὶ ὡς δεῖ ἐγχριομένοις, τὰ μαλάγματα δ᾽ οὐκ ἄχρηστα, οἱ ἁλτῆρες οὐκ ἄχρηστοι, ἀλλὰ τισὶν ἄχρηστοι, τισὶν πάλιν χρήσιμοι.","st":"2.21"},{"sp":"N","t":"ἄν μου πυνθάνῃ νῦν ‘χρήσιμοί εἰσιν οἱ συλλογισμοί;’ ἐρῶ σοι ὅτι χρήσιμοι, κἂν θέλῃς, ἀποδείξω, πῶς. ‘ἐμὲ οὖν τι ὠφελήκασιν;’ ἄνθρωπε, μὴ γὰρ ἐπύθου, εἰ σοὶ χρήσιμοι, ἀλλὰ καθόλου;","st":"2.21"},{"sp":"N","t":"πυθέσθω μου καὶ ὁ δυσεντερικός, εἰ χρήσιμον ὄξος, ἐρῶ ὅτι χρήσιμον. ‘ἐμοὶ οὖν χρήσιμον;’ ἐρῶ ‘οὔ.’ ζήτησον πρῶτον σταλῆναί σου τὸ ῥεῦμα, τὰ ἑλκύδρια ἀπουλωθῆναι. καὶ ὑμεῖς, ἄνδρες, τὰ ἕλκη πρῶτον θεραπεύετε, τὰ ῥεύματα ἐπιστήσατε, ἠρεμήσατε τῇ διανοίᾳ, ἀπερίσπαστον αὐτὴν ἐνέγκατε εἰς τὴν σχολήν: καὶ γνώσεσθε οἵαν ἰσχὺν ὁ λόγος ἔχει. περὶ φιλίας. περὶ ἅ τις ἐσπούδακεν, φιλεῖ ταῦτα εἰκότως. μή τι οὖν περὶ τὰ κακὰ ἐσπουδάκασιν οἱ ἄνθρωποι; οὐδαμῶς. ἀλλὰ μή τι περὶ τὰ μηδὲν πρὸς αὐτούς; οὐδὲ περὶ ταῦτα.","st":"2.21"},{"sp":"N","t":"ὑπολείπεται τοίνυν περὶ μόνα τὰ ἀγαθὰ ἐσπουδακέναι αὐτούς: εἰ δ᾽ ἐσπουδακέναι, καὶ φιλεῖν ταῦτα.","st":"2.22"},{"sp":"N","t":"ὅστις οὖν ἀγαθῶν ἐπιστήμων ἐστίν, οὗτος ἂν καὶ φιλεῖν εἰδείη: ὁ δὲ μὴ δυνάμενος διακρῖναι τὰ ἀγαθὰ ἀπὸ τῶν κακῶν καὶ τὰ οὐδέτερα ἀπ᾽ ἀμφοτέρων πῶς ἂν ἔτι οὗτος φιλεῖν δύναιτο; τοῦ φρονίμου τοίνυν ἐστὶ μόνου τὸ φιλεῖν.","st":"2.22"},{"sp":"N","t":"καὶ πῶς; φησίν: ἐγὼ γὰρ ἄφρων ὢν ὅμως φιλῶ μου τὸ παιδίον.","st":"2.22"},{"sp":"N","t":"— θαυμάζω μὲν νὴ τοὺς θεούς, πῶς καὶ τὸ πρῶτον ὡμολόγηκας ἄφρονα εἶναι σεαυτόν. τί γάρ σοι λείπει; οὐ χρῇ αἰσθήσει, οὐ φαντασίας διακρίνεις, οὐ τροφὰς προσφέρῃ τὰς ἐπιτηδείους τῷ σώματι, οὐ σκέπην, οὐκ οἴκησιν;","st":"2.22"},{"sp":"N","t":"πόθεν οὖν ὁμολογεῖς ἄφρων εἶναι; ὅτι νὴ Δία πολλάκις ἐξίστασαι ὑπὸ τῶν φαντασιῶν καὶ ταράττῃ καὶ ἡττῶσίν σε αἱ πιθανότητες αὐτῶν: καὶ ποτὲ μὲν ταῦτα ἀγαθὰ ὑπολαμβάνεις, εἶτα ἐκεῖνα αὐτὰ κακά, ὕστερον δ᾽ οὐδέτερα: καὶ ὅλως λυπῇ, φοβῇ, φθονεῖς, ταράσσῃ, μεταβάλλῃ: διὰ ταῦτα ὁμολογεῖς ἄφρων εἶναι.","st":"2.22"},{"sp":"N","t":"ἐν δὲ τῷ φιλεῖν οὐ μεταβάλλῃ; ἀλλὰ πλοῦτον μὲν καὶ ἡδονὴν καὶ ἁπλῶς αὐτὰ τὰ πράγματα ποτὲ μὲν ἀγαθὰ ὑπολαμβάνεις εἶναι, ποτὲ δὲ κακά: ἀνθρώπους δὲ τοὺς αὐτοὺς οὐχὶ ποτὲ μὲν ἀγαθούς, ποτὲ δὲ κακοὺς καὶ ποτὲ μὲν οἰκείως ἔχεις, ποτὲ δ᾽ ἐχθρῶς αὐτοῖς καὶ ποτὲ μὲν ἐπαινεῖς, ποτὲ δὲ ψέγεις; — ναὶ καὶ ταῦτα πάσχω.","st":"2.22"},{"sp":"N","t":"— τί οὖν; ὁ ἐξηπατημένος περί τινος δοκεῖ σοι φίλος εἶναι αὐτοῦ; — οὐ πάνυ. — οὐδ᾽ ὁ μεταπτώτως ἑλόμενος αὐτὸν εἶναι εὔνους αὐτῷ; — οὐδ᾽ οὗτος. — ὁ δὲ νῦν λοιδορῶν μέν τινα, ὕστερον δὲ θαυμάζων;","st":"2.22"},{"sp":"N","t":"— οὐδ᾽ οὗτος. — τί οὖν; κυνάρια οὐδέποτ᾽ εἶδες σαίνοντα καὶ προσπαίζοντα ἀλλήλοις, ἵν᾽ εἴπῃς ‘οὐδὲν φιλικώτερον;’ ἀλλ᾽ ὅπως ἴδῃς, τί ἐστι φιλία, βάλε κρέας εἰς μέσον καὶ γνώσῃ.","st":"2.22"},{"sp":"N","t":"βάλε καὶ σοῦ καὶ τοῦ παιδίου μέσον ἀγρίδιον καὶ γνώσῃ, πῶς σὲ τὸ παιδίον ταχέως κατορύξαι θέλει καὶ σὺ τὸ παιδίον εὔχῃ ἀποθανεῖν. εἶτα σὺ πάλιν ‘οἷον ἐξέθρεψα τεκνίον: πάλαι ἐκφέρει.’","st":"2.22"},{"sp":"N","t":"βάλε κορασίδιον κομψὸν καὶ αὐτὸ ὁ γέρων φίλει κἀκεῖνος ὁ νέος: ἂν δέ, δοξάριον. ἂν δὲ κινδυνεῦσαι δέῃ, ἐρεῖς τὰς φωνὰς τὰς τοῦ Ἀδμήτου πατρός: χαίρεις ὁρῶν φῶς, πατέρα δ᾽ οὐ χαίρειν δοκεῖς; θέλεις βλέπειν φῶς, πατέρα δ᾽ οὐ θέλειν δοκεῖς; οἴει ὅτι ἐκεῖνος οὐκ ἐφίλει τὸ ἴδιον παιδίον,","st":"2.22"},{"sp":"N","t":"ὅτε μικρὸν ἦν, οὐδὲ πυρέσσοντος αὐτοῦ ἠγωνία οὐδ᾽ ἔλεγεν πολλάκις ὅτι ‘ὤφελον ἐγὼ μᾶλλον ἐπύρεσσον;’ εἶτα ἐλθόντος τοῦ πράγματος καὶ ἐγγίσαντος ὅρα οἵας φωνὰς ἀφιᾶσιν.","st":"2.22"},{"sp":"N","t":"ὁ Ἐτεοκλῆς καὶ ὁ Πολυνείκης οὐκ ἦσαν ἐκ τῆς αὐτῆς μητρὸς καὶ τοῦ αὐτοῦ πατρός; οὐκ ἦσαν συντεθραμμένοι, συμβεβιωκότες, συμπεπωκότες, συγκεκοιμημένοι, πολλάκις ἀλλήλους καταπεφιληκότες; ὥστ᾽ εἴ τις οἶμαι εἶδεν αὐτούς, κατεγέλασεν ἂν τῶν φιλοσόφων ἐφ᾽ οἷς περὶ φιλίας παραδοξολογοῦσιν.","st":"2.22"},{"sp":"N","t":"ἀλλ᾽ ἐμπεσούσης εἰς τὸ μέσον ὥσπερ κρέως τῆς τυραννίδος ὅρα οἷα λέγουσι: ποῦ ποτε στήσῃ πρὸ πύργων; — ὡς τί μ᾽ † ἐρωτᾷς τῷδ᾽ †; — ἀντιτάξομαι κτενῶν σε. — κἀμὲ τοῦδ᾽ ἔρως ἔχει. καὶ εὔχονται εὐχὰς τοιάσδε.","st":"2.22"},{"sp":"N","t":"καθόλου γὰρ — μὴ ἐξαπατᾶσθε — πᾶν ζῷον οὐδενὶ οὕτως ᾠκείωται ὡς τῷ ἰδίῳ συμφέροντι. ὅ τι ἂν οὖν πρὸς τοῦτο φαίνηται αὐτῷ ἐμποδίζειν, ἄν τ᾽ ἀδελφὸς ᾖ τοῦτο ἄν τε πατὴρ ἄν τε τέκνον ἄν τ᾽ ἐρώμενος ἄν τ᾽ ἐραστής, μισεῖ, προβάλλεται, καταρᾶται.","st":"2.22"},{"sp":"N","t":"οὐδὲν γὰρ οὕτως φιλεῖν πέφυκεν ὡς τὸ αὑτοῦ συμφέρον: τοῦτο πατὴρ καὶ ἀδελφὸς καὶ συγγενεῖς καὶ πατρὶς καὶ θεός. ὅταν γοῦν εἰς τοῦτο ἐμποδίζειν ἡμῖν οἱ θεοὶ δοκῶσιν,","st":"2.22"},{"sp":"N","t":"κἀκείνους λοιδοροῦμεν καὶ τὰ ἱδρύματα αὐτῶν καταστρέφομεν καὶ τοὺς ναοὺς ἐμπιπρῶμεν, ὥσπερ Ἀλέξανδρος ἐκέλευσεν ἐμπρησθῆναι τὰ Ἀσκλήπεια ἀποθανόντος τοῦ ἐρωμένου.","st":"2.22"},{"sp":"N","t":"διὰ τοῦτο ἂν μὲν ἐν ταὐτῷ τις θῇ τὸ συμφέρον καὶ τὸ ὅσιον καὶ τὸ καλὸν καὶ πατρίδα καὶ γονεῖς καὶ φίλους, σῴζεται ταῦτα πάντα: ἂν δ᾽ ἀλλαχοῦ μὲν τὸ συμφέρον, ἀλλαχοῦ δὲ τοὺς φίλους καὶ τὴν πατρίδα καὶ τοὺς συγγενεῖς καὶ αὐτὸ τὸ δίκαιον, οἴχεται πάντα ταῦτα καταβαρούμενα ὑπὸ τοῦ συμφέροντος.","st":"2.22"},{"sp":"N","t":"ὅπου γὰρ ἂν τὸ ‘ἐγὼ’ καὶ τὸ ‘ἐμόν,’ ἐκεῖ ἀνάγκη ῥέπειν τὸ ζῷον: εἰ ἐν σαρκί, ἐκεῖ τὸ κυριεῦον εἶναι: εἰ ἐν προαιρέσει, ἐκεῖνο εἶναι: εἰ ἐν τοῖς ἐκτός, ἐκεῖνο.","st":"2.22"},{"sp":"N","t":"εἰ τοίνυν ἐκεῖ εἰμι ἐγώ, ὅπου ἡ προαίρεσις, οὕτως μόνως καὶ φίλος ἔσομαι οἷος δεῖ καὶ υἱὸς καὶ πατήρ. τοῦτο γάρ μοι συνοίσει τηρεῖν τὸν πιστόν, τὸν αἰδήμονα, τὸν ἀνεκτικόν, τὸν ἀφεκτικὸν καὶ συνεργητικόν, φυλάσσειν τὰς σχέσεις.","st":"2.22"},{"sp":"N","t":"ἂν δ᾽ ἀλλαχοῦ μὲν ἐμαυτὸν θῶ, ἀλλαχοῦ δὲ τὸ καλόν, οὕτως ἰσχυρὸς γίνεται ὁ Ἐπικούρου λόγος, ἀποφαίνων ἢ μηδὲν εἶναι τὸ καλὸν ἢ εἰ ἄρα τὸ ἔνδοξον.","st":"2.22"},{"sp":"N","t":"διὰ ταύτην τὴν ἄγνοιαν καὶ Ἀθηναῖοι καὶ Λακεδαιμόνιοι διεφέροντο καὶ Θηβαῖοι πρὸς ἀμφοτέρους καὶ μέγας βασιλεὺς πρὸς τὴν Ἑλλάδα καὶ Μακεδόνες πρὸς ἀμφοτέρους καὶ νῦν Ῥωμαῖοι πρὸς Γέτας καὶ ἔτι πρότερον τὰ ἐν Ἰλίῳ διὰ ταῦτα ἐγένετο.","st":"2.22"},{"sp":"N","t":"ὁ Ἀλέξανδρος τοῦ Μενελάου ξένος ἦν, καὶ εἴ τις αὐτοὺς εἶδεν φιλοφρονουμένους ἀλλήλους, ἠπίστησεν ἂν τῷ λέγοντι οὐκ εἶναι φίλους αὐτούς. ἀλλ᾽ ἐβλήθη εἰς τὸ μέσον μερίδιον, κομψὸν γυναικάριον, καὶ περὶ αὐτοῦ πόλεμος.","st":"2.22"},{"sp":"N","t":"καὶ νῦν ὅταν ἴδῃς φίλους, ἀδελφοὺς ὁμονοεῖν δοκοῦντας, μὴ αὐτόθεν ἀποφήνῃ περὶ τῆς φιλίας τι αὐτῶν μηδ᾽ ἂν ὀμνύωσιν μηδ᾽ ἂν ἀδυνάτως ἔχειν λέγωσιν ἀπηλλάχθαι ἀλλήλων.","st":"2.22"},{"sp":"N","t":"οὐκ ἔστι πιστὸν τὸ τοῦ φαύλου ἡγεμονικόν: ἀβέβαιόν ἐστιν, ἄκριτον, ἄλλοθ᾽ ὑπ᾽ ἄλλης φαντασίας νικώμενον.","st":"2.22"},{"sp":"N","t":"ἀλλ᾽ ἐξέτασον μὴ ταῦθ᾽ ἃ οἱ ἄλλοι, εἰ ἐκ τῶν αὐτῶν γονέων καὶ ὁμοῦ ἀνατεθραμμένοι καὶ ὑπὸ τῷ αὐτῷ παιδαγωγῷ, ἀλλ᾽ ἐκεῖνο μόνον, ποῦ τὸ συμφέρον αὐτοῖς τίθενται, πότερον ἐκτὸς ἢ ἐν προαιρέσει.","st":"2.22"},{"sp":"N","t":"ἂν ἐκτός, μὴ εἴπῃς φίλους οὐ μᾶλλον ἢ πιστοὺς ἢ βεβαίους ἢ θαρραλέους ἢ ἐλευθέρους, ἀλλὰ μηδ᾽ ἀνθρώπους, εἰ νοῦν ἔχεις.","st":"2.22"},{"sp":"N","t":"οὐ γὰρ ἀνθρωπικὸν δόγμα ἐστὶ τὸ ποιοῦν δάκνειν ἀλλήλους καὶ λοιδορεῖσθαι καὶ τὰς ἐρημίας καταλαμβάνειν ἢ τὰς ἀγορὰς † ὡς τὰ ὄρη καὶ ἐν τοῖς δικαστηρίοις ἀποδείκνυσθαι τὰ λῃστῶν: οὐδὲ τὸ ἀκρατεῖς καὶ μοιχοὺς καὶ φθορεῖς ἀπεργαζόμενον οὐδ᾽ ὅσ᾽ ἄλλα πλημμελοῦσιν ἄνθρωποι κατ᾽ ἀλλήλων δι᾽ ἓν καὶ μόνον τοῦτο δόγμα, τὸ ἐν τοῖς ἀπροαιρέτοις τίθεσθαι αὑτοὺς καὶ τὰ ἑαυτῶν.","st":"2.22"},{"sp":"N","t":"ἂν δ᾽ ἀκούσῃς, ὅτι ταῖς ἀληθείαις οὗτοι οἱ ἄνθρωποι ἐκεῖ μόνον οἴονται τὸ ἀγαθὸν ὅπου προαίρεσις, ὅπου χρῆσις ὀρθὴ φαντασιῶν, μηκέτι πολυπραγμονήσῃς μήτ᾽ εἰ υἱὸς καὶ πατήρ ἐστι μήτ᾽ εἰ ἀδελφοὶ μήτ᾽ εἰ πολὺν χρόνον συμπεφοιτηκότες καὶ ἑταῖροι, ἀλλὰ μόνον αὐτὸ τοῦτο γνοὺς θαρρῶν ἀποφαίνου, ὅτι φίλοι, ὥσπερ ὅτι πιστοί, ὅτι δίκαιοι.","st":"2.22"},{"sp":"N","t":"ποῦ γὰρ ἀλλαχοῦ φιλία ἢ ὅπου πίστις, ὅπου αἰδώς, ὅπου δόσις τοῦ καλοῦ, τῶν δ᾽ ἄλλων οὐδενός;","st":"2.22"},{"sp":"N","t":"‘ἀλλὰ τεθεράπευκέ με τοσούτῳ χρόνῳ: καὶ οὐκ ἐφίλει με;’ πόθεν οἶδας, ἀνδράποδον, εἰ οὕτως τεθεράπευκεν ὡς τὰ ὑποδήματα σπογγίζει τὰ ἑαυτοῦ, ὡς τὸ κτῆνος; πόθεν οἶδας, εἰ τὴν χρείαν σ᾽ ἀποβαλόντα τὴν τοῦ σκευαρίου ῥίψει ὡς κατεαγὸς πινάκιον;","st":"2.22"},{"sp":"N","t":"‘ἀλλὰ γυνή μου ἐστὶ καὶ τοσούτῳ χρόνῳ συμβεβιώκαμεν.’ πόσῳ δ᾽ ἡ Ἐριφύλη μετὰ τοῦ Ἀμφιαράου καὶ τέκνων μήτηρ καὶ πολλῶν;","st":"2.22"},{"sp":"N","t":"ἀλλ᾽ ὅρμος ἦλθεν εἰς τὸ μέσον. τί δ᾽ ἐστὶν ὅρμος; τὸ δόγμα τὸ περὶ τῶν τοιούτων. ἐκεῖνο ἦν τὸ θηριῶδες, ἐκεῖνο τὸ διακόπτον τὴν φιλίαν, τὸ οὐκ ἐῶν εἶναι γυναῖκα γαμετήν, τὴν μητέρα μητέρα.","st":"2.22"},{"sp":"N","t":"καὶ ὑμῶν ὅστις ἐσπούδακεν ἢ αὐτός τινι εἶναι φίλος ἢ ἄλλον κτήσασθαι φίλον, ταῦτα τὰ δόγματα ἐκκοπτέτω, ταῦτα μισησάτω, ταῦτα ἐξελασάτω ἐκ τῆς ψυχῆς τῆς ἑαυτοῦ.","st":"2.22"},{"sp":"N","t":"καὶ οὕτως ἔσται πρῶτον μὲν αὐτὸς ἑαυτῷ μὴ λοιδορούμενος, μὴ μαχόμενος, μὴ μετανοῶν, μὴ βασανίζων ἑαυτόν:","st":"2.22"},{"sp":"N","t":"ἔπειτα καὶ ἑτέρῳ, τῷ μὲν ὁμοίῳ παντὶ ἁπλῶς, τοῦ δ᾽ ἀνομοίου ἀνεκτικός, πρᾷος πρὸς αὐτόν, ἥμερος, συγγνωμονικὸς ὡς πρὸς ἀγνοοῦντα, ὡς πρὸς διαπίπτοντα περὶ τῶν μεγίστων: οὐδενὶ χαλεπός, ἅτ᾽ εἰδὼς ἀκριβῶς τὸ τοῦ Πλάτωνος, ὅτι πᾶσα ψυχὴ ἄκουσα στέρεται τῆς ἀληθείας.","st":"2.22"},{"sp":"N","t":"εἰ δὲ μή, τὰ μὲν ἄλλα πράξετε πάντα ὅσα οἱ φίλοι καὶ συμπιεῖσθε καὶ συσκηνήσετε καὶ συμπλεύσετε καὶ ἐκ τῶν αὐτῶν γεγενημένοι ἔσεσθε: καὶ γὰρ οἱ ὄφεις: φίλοι δ᾽ οὔτ᾽ ἐκεῖνοι οὔθ᾽ ὑμεῖς, μέχρις ἂν ἔχητε τὰ θηριώδη ταῦτα καὶ μιαρὰ δόγματα. περὶ τῆς τοῦ λέγειν δυνάμεως. βιβλίον πᾶς ἂν ἥδιον ἀναγνῴη καὶ ῥᾷον τὸ εὐσημοτέροις γράμμασι γεγραμμένον οὐκοῦν καὶ λόγους πᾶς ἄν τις ῥᾷον ἀκούσειε τοὺς εὐσχήμοσιν ἅμα καὶ εὐπρεπέσιν ὀνόμασι σεσημασμένους.","st":"2.22"},{"sp":"N","t":"οὐκ ἄρα τοῦτο ῥητέον, ὡς οὐδεμία δύναμίς ἐστιν ἀπαγγελτική: τοῦτο γὰρ ἅμα μὲν ἀσεβοῦς ἐστιν ἀνθρώπου, ἅμα δὲ δειλοῦ. ἀσεβοῦς μέν, ὅτι τὰς παρὰ τοῦ θεοῦ χάριτας ἀτιμάζει, ὥσπερ εἰ ἀνῄρει τὴν εὐχρηστίαν τῆς ὁρατικῆς ἢ τῆς ἀκουστικῆς δυνάμεως ἢ αὐτῆς τῆς φωνητικῆς.","st":"2.23"},{"sp":"N","t":"εἰκῇ οὖν σοι ὁ θεὸς ὀφθαλμοὺς ἔδωκεν, εἰκῇ πνεῦμα ἐνεκέρασεν αὐτοῖς οὕτως ἰσχυρὸν καὶ φιλότεχνον, ὥστε μακρὰν ἐξικνούμενον ἀναμάσσεσθαι τοὺς τύπους τῶν ὁρωμένων;","st":"2.23"},{"sp":"N","t":"καὶ ποῖος ἄγγελος οὕτως ὠκὺς καὶ ἐπιμελής; εἰκῇ δὲ καὶ τὸν μεταξὺ ἀέρα οὕτως ἐνεργὸν ἐποίησεν καὶ ἔντονον, ὥστε δι᾽ αὐτοῦ τεινομένου πως διικνεῖσθαι τὴν ὅρασιν; εἰκῇ δὲ φῶς ἐποίησεν, οὗ μὴ παρόντος οὐδενὸς τῶν ἄλλων ὄφελος ἦν;","st":"2.23"},{"sp":"N","t":"ἄνθρωπε, μήτ᾽ ἀχάριστος ἴσθι μήτε πάλιν ἀμνήμων τῶν κρεισσόνων, ἀλλ᾽ ὑπὲρ μὲν τοῦ ὁρᾶν καὶ ἀκούειν καὶ νὴ Δία ὑπὲρ αὐτοῦ τοῦ ζῆν καὶ τῶν συνεργῶν πρὸς αὐτό, ὑπὲρ καρπῶν ξηρῶν, ὑπὲρ οἴνου, ὑπὲρ ἐλαίου εὐχαρίστει τῷ θεῷ:","st":"2.23"},{"sp":"N","t":"μέμνησο δ᾽ ὅτι ἄλλο τί σοι δέδωκεν κρεῖττον ἁπάντων τούτων, τὸ χρησόμενον αὐτοῖς, τὸ δοκιμάσον, τὸ τὴν ἀξίαν ἑκάστου λογιούμενον.","st":"2.23"},{"sp":"N","t":"τί γάρ ἐστι τὸ ἀποφαινόμενον ὑπὲρ ἑκάστης τούτων τῶν δυνάμεων, πόσου τις ἀξία ἐστὶν αὐτῶν; μή τι αὐτὴ ἑκάστη ἡ δύναμις; μή τι τῆς ὁρατικῆς ποτ᾽ ἤκουσας λεγούσης τι περὶ ἑαυτῆς, μή τι τῆς ἀκουστικῆς; μή τι πυρῶν; μή τι κριθῶν; μή τι ἵππου; μή τι κυνός; ἀλλ᾽ ὡς διάκονοι καὶ δοῦλαι τεταγμέναι εἰσὶν ὑπηρετεῖν τῇ χρηστικῇ τῶν φαντασιῶν.","st":"2.23"},{"sp":"N","t":"κἂν πύθῃ, πόσου ἕκαστον ἄξιόν ἐστιν, τίνος πυνθάνῃ; τίς σοι ἀποκρίνεται; πῶς οὖν δύναταί τις ἄλλη δύναμις κρείσσων εἶναι ταύτης, ἣ καὶ ταῖς λοιπαῖς διακόνοις χρῆται καὶ δοκιμάζει αὐτὴ ἕκαστα καὶ ἀποφαίνεται;","st":"2.23"},{"sp":"N","t":"τίς γὰρ ἐκείνων οἶδεν, τίς ἐστιν αὐτὴ καὶ πόσου ἀξία; τίς ἐκείνων οἶδεν, ὁπότε δεῖ χρῆσθαι αὐτῇ καὶ πότε μή; τίς ἐστιν ἡ ἀνοίγουσα καὶ κλείουσα τοὺς ὀφθαλμοὺς καὶ ἀφ᾽ ὧν δεῖ ἀποστρέφουσα, τοῖς δὲ προσάγουσα; ἡ ὁρατική; οὔ, ἀλλ᾽ ἡ προαιρετική. τίς ἡ τὰ ὦτα ἐπικλείουσα καὶ ἀνοίγουσα;","st":"2.23"},{"sp":"N","t":"τίς, καθ᾽ ἣν περίεργοι καὶ πευθῆνες ἢ πάλιν ἀκίνητοι ὑπὸ λόγου; ἡ ἀκουστική;","st":"2.23"},{"sp":"N","t":"οὐκ ἄλλη ἢ ἡ προαιρετικὴ δύναμις. εἶτ᾽ αὐτὴ ἰδοῦσα, ὅτι ἐν τυφλαῖς καὶ κωφαῖς ταῖς ἄλλαις ἁπάσαις δυνάμεσίν ἐστι μηδέ τι ἄλλο συνορᾶν δυναμέναις πλὴν αὐτὰ ἐκεῖνα τὰ ἔργα, ἐφ᾽ οἷς τεταγμέναι εἰσὶ διακονεῖν ταύτῃ καὶ ὑπηρετεῖν, αὐτὴ δὲ μόνη ὀξὺ βλέπει καὶ τάς τ᾽ ἄλλας καθορᾷ, πόσου ἑκάστη ἀξία, καὶ αὑτήν, μέλλει ἡμῖν ἄλλο τι ἀποφαίνεσθαι τὸ κράτιστον εἶναι ἢ αὐτήν;","st":"2.23"},{"sp":"N","t":"καὶ τί ποιεῖ ἄλλο ὀφθαλμὸς ἀνοιχθεὶς ἢ ὁρᾷ; εἰ δὲ δεῖ τὴν τοῦ τινος ἰδεῖν γυναῖκα καὶ πῶς, τίς λέγει;","st":"2.23"},{"sp":"N","t":"ἡ προαιρετική. εἰ δὲ δεῖ πιστεῦσαι τοῖς λεχθεῖσιν ἢ ἀπιστῆσαι καὶ πιστεύσαντα ἐρεθισθῆναι ἢ μή, τίς λέγει;","st":"2.23"},{"sp":"N","t":"οὐχ ἡ προαιρετική; ἡ δὲ φραστικὴ αὕτη καὶ καλλωπιστικὴ τῶν ὀνομάτων, εἴ τις ἄρα ἰδία δύναμις, τί ἄλλο ποιεῖ ἤ, ὅταν ἐμπέσῃ λόγος περί τινος, καλλωπίζει τὰ ὀνομάτια καὶ συντίθησιν ὥσπερ οἱ κομμωταὶ τὴν κόμην;","st":"2.23"},{"sp":"N","t":"πότερον δ᾽ εἰπεῖν ἄμεινον ἢ σιωπῆσαι καὶ οὕτως ἄμεινον ἢ ἐκείνως καὶ τοῦτο πρέπον ἢ οὐ πρέπον, καὶ τὸν καιρὸν ἑκάστου καὶ τὴν χρείαν τίς ἄλλη λέγει ἢ ἡ προαιρετική; θέλεις οὖν αὐτὴν παρελθοῦσαν αὑτῆς καταψηφίσασθαι;","st":"2.23"},{"sp":"N","t":"‘τί οὖν;,’ φησίν, ‘εἰ οὕτως τὸ πρᾶγμα ἔχει, καὶ δύναται τὸ διακονοῦν κρεῖσσον εἶναι ἐκείνου ᾧ διακονεῖ, ὁ ἵππος τοῦ ἱππέως ἢ ὁ κύων τοῦ κυνηγοῦ ἢ τὸ ὄργανον τοῦ κιθαριστοῦ ἢ οἱ ὑπηρέται τοῦ βασιλέως.’ — τί ἐστι τὸ χρώμενον;","st":"2.23"},{"sp":"N","t":"προαίρεσις. τί ἐπιμελεῖται πάντων; προαίρεσις. τί ὅλον ἀναιρεῖ τὸν ἄνθρωπον ποτὲ μὲν λιμῷ, ποτὲ δ᾽ ἀγχόνῃ, ποτὲ δὲ κατὰ κρημνοῦ; προαίρεσις.","st":"2.23"},{"sp":"N","t":"εἶτα τούτου τί ἰσχυρότερον ἐν ἀνθρώποις ἐστίν; καὶ πῶς οἷόν τε τοῦ ἀκωλύτου τὰ κωλυόμενα; τὴν ὁρατικὴν δύναμιν τίνα πέφυκεν ἐμποδίζειν;","st":"2.23"},{"sp":"N","t":"καὶ προαίρεσις καὶ ἀπροαίρετα. τὴν ἀκουστικὴν ταὐτά, τὴν φραστικὴν ὡσαύτως. προαίρεσιν δὲ τί ἐμποδίζειν πέφυκεν; ἀπροαίρετον οὐδέν, αὐτὴ δ᾽ ἑαυτὴν διαστραφεῖσα. διὰ τοῦτο κακία μόνη αὕτη γίνεται ἢ ἀρετὴ μόνη.","st":"2.23"},{"sp":"N","t":"εἶτα τηλικαύτη δύναμις οὖσα καὶ πᾶσι τοῖς ἄλλοις ἐπιτεταγμένη παρελθοῦσα ἡμῖν λεγέτω κράτιστον εἶναι τῶν ὄντων τὴν σάρκα. οὐδὲ εἰ αὐτὴ ἡ σὰρξ ἑαυτὴν ἔλεγεν εἶναι κράτιστον, ἠνέσχετο ἄν τις αὐτῆς.","st":"2.23"},{"sp":"N","t":"νῦν δὲ τί ἐστιν, Ἐπίκουρε, τὸ ταῦτα ἀποφαινόμενον; τὸ περὶ Τέλους συγγεγραφός, τὸ τὰς Φυσικάς, τὸ περὶ Κανόνος; τὸ τὸν πώγωνα καθεικός; τὸ γράφον, ὅτε ἀπέθνῃσκεν, ὅτι ‘τὴν τελευταίαν ἄγοντες ἅμα καὶ μακαρίαν ἡμέραν;’","st":"2.23"},{"sp":"N","t":"ἡ σὰρξ ἢ ἡ προαίρεσις; εἶτα τούτου τι κρεῖσσον ἔχειν ὁμολογεῖς καὶ οὐ μαίνῃ; οὕτως τυφλὸς ταῖς ἀληθείαις καὶ κωφὸς εἶ;","st":"2.23"},{"sp":"N","t":"τί οὖν; ἀτιμάζει τις τὰς ἄλλας δυνάμεις; μὴ γένοιτο. λέγει τις μηδεμίαν εἶναι χρείαν ἢ προαγωγὴν ... τῆς προαιρετικῆς δυνάμεως; μὴ γένοιτο. ἀνόητον, ἀσεβές, ἀχάριστον πρὸς τὸν θεόν. ἀλλὰ τὴν ἀξίαν ἑκάστῳ ἀποδίδωσιν.","st":"2.23"},{"sp":"N","t":"ἔστι γάρ τις καὶ ὄνου χρεία, ἀλλ᾽ οὐχ ἡλίκη βοός: ἔστι καὶ κυνός, ἀλλ᾽ οὐχ ἡλίκη οἰκέτου: ἔστι καὶ οἰκέτου, ἀλλ᾽ οὐχ ἡλίκη τῶν πολιτῶν: ἔστι καὶ τούτων, ἀλλ᾽ οὐχ ἡλίκη τῶν ἀρχόντων.","st":"2.23"},{"sp":"N","t":"οὐ μέντοι διὰ τὸ ἄλλα εἶναι κρείττονα καὶ ἣν παρέχει τὰ ἕτερα χρείαν ἀτιμαστέον. ἔστι τις ἀξία καὶ τῆς φραστικῆς δυνάμεως, ἀλλ᾽ οὐχ ἡλίκη τῆς προαιρετικῆς.","st":"2.23"},{"sp":"N","t":"ὅταν οὖν ταῦτα λέγω, μή τις οἰέσθω ὅτι ἀμελεῖν ὑμᾶς ἀξιῶ φράσεως: οὐδὲ γὰρ ὀφθαλμῶν οὐδ᾽ ὤτων οὐδὲ χειρῶν οὐδὲ ποδῶν οὐδ᾽ ἐσθῆτος οὐδ᾽ ὑποδημάτων.","st":"2.23"},{"sp":"N","t":"ἀλλ᾽ ἄν μου πυνθάνῃ ‘τί οὖν ἐστι κράτιστον τῶν ὄντων;,’ τί εἴπω; τὴν φραστικήν; οὐ δύναμαι: ἀλλὰ τὴν προαιρετικήν, ὅταν ὀρθὴ γένηται.","st":"2.23"},{"sp":"N","t":"τοῦτο γάρ ἐστι τὸ κἀκείνῃ χρώμενον καὶ ταῖς ἄλλαις πάσαις καὶ μικραῖς καὶ μεγάλαις δυνάμεσιν: τούτου κατορθωθέντος ἀγαθὸς ἄνθρωπος ἀγαθὸς γίνεται, ἀποτευχθέντος κακὸς ἄνθρωπος γίνεται:","st":"2.23"},{"sp":"N","t":"παρ᾽ ὃ ἀτυχοῦμεν, εὐτυχοῦμεν, μεμφόμεθ᾽ ἀλλήλους, εὐαρεστοῦμεν, ἁπλῶς ὃ λεληθὸς μὲν κακοδαιμονίαν ποιεῖται, τυχὸν δ᾽ ἐπιμελείας εὐδαιμονίαν.","st":"2.23"},{"sp":"N","t":"τὸ δ᾽ αἴρειν τὴν δύναμιν τῆς φραστικῆς καὶ λέγειν μὴ εἶναι μηδεμίαν ταῖς ἀληθείαις οὐ μόνον ἀχαρίστου ἐστὶ πρὸς τοὺς δεδωκότας, ἀλλὰ καὶ δειλοῦ.","st":"2.23"},{"sp":"N","t":"ὁ γὰρ τοιοῦτος φοβεῖσθαί μοι δοκεῖ, μή, εἴπερ ἐστί τις δύναμις κατὰ τὸν τόπον, οὐ δυνηθῶμεν αὐτῆς καταφρονῆσαι.","st":"2.23"},{"sp":"N","t":"τοιοῦτοί εἰσι καὶ οἱ λέγοντες μηδεμίαν εἶναι παραλλαγὴν κάλλους πρὸς αἶσχος. εἶτα ὁμοίως ἦν κινηθῆναι τὸν Θερσίτην ἰδόντα καὶ τὸν Ἀχιλλέα; ὁμοίως τὴν Ἑλένην καὶ ἣν ἔτυχε γυναῖκα;","st":"2.23"},{"sp":"N","t":"καὶ ταῦτα μωρὰ καὶ ἄγροικα καὶ οὐκ εἰδότων τὴν ἑκάστου φύσιν, ἀλλὰ φοβουμένων μὴ ἄν τις αἴσθηται τῆς διαφορᾶς, εὐθὺς συναρπασθεὶς καὶ ἡττηθεὶς ἀπέλθῃ.","st":"2.23"},{"sp":"N","t":"ἀλλὰ τὸ μέγα τοῦτο, ἀπολιπεῖν ἑκάστῳ τὴν αὑτοῦ δύναμιν ἣν ἔχει καὶ ἀπολιπόντα ἰδεῖν τὴν ἀξίαν τῆς δυνάμεως καὶ τὸ κράτιστον τῶν ὄντων καταμαθεῖν καὶ τοῦτο ἐν παντὶ μεταδιώκειν, περὶ τοῦτο ἐσπουδακέναι, πάρεργα τἆλλα πρὸς τοῦτο πεποιημένον, οὐ μέντοι ἀμελοῦντα οὐδ᾽ ἐκείνων κατὰ δύναμιν.","st":"2.23"},{"sp":"N","t":"καὶ γὰρ ὀφθαλμῶν ἐπιμελητέον, ἀλλ᾽ οὐχ ὡς τοῦ κρατίστου, ἀλλὰ καὶ τούτων διὰ τὸ κράτιστον: ὅτι ἐκεῖνο οὐκ ἄλλως ἕξει κατὰ φύσιν εἰ μὴ ἐν τούτοις εὐλογιστοῦν καὶ τὰ ἕτερα παρὰ τὰ ἕτερα αἱρούμενον.","st":"2.23"},{"sp":"N","t":"τί οὖν ἐστι τὸ γινόμενον; οἷον εἴ τις ἀπιὼν εἰς τὴν πατρίδα τὴν ἑαυτοῦ καὶ διοδεύων πανδοκεῖον καλὸν ἀρέσαντος αὐτῷ τοῦ πανδοκείου καταμένοι ἐν τῷ πανδοκείῳ.","st":"2.23"},{"sp":"N","t":"ἄνθρωπε, ἐπελάθου σου τῆς προθέσεως: οὐκ εἰς τοῦτο ὥδευες, ἀλλὰ διὰ τούτου. ‘ἀλλὰ κομψὸν τοῦτο.’ πόσα δ᾽ ἄλλα πανδοκεῖα κομψά, πόσοι δὲ λειμῶνες: ἁπλῶς ὡς δίοδος.","st":"2.23"},{"sp":"N","t":"τὸ δὲ προκείμενον ἐκεῖνο: εἰς τὴν πατρίδα ἐπανελθεῖν, τοὺς οἰκείους ἀπαλλάξαι δέους, αὐτὸν τὰ τοῦ πολίτου ποιεῖν, γῆμαι, παιδοποιεῖσθαι, ἄρξαι τὰς νομιζομένας ἀρχάς.","st":"2.23"},{"sp":"N","t":"οὐ γὰρ τοὺς κομψοτέρους ἡμῖν τόπους ἐκλεξόμενος ἐλήλυθας, ἀλλ᾽ ἐν οἷς ἐγένου καὶ ὧν κατατέταξαι πολίτης, ἐν τούτοις ἀναστραφησόμενος. τοιοῦτόν τι καὶ ἐνταῦθά ἐστι τὸ γινόμενον.","st":"2.23"},{"sp":"N","t":"ἐπεὶ διὰ λόγου καὶ τοιαύτης παραδόσεως ἐλθεῖν ἐπὶ τὸ τέλειον δεῖ καὶ τὴν αὑτοῦ προαίρεσιν ἐκκαθᾶραι καὶ τὴν δύναμιν τὴν χρηστικὴν τῶν φαντασιῶν ὀρθὴν κατασκευάσαι, ἀνάγκη δὲ τὴν παράδοσιν γίνεσθαι διά τινων θεωρημάτων καὶ διὰ λέξεως ποιᾶς καὶ μετά τινος ποικιλίας καὶ δριμύτητος τῶν θεωρημάτων,","st":"2.23"},{"sp":"N","t":"ὑπ᾽ αὐτῶν τινες τούτων ἁλισκόμενοι καταμένουσιν αὐτοῦ, ὁ μὲν ὑπὸ τῆς λέξεως, ὁ δ᾽ ὑπὸ συλλογισμῶν, ὁ δ᾽ ὑπὸ μεταπιπτόντων, ὁ δ᾽ ὑπ᾽ ἄλλου τινὸς τοιούτου πανδοκείου, καὶ προσμείναντες κατασήπονται ὡς παρὰ ταῖς Σειρῆσιν.","st":"2.23"},{"sp":"N","t":"ἄνθρωπε, τὸ προκείμενον ἦν σοι κατασκευάσαι σαυτὸν χρηστικὸν ταῖς προσπιπτούσαις φαντασίαις κατὰ φύσιν, ἐν ὀρέξει ἀναπότευκτον, ἐν δ᾽ ἐκκλίσει ἀπερίπτωτον, μηδέποτ᾽ ἀτυχοῦντα, μηδέποτε δυστυχοῦντα, ἐλεύθερον, ἀκώλυτον, ἀνανάγκαστον, συναρμόζοντα τῇ τοῦ Διὸς διοικήσει, ταύτῃ πειθόμενον, ταύτῃ εὐαρεστοῦντα, μηδένα μεμφόμενον, μηδέν᾽ αἰτιώμενον, δυνάμενον εἰπεῖν τούτους τοὺς στίχους ἐξ ὅλης ψυχῆς ἄγου δέ μ᾽, ὦ Ζεῦ, καὶ σύ γ᾽ ἡ Πεπρωμένη.","st":"2.23"},{"sp":"N","t":"εἶτα τοῦτο τὸ προκείμενον ἔχων ἀρέσαντός σοι λεξειδίου, ἀρεσάντων θεωρημάτων τινῶν αὐτοῦ καταμένεις καὶ κατοικεῖν προαιρῇ ἐπιλαθόμενος τῶν ἐν οἴκῳ καὶ λέγεις ‘ταῦτα κομψά ἐστιν;’ τίς γὰρ λέγει μὴ εἶναι αὐτὰ κομψά;","st":"2.23"},{"sp":"N","t":"ἀλλ᾽ ὡς δίοδον, ὡς πανδοκεῖα. τί γὰρ κωλύει φράζοντα ὡς Δημοσθένης ἀτυχεῖν; τί δὲ κωλύει συλλογισμοὺς ἀναλύοντα ὡς Χρύσιππος ἄθλιον εἶναι, πενθεῖν, φθονεῖν, ἁπλῶς ταράσσεσθαι, κακοδαιμονεῖν;","st":"2.23"},{"sp":"N","t":"οὐδὲ ἕν. ὁρᾷς οὖν ὅτι πανδοκεῖα ἦν ταῦτα οὐδενὸς ἄξια, τὸ δὲ προκείμενον ἄλλο ἦν.","st":"2.23"},{"sp":"N","t":"ταῦτα ὅταν λέγω πρός τινας, οἴονταί με καταβάλλειν τὴν περὶ τὸ λέγειν ἐπιμέλειαν ἢ τὴν περὶ τὰ θεωρήματα. ἐγὼ δ᾽ οὐ ταύτην καταβάλλω, ἀλλὰ τὸ περὶ ταῦτ᾽ ἀκαταληκτικῶς ἔχειν καὶ ἐνταῦθα τίθεσθαι τὰς αὑτῶν ἐλπίδας.","st":"2.23"},{"sp":"N","t":"εἴ τις τοῦτο παριστὰς βλάπτει τοὺς ἀκούοντας, κἀμὲ τίθεσθε ἕνα τῶν βλαπτόντων. οὐ δύναμαι δ᾽ ἄλλο βλέπων τὸ κράτιστον καὶ τὸ κυριώτατον ἄλλο λέγειν εἶναι, ἵν᾽ ὑμῖν χαρίσωμαι. πρός τινα τῶν οὐκ ἠξιωμένων ὑπ᾽ερ αὐτοῦ. εἰπόντος αὐτῷ τινος ὅτι Πολλάκις ἐπιθυμῶν σου ἀκοῦσαι ἦλθον πρὸς σὲ καὶ οὐδέποτέ μοι ἀπεκρίνω: καὶ νῦν,","st":"2.23"},{"sp":"N","t":"εἰ δυνατόν, παρακαλῶ σε εἰπεῖν τί μοι, Δοκεῖ σοι, ἔφη, καθάπερ ἄλλου τινὸς εἶναι τέχνη οὕτως δὲ καὶ τοῦ λέγειν, ἣν ὁ μὲν ἔχων ἐμπείρως ἐρεῖ, ὁ δὲ μὴ ἔχων ἀπείρως;","st":"2.24"},{"sp":"N","t":"— δοκεῖ. — οὐκοῦν ὁ μὲν διὰ τοῦ λέγειν αὐτός τε ὠφελούμενος καὶ ἄλλους οἷός τε ὢν ὠφελεῖν οὗτος ἐμπείρως ἂν λέγοι, ὁ δὲ βλαπτόμενος μᾶλλον καὶ βλάπτων οὗτος ἄπειρος ἂν εἴη τῆς τέχνης ταύτης τῆς τοῦ λέγειν; εὕροις ἂν τοὺς μὲν βλαπτομένους τοὺς δ᾽ ὠφελουμένους.","st":"2.24"},{"sp":"N","t":"οἱ δ᾽ ἀκούοντες πάντες ὠφελοῦνται ἀφ᾽ ὧν ἀκούουσιν ἢ καὶ τούτων εὕροις ἂν τοὺς μὲν ὠφελουμένους τοὺς δὲ βλαπτομένους; — καὶ τούτων, ἔφη. — οὐκοῦν καὶ ἐνταῦθα ὅσοι μὲν ἐμπείρως ἀκούουσιν ὠφελοῦνται, ὅσοι δ᾽ ἀπείρως βλάπτονται;","st":"2.24"},{"sp":"N","t":"— ὡμολόγει. — ἔστιν ἄρα τις ἐμπειρία καθάπερ τοῦ λέγειν οὕτως καὶ τοῦ ἀκούειν; — ἔοικεν.","st":"2.24"},{"sp":"N","t":"— εἰ δὲ βούλει, καὶ οὕτως σκέψαι αὐτό. τὸ μουσικῶς ἅψασθαι τίνος σοι δοκεῖ; — μουσικοῦ. — τί δέ;","st":"2.24"},{"sp":"N","t":"τὸν ἀνδριάντα ὡς δεῖ κατασκευάσαι τίνος σοι φαίνεται; — ἀνδριαντοποιοῦ. — τὸ ἰδεῖν ἐμπείρως οὐδεμιᾶς σοι προσδεῖσθαι φαίνεται τέχνης; — προσδεῖται καὶ τοῦτο.","st":"2.24"},{"sp":"N","t":"— οὐκοῦν εἰ καὶ τὸ λέγειν ὡς δεῖ τοῦ ἐμπείρου ἐστίν, ὁρᾷς ὅτι καὶ τὸ ἀκούειν ὠφελίμως τοῦ ἐμπείρου ἐστίν;","st":"2.24"},{"sp":"N","t":"καὶ τὸ μὲν τελείως καὶ ὠφελίμως, εἰ βούλει, πρὸς τὸ παρὸν ἀφῶμεν, ἐπεὶ καὶ μακράν ἐσμεν ἀμφότεροι παντὸς τοῦ τοιούτου:","st":"2.24"},{"sp":"N","t":"ἐκεῖνο δὲ πᾶς ἄν τις ὁμολογῆσαί μοι δοκεῖ, ὅτι ποσῆς γέ τινος τριβῆς περὶ τὸ ἀκούειν προσδεῖται ὁ τῶν φιλοσόφων ἀκουσόμενος. ἢ γὰρ οὔ;","st":"2.24"},{"sp":"N","t":"περὶ τίνος οὖν λέγω πρὸς σέ; δεῖξόν μοι. περὶ τίνος ἀκοῦσαι δύνασαι; περὶ ἀγαθῶν καὶ κακῶν; τίνος; ἆρά γε ἵππου; — οὔ. — ἀλλὰ βοός; — οὔ. — τί οὖν;","st":"2.24"},{"sp":"N","t":"ἀνθρώπου; — ναί. — οἴδαμεν οὖν, τί ἐστιν ἄνθρωπος, τίς ἡ φύσις αὐτοῦ, τίς ἡ ἔννοια; ἔχομεν καὶ κατὰ ποσὸν περὶ τοῦτο τὰ ὦτα τετρημένα; ἀλλὰ φύσις τί ἐστιν ἐννοεῖς ἢ δύνασαι καὶ κατὰ ποσὸν ἀκολουθῆσαί μοι λέγοντι;","st":"2.24"},{"sp":"N","t":"ἀλλ᾽ ἀποδείξει χρήσομαι πρὸς σέ; πῶς; παρακολουθεῖς γὰρ αὐτῷ τούτῳ, τί ἐστιν ἀπόδειξις ἢ πῶς τι ἀποδείκνυται ἢ διὰ τίνων; ἢ τίνα ὅμοια μὲν ἀποδείξει ἐστίν, ἀπόδειξις δ᾽ οὐκ ἔστιν;","st":"2.24"},{"sp":"N","t":"τί γάρ ἐστιν ἀληθὲς οἶδας ἢ τί ἐστι ψεῦδος; τί τίνι ἀκολουθεῖ, τί τίνι μάχεται ἢ ἀνομολογούμενόν ἐστιν ἢ ἀσύμφωνον;","st":"2.24"},{"sp":"N","t":"ἀλλὰ κινῶ σε πρὸς φιλοσοφίαν; πῶς παραδεικνύω σοι τὴν μάχην τῶν πολλῶν ἀνθρώπων, καθ᾽ ἣν διαφέρονται περὶ ἀγαθῶν καὶ κακῶν καὶ συμφερόντων καὶ ἀσυμφόρων, αὐτὸ τοῦτο τί ἐστι μάχη οὐκ εἰδότι; δεῖξον οὖν μοι, τί περανῶ διαλεγόμενός σοι. κίνησόν μοι προθυμίαν.","st":"2.24"},{"sp":"N","t":"ὡς ἡ κατάλληλος πόα τῷ προβάτῳ φανεῖσα προθυμίαν αὐτῷ κινεῖ πρὸς τὸ φαγεῖν, ἂν δὲ λίθον ἢ ἄρτον παραθῇς, οὐ κινηθήσεται, οὕτως εἰσί τινες ἡμῖν φυσικαὶ προθυμίαι καὶ πρὸς τὸ λέγειν, ὅταν ὁ ἀκουσόμενος φανῇ τις, ὅταν αὐτὸς ἐρεθίσῃ. ἂν δ᾽ ὡς λίθος ἢ χόρτος ᾖ παρακείμενος, πῶς δύναται ἀνθρώπῳ ὄρεξιν κινῆσαι;","st":"2.24"},{"sp":"N","t":"ἡ ἄμπελος μή τι λέγει τῷ γεωργῷ ‘ἐπιμελοῦ μου;’ ἀλλ᾽ αὐτὴ δι᾽ αὑτῆς ἐμφαίνουσα, ὅτι ἐπιμεληθέντι λυσιτελήσει αὐτῷ, ἐκκαλεῖται πρὸς τὴν ἐπιμέλειαν.","st":"2.24"},{"sp":"N","t":"τὰ παιδία τὰ πιθανὰ καὶ δριμέα τίνα οὐκ ἐκκαλεῖται πρὸς τὸ συμπαίζειν αὐτοῖς καὶ συνέρπειν καὶ πρὸς τὸ συμψελλίζειν; ὄνῳ δὲ τίς προθυμεῖται συμπαίζειν ἢ συνογκᾶσθαι; καὶ γὰρ εἰ μικρόν, ὅμως ὀνάριόν ἐστιν. τί οὖν μοι οὐδὲν λέγεις;","st":"2.24"},{"sp":"N","t":"— ἐκεῖνο μόνον ἔχω σοι εἰπεῖν, ὅτι ὁ ἀγνοῶν, τίς ἐστι καὶ ἐπὶ τί γέγονεν καὶ ἐν τίνι τούτῳ τῷ κόσμῳ καὶ μετὰ τίνων κοινωνῶν καὶ τίνα τὰ ἀγαθά ἐστι καὶ τὰ κακὰ καὶ τὰ καλὰ καὶ τὰ αἰσχρά, καὶ μήτε λόγῳ παρακολουθῶν μήτ᾽ ἀποδείξει, μήτε τί ἐστιν ἀληθὲς ἢ τί ψεῦδος, μήτε διακρῖναι ταῦτα δυνάμενος οὔτ᾽ ὀρέξεται κατὰ φύσιν οὔτ᾽ ἐκκλινεῖ οὔθ᾽ ὁρμήσει οὔτ᾽ ἐπιβαλεῖται, οὐ συγκαταθήσεται, οὐκ ἀνανεύσει, οὐκ ἐφέξει, τὸ σύνολον. κωφλὸς καὶ τυφλὸς περιελεύσεται δοκῶν μέν τις εἶναι, ὢν δ᾽ οὐδείς.","st":"2.24"},{"sp":"N","t":"νῦν γὰρ πρῶτον τοῦθ᾽ οὕτως ἔχει; οὐχὶ ἐξ οὗ γένος ἀνθρώπων ἐστίν, ἐξ ἐκείνου πάντα τὰ ἁμαρτήματα καὶ τὰ ἀτυχήματα παρὰ ταύτην τὴν ἄγνοιαν γεγένηται;","st":"2.24"},{"sp":"N","t":"Ἀγαμέμνων καὶ Ἀχιλλεὺς διὰ τί ἀλλήλοις διεφέροντο; οὐχὶ διὰ τὸ μὴ εἰδέναι, τίνα ἐστὶ συμφέροντα καὶ ἀσύμφορα; οὐχὶ ὁ μὲν λέγει, ὅτι συμφέρει ἀποδοῦναι τῷ πατρὶ τὴν Χρυσηίδα, ὁ δὲ λέγει, ὅτι οὐ συμφέρει; οὐχὶ ὁ μὲν λέγει, ὅτι δεῖ αὐτὸν λαβεῖν τὸ ἄλλου γέρας, ὁ δέ, ὅτι οὐ δεῖ; οὐχὶ διὰ ταῦτα ἐπελάθοντο καὶ τίνες ἦσαν καὶ ἐπὶ τί ἐληλύθεσαν;","st":"2.24"},{"sp":"N","t":"ἔα, ἄνθρωπε, ἐπὶ τί ἐλήλυθας; ἐρωμένας κτησόμενος ἢ πολεμήσων; ‘πολεμήσων.’ τίσι; τοῖς Τρωσὶν ἢ τοῖς Ἕλλησιν; ‘τοῖς Τρωσίν.’ ἀφεὶς οὖν τὸν Ἕκτορα ἐπὶ τὸν βασιλέα τὸν σαυτοῦ σπᾷς τὸ ξίφος;","st":"2.24"},{"sp":"N","t":"σὺ δ᾽, ὦ βέλτιστε, ἀφεὶς τὰ τοῦ βασιλέως ἔργα, ᾧ λαοί τ᾽ ἐπιτετράφαται καὶ τόσσα μέμηλεν, περὶ κορασιδίου διαπυκτεύεις τῷ πολεμικωτάτῳ τῶν συμμάχων, ὃν δεῖ παντὶ τρόπῳ περιέπειν καὶ φυλάττειν; καὶ χείρων γίνῃ κομψοῦ ἀρχιερέως, ὃς τοὺς καλοὺς μονομάχους διὰ πάσης ἐπιμελείας ἔχει; ὁρᾷς, οἷα ποιεῖ ἄγνοια περὶ τῶν συμφερόντων;","st":"2.24"},{"sp":"N","t":"‘ἀλλὰ κἀγὼ πλούσιός εἰμι.’ μή τι οὖν τοῦ Ἀγαμέμνονος πλουσιώτερος; ‘ἀλλὰ καὶ καλός εἰμι.’ μή τι οὖν τοῦ Ἀχιλλέως καλλίων; ‘ἀλλὰ καὶ κόμιον κομψὸν ἔχω.’ ὁ δ᾽ Ἀχιλλεὺς οὐ κάλλιον καὶ ξανθόν; καὶ οὐκ ἐκτένιζεν αὐτὸ κομψῶς οὐδ᾽ ἔπλασσεν.","st":"2.24"},{"sp":"N","t":"‘ἀλλὰ καὶ ἰσχυρός εἰμι.’ μή τι οὖν δύνασαι λίθον ἆραι ἡλίκον ὁ Ἕκτωρ ἢ ὁ Αἴας; ‘ἀλλὰ καὶ εὐγενής.’ μή τι ἐκ θεᾶς μητρός, μή τι πατρὸς ἐγγόνου Διός; τί οὖν ἐκεῖνον ὠφελεῖ ταῦτα, ὅταν καθήμενος κλαίῃ διὰ τὸ κορασίδιον; ‘ἀλλὰ ῥήτωρ εἰμί.’","st":"2.24"},{"sp":"N","t":"ἐκεῖνος δ᾽ οὐκ ἦν; οὐ βλέπεις πῶς κέχρηται τοῖς δεινοτάτοις τῶν Ἑλλήνων περὶ λόγους Ὀδυσσεῖ καὶ Φοίνικι, πῶς αὐτοὺς ἀστόμους πεποίηκε;","st":"2.24"},{"sp":"N","t":"ταῦτά σοι μόνα ἔχω εἰπεῖν καὶ οὐδὲ ταῦτα προθύμως.","st":"2.24"},{"sp":"N","t":"— διὰ τί; — ὅτι με οὐκ ἠρέθισας. εἰς τί γὰρ ἀπιδὼν ἐρεθισθῶ ὡς οἱ ἱππικοὶ περὶ τοὺς ἵππους τοὺς εὐφυεῖς; εἰς τὸ σωμάτιον; αἰσχρῶς αὐτὸ πλάσσεις. εἰς τὴν ἐσθῆτα; καὶ ταύτην τρυφερὰν ἔχεις. εἰς σχῆμα, εἰς βλέμμα;","st":"2.24"},{"sp":"N","t":"εἰς οὐδέν. ὅταν ἀκοῦσαι θέλῃς φιλοσόφου, μὴ λέγε αὐτῷ ὅτι ‘οὐδέν μοι λέγεις;,’ ἀλλὰ μόνον δείκνυε σαυτὸν † τοῦ ἀκούειν καὶ ὄψει, πῶς κινήσεις τὸν λέγοντα. πῶς ἀναγκαῖα τὰ λογικά. τῶν παρόντων δέ τινος εἰπόντος Πεῖσόν με, ὅτι τὰ λογικὰ χρήσιμά ἐστιν, Θέλεις, ἔφη, ἀποδείξω σοι τοῦτο;","st":"2.24"},{"sp":"N","t":"— ναί. — οὐκοῦν λόγον μ᾽ ἀποδεικτικὸν διαλεχθῆναι δεῖ; — ὁμολογήσαντος δὲ Πόθεν οὖν εἴσῃ, ἄν σε σοφίσωμαι;","st":"2.25"},{"sp":"N","t":"— σιωπήσαντος δὲ τοῦ ἀνθρώπου Ὁρᾷς, ἔφη, πῶς αὐτὸς ὁμολογεῖς ὅτι ταῦτα ἀναγκαῖά ἐστιν, εἰ χωρὶς αὐτῶν οὐδ᾽ αὐτὸ τοῦτο δύνασαι μαθεῖν, πότερον ἀναγκαῖα ἢ οὐκ ἀναγκαῖά ἐστιν. τί τὸ ἴδιον τοῦ ἁμαρτήματος. πᾶν ἁμάρτημα μάχην περιέχει. ἐπεὶ γὰρ ὁ ἁμαρτάνων οὐ θέλει ἁμαρτάνειν, ἀλλὰ κατορθῶσαι, δῆλον ὅτι ὃ μὲν θέλει οὐ ποιεῖ.","st":"2.25"},{"sp":"N","t":"τί γὰρ ὁ κλέπτης θέλει πρᾶξαι; τὸ αὑτῷ συμφέρον. οὐκ οὖν, εἰ ἀσύμφορόν ἐστιν αὐτῷ τὸ κλέπτειν, ὃ μὲν θέλει ποιεῖ.","st":"2.26"},{"sp":"N","t":"πᾶσα δὲ ψυχὴ λογικὴ φύσει διαβέβληται πρὸς μάχην: καὶ μέχρι μὲν ἂν μὴ παρακολουθῇ τούτῳ, ὅτι ἐν μάχῃ ἐστίν, οὐδὲν κωλύεται τὰ μαχόμενα ποιεῖν: παρακολουθήσαντα δὲ πολλὴ ἀνάγκη ἀποστῆναι τῆς μάχης καὶ φυγεῖν οὕτως ὡς καὶ ἀπὸ τοῦ ψεύδους ἀνανεῦσαι πικρὰ ἀνάγκη τῷ αἰσθανομένῳ, ὅτι ψεῦδός ἐστιν: μέχρι δὲ τοῦτο μὴ φαντάζηται, ὡς ἀληθεῖ ἐπινεύει αὐτῷ.","st":"2.26"},{"sp":"N","t":"δεινὸς οὖν ἐν λόγῳ, ὁ δ᾽ αὐτὸς καὶ προτρεπτικὸς καὶ ἐλεγκτικὸς οὗτος ὁ δυνάμενος ἑκάστῳ παραδεῖξαι τὴν μάχην, καθ᾽ ἣν ἁμαρτάνει, καὶ σαφῶς παραστῆσαι, πῶς ὃ θέλει οὐ ποιεῖ καὶ ὃ μὴ θέλει ποιεῖ.","st":"2.26"},{"sp":"N","t":"ἂν γὰρ τοῦτο δείξῃ τις, αὐτὸς ἀφ᾽ αὑτοῦ ἀναποχωρήσει. μέχρι δὲ μὴ δεικνύῃς, μὴ θαύμαζε, εἰ ἐπιμένει: κατορθώματος γὰρ φαντασίαν λαμβάνων ποιεῖ αὐτό.","st":"2.26"},{"sp":"N","t":"διὰ τοῦτο καὶ Σωκράτης ταύτῃ τῇ δυνάμει πεποιθὼς ἔλεγεν ὅτι ‘ἐγὼ ἄλλον μὲν οὐδένα εἴωθα παρέχειν μάρτυρα ὧν λέγω, ἀρκοῦμαι δ᾽ ἀεὶ τῷ προσδιαλεγομένῳ καὶ ἐκεῖνον ἐπιψηφίζω καὶ καλῶ μάρτυρα καὶ εἷς ὢν οὗτος ἀρκεῖ μοι ἀντὶ πάντων.’","st":"2.26"},{"sp":"N","t":"ᾔδει γάρ, ὑπὸ τίνος λογικὴ ψυχὴ κινεῖται †, ζυγῷ ἐπιρρέψει, ἄν τε θέλῃς ἄν τε μή. λογικῷ ἡγεμονικῷ δεῖξον μάχην καὶ ἀποστήσεται: ἂν δὲ μὴ δεικνύῃς, αὐτὸς σαυτῷ μᾶλλον ἐγκάλει ἢ τῷ μὴ πειθομένῳ.","st":"2.26"},{"sp":"HDR","t":"Βιβλίον γʹ","st":"3.1"},{"sp":"N","t":"— δοκοῦσιν, ἔφη. — οὐκοῦν καὶ ἄνθρωποι οἱ μὲν καλοί, οἱ δ᾽ αἰσχροί; — πῶς γὰρ οὔ; — πότερον οὖν κατὰ τὸ αὐτὸ ἕκαστα τούτων ἐν τῷ αὐτῷ γένει καλὰ προσαγορεύομεν ἢ ἰδίως ἕκαστον; οὕτως δ᾽ ὄψει αὐτό.","st":"3.1"},{"sp":"N","t":"ἐπειδὴ πρὸς ἄλλο μὲν ὁρῶμεν κύνα πεφυκότα, πρὸς ἄλλον δ᾽ ἵππον, πρὸς ἄλλο δ᾽ εἰ οὕτως τύχοι ἀηδόνα, καθόλου μὲν οὐκ ἀτόπως ἀποφήναιτ᾽ ἄν τις ἕκαστον τηνικαῦτα καλὸν εἶναι, ὁπότε κατὰ τὴν αὑτοῦ φύσιν κράτιστ᾽ ἔχοι: ἐπεὶ δ᾽ ἡ φύσις ἑκάστου διάφορός ἐστιν, διαφόρως εἶναί μοι δοκεῖ ἕκαστον αὐτῶν καλόν: ἢ γὰρ οὔ;","st":"3.1"},{"sp":"N","t":"— ὡμολόγει. — οὐκ οὖν ὅπερ κύνα ποιεῖ καλόν, τοῦτο ἵππον αἰσχρόν, ὅπερ δ᾽ ἵππον καλόν, τοῦτο κύνα αἰσχρόν, εἴ γε διάφοροι αἱ φύσεις εἰσὶν αὐτῶν;","st":"3.1"},{"sp":"N","t":"— ἔοικεν. — καὶ γὰρ τὸ παγκρατιαστὴν οἶμαι ποιοῦν καλὸν τοῦτο παλαιστὴν οὐκ ἀγαθὸν ποιεῖ, δρομέα δὲ καὶ γελοιότατον: καὶ ὁ πρὸς πενταθλίαν καλὸς ὁ αὐτὸς οὗτος πρὸς πάλην αἴσχιστος; — οὕτως, ἔφη.","st":"3.1"},{"sp":"N","t":"— τί οὖν ποιεῖ ἄνθρωπον καλὸν ἢ ὅπερ τῷ γένει καὶ κύνα καὶ ἵππον; — τοῦτο, ἔφη. — τί οὖν ποιεῖ κύνα καλόν; ἡ ἀρετὴ ἡ κυνὸς παροῦσα. τί ἵππον; ἡ ἀρετὴ ἡ ἵππου παροῦσα. τί οὖν ἄνθρωπον; μή ποθ᾽ ἡ ἀρετὴ ἡ ἀνθρώπου παροῦσα;","st":"3.1"},{"sp":"N","t":"καὶ σὺ οὖν εἰ θέλεις καλὸς εἶναι, νεανίσκε, τοῦτο ἐκπόνει, τὴν ἀρετὴν τὴν ἀνθρωπικήν.","st":"3.1"},{"sp":"N","t":"— τίς δ᾽ ἐστὶν αὕτη; — ὅρα, τίνας αὐτὸς ἐπαινεῖς, ὅταν δίχα πάθους τινὰς ἐπαινῇς: πότερα τοὺς δικαίους ἢ τοὺς ἀδίκους; — τοὺς δικαίους. — πότερον τοὺς σώφρονας ἢ τοὺς ἀκολάστους; — τοὺς σώφρονας. — τοὺς ἐγκρατεῖς δ᾽ ἢ τοὺς ἀκρατεῖς; — τοὺς ἐγκρατεῖς.","st":"3.1"},{"sp":"N","t":"— οὐκοῦν τοιοῦτόν τινα ποιῶν σαυτὸν ἴσθι ὅτι καλὸν ποιήσεις: μέχρις δ᾽ ἂν τούτων ἀμελῇς, αἰσχρόν σ᾽ εἶναι ἀνάγκη, κἂν πάντα μηχανᾷ ὑπὲρ τοῦ φαίνεσθαί σε καλόν.","st":"3.1"},{"sp":"N","t":"ἐντεῦθεν οὐκέτι ἔχω σοι πῶς εἴπω: ἄν τε γὰρ λέγω ἃ φρονῶ, ἀνιάσω σε καὶ ἐξελθὼν τάχα οὐδ᾽ εἰσελεύσῃ: ἄν τε μὴ λέγω, ὅρα οἷον ποιήσω, εἰ σὺ μὲν ἔρχῃ πρὸς ἐμὲ ὠφεληθησόμενος, ἐργὼ δ᾽ οὐκ ὠφελήσω σ᾽ οὐδέν, καὶ σὺ μὲν ὡς πρὸς φιλόσοφον, ἐγὼ δ᾽ οὐδὲν ἐρῶ σοι ὡς φιλόσοφος.","st":"3.1"},{"sp":"N","t":"πῶς δὲ καὶ ὠμόν ἐστι πρὸς αὐτόν σε τὸ περιιδεῖν ἀνεπανόρθωτον ἄν ποθ᾽ ὕστερον φρένας σχῇς, εὐλόγως μοι ἐγκαλέσεις:","st":"3.1"},{"sp":"N","t":"‘τί εἶδεν ἐν ἐμοὶ ὁ Ἐπίκτητος, ἵνα βλέπων με τοιοῦτον εἰσερχόμενον πρὸς αὐτὸν οὕτως αἰσχρῶς ἔχοντα περιίδῃ καὶ μηδέποτε μηδὲ ῥῆμα εἴπῃ;","st":"3.1"},{"sp":"N","t":"οὕτως μου ἀπέγνω; νέος οὐκ ἤμην; οὐκ ἤμην λόγου ἀκουστικός; πόσοι δ᾽ ἄλλοι νέοι ἐφ᾽ ἡλικίας πολλὰ τοιαῦτα διαμαρτάνουσιν;","st":"3.1"},{"sp":"N","t":"τινά ποτ᾽ ἀκούω Πολέμωνα ἐξ ἀκολαστοτάτου νεανίσκου τοσαύτην μεταβολὴν μεταβαλεῖν. ἔστω, οὐκ ᾤετό με Πολέμωνα ἔσεσθαι: τὴν μὲν κόμην ἠδύνατό μου διορθῶσαι, τὰ μὲν περιάμματά μου περιελεῖν, ψιλούμενόν με παῦσαι ἠδύνατο, ἀλλὰ βλέπων με —","st":"3.1"},{"sp":"N","t":"τίνος εἴπω; — σχῆμα ἔχοντα ἐσιώπα.’ ἐγὼ οὐ λέγω, τίνος ἐστὶ τὸ σχῆμα τοῦτο: σὺ δ᾽ αὐτὸ ἐρεῖς τόθ᾽, ὅταν εἰς σαυτὸν ἔλθῃς, καὶ γνώσει, οἷόν ἐστι καὶ τίνες αὐτὸ ἐπιτηδεύουσι.","st":"3.1"},{"sp":"N","t":"τοῦτό μοι ὕστερον ἂν ἐγκαλῇς, τί ἕξω ἀπολογήσασθαι; ναί: ἀλλ᾽ ἐρῶ καὶ οὐ πεισθήσεται. τῷ γὰρ Ἀπόλλωνι ἐπείσθη ὁ Λάιος; οὐκ ἀπελθὼν καὶ μεθυσθεὶς χαίρειν εἶπεν τῷ χρησμῷ; τί οὖν; παρὰ τοῦτο οὐκ εἶπεν αὐτῷ ὁ Ἀπόλλων τὰς ἀληθείας;","st":"3.1"},{"sp":"N","t":"καίτοι ἐγὼ μὲν οὐκ οἶδα οὔτ᾽ εἰ πεισθήσῃ μοι οὔτ᾽ εἰ μή: ἐκεῖνος δ᾽ ἀκριβέστατα ᾔδει, ὅτι οὐ πεισθήσεται, καὶ ὅμως εἶπεν.","st":"3.1"},{"sp":"N","t":"— διὰ τί δ᾽ εἶπεν; — διὰ τί δὲ Ἀπόλλων ἐστίν; διὰ τί δὲ χρησμῳδεῖ; διὰ τί δ᾽ εἰς ταύτην τὴν χώραν ἑαυτὸν κατατέταχεν, ὥστε μάντις εἶναι καὶ πηγὴ τῆς ἀληθείας καὶ πρὸς αὐτὸν ἔρχεσθαι τοὺς ἐκ τῆς οἰκουμένης; διὰ τί δὲ προγέγραπται τὸ γνῶθι σαυτὸν μηδενὸς αὐτὸ νοοῦντος;","st":"3.1"},{"sp":"N","t":"Σωκράτης πάντας ἔπειθε τοὺς προσιό ντας ἐπιμελεῖσθαι ἑαυτῶν; οὐδὲ τὸ χιλιοστὸν μέρος. ἀλλ᾽ ὅμως ἐπειδὴ εἰς ταύτην τὴν τάξιν ὑπὸ τοῦ δαιμονίου, ὥς φησιν αὐτός, κατετάχθη, μηκέτι ἐξέλιπεν. ἀλλὰ καὶ πρὸς τοὺς δικαστὰς τί λέγει;","st":"3.1"},{"sp":"N","t":"‘ἄν μ᾽ ἀφῆτε,’ φησίν, ‘ἐπὶ τούτοις, ἵνα μηκέτι ταῦτα πράσσω ἃ νῦν, οὐκ ἀνέξομαι οὐδ᾽ ἀνήσω: ἀλλὰ καὶ νέῳ καὶ πρεσβυτέρῳ καὶ ἁπλῶς ἀεὶ τῷ ἐντυγχάνοντι προσελθὼν πεύσομαι ταῦτα ἃ καὶ νῦν πυνθάνομαι, πολὺ δὲ μάλιστα ὑμῶν, φησί, τῶν πολιτῶν, ὅτι ἐγγυτέρω μου γένει ἐστέ.’","st":"3.1"},{"sp":"N","t":"οὕτως περίεργος εἶ, ὦ Σώκρατες, καὶ πολυπράγμων; τί δέ σοι μέλει, τί ποιοῦμεν; ‘οἷον καὶ λέγεις; κοινωνός μου ὢν καὶ συγγενὴς ἀμελεῖς σεαυτοῦ καὶ τῇ πόλει παρέχεις πολίτην κακὸν καὶ τοῖς συγγενέσι συγγενῆ καὶ τοῖς γείτοσι γείτονα.’","st":"3.1"},{"sp":"N","t":"‘σὺ οὖν τίς εἶ;’ ἐνταῦθα μέγα ἐστὶ τὸ εἰπεῖν ὅτι ‘οὗτός εἰμι, ᾧ δεῖ μέλειν ἀνθρώπων.’ οὐδὲ γὰρ λέοντι τὸ τυχὸν βοίδιον τολμᾷ ἀντιστῆναι αὐτῷ: ἂν δ᾽ ὁ ταῦρος προσελθὼν ἀνθίστηται, λέγε αὐτῷ, ἄν σοι δόξῃς,","st":"3.1"},{"sp":"N","t":"‘σὺ δὲ τίς εἶ;’ καὶ ‘τί σοὶ μέλει;’ ἄνθρωπε, ἐν παντὶ γένει φύεταί τι ἐξαίρετον: ἐν βουσίν, ἐν κυσίν, ἐν μελίσσαις, ἐν ἵπποις. μὴ δὴ λέγε τῷ ἐξαιρέτῳ ‘σὺ οὖν τί εἶ;’ εἰ δὲ μή, ἐρεῖ σοι φωνήν ποθεν λαβὸν ‘ἐγώ εἰμι τοιοῦτον οἷον ἐν ἱματίῳ πορφύρα: μή μ᾽ ἀξίου ὅμοιον εἶναι τοῖς ἄλλοις ἢ τῇ φύσει μου μέμφου, ὅτι με διαφέροντα παρὰ τοὺς ἄλλους ἐποίησεν.’","st":"3.1"},{"sp":"N","t":"τί οὖν; ἐγὼ τοιοῦτος; πόθεν; σὺ γὰρ τοιοῦτος οἷος ἀκούειν τἀληθῆ; ὤφελεν. ἀλλ᾽ ὅμως ἐπεί πως κατεκρίθην πώγωνα ἔχειν πολιὸν καὶ τρίβωνα καὶ σὺ εἰσέρχῃ πρὸς ἐμὲ ὡς πρὸς φιλόσοφον, οὐ χρήσομαί σοι ὠμῶς οὐδ᾽ ἀπογνωστικῶς, ἀλλ᾽ ἐρῶ: νεανίσκε, τίνα θέλεις καλὸν ποιεῖν; γνῶθι πρῶτον τίς εἶ καὶ οὕτως κόσμει σεαυτόν.","st":"3.1"},{"sp":"N","t":"ἄνθρωπος εἶ: τοῦτο δ᾽ ἐστὶ θνητὸν ζῷον χρηστικὸν φαντασίαις λογικῶς. τὸ δὲ λογικῶς τί ἐστιν; φύσει ὁμολογουμένως καὶ τελέως. τί οὖν ἐξαίρετον ἔχεις; τὸ ζῷον; οὔ. τὸ θνητόν; οὔ. τὸ χρηστικὸν φαντασίαις;","st":"3.1"},{"sp":"N","t":"οὔ. τὸ λογικὸν ἔχεις ἐξαίρετον: τοῦτο κόσμει καὶ καλλώπιζε: τὴν κόμην δ᾽ ἄφες τῷ πλάσαντι ὡς αὐτὸς ἠθέλησεν.","st":"3.1"},{"sp":"N","t":"ἄγε, τίνας ἄλλας ἔχεις προσηγορίας; ἀνὴρ εἶ ἢ γυνή; — ἀνήρ. — ἄνδρα οὖν καλλώπιζε, μὴ γυναῖκα. ἐκείνη φύσει λεία γέγονε καὶ τρυφερά: κἂν ἔχῃ τρίχας πολλάς, τέρας ἐστὶ καὶ ἐν τοῖς τέρασιν ἐν Ῥώμῃ δείκνυται.","st":"3.1"},{"sp":"N","t":"τοῦτο δ᾽ ἐπ᾽ ἀνδρός ἐστι τὸ μὴ ἔχειν: κἂν μὲν φύσει μὴ ἔχῃ, τέρας ἐστίν, ἂν δ᾽ αὐτὸς ἑαυτοῦ ἐκκόπτῃ καὶ ἀποτίλλῃ, τί αὐτὸν ποιήσωμεν; ποῦ αὐτὸν δείξωμεν καὶ τί προγράψωμεν; ‘δείξω ὑμῖν ἄνδρα, ὃς θέλει μᾶλλον γυνὴ εἶναι ἢ ἀνήρ.’","st":"3.1"},{"sp":"N","t":"ὦ δεινοῦ θεάματος: οὐδεὶς οὐχὶ θαυμάσει τὴν προγραφήν: νὴ τὸν Δία, οἶμαι ὅτι αὐτοὶ οἱ τιλλόμενοι οὐ παρακολουθοῦντες, ὅτι τοῦτ᾽ αὐτό ἐστιν, ὃ ποιοῦσιν, ποιοῦσιν. ἄνθρωπε, τί ἔχεις ἐγκαλέσαι σου τῇ φύσει;","st":"3.1"},{"sp":"N","t":"ὅτι σε ἄνδρα ἐγέννησεν; τί οὖν; πάσας ἔδει γυναῖκας γεννῆσαι; καὶ τί ἂν ὄφελος ἦν σοι τοῦ κοσμεῖσθαι; τίνι ἂν ἐκοσμοῦ, εἰ πάντες ἦσαν γυναῖκες;","st":"3.1"},{"sp":"N","t":"ἀλλ᾽ οὐκ ἀρέσκει σοι τὸ πραγμάτιον: ὅλον δι᾽ ὅλων αὐτὸ ποίησον: ἆρον — τί ποτ᾽ ἐκεῖνο; — τὸ αἴτιον τῶν τριχῶν: ποίησον εἰς ἅπαντα σαυτὸν γυναῖκα, ἵνα μὴ πλανώμεθα, μὴ τὸ μὲν ἥμισυ ἀνδρός, τὸ δ᾽ ἥμισυ γυναικός.","st":"3.1"},{"sp":"N","t":"τίνι θέλεις ἀρέσαι; τοῖς γυναικαρίοις; ὡς ἀνὴρ αὐτοῖς ἄρεσον. ‘ναί: ἀλλὰ τοῖς λείοις χαίρουσιν.’ οὐκ ἀπάγξῃ; καὶ εἰ τοῖς κιναίδοις ἔχαιρον, ἐγένου ἂν κίναιδος;","st":"3.1"},{"sp":"N","t":"τοῦτό σοι τὸ ἔργον ἐστίν, ἐπὶ τοῦτο ἐγεννήθης, ἵνα σοι αἱ γυναῖκες αἱ ἀκόλαστοι χαίρωσιν;","st":"3.1"},{"sp":"N","t":"τοιοῦτόν σε θῶμεν πολίτην Κορινθίων, κἂν οὕτως τύχῃ, ἀστυνόμον ἢ ἐφήβαρχον ἢ στρατηγὸν ἢ ἀγωνοθέτην;","st":"3.1"},{"sp":"N","t":"ἄγε καὶ γαμήσας τίλλεσθαι μέλλεις; τίνι καὶ ἐπὶ τί; καὶ παιδία ποιήσας εἶτα κἀκεῖνα τιλλόμενα ἡμῖν εἰσάξεις εἰς τὸ πολίτευμα; καλὸς πολίτης καὶ βουλευτὴς καὶ ῥήτωρ. τοιούτους δεῖ νέους εὔχεσθαι ἡμῖν φύεσθαι καὶ ἀνατρέφεσθαι;","st":"3.1"},{"sp":"N","t":"μή, τοὺς θεούς σοι, νεανίσκε: ἀλλ᾽ ἅπαξ ἀκούσας τῶν λόγων τούτων ἀπελθὼν σαυτῷ εἰπὲ ‘ταῦτά μοι Ἐπίκτητος οὐκ εἴρηκεν: πόθεν γὰρ ἐκείνῳ; ἀλλὰ θεός τίς ποτ᾽ εὐμενὴς δι᾽ ἐκείνου. οὐδὲ γὰρ ἂν ἐπῆλθεν Ἐπικτήτῳ ταῦτα εἰπεῖν οὐκ εἰωθότι λέγειν πρὸς οὐδένα.","st":"3.1"},{"sp":"N","t":"ἄγε οὖν τῷ θεῷ πεισθῶμεν, ἵνα μὴ θεοχόλωτοι ὦμεν.’ οὔ: ἀλλ᾽ ἂν μὲν κόραξ κραυγάζων σημαίνῃ σοί τι, οὐχ ὁ κόραξ ἐστὶν ὁ σημαίνων, ἀλλ᾽ ὁ θεὸς δι᾽ αὐτοῦ: ἂν δὲ δι᾽ ἀνθρωπίνης φωνῆς σημαίνῃ τι, τὸν ἄνθρωπον ποιήσει λέγειν σοι ταῦτα, ἵν᾽ ἀγνοῇς τὴν δύναμιν τοῦ δαιμονίου, ὅτι τοῖς μὲν οὕτως, τοῖς δ᾽ ἐκείνως σημαίνει, περὶ δὲ τῶν μεγίστων καὶ κυριωτάτων","st":"3.1"},{"sp":"N","t":"διὰ καλλίστου ἀγγέλου σημαίνει; τί ἐστιν ἄλλο, ὃ λέγει ὁ ποιητής; ἐπεὶ πρό οἱ εἴπομεν ἡμεῖς, Ἑρμείαν πέμψαντες ἐύσκοπον ἀργειφόντην, μήτ᾽ αὐτὸν κτείνειν μήτε μνάασθαι ἄκοιτιν.","st":"3.1"},{"sp":"N","t":"ὁ Ἑρμῆς καταβὰς ἔμελλεν αὐτῷ λέγειν ταῦτα καὶ σοὶ νῦν λέγουσιν οἱ θεοὶ ταῦτα Ἑρμείαν πέμψαντες διάκτορον ἀργειφόντην μὴ ἐκστρέφειν τὰ καλῶς ἔχοντα μηδὲ περιεργάζεσθαι, ἀλλ᾽ ἀφεῖναι τὸν ἄνδρα ἄνδρα, τὴν γυναῖκα γυναῖκα, τὸν καλὸν ἄνθρωπον ὡς καλὸν ἄνθρωπον, τὸν αἰσχρὸν ὡς ἄνθρωπον αἰσχρόν. ὅτι οὐκ εἶ κρέας οὐδὲ τρίχες, ἀλλὰ προαίρεσις:","st":"3.1"},{"sp":"N","t":"ταύτην ἂν σχῇς καλήν, τότ᾽ ἔστι καλός.","st":"3.1"},{"sp":"N","t":"μέχρι δὲ νῦν οὐ τολμῶ σοι λέγειν, ὅτι αἰσχρὸς εἶ: δοκεῖς γάρ μοι πάντα θέλειν ἀκοῦσαι ἢ τοῦτο.","st":"3.1"},{"sp":"N","t":"ἀλλ᾽ ὅρα, τί λέγει Σωκράτης τῷ καλλίστῳ πάντων καὶ ὡραιοτάτῳ Ἀλκιβιάδῃ: ‘πειρῶ οὖν καλὸς εἶναι.’ τί αὐτῷ λέγει; ‘πλάσσε σου τὴν κόμην καὶ τίλλε σου τὰ σκέλη;’ μὴ γένοιτο: ἀλλὰ ‘κόσμει σου τὴν προαίρεσιν, ἔξαιρε τὰ φαῦλα δόγματα.’","st":"3.1"},{"sp":"N","t":"τὸ σωμάτιον οὖν πῶς; ὡς πέφυκεν. ἄλλῳ τούτων ἐμέλησεν: ἐκείνῳ ἐπίστρεψον.","st":"3.1"},{"sp":"N","t":"— τί οὖν; ἀκάθαρτον δεῖ εἶναι; — μὴ γένοιτο: ἀλλ᾽ ὃς εἶ καὶ πέφυκας, τοῦτον κάθαιρε, ἄνδρα ὡς ἄνδρα καθάριον εἶναι, γυναῖκα ὡς γυναῖκα, παιδίον ὡς παιδίον.","st":"3.1"},{"sp":"N","t":"οὔ: ἀλλὰ καὶ τοῦ λέοντος ἐκτίλωμεν τὴν κόμην, ἵνα μὴ ἀκάθαρτος ᾖ, καὶ τοῦ ἀλεκτρυόνος τὸν λόφον: δεῖ γὰρ καὶ τοῦτον καθάριον εἶναι. ἀλλ᾽ ὡς ἀλεκτρυόνα καὶ ἐκεῖνον ὡς λέοντα καὶ τὸν κυνηγετικὸν κύνα ὡς κυνηγετικόν. περὶ τίνα ἀσκεῖσθαι δεῖ τὸν προκόψοντα καὶ ὅτι τῶν κυριωτάτων ἀμελοῦμεν. τρεῖς εἰσι τόποι, περὶ οὓς ἀσκηθῆναι δεῖ τὸν ἐσόμενον καλὸν καὶ ἀγαθόν: ὁ περὶ τὰς ὀρέξεις καὶ τὰς ἐκκλίσεις, ἵνα μήτ᾽ ὀρεγόμενος ἀποτυγχάνῃ μήτ᾽ ἐκκλίνων περιπίπτῃ:","st":"3.1"},{"sp":"N","t":"ὁ περὶ τὰς ὁρμὰς καὶ ἀφορμὰς καὶ ἁπλῶς ὁ περὶ τὸ καθῆκον, ἵνα τάξει, ἵνα εὐλογίστως, ἵνα μὴ ἀμελῶς: τρίτος ἐστὶν ὁ περὶ τὴν ἀνεξαπατησίαν καὶ ἀνεικαιότητα καὶ ὅλως ὁ περὶ τὰς συγκαταθέσεις.","st":"3.2"},{"sp":"N","t":"τούτων κυριώτατος καὶ μάλιστα ἐπείγων ἐστὶν ὁ περὶ τὰ πάθη: πάθος γὰρ ἄλλως οὐ γίνεται εἰ μὴ ὀρέξεως ἀποτυγχανούσης ἢ ἐκκλίσεως περιπιπτούσης. οὗτός ἐστιν ὁ ταραχάς, θορύβους, ἀτυχίας, ὁ δυστυχίας ἐπιφέρων, ὁ πένθη, οἰμωγάς, φθόνους, ὁ φθονερούς, ὁ ζηλοτύπους ποιῶν, δι᾽ ὧν οὐδ᾽ ἀκοῦσαι λόγου δυνάμεθα.","st":"3.2"},{"sp":"N","t":"δεύτερός ἐστιν ὁ περὶ τὸ καθῆκον: οὐ δεῖ γάρ με εἶναι ἀπαθῆ ὡς ἀνδριάντα, ἀλλὰ τὰς σχέσεις τηροῦντα τὰς φυσικὰς καὶ ἐπιθέτους ὡς εὐσεβῆ, ὡς υἱόν, ὡς ἀδελφόν, ὡς πατέρα, ὡς πολίτην.","st":"3.2"},{"sp":"N","t":"τρίτος ἐστὶν ὁ ἤδη τοῖς προκόπτουσιν ἐπιβάλλων, ὁ περὶ τὴν αὐτῶν τούτων ἀσφάλειαν, ἵνα μηδ᾽ ἐν ὕπνοις λάθῃ τις ἀνεξέταστος παρελθοῦσα φαντασία μηδ᾽ ἐν οἰνώσει μηδὲ μελαγχολῶντος. — τοῦτο ὑπὲρ ἡμᾶς, φησίν, ἐστίν.","st":"3.2"},{"sp":"N","t":"— οἱ δὲ νῦν φιλόσοφοι ἀφέντες τὸν πρῶτον τόπον καὶ τὸν δεύτερον καταγίνονται περὶ τὸν τρίτον: μεταπίπτοντας, ἠρωτῆσθαι περαίνοντας, ὑποθετικούς, ψευδομένους.","st":"3.2"},{"sp":"N","t":"— δεῖ γάρ, φησίν, καὶ ἐν ταῖς ὕλαις ταύταις γενόμενον διαφυλάξαι τὸ ἀνεξαπάτητον.","st":"3.2"},{"sp":"N","t":"— τίνα; τὸν καλὸν καὶ ἀγαθόν. σοὶ οὖν τοῦτο λείπει; τὰς ἄλλας ἐκπεπόνηκας; περὶ κερμάτιον ἀνεξαπάτητος εἶ; ἐὰν ἴδῃς κοράσιον καλόν, ἀντέχεις τῇ φαντασίᾳ; ἂν ὁ γείτων σου κληρονομήσῃ, οὐ δάκνῃ; νῦν οὐδὲν ἄλλο σοι λείπει ἢ ἀμεταπτωσία;","st":"3.2"},{"sp":"N","t":"τάλας, αὐτὰ ταῦτα τρέμων μανθάνεις καὶ ἀγωνιῶν, μή τίς σου καταφρονήσῃ, καὶ πυνθανόμενος, μή τίς τι περὶ σοῦ λέγει.","st":"3.2"},{"sp":"N","t":"κἄν τις ἐλθὼν εἴπῃ σοι ὅτι ‘λόγου γινομένου, τίς ἄριστός ἐστι τῶν φιλοσόφων, παρών τις ἔλεγεν, ὅτι εἷς φιλόσοφος ὁ δεῖνα,’ γέγονέ σου τὸ ψυχάριον ἀντὶ δακτυλιαίου δίπηχυ. ἂν δ᾽ ἄλλος παρὼν εἴπῃ ‘οὐδὲν εἴρηκας, οὐκ ἔστιν ἄξιον τοῦ δεῖνος ἀκροᾶσθαι: τί γὰρ οἶδεν; τὰς πρώτας ἀφορμὰς ἔχει, πλέον δ᾽ οὐδέν,’ ἐξέστηκας, ὠχρίακας, εὐθὺς κέκραγας ‘ἐγὼ αὐτῷ δείξω, τίς εἰμι, ὅτι μέγας φιλόσοφος.’","st":"3.2"},{"sp":"N","t":"βλέπεται ἐξ αὐτῶν τούτων. τί θέλεις ἐξ ἄλλων δεῖξαι; οὐκ οἶδας, ὅτι Διογένης τῶν σοφιστῶν τινα οὕτως ἔδειξεν ἐκτείνας τὸν μέσον δάκτυλον, εἶτα ἐκμανέντος αὐτοῦ ‘οὗτός ἐστιν,’ ἔφη, ‘ὁ δεῖνα: ἔδειξα ὑμῖν αὐτόν;’","st":"3.2"},{"sp":"N","t":"ἄνθρωπος γὰρ δακτύλῳ οὐ δείκνυται ὡς λίθος ἢ ὡς ξύλον, ἀλλ᾽ ὅταν τις τὰ δόγματα αὐτοῦ δείξῃ, τότε αὐτὸν ὡς ἄνθρωπον ἔδειξεν.","st":"3.2"},{"sp":"N","t":"βλέπωμεν καὶ σοῦ τὰ δόγματα. μὴ γὰρ οὐ δῆλόν ἐστιν, ὅτι σὺ τὴν προαίρεσιν τὴν σαυτοῦ ἐν οὐδενὶ τίθεσαι, ἔξω δὲ βλέπεις εἰς τὰ ἀπροαίρετα, τί ἐρεῖ ὁ δεῖνα καὶ τίς εἶναι δόξεις, εἰ φιλόλογος, εἰ Χρύσιππον ἀνεγνωκὼς ἢ Ἀντίπατρον; εἰ μὲν γὰρ καὶ Ἀρχέδημον, ἀπέχεις ἅπαντα.","st":"3.2"},{"sp":"N","t":"τί ἔτι ἀγωνιᾷς, μὴ οὐ δείξῃς ἡμῖν, τίς εἶ; θέλεις σοι εἴπω, τίνα ἡμῖν ἔδειξας; ἄνθρωπον παριόντα ταπεινόν, μεμψίμοιρον, ὀξύθυμον, δειλόν, πάντα μεμφόμενον, πᾶσιν ἐγκαλοῦντα, μηδέποτε ἡσυχίαν ἄγοντα, πέρπερον: ταῦτα ἡμῖν ἔδειξας.","st":"3.2"},{"sp":"N","t":"ἄπελθε νῦν καὶ ἀναγίγνωσκε Ἀρχέδημον: εἶτα μῦς ἂν καταπέσῃ καὶ ψοφήσῃ, ἀπέθανες. τοιοῦτος γάρ σε μένει θάνατος, οἷον καὶ τὸν — τίνα ποτ᾽ ἐκεῖνον; — τὸν Κρῖνιν. καὶ ἐκεῖνος μέγα ἐφρόνει, ὅτι ἐνόει Ἀρχέδημον.","st":"3.2"},{"sp":"N","t":"τάλας, οὐ θέλεις ἀφεῖναι ταῦτα τὰ μηδὲν πρὸς σέ; πρέπει ταῦτα τοῖς δυναμένοις δίχα ταραχῆς αὐτὰ μανθάνειν, οἷς ἔξεστιν εἰπεῖν ‘οὐκ ὀργίζομαι, οὐ λυποῦμαι, οὐ φθονῶ, οὐ κωλύομαι, οὐκ ἀναγκάζομαι. τί μοι λοιπόν; εὐσχολῶ, ἡσυχίαν ἄγω.","st":"3.2"},{"sp":"N","t":"ἴδωμεν, πῶς περὶ τὰς μεταπτώσεις τῶν λόγων δεῖ ἀναστρέφεσθαι: ἴδωμεν, πῶς ὑπόθεσίν τις λαβὼν εἰς οὐδὲν ἄτοπον ἀπαχθήσεται.’ ἐκείνων ἐστὶ ταῦτα.","st":"3.2"},{"sp":"N","t":"τοῖς εὖ παθοῦσι πρέπει πῦρ καίειν, ἀριστᾶν, ἂν οὕτως τύχῃ, καὶ ᾁδειν καὶ ὀρχεῖσθαι: βυθιζομένου δὲ τοῦ πλοίου σύ μοι παρελθὼν ἐπαίρεις τοὺς σιφάρους. τίς ὕλη τοῦ ἀγαθοῦ καὶ πρὸς τί μάλιστ᾽ ἀσκητέον. ὕλη τοῦ καλοῦ καὶ ἀγαθοῦ τὸ ἴδιον ἡγεμονικόν, τὸ σῶμα δ᾽ ἰατροῦ καὶ ἀπἀλείπτου, ὁ ἀγρὸς γεωργοῦ ὕλη: ἔργον δὲ καλοῦ καὶ ἀγαθοῦ τὸ χρῆσθαι ταῖς φαντασίαις κατὰ φύσιν.","st":"3.2"},{"sp":"N","t":"πέφυκεν δὲ πᾶσα ψυχὴ ὥσπερ τῷ ἀληθεῖ ἐπινεύειν, πρὸς τὸ ψεῦδος ἀνανεύειν, πρὸς τὸ ἄδηλον ἐπέχειν, οὕτως πρὸς μὲν τὸ ἀγαθὸν ὀρεκτικῶς κινεῖσθαι, πρὸς δὲ τὸ κακὸν ἐκκλιτικῶς, πρὸς δὲ τὸ μήτε κακὸν μήτ᾽ ἀγαθὸν οὐδετέρως.","st":"3.3"},{"sp":"N","t":"ὡς γὰρ τὸ τοῦ Καίσαρος νόμισμα οὐκ ἔξεστιν ἀποδοκιμάσαι τῷ τραπεζίτῃ οὐδὲ τῷ λαχανοπώλῃ, ἀλλ᾽ ἂν δείξῃς, θέλει οὐ θέλει, προέσθαι αὐτὸν δεῖ τὸ ἀντ᾽ αὐτοῦ πωλούμενον, οὕτως ἔχει καὶ ἐπὶ τῆς ψυχῆς.","st":"3.3"},{"sp":"N","t":"τὸ ἀγαθὸν φανὲν εὐθὺς ἐκίνησεν ἐφ᾽ αὑτό, τὸ κακὸν ἀφ᾽ αὑτοῦ. οὐδέποτε δ᾽ ἀγαθοῦ φαντασίαν ἐναργῆ ἀποδοκιμάσει ψυχή, οὐ μᾶλλον ἢ τὸ Καίσαρος νόμισμα. ἔνθεν ἐξήρτηται πᾶσα κίνησις καὶ ἀνθρώπου καὶ θεοῦ.","st":"3.3"},{"sp":"N","t":"διὰ τοῦτο πάσης οἰκειότητος προκρίνεται τὸ ἀγαθόν. οὐδὲν ἐμοὶ καὶ τῷ πατρί, ἀλλὰ τῷ ἀγαθῷ. ‘οὕτως εἶ σκληρός;’ οὕτως γὰρ πέφυκα: τοῦτό μοι τὸ νόμισμα δέδωκεν ὁ θεός.","st":"3.3"},{"sp":"N","t":"διὰ τοῦτο, εἰ τοῦ καλοῦ καὶ δικαίου τὸ ἀγαθὸν ἕτερόν ἐστιν, οἴχεται καὶ πατὴρ καὶ ἀδελφὸς καὶ πατρὶς καὶ πάντα τὰ πράγματα.","st":"3.3"},{"sp":"N","t":"ἀλλ᾽ ἐγὼ τὸ ἐμὸν ἀγαθὸν ὑπερίδω, ἵνα σὺ σχῇς, καὶ παραχωρήσω σοι; ἀντὶ τίνος; ‘πατήρ σου εἰμί.’ ἀλλ᾽ οὐκ ἀγαθόν. ‘ἀδελφός σου εἰμί.’","st":"3.3"},{"sp":"N","t":"ἀλλ᾽ οὐκ ἀγαθόν. ἐὰν δ᾽ ἐν ὀρθῇ προαιρέσει θῶμεν, αὐτὸ τὸ τηρεῖν τὰς σχέσεις ἀγαθὸν γίνεται: καὶ λοιπὸν ὁ τῶν ἐκτός τινων ἐκχωρῶν, οὗτος τοῦ ἀγαθοῦ τυγχάνει.","st":"3.3"},{"sp":"N","t":"‘αἴρει τὰ χρήματα ὁ πατήρ.’ ἀλλ᾽ οὐ βλάπτει. ‘ἕξει τὸ πλέον τοῦ ἀγροῦ ὁ ἀδελφός.’ ὅσον καὶ θέλει. μή τι οὖν τοῦ αἰδήμονος, μή τι τοῦ πιστοῦ, μή τι τοῦ φιλαδέλφου;","st":"3.3"},{"sp":"N","t":"ἐκ ταύτης γὰρ τῆς οὐσίας τίς δύναται ἐκβαλεῖν; οὐδ᾽ ὁ Ζεύς. οὐδὲ γὰρ ἠθέλησεν, ἀλλ᾽ ἐπ᾽ ἐμοὶ αὐτὸ ἐποίησεν καὶ ἔδωκεν οἷον εἶχεν αὐτός, ἀκώλυστον, ἀνανάγκαστον, ἀπαραπόδιστον.","st":"3.3"},{"sp":"N","t":"ὅταν οὖν ἄλλῳ ἄλλο τὸ νόμισμα ᾖ, ἐκεῖνό τις δείξας ἔχει τὸ ἀντ᾽ αὐτοῦ πιπρασκόμενον.","st":"3.3"},{"sp":"N","t":"ἐλήλυθεν εἰς τὴν ἐπαρχίαν κλέπτης ἀνθύπατος. τίνι νομίσματι χρῆται; ἀργυρίῳ. δεῖξον καὶ ἀπόφερε ὃ θέλεις. ἐλήλυθεν μοιχός. τίνι νομίσματι χρῆται; κορασιδίοις. ‘λάβε,’ φησίν, ‘τὸ νόμισμα καὶ πώλησόν μοι τὸ πραγμάτιον.’ δὸς καὶ ἀγόραζε.","st":"3.3"},{"sp":"N","t":"ἄλλος περὶ παιδάρια ἐσπούδακεν. δὸς αὐτῷ τὸ νόμισμα καὶ λάβε ὃ θέλεις. ἄλλος φιλόθηρος. δὸς ἱππάριον καλὸν ἢ κυνάριον: οἰμώζων καὶ στένων πωλήσει ἀντ᾽ αὐτοῦ ὃ θέλεις. ἄλλος γὰρ αὐτὸν ἀναγκάζει ἔσωθεν, ὁ τὸ νόμισμα τοῦτο τεταχώς.","st":"3.3"},{"sp":"N","t":"πρὸς τοῦτο μάλιστα τὸ εἶδος αὑτὸν γυμναστέον. εὐθὺς ὄρθρου προελθὼν ὃν ἂν ἴδῃς, ὃν ἂν ἀκούσῃς, ἐξέταζε, ἀποκρίνου ὡς πρὸς ἐρώτημα. τί εἶδες; καλὸν ἢ καλήν; ἔπαγε τὸν κανόνα. ἀπροαίρετον ἢ προαιρετικόν; ἀπροαίρετον: αἶρε ἔξω.","st":"3.3"},{"sp":"N","t":"τί εἶδες; πενθοῦντ᾽ ἐπὶ τέκνου τελευτῇ; ἔπαγε τὸν κανόνα. ὁ θάνατός ἐστιν ἀπροαίρετον: αἶρε ἐκ τοῦ μέσου. ἀπήντησέ σοι ὕπατος; ἔπαγε τὸν κανόνα. ὑπατεία ποῖόν τι ἐστίν; ἀπροαίρετον ἢ προαιρετικόν; ἀπροαίρετον: αἶρε καὶ τοῦτο, οὐκ ἔστι δόκιμον: ἀπόβαλε, οὐδὲν πρὸς σέ.","st":"3.3"},{"sp":"N","t":"καὶ τοῦτο εἰ ἐποιοῦμεν καὶ πρὸς τοῦτο ἠσκούμεθα καθ᾽ ἡμέραν ἐξ ὄρθρου μέχρι νυκτός, ἐγίνετο ἄν τι, νὴ τοὺς θεούς.","st":"3.3"},{"sp":"N","t":"νῦν δ᾽ εὐθὺς ὑπὸ πάσης φαντασίας κεχηνότες λαμβανόμεθα καὶ μόνον, εἴπερ ἄρα, ἐν τῇ σχολῇ μικρόν τι διεγειρόμεθα: εἶτ᾽ ἐξελθόντες ἂν ἴδωμεν πενθοῦντα, λέγομεν ‘ἀπώλετο:’ ἂν ὕπατον, ‘μακάριος:’ ἂν ἐξωρισμένον, ‘ταλαίπωρος:’ ἂν πένητα,","st":"3.3"},{"sp":"N","t":"‘ἄθλιος, οὐκ ἔχει πόθεν φάγῃ.’ ταῦτ᾽ οὖν ἐκκόπτειν δεῖ τὰ πονηρὰ δόγματα, περὶ τοῦτο συντετάσθαι. τί γάρ ἐστι τὸ κλαίειν καὶ οἰμώζειν; δόγμα. τί δυστυχία; δόγμα. τί στάσις, τί διχόνοια, τί μέμψις, τί κατηγορία, τί ἀσέβεια, τί φλυαρία;","st":"3.3"},{"sp":"N","t":"ταῦτα πάντα δόγματά ἐστι καὶ ἄλλο οὐδὲν καὶ δόγματα περὶ τῶν ἀπροαιρέτων ὡς ὄντων ἀγαθῶν καὶ κακῶν. ταῦτά τις ἐπὶ τὰ προαιρετικὰ μεταθέτω, κἀγὼ αὐτὸν ἐγγυῶμαι ὅτι εὐσταθήσει, ὡς ἂν ἔχῃ τὰ περὶ αὐτόν.","st":"3.3"},{"sp":"N","t":"οἷόν ἐστιν ἡ λεκάνη τοῦ ὕδατος, τοιοῦτον ἡ ψυχή, οἷον ἡ αὐγὴ ἡ προσπίπτουσα τῷ ὕδατι, τοιοῦτον αἱ φαντασίαι.","st":"3.3"},{"sp":"N","t":"ὅταν οὖν τὸ ὕδωρ κινηθῇ, δοκεῖ μὲν καὶ ἡ αὐγὴ κινεῖσθαι, οὐ μέντοι κινεῖται.","st":"3.3"},{"sp":"N","t":"καὶ ὅταν τοίνυν σκοτωθῇ τις, οὐχ αἱ τέχναι καὶ αἱ ἀρεταὶ συγχέονται, ἀλλὰ τὸ πνεῦμα, ἐφ᾽ οὗ εἰσιν: καταστάντος δὲ καθίσταται κἀκεῖνα. πρὸς τὸν ἀκόσμως ἐν θεάτρῳ σπουδάσαντα. τοῦ δ᾽ ἐπιτρόπου τῆς Ἠπείρου ἀκοσμότερον σπουδάσαντος κωμῳδῷ τινι καὶ ἐπὶ τούτῳ δημοσίᾳ λοιδορηθέντος, εἶτα ἑξῆς ἀπαγγείλαντος πρὸς αὐτόν, ὅτι ἐλοιδορήθη, καὶ ἀγανακτοῦντος πρὸς τοὺς λοιδορήσαντας Καὶ τί κακόν, ἔφη, ἐποίουν; ἐσπούδαζον καὶ οὗτοι ὡς καὶ σύ.","st":"3.3"},{"sp":"N","t":"εἰπόντος δ᾽ ἐκείνου Οὕτως οὖν τις σπουδάζει; σέ, ἔφη, βλέποντες τὸν αὐτῶν ἄρχοντα, τοῦ Καίσαρος φίλον καὶ ἐπίτροπον, οὕτως σπουδάζοντα οὐκ ἔμελλον καὶ αὐτοὶ οὕτως σπουδάζειν;","st":"3.4"},{"sp":"N","t":"εἰ γὰρ μὴ δεῖ οὕτως σπουδάζειν, μηδὲ σὺ σπούδαζε: εἰ δὲ δεῖ, τί χαλεπαίνεις, εἴ σε ἐμιμήσαντο; τίνας γὰρ ἔχουσιν μιμήσασθαι οἱ πολλοὶ ἢ τοὺς ὑπερέχοντας ὑμᾶς; εἰς τίνας ἀπίδωσιν ἐλθόντες εἰς τὰ θέατρα ἢ ὑμᾶς;","st":"3.4"},{"sp":"N","t":"‘ὅρα πῶς ὁ ἐπίτροπος τοῦ Καίσαρος θεωρεῖ: κέκραγεν: κἀγὼ τοίνυν κραυγάσω. ἀναπηδᾷ: κἀγὼ ἀναπηδήσω. οἱ δοῦλοι αὐτοῦ διακάθηνται κραυγάζοντες: ἐγὼ δ᾽ οὐκ ἔχω δούλους: ἀντὶ πάντων αὐτὸς ὅσον δύναμαι κραυγάσω.’","st":"3.4"},{"sp":"N","t":"εἰδέναι σε οὖν δεῖ, ὅταν εἰσέρχῃ εἰς τὸ θέατρον, ὅτι κανὼν εἰσέρχῃ καὶ παράδειγμα τοῖς ἄλλοις, πῶς αὐτοὺς δεῖ θεωρεῖν.","st":"3.4"},{"sp":"N","t":"τί οὖν σε ἐλοιδόρουν; ὅτι πᾶς ἄνθρωπος μισεῖ τὸ ἐμποδίζον. ἐκεῖνοι στεφανωθῆναι ἤθελον τὸν δεῖνα, σὺ ἕτερον: ἐκεῖνοι σοὶ ἐνεπόδιζον καὶ σὺ ἐκείνοις. σὺ εὑρίσκου ἰσχυρότερος: ἐκεῖνοι ὃ ἐδύναντο ἐποίουν, ἐλοιδόρουν τὸ ἐμποδίζον.","st":"3.4"},{"sp":"N","t":"τί οὖν θέλεις; ἵνα σὺ μὲν ποιῇς ὃ θέλεις, ἐκεῖνοι δὲ μηδ᾽ εἴπωσιν ἃ θέλουσιν; καὶ τί θαυμαστόν; οἱ γεωργοὶ τὸν Δία οὐ λοιδοροῦσιν, ὅταν ἐμποδίζωνται ὑπ᾽ αὐτοῦ; οἱ ναῦται οὐ λοιδοροῦσι; τὸν Καίσαρα παύονται λοιδοροῦντες;","st":"3.4"},{"sp":"N","t":"τί οὖν; οὐ γιγνώσκει ὁ Ζεύς; τῷ Καίσαρι οὐκ ἀπαγγέλλονται τὰ λεγόμενα; τί οὖν ποιεῖ; οἶδεν ὅτι, ἂν πάντας τοὺς λοιδοροῦντας κολάζῃ, οὐχ ἕξει τίνων ἄρξει.","st":"3.4"},{"sp":"N","t":"τί οὖν; ἔδει εἰσερχόμενον εἰς τὸ θέατρον τοῦτο εἰπεῖν ‘ἄγε ἵνα Σώφρων στεφανωθῇ;’ ἀλλ᾽ ἐκεῖνο ‘ἄγε ἵνα τηρήσω τὴν ἐμαυτοῦ προαίρεσιν ἐπὶ ταύτης τῆς ὕλης κατὰ φύσιν ἔχουσαν.’","st":"3.4"},{"sp":"N","t":"ἐμοὶ παρ᾽ ἐμὲ φίλτερος οὐδείς: γελοῖον οὖν, ἵν᾽ ἄλλος νικήσῃ κωμῳδῶν, ἐμὲ βλάπτεσθαι.","st":"3.4"},{"sp":"N","t":"— τίνα οὖν θέλω νικῆσαι; — τὸν νικῶντα: καὶ οὕτως ἀεὶ νικήσει, ὃν θέλω. — ἀλλὰ θέλω στεφανωθῆναι Σώφρονα. — ἐν οἴκῳ ὅσους θέλεις ἀγῶνας ἄγων ἀνακήρυξον αὐτὸν Νέμεα, Πύθια, Ἴσθμια, Ὀλύμπια: ἐν φανερῷ δὲ μὴ πλεονέκτει μηδ᾽ ὑφάρπαζε τὸ κοινόν. εἰ δὲ μή, ἀνέχου λοιδορούμενος: ὡς,","st":"3.4"},{"sp":"N","t":"ὅταν ταὐτὰ ποιῇς τοῖς πολλοῖς, εἰς ἴσον ἐκείνοις καθιστᾷς σαυτόν. πρὸς τοὺς διὰ νόσον ἀπαλλαττομένους. νοσῶ, φησίν, ἐνθάδε καὶ βούλομαι ἀπιέναι εἰς οἶκον.","st":"3.4"},{"sp":"N","t":"— ἐν οἴκῳ γὰρ ἄνοσος ἦς σύ; οὐ σκοπεῖς, εἴ τι ποιεῖς ἐνθάδε τῶν πρὸς τὴν προαίρεσιν τὴν σαυτοῦ φερόντων, ἵν᾽ ἐπανορθωθῇ; εἰ μὲν γὰρ μηδὲν ἀνύεις, περισσῶς καὶ ἦλθες.","st":"3.5"},{"sp":"N","t":"ἄπιθι, ἐπιμελοῦ τῶν ἐν οἴκῳ. εἰ γὰρ μὴ δύναταί σου τὸ ἡγεμονικὸν σχεῖν κατὰ φύσιν, τό γ᾽ ἀγρίδιον δυνήσεται: τό γε κερμάτιον αὐξήσεις, τὸν πατέρα γηροκομήσεις, ἐν τῇ ἀγορᾷ ἀναστραφήσῃ, ἄρξεις: κακὸς κακῶς τί ποτε ποιήσεις τῶν ἑξῆς.","st":"3.5"},{"sp":"N","t":"εἰ δὲ παρακολουθεῖς σαυτῷ, ὅτι ἀποβάλλεις τινὰ δόγματα φαῦλα καὶ ἄλλ᾽ ἀντ᾽ αὐτῶν ἀναλαμβάνεις καὶ τὴν σαυτοῦ στάσιν μετατέθεικας ἀπὸ τῶν ἀπροαιρέτων ἐπὶ τὰ προαιρετικά, κἄν ποτ᾽ εἴπῃς ‘οἴμοι,’ οὐ λέγεις διὰ τὸν πατέρα, τὸν ἀδελφόν, ἀλλὰ","st":"3.5"},{"sp":"N","t":"‘δι᾽ ἐμέ,’ ἔτι ὑπολογίζῃ νόσον; οὐκ οἶδας, ὅτι καὶ νόσος καὶ θάνατος καταλαβεῖν ἡμᾶς ὀφείλουσίν τί ποτε ποιοῦντας; τὸν γεωργὸν γεωργοῦντα καταλαμβάνουσι, τὸν ναυτικὸν πλέοντα.","st":"3.5"},{"sp":"N","t":"σὺ τί θέλεις ποιῶν καταληφθῆναι; τί ποτε μὲν γὰρ ποιοῦντά σε δεῖ καταληφθῆναι. εἴ τι ἔχεις τούτου κρεῖσσον ποιῶν καταληφθῆναι, ποίει ἐκεῖνο.","st":"3.5"},{"sp":"N","t":"ἐμοὶ μὲν γὰρ καταληφθῆναι γένοιτο μηδενὸς ἄλλου ἐπιμελουμένῳ ἢ τῆς προαιρέσεως τῆς ἐμῆς, ἵν᾽ ἀπαθής, ἵν᾽ ἀκώλυτος, ἵν᾽ ἀνανάγκαστος, ἵν᾽ ἐλεύθερος.","st":"3.5"},{"sp":"N","t":"ταῦτα ἐπιτηδεύων θέλω εὑρεθῆναι, ἵν᾽ εἰπεῖν δύνωμαι τῷ θεῷ ‘μή τι παρέβην σου τὰς ἐντολάς; μή τι πρὸς ἄλλα ἐχρησάμην ταῖς ἀφορμαῖς ἃς ἔδωκας; μή τι ταῖς αἰσθήσεσιν ἄλλως, μή τι ταῖς προλήψεσιν; μή τί σοί ποτ᾽ ἐνεκάλεσα;","st":"3.5"},{"sp":"N","t":"μή τι ἐμεμψάμην σου τὴν διοίκησιν; ἐνόσησα, ὅτε ἠθέλησας: καὶ οἱ ἄλλοι, ἀλλ᾽ ἐγὼ ἑκών. πένης ἐγενόμην σου θέλοντος, ἀλλὰ χαίρων. οὐκ ἦρξα, ὅτι σὺ οὐκ ἠθέλησας: οὐδέποτ᾽ ἐπεθύμησα ἀρχῆς. μή τί με τούτου ἕνεκα στυγνότερον εἶδες; μὴ οὐ προσῆλθόν σοί ποτε φαιδρῷ τῷ προσώπῳ, ἕτοιμος εἴ τι ἐπιτάσσεις, εἴ τι σημαίνεις;","st":"3.5"},{"sp":"N","t":"νῦν με θέλεις ἀπελθεῖν ἐκ τῆς πανηγύρεως: ἄπειμι, χάριν σοι ἔχω πᾶσαν, ὅτι ἠξίωσάς με συμπανηγυρίσαι σοι καὶ ἰδεῖν ἔργα τὰ σὰ καὶ τῇ διοικήσει σου συμπαρακολουθῆσαι σοί.’","st":"3.5"},{"sp":"N","t":"ταῦτά με ἐνθυμούμενον, ταῦτα γράφοντα, ταῦτα ἀναγιγνώσκοντα καταλάβοι ὁ θάνατος.","st":"3.5"},{"sp":"N","t":"ἀλλ᾽ ἡ μήτηρ μου τὴν κεφαλὴν νοσοῦντος οὐ κρατήσει. — ἄπιθι τοίνυν πρὸς τὴν μητέρα: ἄξιος γὰρ εἶ τὴν κεφαλὴν κρατούμενος νοσεῖν.","st":"3.5"},{"sp":"N","t":"— ἀλλ᾽ ἐπὶ κλιναρίου κομψοῦ ἐν οἴκῳ κατεκείμην. — ἄπιθί σου ἐπὶ τὸ κλινάριον: ἢ † ὑγιαίνων ἄξιος εἶ ἐπὶ τοιούτου κατακεῖσθαι. μὴ τοίνυν ἀπόλλυε, ἃ δύνασαι ἐκεῖ ποιεῖν. ἀλλ᾽ ὁ Σωκράτης τί λέγει;","st":"3.5"},{"sp":"N","t":"‘ὥσπερ ἄλλος τις,’ φησίν, ‘χαίρειν τὸν ἀγρὸν τὸν αὑτοῦ ποιῶν κρείσσονα, ἄλλος τὸν ἵππον, οὕτως ἐγὼ καθ᾽ ἡμέραν χαίρω παρακολουθῶν ἐμαυτῷ βελτίονι γινομένῳ.’","st":"3.5"},{"sp":"N","t":"— πρὸς τί; μή τι πρὸς λεξείδια; — ἄνθρωπε, εὐφήμει. — μή τι πρὸς θεωρημάτια; — τί ποιεῖς; — καὶ μὴν οὐ βλέπω,","st":"3.5"},{"sp":"N","t":"τί ἐστιν ἄλλο, περὶ ὃ ἀσχολοῦνται οἱ φιλόσοφοι. — οὐδέν σοι δοκεῖ εἶναι τὸ μηδέποτε ἐγκαλέσαι τινί, μὴ θεῷ, μὴ ἀνθρώπῳ: μὴ μέμψασθαι μηδένα: τὸ αὐτὸ πρόσωπον ἀεὶ καὶ ἐκφέρειν καὶ εἰσφέρειν;","st":"3.5"},{"sp":"N","t":"ταῦτα ἦν, ἃ ᾔδει ὁ Σωκράτης, καὶ ὅμως οὐδέποτε εἶπεν, ὅτι οἶδέν τι ἢ διδάσκει. εἰ δέ τις λεξείδια ᾔτει ἢ θεωρημάτια, ἀπῆγεν πρὸς Πρωταγόραν, πρὸς Ἱππίαν. καὶ γὰρ εἰ λάχανά τις ζητῶν ἐλήλυθεν, πρὸς τὸν κηπουρὸν ἂν αὐτὸν ἀπήγαγεν: τίς οὖν ὑμῶν ἔχει ταύτην τὴν ἐπιβολήν;","st":"3.5"},{"sp":"N","t":"ἐπεί τοι εἰ εἴχετε, καὶ ἐνοσεῖτε ἂν ἡδέως καὶ","st":"3.5"},{"sp":"N","t":"ἐπεινᾶτε καὶ ἀπεθνῄσκετε. εἴ τις ὑμῶν ἠράσθη κορασίου κομψοῦ, οἶδεν ὅτι ἀληθῆ λέγω. σποράδην τινά. πυθομένου δέ τινος, πῶς νῦν μᾶλλον ἐκπεπονημένου τοῦ λόγου πρότερον μείζονες προκοπαὶ ἦσαν,","st":"3.5"},{"sp":"N","t":"κατὰ τί, ἔφη, ἐκπεπόνηται καὶ κατὰ τί μείζους αἱ προκοπαὶ τότε ἦσαν; καθὸ γὰρ νῦν ἐκπεπόνηται, κατὰ τοῦτο καὶ προκοπαὶ νῦν εὑρεθήσονται.","st":"3.6"},{"sp":"N","t":"καὶ νῦν μὲν ὥστε συλλογισμοὺς ἀναλύειν ἐκπεπόνηται καὶ προκοπαὶ γίνονται: τότε δ᾽ ὥστε τὸ ἡγεμονικὸν κατὰ φύσιν ἔχον τηρῆσαι καὶ ἐξεπονεῖτο καὶ προκοπαὶ ἦσαν.","st":"3.6"},{"sp":"N","t":"μὴ οὖν ἐνάλλασσε μηδὲ ζήτει, ὅταν ἄλλο ἐκπονῇς, ἐν ἄλλῳ προκόπτειν. ἀλλ᾽ ἴδε, εἴ τις ἡμῶν πρὸς τούτῳ ὤν, ὥστε κατὰ φύσιν ἔχειν καὶ διεξάγειν, οὐ προκόπτει. οὐδένα γὰρ εὑρήσεις.","st":"3.6"},{"sp":"N","t":"ὁ σπουδαῖος ἀήττητος: † ἢ γὰρ οὐκ ἀγωνίζεται, ὅπου μὴ κρείσσων, εἰ μὴ ὅπου κρείσσων ἐστίν.","st":"3.6"},{"sp":"N","t":"‘εἰ † κατὰ τὸν ἀγρὸν θέλεις, λάβε: λάβε τοὺς οἰκέτας, λάβε τὴν ἀρχήν, λάβε τὸ σωμάτιον. τὴν δ᾽ ὄρεξιν οὐ ποιήσεις ἀποτευκτικὴν οὐδὲ τὴν ἔκκλισιν περιπτωτικήν.’","st":"3.6"},{"sp":"N","t":"εἰς τοῦτον μόνον τὸν ἀγῶνα καθίησιν τὸν περὶ τῶν προαιρετικῶν: πῶς οὖν οὐ μέλλει ἀήττητος εἶναι;","st":"3.6"},{"sp":"N","t":"πυθομένου δέ τινος, τί ἐστιν ὁ κοινὸς νοῦς, Ὥσπερ, φησίν, κοινή τις ἀκοὴ λέγοιτ᾽ ἂν ἡ μόνον φωνῶν διακριτική, ἡ δὲ τῶν φθόγγων οὐκέτι κοινή, ἀλλὰ τεχνική, οὕτως ἐστί τινα, ἃ οἱ μὴ παντάπασιν διεστραμμένοι τῶν ἀνθρώπων κατὰ τὰς κοινὰς ἀφορμὰς ὁρῶσιν. ἡ τοιαύτη κατάστασις κοινὸς νοῦς καλεῖται.","st":"3.6"},{"sp":"N","t":"τῶν νέων τοὺς μαλακοὺς οὐκ ἔστι προτρέψαι ῥᾴδιον: οὐδὲ γὰρ τυρὸν ἀγκίστρῳ λαβεῖν: οἱ δ᾽ εὐφυεῖς, κἂν ἀποτρέπῃς, ἔτι μᾶλλον ἔχονται τοῦ λόγου.","st":"3.6"},{"sp":"N","t":"διὸ καὶ ὁ Ῥοῦφος τὰ πολλὰ ἀπέτρεπεν τούτῳ δοκιμαστηρίῳ χρώμενος τῶν εὐφυῶν καὶ ἀφυῶν. ἔλεγε γὰρ ὅτι ‘ὡς ὁ λίθος, κἂν ἀναβάλῃς, ἐνεχθήσεται κάτω ἐπὶ γῆν κατὰ τὴν αὑτοῦ κατασκευήν, οὕτως καὶ ὁ εὐφυής, ὅσῳ μᾶλλον ἀποκρούεταί τις αὐτόν, τοσούτῳ μᾶλλον νεύει ἐφ᾽ ὃ πέφυκεν.’ πρὸς τὸν διορθωτὴν τῶν ἐλευθέρων πόλεων Ἐπικούρειον ὄντα. τοῦ δὲ διορθωτοῦ εἰσελθόντος πρὸς αὐτὸν （ ἦν δ᾽ οὗτος Ἐπικούρειος ） ἄξιον, ἔφη, τοὺς ἰδιώτας ἡμᾶς παρ᾽ ὑμῶν τῶν φιλοσόφων πυνθάνεσθαι, καθάπερ τοὺς εἰς ξένην πόλιν ἐλθόντας παρὰ τῶν πολιτῶν καὶ εἰδότων, τί κράτιστόν ἐστιν ἐν κόσμῳ, ἵνα καὶ αὐτοὶ ἱστορήσαντες μετίωμεν, ὡς ἐκεῖνοι τὰ ἐν ταῖς πόλεσι, καὶ θεώμεθα.","st":"3.6"},{"sp":"N","t":"ὅτι μὲν γὰρ τρία ἐστὶ περὶ τὸν ἄνθρωπον, ψυχὴ καὶ σῶμα καὶ τὰ ἐκτός, σχεδὸν οὐδεὶς ἀντιλέγει: λοιπὸν ὑμέτερόν ἐστιν ἀποκρίνασθαι, τί ἐστι τὸ κράτιστον. τί ἐροῦμεν τοῖς ἀνθρώποις;","st":"3.7"},{"sp":"N","t":"τὴν σάρκα; καὶ διὰ ταύτην Μάξιμος ἔπλευσεν μέχρι Κασσιόπης χειμῶνος μετὰ τοῦ υἱοῦ προπέμπων, ἵν᾽ ἡσθῇ τῇ σαρκί;","st":"3.7"},{"sp":"N","t":"ἀρνησαμένου δ᾽ ἐκείνου καὶ εἰπόντος Μὴ γένοιτο: οὐ προσήκει περὶ τὸ κράτιστον ἐσπουδακέναι; — πάντων μάλιστα προσήκει. — τί οὖν κρεῖσσον ἔχομεν τῆς σαρκός; — τὴν ψυχήν, ἔφη. — ἀγαθὰ δὲ τὰ τοῦ κρατίστου κρείττονά ἐστιν ἢ τὰ τοῦ φαυλοτέρου;","st":"3.7"},{"sp":"N","t":"— τὰ τοῦ κρατίστου. — ψυχῆς δὲ ἀγαθὰ πότερον προαιρετικά ἐστιν ἢ ἀπροαίρετα; — προαιρετικά. — προαιρετικὸν οὖν ἐστιν ἡ ἡδονὴ ἡ ψυχική;","st":"3.7"},{"sp":"N","t":"— ἔφη. — αὕτη δ᾽ ἐπὶ τίσιν γίνεται; πότερον ἐφ᾽ αὑτῇ; ἀλλ᾽ ἀδιανόητόν ἐστιν: προηγουμένην γάρ τινα ὑφεστάναι δεῖ οὐσίαν τοῦ ἀγαθοῦ, ἧς τυγχάνοντες ἡσθησόμεθα κατὰ ψυχήν. — ὡμολόγει καὶ τοῦτο. — ἐπὶ τίνι οὖν ἡσθησόμεθα ταύτην τὴν ψυχικὴν ἡδονήν;","st":"3.7"},{"sp":"N","t":"εἰ γὰρ ἐπὶ τοῖς ψυχικοῖς ἀγαθοῖς, εὕρηται ἡ οὐσία τοῦ ἀγαθοῦ. οὐ γὰρ δύναται ἄλλο μὲν εἶναι ἀγαθόν, ἄλλο δ᾽ ἐφ᾽ ᾧ εὐλόγως ἐπαιρόμεθα, οὐδὲ τοῦ προηγουμένου μὴ ὄντος ἀγαθοῦ τὸ ἐπιγέννημα ἀγαθὸν εἶναι. ἵνα γὰρ εὔλογον ᾖ τὸ ἐπιγέννημα, τὸ προηγούμενον δεῖ ἀγαθὸν εἶναι.","st":"3.7"},{"sp":"N","t":"ἀλλ᾽ οὐ μὴ εἴπητε φρένας ἔχοντες: ἀνακόλουθα γὰρ ἐρεῖτε καὶ Ἐπικούρῳ καὶ τοῖς ἄλλοις ὑμῶν δόγμασιν.","st":"3.7"},{"sp":"N","t":"ὑπολείπεται λοιπὸν ἐπὶ τοῖς σωματικοῖς ἥδεσθαι τὴν κατὰ ψυχὴν ἡδονήν: πάλιν ἐκεῖνα γίνεται προηγούμενα καὶ οὐσία τοῦ ἀγαθοῦ.","st":"3.7"},{"sp":"N","t":"διὰ τοῦτο ἀφρόνως ἐποίησε Μάξιμος, εἰ δι᾽ ἄλλο τι ἔπλευσεν ἢ διὰ τὴν σάρκα, τοῦτ᾽ ἔστι διὰ τὸ κράτιστον.","st":"3.7"},{"sp":"N","t":"ἀφρόνως δὲ ποιεῖ καὶ εἰ ἀπέχεται τῶν ἀλλοτρίων δικαστὴς ὢν καὶ δυνάμενος λαμβάνειν. ἀλλ᾽ ἄν σοι δόξῃ, ἐκεῖνο μόνον σκεπτώμεθα, ἵνα κεκρυμμένως, ἵν᾽ ἀσφαλῶς, ἵνα μή τις γνῷ.","st":"3.7"},{"sp":"N","t":"τὸ γὰρ κλέψαι οὐδ᾽ αὐτὸς Ἐπίκουρος ἀποφαίνει κακόν, ἀλλὰ τὸ ἐμπεσεῖν: καὶ ὅτι πίστιν περὶ τοῦ λαθεῖν λαβεῖν ἀδύνατον, διὰ τοῦτο λέγει","st":"3.7"},{"sp":"N","t":"‘μὴ κλέπτετε.’ ἀλλ᾽ ‘ἐγώ σοι λέγω, ὅτι ἐὰν κομψῶς καὶ περιεσταλμένως γίνηται, λησόμεθα:’ εἶτα καὶ ‘φίλους ἐν τῇ Ῥώμῃ ἔχομεν δυνατοὺς καὶ φίλιας’ καὶ ‘οἱ Ἕλληνες ἀδρανεῖς εἰσιν: οὐδεὶς τολμήσει ἀναβῆναι τούτου ἕνεκα.’","st":"3.7"},{"sp":"N","t":"τί ἀπέχῃ τοῦ ἰδίου ἀγαθοῦ; ἄφρον ἐστὶ τοῦτο, ἠλίθιόν ἐστιν. ἀλλ᾽ οὐδ᾽ ἂν λέγῃς μοι, ὅτι ἀπέχῃ, πιστεύσω σοι.","st":"3.7"},{"sp":"N","t":"ὡς γὰρ ἀδύνατόν ἐστι τῷ ψευδεῖ φαινομένῳ συγκαταθέσθαι καὶ ἀπὸ τοῦ ἀληθοῦς ἀπονεῦσαι, οὕτως ἀδύνατόν ἐστι τοῦ φαινομένου ἀγαθοῦ ἀποστῆναι. ὁ πλοῦτος δ᾽ ἀγαθὸν καὶ οἱονανεὶ τὸ ποιητικώτατόν γε τῶν ἡδονῶν.","st":"3.7"},{"sp":"N","t":"διὰ τί μὴ περιποιήσῃ αὐτόν; διὰ τί δὲ μὴ τὴν τοῦ γείτονος γυναῖκα διαφθείρωμεν, ἂν δυνώμεθα λαθεῖν, ἂν δὲ φλυαρῇ ὁ ἀνήρ, καὶ αὐτὸν προσεκτραχηλίσωμεν;","st":"3.7"},{"sp":"N","t":"εἰ θέλεις εἶναι φιλόσοφος οἷος δεῖ, εἴ γε τέλειος, εἰ ἀκολουθῶν σου τοῖς δόγμασιν: εἰ δὲ μή, οὐδὲν διοίσεις ἡμῶν τῶν λεγομένων Στωικῶν: καὶ αὐτοὶ γὰρ ἄλλα λέγομεν, ἄλλα δὲ ποιοῦμεν.","st":"3.7"},{"sp":"N","t":"ἡμεῖς λέγομεν τὰ καλά, ποιοῦμεν τὰ αἰσχρά: σὺ τὴν ἐναντίαν διαστροφὴν ἔσῃ διεστραμμένος δογματίζων τὰ αἰσχρά, ποιῶν τὰ καλά. τὸν θεόν σοι, ἐπινοεῖς Ἐπικουρείων πόλιν;","st":"3.7"},{"sp":"N","t":"‘ἐγὼ οὐ γαμῶ.’ ‘οὐδ᾽ ἐγώ: οὐ γὰρ γαμητέον.’ ἀλλ᾽ οὐδὲ παιδοποιητέον, ἀλλ᾽ οὐδὲ πολιτευτέον. τί οὖν γένηται; πόθεν οἱ πολῖται; τίς αὐτοὺς παιδεύσει; τίς ἐφήβαρχος, τίς γυμνασίαρχος; τί δὲ καὶ παιδεύσει αὐτούς; ἃ Λακεδαιμόνιοι ἐπαιδεύοντο ἢ Ἀθηναῖοι;","st":"3.7"},{"sp":"N","t":"λάβε μοι νέον, ἄγαγε κατὰ τὰ δόγματά σου. πονηρά ἐστι τὰ δόγματα, ἀνατρεπτικὰ πόλεως, λυμαντικὰ οἴκων, οὐδὲ γυναιξὶ πρέποντα. ἄφες ταῦτ᾽, ἄνθρωπε.","st":"3.7"},{"sp":"N","t":"ζῇς ἐν ἡγεμονούσῃ πόλει: ἄρχειν σε δεῖ, κρίνειν δικαίως, ἀπέχεσθαι τῶν ἀλλοτρίων, σοὶ καλὴν γυναῖκα φαίνεσθαι μηδεμίαν ἢ τὴν σήν, καλὸν παῖδα μηδένα, καλὸν ἀργύρωμα μηδέν, χρύσωμα μηδέν. τούτοις σύμφωνα δόγματα ζήτησον,","st":"3.7"},{"sp":"N","t":"ἀφ᾽ ὧν ὁρμώμενος ἡδέως ἀφέξῃ πραγμάτων οὕτως πιθανῶν πρὸς τὸ ἀγαγεῖν καὶ νικῆσαι.","st":"3.7"},{"sp":"N","t":"ἂν δὲ πρὸς τῇ πιθανότητι τῇ ἐκείνων καὶ φιλοσοφίαν τινά ποτε ταύτην ἐξευρηκότες ὦμεν συνεπωθοῦσαν ἡμᾶς ἐπ᾽ αὐτὰ καὶ ἐπιρρωννύουσαν, τί γένηται;","st":"3.7"},{"sp":"N","t":"ἐν τορεύματι τί κράτιστόν ἐστιν, ὁ ἄργυρος ἢ ἡ τέχνη; χειρὸς οὐσία μὲν ἡ σάρξ, προηγούμενα δὲ τὰ χειρὸς ἔργα.","st":"3.7"},{"sp":"N","t":"οὐκοῦν καὶ καθήκοντα τρισσά: τὰ μὲν πρὸς τὸ εἶναι, τὰ δὲ πρὸς τὸ ποιὰ εἶναι, τὰ δ᾽ αὐτὰ τὰ προηγούμενα. οὕτως καὶ ἀνθρώπου οὐ τὴν ὕλην δεῖ τιμᾶν, τὰ σαρκίδια, ἀλλὰ τὰ προηγούμενα.","st":"3.7"},{"sp":"N","t":"τίνα ἐστὶ ταῦτα; πολιτεύεσθαι, γαμεῖν, παιδοποιεῖσθαι, θεὸν σέβειν, γονέων ἐπιμελεῖσθαι, καθόλου ὀρέγεσθαι, ἐκκλίνειν, ὁρμᾶν, ἀφορμᾶν, ὡς ἕκαστον τούτων δεῖ ποιεῖν, ὡς πεφύκαμεν. πεφύκαμεν δὲ πῶς;","st":"3.7"},{"sp":"N","t":"ὡς ἐλεύθεροι, ὡς γενναῖοι, ὡς αἰδήμονες. ποῖον γὰρ ἄλλο ζῷον ἐρυθριᾷ, ποῖον αἰσχροῦ φαντασίαν λαμβάνει;","st":"3.7"},{"sp":"N","t":"τὴν ἡδονὴν δ᾽ ὑπόταξαι τούτοις ὡς διάκονον, ὡς ὑπηρέτιν, ἵνα προθυμίας ἐκκαλέσηται, ἵν᾽ ἐν τοῖς κατὰ φύσιν ἔργοις παρακρατῇ. ἀλλ᾽ ἐγὼ πλούσιός εἰμι καὶ οὐδενὸς χρεία μοί ἐστιν.","st":"3.7"},{"sp":"N","t":"— τί οὖν ἔτι προσποιῇ φιλοσοφεῖν; ἀρκεῖ τὰ χρυσώματα καὶ τὰ ἀργυρώματα: τί σοι χρεία δογμάτων;","st":"3.7"},{"sp":"N","t":"— ἀλλὰ καὶ κριτής εἰμι τῶν Ἑλλήνων. — οἶδας κρίνειν; τί σε ἐποίησεν εἰδέναι; — Καῖσάρ μοι κωδίκελλον ἔγραψεν. — Γραψάτω σοι, ἵνα κρίνῃς περὶ τῶν μουσικῶν: καὶ τί σοι ὄφελος;","st":"3.7"},{"sp":"N","t":"ὅμως δὲ πῶς κριτὴς ἐγένου; τὴν τίνος χεῖρα καταφιλήσας, τὴν Συμφόρου ἢ τὴν Νουμηνίου; τίνος πρὸ τοῦ κοιτῶνος κοιμηθείς; τίνι πέμψας δῶρα; εἶτα οὐκ αἰσθάνῃ, ὅτι τοσούτου ἄξιόν ἐστι κριτὴν εἶναι ὅσου Νουμήνιος; — ἀλλὰ δύναμαι ὃν θέλω εἰς φυλακὴν βαλεῖν.","st":"3.7"},{"sp":"N","t":"— ὡς λίθον. — ἀλλὰ δύναμαι ξυλοκοπῆσαι ὃν θέλω. — ὡς ὄνον. οὐκ ἔστι τοῦτο ἀνθρώπων ἀρχή.","st":"3.7"},{"sp":"N","t":"ὡς λογικῶν ἡμῶν ἄρξον δεικνὺς ἡμῖν τὰ συμφέροντα καὶ ἀκολουθήσομεν: δείκνυε τὰ ἀσύμφορα καὶ ἀποστραφησόμεθα.","st":"3.7"},{"sp":"N","t":"ζηλωτὰς ἡμᾶς κατασκεύασον σεαυτοῦ ὡς Σωκράτης ἑαυτοῦ. ἐκεῖνος ἦν ὁ ὡς ἀνθρώπων ἄρχων, ὁ κατεσκευακὼς ὑποτεταχότας αὐτῷ τὴν ὄρεξιν τὴν αὑτῶν, τὴν ἔκκλισιν, τὴν ὁρμήν, τὴν ἀφορμήν.","st":"3.7"},{"sp":"N","t":"‘τοῦτο ποίησον, τοῦτο μὴ ποιήσῃς: εἰ δὲ μή, εἰς φυλακήν σε βαλῶ.’ οὐκέτι ὡς λογικῶν ἡ ἀρχὴ γίνεται.","st":"3.7"},{"sp":"N","t":"ἀλλ᾽ ‘ὡς ὁ Ζεὺς διέταξεν, τοῦτο ποίησον: ἂν δὲ μὴ ποιήσῃς, ζημιωθήσῃ, βλαβήσῃ.’ ποίαν βλάβην; ἄλλην οὐδεμίαν, ἀλλὰ τὸ μὴ ποιῆσαι ἃ δεῖ: ἀπολέσεις τὸν πιστόν, τὸν αἰδήμονα, τὸν κόσμιον. τούτων ἄλλας βλάβας μείζονας μὴ ζήτει. πῶς πρὸς τὰς φαντασίας γυμναστέον. ὡς πρὸς τὰ ἐρωτήματα τὰ σοφιστικὰ γυμναζόμεθα, οὕτως καὶ πρὸς τὰς φαντασίας καθ᾽ ἡμέραν ἔδει γυμνάζεσθαι: προτείνουσι γὰρ ἡμῖν καὶ αὗται ἐρωτήματα.","st":"3.7"},{"sp":"N","t":"ὁ υἱὸς ἀπέθανε τοῦ δεῖνος. ἀπόκριναι ‘ἀπροαίρετον, οὐ κακόν.’ ὁ πατὴρ τὸν δεῖνα ἀποκληρονόμον ἀπέλειπεν. τί σοι δοκεῖ; ‘ἀπροαίρετον, οὐ κακόν.’ Καῖσαρ αὐτὸν κατέκρινεν.","st":"3.8"},{"sp":"N","t":"‘ἀπροαίρετον, οὐ κακόν.’ ἐλυπήθη ἐπὶ τούτοις. ‘προαιρετικόν, κακόν.’ γενναίως ὑπέμεινεν. ‘προαιρετικόν, ἀγαθόν.’","st":"3.8"},{"sp":"N","t":"κἂν οὕτως ἐθιζώμεθα, προκόψομεν: οὐδέποτε γὰρ ἄλλῳ συγκαταθησόμεθα ἢ οὗ φαντασία καταληπτικὴ γίνεται.","st":"3.8"},{"sp":"N","t":"ὁ υἱὸς ἀπέθανε. τί ἐγένετο; ὁ υἱὸς ἀπέθανεν. ἄλλο οὐδέν; οὐδεέν. τὸ πλοῖον ἀπώλετο. τί ἐγένετο; τὸ πλοῖον ἀπώλετο. εἰς φυλακὴν ἀπήχθη. τί γέγονεν; εἰς φυλακὴν ἀπήχθη. τὸ δ᾽ ὅτι ‘κακῶς πέπραχεν’","st":"3.8"},{"sp":"N","t":"ἐξ αὑτοῦ ἕκαστος προστίθησιν. ‘ἀλλ᾽ οὐκ ὀρθῶς ταῦτα ὁ Ζεὺς ποιεῖ.’ διὰ τί; ὅτι σε ὑπομενητικὸν ἐποίησεν, ὅτι μεγαλόψυχον, ὅτι ἀφεῖλεν αὐτῶν τὸ εἶναι κακά, ὅτι ἔξεστίν σοι πάσχοντι ταῦτα εὐδαιμονεῖν, ὅτι σοι τὴν θύραν ἤνοιξεν, ὅταν σοι μὴ ποιῇ; ἄνθρωπε, ἔξελθε καὶ μὴ ἐγκάλει.","st":"3.8"},{"sp":"N","t":"πῶς ἔχουσι Ῥωμαῖοι πρὸς φιλοσόφους ἂν θέλῃς γνῶναι, ἄκουσον. Ἰταλικὸς ὁ μάλιστα δοκῶν αὐτῶν φιλόσοφος εἶναι παρόντος ποτέ μου χαλεπήνας τοῖς ἰδίοις, ὡς ἀνήκεστα πάσχων, ‘οὐ δύναμαι,’ ἔφη, ‘φέρειν: ἀπόλλυτέ με, ποιήσετέ με τοιοῦτον γενέσθαι,’ δείξας ἐμέ. πρός τινα ῥήτορα ἀνιόντα εἰς Ῥώμην ἐπὶ δίκῃ. εἰσελθόντος δέ τινος πρὸς αὐτόν, ὃς εἰς Ῥώμην ἀνῄει δίκην ἔχων περὶ τιμῆς τῆς αὑτοῦ, πυθόμενος τὴν αἰτίαν, δι᾽ ἣν ἄνεισιν, ἐπερωτήσαντος ἐκείνου, τίνα γνώμην ἔχει περὶ τοῦ πράγματος,","st":"3.8"},{"sp":"N","t":"εἴ μου πυνθάνῃ, τί πράξεις ἐν Ῥώμῃ, φησίν, πότερον κατορθώσεις ἢ ἀποτεύξῃ, θεώρημα πρὸς τοῦτο οὐκ ἔχω: εἰ δὲ πυνθάνῃ, πῶς πράξεις, τοῦτο εἰπεῖν, ὅτι, εἰ μὲν ὀρθὰ δόγματα ἔχεις, καλῶς, εἰ δὲ φαῦλα, κακῶς. παντὶ γὰρ αἴτιον τοῦ πράσσειν τι δόγμα.","st":"3.9"},{"sp":"N","t":"τί γάρ ἐστιν, ὃ ἐπεθύμησας προστάτης χειροτονηθῆναι Κνωσίων; τὸ δόγμα. τί ἐστιν, δι᾽ ὃ νῦν εἰς Ῥώμην ἀνέρχῃ; τὸ δόγμα. καὶ μετὰ χειμῶνος καὶ κινδύνου καὶ ἀναλωμάτων; — ἀνάγκη γάρ ἐστιν. — τίς σοι λέγει τοῦτο;","st":"3.9"},{"sp":"N","t":"τὸ δόγμα. οὐκοῦν εἰ πάντων αἴτια τὰ δόγματα, φαῦλα δέ τις ἔχει δόγματα, οἷον ἂν ᾖ τὸ αἴτιον, τοιοῦτον καὶ τὸ ἀποτελούμενον.","st":"3.9"},{"sp":"N","t":"ἆρ᾽ οὖν πάντες ἔχομεν ὑγιῆ δόγματα καὶ σὺ καὶ ὁ ἀντίδικός σου; καὶ πῶς διαφέρεσθε; ἀλλὰ σὺ μᾶλλον ἢ ἐκεῖνος; διὰ τί; δοκεῖ σοι. κἀκείνῳ καὶ τοῖς μαινομένοις. τοῦτο πονηρὸν κριτήριον. ἀλλὰ δεῖξόν μοι,","st":"3.9"},{"sp":"N","t":"ὅτι ἐπίσκεψίν τινα καὶ ἐπιμέλειαν πεποίησαι τῶν σαυτοῦ δογμάτων. καὶ ὡς νῦν εἰς Ῥώμην πλεῖς ἐπὶ τῷ προστάτης εἶναι Κνωσίων καὶ οὐκ ἐξαρκεῖ σοι μένειν ἐν οἴκῳ τὰς τιμὰς ἔχοντι ἃς εἶχες, ἀλλὰ μείζονός τινος ἐπιθυμεῖς καὶ ἐπιφανεστέρου, πότε οὕτως ἔπλευσας ὑπὲρ τοῦ τὰ δόγματα ἐπισκέψασθαι τὰ σαυτοῦ καὶ εἴ τι φαῦλον ἔχεις, ἐκβαλεῖν;","st":"3.9"},{"sp":"N","t":"τίνι προσελήλυθας τούτου ἕνεκα; ποῖον χρόνον ἐπέταξας σαυτῷ, ποίαν ἡλικίαν; ἔπελθέ σου τοὺς χρόνους, εἰ ἐμὲ αἰσχύνῃ, αὐτὸς πρὸς σαυτόν.","st":"3.9"},{"sp":"N","t":"ὅτε παῖς ἦς, ἐξήταζες τὰ σαυτοῦ δόγματα; οὐχὶ δ᾽ ὡς πάντα ποιεῖς, ἐποίεις ἃ ἐποίεις; ὅτε δὲ μειράκιον ἤδη καὶ τῶν ῥητόρων ἤκουες καὶ αὐτὸς ἐμελέτας, τί σοι λείπειν ἐφαντάζου;","st":"3.9"},{"sp":"N","t":"ὅτε δὲ νεανίσκος καὶ ἤδη ἐπολιτεύου καὶ δίκας αὐτὸς ἔλεγες καὶ εὐδοκίμεις, τίς σοι ἔτι ἴσος ἐφαίνετο; ποῦ δ᾽ ἂν ἠνέσχου ὑπό τινος ἐξεταζόμενος, ὅτι πονηρὰ ἔχεις δόγματα;","st":"3.9"},{"sp":"N","t":"τί οὖν σοι θέλεις εἴπω; — βοήθησόν μοι εἰς τὸ πρᾶγμα. — οὐκ ἔχω πρὸς τοῦτο θεωρήματα: οὐδὲ σύ, εἰ τούτου ἕνεκα ἐλήλυθας πρὸς ἐμέ, ὡς πρὸς φιλόσοφον ἐλήλυθας, ἀλλ᾽ ὡς πρὸς λαχανοπώλην, ἀλλ᾽ ὡς πρὸς σκυτέα.","st":"3.9"},{"sp":"N","t":"— πρὸς τί οὖν ἔχουσιν οἱ φιλόσοφοι θεωρήματα; — πρὸς τοῦτο, ὅ τι ἂν ἀποβῇ, τὸ ἡγεμονικὸν ἡμῶν κατὰ φύσιν ἔχειν καὶ διεξάγειν. μικρόν σοι δοκεῖ τοῦτο; — οὔ: ἀλλὰ τὸ μέγιστον. — τί οὖν; ὀλίγου χρόνου χρείαν ἔχει καὶ ἔστι παρερχόμενον αὐτὸ λαβεῖν; εἰ δύνασαι, λάμβανε. εἶτ᾽ ἐρεῖς","st":"3.9"},{"sp":"N","t":"‘συνέβαλλον Ἐπικτήτῳ ὡς λίθῳ, ὡς ἀνδριάντι.’ εἶδες γάρ με καὶ πλέον οὐδέν. ἀνθρώπῳ δ᾽ ὡς ἀνθρώπῳ συμβάλλει ὁ τὰ δόγματα αὐτοῦ καταμανθάνων καὶ ἐν τῷ μέρει τὰ ἴδια δεικνύων.","st":"3.9"},{"sp":"N","t":"κατάμαθέ μου τὰ δόγματα, δεῖξόν μοι τὰ σὰ καὶ οὕτως λέγε συμβεβληκέναι μοι. ἐλέγξωμεν ἀλλήλους: εἴ τι ἔχω κακὸν δόγμα, ἄφελε αὐτό: εἴ τι ἔχεις, θὲς εἰς τὸ μέσον. τοῦτό ἐστι φιλοσόφῳ συμβάλλειν.","st":"3.9"},{"sp":"N","t":"οὔ: ἀλλὰ ‘πάροδός ἐστι καὶ ἕως τὸ πλοῖον μισθούμεθα, δυνάμεθα καὶ Ἐπίκτητον ἰδεῖν: ἴδωμεν, τί ποτε λέγει.’ εἶτ᾽ ἐξελθὼν ‘οὐδὲν ἦν ὁ Ἐπίκτητος, ἐσολοίκιζεν, ἐβαρβάριζεν.’ τίνος γὰρ ἄλλου κριταὶ εἰσέρχεσθε;","st":"3.9"},{"sp":"N","t":"‘ἀλλ᾽ ἂν πρὸς τούτοις,’ φησίν, ‘ὦ, ἀγρὸν οὐχ ἕξω ὡς οὐδὲ σύ, ποτήρια ἀργυρᾶ οὐχ ἕξω ὡς οὐδὲ σύ, κτήνη καλὰ ὡς οὐδὲ σύ.’","st":"3.9"},{"sp":"N","t":"πρὸς ταῦτα ἴσως ἀρκεῖ ἐκεῖνο εἰπεῖν ὅτι ‘ἀλλὰ χρείαν αὐτῶν οὐκ ἔχω: σὺ δ᾽ ἂν πολλὰ κτήσῃ, ἄλλων χρείαν ἔχεις, θέλεις οὐ θέλεις, πτωχότερός μου.’","st":"3.9"},{"sp":"N","t":"— τίνος οὖν ἔχω χρείαν; — τοῦ σοὶ μὴ παρόντος: τοῦ εὐσταθεῖν, τοῦ κατὰ φύσιν ἔχειν τὴν διάνοιαν, τοῦ μὴ ταράττεσθαι.","st":"3.9"},{"sp":"N","t":"πάτρων, οὐ πάτρων, τί μοι μέλει; σοὶ μέλει. πλουσιώτερός σου εἰμί: οὐκ ἀγωνιῶ, τί φρονήσει περὶ ἐμοῦ ὁ Καῖσαρ: οὐδένα κολακεύω τούτου ἕνεκα. ταῦτα ἔχω ἀντὶ τῶν ἀργυρωμάτων, ἀντὶ τῶν χρυσωμάτων. σὺ χρυσᾶ σκεύη, ὀστράκινον τὸν λόγον, τὰ δόγματα, τὰς συγκαταθέσεις, τὰς ὁρμάς, τὰς ὀρέξεις.","st":"3.9"},{"sp":"N","t":"ὅταν δὲ ταῦτα ἔχω κατὰ φύσιν, διὰ τί μὴ φιλοτεχνήσω καὶ περὶ τὸν λόγον; εὐσχολῶ γάρ: οὐ περισπᾶταί μου ἡ διάνοια. τί ποιήσω μὴ περισπώμενος; τούτου τί ἀνθρωπικώτερον ἔχω;","st":"3.9"},{"sp":"N","t":"ὑμεῖς ὅταν μηδὲν ἔχητε, ταράσσεσθε, εἰς θέατρον εἰσέρχεσθε ἢ ἀναλύετε: διὰ τί ὁ φιλόσοφος μὴ ἐξεργάσηται τὸν αὑτοῦ λόγον;","st":"3.9"},{"sp":"N","t":"σὺ κρυστάλλινα, ἐγὼ τὰ τοῦ Ψευδομένου: σὺ μούρρινα, ἐγὼ τὰ τοῦ Ἀποφάσκοντος. σοὶ πάντα μικρὰ φαίνεται ἃ ἔχεις, ἐμοὶ τὰ ἐμὰ πάντα μεγάλα. ἀπλήρωτός σου ἐστὶν ἡ ἐπιθυμία, ἡ ἐμὴ πεπλήρωται.","st":"3.9"},{"sp":"N","t":"τοῖς παιδίοις εἰς στενόβρογχον κεράμιον καθιεῖσιν τὴν χεῖρα καὶ ἐκφέρουσιν ἰσχαδοκάρυα τοῦτο συμβαίνει: ἂν πληρώσῃ τὴν χεῖρα, ἐξενεγκεῖν οὐ δύναται, εἶτα κλάει. ἄφες ὀλίγα ἐξ αὐτῶν καὶ ἐξοίσεις. καὶ σὺ ἄφες τὴν ὄρεξιν: μὴ πολλῶν ἐπιθύμει καὶ οἴσεις. πῶς φέρειν δεῖ τὰς νόσους. ἑκάστου δόγματος ὅταν ἡ χρεία παρῇ, πρόχειρον αὐτὸ ἔχειν δεῖ: ἐπ᾽ ἀρίστῳ τὰ περὶ ἀρίστου, ἐν βαλανείῳ τὰ περὶ βαλανείου, ἐν κοίτῃ τὰ περὶ κοίτης.","st":"3.9"},{"sp":"N","t":"μηδ᾽ ὕπνον μαλακοῖσιν ἐπ᾽ ὄμμασι προσδέξασθαι, πρὶν τῶν ἡμερινῶν ἔργων λογίσασθαι ἕκαστα:","st":"3.10"},{"sp":"N","t":"πῇ παρέβην; τί δ᾽ ἔρεξα; τί μοι δέον οὐ τετέλεσται; ἀρξάμενος δ᾽ ἀπὸ τοῦδε † ἐπέξιθι: καὶ μετέπειτα δειλὰ μὲν † ῥέξας ἐπιπλήσσεο, χρηστὰ δὲ τέρπου. καὶ τούτους τοὺς στίχους κατέχειν χρηστικῶς,","st":"3.10"},{"sp":"N","t":"οὐχ ἵνα δι᾽ αὐτῶν ἀναφωνῶμεν, ὡς διὰ τοῦ Παιὰν Ἄπολλον. πάλιν ἐν πυρετῷ τὰ πρὸς τοῦτο:","st":"3.10"},{"sp":"N","t":"μή, ἂν πυρέξωμεν, ἀφιέναι πάντα καὶ ἐπιλανθάνεσθαι: ‘ἂν ἐγὼ ἔτι φιλοσοφήσω, ὃ θέλει γινέσθω. πού ποτ᾽ ἀπελθόντα τοῦ σωματίου ἐπιμελεῖσθαι †’","st":"3.10"},{"sp":"N","t":"εἴ τε καὶ πυρετὸς οὐκ ἔρχεται. τὸ δὲ φιλοσοφῆσαι τί ἐστιν; οὐχὶ παρασκευάσασθαι πρὸς τὰ συμβαίνοντα; οὐ παρακολουθεῖς οὖν, ὅτι τοιοῦτόν τι λέγεις ‘ἂν ἔτι ἐγὼ παρασκευάσωμαι πρὸς τὸ πρᾴως φέρειν τὰ συμβαίνοντα, ὃ θέλει γινέσθω;’ οἷον εἴ τις πληγὰς λαβὼν ἀποσταίη τοῦ παγκρατιάζειν.","st":"3.10"},{"sp":"N","t":"ἀλλ᾽ ἐκεῖ μὲν ἔξεστι καταλῦσαι καὶ μὴ δέρεσθαι, ἐνθάδε δ᾽ ἂν καταλύσωμεν φιλοσοφοῦντες, τί ὄφελος; τί οὖν δεῖ λέγειν αὐτὸν ἐφ᾽ ἑκάστου τῶν τραχέων; ὅτι ‘ἕνεκα τούτου ἐγυμναζόμην, ἐπὶ τοῦτο ἤσκουν.’","st":"3.10"},{"sp":"N","t":"ὁ θεός σοι λέγει ‘δός μοι ἀπόδειξιν, εἰ νομίμως ἤθλησας, εἰ ἔφαγες ὅσα δεῖ, εἰ ἐγυμνάσθης, εἰ τοῦ ἀλείπτου ἤκουσας:’ εἶτ᾽ ἐπ᾽ αὐτοῦ τοῦ ἔργου καταμαλακίζῃ; νῦν τοῦ πυρέττειν καιρός ἐστιν, τοῦτο καλῶς γινέσθω: τοῦ διψᾶν, δίψα καλῶς: τοῦ πεινᾶν, πείνα καλῶς.","st":"3.10"},{"sp":"N","t":"οὐκ ἐξἔστιν ἐπὶ σοί; τίς σε κωλύσει; ἀλλὰ πιεῖν μὲν κωλύσει ὁ ἰατρός, καλῶς δὲ διψᾶν οὐ δύναται: καὶ φαγεῖν μὲν κωλύσει, πεινᾶν δὲ καλῶς οὐ δύναται. ἀλλ᾽ οὐ φιλολογῶ;","st":"3.10"},{"sp":"N","t":"— τίνος δ᾽ ἕνεκα φιλολογεῖς; ἀνδράποδον, οὐχ ἵνα εὐροῇς; οὐχ ἵνα εὐσταθῇς; οὐχ ἵνα κατὰ φύσιν ἔχῃς καὶ διεξάγῃς;","st":"3.10"},{"sp":"N","t":"τί κωλύει πυρέσσοντα κατὰ φύσιν ἔχειν τὸ ἡγεμονικόν; ἐνθάδ᾽ ὁ ἔλεγχος τοῦ πράγματος, ἡ δοκιμασία τοῦ φιλοσοφοῦντος. μέρος γάρ ἐστι καὶ τοῦτο τοῦ βίου, ὡς περίπατος, ὡς πλοῦς, ὡς ὁδοιπορία, οὕτως καὶ πυρετός.","st":"3.10"},{"sp":"N","t":"μή τι περιπατῶν ἀναγιγνώσκεις; — οὔ. — οὕτως οὐδὲ πυρέσσων. ἀλλ᾽ ἂν καλῶς περιπατῇς, ἔχεις τὸ τοῦ περιπατοῦντος: ἂν καλῶς πυρέξῃς, ἔχεις τὰ τοῦ πυρέσσοντος.","st":"3.10"},{"sp":"N","t":"τί ἐστι καλῶς πυρέσσειν; μὴ θεὸν μέμψασθαι, μὴ ἄνθρωπον, μὴ θλιβῆναι ὑπὸ τῶν γινομένων, εὖ καὶ καλῶς προσδέχεσθαι τὸν θάνατον, ποιεῖν τὰ προστασσόμενα: ὅταν ὁ ἰατρὸς εἰσέρχηται, μὴ φοβεῖσθαι, τί εἴπῃ, μηδ᾽ ἂν εἴπῃ ‘κομψῶς ἔχεις,’ ὑπερχαίρειν: τί γάρ σοι ἀγαθὸν εἶπεν; ὅτε γὰρ ὑγίαινες, τί σοι ἦν ἀγαθόν;","st":"3.10"},{"sp":"N","t":"μηδ᾽ ἂν εἴπῃ ‘κακῶς ἔχεις,’ ἀθυμεῖν: τί γάρ ἐστι τὸ κακῶς ἔχειν; ἐγγίζειν τῷ διαλυθῆναι τὴν ψυχὴν ἀπὸ τοῦ σώματος. τί οὖν δεινόν ἐστιν; ἐὰν νῦν μὴ ἐγγίσῃς, ὕστερον οὐκ ἐγγιεῖς; ἀλλὰ ὁ κόσμος μέλλει ἀνατρέπεσθαι σοῦ ἀποθανόντος;","st":"3.10"},{"sp":"N","t":"τί οὖν κολακεύεις τὸν ἰατρόν; τί λέγεις ‘ἐὰν σὺ θέλῃς, κύριε, καλῶς ἕξω;’ τί παρέχεις αὐτῷ ἀφορμὴν τοῦ ἐπᾶραι ὀφρῦν; οὐχὶ δὲ τὴν αὑτοῦ ἀξίαν αὐτῷ ἀποδίδως, ὡς σκυτεῖ περὶ τὸν πόδα, ὡς τέκτονι περὶ τὴν οἰκίαν, οὕτως καὶ τῷ ἰατρῷ περὶ τὸ σωμάτιον, τὸ οὐκ ἐμόν, τὸ φύσει νεκρόν; τούτων ὁ καιρός ἐστι τῷ πυρέσσοντι: ἂν ταῦτα ἐκπληρώσῃ, ἔχει τὰ αὑτοῦ.","st":"3.10"},{"sp":"N","t":"οὐ γάρ ἐστιν ἔργον τοῦ φιλοσόφου ταῦτα τὰ ἐκτὸς τηρεῖν, οὔτε τὸ οἰνάριον οὔτε τὸ ἐλάδιον οὔτε τὸ σωμάτιον, ἀλλὰ τί; τὸ ἴδιον ἡγεμονικόν. τὰ δ᾽ ἔξω πῶς; μέχρι τοῦ μὴ ἀλογίστως κατὰ ταῦτα ἀναστρέφεσθαι.","st":"3.10"},{"sp":"N","t":"ποῦ οὖν ἔτι καιρὸς τοῦ φοβεῖσθαι; ποῦ οὖν ἔτι καιρὸς ὀργῆς; ποῦ φόβου περὶ τῶν ἀλλοτρίων, περὶ τῶν μηδενὸς ἀξίων;","st":"3.10"},{"sp":"N","t":"δύο γὰρ ταῦτα πρόχειρα ἔχειν δεῖ: ὅτι ἔξω τῆς προαιρέσεως οὐδέν ἐστιν οὔτε ἀγαθὸν οὔτε κακὸν καὶ ὅτι οὐ δεῖ προηγεῖσθαι τῶν πραγμάτων, ἀλλ᾽ ἐπακολουθεῖν.","st":"3.10"},{"sp":"N","t":"‘οὐκ ἔδει οὕτως μοι προσενεχθῆναι τὸν ἀδελφόν.’ οὔ: ἀλλὰ τοῦτο μὲν ἐκεῖνος ὄψεται. ἐγὼ δ᾽, ὡς ἂν προσενεχθῇ, αὐτὸς ὡς δεῖ χρήσομαι τοῖς πρὸς ἐκεῖνον.","st":"3.10"},{"sp":"N","t":"τοῦτο γὰρ ἐμόν ἐστιν, ἐκεῖνο δ᾽ ἀλλότριον: τοῦτο οὐδεὶς κωλῦσαι δύναται, ἐκεῖνο κωλύεται. σποράδην τινά. εἰσί τινες ὡς ἐκ νόμου διατεταγμέναι κολάσεις τοῖς ἀπειθοῦσι τῇ θείᾳ διοικήσει:","st":"3.10"},{"sp":"N","t":"‘ὃς ἂν ἄλλο τι ἡγήσηται ἀγαθὸν παρὰ τὰ προαιρετικά, φθονείτω, ἐπιθυμείτω, κολακευέτω, ταρασσέσθω: ὃς ἂν ἄλλο κακόν, λυπείσθω, πενθείτω, θρηνείτω, δυστυχείτω.’","st":"3.11"},{"sp":"N","t":"καὶ ὅμως οὕτως πικρῶς κολαζόμενοι ἀποστῆναι οὐ δυνάμεθα. μέμνησο, τί λέγει ὁ ποιητὴς περὶ τοῦ ξένου:","st":"3.11"},{"sp":"N","t":"ξεῖν᾽, οὔ μοι θέμις ἔστ᾽ι καὶ, οὐδ᾽ εἰ κακίων σέθεν ἔλθοι, ξεῖνον ἀτιμῆσαι: πρὸς γὰρ Διός εἰσιν ἅπαντες ξεῖνοί τε πτωχοί τε. τοῦτο οὖν καὶ ἐπὶ πατρὸς πρόχειρον ἔχειν:","st":"3.11"},{"sp":"N","t":"οὔ μοι θέμις ἔστ᾽ οὐδ᾽ εἰ κακίων σέθεν ἔλθοι, πατέρ᾽ ἀτιμῆσαι: πρὸς γὰρ Διός εἰσιν ἅπαντες τοῦ Πατρῴου:","st":"3.11"},{"sp":"N","t":"καὶ ἐπ᾽ ἀδελφῷ: πρὸς γὰρ Διός εἰσιν ἅπαντες τοῦ Ὁμογνίου. καὶ οὕτως κατὰ τὰς ἄλλας σχέσεις εὑρήσομεν ἐπόπτην τὸν Δία. περὶ ἀσκήσεως. τὰς ἀσκήσεις οὐ δεῖ διὰ τῶν παρὰ φύσιν καὶ παραδόξων ποιεῖσθαι, ἐπεί τοι τῶν θαυματοποιῶν οὐδὲν διοίσομεν οἱ λέγοντες φιλοσοφεῖν.","st":"3.11"},{"sp":"N","t":"δύσκολον γάρ ἐστι καὶ τὸ ἐπὶ σχοινίου περιπατεῖν καὶ οὐ μόνον δύσκολον, ἀλλὰ καὶ ἐπικίνδυνον. τούτου ἕνεκα δεῖ καὶ ἡμᾶς μελετᾶν ἐπὶ σχοινίου περιπατεῖν ἢ φοίνικα ἱστάνειν ἢ ἀνδριάντας περιλαμβάνειν;","st":"3.12"},{"sp":"N","t":"οὐδαμῶς. οὐκ ἔστι τὸ δύσκολον πᾶν καὶ ἐπικίνδυνον ἐπιτήδειον πρὸς ἄσκησιν, ἀλλὰ τὸ πρόσφορον τῷ προκειμένῳ ἐκπονηθῆναι.","st":"3.12"},{"sp":"N","t":"τί δ᾽ ἐστὶ τὸ προκείμενον ἐκπονηθῆναι; ὀρέξει καὶ ἐκκλίσει ἀκωλύτως ἀναστρέφεσθαι. τοῦτο δὲ τί ἐστιν, μήτε ὀρεγόμενον ἀποτυγχάνειν μήτ᾽ ἐκκλίνοντα περιπίπτειν. πρὸς τοῦτο οὖν καὶ τὴν ἄσκησιν ῥέπειν δεῖ.","st":"3.12"},{"sp":"N","t":"ἐπεὶ γὰρ οὐκ ἔστιν ἀναπότευκτον σχεῖν τὴν ὄρεξιν καὶ τὴν ἔκκλισιν ἀπερίπτωτον ἄνευ μεγάλης καὶ συνεχοῦς ἀσκήσεως, ἴσθι ὅτι, ἐὰν ἔξω ἐάσῃς ἀποστρέφεσθαι αὐτὴν ἐπὶ τὰ ἀπροαίρετα, οὔτε τὴν ὄρεξιν ἐπιτευκτικὴν ἕξεις οὔτε τὴν ἔκκλισιν ἀπερίπτωτον.","st":"3.12"},{"sp":"N","t":"καὶ ἐπεὶ τὸ ἔθος ἰσχυρὸν προηγῆται πρὸς μόνα ταῦτα εἰθισμένων ἡμῶν χρῆσθαι ὀρέξει καὶ ἐκκλίσει, δεῖ τῷ ἔθει τούτῳ ἐναντίον ἔθος ἀντιθεῖναι καὶ ὅπου ὁ πολὺς ὄλισθος τῶν φαντασιῶν, ἐκεῖ ἀντιτιθέναι τὸ ἀσκητικόν.","st":"3.12"},{"sp":"N","t":"Ἑτεροκλινῶς ἔχω πρὸς ἡδονήν: ἀνατοιχήσω ἐπὶ τὸ ἐναντίον ὑπὲρ τὸ μέτρον τῆς ἀσκήσεως ἕνεκα. ἐκκλιτικῶς ἔχω πόνου: τρίψω μου καὶ γυμνάσω πρὸς τοῦτο τὰς φαντασίας ὑπὲρ τοῦ ἀποστῆναι τὴν ἔκκλισιν ἀπὸ παντὸς τοῦ τοιούτου.","st":"3.12"},{"sp":"N","t":"τίς γάρ ἐστιν ἀσκητής; ὁ μελετῶν ὀρέξει μὲν μὴ χρῆσθαι, ἐκκλίσει δὲ πρὸς μόνα τὰ προαιρετικὰ χρῆσθαι καὶ μελετῶν μᾶλλον ἐν τοῖς δυσκαταπονήτοις. καθ᾽ ὃ καὶ ἄλλῳ πρὸς ἄλλα μᾶλλον ἀσκητέον.","st":"3.12"},{"sp":"N","t":"τί οὖν ὧδε ποιεῖ τὸ φοίνικα στῆσαι ἢ τὸ στέγην δερματίνην καὶ ὅλμον καὶ ὕπερον περιφέρειν;","st":"3.12"},{"sp":"N","t":"ἄνθρωπε, ἄσκησον, εἰ γοργὸς εἶ, λοιδορούμενος ἀνέχεσθαι, ἀτιμασθεὶς μὴ ἀχθεσθῆναι. εἶθ᾽ οὕτως προσβήσῃ, ἵνα, κἂν πλήξῃ σέ τις, εἴπῃς αὐτὸς πρὸς αὑτὸν ὅτι ‘δόξον ἀνδριάντα περιειληφέναι.’","st":"3.12"},{"sp":"N","t":"εἶτα καὶ οἰναρίῳ κομψῶς χρῆσθαι, μὴ εἰς τὸ πολὺ πίνειν （ καὶ γὰρ περὶ τοῦτο ἐπαρίστεροι ἀσκηταί εἰσιν ） , ἀλλὰ πρῶτον εἰς τὸ ἀποσχέσθαι, καὶ κορασιδίου ἀπέχεσθαι καὶ πλακουνταρίου. εἶτά ποτε ὑπὲρ δοκιμασίας, εἰ ἄρα, καθήσεις εὐκαίρως αὐτὸς σαυτὸν ὑπὲρ τοῦ γνῶναι, εἰ ὁμοίως ἡττῶσίν σε αἱ φαντασίαι.","st":"3.12"},{"sp":"N","t":"τὰ πρῶτα δὲ φεῦγε μακρὰν ἀπὸ τῶν ἰσχυροτέρων. ἄνισος ἡ μάχη κορασιδίῳ κομψῷ πρὸς νέον ἀρχόμενον φιλοσοφεῖν: χύτρα, φασί, καὶ πέτρα οὐ συμφωνεῖ.","st":"3.12"},{"sp":"N","t":"μετὰ τὴν ὄρεξιν καὶ τὴν ἔκκλισιν δεύτερος τρόπος ὁ περὶ τὴν ὁρμὴν καὶ ἀφορμήν: ἵν᾽ εὐπειθὴς τῷ λόγῳ, ἵνα μὴ παρὰ καιρόν, μὴ παρὰ τόπον, μὴ παρὰ ἄλλην τινὰ τοιαύτην ἀσυμμετρίαν.","st":"3.12"},{"sp":"N","t":"τρίτος ὁ περὶ τὰς συγκαταθέσεις, ὁ πρὸς τὰ πιθανὰ καὶ ἑλκυστικά.","st":"3.12"},{"sp":"N","t":"ὡς γὰρ ὁ Σωκράτης ἔλεγεν ἀνεξέταστον βίον μὴ ζῆν, οὕτως ἀνεξέταστον φαντασίαν μὴ παραδέχεσθαι, ἀλλὰ λέγειν ‘ἔκδεξαι, ἄφες ἴδω, τίς εἶ καὶ πόθεν ἔρχῃ,’ ὡς οἱ νυκτοφύλακες ‘δεῖξόν μοι τὰ συνθήματα.’ ‘ἔχεις τὸ παρὰ τῆς φύσεως σύμβολον, ὃ δεῖ τὴν παραδεχθησομένην ἔχειν φαντασίαν;’","st":"3.12"},{"sp":"N","t":"καὶ λοιπὸν ὅσα τῷ σώματι προσάγεται ὑπὸ τῶν γυμναζόντων αὐτό, ἂν μὲν ὧδέ που ῥέπῃ πρὸς ὄρεξιν καὶ ἔκκλισιν, εἴη ἂν καὶ αὐτὰ ἀσκητικά: ἂν δὲ πρὸς ἐπίδειξιν, ἔξω νενευκότος ἐστὶ καὶ ἄλλο τι θηρωμένου καὶ θεατὰς ζητοῦντος τοὺς ἐροῦντας ‘ὦς μεγάλου ἀνθρώπου.’","st":"3.12"},{"sp":"N","t":"διὰ τοῦτο καλῶς ὁ Ἀπολλώνιος ἔλεγεν ὅτι ‘ὅταν θέλῃς σαυτῷ ἀσκῆσαι, διψῶν ποτε καύματος ἐφέλκυσαι βρόγχον ψυχροῦ καὶ ἔκπτυσον καὶ μηδενὶ εἴπῃς.’ τί ἐρημία καὶ ποῖος ἔρημος. ἐρημία ἐστὶ κατάστασίς τις ἀβοηθήτου. οὐ γὰρ ὁ μόνος ὢν εὐθὺς καὶ ἔρημος, ὥσπερ οὐδ᾽ ὁ ἐν πολλοῖς ὢν οὐκ ἔρημος.","st":"3.12"},{"sp":"N","t":"ὅταν γοῦν ἀπολέσωμεν ἢ ἀδελφὸν ἢ υἱὸν ἢ φίλον, ᾧ προσαναπαυόμεθα, λέγομεν ἀπολελεῖφθαι ἔρημοι, πολλάκις ἐν Ῥώμῃ ὄντες, τοσούτου ὄχλου ἡμῖν ἀπαντῶντος καὶ τοσούτων συνοικούντων, ἔσθ᾽ ὅτε πλῆθος δούλων ἔχοντες.","st":"3.13"},{"sp":"N","t":"θέλει γὰρ ὁ ἔρημος κατὰ τὴν ἔννοιαν ἀβοήθητός τις εἶναι καὶ ἐκκείμενος τοῖς βλάπτειν βουλομένοις. διὰ τοῦτο, ὅταν ὁδεύωμεν, τότε μάλιστα ἐρήμους λέγομεν ἑαυτούς, ὅταν εἰς λῃστὰς ἐμπέσωμεν. οὐ γὰρ ἀνθρώπου ὄψις ἐξαιρεῖται ἐρημίας, ἀλλὰ πιστοῦ καὶ αἰδήμονος καὶ ὠφελίμου.","st":"3.13"},{"sp":"N","t":"ἐπεὶ εἰ τὸ μόνον εἶναι ἀρκεῖ πρὸς τὸ ἔρημον εἶναι, λέγε ὅτι καὶ ὁ Ζεὺς ἐν τῇ ἐκπυρώσει ἔρημός ἐστι καὶ κατακλαίει αὐτὸς ἑαυτοῦ: ‘τάλας ἐγώ, οὔτε τὴν Ἥραν ἔχω οὔτε τὴν Ἀθηνᾶν οὔτε τὸν Ἀπόλλωνα οὔτε ὅλως ἢ ἀδελφὸν ἢ υἱὸν ἢ ἔγγονον ἢ συγγενῆ.’","st":"3.13"},{"sp":"N","t":"ταῦτα καὶ λέγουσί τινες ὅτι ποιεῖ μόνος ἐν τῇ ἐκπυρώσει. οὐ γὰρ ἐπινοοῦσι διεξαγωγὴν μόνου καὶ ἀπό τινος φυσικοῦ ὁρμώμενοι, ἀπὸ τοῦ φύσει κοινωνικοῦ εἶναι καὶ φιλαλλήλου καὶ ἡδέως συναναστρέφεσθαι ἀνθρώποις.","st":"3.13"},{"sp":"N","t":"ἀλλ᾽ οὐδὲν ἧττον δεῖ τινα καὶ πρὸς τοῦτο παρασκευὴν ἔχειν τὸ δύνασθαι αὐτὸν ἑαυτῷ ἀρκεῖν, δύνασθαι αὐτὸν ἑαυτῷ συνεῖναι:","st":"3.13"},{"sp":"N","t":"ὡς ὁ Ζεὺς αὐτὸς ἑαυτῷ σύνεστιν καὶ ἡσυχάζει ἐφ᾽ ἑαυτοῦ καὶ ἐννοεῖ τὴν διοίκησιν τὴν ἑαυτοῦ οἵα ἐστὶ καὶ ἐν ἐπινοίαις γίνεται πρεπούσαις ἑαυτῷ, οὕτως καὶ ἡμᾶς δύνασθαι αὐτοὺς ἑαυτοῖς λαλεῖν, μὴ προσδεῖσθαι ἄλλων, διαγωγῆς μὴ ἀπορεῖν:","st":"3.13"},{"sp":"N","t":"ἐφιστάνειν τῇ θείᾳ διοικήσει, τῇ αὑτῶν πρὸς τἆλλα σχέσει: ἐπιβλέπειν, πῶς πρότερον εἴχομεν πρὸς τὰ συμβαίνοντα, πῶς νῦν: τίνα ἐστὶν ἔτι τὰ θλίβοντα: πῶς ἂν θεραπευθῇ καὶ ταῦτα, πῶς ἐξαιρεθῇ: εἴ τινα ἐξεργασίας δεῖται τούτων, κατὰ τὸν αὐτῶν λόγον ἐξεργάζεσθαι.","st":"3.13"},{"sp":"N","t":"ὁρᾶτε γάρ, ὅτι εἰρήνην μεγάλην ὁ Καῖσαρ ἡμῖν δοκεῖ παρέχειν, ὅτι οὐκ εἰσὶν οὐκέτι πόλεμοι οὐδὲ μάχαι οὐδὲ λῃστήρια μεγάλα οὐδὲ πειρατικά, ἀλλ᾽ ἔξεστιν πάσῃ ὥρᾳ ὁδεύειν, πλεῖν ἀπ᾽ ἀνατολῶν ἐπὶ δυσμάς.","st":"3.13"},{"sp":"N","t":"μή τι οὖν καὶ ἀπὸ πυρετοῦ δύναται ἡμῖν εἰρήνην παρασχεῖν, μή τι καὶ ἀπὸ ναυαγίου, μή τι καὶ ἀπὸ ἐμπρησμοῦ ἢ ἀπὸ σεισμοῦ ἢ ἀπὸ κεραυνοῦ; ἄγε ἀπ᾽ ἔρωτος; οὐ δύναται. ἀπὸ πένθους; οὐ δύναται. ἀπὸ φθόνου; οὐ δύναται. ἀπ᾽ οὐδενὸς ἁπλῶς τούτων:","st":"3.13"},{"sp":"N","t":"ὁ δὲ λόγος ὁ τῶν φιλοσόφων ὑπισχνεῖται καὶ ἀπὸ τούτων εἰρήνην παρέχειν. καὶ τί λέγει; ‘ἄν μοι προσέχητε, ὦ ἄνθρωποι, ὅπου ἂν ἦτε, ὅ τι ἂν ποιῆτε, οὐ λυπηθήσεσθε, οὐκ ὀργισθήσεσθε, οὐκ ἀναγκασθήσεσθε, οὐ κωλυθήσεσθε, ἀπαθεῖς δὲ καὶ ἐλεύθεροι διάξετε ἀπὸ πάντων.’","st":"3.13"},{"sp":"N","t":"ταύτην τὴν εἰρήνην τις ἔχων οὐχὶ κεκηρυγμένην οὐχ ὑπὸ τοῦ Καίσαρος （ πόθεν γὰρ αὐτῷ ταύτην κηρύξαι; ） , ἀλλ᾽ ὑπὸ τοῦ θεοῦ κεκηρυγμένην διὰ τοῦ λόγου οὐκ ἀρκεῖται, ὅταν ᾖ μόνος, ἐπιβλέπων καὶ ἐνθυμούμενος","st":"3.13"},{"sp":"N","t":"‘νῦν ἐμοὶ κακὸν οὐδὲν δύναται συμβῆναι, ἐμοὶ λῃστὴς οὐκ ἔστιν, ἐμοὶ σεισμὸς οὐκ ἔστιν, πάντα εἰρήνης μεστά, πάντα ἀταραξίας: πᾶσα ὁδός, πᾶσα πόλις, πᾶσα σύνοδος, γείτων, κοινωνὸς ἀβλαβής. ἄλλος παρέχει τροφάς, ᾧ μέλει, ἄλλος ἐσθῆτα, ἄλλος αἰσθήσεις ἔδωκεν, ἄλλος προλήψεις.","st":"3.13"},{"sp":"N","t":"ὅταν δὲ μὴ παρέχῃ τἀναγκαῖα, τὸ ἀνακλητικὸν σημαίνει, τὴν θύραν ἤνοιξεν καὶ λέγει σοι ‘ἔρχου.’ ποῦ; εἰς οὐδὲν δεινόν, ἀλλ᾽ ὅθεν ἐγένου, εἰς τὰ φίλα καὶ συγγενῆ, εἰς τὰ στοιχεῖα.","st":"3.13"},{"sp":"N","t":"ὅσον ἦν ἐν σοὶ πυρός, εἰς πῦρ ἄπεισιν, ὅσον ἦν γῃδίου, εἰς γῄδιον, ὅσον πνευματίου, εἰς πνευμάτιον, ὅσον ὑδατίου, εἰς ὑδάτιον. οὐδεὶς Ἅιδης οὐδ᾽ Ἀχέρων οὐδὲ Κωκυτὸς οὐδὲ Πυριφλεγέθων, ἀλλὰ πάντα θεῶν μεστὰ καὶ δαιμόνων;’","st":"3.13"},{"sp":"N","t":"ταῦτά τις ἐνθυμεῖσθαι ἔχων καὶ βλέπων τὸν ἥλιον καὶ σελήνην καὶ ἄστρα καὶ γῆς ἀπολαύων καὶ θαλάσσης ἔρημός ἐστιν οὐ μᾶλλον ἢ καὶ ἀβοήθητος.","st":"3.13"},{"sp":"N","t":"‘τί οὖν; ἄν τις ἐπελθών μοι μόνῳ ἀποσφάξῃ με;’ μωρέ, σὲ οὔ, ἀλλὰ τὸ σωμάτιον.","st":"3.13"},{"sp":"N","t":"ποία οὖν ἔτι ἐρημία, ποία ἀπορία; τί χείρονας ἑαυτοὺς ποιῶμεν τῶν παιδαρίων; ἅ τινα ὅταν ἀπολειφθῇ μόνα, τί ποιεῖ; ἄραντα ὀστράκια καὶ σποδὸν οἰκοδομεῖ τί ποτε, εἶτα καταστρέφει καὶ πάλιν ἄλλο οἰκοδομεῖ: καὶ οὕτως οὐδέποτε ἀπορεῖ διαγωγῆς.","st":"3.13"},{"sp":"N","t":"ἐγὼ οὖν, ἂν πλεύσητε ὑμεῖς, μέλλω καθήμενος κλαίειν ὅτι μόνος ἀπελείφθην καὶ ἔρημος οὕτως; οὐκ ὀστράκια ἕξω, οὐ σποδόν; ἀλλ᾽ ἐκεῖνα ὑπ᾽ ἀφροσύνης ταῦτα ποιεῖ, ἡμεῖς δ᾽ ὑπὸ φρονήσεως δυστυχοῦμεν;","st":"3.13"},{"sp":"N","t":"πᾶσα μεγάλη δύναμις ἐπισφαλὴς τῷ ἀρχομένῳ. φέρειν οὖν δεῖ τὰ τοιαῦτα κατὰ δύναμιν, ἀλλὰ κατὰ φύσιν .","st":"3.13"},{"sp":"N","t":"... ἀλλ᾽ οὐχὶ τῷ φθισικῷ. μελέτησόν ποτε διαγωγὴν ὡς ἄρρωστος, ἵνα ποθ᾽ ὡς ὑγιαίνων διαγάγῃς. ἀσίτησον, ὑδροπότησον: ἀπόσχου ποτὲ παντάπασιν ὀρέξεως, ἵνα ποτὲ καὶ εὐλόγως ὀρεχθῇς. εἰ δ᾽ εὐλόγως, ὅταν ἔχῃς τι ἐν σεαυτῷ ἀγαθόν, εὖ ὀρεχθήσῃ.","st":"3.13"},{"sp":"N","t":"οὔ: ἀλλ᾽ εὐθέως ὡς σοφοὶ διάγειν ἐθέλομεν καὶ ὠφελεῖν ἀνθρώπους. ποίαν ὠφέλειαν; τί ποιεῖς; σαυτὸν γὰρ ὠφέλησας; ἀλλὰ προτρέψαι αὐτοὺς θέλεις. σὺ γὰρ προτέτρεψαι; θέλεις αὐτοὺς ὠφελῆσαι.","st":"3.13"},{"sp":"N","t":"δεῖξον αὐτοῖς ἐπὶ σεαυτοῦ, οἵους ποιεῖ φιλοσοφία, καὶ μὴ φλυάρει. ἐσθίων τοὺς συνεσθίοντας ὠφέλει, πίνων τοὺς πίνοντας, εἴκων πᾶσι, παραχωρῶν, ἀνεχόμενος, οὕτως αὐτοὺς ὠφέλει καὶ μὴ κατεξέρα αὐτῶν τὸ σαυτοῦ φλέγμα. σποράδην τινά. ὡς οἱ κακοὶ τραγῳδοὶ μόνοι ᾆσαι οὐ δύνανται, ἀλλὰ μετὰ πολλῶν, οὕτως ἔνιοι μόνοι περιπατῆσαι οὐ δύνανται.","st":"3.13"},{"sp":"N","t":"ἄνθρωπε, εἴ τις εἶ, καὶ μόνος περιπάτησον καὶ σαυτῷ λάλησον καὶ μὴ ἐν τῷ χορῷ κρύπτου.","st":"3.14"},{"sp":"N","t":"σκώφθητί ποτε, περίβλεψαι, ἐνσείσθητι, ἵνα γνῷς, τίς εἶ.","st":"3.14"},{"sp":"N","t":"ὅταν τις ὕδωρ πίνῃ ἢ ποιῇ τι ἀσκητικόν, ἐκ πάσης ἀφορμῆς λέγει αὐτὸ πρὸς πάντας.","st":"3.14"},{"sp":"N","t":"‘ἐγὼ ὕδωρ πίνω.’ διὰ γὰρ τοῦτο ὕδωρ πίνεις, διὰ γὰρ τὸ ὕδωρ πίνειν; ἄνθρωπε, εἴ σοι λυσιτελεῖν πίνειν, πῖνε: εἰ δὲ μή, γελοίως ποιεῖς.","st":"3.14"},{"sp":"N","t":"εἰ δὲ συμφέρει σοι καὶ πίνεις, σιώπα πρὸς τοὺς δυσαρεστοῦντας τοῖς ἀνθρώποις. τί οὖν; αὐτοῖς τούτοις ἀρέσκειν θέλεις;","st":"3.14"},{"sp":"N","t":"τῶν πραττομένων τὰ μὲν προηγουμένως πράττεται, τὰ δὲ κατὰ περίστασιν, τὰ δὲ κατ᾽ οἰκονομίαν, τὰ δὲ κατὰ συμπεριφοράν, τὰ δὲ κατ᾽ ἔνστασιν.","st":"3.14"},{"sp":"N","t":"δύο ταῦτα ἐξελεῖν τῶν ἀνθρώπων, οἴησιν καὶ ἀπιστίαν. οἴησις μὲν οὖν ἐστι τὸ δοκεῖν μηδενὸς προσδεῖσθαι, ἀπιστία δὲ τὸ ὑπολαμβάνειν μὴ δυνατὸν εἶναι εὐροεῖν τοσούτων περιεστηκότων.","st":"3.14"},{"sp":"N","t":"τὴν μὲν οὖν οἴησιν ἔλεγχος ἐξαιρεῖ, καὶ τοῦτο πρῶτον ποιεῖ Σωκράτης. ὅτι δ᾽ οὐκ ἀδύνατόν ἐστι τὸ πρᾶγμα, σκέψαι καὶ ζήτησον. οὐδέν σε βλάψει ἡ ζήτησις αὕτη:","st":"3.14"},{"sp":"N","t":"καὶ σχεδὸν τὸ φιλοσοφεῖν τοῦτ᾽ ἔστι, ζητεῖν, πῶς ἐνδέχεται ἀπαραποδίστως ὀρέξει χρῆσθαι καὶ ἐκκλίσει.","st":"3.14"},{"sp":"N","t":"‘κρείσσων εἰμὶ σοῦ: ὁ γὰρ πατήρ μου ὑπατικός ἐστιν.’ ἄλλος λέγει","st":"3.14"},{"sp":"N","t":"‘ἐγὼ δεδημάρχηκα, σὺ δ᾽ οὔ.’ εἰ δ᾽ ἵπποι ἦμεν, ἔλεγες ἂν ὅτι ‘ὁ πατήρ μου ὠκύτερος ἦν’ ἢ ὅτι ‘ἐγὼ ἔχω πολλὰς κριθὰς καὶ χόρτον’ ἢ ὅτι ‘κομψὰ περιτραχήλια;’ εἰ οὖν ταῦτά σου λέγοντος εἶπον ὅτι ‘ἔστω ταῦτα, τρέχωμεν οὖν;’","st":"3.14"},{"sp":"N","t":"ἄγε, ἐπ᾽ ἀνθρώπου οὖν οὐδέν ἐστι τοιοῦτον οἷον ἐφ᾽ ἵππου δρόμος, ἐξ οὗ γνωσθήσεται ὁ χείρων καὶ ὁ κρείττων; μήποτ᾽ ἐστὶν αἰδώς, πίστις, δικαιοσύνη;","st":"3.14"},{"sp":"N","t":"τούτοις δείκνυε κρείττονα σεαυτόν, ἵν᾽ ὡς ἄνθρωπος ᾖ κρείττων. ἄν μοι λέγῃς ὅτι ‘μεγάλα λακτίζω,’ ἐρῶ σοι κἀγὼ ὅτι ‘ἐπὶ ὄνου ἔργῳ μέγα φρονεῖς.’ ὅτι δεῖ περιεσκεμμένως ἔρχεσθαι ἐφ᾽ ἕκαστα. ἑκάστου ἔργου σκόπει τὰ καθηγούμενα καὶ τὰ ἀκόλουθα καὶ οὕτως ἔρχου ἐπ᾽ αὐτό. εἰ δὲ μή, τὴν μὲν πρώτην ἥξεις προθύμως ἅτε μηδὲν τῶν ἑξῆς ἐντεθυμημένος, ὕστερον δ᾽ ἀναφανέντων τινῶν αἰσχρῶς ἀποστήσῃ.","st":"3.14"},{"sp":"N","t":"‘θέλω Ὀλύμπια νικῆσαι.’ ἀλλὰ σκόπει τὰ καθηγούμενα αὐτοῦ καὶ τὰ ἀκόλουθα: καὶ οὕτως ἄν σοι λυσιτελῇ, ἅπτου τοῦ ἔργου.","st":"3.15"},{"sp":"N","t":"δεῖ σε εὐτακτεῖν, ἀναγκοφαγεῖν, ἀπέχεσθαι πεμμάτων, γυμνάζεσθαι πρὸς ἀνάγκην, ὥρᾳ τεταγμένῃ, ἐν καύματι, ἐν ψύχει: μὴ ψυχρὸν πίνειν, μὴ οἶνον ὅτ᾽ ἔτυχεν: ἁπλῶς ὡς ἰατρῷ γὰρ παραδεδωκέναι σεαυτὸν τῷ ἐπιστάτῃ:","st":"3.15"},{"sp":"N","t":"εἶτα ἐν τῷ ἀγῶνι παρορύσσεσθαι, ἔστιν ὅτε χεῖρα ἐκβαλεῖν, σφυρὸν στρέψαι, πολλὴν ἁφὴν καταπιεῖν, μαστιγωθῆναι: καὶ μετὰ τούτων πάντων ἔσθ᾽ ὅτε νικηθῆναι.","st":"3.15"},{"sp":"N","t":"ταῦτα λογισάμενος, ἂν ἔτι θέλῃς, ἔρχου ἐπὶ τὸ ἀθλεῖν: εἰ δὲ μή, ὅρα ὅτι ὡς τὰ παιδία ἀναστραφήσῃ, ἃ νῦν μὲν ἀθλητὰς παίζει, νῦν δὲ μονομάχους, νῦν δὲ σαλπίζει, εἶτα τραγῳδεῖ ὅ τι ἂν ἴδῃ καὶ θαυμάσῃ.","st":"3.15"},{"sp":"N","t":"οὕτως καὶ σὺ νῦν μὲν ἀθλητής, νῦν δὲ μονομάχος, εἶτα φιλόσοφος, εἶτα ῥήτωρ, ὅλῃ δὲ τῇ ψυχῇ οὐδέν, ἀλλ᾽ ὡς ὁ πίθηκος πᾶν ὃ ἂν ἴδῃς μιμῇ καὶ ἀεί σοι ἄλλο ἐξ ἄλλου ἀρέσκει, τὸ σύνηθες δ᾽ ἀπαρέσκει.","st":"3.15"},{"sp":"N","t":"οὐ γὰρ μετὰ σκέψεως ἦλθες ἐπί τι οὐδὲ περιοδεύσας ὅλον τὸ πρᾶγμα οὐδὲ βασανίσας, ἀλλ᾽ εἰκῇ καὶ κατὰ ψυχρὰν ἐπιθυμίαν.","st":"3.15"},{"sp":"N","t":"οὕτως τινὲς ἰδόντες φιλόσοφον καὶ ἀκούσαντές τινος οὕτως λέγοντος, ὡς Εὐφράτης λέγει （ καίτοι τίς οὕτως δύναται εἰπεῖν ὡς ἐκεῖνος; ） , θέλουσιν καὶ αὐτοὶ φιλοσοφεῖν.","st":"3.15"},{"sp":"N","t":"ἄνθρωπε, σκέψαι πρῶτον τί ἐστι τὸ πρᾶγμα, εἶτα καὶ τὴν σαυτοῦ φύσιν, τί δύνασαι βαστάσαι. εἰ παλαιστής, ἰδού σου τοὺς ὤμους, τοὺς μηρούς, τὴν ὀσφῦν.","st":"3.15"},{"sp":"N","t":"ἄλλος γὰρ πρὸς ἄλλο τι πέφυκεν. δοκεῖς ὅτι ταῦτα ποιῶν δύνασαι φιλοσοφεῖν; δοκεῖς ὅτι δύνασαι ὡσαύτως ἐσθίειν, ὡσαύτως πίνειν, ὁμοίως ὀργίζεσθαι, ὁμοίως δυσαρεστεῖν;","st":"3.15"},{"sp":"N","t":"ἀγρυπνῆσαι δεῖ, πονῆσαι, νικῆσαί τινας ἐπιθυμίας, ἀπελθεῖν ἀπὸ τῶν οἰκείων, ὑπὸ παιδαρίου καταφρονηθῆναι, ὑπὸ τῶν ἀπαντώντων καταγελασθῆναι, ἐν παντὶ ἔλασσον ἔχειν, ἐν ἀρχῇ, ἐν τιμῇ, ἐν δίκῃ.","st":"3.15"},{"sp":"N","t":"ταῦτα περισκεψάμενος, εἴ σοι δοκεῖ, προσέρχου, εἰ θέλεις ἀντικαταλλάξασθαι τούτων ἀπάθειαν, ἐλευθερίαν, ἀταραξίαν. εἰ δὲ μή, μὴ πρόσαγε, μὴ ὡς τὰ παιδία νῦν μὲν φιλόσοφος, ὕστερον δὲ τελώνης, εἶτα ῥήτωρ, εἶτα ἐπίτροπος Καίσαρος.","st":"3.15"},{"sp":"N","t":"ταῦτα οὐ συμφωνεῖ: ἕνα σε δεῖ ἄνθρωπον εἶναι ἢ ἀγαθὸν ἢ κακόν: ἢ τὸ ἡγεμονικόν σε δεῖ ἐξεργάζεσθαι τὸ σαυτοῦ ἢ τὰ ἐκτός: ἢ περὶ τὰ ἔσω φιλοπονεῖν ἢ περὶ τὰ ἔξω: τοῦτ᾽ ἔστι φιλοσόφου στάσιν ἔχειν ἢ ἰδιώτου. Ῥούφῳ τις ἔλεγεν Γάλβα σφαγέντος ὅτι","st":"3.15"},{"sp":"N","t":"‘νῦν προνοίᾳ ὁ κόσμος διοικεῖται;:’ ὁ δὲ ‘μὴ παρέργως ποτ᾽,’ ἔφη, ‘ἀπὸ Γάλβα κατεσκεύασα, ὅτι προνοίᾳ ὁ κόσμος διοικεῖται;’ ὅτι εὐλαβῶς δεῖ συγκαθιέναι εἰς συμπεριφοράν. ἀνάγκη τὸν συγκαθιέντα τισὶν ἐπιπλέον ἢ εἰς λαλιὰν ἢ εἰς συμπόσια ἢ ἁπλῶς εἰς συμβίωσιν ἢ αὐτὸν ἐκείνοις ἐξομοιωθῆναι ἢ ἐκείνους μεταθεῖναι ἐπὶ τὰ αὑτοῦ.","st":"3.15"},{"sp":"N","t":"καὶ γὰρ ἄνθρακα ἀπεσβεσμένον ἂν θῇ παρὰ τὸν καιόμενον, ἢ αὐτὸς ἐκεῖνον ἀποσβέσει ἢ ἐκεῖνος τοῦτον ἐκκαύσει.","st":"3.16"},{"sp":"N","t":"τηλικούτου οὖν τοῦ κινδύνου ὄντος εὐλαβῶς δεῖ τοῖς ἰδιώταις συγκαθίεσθαι εἰς τὰς τοιαύτας συμπεριφορὰς μεμνημένους, ὅτι ἀμήχανον τὸν συνανατριβόμενον τῷ ἠσβολωμένῳ μὴ καὶ αὐτὸν ἀπολαῦσαι τῆς ἀσβόλης: τί γὰρ ποιήσεις,","st":"3.16"},{"sp":"N","t":"ἂν περὶ μονομάχων λαλῇς, ἂν περὶ ἵππων, ἂν περὶ ἀθλητῶν, ἂν τὸ ἔτι τούτων χεῖρον περὶ ἀνθρώπων: ‘ὁ δεῖνα κακός, ὁ δεῖνα ἀγαθός: τοῦτο καλῶς ἐγένετο, τοῦτο κακῶς:’ ἔτι ἂν σκώπτῃ, ἂν γελοιάζῃ, ἂν κακοηθίζηται;","st":"3.16"},{"sp":"N","t":"ἔχει τις ὑμῶν παρασκευὴν οἵαν ὁ κιθαριστικὸς τὴν λύραν λαβών, ὥστ᾽ εὐθὺς ἁψάμενος τῶν χορδῶν γνῶναι τὰς ἀσυμφώνους καὶ ἁρμόσασθαι τὸ ὄργανον; οἵαν εἶχεν δύναμιν Σωκράτης, ὥστ᾽ ἐν πάσῃ συμπεριφορᾷ ἄγειν ἐπὶ τὸ αὑτοῦ τοὺς συνόντας;","st":"3.16"},{"sp":"N","t":"πόθεν ὑμῖν; ἀλλ᾽ ἀνάγκη ὑπὸ τῶν ἰδιωτῶν ὑμᾶς περιάγεσθαι.","st":"3.16"},{"sp":"N","t":"διὰ τί οὖν ἐκεῖνοι ὑμῶν ἰσχυρότεροι; ὅτι ἐκεῖνοι μὲν τὰ σαπρὰ ταῦτα ἀπὸ δογμάτων λαλοῦσιν, ὑμεῖς δὲ τὰ κομψὰ ἀπὸ τῶν χειλῶν: διὰ τοῦτο ἄτονά ἐστι καὶ νεκρά, καὶ σικχᾶναι ἔστιν ἀκούοντα ὑμῶν τοὺς προτρεπτικοὺς καὶ τὴν ἀρετὴν τὴν ταλαίπωρον, ἣ ἄνω κάτω θρυλεῖται. οὕτως ὑμᾶς οἱ ἰδιῶται νικῶσιν.","st":"3.16"},{"sp":"N","t":"πανταχοῦ γὰρ ἰσχυρὸν τὸ δόγμα, ἀνίκητον τὸ δόγμα.","st":"3.16"},{"sp":"N","t":"μέχρις ἂν οὖν παγῶσιν ἐν ὑμῖν αἱ κομψαὶ ὑπολήψεις καὶ δυναμίν τινα περιποιήσησθε πρὸς ἀσφάλειαν, συμβουλεύω ὑμῖν εὐλαβῶς τοῖς ἰδιώταις συγκαταβαίνειν: εἰ δὲ μή, καθ᾽ ἡμέραν ὡς κηρὸς ἐν ἡλίῳ διατακήσεται, ὑμῶν εἴ τινα ἐν τῇ σχολῇ ἐγγράφετε.","st":"3.16"},{"sp":"N","t":"μακρὰν οὖν ἀπὸ τοῦ ἡλίου πού ποτε ὑπάγετε, μέχρις ἂν κηρίνας τὰς ὑπολήψεις ἔχητε.","st":"3.16"},{"sp":"N","t":"διὰ τοῦτο καὶ τῶν πατρίδων συμβουλεύουσιν ἀποχωρεῖν οἱ φιλόσοφοι, ὅτι τὰ παλαιὰ ἔθη περισπᾷ καὶ οὐκ ἐᾷ ἀρχὴν γενέσθαι τινὰ ἄλλου ἐθισμοῦ, οὐδὲ φέρομεν τοὺς ἀπαντῶντας καὶ λέγοντας ‘εἴδ᾽ ὁ δεῖνα φιλοσοφεῖ, ὁ τοῖος καὶ ὁ τοῖος.’","st":"3.16"},{"sp":"N","t":"οὕτως καὶ οἱ ἰατροὶ τοὺς μακρονοσοῦντας ἐκπέμπουσιν εἰς ἄλλην χώραν καὶ ἄλλον ἀέρα καλῶς ποιοῦντες.","st":"3.16"},{"sp":"N","t":"καὶ ὑμεῖς ἀντεισαγάγετε ἄλλα ἔθη: πήξατε ὑμῶν τὰς ὑπολήψεις, ἐναθλεῖτε αὐταῖς.","st":"3.16"},{"sp":"N","t":"οὔ: ἀλλ᾽ ἔνθεν ἐπὶ θεωρίαν, εἰς μονομαχίαν, εἰς ξυστόν, εἰς κίρκον: εἶτ᾽ ἐκεῖθεν ὧδε καὶ πάλιν ἔνθεν ἐκεῖ οἱ αὐτοί.","st":"3.16"},{"sp":"N","t":"καὶ ἔθος κομψὸν οὐδέν, οὔτε προσοχὴ οὔτ᾽ ἐπιστροφὴ ἐφ᾽ αὑτὸν καὶ παρατήρησις ‘πῶς χρῶμαι ταῖς προσπιπτούσαις φαντασίαις; κατὰ φύσιν ἢ παρὰ φύσιν; πῶς ἀποκρίνωμαι πρὸς αὐτάς; ὡς δεῖ ἢ ὡς οὐ δεῖ; ἐπιλέγω τοῖς ἀπροαιρέτοις, ὅτι οὐδὲν πρὸς ἐμέ;’","st":"3.16"},{"sp":"N","t":"εἰ γὰρ μήπω οὕτως ἔχητε, φεύγετε ἔθη τὰ πρότερον, φεύγετε τοὺς ἰδιώτας, εἰ θέλετε ἄρξασθαί ποτέ τινες εἶναι. περὶ προνοίας. ὅταν τῇ προνοίᾳ ἐγκαλῇς, ἐπιστράφηθι καὶ γνώσῃ, ὅτι κατὰ λόγον γέγονεν.","st":"3.16"},{"sp":"N","t":"‘ναί, ἀλλ᾽ ὁ ἄδικος πλέον ἔχει.’ ἐν τίνι; ἐν ἀργυρίῳ: πρὸς γὰρ τοῦτό σου κρείττων ἐστίν, ὅτι κολακεύει, ἀναισχυντεῖ, ἀγρυπνεῖ. τί θαυμαστόν;","st":"3.17"},{"sp":"N","t":"ἀλλ᾽ ἐκεῖνο βλέπε, εἰ ἐν τῷ πιστὸς εἶναι πλέον σου ἔχει, εἰ ἐν τῷ αἰδήμων. οὐ γὰρ εὑρήσεις: ἀλλ᾽ ὅπου κρείττων, ἐκεῖ σαυτὸν εὑρήσεις πλέον ἔχοντα.","st":"3.17"},{"sp":"N","t":"κἀγώ ποτ᾽ εἶπόν τινι ἀγανακτοῦντι, ὅτι Φιλόστοργος εὐτυχεῖ, Ἤθελες ἂν σὺ μετὰ Σούρα κοιμᾶσθαι;—’μὴ γένοιτο,’ φησίν,","st":"3.17"},{"sp":"N","t":"‘ἐκείνη ἡ ἡμέρα.’ — τί οὖν ἀγανακτεῖς, εἰ λαμβάνει τι ἀνθ᾽ οὗ πωλεῖ; ἢ πῶς μακαρίζεις τὸν διὰ τούτων, ἃ σὺ ἀπεύχῃ, κτώμενον ἐκεῖνα; ἢ τί κακὸν ποιεῖ ἡ πρόνοια, εἰ τοῖς κρείττοσι τὰ κρείττω δίδωσιν; ἢ οὐκ ἔστι κρεῖττον αἰδήμονα εἶναι ἢ πλούσιον; ὡμολόγει. τί οὖν ἀγανακτεῖς, ἄνθρωπε, ἔχων τὸ κρεῖττον;","st":"3.17"},{"sp":"N","t":"μέμνησθε οὖν ἀεὶ καὶ πρόχειρον ἔχετε, ὅτι νόμος οὗτος φυσικὸς τὸν κρείττονα τοῦ χείρονος πλέον ἔχειν, ἐν ᾧ κρείττων ἐστίν, καὶ οὐδέποτ᾽ ἀγανακτήσετε.","st":"3.17"},{"sp":"N","t":"‘ἀλλ᾽ ἡ γυνή μοι κακῶς χρῆται.’ καλῶς. ἄν τίς σου πυνθάνηται, τί ἐστι τοῦτο, λέγε ‘ἡ γυνή μοι κακῶς χρῆται.’ ‘ἄλλο οὖν οὐδέν;’","st":"3.17"},{"sp":"N","t":"οὐδέν. ‘ὁ πατήρ μοι οὐδὲν δίδωσιν.’ ... ὅτι δὲ κακόν ἐστιν, τοῦτο ἔσωθεν αὐτῷ δεῖ προσθεῖναι καὶ προσκαταψεύσασθαι;","st":"3.17"},{"sp":"N","t":"διὰ τοῦτο οὐ δεῖ τὴν πενίαν ἐκβάλλειν, ἀλλὰ τὸ δόγμα τὸ περὶ αὐτῆς, καὶ οὕτως εὐροήσομεν. ὅτι οὐ δεῖ πρὸς τὰς ἀγγελίας ταράσσεσθαι. ὅταν σοί τι προσαγγελθῇ ταρακτικόν, ἐκεῖνο ἔχε πρόχειρον, ὅτι ἀγγελία περὶ οὐδενὸς προαιρετικοῦ γίνεται. μή τι γὰρ δύναταί σοί τις ἀγγεῖλαι,","st":"3.17"},{"sp":"N","t":"ὅτι κακῶς ὑπέλαβες ἢ κακῶς ὠρέχθης; — οὐδαμῶς. — ἀλλ᾽ ὅτι ἀπέθανέν τις: τί οὖν πρὸς σέ; ὅτι σε κακῶς τις λέγει: τί οὖν πρὸς σέ;","st":"3.18"},{"sp":"N","t":"ὅτι ὁ πατὴρ τάδε τινὰ ἑτοιμάζεται: ἐπὶ τίνα; μή τι ἐπὶ τὴν προαίρεσιν; πόθεν δύναται; ἀλλ᾽ ἐπὶ τὸ σωμάτιον, ἐπὶ τὸ κτησείδιον: ἐσώθης, οὐκ ἐπὶ σέ.","st":"3.18"},{"sp":"N","t":"οὐκοῦν ἀλλ᾽ ὁ κριτὴς ἀποφαίνεται ὅτι ἠσέβησας. περὶ Σωκράτους δ᾽ οὐκ ἀπεφήναντο οἱ δικασταί; μή τι σὸν ἔργον ἐστὶ τὸ ἐκεῖνον ἀποφήνασθαι; — οὔ. — τί οὖν ἔτι σοι μέλει;","st":"3.18"},{"sp":"N","t":"ἔστι τι τοῦ πατρός σου ἔργον, ὃ ἂν μὴ ἐκπληρώσῃ, ἀπώλεσεν τὸν πατέρα, τὸν φιλόστοργον, τὸν ἥμερον. ἄλλο δὲ μηδὲν ζήτει τούτου ἕνεκα αὐτὸν ἀπολέσθαι. οὐδέποτε γὰρ ἐν ἄλλῳ μέν τις ἁμαρτάνει, εἰς ἄλλο δὲ βλάπτεται.","st":"3.18"},{"sp":"N","t":"πάλιν σὸν ἔργον τὸ ἀπολογηθῆναι εὐσταθῶς, αἰδημόνως, ἀοργήτως. εἰ δὲ μή, ἀπώλεσας καὶ σὺ τὸν υἱόν, τὸν αἰδήμονα, τὸν γενναῖον.","st":"3.18"},{"sp":"N","t":"τί οὖν; ὁ κριτὴς ἀκίνδυνός ἐστιν; οὔ: ἀλλὰ κἀκείνῳ τὰ ἴσα κινδυνεύεται. τί οὖν ἔτι φοβῇ, τί ἐκεῖνος κρινεῖ; τί σοὶ καὶ τῷ ἀλλοτρίῳ κακῷ;","st":"3.18"},{"sp":"N","t":"σὸν κακόν ἐστι τὸ κακῶς ἀπολογηθῆναι: τοῦτο φυλάσσου μόνον: κριθῆναι δ᾽ ἢ μὴ κριθῆναι ὥσπερ ἄλλου ἐστὶν ἔργον, οὕτως κακὸν ἄλλου ἐστίν.","st":"3.18"},{"sp":"N","t":"‘ἀπειλεῖ σοι ὁ δεῖνα.’ ἐμοί; οὔ. ‘ψέγει σε.’ αὐτὸς ὄψεται, πῶς ποιεῖ τὸ ἴδιον ἔργον. ‘μέλλει σε κατακρινεῖν ἀδίκως.’ ἄθλιος. τίς στάσις ἰδιώτου καὶ φιλοσόφου. ἡ πρώτη διαφορὰ ἰδιώτου καὶ φιλοσόφου: ὁ μὲν λέγει ‘οὐαί μοι διὰ τὸ παιδάριον, διὰ τὸν ἀδελφόν, οὐαὶ διὰ τὸν πατέρα,’ ὁ δ᾽, ἄν ποτ᾽ εἰπεῖν ἀναγκασθῇ, ‘οὐαί μοι’","st":"3.18"},{"sp":"N","t":"ἐπιστήσας λέγει ‘δι᾽ ἐμέ.’ προαίρεσιν γὰρ οὐδὲν δύναται κωλῦσαι ἢ βλάψαι ἀπροαίρετον εἰ μὴ αὐτὴ ἑαυτήν.","st":"3.19"},{"sp":"N","t":"ἂν οὖν ἐπὶ τοῦτο ῥέψωμεν καὶ αὐτοί, ὥσθ᾽ ὅταν δυσοδῶμεν, αὑτοὺς αἰτιᾶσθαι καὶ μεμνῆσθαι, ὅτι οὐδὲν ἄλλο ταραχῆς ἢ ἀκαταστασίας αἴτιόν ἐστιν ἢ δόγμα, ὀμνύω ὑμῖν πάντας θεούς, ὅτι προεκόψ","st":"3.19"},{"sp":"N","t":"αμεν. νῦν δ᾽ ἄλλην ὁδὸν ἐξ ἀρχῆς ἐληλύθαμεν. εὐθὺς ἔτι παίδων ἡμῶν ὄντων ἡ τιτθή, εἴ ποτε προσεπταίσαμεν χάσκοντες, οὐχὶ ἡμῖν ἐπέπλησσεν, ἀλλὰ τὸν λίθον ἔτυπτεν. τί γὰρ ἐποίησεν ὁ λίθος; διὰ τὴν τοῦ παιδίου σου μωρίαν ἔδει μεταβῆναι αὐτόν;","st":"3.19"},{"sp":"N","t":"πάλιν ἂν μὴ εὕρωμεν φαγεῖν ἐκ βαλανείου, οὐδέποθ᾽ ἡμῶν καταστέλλει τὴν ἐπιθυμίαν ὁ παιδαγωγός, ἀλλὰ δέρει τὸν μάγειρον. ἄνθρωπε, μὴ γὰρ ἐκείνου σε παιδαγωγὸν κατεστήσαμεν; ἀλλὰ τοῦ παιδίου ἡμῶν: τοῦτο ἐπανόρθου, τοῦτο ὠφέλει.","st":"3.19"},{"sp":"N","t":"οὕτως καὶ αὐξηθέντες φαινόμεθα παιδία. παῖς γὰρ ἐν μουσικοῖς ὁ ἄμουσος, ἐν γραμματικοῖς ὁ ἀγράμματικος, ἐν βίῳ ὁ ἀπαίδευτος. ὅτι ἀπὸ πάντων τῶν ἐκτὸς ἔστιν ὠφελεῖσθαι. ἐπὶ τῶν θεωρητικῶν φαντασιῶν πάντες σχεδὸν τὸ ἀγαθὸν καὶ τὸ κακὸν ἐν ἡμῖν ἀπέλιπον, οὐχὶ δ᾽ ἐν τοῖς ἐκτός.","st":"3.19"},{"sp":"N","t":"οὐδεὶς λέγει ἀγαθὸν τὸ ἡμέραν εἶναι, κακὸν τὸ νύκτα εἶναι, μέγιστον δὲ κακῶν τὸ τρία τέσσαρα εἶναι. ἀλλὰ τί;","st":"3.20"},{"sp":"N","t":"τὴν μὲν ἐπιστήμην ἀγαθόν, τὴν δ᾽ ἀπάτην κακόν, ὥστε καὶ περὶ αὐτὸ τὸ ψεῦδος ἀγαθὸν συνίστασθαι, τὴν ἐπιστήμην τοῦ ψεῦδος εἶναι αὐτό.","st":"3.20"},{"sp":"N","t":"ἔδει οὖν οὕτως καὶ ἐπὶ τοῦ βίου. ὑγεία ἀγαθόν, νόσος δὲ κακόν; οὔ, ἄνθρωπε. ἀλλὰ τί; τὸ καλῶς ὑγιαίνειν ἀγαθόν, τὸ κακῶς κακόν. — ὥστε καὶ ἀπὸ νόσου ἔστιν ὠφεληθῆναι; — τὸν θεόν σοι, ἀπὸ θανάτου γὰρ οὐκ ἔστιν; ἀπὸ πληρώσεως γὰρ οὐκ ἔστιν,","st":"3.20"},{"sp":"N","t":"μικρά σοι δοκεῖ ὁ Μενοικεὺς ὠφεληθῆναι, ὅτ᾽ ἀπέθνῃσκεν; — τοιαῦτά τις εἰπὼν ὠφεληθείη ἢ οἷα ἐκεῖνος ὠφελήθη. — ἔα, ἄνθρωπε, οὐκ ἐτήρησεν τὸν φιλόπατριν, τὸν μεγαλόφρονα, τὸν πιστόν, τὸν γενναῖον; ἐπιζήσας δὲ οὐκ ἀπώλλυεν ταῦτα πάντα;","st":"3.20"},{"sp":"N","t":"οὐ περιεποιεῖτο τὰ ἐναντία; τὸν δειλὸν οὐκ ἀνελάμβανεν, τὸν ἀγεννῆ, τὸν μισόπατριν, τὸν φιλόψυχον; ἄγε δοκεῖ σοι μικρὰ ὠφεληθῆναι ἀποθανών;","st":"3.20"},{"sp":"N","t":"οὔ: ἀλλ᾽ ὁ τοῦ Ἀδμήτου πατὴρ μεγάλα ὠφελήθη ζήσας οὕτως ἀγεννῶς καὶ ἀθλίως;","st":"3.20"},{"sp":"N","t":"ὕστερον γὰρ οὐκ ἀπέθανεν; παύσασθε, τοὺς θεοὺς ὑμῖν, τὰς ὕλας θαυμάζοντες, παύσασθ᾽ ἑαυτοὺς δούλους ποιοῦντες πρῶτον τῶν πραγμάτων, εἶτα δι᾽ αὐτὰ καὶ τῶν ἀνθρώπων τῶν ταῦτα περιποιεῖν ἢ ἀφαιρεῖσθαι δυναμένων. ἔστιν οὖν ἀπὸ τούτων ὠφεληθῆναι;","st":"3.20"},{"sp":"N","t":"— ἀπὸ πάντων. — καὶ ἀπὸ τοῦ λοιδοροῦντος; — τί δ᾽ ὠφελεῖ τὸν ἀθλητὴν ὁ προσγυμναζόμενος; τὰ μέγιστα. καὶ οὗτος ἐμοῦ προγυμναστὴς γίνεται: τὸ ἀνεκτικόν μου γυμνάζει, τὸ ἀόργητον, τὸ πρᾷον.","st":"3.20"},{"sp":"N","t":"οὔ: ἀλλ᾽ ὁ μὲν τοῦ τραχήλου καθάπτων καὶ τὴν ὀσφῦν μου καὶ τοὺς ὤμους καταρτίζων ὠφελεῖ με καὶ ὁ ἀλείπτης καλῶς ποιῶν λέγει ‘ἆρον ὕπερον ἀμφοτέραις’ καὶ ὅσῳ βαρύτερός ἐστιν ἐκεῖνος, τοσούτῳ μᾶλλον ὠφελοῦμαι ἐγώ: εἰ δέ τις πρὸς ἀοργησίαν με γυμνάζει, οὐκ ὠφελεῖ με;","st":"3.20"},{"sp":"N","t":"τοῦτ᾽ ἔστι τὸ μὴ εἰδέναι ἀπ᾽ ἀνθρώπων ὠφελεῖσθαι. κακὸς γείτων; αὑτῷ: ἀλλ᾽ ἐμοὶ ἀγαθός: γυμνάζει μου τὸ εὔγνωμον, τὸ ἐπιεικές.","st":"3.20"},{"sp":"N","t":"κακὸς πατήρ; αὑτῷ: ἀλλ᾽ ἐμοὶ ἀγαθός. τοῦτ᾽ ἔστι τὸ τοῦ Ἑρμοῦ ῥαβδίον: ‘οὗ θέλεις,’ φησίν, ‘ἅψαι καὶ χρυσοῦν ἔσται.’ οὔ: ἀλλ᾽ ὃ θέλεις φέρε κἀγὼ αὐτὸ ἀγαθὸν ποιήσω. φέρε νόσον, φέρε θάνατον, φέρε ἀπορίαν, φέρε λοιδορίαν, δίκην τὴν περὶ τῶν ἐσχάτων: πάντα ταῦτα τῷ ῥαβδίῳ τοῦ Ἑρμοῦ ὠφέλιμα ἔσται.","st":"3.20"},{"sp":"N","t":"‘τὸν θάνατον τί ποιήσεις;’ τί γὰρ ἄλλο ἢ ἵνα σε κοσμήσῃ ἢ ἵνα δείξῃς ἔργῳ δι᾽ αὐτοῦ, τί ἐστιν ἄνθρωπος τῷ βουλήματι τῆς φύσεως παρακολουθῶν;","st":"3.20"},{"sp":"N","t":"‘τὴν νόσον τί ποιήσεις;’ δείξω αὐτῆς τὴν φύσιν, διαπρέψω ἐν αὐτῇ, εὐσταθήσω, εὐροήσω, τὸν ἰατρὸν οὐ κολακεύσω, οὐκ εὔξομαι ἀποθανεῖν.","st":"3.20"},{"sp":"N","t":"τί ἔτι ἄλλο ζητεῖς; πᾶν ὃ ἂν δῷς, ἐγὼ αὐτὸ ποιήσω μακάριον, εὐδαιμονικόν, σεμνόν, ζηλωτόν. οὔ: ἀλλὰ","st":"3.20"},{"sp":"N","t":"‘βλέπε μὴ νοσήσῃς: κακόν ἐστιν.’ οἷον εἴ τις ἔλεγεν ‘βλέπε μὴ λάβῃς ποτὲ φαντασίαν τοῦ τὰ τρία τέσσαρα εἶναι: κακόν ἐστιν.’ ἄνθρωπε, πῶς κακόν; ἂν ὃ δεῖ περὶ αὐτοῦ ὑπολάβω, πῶς ἔτι με βλάψει; οὐχὶ δὲ μᾶλλον καὶ ὠφελήσει;","st":"3.20"},{"sp":"N","t":"ἂν οὖν περὶ πενίας ὃ δεῖ ὑπολάβω, ἂν περὶ νόσου, ἂν περὶ ἀναρχίας, οὐκ ἀρκεῖ μοι; οὐκ ὠφέλιμα ἔσται; πῶς οὖν ἔτι ἐν τοῖς ἐκτὸς τὰ κακὰ καὶ τἀγαθὰ δεῖ με ζητεῖν;","st":"3.20"},{"sp":"N","t":"ἀλλὰ τί; ταῦτα μέχρι ὧδε, εἰς οἶκον δ᾽ οὐδεὶς ἀποφέρει: ἀλλ᾽ εὐθὺς πρὸς τὸ παιδάριον πόλεμος, πρὸς τοὺς γείτονας, πρὸς τοὺς σκώψαντας, πρὸς τοὺς καταγελάσαντας.","st":"3.20"},{"sp":"N","t":"καλῶς γένοιτο Λεσβίῳ, ὅτι με καθ᾽ ἡμέραν ἐξελέγχει μηδὲν εἰδότα. πρὸς τοὺς εὐκόλως ἐπὶ τὸ σοφιστεύειν ἐρχομένους. ὅτι τὰ θεωρήματα ἀναλαβόντες ψιλὰ εὐθὺς αὐτὰ ἐξεμέσαι θέλουσιν ὡς οἱ στομαχικοὶ τὴν τροφήν.","st":"3.20"},{"sp":"N","t":"πρῶτον αὐτὸ πέψον, εἶθ᾽ οὕτω μὴ ἐξεμέσῃς: εἰ δὲ μή, ἔμετος τῷ ὄντι γίνεται, πρᾶγμ᾽ ἀκάθαρτον καὶ ἄβρωτον.","st":"3.21"},{"sp":"N","t":"ἀλλ᾽ ἀπ᾽ αὐτῶν ἀναδοθέντων δεῖξόν τινα ἡμῖν μεταβολὴν τοῦ ἡγεμονικοῦ τοῦ σεαυτοῦ, ὡς οἱ ἀθληταὶ τοὺς ὤμους, ἀφ᾽ ὧν ἐγυμνάσθησαν καὶ ἔφαγον, ὡς οἱ τὰς τέχνας ἀναλαβόντες, ἀφ᾽ ὧν ἔμαθον.","st":"3.21"},{"sp":"N","t":"οὐκ ἔρχεται ὁ τέκτων καὶ λέγει ‘ἀκούσατέ μου διαλεγομένου περὶ τῶν τεκτονικῶν,’ ἀλλ᾽ ἐκμισθωσάμενος οἰκίαν ταύτην κατασκευάσας δείκνυσιν, ὅτι ἔχει τὴν τέχνην.","st":"3.21"},{"sp":"N","t":"τοιοῦτόν τι καὶ σὺ ποίησον: φάγε ὡς ἄνθρωπος, πίε ὡς ἄνθρωπος, κοσμήθητι, γάμησον, παιδοποίησον, πολίτευσαι: ἀνάσχου λοιδορίας, ἔνεγκε ἀδελφὸν ἀγνώμονα, ἔνεγκε πατέρα, ἔνεγκε υἱόν, γείτονα, σύνοδον.","st":"3.21"},{"sp":"N","t":"ταῦτα ἡμῖν δεῖξον, ἵν᾽ ἴδωμεν, ὅτι μεμάθηκας ταῖς ἀληθείαις τι τῶν φιλοσόφων. οὔ: ἀλλ᾽ ‘ἐλθόντες ἀκούσατέ μου σχόλια λέγοντος.’ ὕπαγε, ζήτει τίνων κατεξεράσεις.","st":"3.21"},{"sp":"N","t":"‘καὶ μὴν ἐγὼ ὑμῖν ἐξηγήσομαι τὰ Χρυσίππεια ὡς οὐδείς, τὴν λέξιν διαλύσω καθαρώτατα, προσθήσω ἄν που καὶ Ἀντιπάτρου καὶ Ἀρχεδήμου φοράν.’","st":"3.21"},{"sp":"N","t":"εἶτα τούτου ἕνεκα ἀπολίπωσιν οἱ νέοι τὰς πατρίδας καὶ τοὺς γονεῖς τοὺς αὑτῶν, ἵν᾽ ἐλθόντες λεξείδιά σου ἐξηγουμένου ἀκούσωσιν;","st":"3.21"},{"sp":"N","t":"οὐ δεῖ αὐτοὺς ὑποστρέψαι ἀνεκτικούς, συνεργητικούς, ἀπαθεῖς, ἀταράχους, ἔχοντάς τι ἐφόδιον τοιοῦτον εἰς τὸν βίον, ἀφ᾽ οὗ ὁρμώμενοι φέρειν δυνήσονται τὰ συμπίπτοντα καλῶς καὶ κοσμεῖσθαι ὑπ᾽ αὐτῶν;","st":"3.21"},{"sp":"N","t":"καὶ πόθεν σοι μεταδιδόναι τούτων ὧν οὐκ ἔχεις; αὐτὸς γὰρ ἄλλο τι ἐποίησας ἐξ ἀρχῆς ἢ περὶ ταῦτα κατετρίβης, πῶς οἱ συλλογισμοὶ ἀναλυθήσονται, πῶς οἱ μεταπίπτοντες, πῶς οἱ τῷ ἠρωτῆσθαι περαίνοντες;","st":"3.21"},{"sp":"N","t":"‘ἀλλ᾽ ὁ δεῖνα σχολὴν ἔχει: διὰ τί μὴ κἀγὼ σχῶ;’ οὐκ εἰκῇ ταῦτα γίνεται, ἀνδράποδον, οὐδ᾽ ὡς ἔτυχεν, ἀλλὰ καὶ ἡλικίαν εἶναι δεῖ καὶ βίον καὶ θεὸν ἡγεμόνα.","st":"3.21"},{"sp":"N","t":"οὔ: ἀλλ᾽ ἀπὸ λιπομένος μὲν οὐδεὶς ἀνάγεται μὴ θύσας τοῖς θεοῖς καὶ παρακαλέσας αὐτοὺς βοηθοὺς οὐδὲ σπείρουσιν ἄλλως οἱ ἄνθρωποι εἰ μὴ τὴν Δήμητρα ἐπικαλεσάμενοι: τηλικούτου δ᾽ ἔργου ἁψάμενός τις ἄνευ θεῶν ἀσφαλῶς ἅψεται καὶ οἱ τούτῳ προσιόντες εὐτυχῶς προσελεύσονται;","st":"3.21"},{"sp":"N","t":"τί ἄλλο ποιεῖς, ἄνθρωπε, ἢ τὰ μυστήρια ἐξορχῇ καὶ λέγεις ‘οἴκημά ἐστι καὶ ἐν Ἐλευσῖνι, ἰδοὺ καὶ ἐνθάδε. ἐκεῖ ἱεροφάντης: καὶ ἐγὼ ποιήσω ἱεροφάντην. ἐκεῖ κήρυξ: κἀγὼ κήρυκα καταστήσω. ἐκεῖ δᾳδοῦχος: κἀγὼ δᾳδοῦχον. ἐκεῖ δᾷδες: καὶ ἐνθάδε. αἱ φωναὶ αἱ αὐταί: τὰ γινόμενα τί διαφέρει ταῦτα ἐκείνων;’","st":"3.21"},{"sp":"N","t":"ἀσεβέστατε ἄνθρωπε, οὐδὲν διαφέρει; καὶ παρὰ τόπον ταῦτα ὠφελεῖ καὶ παρὰ καιρόν: καὶ μετὰ θυσίας δὲ καὶ μετ᾽ εὐχῶν καὶ προηγνευκότα καὶ προδιακείμενον τῇ γνώμῃ, ὅτι ἱεροῖς προσελεύσεται καὶ ἱεροῖς παλαιοῖς. οὕτως ὠφέλιμα γίνεται τὰ μυστήρια,","st":"3.21"},{"sp":"N","t":"οὕτως εἰς φαντασίαν ἐρχόμεθα, ὅτι ἐπὶ παιδείᾳ καὶ ἐπανορθώσει τοῦ βίου κατεστάθη πάντα ταῦτα ὑπὸ τῶν παλαιῶν.","st":"3.21"},{"sp":"N","t":"σὺ δ᾽ ἐξαγγέλλεις αὐτὰ καὶ ἐξορχῇ παρὰ καιρόν, παρὰ τόπον, ἄνευ θυμάτων, ἄνευ ἁγνείας: οὐκ ἐσθῆτα ἔχεις ἣν δεῖ τὸν ἱεροφάντην, οὐ κόμην, οὐ στρόφιον οἷον δεῖ, οὐ φωνήν, οὐχ ἡλικίαν, οὐχ ἥγνευκας ὡς ἐκεῖνος, ἀλλ᾽ αὐτὰς μόνας τὰς φωνὰς ἀνειληφὼς λέγεις. ἱεραί εἰσιν αἱ φωναὶ αὐταὶ καθ᾽ αὑτάς;","st":"3.21"},{"sp":"N","t":"ἄλλον τρόπον δεῖ ἐπὶ ταῦτα ἐλθεῖν: μέγα ἐστὶ τὸ πρᾶγμα, μυστικόν ἐστιν, οὐχ ὡς ἔτυχεν οὐδὲ τῷ τυχόντι δεδομένον.","st":"3.21"},{"sp":"N","t":"ἀλλ᾽ οὐδὲ σοφὸν εἶναι τυχὸν ἐξαρκεῖ πρὸς τὸ ἐπιμεληθῆναι νέων: δεῖ δὲ καὶ προχειρότητά τινα εἶναι καὶ ἐπιτηδειότητα πρὸς τοῦτο, νὴ τὸν Δία, καὶ σῶμα ποιὸν καὶ πρὸ πάντων τὸν θεὸν συμβουλεύειν ταύτην τὴν χώραν κατασχεῖν,","st":"3.21"},{"sp":"N","t":"ὡς Σωκράτει συνεβούλευεν τὴν ἐλεγκτικὴν χώραν ἔχειν, ὡς Διογένει τὴν βασιλικὴν καὶ ἐπιπληκτικήν, ὡς Ζήνωνι τὴν διδασκαλικὴν καὶ δογματικήν.","st":"3.21"},{"sp":"N","t":"σὺ δ᾽ ἰατρεῖον ἀνοίγεις ἄλλο οὐδὲν ἔχων ἢ φάρμακα, ποῦ δὲ ἢ πῶς ἐπιτίθεται ταῦτα, μήτε εἰδὼς μήτε πολυπραγμονήσας.","st":"3.21"},{"sp":"N","t":"‘ἰδοὺ ἐκεῖνος ταῦτα, κολλύρια: κἀγὼ ἔχω.’ μή τι οὖν καὶ τὴν δύναμιν τὴν χρηστικὴν αὐτοῖς; μή τι οἶδας καὶ πότε καὶ πῶς ὠφελήσει καὶ τίνα;","st":"3.21"},{"sp":"N","t":"τί οὖν κυβεύεις ἐν τοῖς μεγίστοις, τί ῥᾳδιουργεῖς, τί ἐπιχειρεῖς πράγματι μηδέν σοι προσήκοντι; ἄφες αὐτὸ τοῖς δυναμένοις, τοῖς κοσμοῦσι. μὴ προστρίβου καὶ αὐτὸς αἶσχος φιλοσοφίᾳ διὰ σαυτοῦ, μηδὲ γίνου μέρος τῶν διαβαλλόντων τὸ ἔργον.","st":"3.21"},{"sp":"N","t":"ἀλλὰ εἴ σε ψυχαγωγεῖ τὰ θεωρήματα, καθήμενος αὐτὰ στρέφε αὐτὸς ἐπὶ σεαυτοῦ: φιλόσοφον δὲ μηδέποτ᾽ εἴπῃς σεαυτὸν μηδ᾽ ἄλλου ἀνάσχῃ λέγοντος, ἀλλὰ λέγε ‘πεπλάνηται: ἐγὼ γὰρ οὔτ᾽ ὀρέγομαι ἄλλως ἢ πρότερον οὐδ᾽ ὁρμῶ ἐπ᾽ ἄλλα οὐδὲ συγκατατίθεμαι ἄλλοις οὐδ᾽ ὅλως ἐν χρήσει φαντασιῶν παρήλλαχά τι ἀπὸ τῆς πρότερον καταστάσεως.’","st":"3.21"},{"sp":"N","t":"ταῦτα φρόνει καὶ λέγε περὶ σεαυτοῦ, εἰ θέλεις τὰ κατ᾽ ἀξίαν φρονεῖν: εἰ δὲ μή, κύβευε καὶ ποίει ἃ ποιεῖς. ταῦτα γάρ σοι πρέπει. περὶ Κυνισμοῦ. πυθομένου δὲ τῶν γνωρίμων τινὸς αὐτοῦ, ὃς ἐφαίνετο ἐπιρρεπῶς ἔχων πρὸς τὸ κυνίσαι, Ποῖόν τινα εἶναι δεῖ τὸν κυνίζοντα καὶ τίς ἡ πρόληψις ἡ τοῦ πράγματος, Σκεψόμεθα κατὰ σχολήν.","st":"3.21"},{"sp":"N","t":"τοσοῦτον δ᾽ ἔχω σοι εἰπεῖν, ὅτι ὁ δίχα θεοῦ τηλικούτῳ πράγματι ἐπιβαλλόμενος θεοχόλωτός ἐστι καὶ οὐδὲν ἄλλο ἢ δημοσίᾳ θέλει ἀσχημονεῖν.","st":"3.22"},{"sp":"N","t":"οὐδὲ γὰρ ἐν οἰκίᾳ καλῶς οἰκουμένῃ παρελθών τις αὐτὸς ἑαυτῷ λέγει ‘ἐμὲ δεῖ οἰκονόμον εἶναι:’ εἰ δὲ μή, ἐπιστραφεὶς ὁ κύριος καὶ ἰδὼν αὐτὸν σοβαρῶς διατασσόμενον, ἑλκύσας ἔτεμεν.","st":"3.22"},{"sp":"N","t":"οὕτως γίνεται καὶ ἐν τῇ μεγάλῃ ταύτῃ πόλει. ἔστι γάρ τις καὶ ἐνθάδ᾽ οἰκοδεσπότης ἕκαστα ὁ διατάσσων.","st":"3.22"},{"sp":"N","t":"‘σὺ ἥλιος εἶ: δύνασαι περιερχόμενος ἐνιαυτὸν ποιεῖν καὶ ὥρας καὶ τοὺς καρποὺς αὔξειν καὶ τρέφειν καὶ ἀνέμους κινεῖν καὶ ἀνιέναι καὶ τὰ σώματα τῶν ἀνθρώπων θερμαίνειν συμμέτρως: ὕπαγε, περιέρχου καὶ οὕτως διακίνει ἀπὸ τῶν μεγίστων ἐπὶ τὰ μικρότατα.","st":"3.22"},{"sp":"N","t":"σὺ μοσχάριον εἶ: ὅταν ἐπιφανῇ λέων, τὰ σαυτοῦ πρᾶσσε: εἰ δὲ μή, οἰμώξεις. σὺ ταῦρος εἶ, προσελθὼν μάχου: σοὶ γὰρ τοῦτο ἐπιβάλλει καὶ πρέπει καὶ δύνασαι αὐτὸ ποιεῖν.","st":"3.22"},{"sp":"N","t":"σὺ δύνασαι ἡγεῖσθαι τοῦ στρατεύματος ἐπὶ Ἴλιον: ἴσθι Ἀγαμέμνων. σὺ δύνασαι τῷ Ἕκτορι μονομαχῆσαι: ἴσθι Ἀχιλλεύς.’","st":"3.22"},{"sp":"N","t":"εἰ δὲ Θερσίτης παρελθὼν ἀντεποιεῖτο τῆς ἀρχῆς, ἢ οὐκ ἂν ἔτυχεν ἢ τυχὼν ἂν ἠσχημόνησεν ἐν πλείοσι μάρτυσι.","st":"3.22"},{"sp":"N","t":"καὶ σὺμβούλευσαι περὶ πράγματος ἐπιμελῶς: οὐκ ἔστιν οἷον δοκεῖ σοι.","st":"3.22"},{"sp":"N","t":"‘τριβώνιον καὶ νῦν φορῶ καὶ τόθ᾽ ἕξω, κοιμῶμαι καὶ νῦν σκληρῶς καὶ τότε κοιμήσομαι, πηρίδιον προσλήψομαι καὶ ξύλον καὶ περιερχόμενος αἰτεῖν ἄρξομαι τοὺς ἀπαντῶντας, λοιδορεῖν: κἂν ἴδω τινὰ δρωπακιζόμενον, ἐπιτιμήσω αὐτῷ, κἂν τὸ κόμιον πεπλακότα ἢ ἐν κοκκίνοις περιπατοῦντα.’","st":"3.22"},{"sp":"N","t":"εἰ τοιοῦτόν τι φαντάζῃ τὸ πρᾶγμα, μακρὰν ἀπ᾽ αὐτοῦ: μὴ προσέλθῃς, οὐδέν ἐστι πρὸς σέ.","st":"3.22"},{"sp":"N","t":"εἰ δ᾽ οἷόν ἐστι φανταζόμενος οὐκ ἀπαξιοῖς σεαυτόν, σκέψαι ἡλίκῳ πράγματι ἐπιχειρεῖς.","st":"3.22"},{"sp":"N","t":"πρῶτον ἐν τοῖς κατὰ σαυτὸν οὐκέτι δεῖ σε ὅμοιον ἐν οὐδενὶ φαίνεσθαι οἷς νῦν ποιεῖς, οὐ θεῷ ἐγκαλοῦντα, οὐκ ἀνθρώπῳ: ὄρεξιν ἆραί σε δεῖ παντελῶς, ἔκκλισιν ἐπὶ μόνα μεταθεῖναι τὰ προαιρετικά: σοὶ μὴ ὀργὴν εἶναι, μὴ μῆνιν, μὴ φθόνον, μὴ ἔλεον: μὴ κοράσιόν σοι φαίνεσθαι καλόν, μὴ δοξάριον, μὴ παιδάριον, μὴ πλακουντάριον.","st":"3.22"},{"sp":"N","t":"ἐκεῖνο γὰρ εἰδέναι σε δεῖ, ὅτι οἱ ἄλλοι ἄνθρωποι τοὺς τοίχους προβέβληνται καὶ τὰς οἰκίας καὶ τὸ σκότος, ὅταν τι τῶν τοιούτων ποιῶσιν, καὶ τὰ κρύψοντα πολλὰ ἔχουσιν. κέκλεικε τὴν θύραν, ἕστακέν τινα πρὸ τοῦ κοιτῶνος: ‘ἄν τις ἔλθῃ, λέγε ὅτι ἔξω ἐστίν, οὐ σχολάζει.’","st":"3.22"},{"sp":"N","t":"ὁ Κυνικὸς δ᾽ ἀντὶ πάντων τούτων ὀφείλει τὴν αἰδῶ προβεβλῆσθαι: εἰ δὲ μή, γυμνὸς καὶ ἐν ὑπαίθρῳ ἀσχημονήσει. τοῦτο οἰκία ἐστὶν αὐτῷ, τοῦτο θύρα, τοῦτο οἱ ἐπὶ τοῦ κοιτῶνος, τοῦτο σκότος.","st":"3.22"},{"sp":"N","t":"οὔτε γὰρ θέλειν τι δεῖ ἀποκρύπτειν αὐτὸν τῶν ἑαυτοῦ （ εἰ δὲ μή, ἀπῆλθεν, ἀπώλεσε τὸν Κυνικόν, τὸν ὕπαιθρον, τὸν ἐλεύθερον, ἦρκταί τι τῶν ἐντὸς φοβεῖσθαι, ἦρκται χρείαν ἔχειν τοῦ ἀποκρύψοντος ） οὔτε ὅταν θέλῃ δύναται. ποῦ γὰρ αὑτὸν ἀποκρύψῃ ἢ πῶς;","st":"3.22"},{"sp":"N","t":"ἂν δ᾽ ἀπὸ τύχης ἐμπέσῃ ὁ παιδευτὴς ὁ κοινός, ὁ παιδαγωγός, οἷα πάσχειν ἀνάγκη;","st":"3.22"},{"sp":"N","t":"ταῦτ᾽ οὖν δεδοικότα ἐπιθαρρεῖν οἷόν τ᾽ ἔτι ἐξ ὅλης ψυχῆς ἐπιστατεῖν τοῖς ἄλλοις ἀνθρώποις;","st":"3.22"},{"sp":"N","t":"ἀμήχανον, ἀδύνατον. πρῶτον οὖν τὸ ἡγεμονικόν σε δεῖ τὸ σαυτοῦ καθαρὸν ποιῆσαι καὶ τὴν ἔνστασιν ταύτην:","st":"3.22"},{"sp":"N","t":"‘νῦν ἐμοὶ ὕλη ἐστὶν ἡ ἐμὴ διάνοια, ὡς τῷ τέκτονι τὰ ξύλα, ὡς τῷ σκυτεῖ τὰ δέρματα: ἔργον δ᾽ ὀρθὴ χρῆσις τῶν φαντασιῶν.","st":"3.22"},{"sp":"N","t":"τὸ σωμάτιον δὲ οὐδὲν πρὸς ἐμέ: τὰ τούτου μέρη οὐδὲν πρὸς ἐμέ. θάνατος; ἐρχέσθω, ὅταν θέλῃ, εἴτε ὅλου εἴτε μέρους τινός.","st":"3.22"},{"sp":"N","t":"φυγή; καὶ ποῦ δύναταί τις ἐκβαλεῖν; ἔξω τοῦ κόσμου οὐ δύναται. ὅπου δ᾽ ἂν ἀπέλθω, ἐκεῖ ἥλιος, ἐκεῖ σελήνη, ἐκεῖ ἄστρα, ἐνύπνια, οἰωνοί, ἡ πρὸς θεοὺς ὁμιλία.’","st":"3.22"},{"sp":"N","t":"εἶθ᾽ οὕτως παρασκευασάμενον οὐκ ἔστι τούτοις ἀρκεῖσθαι τὸν ταῖς ἀληθείαις Κυνικόν, ἀλλ᾽ εἰδέναι δεῖ, ὅτι ἄγγελος ἀπὸ τοῦ Διὸς ἀπέσταλται καὶ πρὸς τοὺς ἀνθρώπους περὶ ἀγαθῶν καὶ κακῶν ὑποδείξων αὐτοῖς, ὅτι πεπλάνηνται καὶ ἀλλαχοῦ ζητοῦσι τὴν οὐσίαν τοῦ ἀγαθοῦ καὶ τοῦ κακοῦ, ὅπου οὐκ ἔστιν, ὅπου δ᾽ ἔστιν, οὐκ ἐνθυμοῦνται,","st":"3.22"},{"sp":"N","t":"καὶ ὡς ὁ Διογένης ἀπαχθεὶς πρὸς Φίλιππον μετὰ τὴν ἐν Χαιρωνείᾳ μάχην κατάσκοπος εἶναι. τῷ γὰρ ὄντι κατάσκοπός ἐστιν ὁ Κυνικὸς τοῦ τίνα ἐστὶ τοῖς ἀνθρώποις φίλα καὶ τίνα πολέμια.","st":"3.22"},{"sp":"N","t":"καὶ δεῖ αὐτὸν ἀκριβῶς κατασκεψάμενον ἐλθόντ᾽ ἀπαγγεῖλαι τἀληθῆ μήθ᾽ ὑπὸ φόβου ἐκπλαγέντα, ὥστε τοὺς μὴ ὄντας πολεμίους δεῖξαι, μήτε τινὰ ἄλλον τρόπον ὑπὸ τῶν φαντασιῶν παραταραχθέντα ἢ συγχυθέντα.","st":"3.22"},{"sp":"N","t":"δεῖ οὖν αὐτὸν δύνασθαι ἀνατεινάμενον, ἂν οὕτως τύχῃ, καὶ ἐπὶ σκηνὴν τραγικὴν ἀνερχόμενον λέγειν τὸ τοῦ Σωκράτους: ἰὼ ἄνθρωποι, ποῖ φέρεσθε; τί ποιεῖτε, ὦ ταλαίπωροι; ὡς τυφλοὶ ἄνω καὶ κάτω κυλίεσθε: ἄλλην ὁδὸν ἀπέρχεσθε τὴν οὖσαν ἀπολελοιπότες, ἀλλαχοῦ ζητεῖτε τὸ εὔρουν καὶ τὸ εὐδαιμονικόν, ὅπου οὐκ ἔστιν, οὐδ᾽ ἄλλου δεικνύοντος πιστεύετε.","st":"3.22"},{"sp":"N","t":"τί αὐτὸ ἔξω ζητεῖτε; ἐν σώματι οὐκ ἔστιν. εἰ ἀπιστεῖτε, ἴδετε Μύρωνα, ἴδετε Ὀφέλλιον. ἐν κτήσει οὐκ ἔστιν. εἰ δ᾽ ἀπιστεῖτε, ἴδετε Κροῖσον, ἴδετε τοὺς νῦν πλουσίους, ὅσης οἰμωγῆς ὁ βίος αὐτῶν μεστός ἐστιν. ἐν ἀρχῇ οὐκ ἔστιν. εἰ δὲ μή γε, ἔδει τοὺς δὶς καὶ τρὶς ὑπάτους εὐδαίμονας εἶναι: οὐκ εἰσὶ δέ.","st":"3.22"},{"sp":"N","t":"τίσιν περὶ τούτου πιστεύσομεν; ὑμῖν τοῖς ἔξωθεν τὰ ἐκείνων βλέπουσιν καὶ ὑπὸ τῆς φαντασίας περιλαμπομένοις ἢ αὐτοῖς ἐκείνοις;","st":"3.22"},{"sp":"N","t":"τί λέγουσιν; ἀκούσατε αὐτῶν, ὅταν οἰμώζωσιν, ὅταν στένωσιν, ὅταν δι᾽ αὐτὰς τὰς ὑπατείας καὶ τὴν δόξαν καὶ τὴν ἐπιφάνειαν ἀθλιώτερον οἴωνται καὶ ἐπικινδυνότερον ἔχειν.","st":"3.22"},{"sp":"N","t":"ἐν βασιλείᾳ οὐκ ἔστιν. εἰ δὲ μή, Νέρων ἂν εὐδαίμων ἐγένετο καὶ Σαρδανάπαλλος. ἀλλ᾽ οὐδ᾽ Ἀγαμέμνων εὐδαίμων ἦν καίτοι κομψότερος ὢν Σαρδαναπάλλου καὶ Νέρωνος, ἀλλὰ τῶν ἄλλων ῥεγκόντων ἐκεῖνος τί ποιεῖ; πολλὰς ἐκ κεφαλῆς προθελύμνους ἕλκετο χαίτας. καὶ αὐτὸς τί λέγει; πλάζομαι ὧδε, φησίν, καὶ ἀλαλύκτημαι: κραδίη δέ μοι ἔξω στηθέων ἐκθρῴσκει. τάλας, τί τῶν σῶν ἔχει κακῶς;","st":"3.22"},{"sp":"N","t":"ἡ κτῆσις; οὐκ ἔχει. τὸ σῶμα; οὐκ ἔχει. ἀλλὰ πολύχρυσος εἶ καὶ πολύχαλκος: τί οὖν σοι κακόν ἐστιν; ἐκεῖνο, ὅ τι ποτὲ ἠμέληταί σου καὶ κατέφθαρται, ᾧ ὀρεγόμεθα, ᾧ ἐκκλίνομεν, ᾧ ὁρμῶμεν καὶ ἀφορμῶμεν.","st":"3.22"},{"sp":"N","t":"πῶς ἠμέληται; ἀγνοεῖ τὴν οὐσίαν τοῦ ἀγαθοῦ πρὸς ἣν πέφυκε καὶ τὴν τοῦ κακοῦ καὶ τί ἴδιον ἔχει καὶ τί ἀλλότριον. καὶ ὅταν τι τῶν ἀλλοτρίων κακῶς ἔχῃ, λέγει ‘οὐαί μοι, οἱ γὰρ Ἕλληνες κινδυνεύουσι.’","st":"3.22"},{"sp":"N","t":"ταλαίπωρον ἡγεμονικὸν καὶ μόνον ἀτημέλητον καὶ ἀθεράπευτον. ‘μέλλουσιν ἀποθνῄσκειν ὑπὸ τῶν Τρώων ἀναιρεθέντες.’ ἂν δ᾽ αὐτοὺς οἱ Τρῶες μὴ ἀποκτείνωσιν, οὐ μὴ ἀποθάνωσιν; ‘ναί, ἀλλ᾽ οὐχ᾽ ὑφ᾽ ἓν πάντες.’ τί οὖν διαφέρει; εἰ γὰρ κακόν ἐστι τὸ ἀποθανεῖν, ἄν τε ὁμοῦ ἄν τε καθ᾽ ἕνα ὁμοίως κακόν ἐστιν. μή τι ἄλλο τι μέλλει γίνεσθαι ἢ τὸ σωμάτιον χωρίζεσθαι καὶ ἡ ψυχή;","st":"3.22"},{"sp":"N","t":"οὐδέν. σοὶ δὲ ἀπολλυμένων τῶν Ἑλλήνων ἡ θύρα κέκλεισται; οὐκ ἔξεστιν ἀποθανεῖν; ‘ἔξεστιν.’ τί οὖν πενθεῖς; ‘οὐᾶ, βασιλεὺς καὶ τὸ τοῦ Διὸς σκῆπτρον ἔχων.’ ἀτυχὴς βασιλεὺς οὐ γίνεται: οὐ μᾶλλον ἢ ἀτυχὴς θεός.","st":"3.22"},{"sp":"N","t":"τί οὖν εἶ; ποιμὴν ταῖς ἀληθείαις: οὕτως γὰρ κλάεις ὡς οἱ ποιμένες, ὅταν λύκος ἁρπάσῃ τι τῶν προβάτων αὐτῶν: καὶ οὗτοι δὲ πρόβατά εἰσιν οἱ ὑπὸ σοῦ ἀρχόμενοι.","st":"3.22"},{"sp":"N","t":"τί δὲ καὶ ἤρχου; μή τι ὄρεξις ὑμῖν ἐκινδυνεύετο, μή τι ἔκκλισις, μή τι ὁρμή, μή τι ἀφορμή; ‘οὔ,’ φησίν, ‘ἀλλὰ τοῦ ἀδελφοῦ μου τὸ γυναικάριον ἡρπάγη.’","st":"3.22"},{"sp":"N","t":"οὐκ οὖν κέρδος μέγα στερηθῆναι μοιχικοῦ γυναικαρίου; ‘καταφρονηθῶμεν οὖν ὑπὸ τῶν Τρώων;’ τίνων ὄντων; φρονίμων ἢ ἀφρόνων; εἰ φρονίμων, τί αὐτοῖς πολεμεῖτε; εἰ ἀφρόνων, τί ὑμῖν μέλει;","st":"3.22"},{"sp":"N","t":"‘ἐν τίνι οὖν ἔστι τὸ ἀγαθόν, ἐπειδὴ ἐν τούτοις οὐκ ἔστιν; εἰπὲ ἡμῖν, κύριε ἄγγελε καὶ κατάσκοπε.’ ‘ὅπου οὐ δοκεῖτε οὐδὲ θέλετε ζητῆσαι αὐτό. εἰ γὰρ ἠθέλετε, εὕρετε ἂν αὐτὸ ἐν ὑμῖν ὂν οὐδ᾽ ἂν ἔξω ἐπλάζεσθε οὐδ᾽ ἂν ἐζητεῖτε τὰ ἀλλότρια ὡς ἴδια.","st":"3.22"},{"sp":"N","t":"ἐπιστρέψατε αὐτοὶ ἐφ᾽ ἑαυτούς, καταμάθετε τὰς προλήψεις ἃς ἔχετε. ποῖόν τι φαντάζεσθε τὸ ἀγαθόν; τὸ εὔρουν, τὸ εὐδαιμονικόν, τὸ ἀπαραπόδιστον. ἄγε, μέγα δ᾽ αὐτὸ φυσικῶς οὐ φαντάζεσθε; ἀξιόλογον οὐ φαντάζεσθε; ἀβλαβὲς οὐ φαντάζεσθε;","st":"3.22"},{"sp":"N","t":"ἐν ποίᾳ οὖν ὕλῃ δεῖ ζητεῖν τὸ εὔρουν καὶ ἀπαραπόδιστον; ἐν τῇ δούλῃ ἢ ἐν τῇ ἐλευθέρᾳ;’ ‘ἐν τῇ ἐλευθέρᾳ.’ ‘τὸ σωμάτιον οὖν ἐλεύθερον ἔχετε ἢ δοῦλον;’ ‘οὐκ ἴσμεν.’ ‘οὐκ ἴστε ὅτι πυρετοῦ δοῦλόν ἐστιν, ποδάγρας, ὀφθαλμίας, δυσεντερίας, τυράννου, πυρός, σιδήρου, παντὸς τοῦ ἰσχυροτέρου;’","st":"3.22"},{"sp":"N","t":"‘ναὶ δοῦλον.’ ‘πῶς οὖν ἔτι ἀνεμπόδιστον εἶναί τι δύναται τῶν τοῦ σώματος; πῶς δὲ μέγα ἢ ἀξιόλογον τὸ φύσει νεκρόν, ἡ γῆ, ὁ πηλός; τί οὖν; οὐδὲν ἔχετε ἐλεύθερον;’ ‘μήποτε οὐδέν.’","st":"3.22"},{"sp":"N","t":"‘καὶ τίς ὑμᾶς ἀναγκάσαι δύναται συγκαταθέσθαι τῷ ψευδεῖ φαινομένῳ;’ ‘οὐδείς.’ ‘τίς δὲ μὴ συγκαταθέσθαι τῷ φαινομένῳ ἀληθεῖ;’ ‘οὐδείς.’ ‘ἐνθάδ᾽ οὖν ὁρᾶτε, ὅτι ἔστι τι ἐν ὑμῖν ἐλεύθερον φύσει.","st":"3.22"},{"sp":"N","t":"ὀρέγεσθαι δ᾽ ἢ ἐκκλίνειν ἢ ὁρμᾶν ἢ ἀφορμᾶν ἢ παρασκευάζεσθαι ἢ προτίθεσθαι τίς ὑμῶν δύναται μὴ λαβὼν φαντασίαν λυσιτελοῦς ἢ μὴ καθήκοντος;’ ‘οὐδείς.’ ‘ἔχετε οὖν καὶ ἐν τούτοις ἀκώλυτον καὶ ἐλεύθερον.","st":"3.22"},{"sp":"N","t":"ταλαίπωροι, τοῦτο ἐξεργάζεσθε, τούτου ἐπιμέλεσθε, ἐνταῦθα ζητεῖτε τὸ ἀγαθόν.’","st":"3.22"},{"sp":"N","t":"καὶ πῶς ἐνδέχεται μηδὲν ἔχοντα, γυμνόν, ἄοικον, ἀνέστιον, αὐχμῶντα, ἄδουλον, ἄπολιν διεξάγειν εὐρόως;","st":"3.22"},{"sp":"N","t":"ἰδοὺ ἀπέσταλκεν ὑμῖν ὁ θεὸς τὸν δείξοντα ἔργῳ, ὅτι ἐνδέχεται.","st":"3.22"},{"sp":"N","t":"‘ἴδετέ με, ἄοικός εἰμι, ἄπολις, ἀκτήμων, ἄδουλος: χαμαὶ κοιμῶμαι: οὐ γυνή, οὐ παιδία, οὐ πραιτωρίδιον, ἀλλὰ γῆ μόνον καὶ οὐρανὸς καὶ ἓν τριβωνάριον.","st":"3.22"},{"sp":"N","t":"καὶ τί μοι λείπειν; οὐκ εἰμὶ ἄλυπος, οὐκ εἰμὶ ἄφοβος, οὐκ εἰμὶ ἐλεύθερος; πότε ὑμῶν εἶδέν μέ τις ἐν ὀρέξει με ἀποτυγχάνοντα, πότ᾽ ἐν ἐκκλίσει περιπίπτοντα; πότ᾽ ἐμεμψάμην ἢ θεὸν ἢ ἄνθρωπον, πότ᾽ ἐνεκάλεσά τινι; μή τις ὑμῶν ἐσκυθρωπακότα με εἶδεν; πῶς δ᾽ ἐντυγχάνω τούτοις,","st":"3.22"},{"sp":"N","t":"οὓς ὑμεῖς φοβεῖσθε καὶ θαυμάζετε; οὐχ ὡς ἀνδραπόδοις; τίς με ἰδὼν οὐχὶ τὸν βασιλέα τὸν ἑαυτοῦ ὁρᾶν οἴεται καὶ δεσπότην;’","st":"3.22"},{"sp":"N","t":"ἴδε κυνικαὶ φωναί, ἴδε χαρακτήρ, ἴδ᾽ ἐπιβολή. οὔ: ἀλλὰ πηρίδιον καὶ ξύλον καὶ γνάθοι μεγάλαι: καταφαγεῖν πᾶν ὃ εἂν δῷς ἢ ἀποθησαυρίσαι ἢ τοῖς ἀπαντῶσι λοιδορεῖσθαι ἀκαίρως ἢ καλὸν τὸν ὦμον δεικνύειν.","st":"3.22"},{"sp":"N","t":"τηλικούτῳ πράγματι ὁρᾷς πῶς μέλλεις ἐγχειρεῖν; ἔσοπτρον πρῶτον λάβε, ἴδε σου τοὺς ὤμους, κατάμαθε τὴν ὀσφύν, τοὺς μηρούς. Ὀλύμπια μέλλεις ἀπογράφεσθαι, ἄνθρωπε, οὐχί τινά ποτε ἀγῶνα ψυχρὸν καὶ ταλαίπωρον.","st":"3.22"},{"sp":"N","t":"οὐκ ἔστιν ἐν Ὀλυμπίοις νικηθῆναι μόνον καὶ ἐξελθεῖν, ἀλλὰ πρῶτον μὲν ὅλης τῆς οἰκουμένης βλεπούσης δεῖ ἀσχημονῆσαι, οὐχὶ Ἀθηναίων μόνον ἢ Λακεδαιμονίων ἢ Νικοπολιτῶν, εἶτα καὶ δέρεσθαι δεῖ τὸν εἰκῇ ἐξελθόντα, πρὸ δὲ τοῦ δαρῆναι διψῆσαι, καυματισθῆναι, πολλὴν ἁφὴν καταπιεῖν.","st":"3.22"},{"sp":"N","t":"βούλευσαι ἐπιμελέστερον, γνῶθι σαυτόν, ἀνάκρινον τὸ δαιμόνιον, δίχα θεοῦ μὴ ἐπιχειρήσῃς. ἂν γὰρ συμβουλεύσῃ, ἴσθι ὅτι μέγαν σε θέλει γενέσθαι ἢ πολλὰς πληγὰς λαβεῖν.","st":"3.22"},{"sp":"N","t":"καὶ γὰρ τοῦτο λίαν κομψὸν τῷ Κυνικῷ παραπέπλεκται: δέρεσθαι αὐτὸν δεῖ ὡς ὄνον καὶ δερόμενον φιλεῖν αὐτοὺς τοὺς δέροντας ὡς πατέρα πάντων, ὡς ἀδελφόν.","st":"3.22"},{"sp":"N","t":"οὔ: ἀλλ᾽ ἄν τίς σε δέρῃ, κραύγαζε στὰς ἐν τῷ μέσῳ ‘ὦ Καῖσαρ, ἐν τῇ σῇ εἰρήνῃ οἷα πάσχω; ἄγωμεν ἐπὶ τὸν ἀνθύπατον.’","st":"3.22"},{"sp":"N","t":"Κυνικῷ δὲ Καῖσαρ τί ἐστιν ἢ ἀνθύπατος ἢ ἄλλος ἢ ὁ καταπεπομφὼς αὐτὸν καὶ ᾧ λατρεύει, ὁ Ζεύς; ἄλλον τινὰ ἐπικαλεῖται ἢ ἐκεῖνον; οὐ πέπεισται δ᾽, ὅ τι ἂν πάσχῃ τούτων, ὅτι ἐκεῖνος αὐτὸν γυμνάζει;","st":"3.22"},{"sp":"N","t":"ἀλλ᾽ ὁ μὲν Ἡρακλῆς ὑπὸ Εὐρυσθέως γυμναζόμενος οὐκ ἐνόμιζεν ἄθλιος εἶναι, ἀλλ᾽ ἀόκνως ἐπετέλει πάντα τὰ προσταττόμενα: οὗτος δ᾽ ὑπὸ τοῦ Διὸς ἀθλούμενος καὶ γυμναζόμενος μέλλει κεκραγέναι καὶ ἀγανακτεῖν, ἄξιος φορεῖν τὸ σκῆπτρον τὸ Διογένους; ἄκουε, τί λέγει ἐκεῖνος πυρέσσων πρὸς τοὺς παριόντας:","st":"3.22"},{"sp":"N","t":"‘κακαί,’ ἔφη, ‘κεφαλαί, οὐ μενεῖτε; ἀλλ᾽ ἀθλητῶν μὲν ὄλεθρον ἢ μάχην ὀψόμενοι ἄπιτε ὁδὸν τοσαύτην εἰς Ὀλυμπίαν: πυρετοῦ δὲ καὶ ἀνθρώπου μάχην ἰδεῖν οὐ βούλεσθε;’","st":"3.22"},{"sp":"N","t":"ταχύ γ᾽ ἂν ὁ τοιοῦτος ἐνεκάλεσεν τῷ θεῷ καταπεπομφότι αὐτὸν ὡς παρ᾽ ἀξίαν αὐτῷ χρωμένῳ, ὅς γε ἐνεκαλλωπίζετο ταῖς περιστάσεσι καὶ θέαμα εἶναι ἠξίου τῶν παριόντων. ἐπὶ τίνι γὰρ ἐγκαλέσει; ὅτι εὐσχημονεῖ; ὅτί κατηγορεῖ; ὅτι λαμπροτέραν ἐπιδείκνυται τὴν ἀρετὴν τὴν ἑαυτοῦ;","st":"3.22"},{"sp":"N","t":"ἄγε, περὶ πενίας δὲ τί λέγει, περὶ θανάτου, περὶ πόνου; πῶς συνέκρινεν τὴν εὐδαιμονίαν τὴν αὑτοῦ τῇ μεγάλου βασιλέως;","st":"3.22"},{"sp":"N","t":"μᾶλλον δ᾽ οὐδὲ συγκριτὸν ᾤετο εἶναι. ὅπου γὰρ ταραχαὶ καὶ λῦπαι καὶ φόβοι καὶ ὀρέξεις ἀτελεῖς καὶ ἐκκλίσεις περιπίπτουσαι καὶ φθόνοι καὶ ζηλοτυπίαι, ποῦ ἐκεῖ πάροδος εὐδαιμονίας; ὅπου δ᾽ ἂν ᾖ σαπρὰ δόγματα, ἐκεῖ πάντα ταῦτα εἶναι ἀνάγκη.","st":"3.22"},{"sp":"N","t":"πυθομένου δὲ τοῦ νεανίσκου, εἰ νοσήσας ἀξιοῦντος φίλου πρὸς αὐτὸν ἐλθεῖν ὥστε νοσοκομηθῆναι ὑπακούσει, Ποῦ δὲ φίλον μοι δώσεις Κυνικοῦ;","st":"3.22"},{"sp":"N","t":"ἔφη. δεῖ γὰρ αὐτὸν ἄλλον εἶναι τοιοῦτον, ἵν᾽ ἄξιος ᾖ φίλος αὐτοῦ ἀριθμεῖσθαι. κοινωνὸν αὐτὸν εἶναι δεῖ τοῦ σκήπτρου καὶ τῆς βασιλείας καὶ διάκονον ἄξιον, εἰ μέλλει φιλίας ἀξιωθήσεσθαι, ὡς Διογένης Ἀντισθένους ἐγένετο, ὡς Κράτης Διογένους.","st":"3.22"},{"sp":"N","t":"ἢ δοκεῖ σοι, ὅτι, ἂν χαίρειν αὐτῷ λέγῃ προσερχόμενος, φίλος ἐστὶν αὐτοῦ κἀκεῖνος αὐτὸν ἄξιον ἡγήσεται τοῦ πρὸς αὐτὸν εἰσελθεῖν;","st":"3.22"},{"sp":"N","t":"ὥστε ἄν σοι δοκῇ καὶ ἐνθυμηθῇς τι τοιοῦτον, κοπρίαν μᾶλλον περιβλέπου κομψήν, ἐν ᾗ πυρέξεις, ἀποσκέπουσαν τὸν βορέαν, ἵνα μὴ περιψυγῇς.","st":"3.22"},{"sp":"N","t":"σὺ δέ μοι δοκεῖς θέλειν εἰς οἶκόν τινος ἀπελθὼν διὰ χρόνου χορτασθῆναι. τί οὖν σοι καὶ ἐπιχειρεῖν πράγματι τηλικούτῳ;","st":"3.22"},{"sp":"N","t":"γάμος δ᾽, ἔφη, καὶ παῖδες προηγουμένως παραληφθήσονται ὑπὸ τοῦ Κυνικοῦ; — ἄν μοι σοφῶν, ἔφη, δῷς πόλιν, τάχα μὲν οὐδ᾽ ἥξει τις ῥᾳδίως ἐπὶ τὸ κυνίζειν. τίνων γὰρ ἕνεκα ἀναδέξηται ταύτην τὴν διεξαγωγήν; ὅμως δ᾽ ἂν ὑποθώμεθα,","st":"3.22"},{"sp":"N","t":"οὐδὲν κωλύσει καὶ γῆμαι αὐτὸν καὶ παιδοποιήσασθαι. καὶ γὰρ ἡ γυνὴ αὐτοῦ ἔσται ἄλλη τοιαύτη καὶ ὁ πενθερὸς ἄλλος τοιοῦτος καὶ τὰ παιδία οὕτως ἀνατραφήσεται.","st":"3.22"},{"sp":"N","t":"τοιαύτης δ᾽ οὔσης καταστάσεως, οἵα νῦν ἐστιν, ὡς ἐν παρατάξει, μή ποτ᾽ ἀπερίσπαστον εἶναι δεῖ τὸν Κυνικόν, ὅλον πρὸς τῇ διακονίᾳ τοῦ θεοῦ, ἐπιφοιτᾶν ἀνθρώποις δυνάμενον, οὐ προσδεδεμένον καθήκουσιν ἰδιωτικοῖς οὐδ᾽ ἐμπεπλεγμένον σχέσεσιν, ἃς παραβαίνων οὐκέτι σώσει τὸ τοῦ καλοῦ καὶ ἀγαθοῦ πρόσωπον, τηρῶν δ᾽ ἀπολεῖ τὸν ἄγγελον καὶ κατάσκοπον καὶ κήρυκα τῶν θεῶν;","st":"3.22"},{"sp":"N","t":"ὅρα γάρ, ὅτι αὐτὸν ἀποδεικνύναι δεῖ τινα τῷ πενθερῷ, ἀποδιδόναι τοῖς ἄλλοις συγγενέσι τῆς γυναικός, αὐτῇ τῇ γυναικί: εἰς νοσοκομίας λοιπὸν ἐκκλείεται, εἰς πορισμόν.","st":"3.22"},{"sp":"N","t":"ἵνα τἆλλα ἀφῶ, δεῖ αὐτὸν κουκκούμιον, ὅπου θερμὸν ποιήσει τῷ παιδίῳ, ἵν᾽ αὐτὸ λούσῃ εἰς σκάφην: ἐρίδια τεκούσῃ τῇ γυναικί, ἔλαιον, κραβάττιον, ποτήριον （ γίνεται ἤδη πλείω σκευάρια ）","st":"3.22"},{"sp":"N","t":": τὴν ἄλλην ἀσχολίαν, τὸν περισπασμόν. ποῦ μοι λοιπὸν ἐκεῖνος ὁ βασιλεὺς ὁ τοῖς κοινοῖς προσευκαιρῶν, ᾧ λαοί τ᾽ ἐπιτετράφαται καὶ τόσσα μέμηλεν: ὃν δεῖ τοὺς ἄλλους ἐπισκοπεῖν, τοὺς γεγαμηκότας, τοὺς πεπαιδοποιημένους, τίς καλῶς χρῆται τῇ αὑτοῦ γυναικί, τίς κακῶς, τίς διαφέρεται, ποία οἰκία εὐσταθεῖ, ποία οὔ, ὡς ἰατρὸν περιερχόμενον καὶ τῶν σφυγμῶν ἁπτόμενον;","st":"3.22"},{"sp":"N","t":"‘σὺ πυρέττεις, σὺ κεφαλαλγεῖς, σὺ ποδαγρᾷς: σὺ ἀνάτεινον, σὺ φάγε, σὺ ἀλούτησον: σὲ δεῖ τμηθῆναι, σὲ δεῖ καυθῆναι.’","st":"3.22"},{"sp":"N","t":"ποῦ σχολὴ τῷ εἰς τὰ ἰδιωτικὰ καθήκοντα ἐνδεδεμένῳ; οὐ δεῖ αὐτὸν πορίσαι ἱματίδια τοῖς παιδίοις; ἄγε, πρὸς γραμματιστὴν ἀποστεῖλαι πινακίδια ἔχοντα, γραφεῖα, τιτλάρια, καὶ τούτοις κραβάττιον ἑτοιμάσαι; οὐ γὰρ ἐκ τῆς κοιλίας ἐξελθόντα δύναται Κυνικὰ εἶναι: εἰ δὲ μή, κρεῖσσον ἦν αὐτὰ γενόμενα ῥῖψαι ἢ οὕτως ἀποκτεῖναι.","st":"3.22"},{"sp":"N","t":"σκόπει, ποῦ κατάγομεν τὸν Κυνικόν, πῶς αὐτοῦ τὴν βασιλείαν ἀφαιρούμεθα.","st":"3.22"},{"sp":"N","t":"— ναί: ἀλλὰ Κράτης ἔγημεν. — περίστασίν μοι λέγεις ἐξ ἔρωτος γενομένην καὶ γυναῖκα τιθεῖς ἄλλον Κράτητα. ἡμεῖς δὲ περὶ τῶν κοινῶν γάμων καὶ ἀπεριστάτων ζητοῦμεν καὶ οὕτως ζητοῦντες οὐχ εὑρίσκομεν ἐν ταύτῃ τῇ καταστάσει προηγούμενον τῷ Κυνικῷ τὸ πρᾶγμα. πῶς οὖν ἔτι, φησίν, διασώσει τὴν κοινωνίαν;","st":"3.22"},{"sp":"N","t":"— τὸν θεόν σοι: μείζονα δ᾽ εὐεργετοῦσιν ἀνθρώπους οἱ ἢ δύο ἢ τρία κακόρυγχα παιδία ἀνθ᾽ αὑτῶν εἰσάγοντες ἢ οἱ ἐπισκοποῦντες πάντας κατὰ δύναμιν ἀνθρώπους, τί ποιοῦσιν, πῶς διάγουσιν, τίνος ἐπιμελοῦνται, τίνος ἀμελοῦσι παρὰ τὸ προσῆκον;","st":"3.22"},{"sp":"N","t":"καὶ Θηβαίους μείζονα ὠφέλησαν ὅσοι τεκνία αὐτοῖς κατέλιπον Ἐπαμινώνδου τοῦ ἀτέκνου ἀποθανόντος; καὶ Ὁμήρου πλείονα τῇ κοινωνίᾳ συνεβάλετο Πρίαμος ὁ πεντήκοντα γεννήσας περικαθάρματα ἢ Δαναὸς ἢ Αἴολος;","st":"3.22"},{"sp":"N","t":"εἶτα στρατηγία μὲν ἢ σύνταγμά τινα ἀπείρξει γάμου ἢ παιδοποιίας καὶ οὐ δόξει οὗτος ἀντ᾽ οὐδενὸς ἠλλάχθαι τὴν ἀτεκνίαν, ἡ δὲ τοῦ Κυνικοῦ βασιλεία οὐκ ἔσται ἀνταξία;","st":"3.22"},{"sp":"N","t":"μήποτε οὐκ αἰσθανόμεθα τοῦ μεγέθους αὐτοῦ οὐδὲ φανταζόμεθα κατ᾽ ἀξίαν τὸν χαρακτῆρα τὸν Διογένους, ἀλλ᾽ εἰς τοὺς νῦν ἀποβλέπομεν, τοὺς τραπεζῆας πυλαωρούς, οἳ οὐδὲν μιμοῦνται ἐκείνους ἢ εἴ ὅτι ἄρα πόρδωνες γίνονται, ἄλλο δ᾽ οὐδέν;","st":"3.22"},{"sp":"N","t":"ἐπεὶ οὐκ ἂν ἡμᾶς ἐκίνει ταῦτα οὐδ᾽ ἂν ἐπεθαυμάζομεν, εἰ μὴ γαμήσει ἢ παιδοποιήσεται. ἄνθρωπε, πάντας ἀνθρώπους πεπαιδοποίηται, τοὺς ἄνδρας υἱοὺς ἔχει, τὰς γυναῖκας θυγατέρας: πᾶσιν οὕτως προσέρχεται, οὕτως πάντων κήδεται.","st":"3.22"},{"sp":"N","t":"ἢ σὺ δοκεῖς ὑπὸ περιεργίας λοιδορεῖσθαι τοῖς ἀπαντῶσιν; ὡς πατὴρ αὐτὸ ποιεῖ, ὡς ἀδελφὸς καὶ τοῦ κοινοῦ πατρὸς ὑπηρέτης τοῦ Διός.","st":"3.22"},{"sp":"N","t":"ἄν σοι δόξῃ, πυθοῦ μου καὶ εἰ πολιτεύσεται. σαννίων, μείζονα πολιτείαν ζητεῖς, ἧς πολιτεύσεται;","st":"3.22"},{"sp":"N","t":"ἢ ἐν Ἀθηναίοις παρελθὼν ἐρεῖ τις περὶ προσόδων ἢ πόρων, ὃν δεῖ πᾶσιν ἀνθρώποις διαλέγεσθαι, ἐπίσης μὲν Ἀθηναίοις, ἐπίσης δὲ Κορινθίοις, ἐπίσης δὲ Ῥωμαίοις οὐ περὶ πόρων οὐδὲ περὶ προσόδων οὐδὲ περὶ εἰρήνης ἢ πολέμου, ἀλλὰ περὶ εὐδαιμονίας ἢ καὶ κακοδαιμονίας, περὶ εὐτυχίας καὶ δυστυχίας, περὶ δουλείας καὶ ἐλευθερίας;","st":"3.22"},{"sp":"N","t":"τηλικαύτην πολιτείαν πολιτευομένου ἀνθρώπου σύ μου πυνθάνῃ εἰ πολιτεύσεται; πυθοῦ μου καί, εἰ ἄρξει: πάλιν ἐρῶ σοι: μωρέ, ποίαν ἀρχὴν μείζονα, ἧς ἄρχει;","st":"3.22"},{"sp":"N","t":"χρεία μέντοι καὶ σώματος ποιοῦ τῷ τοιούτῳ. ἐπεί τοι ἂν φθισικὸς προέρχηται, λεπτὸς καὶ ὠχρός, οὐκέτι ὁμοίαν ἔμφασιν ἡ μαρτυρία αὐτοῦ ἔχει.","st":"3.22"},{"sp":"N","t":"δεῖ γὰρ αὐτὸν οὐ μόνον τὰ τῆς ψυχῆς ἐπιδεικνύοντα παριστάνειν τοῖς ἰδιώταις ὅτι ἐνδέχεται δίχα τῶν θαυμαζομένων εἶναι ὑπ᾽ αὐτῶν καλὸν καὶ ἀγαθόν, ἀλλὰ καὶ διὰ τοῦ σώματος ἐνδείκνυσθαι, ὅτι ἡ ἀφελὴς καὶ λιτὴ καὶ ὕπαιθρος δίαιτα οὐδὲ τὸ σῶμα λυμαίνεται:","st":"3.22"},{"sp":"N","t":"‘ἰδοὺ καὶ τούτου μάρτυς εἰμὶ ἐγὼ καὶ τὸ σῶμα τὸ ἐμόν.’ ὡς Διογένης ἐποίει: στίλβων γὰρ περιήρχετο καὶ κατ᾽ αὐτὸ τὸ σῶμα ἐπέστρεφε τοὺς πολλούς.","st":"3.22"},{"sp":"N","t":"ἐλεούμενος δὲ Κυνικὸς ἐπαίτης δοκεῖ: πάντες ἀποστρέφονται, πάντες προσκόπτουσιν. οὐδὲ γὰρ ῥυπαρὸν αὐτὸν δεῖ φαίνεσθαι, ὡς μηδὲ κατὰ τοῦτο τοὺς ἀνθρώπους ἀποσοβεῖν, ἀλλ᾽ αὐτὸν τὸν αὐχμὸν αὐτοῦ δεῖ καθαρὸν εἶναι καὶ ἀγωγόν.","st":"3.22"},{"sp":"N","t":"δεῖ δὲ καὶ χάριν πολλὴν προσεῖναι φυσικὴν τῷ Κυνικῷ καὶ ὀξύτητα （ εἰ δὲ μή, μύξα γίνεται, ἄλλο δ᾽ οὐδέν ） , ἵνα ἑτοίμως δύνηται καὶ παρακειμένως πρὸς τὰ ἐμπίπτοντα ἀπαντᾶν.","st":"3.22"},{"sp":"N","t":"ὡς Διογένης πρὸς τὸν εἰπόντα ‘σὺ εἶ ὁ Διογένης ὁ μὴ οἰόμενος εἶναι θεούς;’ ‘καὶ πῶς,’ ἔφη, ‘σὲ θεοῖς ἐχθρὸν νομίζων;’","st":"3.22"},{"sp":"N","t":"πάλιν Ἀλεξάνδρῳ ἐπιστάντι αὐτῷ κοιμωμένῳ καὶ εἰπόντι οὐ χρὴ παννύχιον εὕδειν βουληφόρον ἄνδρα ἔνυπνος ἔτι ὢν ἀπήντησεν ᾧ λαοί τ᾽ ἐπιτετράφαται καὶ τόσσα μέμηλεν.","st":"3.22"},{"sp":"N","t":"πρὸ πάντων δὲ τὸ ἡγεμονικὸν αὐτοῦ δεῖ καθαρώτερον εἶναι τοῦ ἡλίου: εἰ δὲ μή, κυβευτὴν ἀνάγκη καὶ ῥᾳδιουργόν, ὅστις ἐνεχόμενός τινι αὐτὸς κακῷ ἐπιτιμήσει τοῖς ἄλλοις.","st":"3.22"},{"sp":"N","t":"ὅρα γάρ, οἷόν ἐστιν. τοῖς βασιλεῦσι τούτοις καὶ τυράννοις οἱ δορυφόροι καὶ τὰ ὅπλα παρεῖχε τὸ ἐπιτιμᾶν τισιν καὶ δύνασθαι καὶ κολάζειν τοὺς ἁμαρτάνοντας καὶ αὐτοῖς οὖσι κακοῖς, τῷ Κυνικῷ ἀντὶ τῶν ὅπλων καὶ τῶν δορυφόρων τὸ συνειδὸς τὴν ἐξουσίαν ταύτην παραδίδωσιν.","st":"3.22"},{"sp":"N","t":"ὅταν ἴδῃς, ὅτι ὑπερηγρύπνηκεν ὑπὲρ ἀνθρώπων καὶ πεπόνηκεν καὶ καθαρὸς μὲν κεκοίμηται, καθαρώτερον δ᾽ αὐτὸν ἔτι ὁ ὕπνος ἀφῆκεν, ἐντεθύμηται δ᾽, ὅσα ἐντεθύμηται ὡς φίλος τοῖς θεοῖς, ὡς ὑπηρέτης, ὡς μετέχων τῆς ἀρχῆς τοῦ Διός, πανταχοῦ δ᾽ αὐτῷ πρόχειρον τὸ ἄγου δέ μ᾽ ὦ Ζεῦ καὶ σύ γ᾽ ἡ Πεπρωμένη, καὶ ὅτι εἰ ταύτῃ τοῖς θεοῖς φίλον, ταύτῃ γινέσθω:","st":"3.22"},{"sp":"N","t":"διὰ τί μὴ θαρρήσῃ παρρησιάζεσθαι πρὸς τοὺς ἀδελφοὺς τοὺς ἑαυτοῦ, πρὸς τὰ τέκνα, ἁπλῶς πρὸς τοὺς συγγενεῖς;","st":"3.22"},{"sp":"N","t":"διὰ τοῦτο οὔτε περίεργος οὔτε πολυπράγμων ἐστὶν ὁ οὕτω διακείμενος: οὐ γὰρ τὰ ἀλλότρια πολυπραγμονεῖ, ὅταν τὰ ἀνθρώπινα ἐπισκοπῇ, ἀλλὰ τὰ ἴδια. εἰ δὲ μή, λέγε καὶ τὸν στρατηγὸν πολυπράγμονα, ὅταν τοὺς στρατιώτας ἐπισκοπῇ καὶ ἐξετάζῃ καὶ παραφυλάσσῃ καὶ τοὺς ἀκοσμοῦντας κολάζῃ.","st":"3.22"},{"sp":"N","t":"ἐὰν δ᾽ ὑπὸ μάλης ἔχων πλακουντάριον ἐπιτιμᾷς ἄλλοις, ἐρῶ σοι: οὐ θέλεις μᾶλλον ἀπελθὼν εἰς γωνίαν καταφαγεῖν ἐκεῖνο ὃ κέκλοφας; τί δὲ σοὶ καὶ τοῖς ἀλλοτρίοις;","st":"3.22"},{"sp":"N","t":"τίς γὰρ εἶ; ὁ ταῦρος εἶ ἢ ἡ βασίλισσα τῶν μελισσῶν; δεῖξόν μοι τὰ σύμβολα τῆς ἡγεμονίας, οἷα ἐκείνη ἐκ φύσεως ἔχει. εἰ δὲ κηφὴν εἶ ἐπιδικαζόμενος τῆς βασιλείας τῶν μελισσῶν, οὐ δοκεῖς ὅτι καὶ σὲ καταβαλλοῦσιν οἱ συμπολιτευόμενοι, ὡς αἱ μέλισσαι τοὺς κηφῆνας;","st":"3.22"},{"sp":"N","t":"τὸ μὲν γὰρ ἀνεκτικὸν τοσοῦτον ἔχειν δεῖ τὸν Κυνικόν, ὥστ᾽ αὐτὸν ἀναίσθητον δοκεῖν τοῖς πολλοῖς καὶ λίθον: οὐδεὶς αὐτὸν λοιδορεῖ, οὐδεὶς τύπτει, οὐδεὶς ὑβρίζει: τὸ σωμάτιον δ᾽ αὐτοῦ δέδωκεν αὐτὸς χρῆσθαι τῷ θέλοντι ὡς βούλεται.","st":"3.22"},{"sp":"N","t":"μέμνηται γάρ, ὅτι τὸ χεῖρον ἀνάγκη νικᾶσθαι ὑπὸ τοῦ κρείττονος, ὅπου χεῖρόν ἐστιν, τὸ δὲ σωμάτιον τῶν πολλῶν χεῖρον, τὸ ἀσθενέστερον τῶν ἰσχυροτέρων.","st":"3.22"},{"sp":"N","t":"οὐδέποτ᾽ οὖν εἰς τοῦτον καταβαίνει τὸν ἀγῶνα, ὅπου δύναται νικηθῆναι, ἀλλὰ τῶν ἀλλοτρίων εὐθὺς ἐξίσταται, τῶν δούλων οὐκ ἀντιποιεῖται. ὅπου δὲ προαίρεσις καὶ χρῆσις τῶν φαντασιῶν,","st":"3.22"},{"sp":"N","t":"ἐκεῖ ὄψει, ὅσα ὄμματα ἔχει, ἵν᾽ εἴπῃς, ὅτι Ἄργος τυφλὸς ἦν πρὸς αὐτόν.","st":"3.22"},{"sp":"N","t":"μή που συγκατάθεσις προπετής, μή που ὁρμὴ εἰκαία, μή που ὄρεξις ἀποτευκτική, μή που ἔκκλισις περιπτωτική, μή που ἐπιβολὴ ἀτελής, μή που μέμψις, μή που ταπείνωσις ἢ φθόνος;","st":"3.22"},{"sp":"N","t":"ὧδε ἡ πολλὴ προσοχὴ καὶ σύντασις, τῶν δ᾽ ἄλλων ἕνεκα ὕπτιος ῥέγκει: εἰρήνη πᾶσα. λῃστὴς προαιρέσεως οὐ γίνεται, τύραννος οὐ γίνεται.","st":"3.22"},{"sp":"N","t":"σωματίου δέ; ναί. καὶ κτησειδίου; ναί: καὶ ἀρχῶν καὶ τιμῶν. τί οὖν αὐτῷ τούτων μέλει; ὅταν οὖν τις διὰ τούτων αὐτὸν ἐκφοβῇ, λέγει αὐτῷ ‘ὕπαγε, ζήτει τὰ παιδία: ἐκείνοις τὰ προσωπεῖα φοβερά ἐστιν, ἐγὼ δ᾽ οἶδα, ὅτι ὀστράκινά ἐστιν, ἔσωθεν δὲ οὐδὲν ἔχει.’","st":"3.22"},{"sp":"N","t":"περὶ τοιούτου πράγματος βουλεύῃ. ὥστε ἐάν σοι δόξῃ, τὸν θεόν σοι, ὑπέρθου καὶ ἰδού σοι πρῶτον τὴν παρασκευήν.","st":"3.22"},{"sp":"N","t":"ἰδοὺ γάρ, τί καὶ ὁ Ἕκτωρ λέγει τῇ Ἀνδρομάχῃ: ‘ὕπαγε,’ φησίν, ‘μᾶλλον εἰς οἶκον καὶ ὕφαινε: πόλεμος δ᾽ ἄνδρεσσι μελήσει πᾶσι, μάλιστα δ᾽ ἐμοί. ‘","st":"3.22"},{"sp":"N","t":"οὕτως καὶ τῆς ἰδίας παρασκευῆς συνῄσθετο καὶ τῆς ἐκείνης ἀδυναμίας. πρὸς τοὺς ἀναγιγνώσκοντας καὶ διαλεγομένους ἐπιδεικτικῶς. τίς εἶναι θέλεις, σαυτῷ πρῶτον εἰπέ: εἶθ᾽ οὕτως ποίει ἃ ποιεῖς. καὶ γὰρ ἐπὶ τῶν ἄλλων σχεδὸν ἁπάντων οὕτως ὁρῶμεν γινόμενα.","st":"3.22"},{"sp":"N","t":"οἱ ἀθλοῦντες πρῶτον κρίνουσιν, τίνες εἶναι θέλουσιν, εἶθ᾽ οὕτως τὰ ἑξῆς ποιοῦσιν. εἰ δολιχοδρόμος, τοιαύτη τροφή, τοιοῦτος περίπατος, τοιαύτη τρῖψις, τοιαύτη γυμνασία: εἰ σταδιοδρόμος, πάντα ταῦτα ἀλλοῖα: εἰ πένταθλος, ἔτι ἀλλοιότερα. οὕτως εὑρήσεις καὶ ἐπὶ τῶν τεχνῶν.","st":"3.23"},{"sp":"N","t":"εἰ τέκτων, τοιαῦτα ἕξεις: εἰ χαλκεύς, τοιαῦτα. ἕκαστον γὰρ τῶν γινομένων ὑφ᾽ ἡμῶν ἂν μὲν ἐπὶ μηδὲν ἀναφέρωμεν, εἰκῇ ποιήσομεν: ἐὰν δ᾽ ἐφ᾽ ὃ μὴ δεῖ, διεσφαλμένως.","st":"3.23"},{"sp":"N","t":"λοιπὸν ἡ μέν τίς ἐστι κοινὴ ἀναφορά, ἡ δ᾽ ἰδία. πρῶτον ἵν᾽ ὡς ἄνθρωπος. ἐν τούτῳ τί περιέχεται; μὴ ὡς πρόβατον, † εἰ βλαπτικῶς † καὶ ἐπιεικῶς, ὡς θηρίον.","st":"3.23"},{"sp":"N","t":"ἡ δ᾽ ἰδία πρὸς τὸ ἐπιτήδευμα ἑκάστου καὶ τὴν προαίρεσιν. ὁ κιθαρῳδὸς ὡς κιθαρῳδός, ὁ τέκτων ὡς τέκτων, ὁ φιλόσοφος ὡς φιλόσοφος, ὁ ῥήτωρ ὡς ῥήτωρ.","st":"3.23"},{"sp":"N","t":"ὅταν οὖν λέγῃς ‘δεῦτε καὶ ἀκούσατέ μου ἀναγιγνώσκοντος ὑμῖν,’ σκέψαι πρῶτον μὴ εἰκῇ αὐτὸ ποιεῖν. εἶτ᾽ ἂν εὕρῃς, ὅτι ἀναφέρεις, σκέψαι, εἰ ἐφ᾽ ὃ δεῖ. ὠφελῆσαι θέλεις ἢ ἐπαινεθῆναι;","st":"3.23"},{"sp":"N","t":"εὐθὺς ἀκούεις λέγοντος ‘ἐμοὶ δὲ τοῦ παρὰ τῶν πολλῶν ἐπαίνου τίς λόγος;’ καὶ καλῶς λέγει. οὐδὲν γὰρ τῷ μουσικῷ, καθὸ μουσικός ἐστιν, οὐδὲ τῷ γεωμετρικῷ.","st":"3.23"},{"sp":"N","t":"οὐκοῦν ὠφελῆσαι θέλεις; πρὸς τί; εἰπὲ καὶ ἡμῖν, ἵνα καὶ αὐτοὶ τρέχωμεν εἰς τὸ ἀκροατήριόν σου. νῦν δύναταί τις ὠφελῆσαι ἄλλους μὴ αὐτὸς ὠφελημένος; οὔ. οὐδὲ γὰρ εἰς τεκτονικὴν ὁ μὴ τέκτων οὐδ᾽ εἰς σκυτικὴν ὁ μὴ σκυτεύς.","st":"3.23"},{"sp":"N","t":"θέλεις οὖν γνῶναι, εἰ ὠφέλησαι; φέρε σου τὰ δόγματα, φιλόσοφε. τίς ἐπαγγελία ὀρέξεως; μὴ ἀποτυγχάνειν. τίς ἐκκλίσεως;","st":"3.23"},{"sp":"N","t":"μὴ περιπίπτειν. ἄγε, πληροῦμεν αὐτῶν τὴν ἐπαγγελίαν; εἰπέ μοι τἀληθῆ: ἂν δὲ ψεύσῃ, ἐρῶ σοι: πρῴην ψυχρότερόν σου τῶν ἀκροατῶν συνελθόντων καὶ μὴ ἐπιβοησάντων σοι τεταπεινωμένος ἐξῆλθες:","st":"3.23"},{"sp":"N","t":"πρῴην ἐπαινεθεὶς περιήρχου καὶ πᾶσιν ἔλεγες ‘τί σοι ἔδοξα;’ ‘θαυμαστῶς, κύριε, τὴν ἐμήν σοι σωτηρίαν.’ ‘πῶς δ᾽ εἶπον ἐκεῖνο;’ ‘τὸ ποῖον;’ ‘ὅπου διέγραψα τὸν Πᾶνα καὶ τὰς Νύμφας.’","st":"3.23"},{"sp":"N","t":"‘ὑπερφυῶς.’ εἶτά μοι λέγεις, ἐν ὀρέξει καὶ ἐκκλίσει κατὰ φύσιν ἀναστρέφῃ; ὕπαγε, ἄλλον πεῖθε.","st":"3.23"},{"sp":"N","t":"τὸν δεῖνα δὲ πρῴην οὐκ ἐπῄνεις παρὰ τὸ σοὶ φαινόμενον; τὸν δεῖνα δ᾽ οὐκ ἐκολάκευες τὸν συγκλητικόν; ἤθελές σου τὰ παιδία εἶναι τοιαῦτα; — μὴ γένοιτο.","st":"3.23"},{"sp":"N","t":"— τίνος οὖν ἕνεκα ἐπῄνεις καὶ περιεῖπες αὐτόν; — εὐφυὴς νεανίσκος καὶ λόγων ἀκουστικός. — πόθεν τοῦτο; — ἐμὲ θαυμάζει. — εἴρηκας τὴν ἀπόδειξιν. εἶτα τί δοκεῖ σοι; αὐτοί σου οὗτοι οὐ καταφρονοῦσιν λεληθότως;","st":"3.23"},{"sp":"N","t":"ὅταν οὖν ἄνθρωπος συνειδὼς ἑαυτῷ μηθὲν ἀγαθὸν μήτε πεποιηκότι μήτ᾽ ἐνθυμουμένῳ εὕρῃ φιλόσοφον τὸν λέγοντα ‘μεγαλοφυὴς καὶ ἁπλοῦς καὶ ἀκέραιος,’ τί δοκεῖς ἄλλο αὐτὸν λέγειν ἢ ‘οὗτός τινά ποτέ μου χρείαν ἔχει;’","st":"3.23"},{"sp":"N","t":"ἢ εἰπέ μοι, τί μεγαλοφυοῦς ἔργον ἐπιδέδεικται; ἰδοὺ σύνεστί σοι τοσούτῳ χρόνῳ, διαλεγομένου σου ἀκήκοεν, ἀναγιγνώσκοντος ἀκήκοεν. κατέσταλται, ἐπέστραπται ἐφ᾽ αὑτόν; ᾔσθηται, ἐν οἵοις κακοῖς ἐστιν; ἀποβέβληκεν οἴησιν; ζητεῖ τὸν διδάξοντα;","st":"3.23"},{"sp":"N","t":"— ζητεῖ, φησί. — τὸν διδάξοντα, πῶς δεῖ βιοῦν; οὔ, μωρέ: ἀλλὰ πῶς δεῖ φράζειν: τούτου γὰρ ἕνεκα καὶ σὲ θαυμάζει. ἄκουσον αὐτοῦ, τίνα λέγει. ‘οὗτος ὁ ἄνθρωπος πάνυ τεχνικώτατα γράφει, Δίωνος πολὺ κάλλιον.’ ὅλον ἄλλο ἐστίν.","st":"3.23"},{"sp":"N","t":"μή τι λέγει ‘ὁ ἄνθρωπος αἰδήμων ἐστίν, οὗτος πιστός ἐστιν, οὗτος ἀτάραχός ἐστιν;’ εἰ δὲ καὶ ἔλεγεν, εἶπον ἂν αὐτῷ ‘ἐπειδὴ οὗτος πιστός ἐστιν, οὗτος ὁ πιστὸς τί ἐστιν;’ καὶ εἰ μὴ εἶχεν εἰπεῖν, προσέθηκα ἂν ὅτι ‘πρῶτον μάθε, τί λέγεις, εἶθ᾽ οὕτως λέγε.’","st":"3.23"},{"sp":"N","t":"οὕτως οὖν κακῶς διακείμενος καὶ χάσκων περὶ τοὺς ἐπαινέσοντας καὶ ἀριθμῶν τοὺς ἀκούοντάς σου θέλεις ἄλλους ὠφελεῖν; ‘σήμερόν μου πολλῷ πλείονες ἤκουσαν.’ ‘ναί, πολλοί.’ ‘δοκοῦμεν ὅτι πεντακόσιοι.’ ‘οὐδὲν λέγεις: θὲς αὐτοὺς χιλίους.’ ‘Δίωνος οὐδέποτ᾽ ἤκουσαν τοσοῦτοι.’ ‘πόθεν αὐτῷ;’ ‘καὶ κομψῶς αἰσθάνονται λόγων.’","st":"3.23"},{"sp":"N","t":"‘τὸ καλόν, κύριε, καὶ λίθον κινῆσαι δύναται.’ ἰδοὺ φωναὶ φιλοσόφου, ἰδοὺ διάθεσις ὠφελήσοντος ἀνθρώπους: ἰδοὺ ἀκηκοὼς ἄνθρωπος λόγου, ἀνεγνωκὼς τὰ Σωκρατικὰ ὡς Σωκρατικά, οὐχὶ δ᾽ ὡς Λυσίου καὶ Ἰσοκράτους. ‘πολλάκις ἐθαύμασα, τίσιν ποτὲ λόγοις. οὔ: ἀλλὰ τίνι ποτὲ λόγῳ: τοῦτ᾽ ἐκείνου λειότερον.’","st":"3.23"},{"sp":"N","t":"μὴ γὰρ ἄλλως αὐτὰ ἀνεγνώκατε ἢ ὡς ᾠδάρια; ὡς εἴ γε ἀνεγιγνώσκετε ὡς δεῖ, οὐκ ἂν πρὸς τούτοις ἐγίνεσθε, ἀλλ᾽ ἐκεῖνο μᾶλλον ἐβλέπετε ‘ἐμὲ δ᾽ Ἄνυτος καὶ Μέλητος ἀποκτεῖναι μὲν δύνανται, βλάψαι δ᾽ οὔ’ καὶ ὅτι ‘ὡς ἐγὼ ἀιεὶ τοιοῦτος οἷος μηδενὶ προσέχειν τῶν ἐμῶν ἢ τῷ λόγῳ, ὃς ἄν μοι σκοπουμένῳ βέλτιστος φαίνηται.’","st":"3.23"},{"sp":"N","t":"διὰ τοῦτο τίς ἤκουσέ ποτε Σωκράτους λέγοντος ὅτι ‘οἶδά τι καὶ διδάσκω;’ ἀλλὰ ἄλλον ἀλλαχοῦ ἔπεμπεν. τοιγαροῦν ἤρχοντο πρὸς αὐτὸν ἀξιοῦντες φιλοσόφοις ὑπ᾽ αὐτοῦ συσταθῆναι κἀκεῖνος ἀπῆγεν καὶ συνίστανεν.","st":"3.23"},{"sp":"N","t":"οὔ: ἀλλὰ προσπέμπων ἔλεγεν ‘ἄκουσόν μου σήμερον διαλεγομένου ἐν τῇ οἰκίᾳ τῇ Κοδράτου.’ τί σου ἀκούσω; ἐπιδεῖξαί μοι θέλεις, ὅτι κομψῶς συντιθεῖς τὰ ὀνόματα; συντιθεῖς, ἄνθρωπε: καὶ τί σοι ἀγαθόν ἐστιν;","st":"3.23"},{"sp":"N","t":"‘ἀλλ᾽ ἐπαίνεσόν με.’ τί λέγεις τὸ ἐπαίνεσον; ‘εἰπέ μοι ‘οὐᾶ’ καὶ ‘θαυμαστῶς’.’ ἰδοὺ λέγω. εἰ δ᾽ ἐστὶν ἔπαινος ἐκεῖνο, ὅ τι ποτὲ λέγουσιν οἱ φιλόσοφοι τῶν ἐν τῇ τοῦ ἀγαθοῦ κατηγορίᾳ, τί σε ἔχω ἐπαινέσαι; εἰ ἀγαθόν ἐστι τὸ φράζειν ὀρθῶς, δίδαξόν με καὶ ἐπαινέσω.","st":"3.23"},{"sp":"N","t":"τί οὖν; ἀηδῶς δεῖ τῶν τοιούτων ἀκούειν; μὴ γένοιτο. ἐγὼ μὲν οὐδὲ κιθαρῳδοῦ ἀηδῶς ἀκούω: μή τι οὖν τούτου ἕνεκα κιθαρῳδεῖν με δεῖ στάντα; ἄκουσον, τί λέγει Σωκράτης: ‘οὐδὲ γὰρ ἂν πρέποι, ὦ ἄνδρες, τῇδε τῇ ἡλικίᾳ ὥσπερ μειρακίῳ πλάττοντι λόγους εἰς ὑμᾶς εἰσιέναι.’ ‘ὥσπερ μειρακίῳ’ φησίν.","st":"3.23"},{"sp":"N","t":"ἔστι γὰρ τῷ ὄντι κομψὸν τὸ τεχνίον ἐκλέξαι ὀνομάτια καὶ ταῦτα συνθεῖναι καὶ παρελθόντα εὐφυῶς ἀναγνῶναι ἢ εἰπεῖν καὶ μεταξὺ ἀναγιγνώσκοντα ἐπιφθέγξασθαι ὅτι ‘τούτοις οὐ πολλοὶ δύνανται παρακολουθεῖν, μὰ τὴν ὑμετέραν σωτηρίαν.’ φιλόσοφος δ᾽ ἐπ᾽ ἀκρόασιν παρακαλεῖ;","st":"3.23"},{"sp":"N","t":"— οὐχὶ δ᾽ ὡς ὁ ἥλιος ἄγει αὐτὸς ἐφ᾽ ἑαυτὸν τὴν τροφήν, οὕτως δὲ καὶ οὗτος ἄγει τοὺς ὠφεληθησομένους; ποῖος ἰατρὸς παρακαλεῖ, ἵνα τις ὑπ᾽ αὐτοῦ θεραπευθῇ; καίτοι νῦν ἀκούω ὅτι καὶ οἱ ἰατροὶ παρακαλοῦσιν ἐν Ῥώμῃ: πλὴν ἐπ᾽ ἐμοῦ παρεκαλοῦντο.","st":"3.23"},{"sp":"N","t":"‘παρακαλῶ σε ἐλθόντα ἀκοῦσαι, ὅτι σοι κακῶς ἐστι καὶ πάντων μᾶλλον ἐπιμελῇ ἢ οὗ δεῖ σε ἐπιμελεῖσθαι καὶ ὅτι ἀγνοεῖς τὰ ἀγαθὰ καὶ τὰ κακὰ καὶ κακοδαίμων εἶ καὶ δυστυχής.’ κομψὴ παράκλησις. καὶ μὴν ἂν μὴ ταῦτα ἐμποιῇ ὁ τοῦ φιλοσόφου λόγος, νεκρός ἐστι καὶ αὐτὸς καὶ ὁ λέγων.","st":"3.23"},{"sp":"N","t":"εἴωθε λέγειν ὁ Ῥοῦφος ‘εἰ εὐσχολεῖτε ἐπαινέσαι με, ἐγὼ δ᾽ οὐδὲν λέγω.’ τοιγαροῦν οὕτως ἔλεγεν, ὥσθ᾽ ἕκαστον ἡμῶν καθήμενον οἴεσθαι, ὅτι τίς ποτε αὐτὸν διαβέβληκεν: οὕτως ἥπτετο τῶν γιγνομένων, οὕτως πρὸ ὀφθαλμῶν ἐτίθει τὰ ἑκάστου κακά.","st":"3.23"},{"sp":"N","t":"ἰατρεῖόν ἐστιν, ἄνδρες, τὸ τοῦ φιλοσόφου σχολεῖον: οὐ δεῖ ἡσθέντας ἐξελθεῖν, ἀλλ᾽ ἀλγήσαντας. ἔρχεσθε γὰρ οὐχ ὑγιεῖς, ἀλλ᾽ ὁ μὲν ὦμον ἐκβεβληκώς, ὁ δ᾽ ἀπόστημα ἔχων, ὁ δὲ σύριγγα, ὁ δὲ κεφαλαλγῶν.","st":"3.23"},{"sp":"N","t":"εἶτ᾽ ἐγὼ καθίσας ὑμῖν λέγω νοημάτια καὶ ἐπιφωνημάτια, ἵν᾽ ὑμεῖς ἐπαινέσαντές με ἐξέλθητε, ὁ μὲν τὸν ὦμον ἐκφέρων οἷον εἰσήνεγκεν, ὁ δὲ τὴν κεφαλὴν ὡσαύτως ἔχουσαν, ὁ δὲ τὴν σύριγγα, ὁ δὲ τὸ ἀπόστημα;","st":"3.23"},{"sp":"N","t":"εἶτα τούτου ἕνεκα ἀποδημήσωσιν ἄνθρωποι νεώτεροι καὶ τοὺς γονεῖς τοὺς αὑτῶν ἀπολίπωσιν καὶ τοὺς φίλους καὶ τοὺς συγγενεῖς καὶ τὸ κτησίδιον, ἵνα σοι ‘οὐᾶ’ φῶσιν ἐπιφωνημάτια λέγοντι; τοῦτο Σωκράτης ἐποίει, τοῦτο Ζήνων, τοῦτο Κλεάνθης;","st":"3.23"},{"sp":"N","t":"τί οὖν; οὐκ ἔστιν ὁ προτρεπτικὸς χαρακτήρ; — τίς γὰρ οὐ λέγει; ὡς ὁ ἐλεγκτικός, ὡς ὁ διδασκαλικός. τίς οὖν πώποτε τέταρτον εἶπεν μετὰ τούτων τὸν ἐπιδεικτικόν;","st":"3.23"},{"sp":"N","t":"τίς γάρ ἐστιν ὁ προτρεπτικός; δύνασθαι καὶ ἑνὶ καὶ πολλοῖς δεῖξαι τὴν μάχην ἐν ᾗ κυλίονται: καὶ ὅτι μᾶλλον πάντων φροντίζουσιν ἢ ὧν θέλουσιν. θέλουσι μὲν γὰρ τὰ πρὸς εὐδαιμονίαν φέροντα, ἀλλαχοῦ δ᾽ αὐτὰ ζητοῦσι.","st":"3.23"},{"sp":"N","t":"τοῦτο ἵνα γένηται, δεῖ τεθῆναι χίλια βάθρα καὶ παρακληθῆναι τοὺς ἀκουσομένους καὶ σὲ ἐν κομψῷ στολίῳ ἢ τριβωναρίῳ ἀναβάντα ἐπὶ πούλβινον διαγράφειν, πῶς Ἀχιλλεὺς ἀπέθανεν; παύσασθε, τοὺς θεοὺς ὑμῖν, καλὰ ὀνόματα καὶ πράγματα καταισχύνοντες, ὅσον ἐφ᾽ ἑαυτοῖς.","st":"3.23"},{"sp":"N","t":"οὐδὲν προτρεπτικώτερον ἢ ὅταν ὁ λέγων ἐμφαίνῃ τοῖς ἀκούουσιν ὅτι χρείαν αὐτῶν ἔχει.","st":"3.23"},{"sp":"N","t":"ἢ εἰπέ μοι, τίς ἀκούων ἀναγιγνώσκοντός σου ἢ διαλεγομένου περὶ αὑτοῦ ἠγωνίασεν ἢ ἐπεστράφη: εἰς αὑτὸν ἢ ἐξελθὼν εἶπεν ὅτι ‘καλῶς μου ἥψατο ὁ φιλόσοφος: οὐκέτι δεῖ ταῦτα ποιεῖν;’","st":"3.23"},{"sp":"N","t":"οὐχὶ δ᾽, ἂν λίαν εὐδοκιμῇς, λέγει πρός τινα ‘κομψῶς ἔφρασεν τὰ περὶ τὸν Ξέρξην,’ ἄλλος ‘οὔ: ἀλλὰ τὴν ἐπὶ Πύλαις μάχην;’ τοῦτό ἐστιν ἀκρόασις φιλοσόφου; περὶ τοῦ μὴ δεῖν προσπάσχειν τοῖς οὐκ ἐφ᾽ ἡμῖν. τὸ ἄλλου παρὰ φύσιν σοὶ κακὸν μὴ γινέσθω: οὐ γὰρ συνταπεινοῦσθαι πέφυκας οὐδὲ συνατυχεῖν, ἀλλὰ συνευτυχεῖν.","st":"3.23"},{"sp":"N","t":"ἂν δέ τις ἀτυχῇ, μέμνησο, ὅτι παρ᾽ αὑτὸν ἀτυχεῖ. ὁ γὰρ θεὸς πάντας ἀνθρώπους ἐπὶ τὸ εὐδαιμονεῖν, ἐπὶ τὸ εὐσταθεῖν ἐποίησεν.","st":"3.24"},{"sp":"N","t":"πρὸς τοῦτο ἀφορμὰς ἔδωκεν, τὰ μὲν ἴδια δοὺς ἑκάστῳ, τὰ δ᾽ ἀλλότρια: τὰ μὲν κωλυτὰ καὶ ἀφαιρετὰ καὶ ἀναγκαστὰ οὐκ ἴδια, τὰ δ᾽ ἀκώλυτα ἴδια: τὴν δ᾽ οὐσίαν τοῦ ἀγαθοῦ καὶ τοῦ κακοῦ, ὥσπερ ἦν ἄξιον τὸν κηδόμενον ἡμῶν καὶ πατρικῶς προιστάμενον, ἐν τοῖς ἰδίοις.","st":"3.24"},{"sp":"N","t":"‘ἀλλ᾽ ἀποκεχώρηκα τοῦ δεῖνος καὶ ὀδυνᾶται.’ διὰ τί γὰρ τὰ ἀλλότρια ἴδια ἡγήσατο; διὰ τί, ὅτε σε βλέπων ἔχαιρεν, οὐκ ἐπελογίζετο, ὅτι θνητὸς εἶ, ἀποδημητικὸς εἶ; τοιγαροῦν τίνει δίκας τῆς αὑτοῦ μωρίας.","st":"3.24"},{"sp":"N","t":"σὺ δ᾽ ἀντὶ τίνος; ἐπὶ τί κλάεις σεαυτόν; ἢ οὐδὲ σὺ ταῦτα ἐμελέτησας, ἀλλ᾽ ὡς τὰ γύναια τὰ οὐδενὸς ἄξια πᾶσιν οἷς ἔχαιρες ὡς ἀιεὶ συνεσόμενος συνῆς, τοῖς τόποις, τοῖς ἀνθρώποις, ταῖς διατριβαῖς; καὶ νῦν κλαίων ἐκάθισας, ὅτι μὴ τοὺς αὐτοὺς βλέπεις καὶ ἐν τοῖς αὐτοῖς τόποις διατρίβεις.","st":"3.24"},{"sp":"N","t":"τούτου γὰρ ἄξιος εἶ, ἵνα καὶ τῶν κοράκων καὶ κορωνῶν ἀθλιώτερος ᾖς, οἷς ἔξεστιν ἵπτασθαι, ὅπου θέλουσιν, καὶ μετοικοδομεῖν τὰς νεοσσιὰς καὶ τὰ πελάγη διαπερᾶν μὴ στένουσιν μηδὲ ποθοῦσι τὰ πρῶτα.","st":"3.24"},{"sp":"N","t":"— ναί: ἀλλ᾽ ὑπὸ τοῦ ἄλογα εἶναι πάσχει αὐτά. — ἡμῖν οὖν λόγος ἐπὶ ἀτυχίᾳ καὶ κακοδαιμονίᾳ δέδοται ὑπὸ τῶν θεῶν, ἵν᾽ ἄθλιοι, ἵνα πενθοῦντες διατελῶμεν;","st":"3.24"},{"sp":"N","t":"ἢ πάντες ἔστωσαν ἀθάνατοι καὶ μηδεὶς ἀποδημείτω, μηδ᾽ ἡμεῖς ποῦ ἀποδημῶμεν, ἀλλὰ μένωμεν ὡς τὰ φυτὰ προσερριζωμένοι: ἂν δέ τις ἀποδημήσῃ τῶν συνήθων, καθήμενοι κλαίωμεν καὶ πάλιν, ἂν ἔλθῃ, ὀρχώμεθα καὶ κροτῶμεν ὡς τὰ παιδία;","st":"3.24"},{"sp":"N","t":"οὐκ ἀπογαλακτίσομεν ἤδη ποθ᾽ ἑαυτοὺς καὶ μεμνησόμεθα ὧν ἠκούσαμεν παρὰ τῶν φιλοσόφων; εἴ γε μὴ ὡς ἐπαοιδῶν αὐτῶν ἠκούομεν, ὅτι ὁ κόσμος οὗτος μία πόλις ἐστὶ καὶ ἡ οὐσία, ἐξ ἧς δεδημιούργηται, μία καὶ ἀνάγκη περίοδόν τινα εἶναι καὶ παραχώρησιν ἄλλων ἄλλοις καὶ τὰ μὲν διαλύεσθαι, τὰ δ᾽ ἐπιγίνεσθαι, τὰ μὲν μένειν ἐν τῷ αὐτῷ, τὰ δὲ κινεῖσθαι.","st":"3.24"},{"sp":"N","t":"πάντα δὲ φίλων μεστά, πρῶτα μὲν θεῶν, εἶτα καὶ ἀνθρώπων φύσει πρὸς ἀλλήλους ᾠκειωμένων: καὶ δεῖ τοὺς μὲν παρεῖναι ἀλλήλοις, τοὺς δ᾽ ἀπαλλάττεσθαι, τοῖς μὲν συνοῦσι χαίροντας, τοῖς δ᾽ ἀπαλλαττομένοις μὴ ἀχθομένους.","st":"3.24"},{"sp":"N","t":"ὁ δ᾽ ἄνθρωπος πρὸς τῷ φύσει μεγαλόφρων εἶναι καὶ πάντων τῶν ἀπροαιρέτων καταφρονητικὸς ἔτι κἀκεῖνο ἔσχηκε τὸ μὴ ἐρριζῶσθαι μηδὲ προσπεφυκέναι τῇ γῇ, ἀλλὰ ἄλλοτ᾽ ἐπ᾽ ἄλλους ἵεσθαι τόπους ποτὲ μὲν χρειῶν τινων ἐπειγουσῶν, ποτὲ δὲ καὶ αὐτῆς τῆς θέας ἕνεκα. καὶ τῷ Ὀδυσσεῖ τὸ συμβὰν τοιοῦτόν τι ἦν:","st":"3.24"},{"sp":"N","t":"πολλῶν δ᾽ ἀνθρώπων ἴδεν ἄστεα καὶ νόον ἔγνω: καὶ ἔτι πρόσθεν τῷ Ἡρακλεῖ περιελθεῖν τὴν οἰκουμένην ὅλην ἀνθρώπων ὕβριν τε καὶ εὐνομίην ἐφορῶντα καὶ τὴν μὲν ἐκβάλλοντα καὶ καθαίροντα, τὴν δ᾽ ἀντεισάγοντα.","st":"3.24"},{"sp":"N","t":"καίτοι πόσους οἴει φίλους ἔσχεν ἐν Θήβαις, πόσους ἐν Ἄργει, πόσους ἐν Ἀθήναις, πόσους δὲ περιερχόμενος ἐκτήσατο, ὅς γε καὶ ἐγάμει, ὅπου καιρὸς ἐφάνη αὐτῷ, καὶ ἐπαιδοποιεῖτο καὶ τοὺς παῖδας ἀπέλειπεν οὐ στένων οὐδὲ ποθῶν οὐδ᾽ ὡς ὀρφανοὺς ἀφιείς;","st":"3.24"},{"sp":"N","t":"ᾔδει γάρ, ὅτι οὐδείς ἐστιν ἄνθρωπος ὀρφανός, ἀλλὰ πάντων ἀιεὶ καὶ διηνεκῶς ὁ πατήρ ἐστιν ὁ κηδόμενος.","st":"3.24"},{"sp":"N","t":"οὐ γὰρ μέχρι λόγου ἠκηκόει, ὅτι πατήρ ἐστιν ὁ Ζεὺς τῶν ἀνθρώπων, ὅς γε καὶ αὑτοῦ πατέρα ᾤετο αὐτὸν καὶ ἐκάλει καὶ πρὸς ἐκεῖνον ἀφορῶν ἔπραττεν ἃ ἔπραττεν. τοιγάρτοι πανταχοῦ ἐξῆν αὐτῷ διάγειν εὐδαιμόνως.","st":"3.24"},{"sp":"N","t":"οὐδέποτε δ᾽ ἐστὶν οἷόν τ᾽ εἰς τὸ αὐτὸ ἐλθεῖν εὐδαιμονίαν καὶ πόθον τῶν οὐ παρόντων τὸ γὰρ εὐδαιμονοῦν ἀπέχειν δεῖ πάντα ἃ θέλει, πεπληρωμένῳ τινὶ ἐοικέναι: οὐ δίψος δεῖ προσεῖναι αὐτῷ, οὐ λιμόν.","st":"3.24"},{"sp":"N","t":"— ἀλλ᾽ ὁ Ὀδυσσεὺς ἐπεπόνθει πρὸς τὴν γυναῖκα καὶ ἔκλαιεν ἐπὶ πέτραις καθεζόμενος. — σὺ δ᾽ Ὁμήρῳ πάντα προσέχεις καὶ τοῖς μύθοις αὐτοῦ; ἢ εἰ ταῖς ἀληθείαις ἔκλαεν, τί ἄλλο ἢ ἐδυστύχει; τίς δὲ καλός τε καὶ ἀγαθὸς δυστυχεῖ;","st":"3.24"},{"sp":"N","t":"τῷ ὄντι κακῶς διοικεῖται τὰ ὅλα, εἰ μὴ ἐπιμελεῖται ὁ Ζεὺς τῶν ἑαυτοῦ πολιτῶν, ἵν᾽ ὦσιν ὅμοιοι αὐτῷ, εὐδαίμονες. ἀλλὰ ταῦτα οὐ θεμιτὰ οὐδ᾽ ὅσια ἐνθυμηθῆναι,","st":"3.24"},{"sp":"N","t":"ἀλλ᾽ ὁ Ὀδυσσεύς, εἰ μὲν ἔκλαεν καὶ ὠδύρετο, οὐκ ἦν ἀγαθός. τίς γὰρ ἀγαθός ἐστιν ὁ οὐκ εἰδώς, ὅς ἐστιν; τίς δ᾽ οἶδεν ταῦτα ἐπιλελησμένος, ὅτι φθαρτὰ τὰ γενόμενα καὶ ἄνθρωπον ἀνθρώπῳ συνεῖναι οὐ δυνατὸν ἀεί;","st":"3.24"},{"sp":"N","t":"τί οὖν; τῶν μὴ δυνατῶν ἐφίεσθαι ἀνδραποδῶδες, ἠλίθιον, ξένου θεομαχοῦντος, ὡς μόνον οἷόν τε, τοῖς δόγμασι τοῖς ἑαυτοῦ. ἀλλ᾽ ἡ μήτηρ μου στένει μὴ ὁρῶσά με.","st":"3.24"},{"sp":"N","t":"— διὰ τί γὰρ οὐκ ἔμαθεν τούτους τοὺς λόγους; καὶ οὐ τοῦτό φημι, ὅτι οὐκ ἐπιμελητέον τοῦ μὴ οἰμώζειν αὐτήν, ἀλλ᾽ ὅτι οὐ δεῖ θέλειν τὰ ἀλλότρια ἐξ ἅπαντος.","st":"3.24"},{"sp":"N","t":"λύπη δ᾽ ἡ ἄλλου ἀλλότριόν ἐστιν, ἡ δ᾽ ἐμὴ ἐμόν. ἐγὼ οὖν τὸ μὲν ἐμὸν παύσω ἐξ ἅπαντος, ἐπ᾽ ἐμοὶ γάρ ἐστιν: τὸ δ᾽ ἀλλότριον πειράσομαι κατὰ δύναμιν, ἐξ ἅπαντος δ᾽ οὐ πειράσομαι.","st":"3.24"},{"sp":"N","t":"εἰ δὲ μή, θεομαχήσω, ἀντιθήσω πρὸς τὸν Δία, ἀντιδιατάξομαι αὐτῷ πρὸς τὰ ὅλα. καὶ τἀπίχειρα τῆς θεομαχίας ταύτης καὶ ἀπειθείας οὐ παῖδες παίδων ἐκτίσουσιν, ἀλλ᾽ αὐτὸς ἐγὼ μεθ᾽ ἡμέραν, νυκτὸς διὰ τῶν ἐνυπνίων ἐκπηδῶν, ταρασσόμενος, πρὸς πᾶσαν ἀπαγγελίαν τρέμων, ἐξ ἐπιστολῶν ἀλλοτρίων ἠρτημένην ἔχων τὴν ἐμαυτοῦ ἀπάθειαν.","st":"3.24"},{"sp":"N","t":"ἀπὸ Ῥώμης τις ἥκει. ‘μόνον μή τι κακόν.’ τί δὲ κακὸν ἐκεῖ σοι συμβῆναι δύναται, ὅπου μὴ εἶ; ἀπὸ τῆς Ἑλλάδος. ‘μόνον μή τι κακόν.’ οὕτως σοι πᾶς τόπος δύναται δυστυχίας εἶναι αἴτιος. οὐχ ἱκανὸν ἐκεῖ σε ἀτυχεῖν,","st":"3.24"},{"sp":"N","t":"ὅπου αὐτὸς εἶ, ἀλλὰ καὶ πέραν θαλάσσης καὶ διὰ γραμμάτων; οὕτως ἀσφαλῶς σοι τὰ πράγματα ἔχει;","st":"3.24"},{"sp":"N","t":"— τί οὖν, ἂν ἀποθάνωσιν οἱ ἐκεῖ φίλοι; — τί γὰρ ἂν ἄλλο ἢ οἱ θνητοὶ ἀπέθανον; ἢ πῶς ἅμα μὲν γηρᾶσαι θέλεις, ἅμα δὲ μηδενὸς τῶν στεργομένων μὴ εἰδεῖν θάνατον;","st":"3.24"},{"sp":"N","t":"οὐκ οἶσθ᾽, ὅτι ἐν τῷ μακρῷ χρόνῳ πολλὰ καὶ ποικίλα ἀποβαίνειν ἀνάγκη, τοῦ μὲν πυρετὸν γενέσθαι κρείττονα, τοῦ δὲ λῃστήν, τοῦ δὲ τύραννον;","st":"3.24"},{"sp":"N","t":"τοιοῦτο γὰρ τὸ περιέχον, τοιοῦτον οἱ συνόντες, ψύχη καὶ καύματα καὶ τροφαὶ ἀσύμμετροι καὶ ὁδοιπορίαι καὶ πλοῦς καὶ ἄνεμοι καὶ περιστάσεις ποικίλαι: τὸν μὲν ἀπώλεσαν, τὸν δ᾽ ἐξώρισαν, τὸν δ᾽ εἰς πρεσβείαν, ἄλλον δ᾽ εἰς στρατ","st":"3.24"},{"sp":"N","t":"είαν ἐνέβαλον. κάθησο τοίνυν πρὸς πάντα ταῦτα ἐπτοημένος, πενθῶν, ἀτυχῶν, δυστυχῶν, ἐξ ἄλλου ἠρτημένος καὶ τούτου οὐχ ἑνός, οὐ δυεῖν, ἀλλὰ μυρίων ἐπὶ μυρίοις.","st":"3.24"},{"sp":"N","t":"ταῦτα ἤκουες παρὰ τοῖς φιλοσόφοις, ταῦτ᾽ ἐμάνθανες; οὐκ οἶσθ᾽, ὅτι στρατεία τὸ χρῆμά ἐστιν; τὸν μὲν δεῖ φυλάττειν, τὸν δὲ κατασκοπήσοντα ἐξιέναι, τὸν δὲ καὶ πολεμήσοντα: οὐχ οἷόν τ᾽ εἶναι πάντας ἐν τῷ αὐτῷ οὐδ᾽ ἄμεινον.","st":"3.24"},{"sp":"N","t":"σὺ δ᾽ ἀφεὶς ἐκτελεῖν τὰ προστάγματα τοῦ στρατηγοῦ ἐγκαλεῖς, ὅταν τί σοι προσταχθῇ τραχύτερον, καὶ οὐ παρακολουθεῖς, οἷον ἀποφαίνεις, ὅσον ἐπὶ σοί, τὸ στράτευμα, ὅτι ἄν σε πάντες μιμήσωνται, οὐ τάφρον σκάψει τις, οὐ χάρακα περιβαλεῖ, οὐκ ἀγρυπνήσει, οὐ κινδυνεύσει, ἀλλὰ ἄχρηστος δόξει στρατεύεσθαι.","st":"3.24"},{"sp":"N","t":"πάλιν ἐν πλοίῳ ναύτης ἂν πλέῃς, μίαν χώραν κάτεχε καὶ ταύτην προσλιπάρει: ἂν δ᾽ ἐπὶ τὸν ἱστὸν ἀναβῆναι δέῃ, μὴ θέλε, ἂν εἰς τὴν πρῴραν διαδραμεῖν, μὴ θέλε: καὶ τίς ἀνέξεταί σου κυβερνήτης; οὐχὶ δ᾽ ὡς σκεῦος ἄχρηστον ἐκβαλεῖ, οὐδὲν ἄλλο ἢ ἐμπόδιον καὶ κακὸν παράδειγμα τῶν ἄλλων ναυτῶν;","st":"3.24"},{"sp":"N","t":"οὕτως δὲ καὶ ἐνθάδε: στρατεία τίς ἐστιν ὁ βίος ἑκάστου καὶ αὕτη μακρὰ καὶ ποικίλη. τηρεῖν σε δεῖ τὸ τοῦ στρατιώτου καὶ τοῦ στρατηγοῦ πρὸς νεῦμα πράσσειν ἕκαστα:","st":"3.24"},{"sp":"N","t":"εἰ οἷόν τε, μαντευόμενον ἃ θέλει. οὐδὲ γὰρ ὅμοιος ἐκεῖνος ὁ στρατηγὸς καὶ οὗτος οὔτε κατὰ τὴν ἰσχὺν οὔτε κατὰ τὴν τοῦ ἤθους ὑπεροχήν.","st":"3.24"},{"sp":"N","t":"τέταξαι ἐν πόλει † ἡγεμονίᾳ καὶ οὐκ ἐν ταπεινῇ τινι χώρᾳ, ἀλλ᾽ ἀεὶ βουλευτής. οὐκ οἶσθ᾽, ὅτι τὸν τοιοῦτον ὀλίγα μὲν δεῖ οἰκονομεῖν, τὰ πολλὰ δ᾽ ἀποδημεῖν ἄρχοντα ἢ ἀρχόμενον ἢ ὑπηρετοῦντά τινι ἀρχῇ ἢ στρατευόμενον ἢ δικάζοντα; εἶτά μοι θέλεις ὡς φυτὸν προσηρτῆσθαι τοῖς αὐτοῖς τόποις καὶ προσερριζῶσθαι;","st":"3.24"},{"sp":"N","t":"— ἡδὺ γάρ ἐστιν. — τίς οὔ φησιν; ἀλλὰ καὶ ζωμὸς ἡδύς ἐστι καὶ γυνὴ καλὴ ἡδύ ἐστιν. τί ἄλλο λέγουσιν οἱ τέλος ποιούμενοι τὴν ἡδονήν;","st":"3.24"},{"sp":"N","t":"οὐκ αἰσθάνῃ, τίνων ἀνθρώπων φωνὴν ἀφῆκας; ὅτι Ἐπικουρείων καὶ κιναίδων; εἶτα τὰ ἐκείνων ἔργα πράσσων καὶ τὰ δόγματα ἔχων τοὺς λόγους ἡμῖν λέγεις τοὺς Ζήνωνος καὶ Σωκράτους; οὐκ ἀπορρίψεις ὡς μακροτάτω τἀλλότρια, οἷς κοσμῇ μηδέν σοι προσήκουσιν;","st":"3.24"},{"sp":"N","t":"ἢ τί ἄλλο θέλουσιν ἐκεῖνοι ἢ καθεύδειν ἀπαραποδίστως καὶ ἀναναγκάστως καὶ ἀναστάντες ἐφ᾽ ἡσυχίας χασμήσασθαι καὶ τὸ πρόσωπον ἀποπλῦναι, εἶτα γράψαι καὶ ἀναγνῶναι ἃ θέλουσιν, εἶτα φλυαρῆσαί τί ποτ᾽ ἐπαινούμενοι ὑπὸ τῶν φίλων, ὅ τι ἂν λέγωσιν, εἶτα εἰς περίπατον προελθόντες καὶ ὀλίγα περιπατήσαντες λούσασθαι, εἶτα φαγεῖν, εἶτα κοιμηθῆναι, οἵαν δὴ κοίτην καθεύδειν τοὺς τοιούτους εἰκός — τί ἄν τις λέγοι; ἔξεστιν γὰρ τεκμαίρεσθαι.","st":"3.24"},{"sp":"N","t":"ἄγε, φέρε μοι καὶ σὺ τὴν σαυτοῦ διατριβήν, ἣν ποθεῖς, ζηλωτὰ τῆς ἀληθείας καὶ Σωκράτους καὶ Διογένους. τί θέλεις ἐν Ἀθήναις ποιεῖν; ταῦτα αὐτά;","st":"3.24"},{"sp":"N","t":"μή τι ἕτερα; τί οὖν Στωικὸν σαυτὸν εἶναι λέγεις; εἶτα οἱ μὲν τῆς Ῥωμαίων πολιτείας καταψευδόμενοι κολάζονται πικρῶς, τοὺς δ᾽ οὕτως μεγάλου καὶ σεμνοῦ καταψευδομένους πράγματος καὶ ὀνόματος ἀθῴους ἀπαλλάττεσθαι δεῖ;","st":"3.24"},{"sp":"N","t":"ἢ τοῦτό γε οὐ δυνατόν, ἀλλ᾽ ὁ νόμος θεῖος καὶ ἰσχυρὸς καὶ ἀναπόδραστος οὗτός ἐστιν ὁ τὰς μεγίστας εἰσπρασσόμενος κολάσεις παρὰ τῶν τὰ μέγιστα ἁμαρτανόντων;","st":"3.24"},{"sp":"N","t":"τί γὰρ λέγει; ‘ὁ προσποιούμενος τὰ μηδὲν πρὸς αὐτὸν ἔστω ἀλαζών, ἔστω κενόδοξος: ὁ ἀπειθῶν τῇ θείᾳ διοικήσει ἔστω ταπεινός, ἔστω δοῦλος, λυπείσθω, φθονείτω, ἐλεείτω, τὸ κεφάλαιον πάντων, δυστυχείτω, θρηνείτω.’","st":"3.24"},{"sp":"N","t":"τί οὖν; θέλεις με τὸν δεῖνα θεραπεύειν; ἐπὶ θύραις αὐτοῦ πορεύεσθαι; — εἰς τοῦτο αἱρεῖ λόγος, ὑπὲρ τῆς πατρίδος, ὑπὲρ τῶν συγγενῶν, ὑπὲρ ἀνθρώπων, διὰ τί μὴ ἀπέλθῃς; ἀλλ᾽ ἐπὶ μὲν τὰς τοῦ σκυτέως οὐκ αἰσχύνῃ πορευόμενος, ὅταν δέῃ ὑποδημάτων, οὐδ᾽ ἐπὶ τὰς τοῦ κηπουροῦ, ὅταν θιδράκων, ἐπὶ δὲ τὰς τῶν πλουσίων, ὅταν τινὸς ὁμοίου δέῃ;","st":"3.24"},{"sp":"N","t":"— ναί: τὸν σκυτέα γὰρ οὐ θαυμάζω. — μηδὲ τὸν πλούσιον. — οὐδὲ τὸν κηπουρὸν κολακεύσω. — μηδὲ τὸν πλούσιον. πῶς οὖν τύχω οὗ δέομαι;","st":"3.24"},{"sp":"N","t":"— ἐγὼ δέ σοι λέγω ὅτι ‘ὡς τευξόμενος ἀπέρχου;’ οὐχὶ δὲ μόνον, ἵνα πράξῃς τὸ σαυτῷ πρέπον;","st":"3.24"},{"sp":"N","t":"— τί οὖν ἔτι πορεύομαι; — ἵν᾽ ἀπέλθῃς, ἵνα ἀποδεδωκὼς ᾖς τὰ τοῦ πολίτου ἔργα, τὰ ἀδελφοῦ, τὰ φίλου.","st":"3.24"},{"sp":"N","t":"καὶ λοιπὸν μέμνησο, ὅτι πρὸς σκυτέα ἀφῖξαι, πρὸς λαχανοπώλην, οὐδενὸς μεγάλου ἢ σεμνοῦ ἔχοντα τὴν ἐξουσίαν, κἂν αὐτὸ πολλοῦ πωλῇ. ὡς ἐπὶ τὰς θίδρακας ἀπέρχῃ: ὀβολοῦ γάρ εἰσιν, ταλάντου δ᾽ οὐκ εἰσίν.","st":"3.24"},{"sp":"N","t":"οὕτως κἀνταῦθα. τοῦ ἐπὶ θύρας ἐλθεῖν ἄξιον τὸ πρᾶγμα: ἔστω, ἀφίξομαι. τοῦ διαλεχθῆναι οὕτως: ἔστω, διαλεχθήσομαι. ἀλλὰ καὶ τὴν χεῖρα δεῖ καταφιλῆσαι καὶ θωπεῦσαι δι᾽ ἐπαίνου. ἄπαγε, ταλάντου ἐστίν: οὐ λυσιτελεῖ μοι οὐδὲ τῇ πόλει οὐδὲ τοῖς φίλοις ἀπολέσαι καὶ πολίτην ἀγαθὸν καὶ φίλον.","st":"3.24"},{"sp":"N","t":"ἀλλὰ δόξεις μὴ προτεθυμῆσθαι μὴ ἀνύσας. πάλιν ἐπελάθου, τίνος ἕνεκα ἐλήλυθας; οὐκ οἶσθ᾽, ὅτι ἀνὴρ καλὸς καὶ ἀγαθὸς οὐδὲν ποιεῖ τοῦ δόξαι ἕνεκα, ἀλλὰ τοῦ πεπρᾶχθαι καλῶς;","st":"3.24"},{"sp":"N","t":"— τί οὖν ὄφελος αὐτῷ τοῦ πρᾶξαι καλῶς; — τί δ᾽ ὄφελος τῷ γράφοντι τὸ Δίωνος ὄνομα, ὡς χρὴ γράφειν; αὐτὸ τὸ γράψαι. — ἔπαθλον οὖν οὐδέν; — σὺ δὲ ζητεῖς ἔπαθλον ἀνδρὶ ἀγαθῷ μεῖζον τοῦ τὰ καλὰ καὶ δίκαια πράττειν;","st":"3.24"},{"sp":"N","t":"ἐν Ὀλυμπίᾳ δ᾽ οὐδεὶς ἄλλο οὐδέν, ἀλλ᾽ ἀρκεῖν σοι δοκεῖ τὸ ἐστεφανῶσθαι Ὀλύμπια. οὕτως σοι μικρὸν καὶ οὐδενὸς ἄξιον εἶναι φαίνεται τὸ εἶναι καλὸν καὶ ἀγαθὸν καὶ εὐδαίμονα;","st":"3.24"},{"sp":"N","t":"πρὸς ταῦτα ὑπὸ θεῶν εἰς τὴν πόλιν ταύτην εἰσηγμένος καὶ ἤδη τῶν ἀνδρὸς ἔργων ὀφείλων ἅπτεσθαι τιτθὰς ἐπιποθεῖς καὶ μάμμην καὶ κάμπτει σε καὶ ἀποθηλύνει κλαίοντα γύναια μωρά; οὕτως οὐδέποτε παύσει παιδίον: ὢν νήπιον; οὐκ οἶσθ᾽, ὅτι ὁ τὰ παιδίου ποιῶν ὅσῳ πρεσβύτερος τοσούτῳ γελοιότερος;","st":"3.24"},{"sp":"N","t":"ἐν Ἀθήναις δ᾽ οὐδένα ἑώρας εἰς οἶκον αὐτοῦ φοιτῶν; — ὃν ἐβουλόμην. — καὶ ἐνθάδε τοῦτον θέλε ὁρᾶν καὶ ὃν βούλει ὄψει: μόνον μὴ ταπεινῶς, μὴ μετ᾽ ὀρέξεως ἢ ἐκκλίσεως καὶ ἔσται τὰ σὰ καλῶς.","st":"3.24"},{"sp":"N","t":"τοῦτο δ᾽ οὐκ ἐν τῷ ἐλθεῖν ἐστιν οὐδ᾽ ἐν τῷ ἐπὶ θύραις στῆναι, ἀλλ᾽ ἔνδον ἐν τοῖς δόγμασιν.","st":"3.24"},{"sp":"N","t":"ὅταν τὰ ἐκτὸς καὶ ἀπροαίρετα ἠτιμακὼς ᾖς καὶ μηδὲν αὐτῶν σὸν ἡγημένος, μόνα δ᾽ ἐκεῖνα σά, τὸ κρῖναι καλῶς, τὸ ὑπολαβεῖν, τὸ ὁρμῆσαι, τὸ ὀρεχθῆναι, τὸ ἐκκλῖναι, ποῦ ἔτι κολακείας τόπος, ποῦ ταπεινοφροσύνης; τί ἔτι ποθεῖς τὴν ἡσυχίαν τὴν ἐκεῖ, τί τοὺς συνήθεις τόπους;","st":"3.24"},{"sp":"N","t":"ἔκδεξαι βραχὺ καὶ τούτους πάλιν ἕξεις συνήθεις. εἶτα ἂν οὕτως ἀγεννῶς ἔχῃς, πάλιν καὶ τούτων ἀπαλλαττόμενος κλαῖε καὶ στένε. πῶς οὖν γένωμαι φιλόστοργος;","st":"3.24"},{"sp":"N","t":"— ὡς γενναῖος, ὡς εὐτυχής: οὐδέποτε γὰρ αἱρεῖ ὁ λόγος ταπεινὸν εἶναι οὐδὲ κατακλᾶσθαι οὐδ᾽ ἐξ ἄλλου κρέμασθαι οὐδὲ μέμψασθαί ποτε θεὸν ἢ ἄνθρωπον.","st":"3.24"},{"sp":"N","t":"οὕτως μοι γίνου φιλόστοργος ὡς ταῦτα τηρήσων: εἰ δὲ διὰ τὴν φιλοστοργίαν ταύτην, τἥντινά ποτε καὶ καλεῖς φιλοστοργίαν, δοῦλος μέλλεις εἶναι καὶ ἄθλιος, οὐ λυσιτελεῖ φιλόστοργον εἶναι.","st":"3.24"},{"sp":"N","t":"καὶ τί κωλύει φιλεῖν τινα ὡς θνητόν, ὡς ἀποδημητικόν; ἢ Σωκράτης οὐκ ἐφίλει τοὺς παῖδας τοὺς ἑαυτοῦ; ἀλλ᾽ ὡς ἐλεύθερος, ὡς μεμνημένος, ὅτι πρῶτον δεῖ θεοῖς εἶναι φίλον.","st":"3.24"},{"sp":"N","t":"διὰ τοῦτο οὐδὲν παρέβη τῶν πρεπόντων ἀνδρὶ ἀγαθῷ οὔτ᾽ ἀπολογούμενος οὐθ᾽ ὑποτιμώμενος οὔτ᾽ ἔτι πρόσθεν βουλεύων ἢ στρατευόμενος.","st":"3.24"},{"sp":"N","t":"ἡμεῖς δὲ πάσης προφάσεως πρὸς τὸ ἀγγεννεῖς εἶναι εὐποροῦμεν, οἱ μὲν διὰ παῖδα, οἱ δὲ διὰ μητέρα, ἄλλοι δὲ δι᾽ ἀδελφούς.","st":"3.24"},{"sp":"N","t":"δι᾽ οὐδένα δὲ προσήκει δυστυχεῖν, ἀλλὰ εὐτυχεῖν διὰ πάντας, μάλιστα δὲ διὰ τὸν θεὸν τὸν ἐπὶ τοῦτο ἡμᾶς κατασκευάσαντα.","st":"3.24"},{"sp":"N","t":"ἄγε, Διογένης δ᾽ οὐκ ἐφίλει οὐδένα, ὃς οὕτως ἥμερος ἦν καὶ φιλάνθρωπος, ὥστε ὑπὲρ τοῦ κοινοῦ τῶν ἀνθρώπων τοσούτους πόνους καὶ ταλαιπωρίας τοῦ σώματος ἄσμενος ἀναδέχεσθαι;","st":"3.24"},{"sp":"N","t":"ἀλλ᾽ ἐφίλει πῶς; ὡς τοῦ Διὸς διάκονον ἔδει, ἅμα μὲν κηδόμενος, ἅμα δ᾽ ὡς τῷ θεῷ ὑποτεταγμένος. διὰ τοῦτο πᾶσα γῆ πατρὶς ἦν ἐκείνῳ μόνῳ,","st":"3.24"},{"sp":"N","t":"ἐξαίρετος δ᾽ οὐδεμία: καὶ ἁλοὺς οὐκ ἐπόθει τὰς Ἀθήνας οὐδὲ τοὺς ἐκεῖ συνήθεις καὶ φίλους, ἀλλ᾽ αὐτοῖς τοῖς πειραταῖς συνήθης ἐγίνετο καὶ ἐπανορθοῦν ἐπειρᾶτο. καὶ πραθεὶς ὕστερον ἐν Κορίνθῳ διῆγεν οὕτως ὡς πρόσθεν ἐν Ἀθήναις καὶ εἰς Περραιβοὺς δ᾽ ἂν ἀπελθὼν ὡσαύτως εἶχεν.","st":"3.24"},{"sp":"N","t":"οὕτως ἐλευθερία γίνεται. διὰ τοῦτο ἔλεγεν ὅτι ‘ἐξ οὗ μ᾽ Ἀντισθένης ἠλευθέρωσεν, οὐκέτι ἐδούλευσα.’","st":"3.24"},{"sp":"N","t":"πῶς ἠλευθέρωσεν; ἄκουε, τί λέγει: ‘ἐδίδαξέν με τὰ ἐμὰ καὶ τὰ οὐκ ἐμά. κτῆσις οὐκ ἐμή: συγγενεῖς, οἰκεῖοι, φίλοι, φήμη, συνήθεις τόποι, διατριβή, πάντα ταῦτα ὅτι ἀλλότρια.","st":"3.24"},{"sp":"N","t":"‘σὸν οὖν τί; χρῆσις φαντασιῶν.’ ταύτην ἔδειξέν μοι ὅτι ἀκώλυτον ἔχω, ἀνανάγκαστον: οὐδεὶς ἐμποδίσαι δύναται, οὐδεὶς βιάσασθαι ἄλλως χρήσασθαι ἢ ὡς θέλω.","st":"3.24"},{"sp":"N","t":"τίς οὖν ἔτι ἔχει μου ἐξουσίαν; Φίλιππος ἢ Ἀλέξανδρος ἢ Περδίκκας ἢ ὁ μέγας βασιλεύς; πόθεν αὐτοῖς; τὸν γὰρ ὑπ᾽ ἀνθρώπου μέλλοντα ἡττᾶσθαι πολὺ πρότερον ὑπὸ τῶν πραγμάτων δεῖ ἡττᾶσθαι.’","st":"3.24"},{"sp":"N","t":"οὗτινος οὖν οὐχ ἡδονὴ κρείττων ἐστίν, οὐ πόνος, οὐ δόξα, οὐ πλοῦτος, δύναται δ᾽, ὅταν αὐτῷ δόξῃ, τὸ σωμάτιον ὅλον προσπτύσας τινὶ ἀπελθεῖν, τίνος ἔτι οὗτος δοῦλός ἐστιν, τίνι ὑποτέτακται;","st":"3.24"},{"sp":"N","t":"εἰ δ᾽ ἡδέως ἐν Ἀθήναις διῆγεν καὶ ἥττητο ταύτης τῆς διατριβῆς, ἐπὶ παντὶ ἂν ἦν τὰ ἐκείνου πράγματα, ὁ ἰσχυρότερος κύριος ἂν ἦν λυπῆσαι αὐτόν.","st":"3.24"},{"sp":"N","t":"πῶς ἂν δοκεῖς τοὺς πειρατὰς ἐκολάκευεν, ἵν᾽ αὐτὸν Ἀθηναίων τινὶ πωλήσωσιν, ἵν᾽ ἴδῃ ποτὲ τὸν Πειραιᾶ τὸν καλὸν καὶ τὰ μακρὰ τείχη καὶ τὴν ἀκρόπολιν;","st":"3.24"},{"sp":"N","t":"τίς ὢν εἴδῃς, ἀνδράποδον;","st":"3.24"},{"sp":"N","t":"δοῦλος καὶ ταπεινός: καὶ τί σοι ὄφελος; — οὔ: ἀλλ᾽ ἐλεύθερος. — δεῖξον, πῶς ἐλεύθερος. ἰδοὺ ἐπείληπταί σου τίς ποτε οὗτος ὁ ἐξάγων σε ἀπὸ τῆς συνήθους σοι διατριβῆς καὶ λέγει ‘δοῦλος ἐμὸς εἶ: ἐπ᾽ ἐμοὶ γάρ ἐστι κωλῦσαί σε διάγειν ὡς θέλεις, ἐπ᾽ ἐμοὶ τὸ ἀνεῖναί σε, τὸ ταπεινοῦν: ὅταν θέλω, πάλιν εὐφραίνῃ καὶ μετέωρος πορεύῃ εἰς Ἀθήνας.’","st":"3.24"},{"sp":"N","t":"τί λέγεις πρὸς τοῦτον τὸν δουλαγωγοῦντά σε; ποῖον αὐτῷ καρπιστὴν δίδως; ἢ οὐδ᾽ ὅλως ἀντιβλέπεις, ἀλλ᾽ ἀφεὶς τοὺς πολλοὺς λόγους ἱκετεύεις, ἵνα ἀφεθῇς;","st":"3.24"},{"sp":"N","t":"ἄνθρωπε, εἰς φυλακήν σε δεῖ χαίροντα ἀπιέναι, σπεύδοντα, φθάνοντα τοὺς ἀπάγοντας. εἶτά μοι σὺ μὲν ἐν Ῥώμῃ διάγειν ὀκνεῖς, τὴν Ἑλλάδα ποθεῖς; ὅταν δ᾽ ἀποθνῄσκειν δέῃ, καὶ τότε μέλλεις ἡμῶν κατακλαίειν, ὅτι τὰς Ἀθήνας οὐ μέλλεις βλέπειν καὶ ἐν Λυκείῳ οὐ περιπατήσεις;","st":"3.24"},{"sp":"N","t":"ἐπὶ τοῦτο ἀπεδήμησας; τούτου ἕνεκα ἐζήτησάς τινι συμβαλεῖν, ἵν᾽ ὠφεληθῇς ὑπ᾽ αὐτοῦ; ποίαν ὠφέλειαν; συλλογισμοὺς ἵν᾽ ἀναλύσῃς ἑκτικώτερον ἢ ἐφοδεύσης ὑποθετικούς; καὶ διὰ ταύτην τὴν αἰτίαν ἀδελφὸν ἀπέλιπες, πατρίδα, φίλους, οἰκείους, ἵνα ταῦτα μαθὼν ἐπανέλθῃς; ὥστ᾽ οὐχ ὑπὲρ εὐσταθείας ἀπεδήμεις,","st":"3.24"},{"sp":"N","t":"οὐχ ὑπὲρ ἀταραξίας, οὐχ ἵν᾽ ἀβλαβὴς γενόμενος μηκέτι μηδένα μέμφῃ, μηδενὶ ἐγκαλῇς, μηδείς σε ἀδικῇ καὶ οὕτως τὰς σχέσεις ἀποσῴζῃς ἀπαραποδίστως;","st":"3.24"},{"sp":"N","t":"καλὴν ἐστείλω ταύτην τὴν ἐμπορίαν, συλλογισμοὺς καὶ μεταπίπτοντας καὶ ὑποθετικούς: κἄν σοι φανῇ, ἐν τῇ ἀγορᾷ καθίσας πρόγραψον ὡς οἱ φαρμακοπῶλαι.","st":"3.24"},{"sp":"N","t":"οὐκ ἀρνήσῃ καὶ ὅσα ἔμαθες εἰδέναι, ἵνα μὴ διαβάλῃς τὰ θεωρήματα ὡς ἄχρηστα; τί σοι κακὸν ἐποίησεν φιλοσοφία; τί σε ἠδίκησε Χρύσιππος, ἵν᾽ αὐτοῦ τοὺς πόνους ἔργῳ αὐτὸς ἀχρήστους ἐξελέγχῃς; οὐκ ἤρκει σοι τὰ ἐκεῖ κακά, ὅσα εἶχες αἴτια τοῦ λυπεῖσθαι καὶ πενθεῖν, εἰ καὶ μὴ ἀπεδήμησας, ἀλλὰ πλείω προσέλαβες;","st":"3.24"},{"sp":"N","t":"κἂν ἄλλους πάλιν ἔχῃς συνήθεις καὶ φίλους, ἕξεις πλείονα τοῦ οἰμώζειν αἴτια, κἂν πρὸς ἄλλην χώραν προσπαθῇς. τί οὖν ζῇς; ἵνα λύπας ἄλλας ἐπ᾽ ἄλλαις περιβάλῃ, δι᾽ ἃς ἀτυχεῖς;","st":"3.24"},{"sp":"N","t":"εἶτά μοι καλεῖς τοῦτο φιλοστοργίαν; ποίαν, ἄνθρωπε, φιλοστοργίαν; εἰ ἀγαθόν ἐστιν, οὐδενὸς κακοῦ αἴτιον γίνεται: εἰ κακόν ἐστιν, οὐδέν μοι καὶ αὐτῇ ἐγὼ πρὸς τὰ ἀγαθὰ τὰ ἐμαυτοῦ πέφυκα, πρὸς κακὰ οὐ πέφυκα.","st":"3.24"},{"sp":"N","t":"τίς οὖν ἡ πρὸς τοῦτο ἄσκησις; πρῶτον μὲν ἡ ἀνωτάτω καὶ κυριωτάτη καὶ εὐθὺς ὥσπερ ἐν πύλαις, ὅταν τινὶ προσπάσχῃς, οὐδενὶ τῶν ἀναφαιρέτων, ἀλλά τινι τοιούτῳ γένει, οἷόν ἐστι χύτρα, οἷον ὑάλινον ποτήριον, ἵν᾽ ὅταν καταγῇ, μεμνημένος μὴν μὴ ταραχθῇς.","st":"3.24"},{"sp":"N","t":"οὕτως καὶ ἐνθάδ᾽, ἐὰν παιδίον σαυτοῦ καταφιλῇς, ἐὰν ἀδελφόν, ἐὰν φίλον, μηδέποτε ἐπιδῷς τὴν φαντασίαν εἰς ἅπαν μηδὲ τὴν διάχυσιν ἐάσῃς προελθεῖν ἐφ᾽ ὅσον αὐτὴ θέλει, ἀλλ᾽ ἀντίσπασον, κώλυσον, οἷον οἱ τοῖς θριαμβεύουσιν ἐφεστῶτες ὄπισθεν καὶ ὑπομιμνῄσκοντες, ὅτι ἄνθρωποί εἰσιν.","st":"3.24"},{"sp":"N","t":"τοιοῦτόν τι καὶ σὺ ὑπομίμνῃσκε σεαυτόν, ὅτι θνητὸν φιλεῖς, οὐδὲν τῶν σεαυτοῦ φιλεῖς: ἐπὶ τοῦ παρόντος σοι δέδοται, οὐκ ἀναφαίρετον οὐδ᾽ εἰς ἅπαν, ἀλλ᾽ ὡς σῦκον, ὡς σταφυλή, τῇ τεταγμένῃ ὥρᾳ τοῦ ἔτους: ἂν δὲ χειμῶνος ἐπιποθῇς, μωρὸς εἶ. οὕτως κἂν τὸν υἱὸν ἢ τὸν φίλον τότε ποθῇς,","st":"3.24"},{"sp":"N","t":"ὅτε οὐ δέδοταί σοι, ἴσθι, ὅτι χειμῶνος σῦκον ἐπιποθεῖς. οἷον γάρ ἐστι χειμὼν πρὸς σῦκον, τοιοῦτόν ἐστι πᾶσα ἡ ἀπὸ τῶν ὅλων περίστασις πρὸς τὰ κατ᾽ αὐτὴν ἀναιρούμενα. καὶ λοιπὸν ἐν αὐτοῖς οἷς χαίρεις τινί,","st":"3.24"},{"sp":"N","t":"τὰς ἐναντίας φαντασίας σαυτῷ πρόσβαλε. τί κακόν ἐστι μεταξὺ καταφιλοῦντα τὸ παιδίον ἐπιψελλίζοντα λέγειν ‘αὔριον ἀποθανῇ,’ τῷ φίλῳ ὡσαύτως ‘αὔριον ἀποδημήσεις ἢ σὺ ἢ ἐγὼ καὶ οὐκέτι ὀψόμεθα ἀλλήλους;’","st":"3.24"},{"sp":"N","t":"— ἀλλὰ δύσφημά ἐστι ταῦτα. — καὶ γὰρ τῶν ἐπαοιδῶν ἔνιαι, ἀλλ᾽ ὅτι ὠφελοῦσιν, οὐκ ἐπιστρέφομαι, μόνον ὠφελείτω. σὺ δὲ δύσφημα καλεῖς ἄλλα ἢ τὰ κακοῦ τινος σημαντικά; δύσφημόν ἐστι δειλία,","st":"3.24"},{"sp":"N","t":"δύσφημον ἀγέννεια, πένθος, λύπη, ἀναισχυντία: ταῦτα τὰ ὀνόματα δύσφημά ἐστιν. καίτοι γε οὐδὲ ταῦτα ὀκνεῖν δεῖ φθέγγεσθαι ὑπὲρ φυλακῆς τῶν πραγμάτων.","st":"3.24"},{"sp":"N","t":"δύσφημον δέ μοι λέγεις ὄνομα φυσικοῦ τινὸς πράγματος σημαντικόν; λέγε δύσφημον εἶναι καὶ τὸ θερισθῆναι τοὺς στάχυας: ἀπώλειαν γὰρ σημαίνει τῶν σταχύων: ἀλλ᾽ οὐχὶ τοῦ κόσμου. λέγε δύσφημον καὶ τὸ φυλλορροεῖν καὶ τὸ ἰσχάδα γίνεσθαι ἀντὶ σύκου καὶ ἀσταφίδας ἐκ σταφυλῆς.","st":"3.24"},{"sp":"N","t":"πάντα γὰρ ταῦτα τῶν προτέρων εἰσὶν εἰς ἕτερα μεταβολαί: οὐκ ἀπώλεια, ἀλλὰ τεταγμένη τις οἰκονομία καὶ διοίκησις. τοῦτ᾽ ἔστιν ἀποδημία, καὶ μεταβολὴ μικρά:","st":"3.24"},{"sp":"N","t":"τοῦτο θάνατος, μεταβολὴ μείζων ἐκ τοῦ νῦν ὄντος οὐκ εἰς τὸ μὴ ὄν, ἀλλ᾽ εἰς τὸ νῦν μὴ ὄν.","st":"3.24"},{"sp":"N","t":"— οὐκέτι οὖν ἔσομαι; — οὐκ ἔσει: ἀλλ᾽ ἄλλο τι, οὗ νῦν ὁ κόσμος χρείαν ἔχει. καὶ γὰρ σὺ ἐγένου οὐχ ὅτε σὺ ἠθέλησας, ἀλλ᾽ ὅτε ὁ κόσμος χρείαν ἔσχεν.","st":"3.24"},{"sp":"N","t":"διὰ τοῦτο ὁ καλὸς καὶ ἀγαθὸς μεμνημένος, τίς τ᾽ ἐστὶ καὶ πόθεν ἐλήλυθεν καὶ ὑπὸ τίνος γέγονεν, πρὸς μόνῳ τούτῳ ἐστίν, πῶς τὴν αὑτοῦ χώραν ἐκπληρώσῃ εὐτάκτως καὶ εὐπειθῶς τῷ θεῷ.","st":"3.24"},{"sp":"N","t":"‘ἔτι μ᾽ εἶναι θέλεις; ὡς ἐλεύθερος, ὡς γενναῖος, ὡς σὺ ἠθέλησας: σὺ γάρ με ἀκώλυτον ἐποίησας ἐν τοῖς ἐμοῖς.","st":"3.24"},{"sp":"N","t":"ἀλλ᾽ οὐκέτι μου χρείαν ἔχεις; καλῶς σοι γένοιτο: καὶ μέχρι νῦν διὰ σὲ ἔμενον, δι᾽ ἄλλον οὐδένα, καὶ νῦν σοι πειθόμενος ἀπέρχομαι.’","st":"3.24"},{"sp":"N","t":"‘ πῶς ἀπέρχῃ;’ ‘πάλιν ὡς σὺ ἠθέλησας, ὡς ἐλεύθερος, ὡς ὑπηρέτης σός, ὡς ᾐσθημένος σου τῶν προσταγμάτων καὶ ἀπαγορευμάτων.","st":"3.24"},{"sp":"N","t":"μέχρι δ᾽ ἂν οὗ διατρίβω ἐν τοῖς σοῖς, τίνα με θέλεις εἶναι; ἄρχοντα ἢ ἰδιώτην, βουλευτὴν ἢ δημότην, στρατιώτην ἢ στρατηγόν, † παιδευτὴν ἢ οἰκοδεσπότην; ἣν ἂν χώραν καὶ τάξιν ἐγχειρίσῃς, ὡς λέγει ὁ Σωκράτης, μυριάκις ἀποθανοῦμαι πρότερον ἢ ταύτην ἐγκαταλείψω.","st":"3.24"},{"sp":"N","t":"ποῦ δέ μ᾽ εἶναι θέλεις; ἐν Ῥώμῃ ἢ ἐν Ἀθήναις ἢ ἐν Θήβαις ἢ ἐν Γυάροις; μόνον ἐκεῖ μου μέμνησο.","st":"3.24"},{"sp":"N","t":"ἄν μ᾽ ἐκεῖ πέμπῃς, ὅπου κατὰ φύσιν διεξαγωγὴ οὐκ ἔστιν ἀνθρώπων, οὐ σοὶ ἀπειθῶν ἔξειμι, ἀλλ᾽ ὡς σοῦ μοι σημαίνοντος τὸ ἀνακλητικόν: οὐκ ἀπολείπω σε: μὴ γένοιτο: ἀλλ᾽ αἰσθάνομαι, ὅτι μου χρείαν οὐκ ἔχεις. ἂν δὲ διδῶται κατὰ φύσιν διεξαγωγή,","st":"3.24"},{"sp":"N","t":"οὐ ζητήσω ἄλλον τόπον ἢ ἐν ᾧ εἰμὶ ἢ ἄλλους ἀνθρώπους ἢ μεθ᾽ ὧν εἰμί.’","st":"3.24"},{"sp":"N","t":"ταῦτα νυκτός, ταῦτα ἡμέρας πρόχειρα ἔστω: ταῦτα γράφειν, ταῦτα ἀναγιγνώσκειν: περὶ τούτων τοὺς λόγους ποιεῖσθαι, αὐτὸν πρὸς αὑτόν, πρὸς ἕτερον ‘μή τι ἔχεις μοι πρὸς τοῦτο βοηθῆσαι;’ καὶ πάλιν ἄλλῳ","st":"3.24"},{"sp":"N","t":"προσελθεῖν καὶ ἄλλῳ. εἶτα ἄν τι γένηται τῶν λεγομένων ἀβουλήτων, εὐθὺς ἐκεῖνο πρῶτον ἐπικουφίσει σε, ὅτι οὐκ ἀπροσδόκητον.","st":"3.24"},{"sp":"N","t":"μέγα γὰρ ἐπὶ πάντων τὸ ‘ᾔδειν θνητὸν γεγεννηκώς.’ οὕτως γὰρ ἐρεῖς καὶ ὅτι ‘ᾔδειν θνητὸς ὤν,’ ‘ᾔδειν ἀποδημητικὸς ὤν,’ ‘ᾔδειν ἔκβλητος ὤν,’","st":"3.24"},{"sp":"N","t":"‘ᾔδειν εἰς φυλακὴν ἀπότακτος ὤν.’ εἶτ᾽ ἂν ἐπιστρέφῃς κατὰ σαυτὸν καὶ ζητήσῃς τὴν χώραν, ἐξ ἧς ἐστι τὸ συμβεβηκός, εὐθὺς ἀναμνησθήσῃ, ὅτι ‘ἐκ τῆς τῶν ἀπροαιρέτων, τῶν οὐκ ἐμῶν: τί οὖν πρὸς σἐμέ;’ εἶτα τὸ κυριώτατον","st":"3.24"},{"sp":"N","t":"‘τίς δ᾽ αὐτὸ καὶ ἐπιπέπομφεν;’ ὁ ἡγεμὼν ἢ ὁ στρατηγός, ἡ πόλις, ὁ τῆς πόλεως νόμος. ‘δὸς οὖν αὐτό: δεῖ γάρ με ἀιεὶ τῷ νόμῳ πείθεσθαι ἐν παντί.’","st":"3.24"},{"sp":"N","t":"εἶθ᾽ ὅταν σε ἡ φαντασία δάκνῃ （ τοῦτο γὰρ οὐκ ἐπὶ σοί ） , ἀναμάχου τῷ λόγῳ, καταγωνίζου αὐτήν, μὴ ἐάσῃς ἐνισχύειν μηδὲ προάγειν ἐπὶ τὰ ἑξῆς ἀναπλάσσουσαν ὅσα θέλει καὶ ὡς θέλει.","st":"3.24"},{"sp":"N","t":"ἂν ἐν Γυάροις ᾖς, μὴ ἀνάπλασσε τὴν ἐν Ῥώμῃ διατριβὴν καὶ ὅσαι διαχύσεις ἦσαν ἐκεῖ διάγοντι, ὅσαι γένοιντ᾽ ἂν ἐπανελθόντι: ἀλλ᾽ ἐκεῖ τέτασο, ὅπως δεῖ τὸν ἐν Γυάροις διάγοντα, ἐν Γυάροις ἐρρωμένως διάγειν. κἂν ἐν Ῥώμῃ ᾖς, μὴ ἀνάπλασσε τὴν ἐν Ἀθήναις διατριβήν, ἀλλὰ περὶ μόνης τῆς ἐκεῖ μελέτα.","st":"3.24"},{"sp":"N","t":"εἶτ᾽ ἀντὶ τῶν ἄλλων ἁπασῶν διαχύσεων ἐκείνην ἀντείσαγε, τὴν ἀπὸ τοῦ παρακολουθεῖν, ὅτι πείθῃ τῷ θεῷ, ὅτι οὐ λόγῳ, ἀλλ᾽ ἔργῳ τὰ τοῦ καλοῦ καὶ ἀγαθοῦ ἐκτελεῖς.","st":"3.24"},{"sp":"N","t":"οἷον γάρ ἐστιν αὐτὸν αὑτῷ δύνασθαι εἰπεῖν ‘νῦν ἃ οἱ ἄλλοι ἐν ταῖς σχολαῖς σεμνολογοῦσιν καὶ παραδοξολογεῖν δοκοῦσι, ταῦτα ἐγὼ ἐπιτελῶ: κἀκεῖνοι καθήμενοι τὰς ἐμὰς ἀρετὰς ἐξηγοῦνται καὶ περὶ ἐμοῦ ζητοῦσιν καὶ ἐμὲ ὑμνοῦσιν:","st":"3.24"},{"sp":"N","t":"καὶ τούτου με ὁ Ζεὺς αὐτὸν παρ᾽ ἐμαυτοῦ λαβεῖν ἀπόδειξιν ἠθέλησεν καὶ αὐτὸς δὲ γνῶναι, εἰ ἔχει στρατιώτην οἷον δεῖ, πολίτην οἷον δεῖ, καὶ τοῖς ἄλλοις ἀνθρώποις προάγειν με μάρτυρα τῶν ἀπροαιρέτων. ἴδετε, ὅτι εἰκῇ φοβεῖσθε, μάτην ἐπιθυμεῖτε ὧν ἐπιθυμεῖτε. τὰ ἀγαθὰ ἔξω μὴ ζητεῖτε, ἐν ἑαυτοῖς ζητεῖτε: εἰ δὲ μή, οὐχ εὑρήσετε.","st":"3.24"},{"sp":"N","t":"ἐπὶ τούτοις με νῦν μὲν ἐνταῦθα ἄγει, νῦν δ᾽ ἐκεῖ πέμπει, πένητα δείκνυσι τοῖς ἀνθρώποις, δίχα ἀρχῆς, νοσοῦντα: εἰς Γύαρα ἀποστέλλει, εἰς δεσμωτήριον εἰσάγει. οὐ μισῶν: μὴ γένοιτο: τίς δὲ μισεῖ τὸν ἄριστον τῶν ὑπηρετῶν τῶν ἑαυτοῦ; οὐδ᾽ ἀμελῶν, ὅς γε οὐδὲ τῶν μικροτάτων τινὸς ἀμελεῖ, ἀλλὰ γυμνάζων καὶ μάρτυρι πρὸς τοὺς ἄλλους χρώμενος.","st":"3.24"},{"sp":"N","t":"εἰς τοιαύτην ὑπηρεσίαν κατατεταγμένος ἔτι φροντίζω, ποῦ εἰμι ἢ μετὰ τίνων ἢ τί περὶ ἐμοῦ λέγουσιν; οὐχὶ δ᾽ ὅλος πρὸς τὸν θεὸν τέταμαι καὶ τὰς ἐκείνου ἐντολὰς καὶ τὰ προστάγματα;’","st":"3.24"},{"sp":"N","t":"ταῦτα ἔχων ἀεὶ ἐν χερσὶ καὶ τρίβων αὐτὸς παρὰ σαυτῷ καὶ πρόχειρα ποιῶν οὐδέποτε δεήσῃ τοῦ παραμυθουμένου, τοῦ ἐπιρρωννύντος.","st":"3.24"},{"sp":"N","t":"καὶ γὰρ αἰσχρὸν οὐ τὸ φαγεῖν μὴ ἔχειν, ἀλλὰ τὸ λόγον μὴ ἔχειν ἀρκοῦντα πρὸς ἀφοβίαν, πρὸς ἀλυπίαν.","st":"3.24"},{"sp":"N","t":"ἂν δ᾽ ἅπαξ περιποιήσῃ τὸ ἄλυπον καὶ ἄφοβον, ἔτι σοι τύραννος ἔσται τις ἢ δορυφόρος ἢ Καισαριανοὶ ἢ ὀρδινατίων δήξεταί σε ἢ οἱ ἐπιθύοντες ἐν τῷ Καπιτωλίῳ ἐπὶ τοῖς ὀπτικίοις τὸν τηλικαύτην ἀρχὴν παρὰ τοῦ Διὸς εἰληφότα;","st":"3.24"},{"sp":"N","t":"μόνον μὴ πόμπευε αὐτὴν μηδ᾽ ἀλαζονεύου ἐπ᾽ αὐτῇ, ἀλλ᾽ ἔργῳ δείκνυε: κἂν μηδεὶς αἰσθάνηται, ἀρκοῦ αὐτὸς ὑγιαίνων καὶ εὐδαιμονῶν. πρὸς τοὺς ἀποπίπτοντας ὧν προέθεντο. σκέψαι, ὧν προέθου ἀρχόμενος, τίνων μὲν ἐκράτησας, τίνων δ᾽ οὔ, καὶ πῶς ἐφ᾽ οἷς μὲν εὐφραίνῃ ἀναμιμνῃσκόμενος, ἐφ᾽ οἷς δ᾽ ἄχθῃ, καὶ εἰ δυνατόν, ἀνάλαβε κἀκεῖνα ὧν ἀπώλισθες.","st":"3.24"},{"sp":"N","t":"οὐ γὰρ ἀποκνητέον τὸν ἀγῶνα τὸν μέγιστον ἀγωνιζομένοις, ἀλλὰ καὶ πληγὰς ληπτέον:","st":"3.25"},{"sp":"N","t":"οὐ γὰρ ὑπὲρ πάλης καὶ παγκρατίου ὁ ἀγὼν πρόκειται, οὗ καὶ τυχόντι καὶ μὴ τυχόντι ἔξεστιν μὲν πλείστου ἀξίῳ, ἔξεστι δὲ ὀλίγου εἶναι καὶ νὴ Δία ἔξεστιν μὲν εὐτυχεστάτῳ, ἔξεστι δὲ κακοδαιμονεστάτῳ εἶναι, ἀλλ᾽ ὑπὲρ αὐτῆς εὐτυχίας καὶ εὐδαιμονίας.","st":"3.25"},{"sp":"N","t":"τί οὖν; οὐδ᾽ ἂν ἀπαυδήσωμεν ἐνταῦθα, κωλύει τις πάλιν ἀγωνίζεσθαι οὐδὲ δεῖ περιμεῖναι τετραετίαν ἄλλην, ἵν᾽ ἔλθῃ ἄλλα Ὀλύμπια, ἀλλ᾽ εὐθὺς ἀναλαβόντι καὶ ἀνακτησαμένῳ ἑαυτὸν καὶ τὴν αὐτὴν εἰσφέροντι προθυμίαν ἔξεστιν ἀγωνίζεσθαι: κἂν πάλιν ἀπείπῃς, πάλιν ἔξεστιν, κἂν ἅπαξ νικήσῃς, ὅμοιος εἶ τῷ μηδέποτε ἀπειπόντι.","st":"3.25"},{"sp":"N","t":"μόνον μὴ ὑπὸ ἔθους τοῦ αὐτοῦ ἡδέως αὐτὸ ἄρξῃ ποιεῖν: καὶ λοιπὸν ὡς κακὸς ἀθλητὴς περιέρχῃ νικώμενος τὴν περίοδον ὅμοιος τοῖς ἀποφυγοῦσιν ὄρτυξιν.","st":"3.25"},{"sp":"N","t":"‘ἡττᾷ με φαντασία παιδισκαρίου καλοῦ. τί γάρ; πρῴην οὐχ ἡττήθην;’ ‘προθυμία μοι γίνεται ψέξαι τινά. πρῴην γὰρ οὐκ ἔψεξα;’","st":"3.25"},{"sp":"N","t":"οὕτως ἡμῖν λαλεῖς ὡς ἀζήμιος ἐξεληλυθώς, οἱονεί τις τῷ ἰατρῷ κωλύοντι λούσασθαι λέγοι ‘πρῴην γὰρ οὐκ ἐλουσάμην;’ ἂν οὖν ὁ ἰατρὸς αὐτῷ ἔχῃ λέγειν ‘ἄγε, λουσάμενος οὖν τί ἔπαθες; οὐκ ἐπύρεξας;","st":"3.25"},{"sp":"N","t":"οὐκ ἐκεφαλάλγησας;’ καὶ σὺ ψέξας πρῴην τινὰ οὐ κακοήθους ἔργον ἔπραξας; οὐ φλυάρου; οὐκ ἔθρεψάς σου τὴν ἕξιν ταύτην παραβάλλων αὐτῇ τὰ οἰκεῖα ἔργα; ἡττηθεὶς δὲ τοῦ παιδισκαρίου ἀπῆλθες ἀζήμιος; τί οὖν τὰ πρῴην λέγεις;","st":"3.25"},{"sp":"N","t":"ἔδει δ᾽ οἶμαι μεμνημένον, ὡς οἱ δοῦλοι τῶν πληγῶν, ἀπέχεσθαι τῶν αὐτῶν ἁμαρτημάτων.","st":"3.25"},{"sp":"N","t":"ἀλλ᾽ οὐχ ὅμοιον: ἐνταῦθα μὲν γὰρ ὁ πόνος τὴν μνήμην ποιεῖ, ἐπὶ δὲ τῶν ἁμαρτημάτων ποῖος πόνος, ποία ζημία; πότε γὰρ εἰθίσθης φεύγειν τὸ κακῶς ἐνεργῆσαι; πρὸς τοὺς τὴν ἀπορίαν δεδοικότας. οὐκ αἰσχύνῃ δειλότερος ὢν καὶ ἀγεννέστερος τῶν δραπετῶν; πῶς ἐκεῖνοι φεύγοντες ἀπολείπουσι τοὺς δεσπότας, ποίοις ἀγροῖς πεποιθότες, ποίοις οἰκέταις; οὐχὶ δ᾽ ὀλίγον ὅσον πρὸς τὰς πρώτας ἡμέρας ὑφελόμενοι εἶθ᾽ ὕστερον διὰ γῆς ἢ καὶ θαλάττης φέρονται ἄλλην ἐξ ἄλλης ἀφορμὴν πρὸς τὸ διατρέφεσθαι φιλοτεχνοῦντες;","st":"3.25"},{"sp":"N","t":"καὶ τίς πώποτε δραπέτης λιμῷ ἀπέθανεν; σὺ δὲ τρέμεις, μή σοι λείπῃ τὰ ἀναγκαῖα, καὶ τὰς νύκτας ἀγρυπνεῖς.","st":"3.26"},{"sp":"N","t":"ταλαίπωρε, οὕτως τυφλὸς εἶ καὶ τὴν ὁδὸν οὐχ ὁρᾷς, ὅποι φέρει ἡ τῶν ἀναγκαίων ἔνδεια; ποῦ γὰρ φέρει; ὅπου καὶ ὁ πυρετός, ὅπου καὶ λίθος ἐπιπεσών, εἰς θάνατον. τοῦτον οὖν οὐ πολλάκις σὺ αὐτὸς εἶπες πρὸς τοὺς ἑταίρους, πολλὰ δ᾽ ἀνέγνως τοιαῦτα, πολλὰ δ᾽ ἔγραφες; ποσάκις δ᾽ ἠλαζονεύσω, ὅτι πρός γε τὸ ἀποθανεῖν μετρίως ἔχεις;","st":"3.26"},{"sp":"N","t":"— ναί: ἀλλὰ καὶ οἱ ἐμοὶ πεινήσουσιν. — τί οὖν; μή τι καὶ ὁ ἐκείνων λιμὸς ἀλλαχοῦ που φέρει; οὐχὶ καὶ ἡ αὐτή που κάθοδος;","st":"3.26"},{"sp":"N","t":"τὰ κάτω τὰ αὐτά; οὐ θέλεις οὖν ἐκεῖ βλέπειν θαρρῶν πρὸς πᾶσαν ἀπορίαν καὶ ἔνδειαν, ὅπου καὶ τοὺς πλουσιωτάτους καὶ τὰς ἀρχὰς τὰς μεγίστας ἄρξαντας καὶ αὐτοὺς τοὺς βασιλεῖς καὶ τυράννους δεῖ κατελθεῖν, καὶ σὲ πεινῶντα, ἂν οὕτως τύχῃ, ἐκείνους δὲ διαρραγέντας ὑπὸ ἀπεψιῶν καὶ μέθης;","st":"3.26"},{"sp":"N","t":"τίνα πώποτ᾽ ἐπαίτην ῥᾳδίως εἶδες μὴ γέροντα; τίνα δ᾽ οὐκ ἐσχατόγηρων; ἀλλὰ ῥιγῶντες τὰς νύκτας καὶ τὰς ἡμέρας καὶ χαμαὶ ἐρριμμένοι καὶ ὅσον αὐτὸ τὸ ἀναγκαῖον σιτούμενοι ἐγγὺς ἥκουσιν τῷ μηδ᾽ ἀποθανεῖν δύνασθαι,","st":"3.26"},{"sp":"N","t":"σὺ δ᾽ ὁλόκληρος ἄνθρωπος χεῖρας ἔχων καὶ πόδας περὶ λιμοῦ δέδοικας οὕτως; οὐκ ἀντλεῖν δύνασθαι, οὐ γράφειν, οὐ παιδαγωγεῖν, οὐ θύραν ἀλλοτρίαν φυλάττειν; — ἀλλ᾽ αἰσχρὸν εἰς ταύτην ἐλθεῖν τὴν ἀνάγκην. — μάθε οὖν πρῶτον, τίνα τὰ αἰσχρά ἐστιν, καὶ οὕτως ἡμῖν λέγε σαυτὸν φιλόσοφον. τὸ νῦν δὲ μηδ᾽ ἂν ἄλλος τις εἴπῃ σε, ἀνέχου.","st":"3.26"},{"sp":"N","t":"αἰσχρόν ἐστί σοι τὸ μὴ σὸν ἔργον, οὗ σὺ αἴτιος οὐκ εἶ, ὃ ἄλλως ἀπήντησέν σοι, ὡς κεφαλαλγία, ὡς πυρετός; εἴ σου οἱ γονεῖς πένητες ἦσαν ἢ πλούσιοι μὲν ἦσαν, ἄλλους δὲ κληρονόμους ἀπέλιπον καὶ ζῶντες οὐκ ἐπαρκοῦσιν οὐδέν, σοὶ ταῦτα αἰσχρά ἐστιν;","st":"3.26"},{"sp":"N","t":"ταῦτα ἐμάνθανες παρὰ τοῖς φιλοσόφοις; οὐδέποτε ἤκουσας, ὅτι τὸ αἰσχρὸν ψεκτόν ἐστιν, τὸ δὲ ψεκτὸν ἄξιόν ἐστι τοῦ ψέγεσθαι; † τίνα ἐπὶ τῷ μὴ αὑτοῦ ἔργῳ, ὃ αὐτὸς οὐκ ἐποίησεν;","st":"3.26"},{"sp":"N","t":"σὺ οὖν ἐποίησας τοῦτο, τὸν πατέρα τοιοῦτον; ἢ ἔξεστίν σοι ἐπανορθῶσαι αὐτόν; δίδοταί σοι τοῦτο; τί οὖν; δεῖ σε θέλειν τὰ μὴ διδόμενα ἢ μὴ τυγχάνοντα αὐτῶν αἰσχύνεσθαι;","st":"3.26"},{"sp":"N","t":"οὕτως δὲ καὶ εἰθίζου φιλοσοφῶν ἀφορᾶν εἰς ἄλλους καὶ μηδὲν αὐτὸς ἐλπίζειν ἐκ σεαυτοῦ;","st":"3.26"},{"sp":"N","t":"τοιγαροῦν οἴμωζε καὶ στένε καὶ ἔσθιε δεδοικώς, μὴ οὐ σχῇς τροφὰς αὔριον: περὶ τῶν δουλαρίων τρέμε, μὴ κλέψῃ τι, μὴ φύγῃ, μὴ ἀποθάνῃ.","st":"3.26"},{"sp":"N","t":"οὕτως σὺ ζῆθι καὶ μὴ παύσῃ μηδέποτε, ὅστις ὀνόματι μόνον πρὸς φιλοσοφίαν προσῆλθες καὶ τὰ θεωρήματα αὐτῆς ὅσον ἐπὶ σοὶ κατῄσχυνας ἄχρηστα ἐπιδείξας καὶ ἀνωφελῆ τοῖς ἀναλαμβάνουσιν: οὐδέποτε δ᾽ εὐσταθείας ὠρέχθης, ἀταραξίας, ἀπαθείας: οὐδένα τούτου ἕνεκα ἐθεράπευσας, συλλογισμῶν δ᾽ ἕνεκα πολλούς: οὐδέποτε τούτων τινὰ τῶν φαντασιῶν διεβασάνισας αὐτὸς ἐπὶ σεαυτοῦ ‘δύναμαι φέρειν ἢ οὐ δύναμαι;","st":"3.26"},{"sp":"N","t":"τί μοι τὸ λοιπόν ἐστιν;,’ ἀλλ᾽ ὡς πάντων ἐχόντων σοι καλῶς καὶ ἀσφαλῶς περὶ τὸν τελευταῖον κατεγίνου τόπον, τὸν τῆς ἀμεταπτωσίας, ἵν᾽ ἀμετάπτωτα σχῇς τίνα; τὴν δειλίαν, τὴν ἀγέννειαν, τὸν θαυμασμὸν τῶν πλουσίων, τὴν ἀτελῆ ὄρεξιν, τὴν † ἀποτευκτικὴν ἔκκλισιν: περὶ τῆς τούτων ἀσφαλείας ἐφρόντιζες.","st":"3.26"},{"sp":"N","t":"οὐκ ἔδει προσκτήσασθαι πρῶτον ἐκ τοῦ λόγου, εἶτα τούτῳ περιποιεῖν τὴν ἀσφάλειαν; καὶ τίνα πώποτ᾽ εἶδες τριγχὸν περιοικοδομοῦντα μηδενὶ † τειχίον περιβαλλόμενον αὐτὸ αὐτοῦ; ποῖος δὲ θυρωρὸς καθίσταται ἐπὶ οὐδεμιᾷ θύρᾳ;","st":"3.26"},{"sp":"N","t":"ἀλλὰ σὺ μελετᾷς ἀποδεικνύειν δύνασθαι: τίνα; μελετᾷς μὴ ἀποσαλεύεσθαι διὰ σοφισμάτων: ἀπὸ τίνων;","st":"3.26"},{"sp":"N","t":"δεῖξόν μοι πρῶτον, τί τηρεῖς, τί μετρεῖς ἢ τί ἱστάνεις: εἶθ᾽ οὕτως ἐπιδείκνυε τὸν ζυγὸν ἢ τὸν μέδιμνον.","st":"3.26"},{"sp":"N","t":"ἢ μέχρι τίνος μετρήσεις τὴν σποδόν; οὐ ταῦτά σε ἀποδεικνύειν δεῖ, ἃ ποιεῖ τοὺς ἀνθρώπους εὐδαίμονας, ἃ ποιεῖ προχωρεῖν αὐτοῖς τὰ πράγματα ὡς θέλουσιν, δι᾽ ἃ οὐ δεῖ μέμφεσθαι οὐδενί, ἐγκαλεῖν οὐδενί, πείθεσθαι τῇ διοικήσει τῶν ὅλων; ταῦτά μοι δείκνυε.","st":"3.26"},{"sp":"N","t":"‘ἰδοὺ δεικνύω,’ φησίν, ‘ἀναλύσω σοι συλλογισμούς.’ τοῦτο τὸ μετροῦν ἐστιν, ἀνδράποδον: τὸ μετρούμενον δ᾽ οὐκ ἔστιν.","st":"3.26"},{"sp":"N","t":"διὰ ταῦτα νῦν τίνεις δίκας ὧν ἠμέλησας φιλοσοφίας: τρέμεις, ἀγρυπνεῖς, μετὰ πάντων βουλεύῃ: κἂν μὴ πᾶσιν ἀρέσκειν μέλλῃ τὰ βουλεύματα, κακῶς οἴει βεβουλεῦσθαι.","st":"3.26"},{"sp":"N","t":"εἶτα φοβῇ λιμόν, ὡς δοκεῖς. σὺ δ᾽ οὐ λιμὸν φοβῇ, ἀλλὰ δέδοικας μὴ οὐ σχῇς μάγειρον, μὴ οὐ σχῇς ἄλλον ὀψωνητήν, ἄλλον τὸν ὑποδήσοντα, ἄλλον τὸν ἐνδύσοντα, ἄλλους τοὺς τρίψοντας, ἄλλους τοὺς ἀκολουθήσοντας,","st":"3.26"},{"sp":"N","t":"ἵν᾽ ἐν τῷ βαλανείῳ ἐκδυσάμενος καὶ ἐκτείνας σεαυτὸν ὡς οἱ ἐσταυρωμένοι τρίβῃ ἔνθεν καὶ ἔνθεν, εἶθ᾽ ὁ ἀλείπτης ἐπιστὰς λέγῃ ‘μετάβηθι, δὸς πλευρόν, κεφαλὴν αὐτοῦ λάβε, παράθες τὸν ὦμον,’ εἶτ᾽ ἐλθὼν ἐκ τοῦ βαλανείου εἰς οἶκον κραυγάσῃς ‘οὐδεὶς φέρει φαγεῖν;’","st":"3.26"},{"sp":"N","t":", εἶτ᾽ ‘ἆρον τὰς τραπέζας,’ ‘σπόγγισον.’ τοῦτο φοβῇ, μὴ οὐ δύνῃ ζῆν ἀρρώστου βίον, ἐπεί τοι τὸν τῶν ὑγιαινόντων μάθε, πῶς οἱ δοῦλοι ζῶσιν, πῶς οἱ ἐργάται, πῶς οἱ γνησίως φιλοσοφοῦντες, πῶς Σωκράτης ἔζησεν, ἐκεῖνος μὲν καὶ μετὰ γυναικὸς καὶ παίδων, πῶς Διογένης, πῶς Κλεάνθης ἅμα σχολάζων καὶ ἀντλῶν.","st":"3.26"},{"sp":"N","t":"ταῦτα ἂν θέλῃς ἔχειν, ἕξεις πανταχοῦ καὶ ζήσεις θαρρῶν. τίνι; ᾧ μόνῳ θαρρεῖν ἐνδέχεται, τῷ πιστῷ, τῷ ἀκωλύτῳ, τῷ ἀναφαιρέτῳ, τοῦτ᾽ ἔστι τῇ προαιρέσει τῇ σεαυτοῦ.","st":"3.26"},{"sp":"N","t":"διὰ τί δ᾽ οὕτως ἄχρηστον καὶ ἀνωφελῆ σαυτὸν παρεσκεύακας, ἵνα μηδείς σε εἰς οἰκίαν θέλῃ δέξασθαι, μηδεὶς ἐπιμεληθῆναι; ἀλλὰ σκεῦος μὲν ὁλόκληρον καὶ χρήσιμον ἔξω ἐρριμμένον πᾶς τις εὑρὼν ἀναιρήσεται καὶ κέρδος ἡγήσεται, σὲ δ᾽ οὐδείς, ἀλλὰ πᾶς ζημίαν.","st":"3.26"},{"sp":"N","t":"οὕτως οὐδὲ κυνὸς δύνασαι χρείαν παρασχεῖν οὐδ᾽ ἀλεκτρυόνος. τί οὖν ἔτι ζῆν θέλεις τοιοῦτος ὤν;","st":"3.26"},{"sp":"N","t":"φοβεῖταί τις ἀνὴρ ἀγαθός, μὴ λείπωσιν αὐτῷ τροφαί; τοῖς τυφλοῖς οὐ λείπουσι, τοῖς χωλοῖς οὐ λείπουσι: λείψουσιν ἀνδρὶ ἀγαθῷ; καὶ στρατιώτῃ μὲν ἀγαθῷ οὐ λείπει ὁ μισθοδοτῶν οὐδ᾽ ἐργάτῃ οὐδὲ σκυτεῖ: τῷ δ᾽ ἀγαθῷ λείψει;","st":"3.26"},{"sp":"N","t":"οὕτως ὁ θεὸς ἀμελεῖ τῶν αὑτοῦ ἐπιτευγμάτων, τῶν διακόνων, τῶν μαρτύρων, οἷς μόνοις χρῆται παραδείγμασιν πρὸς τοὺς ἀπαιδεύτους, ὅτι καὶ ἔστι καὶ καλῶς διοικεῖ τὰ ὅλα καὶ οὐκ ἀμελεῖ τῶν ἀνθρωπίνων πραγμάτων καὶ ὅτι ἀνδρὶ ἀγαθῷ οὐδέν ἐστι κακὸν οὔτε ζῶντι οὔτ᾽ ἀποθανόντι;","st":"3.26"},{"sp":"N","t":"— τί οὖν, ὅταν μὴ παρέχῃ τροφάς; — τί γὰρ ἄλλο ἢ ὡς ἀγαθὸς στρατηγὸς τὸ ἀνακλητικόν μοι σεσήμαγκεν; πείθομαι, ἀκολουθῶ, ἐπευφημῶν τὸν ἡγεμόνα, ὑμνῶν αὐτοῦ τὰ ἔργα.","st":"3.26"},{"sp":"N","t":"καὶ γὰρ ἦλθον, ὅτ᾽ ἐκείνῳ ἔδοξεν, καὶ ἄπειμι πάλιν ἐκείνῳ δοκοῦν καὶ ζῶντός μου τοῦτο τὸ ἔργον ἦν, ὑμνεῖν τὸν θεὸν καὶ αὐτὸν ἐπ᾽ ἐμαυτοῦ καὶ πρὸς ἕνα καὶ πρὸς πολλούς.","st":"3.26"},{"sp":"N","t":"οὐ παρέχει μοι πολλά, οὐκ ἄφθονα, τρυφᾶν με οὐ θέλει οὐδὲ γὰρ τῷ Ἡρακλεῖ παρεῖχεν, τῷ υἱεῖ τῷ ἑαυτοῦ, ἀλλ᾽ ἄλλος ἐβασίλευεν Ἄργους καὶ Μυκηνῶν, ὁ δ᾽ ἐπετάσσετο καὶ ἐπόνει καὶ ἐγυμνάζετο.","st":"3.26"},{"sp":"N","t":"καὶ ἦν Εὐρυσθεὺς μέν, ὃς ἦν, οὔτε Ἄργους οὔτε Μυκηνῶν βασιλεύς, ὅς γ᾽ οὐδ᾽ αὐτὸς ἑαυτοῦ, ὁ δ᾽ Ἡρακλῆς ἁπάσης γῆς καὶ θαλάττης ἄρχων καὶ ἡγεμὼν ἦν, καθαρτὴς ἀδικίας καὶ ἀνομίας, εἰσαγωγεὺς δὲ δικαιοσύνης καὶ ὁσιότητος: καὶ ταῦτα ἐποίει καὶ γυμνὸς καὶ μόνος.","st":"3.26"},{"sp":"N","t":"ὁ δ᾽ Ὀδυσσεὺς ὅτε ναυαγὸς ἐξερρίφη, μή τι ἐταπείνωσεν αὐτὸν ἡ ἀπορία, μή τι ἐπέκλασεν; ἀλλὰ πῶς ἀπῄει πρὸς τὰς παρθένους αἰτήσων τὰ ἀναγκαῖα, ὧν αἴσχιστον εἶναι δοκεῖ δεῖσθαι παρ᾽ ἄλλου; ὥς τε λέων ὀρεσίτροφος. τίνι πεποιθώς;","st":"3.26"},{"sp":"N","t":"οὐ δόξῃ οὐδὲ χρήμασιν οὐδ᾽ ἀρχαῖς, ἀλλ᾽ ἀλκῇ τῇ ἑαυτοῦ, τοῦτ᾽ ἔστι δόγμασι περὶ τῶν ἐφ᾽ ἡμῖν καὶ οὐκ ἐφ᾽ ἡμῖν.","st":"3.26"},{"sp":"N","t":"ταῦτα γάρ ἐστι μόνα τὰ τοὺς ἐλευθέρους ποιοῦντα, τὰ τοὺς ἀκωλύτους, τὰ τὸν τράχηλον ἐπαίροντα τῶν τεταπεινομένων, τὰ ἀντιβλέπειν ποιοῦντα ὀρθοῖς τοῖς ὀφθαλμοῖς πρὸς τοὺς πλουσίους, πρὸς τοὺς τυράννους.","st":"3.26"},{"sp":"N","t":"καὶ τὸ τοῦ φιλοσόφου δῶρον τοῦτο ἦν, σὺ δ᾽ οὐκ ἐξελεύσῃ θαρρῶν, ἀλλὰ περιτρέμων τοῖς ἱματιδίοις καὶ τοῖς ἀργυρωματίοις; δύστηνε, οὕτως ἀπώλεσας τὸν μέχρι νῦν χρόνον; τί οὖν, ἂν νοσήσω;","st":"3.26"},{"sp":"N","t":"— νοσήσεις καλῶς. — τίς με θεραπεύσει; — ὁ θεός, οἱ φίλοι. — σκληρῶς κατακείσομαι. — ἀλλ᾽ ὡς ἀνήρ. — οἴκημα ἐπιτήδειον οὐχ ἕξω. — ἐν ἐπιτηδείῳ οὐ νοσήσεις; — τίς μοι ποιήσει τὰ τροφεῖα; — οἱ καὶ τοῖς ἄλλοις ποιοῦντες: ὡς Μάνης νοσήσεις. — τί δὲ καὶ τὸ πέρας τῆς νόσου;","st":"3.26"},{"sp":"N","t":"— ἄλλο τι ἢ θάνατος; ἆρ᾽ οὖν ἐνθυμῇ, ὅτι κεφάλαιον τοῦτο πάντων τῶν κακῶν τῷ ἀνθρώπῳ καὶ ἀγεννείας καὶ δειλίας οὐ θάνατός ἐστιν, μᾶλλον δ᾽ ὁ τοῦ θανάτου φόβος;","st":"3.26"},{"sp":"N","t":"ἐπὶ τοῦτον οὖν μοι γυμνάζου, ἐνταῦθα νευέτωσαν οἱ λόγοι πάντες, τὰ ἀσκήματα, τὰ ἀναγνώσματα, καὶ εἴσῃ, ὅτι οὕτως μόνως ἐλευθεροῦνται ἄνθρωποι.","st":"3.26"},{"sp":"HDR","t":"Βιβλίον δʹ","st":"4.1"},{"sp":"N","t":"τίς οὖν θέλει ζῆν ἁμαρτάνων; — οὐδείς. — τίς θέλει ζῆν ἐξαπατώμενος, προπίπτων, ἄδικος ὤν, ἀκόλαστος, μεμψίμοιρος, ταπεινός;","st":"4.1"},{"sp":"N","t":"— οὐδείς. — οὐδεὶς ἄρα τῶν φαύλων ζῇ ὡς βούλεται: οὐ τοίνυν οὐδ᾽ ἐλεύθερός ἐστιν.","st":"4.1"},{"sp":"N","t":"τίς δὲ θέλει λυπούμενος ζῆν, φοβούμενος, φθονῶν, ἐλεῶν, ὀρεγόμενος καὶ ἀποτυγχάνων, ἐκκλίνων καὶ περιπίπτων;","st":"4.1"},{"sp":"N","t":"— οὐδὲ εἷς. — ἔχομεν οὖν τινα τῶν φαύλων ἄλυπον, ἄφοβον, ἀπερίπτωτον, ἀναπότευκτον; — οὐδένα. — οὐκ ἄρα οὐδὲ ἐλεύθερον.","st":"4.1"},{"sp":"N","t":"ταῦτα ἄν τις ἀκούσῃ δισύπατος, ἂν μὲν προσθῇς ὅτι ‘ἀλλὰ σύ γε σοφὸς εἶ, οὐδὲν πρὸς σὲ ταῦτα,’ συγγνώσεταί σοι.","st":"4.1"},{"sp":"N","t":"ἂν δ᾽ αὐτῷ τὰς ἀληθείας εἴπῃς ὅτι ‘τῶν τρὶς πεπραμένων οὐδὲν διαφέρεις πρὸς τὸ μὴ καὶ αὐτὸς δοῦλος εἶναι,’ τί ἄλλο ἢ πληγάς σε δεῖ προσδοκᾶν;","st":"4.1"},{"sp":"N","t":"‘πῶς γάρ,’ φησίν, ‘ἐγὼ δοῦλός εἰμι; ὁ πατὴρ ἐλεύθερος, ἡ μήτηρ ἐλευθέρα, οὗ ὠνὴν οὐδεὶς ἔχει: ἀλλὰ καὶ συγκλητικός εἰμι καὶ Καίσαρος φίλος καὶ ὑπάτευκα καὶ δούλους πολλοὺς ἔχω.’","st":"4.1"},{"sp":"N","t":"πρῶτον μέν, ὦ βέλτιστε συγκλητικέ, τάχα σου καὶ ὁ πατὴρ τὴν αὐτὴν δουλείαν δοῦλος ἦν καὶ ἡ μήτηρ καὶ ὁ πάππος καὶ ἐφεξῆς πάντες οἱ πρόγονοι.","st":"4.1"},{"sp":"N","t":"εἰ δὲ δὴ καὶ τὰ μάλιστα ἦσαν ἐλεύθεροι, τί τοῦτο πρὸς σέ; τί γάρ, εἰ ἐκεῖνοι μὲν γενναῖοι ἦσαν, σὺ δ᾽ ἀγεννής; ἐκεῖνοι μὲν ἄφοβοι, σὺ δὲ δειλός; ἐκεῖνοι μὲν ἐγκρατεῖς, σὺ δ᾽ ἀκόλαστος; καὶ τί, φησί, τοῦτο πρὸς τὸ δοῦλον εἶναι;","st":"4.1"},{"sp":"N","t":"— οὐδέν σοι φαίνεται εἶναι τὸ ἄκοντά τι ποιεῖν, τὸ ἀναγκαζόμενον, τὸ στένοντα πρὸς τὸ δοῦλον εἶναι;","st":"4.1"},{"sp":"N","t":"— τοῦτο μὲν ἔστω, φησίν. ἀλλὰ τίς με δύναται ἀναγκάσαι, εἰ μὴ ὁ πάντων κύριος Καῖσαρ;","st":"4.1"},{"sp":"N","t":"— οὐκοῦν ἕνα μὲν δεσπότην σαυτοῦ καὶ σὺ αὐτὸς ὡμολόγησας. ὅτι δὲ πάντων, ὡς λέγεις, κοινός ἐστιν, μηδέν σε τοῦτο παραμυθείσθω, ἀλλὰ γίγνωσκε, ὅτι ἐκ μεγάλης οἰκίας δοῦλος εἶ.","st":"4.1"},{"sp":"N","t":"οὕτως καὶ Νικοπολῖται ἐπιβοᾶν εἰώθασι ‘νὴ τὴν Καίσαρος τύχην, ἐλεύθεροί ἐσμεν.’","st":"4.1"},{"sp":"N","t":"ὅμως δ᾽, ἐάν σοι δοκῇ, τὸν μὲν Καίσαρα πρὸς τὸ παρὸν ἀφῶμεν, ἐκεῖνο δέ μοι εἰπέ: οὐδέποτ᾽ ἠράσθης τινός; οὐ παιδισκαρίου, οὐ παιδαρίου, οὐ δούλου, οὐκ ἐλευθέρου;","st":"4.1"},{"sp":"N","t":"— τί οὖν τοῦτο πρὸς τὸ δοῦλον εἶναι ἢ ἐλεύθερον;","st":"4.1"},{"sp":"N","t":"— οὐδέποθ᾽ ὑπὸ τῆς ἐρωμένης ἐπετάγης οὐδὲν ὧν οὐκ ἤθελες; οὐδέποτέ σου τὸ δουλάριον ἐκολάκευσας; οὐδέποτ᾽ αὐτοῦ τοὺς πόδας κατεφίλησας; καίτοι τοῦ Καίσαρος ἄν σέ τις ἀναγκάσῃ, ὕβριν αὐτὸ ἡγῇ καὶ ὑπερβολὴν τυραννίδος.","st":"4.1"},{"sp":"N","t":"τί οὖν ἄλλο ἐστὶ δουλεία; νυκτὸς οὐδέποτ᾽ ἀπῆλθες, ὅπου οὐκ ἤθελες; ἀνάλωσας, ὅσα οὐκ ἤθελες; εἶπάς τινα οἰμώζων καὶ στένων, ἠνέσχου λοιδορούμενος, ἀποκλειόμενος;","st":"4.1"},{"sp":"N","t":"ἀλλ᾽ εἰ σὺ αἰσχύνῃ τὰ σαυτοῦ ὁμολογεῖν, ὅρα ἃ λέγει καὶ ποιεῖ ὁ Θρασωνίδης, ὃς τοσαῦτα στρατευσάμενος, ὅσα τάχα οὐδὲ σύ, πρῶτον μὲν ἐξελήλυθε νυκτός, ὅτε ὁ Γέτας οὐ τολμᾷ ἐξελθεῖν, ἀλλ᾽ εἰ προσηναγκάζετο ὑπ᾽ αὐτοῦ, πόλλ᾽ ἂν ἐπικραυγάσας καὶ τὴν πικρὰν δουλείαν ἀπολοφυράμενος ἐξῆλθεν.","st":"4.1"},{"sp":"N","t":"εἶτα, τί λέγει; παιδισκάριόν με, φησίν, καταδεδούλωκ᾽ εὐτελές, ὃν οὐδὲ εἷς τῶν πολεμίων οὐπώποτε. τάλας,","st":"4.1"},{"sp":"N","t":"ὅς γε καὶ παιδισκαρίου δοῦλος εἶ καὶ παιδισκαρίου εὐτελοῦς. τί οὖν ἔτι σαυτὸν ἐλεύθερον λέγεις; τί δὲ προφέρεις σου τὰς στρατε","st":"4.1"},{"sp":"N","t":"ίας; εἶτα ξίφος αἰτεῖ καὶ πρὸς τὸν ὑπ᾽ εὐνοίας μὴ διδόντα χαλεπαίνειν καὶ δῶρα τῇ μισούσῃ πέμπει καὶ δεῖται καὶ κλαίει, πάλιν δὲ μικρὰ εὐημερήσας ἐπαίρεται: πλὴν καὶ τότε πῶς;","st":"4.1"},{"sp":"N","t":"† μηδ᾽ ἐπιθυμεῖν ἢ φοβεῖσθαι οὔτ᾽ ἐλευθερίαν †.","st":"4.1"},{"sp":"N","t":"σκέψαι δ᾽ ἐπὶ τῶν ζῴων, πῶς χρώμεθα τῇ ἐννοίᾳ τῆς ἐλευθερίας.","st":"4.1"},{"sp":"N","t":"λέοντας τρέφουσιν ἡμέρους ἐγκλείσαντες καὶ σιτίζουσι καὶ κομίζουσιν ἔνιοι μεθ᾽ αὑτῶν. καὶ τίς ἐρεῖ τοῦτον τὸν λέοντα ἐλεύθερον; οὐχὶ δ᾽ ὅσῳ μαλακώτερον διεξάγει, τοσούτῳ δουλικώτερον; τίς δ᾽ ἂν λέων αἴσθησιν καὶ λογισμὸν λαβὼν βούλοιτο τούτων τις εἶναι τῶν λεόντων;","st":"4.1"},{"sp":"N","t":"ἄγε, τὰ δὲ πτηνὰ ταῦτα ὅταν ληφθῇ καὶ ἐγκεκλειμένα τρέφηται, οἷα πάσχει ζητοῦντα ἐκφυγεῖν; καὶ ἔνιά γε αὐτῶν λιμῷ διαφθείρεται μᾶλλον ἢ ὑπομένει τὴν τοιαύτην διεξαγωγήν,","st":"4.1"},{"sp":"N","t":"ὅσα δ᾽ οὖν διασῴζεται, μόγις καὶ χαλεπῶς καὶ φθίνοντα, κἂν ὅλως εὕρῃ τι παρεῳγμένον, ἐξεπήδησεν. οὕτως ὀρέγεται τῆς φυσικῆς ἐλευθερίας καὶ τοῦ αὐτόνομα καὶ ἀκώλυτα εἶναι.","st":"4.1"},{"sp":"N","t":"καὶ τί σοι κακόν ἐστιν ἐνταῦθα; ‘οἷα λέγεις; πέτεσθαι πέφυκα ὅπου θέλω, ὕπαιθρον διάγειν, ᾁδειν ὅταν θέλω: σύ με πάντων τούτων ἀφαιρῇ καὶ λέγεις ‘τί σοι κακόν ἐστιν;’","st":"4.1"},{"sp":"N","t":"διὰ τοῦτο ἐκεῖνα μόνα ἐροῦμεν ἐλεύθερα, ὅσα τὴν ἅλωσιν οὐ φέρει, ἀλλ᾽ ἅμα τε ἑάλω καὶ ἀποθανόντα διέφυγεν.","st":"4.1"},{"sp":"N","t":"οὕτως καὶ Διογένης που λέγει μίαν εἶναι μηχανὴν πρὸς ἐλευθερίαν τὸ εὐκόλως ἀποθνῄσκειν, καὶ τῷ Περσῶν βασιλεῖ γράφει ὅτι ‘τὴν Ἀθηναίων πόλιν καταδουλώσασθαι οὐ δύνασαι: οὐ μᾶλλον,’ φησίν, ‘ἢ τοὺς ἰχθύας.’","st":"4.1"},{"sp":"N","t":"‘πῶς; οὐ γὰρ λήψομαι αὐτούς;’ ‘ἂν λάβῃς,’ φησίν, ‘εὐθὺς ἀπολιπόντες σε οἰχήσονται, καθάπερ οἱ ἰχθύες.’ καὶ γὰρ ἐκείνων ὃν ἂν λάβῃς, ἀπέθανεν: καὶ οὗτοι ληφθέντες ἐὰν ἀποθνῄσκωσιν, τί σοί ἐστι τῆς παρασκευῆς ὄφελος;’","st":"4.1"},{"sp":"N","t":"τοῦτ᾽ ἔστιν ἐλευθέρου ἀνδρὸς φωνὴ σπουδῇ ἐξητακότος τὸ πρᾶγμα καὶ ὥσπερ εἰκὸς εὑρηκότος. ἂν δ᾽ ἀλλαχοῦ ζητῇς ἢ ὅπου ἐστίν, τί θαυμαστόν, εἰ οὐδέποτε αὐτὸ εὑρίσκεις;","st":"4.1"},{"sp":"N","t":"ὁ δοῦλος εὐθὺς εὔχεται ἀφεθῆναι ἐλεύθερος. διὰ τί; δοκεῖτε, ὅτι τοῖς εἰκοστώναις ἐπιθυμεῖ δοῦναι ἀργύριον; οὔ: ἀλλ᾽ ὅτι φαντάζεται μέχρι νῦν διὰ τὸ μὴ τετυχηκέναι τούτου ἐμποδίζεσθαι καὶ δυσροεῖν.","st":"4.1"},{"sp":"N","t":"‘ἂν ἀφεθῶ,’ φησίν, ‘εὐθὺς πᾶσα εὔροια, οὐδενὸς ἐπιστρέφομαι, πᾶσιν ὡς ἴσος καὶ ὅμοιος λαλῶ, πορεύομαι ὅπου θέλω, ἔρχομαι ὅθεν θέλω καὶ ὅπου θέλω.’","st":"4.1"},{"sp":"N","t":"εἶτα ἀπηλευθέρωται καὶ εὐθὺς μὲν οὐκ ἔχων, ποῖ φάγῃ, ζητεῖ, τίνα κολακεύσῃ, παρὰ τίνι δειπνήσῃ: εἶτα ἢ ἐργάζεται τῷ σώματι καὶ πάσχει τὰ δεινότατα κἂν σχῇ τινα φάτνην, ἐμπέπτωκεν εἰς δουλείαν πολὺ τῆς προτέρας χαλεπω","st":"4.1"},{"sp":"N","t":"τέραν ἢ καὶ εὐπορήσας ἄνθρωπος ἀπειρόκαλος πεφίληκε παιδισκάριον καὶ δυστυχῶν ἀνακλαίεται καὶ τὴν δουλείαν ποθεῖ.","st":"4.1"},{"sp":"N","t":"‘τί γάρ μοι κακὸν ἦν; ἄλλος μ᾽ ἐνέδυεν, ἄλλος μ᾽ ὑπέδει, ἄλλος ἔτρεφεν, ἄλλος ἐνοσοκόμει, ὀλίγα αὐτῷ ὑπηρέτουν. νῦν δὲ τάλας οἷα πάσχω πλείοσι δουλεύων ἀνθ᾽ ἑνός;","st":"4.1"},{"sp":"N","t":"ὅμως δ᾽ ἐὰν δακτυλίους,’ φησίν, ‘λάβω, τότε γ᾽ εὐρούστατα διάξω καὶ εὐδαιμονέστατα.’ πρῶτον μὲν ἵνα λάβῃ, πάσχει ὧν ἐστιν ἄξιος: εἶτα λαβὼν πάλιν ταὐτά.","st":"4.1"},{"sp":"N","t":"εἶτά φησιν ‘ἂν μὲν στρατεύσωμαι, ἀπηλλάγην πάντων τῶν κακῶν.’ στρατεύεται, πάσχει ὅσα μαστιγίας καὶ οὐδὲν ἧττον δευτέραν αἰτεῖ στρατείαν καὶ τρίτην.","st":"4.1"},{"sp":"N","t":"εἶθ᾽ ὅταν αὐτὸν τὸν κολοφῶνα ἐπιθῇ καὶ γένηται συγκλητικός, τότε γίνεται δοῦλος εἰς σύλλογον ἐρχόμενος, τότε τὴν καλλίστην καὶ λιπαρωτάτην δουλείαν δουλεύει.","st":"4.1"},{"sp":"N","t":"ἵνα μὴ μωρὸς ᾖ, ἀλλ᾽ ἵνα μάθῃ, ἃ ἔλεγεν ὁ Σωκράτης, τί ἐστι τῶν ὄντων ἕκαστον, καὶ μὴ εἰκῇ τὰς προλήψεις ἐφαρμόζῃ ταῖς ἐπὶ μέρους οὐσίαις.","st":"4.1"},{"sp":"N","t":"τοῦτο γάρ ἐστι τὸ αἴτιον τοῖς ἀνθρώποις πάντων τῶν κακῶν, τὸ τὰς προλήψεις τὰς κοινὰς μὴ δύνασθαι ἐφαρμόζειν. τοῖς ἐπὶ μέρους.","st":"4.1"},{"sp":"N","t":"ἡμεῖς δ᾽ ἄλλοι ἄλλο οἰόμεθα. ὁ μὲν ὅτι νοσεῖ. οὐδαμῶς, ἀλλ᾽ ὅτι τὰς προλήψεις οὐκ ἐφαρμόζει. ὁ δ᾽ ὅτι πτωχός ἐστιν, ὁ δ᾽ ὅτι πατέρα χαλεπὸν ἔχει ἢ μητέρα, τῷ δ᾽ ὅτι ὁ Καῖσαρ οὐχ ἵλεώς ἐστιν. τοῦτο δ᾽ ἐστὶν ἓν καὶ μόνον τὸ τὰς προλήψεις ἐφαρμόζειν μὴ εἰδέναι.","st":"4.1"},{"sp":"N","t":"ἐπεὶ τίς οὐκ ἔχει κακοῦ πρόληψιν, ὅτι βλαβερόν ἐστιν, ὅτι φευκτόν ἐστιν, ὅτι παντὶ τρόπῳ ἀποικονόμητόν ἐστιν; πρόληψις προλήψει οὐ μάχεται, ἀλλ᾽ ὅταν ἔλθῃ ἐπὶ τὸ ἐφαρμόζειν.","st":"4.1"},{"sp":"N","t":"τί οὖν τὸ κακόν ἐστι τοῦτο καὶ βλαβερὸν καὶ φευκτόν; λέγει τὸ Καίσαρος μὴ εἶναι φίλον: ἀπῆλθεν, ἀπέσπεσεν τῆς ἐφαρμογῆς, θλίβεται, ζητεῖ τὰ μηδὲν πρὸς τὸ προκείμενον: ὅτι τυχὼν τοῦ φίλος εἶναι Καίσαρος οὐδὲν ἧττον τοῦ ζητουμένου οὐ τέτευχεν.","st":"4.1"},{"sp":"N","t":"τί γάρ ἐστιν, ὃ ζητεῖ πᾶς ἄνθρωπος; εὐσταθῆσαι, εὐδαιμονῆσαι, πάντα ὡς θέλει ποιεῖν, μὴ κωλύεσθαι, μὴ ἀναγκάζεσθαι. ὅταν οὖν γένηται Καίσαρος φίλος, πέπαυται κωλυόμενος, πέπαυται ἀναγκαζόμενος, εὐσταθεῖ, εὐροεῖ; τίνος πυθώμεθα; τίνα ἔχομεν ἀξιοπιστότερον ἢ αὐτὸν τοῦτον τὸν γεγονότα φίλον;","st":"4.1"},{"sp":"N","t":"ἐλθὲ εἰς τὸ μέσον καὶ εἰπὲ ἡμῖν, πότε ἀταραχώτερον ἐκάθευδες, νῦν ἢ πρὶν γενέσθαι φίλος τοῦ Καίσαρος; εὐθὺς ἀκούεις ὅτι ‘παῦσαι, τοὺς θεούς σοι, ἐμπαίζων μου τῇ τύχῃ: οὐκ οἶδας, οἷα πάσχω τάλας: οὐδ᾽ ὕπνος ἐπέρχεταί μοι, ἀλλ᾽ ἄλλος ἐλθὼν λέγει, ὅτι ἤδη ἐγρηγορεῖ, ἤδη πρόεισιν: εἶτα ταραχαί, εἶτα φροντίδες.’","st":"4.1"},{"sp":"N","t":"ἄγε, ἐδείπνεις δὲ πότε εὐαρεστότερον, νῦν ἢ πρότερον; ἄκουσον αὐτοῦ καὶ περὶ τούτων τί λέγει: ὅτι, ἂν μὲν μὴ κληθῇ, ὀδυνᾶται, ἂν δὲ κληθῇ, ὡς δοῦλος παρὰ κυρίῳ δειπνεῖ μεταξὺ προσέχων, μή τι μωρὸν εἴπῃ ἢ ποιήσῃ. καὶ τί δοκεῖς φοβεῖται; μὴ μαστιγωθῇ ὡς δοῦλος; πόθεν αὐτῷ οὕτως καλῶς; ἀλλ᾽ ὡς πρέπει τηλικοῦτον ἄνδρα, Καίσαρος φίλον, μὴ ἀπολέσῃ τὸν τράχηλον.","st":"4.1"},{"sp":"N","t":"ἐλούου δὲ πότ᾽ ἀταραχώτερον; ἐγυμνάζου δὲ πότε σχολαίτερον; τὸ σύνολον ποῖον μᾶλλον ἤθελες βίον βιοῦν, τὸν νῦν ἢ τὸν τότε;","st":"4.1"},{"sp":"N","t":"ὀμόσαι δύναμαι, ὅτι οὐδεὶς οὕτως ἐστὶν ἀναίσθητος ἢ ἀναλήθης, μὴ ἀποδύρασθαι τὰς αὑτοῦ συμφοράς, ὅσῳ ἂν ᾖ φίλτερος.","st":"4.1"},{"sp":"N","t":"ὅταν οὖν μήτε οἱ βασιλεῖς λεγόμενοι ζῶσιν ὡς θέλουσι μήθ᾽ οἱ φίλοι τῶν βασιλέων, τίνες ἔτι εἰσὶν ἐλεύθεροι; — ζήτει καὶ εὑρήσεις. ἔχεις γὰρ ἀφορμὰς παρὰ τῆς φύσεως πρὸς εὕρεσιν τῆς ἀληθείας. εἰ δ᾽ αὐτὸς οὐχ οἷός τε εἶ κατὰ ταύτας ψιλὰς πορευόμενος εὑρεῖν τὸ ἑξῆς, ἄκουσον παρὰ τῶν ἐζητηκότων.","st":"4.1"},{"sp":"N","t":"τί λέγουσιν; ἀγαθόν σοι δοκεῖ ἡ ἐλευθερία; — τὸ μέγιστον. — δύναται οὖν τις τοῦ μεγίστου ἀγαθοῦ τυγχάνων κακοδαιμονεῖν ἢ κακῶς πράσσειν; — οὔ. — ὅσους οὖν ἂν ἴδῃς κακοδαιμονοῦντας, δυσροοῦντας, πενθοῦντας, ἀποφαίνου θαρρῶν μὴ εἶναι ἐλευθέρους. — ἀποφαίνομαι.","st":"4.1"},{"sp":"N","t":"— οὐκοῦν ἀπὸ μὲν ὠνῆς καὶ πράσεως καὶ τῆς τοιαύτης ἐν κτήσει κατατάξεως ἤδη ἀποκεχωρήκαμεν. εἰ γὰρ ὀρθῶς ὡμολόγησας ταῦτα, ἄν τε μέγας βασιλεὺς κακοδαιμονῇ, οὐκ ἂν ἐλεύθερος, ἄν τε μικρὸς ἄν θ᾽ ὑπατικὸς ἄν τε δισύπατος. — ἔστω.","st":"4.1"},{"sp":"N","t":"ἔτι οὖν ἀπόκριναί μοι κἀκεῖνο: δοκεῖ σοι μέγα τι εἶναι καὶ γενναῖον ἡ ἐλευθερία καὶ ἀξιόλογον; — πῶς γὰρ οὔ; — ἔστιν οὖν τυγχάνοντά τινος οὕτως μεγάλου καὶ ἀξιολόγου καὶ γενναίου ταπεινὸν εἶναι; — οὐκ ἔστιν.","st":"4.1"},{"sp":"N","t":"— ὅταν οὖν ἴδῃς τινὰ ὑποπεπτωκότα ἑτέρῳ ἢ κολακεύοντα παρὰ τὸ φαινόμενον αὐτῷ, λέγε καὶ τοῦτον θαρρῶν μὴ εἶναι ἐλεύθερον: καὶ μὴ μόνον, ἂν δειπναρίου ἕνεκα αὐτὸ ποιῇ, ἀλλὰ κἂν ἐπαρχίας ἕνεκα κἂν ὑπατείας. ἀλλ᾽ ἐκείνους μὲν μικροδούλους λέγε τοὺς μικρῶν τινων ἕνεκα ταῦτα ποιοῦντας, τούτους δ᾽, ὡς εἰσὶν ἄξιοι, μεγαλοδούλους.","st":"4.1"},{"sp":"N","t":"— ἔστω καὶ ταῦτα. — δοκεῖ δέ σοι ἡ ἐλευθερία αὐτεξούσιόν τι εἶναι καὶ αὐτόνομον; — πῶς γὰρ οὔ; — ὅντινα οὖν ἐπ᾽ ἄλλῳ κωλῦσαι ἔστι καὶ ἀναγκάσαι, θαρρῶν λέγε μὴ εἶναι ἐλεύθερον.","st":"4.1"},{"sp":"N","t":"καὶ μή μοι πάππους αὐτοῦ καὶ προπάππους βλέπε καὶ ὠνὴν ζήτει καὶ πρᾶσιν, ἀλλ᾽ ἂν ἀκούσῃς λέγοντος ἔσωθεν καὶ ἐκ πάθους ‘κύριε,’ κἂν δώδεκα ῥάβδοι προάγωσιν, λέγε δοῦλον: κἂν ἀκούσῃς λέγοντος ‘τάλας ἐγώ, οἷα πάσχω,’ λέγε δοῦλον: ἂν ἁπλῶς ἀποκλαιόμενον ἴδῃς, μεμφόμενον, δυσροοῦντα, λέγε δοῦλον περιπόρφυρον ἔχοντα.","st":"4.1"},{"sp":"N","t":"ἂν οὖν μηδὲν τούτων ποιῇ, μήπω εἴπῃς ἐλεύθερον, ἀλλὰ τὰ δόγματα αὐτοῦ κατάμαθε, μή τι ἀναγκαστά, μή τι κωλυτικά, μή τι δυσροητικά: κἂν εὕρῃς τοιοῦτον, λέγε δοῦλον ἀνοχὰς ἔχοντα ἐν Σατουρναλίοις: λέγε, ὅτι ὁ κύριος αὐτοῦ ἀποδημεῖ: εἶθ᾽ ἥξει καὶ γνώσῃ οἷα πάσχει.","st":"4.1"},{"sp":"N","t":"— τίς ἥξει; — πᾶς ὃς ἂν ἐξουσίαν ἔχῃ τῶν ὑπ᾽ αὐτοῦ τινος θελομένων πρὸς τὸ περιποιῆσαι ταῦτα ἢ ἀφελέσθαι. — οὕτως οὖν πολλοὺς κυρίους ἔχομεν; — οὕτως. τὰ γὰρ πράγματα προτέρους τούτων κυρίους ἔχομεν: ἐκεῖνα δὲ πολλά ἐστιν. διὰ ταῦτα ἀνάγκη καὶ τοὺς τούτων τινὸς ἔχοντας ἐξουσίαν κυρίους εἶναι:","st":"4.1"},{"sp":"N","t":"ἐπεί τοι οὐδεὶς αὐτὸν τὸν Καίσαρα φοβεῖται, ἀλλὰ θάνατον, φυγήν, ἀφαίρεσιν τῶν ὄντων, φυλακήν, ἀτιμίαν. οὐδὲ φιλεῖ τις τὸν Καίσαρα, ἂν μή τι ᾖ πολλοῦ ἄξιος, ἀλλὰ πλοῦτον φιλοῦμεν, δημαρχίαν, στρατηγίαν, ὑπατείαν. ὅταν ταῦτα φιλῶμεν καὶ μισῶμεν καὶ φοβώμεθα, ἀνάγκη τοὺς ἐξουσίαν αὐτῶν ἔχοντας κυρίους ἡμῶν εἶναι. διὰ τοῦτο καὶ ὡς θεοὺς αὐτοὺς προσκυνοῦμεν:","st":"4.1"},{"sp":"N","t":"ἐννοοῦμεν γάρ, ὅτι τὸ ἔχον ἐξουσίαν τῆς μεγίστης ὠφελείας θεῖόν ἐστιν, εἶθ᾽ ὑποτάσσομεν κακῶς ‘οὗτος δ᾽ ἔχει τῆς μεγίστης ὠφελείας: θεῖόν ἐστιν. εἶθ᾽ ὑποτάσσομεν κακῶς, οὗτος δ᾽ ἔχει τῆς μεγίστης ὠφελείας ἐξουσίαν.’ ἀνάγκη καὶ τὸ γενόμενον ἐξ αὐτῶν ἐπενεχθῆναι κακῶς.","st":"4.1"},{"sp":"N","t":"τί οὖν ἐστι τὸ ποιοῦν ἀκώλυτον τὸν ἄνθρωπον καὶ αὐτεξούσιον; πλοῦτος γὰρ οὐ ποιεῖ οὐδ᾽ ὑπατεία οὐδ᾽ ἐπαρχία οὐδὲ βασιλεία, ἀλλὰ δεῖ τι ἄλλο εὑρεθῆναι.","st":"4.1"},{"sp":"N","t":"τί οὖν ἐστι τὸ ἐν τῷ γράφειν ἀκώλυτον ποιοῦν καὶ ἀπαραπόδιστον; — ἡ ἐπιστήμη τοῦ γράφειν. — τί δ᾽ ἐν τῷ κιθαρίζειν; — ἡ ἐπιστήμη τοῦ κιθαρίζειν. — οὐκοῦν καὶ ἐν τῷ βιοῦν ἡ ἐπιστήμη τοῦ βιοῦν.","st":"4.1"},{"sp":"N","t":"ὡς μὲν οὖν ἁπλῶς, ἀκήκοας: σκέψαι δ᾽ αὐτὸ καὶ ἐκ τῶν ἐπὶ μέρους. τὸν ἐφιέμενόν τινος τῶν ἐπ᾽ ἄλλοις ὄντων ἐνδέχεται ἀκώλυτον εἶναι; — οὔ. — ἐνδέχεται ἀπαραπόδιστον;","st":"4.1"},{"sp":"N","t":"— οὔ. — οὐκοῦν οὐδ᾽ ἐλεύθερον. ὅρα οὖν: πότερον οὐδὲν ἔχομεν, ὃ ἐφ᾽ ἡμῖν μόνοις ἐστίν, ἢ πάντα ἢ τὰ μὲν ἐφ᾽ ἡμῖν ἐστιν, τὰ δ᾽ ἐπ᾽ ἄλλοις;","st":"4.1"},{"sp":"N","t":"— πῶς λέγεις; — τὸ σῶμα ὅταν θέλῃς ὁλόκληρον εἶναι, ἐπὶ σοί ἐστιν ἢ οὔ; — οὐκ ἐπ᾽ ἐμοί. — ὅταν δ᾽ ὑγιαίνειν; — οὐδὲ τοῦτο. — ὅταν δὲ καλὸν εἶναι; — οὐδὲ τοῦτο. — ζῆν δὲ καὶ ἀποθανεῖν; — οὐδὲ τοῦτο. — οὐκοῦν τὸ μὲν σῶμα ἀλλότριον, ὑπεύθυνον παντὸς τοῦ ἰσχυροτέρου.","st":"4.1"},{"sp":"N","t":"— ἔστω. — τὸν ἀγρὸν δ᾽ ἐπὶ σοί ἐστιν ἔχειν, ὅταν θέλῃς καὶ ἐφ᾽ ὅσον θέλεις καὶ οἷον θέλεις; — οὔ. — τὰ δὲ δουλάρια; — οὔ. — τὰ δ᾽ ἱμάτια; — οὔ. — τὸ δὲ οἰκίδιον; — οὔ. — τοὺς δ᾽ ἵππους; — τούτων μὲν οὐδέν. — ἂν δὲ τὰ τέκνα σου ζῆν θέλῃς ἐξ ἅπαντος ἢ τὴν γυναῖκα ἢ τὸν ἀδελφὸν ἢ τοὺς φίλους, ἐπὶ σοί ἐστιν; — οὐδὲ ταῦτα.","st":"4.1"},{"sp":"N","t":"πότερον οὖν οὐδὲν ἔχεις αὐτεξούσιον, ὃ ἐπὶ μόνῳ ἐστὶ σοί, ἢ ἔχεις τι τοιοῦτον; — οὐκ οἶδα. — ὅρα οὖν οὕτως καὶ σκέψαι αὐτό.","st":"4.1"},{"sp":"N","t":"μή τις δύναταί σε ποιῆσαι συγκαταθέσθαι τῷ ψεύδει; — οὐδείς. — οὐκοῦν ἐν μὲν τῷ συγκαταθετικῷ τόπῳ ἀκώλυτος εἶ καὶ ἀνεμπόδιστος.","st":"4.1"},{"sp":"N","t":"— ἔστω. — ἄγε, ὁρμῆσαι δέ σε ἐφ᾽ ὃ μὴ θέλεις τις δύναται ἀναγκάσαι; — δύναται. ὅταν γάρ μοι θάνατον ἢ δεσμὰ ἀπειλῇ, ἀναγκάζει μ᾽ ὁρμῆσαι. — ἂν οὖν καταφρονῇς τοῦ ἀποθανεῖν καὶ τοῦ δεδέσθαι, ἔτι αὐτοῦ ἐπιστρέφῃ;","st":"4.1"},{"sp":"N","t":"— οὔ. — σὸν οὖν ἐστιν ἔργον τὸ καταφρονεῖν θανάτου ἢ οὐ σόν; — ἐμόν. — σὸν ἄρα ἐστὶ καὶ τὸ ὁρμῆσαι ἢ οὔ; — ἔστω ἐμόν. — τὸ δ᾽ ἀφορμῆσαι τίνος;","st":"4.1"},{"sp":"N","t":"σὸν καὶ τοῦτο. — τί οὖν, ἂν ἐμοῦ ὁρμήσαντος περιπατῆσαι ἐκεῖνός με κωλύσῃ; — τί σου κωλύσει; μή τι τὴν συγκατάθεσιν; — οὔ: ἀλλὰ τὸ σωμάτιον. — ναί, ὡς λίθον. — ἔστω: ἀλλ᾽ οὐκέτι ἐγὼ περιπατῶ.","st":"4.1"},{"sp":"N","t":"— τίς δέ σοι εἶπεν ‘τὸ περιπατῆσαι σὸν ἔργον ἐστὶν ἀκώλυτον;’ ἐγὼ γὰρ ἐκεῖνο ἔλεγον ἀκώλυτον μόνον τὸ ὁρμῆσαι: ὅπου δὲ σώματος χρεία καὶ τῆς ἐκ τούτου συνεργείας, πάλαι ἀκήκοας, ὅτι οὐδέν ἐστι σόν.","st":"4.1"},{"sp":"N","t":"— ἔστω καὶ ταῦτα. — ὀρέγεσθαι δέ σε οὗ μὴ θέλεις τις ἀναγκάσαι δύναται; — οὐδείς. — προθέσθαι δ᾽ ἢ ἐπιβαλέσθαι τις ἢ ἁπλῶς χρῆσθαι ταῖς προσπιπτούσαις φαντασίαις;","st":"4.1"},{"sp":"N","t":"— οὐδὲ τοῦτο: ἀλλὰ ὀρεγόμενόν με κωλύσει τυχεῖν οὗ ὀρέγομαι. — ἂν τῶν σῶν τινος ὀρέγῃ καὶ τῶν ἀκωλύτων, πῶς σε κωλύσει; — οὐδαμῶς. — τίς οὖν σοι λέγει, ὅτι ὁ τῶν ἀλλοτρίων ὀρεγόμενος ἀκώλυτός ἐστιν; Ὑγείας οὖν μὴ ὀρέγωμαι;","st":"4.1"},{"sp":"N","t":"— μηδαμῶς, μηδ᾽ ἄλλου ἀλλοτρίου μηδενός.","st":"4.1"},{"sp":"N","t":"ὃ γὰρ οὐκ ἔστιν ἐπὶ σοὶ παρασκευάσαι ἢ τηρῆσαι ὅτε θέλεις, τοῦτο ἀλλότριόν ἐστιν. μακρὰν ἀπ᾽ αὐτοῦ οὐ μόνον τὰς χεῖρας, ἀλλὰ πολὺ πρότερον τὴν ὄρεξιν: εἰ δὲ μή, παρέδωκας σαυτὸν δοῦλον, ὑπέθηκας τὸν τράχηλον, † ἂν θαυμάσῃς τῶν τι μὴ σῶν ᾧ τινι ἂν τῶν ὑπευθύνων καὶ θνητῶν προσπαθῇς. — ἡ χεὶρ οὐκ ἔστιν ἐμή;","st":"4.1"},{"sp":"N","t":"— μέρος ἐστὶ σόν, φύσει δὲ πηλός, κωλυτόν, ἀναγκαστόν, δοῦλον παντὸς τοῦ ἰσχυροτέρου.","st":"4.1"},{"sp":"N","t":"καὶ τί σοι λέγω χεῖρα; ὅλον τὸ σῶμα οὕτως ἔχειν σε δεῖ ὡς ὀνάριον ἐπισεσαγμένον, ἐφ᾽ ὅσον ἂν οἷόν τε ᾖ, ἐφ᾽ ὅσον ἂν διδῶται: ἂν δ᾽ ἀγγαρεία ᾖ καὶ στρατιώτης ἐπιλάβηται, ἄφες, μὴ ἀντίτεινε μηδὲ γόγγυζε. εἰ δὲ μή, πληγὰς λαβὼν οὐδὲν ἧττον ἀπολεῖς καὶ τὸ ὀνάριον.","st":"4.1"},{"sp":"N","t":"ὅταν δὲ πρὸς τὸ σῶμα οὕτως ἔχειν σε δέῃ, ὅρα, τί ἀπολείπεται περὶ τὰ ἄλλα, ὅσα τοῦ σώματος ἕνεκα παρασκευάζεται. ὅταν ἐκεῖνο ὀνάριον ᾖ, τἆλλα γίνεται χαλινάρια τοῦ ὀναρίου, σαγμάτια, ὑποδημάτια, κριθαί, χόρτος. ἄφες κἀκεῖνα, ἀπόλυε θᾶττον καὶ εὐκολώτερον ἢ τὸ ὀνάριον.","st":"4.1"},{"sp":"N","t":"καὶ ταύτην τὴν παρασκευὴν παρασκευασάμενος καὶ τὴν ἄσκησιν ἀσκήσας τὰ ἀλλότρια ἀπὸ τῶν ἰδίων διακρίνειν, τὰ κωλυτὰ ἀπὸ τῶν ἀκωλύτων, ταῦτα πρὸς σαυτὸν ἡγεῖσθαι, ἐκεῖνα μὴ πρὸς σαυτόν, ἐνταῦθα ἐπιστρόφως ἔχειν τὴν ὄρεξιν, ἐνταῦθα τὴν ἔκκλισιν, μή τι ἔτι φοβῇ τινα;","st":"4.1"},{"sp":"N","t":"— οὐδένα. — περὶ τίνος γὰρ φοβήσῃ; περὶ τῶν σεαυτοῦ, ὅπου σοι ἡ οὐσία τοῦ ἀγαθοῦ καὶ τοῦ κακοῦ; καὶ τίς τούτων ἐξουσίαν ἔχει; τίς ἀφελέσθαι αὐτὰ δύναται, τίς ἐμποδίσαι; οὐ μᾶλλον ἢ τὸν θεόν.","st":"4.1"},{"sp":"N","t":"ἀλλ᾽ ὑπὲρ τοῦ σώματος καὶ τῆς κτήσεως; ὑπὲρ τῶν ἀλλοτρίων; ὑπὲρ τῶν οὐδὲν πρὸς σέ; καὶ τί ἄλλο ἐξ ἀρχῆς ἐμελέτας ἢ διακρίνειν τὰ σὰ καὶ οὐ σά, τὰ ἐπὶ σοὶ καὶ οὐκ ἐπὶ σοί, τὰ κωλυτὰ καὶ ἀκώλυτα; τίνος δὲ ἕνεκα προσῆλθες τοῖς φιλοσόφοις; ἵνα μηδὲν ἧττον ἀτυχῇς καὶ δυστυχῇς;","st":"4.1"},{"sp":"N","t":"οὐκοῦν ἄφοβος μὲν οὕτως ἔσει καὶ ἀτάραχος. λύπη δὲ τί πρὸς σέ; ὧν γὰρ προσδοκωμένων φόβος γίνεται, καὶ λύπη παρόντων. ἐπιθυμήσεις δὲ τίνος ἔτι; τῶν μὲν γὰρ προαιρετικῶν ἅτε καλῶν ὄντων καὶ παρόντων σύμμετρον ἔχεις καὶ καθισταμένην τὴν ὄρεξιν, τῶν δ᾽ ἀπροαιρέτων οὐδενὸς ὀρέγῃ, ἵνα καὶ τόπον σχῇ τὸ ἄλογον ἐκεῖνο καὶ ὠστικὸν καὶ παρὰ τὰ μέτρα ἠπειγμένον;","st":"4.1"},{"sp":"N","t":"ὅταν οὖν πρὸς τὰ πράγματα οὕτως ἔχῃς, τίς ἔτι ἄνθρωπος δύναται φοβερὸς εἶναι; τί γὰρ ἔχει ἄνθρωπος ἀνθρώπῳ φοβερὸν ἢ ὀφθεὶς ἢ λαλήσας ἢ ὅλως συναναστραφείς; οὐ μᾶλλον ἢ ἵππος ἵππῳ ἢ κύων κυνὶ ἢ μέλισσα μελίσσῃ. ἀλλὰ τὰ πράγματα ἑκάστῳ φοβερά ἐστιν: ταῦτα δ᾽ ὅταν περιποιεῖν τις δύνηταί τινι ἢ ἀφελέσθαι, τότε καὶ αὐτὸς φοβερὸς γίνεται.","st":"4.1"},{"sp":"N","t":"πῶς οὖν ἀκρόπολις καταλύεται; οὐ σιδήρῳ οὐδὲ πυρί, ἀλλὰ δόγμασιν. ἂν γὰρ τὴν οὖσαν ἐν τῇ πόλει καθέλωμεν, μή τι καὶ τὴν τοῦ πυρετοῦ, μή τι καὶ τὴν τῶν καλῶν γυναικαρίων, μή τι ἁπλῶς τὴν ἐν ἡμῖν ἀκρόπολιν καὶ τοὺς ἐν ἡμῖν τυράννους ἀποβεβλήκαμεν, οὓς ἐφ᾽ ἑκάστοις καθ᾽ ἡμέραν ἔχομεν, ποτὲ μὲν τοὺς αὐτούς, ποτὲ δ᾽ ἄλλους;","st":"4.1"},{"sp":"N","t":"ἀλλ᾽ ἔνθεν ἄρξασθαι δεῖ καὶ ἔνθεν καθελεῖν τὴν ἀκρόπολιν, ἐκβάλλειν τοὺς τυράννους: τὸ σωμάτιον ἀφεῖναι, τὰ μέρη αὐτοῦ, τὰς δυνάμεις, τὴν κτῆσιν, τὴν φήμην, ἀρχάς, τιμάς, τέκνα, ἀδελφούς, φίλους, πάντα ταῦτα ἡγήσασθαι ἀλλότρια.","st":"4.1"},{"sp":"N","t":"κἂν ἔνθεν ἐκβληθῶσιν οἱ τύραννοι, τί ἔτι ἀποτειχίζω τὴν ἀκρόπολιν ἐμοῦ γε ἕνεκα; ἑστῶσα γὰρ τί μοι ποιεῖ; τί ἔτι ἐκβάλλω τοὺς δορυφόρους; ποῦ γὰρ αὐτῶν αἰσθάνομαι; ἐπ᾽ ἄλλους ἔχουσιν τὰς ῥάβδους καὶ τοὺς κοντοὺς καὶ τὰς μαχαίρας.","st":"4.1"},{"sp":"N","t":"ἐγὼ δ᾽ οὐπώποτ᾽ οὔτε θέλων ἐκωλύθην οὔτ᾽ ἠναγκάσθην μὴ θέλων καὶ πῶς τοῦτο δυνατόν; προσκατατέταχά μου τὴν ὁρμὴν τῷ θεῷ. θέλει μ᾽ ἐκεῖνος πυρέσσειν: κἀγὼ θέλω. θέλει ὁρμᾶν ἐπί τι: κἀγὼ θέλω. θέλει ὀρέγεσθαι: κἀγὼ θέλω. θέλει με τυχεῖν τινος: κἀγὼ βούλομαι.","st":"4.1"},{"sp":"N","t":"οὐ θέλει: οὐ βούλομαι. ἀποθανεῖν οὖν θέλω: στρεβλωθῆναι οὖν θέλω. τίς ἔτι με κωλῦσαι δύναται παρὰ τὸ ἐμοὶ φαινόμενον ἢ ἀναγκάσαι; οὐ μᾶλλον ἢ τὸν Δία.","st":"4.1"},{"sp":"N","t":"οὕτως ποιοῦσι καὶ τῶν ὁδοιπόρων οἱ ἀσφαλέστεροι. ἀκήκοεν ὅτι λῃστεύεται ἡ ὁδός: μόνος οὐ τολμᾷ καθεῖναι, ἀλλὰ περιέμεινεν συνοδίαν ἢ πρεσβευτοῦ ἢ ταμίου ἢ ἀνθυπάτου καὶ προσκατατάξας ἑαυτὸν παρέρχεται ἀσφαλῶς.","st":"4.1"},{"sp":"N","t":"οὕτως καὶ ἐν τῷ κόσμῳ ποιεῖ ὁ φρόνιμος. πολλὰ λῃστήρια, τύραννοι, χειμῶνες, ἀπορίαι, ἀποβολαὶ τῶν φιλτάτων.","st":"4.1"},{"sp":"N","t":"‘ποῦ τις καταφύγῃ; πῶς ἀλῄστευτος παρέλθῃ; ποίαν συνοδίαν περιμείνας ἀσφαλῶς διέλθῃ; τίνι προσκατατάξας ἑαυτόν;","st":"4.1"},{"sp":"N","t":"τῷ δεῖνι, τῷ πλουσίῳ, τῷ ὑπατικῷ. καὶ τί μοι ὄφελος; αὐτὸς ἐκδύεται, οἰμώζει, πενθεῖ. τί δ᾽, ἂν ὁ συνοδοιπόρος αὐτὸς ἐπ᾽ ἐμὲ στραφεὶς λῃστής μου γένηται;","st":"4.1"},{"sp":"N","t":"τί ποιήσω; φίλος ἔσομαι Καίσαρος: ἐκείνου με ὄντα ἑταῖρον οὐδεὶς ἀδικήσει. πρῶτον μέν, ἵνα γένωμαι, πρόσα με δεῖ τλῆναι καὶ παθεῖν, ποσάκις καὶ ὑπὸ πόσων λῃστευθῆναι: εἶτα ἐὰν γένωμαι, καὶ οὗτος θνητός ἐστιν καὶ οὗτος θνητός.","st":"4.1"},{"sp":"N","t":"ἂν δ᾽ αὐτὸς ἔκ τινος περιστάσεως ἐχθρός μου γένηται, ἀναχωρῆσαί πού ποτε κρεῖσσον;","st":"4.1"},{"sp":"N","t":"εἰς ἐρημίαν; ἄγε, ἐκεῖ πυρετὸς οὐκ ἔρχεται; τί οὖν γένηται; οὐκ ἔστιν εὑρεῖν ἀσφαλῆ σύνοδον, πιστόν, ἰσχυρόν, ἀνεπιβούλευτον;’","st":"4.1"},{"sp":"N","t":"οὕτως ἐφίστησιν καὶ ἐννοεῖ, ὅτι, ἐὰν τῷ θεῷ προσκατατάξῃ ἑαυτόν, διελεύσεται ἀσφαλῶς. πῶς λέγεις προσκατατάξαι;","st":"4.1"},{"sp":"N","t":"— ἵν᾽, ὃ ἂν ἐκεῖνος θέλῃ, καὶ αὐτὸς θέλῃ καί, ὃ ἂν ἐκεῖνος μὴ θέλῃ, τοῦτο μηδ᾽ αὐτὸς θέλῃ.","st":"4.1"},{"sp":"N","t":"— πῶς οὖν τοῦτο γένηται; — πῶς γὰρ ἄλλως ἢ ἐπισκεψαμένῳ τὰς ὁρμὰς τοῦ θεοῦ καὶ τὴν διοίκησιν; τί μοι δέδωκεν ἐμὸν καὶ αὐτεξούσιον, τί αὑτῷ κατέλειπεν; τὰ προαιρετικά μοι δέδωκεν, ἐπ᾽ ἐμοὶ πεποίηκεν, ἀνεμπόδιστα, ἀκώλυτα. τὸ σῶμα τὸ πήλινον πῶς ἐδύνατο ἀκώλυτον ποιῆσαι; ὑπέταξεν οὖν τῇ τῶν ὅλων περιόδῳ, τὴν κτῆσιν, τὰ σκεύη, τὴν οἰκίαν, τὰ τέκνα, τὴν γυναῖκα.","st":"4.1"},{"sp":"N","t":"τί οὖν θεομαχῶ; τί θέλω τὰ μὴ θελητά, τὰ μὴ δοθέντα μοι ἐξ ἅπαντος ἔχειν; ἀλλὰ πῶς; ὡς δέδοται καὶ ἐφ᾽ ὅσον δύναται. ἀλλ᾽ ὁ δοὺς ἀφαιρεῖται. τί οὖν ἀντιτείνω; οὐ λέγω, ὅτι ἠλίθιος ἔσομαι τὸν ἰσχυρότερον βιαζόμενος, ἀλλ᾽ ἔτι πρότερον ἄδικος.","st":"4.1"},{"sp":"N","t":"πόθεν γὰρ ἔχων αὐτὰ ἦλθον; ὁ πατήρ μου αὐτὰ ἔδωκεν. ἐκείνῳ δὲ τίς; τὸν ἥλιον δὲ τίς πεποίηκε, τοὺς καρποὺς δὲ τίς, τὰς δ᾽ ὥρας τίς, τὴν δὲ πρὸς ἀλλήλους συμπλοκὴν καὶ κοινωνίαν τίς;","st":"4.1"},{"sp":"N","t":"εἶτα σύμπαντα εἰληφὼς παρ᾽ ἄλλου καὶ αὐτὸν σεαυτόν, ἀγανακτεῖς καὶ μέμφῃ τὸν δόντα, ἄν σού τι ἀφέληται; τίς ὢν καὶ ἐπὶ τί ἐληλυθώς; οὐχὶ ἐκεῖνός σε εἰσήγαγεν; οὐχὶ τὸ φῶς ἐκεῖνός σοι ἔδειξεν; οὐ συνεργοὺς δέδωκεν; οὐ καὶ αἰσθήσεις; οὐ λόγον; ὡς τίνα δὲ εἰσήγαγεν; οὐχ ὡς θνητόν; οὐχ ὡς μετὰ ὀλίγου σαρκιδίου ζήσοντα ἐπὶ γῆς καὶ θεασόμενον τὴν διοίκησιν αὐτοῦ καὶ συμπομπεύσοντα αὐτῷ καὶ συνεορτάσοντα πρὸς ὀλίγον;","st":"4.1"},{"sp":"N","t":"οὐ θέλεις οὖν, ἕως δέδοταί σοι, θεασάμενος τὴν πομπὴν καὶ τὴν πανήγυριν εἶτα, ὅταν σ᾽ ἐξάγῃ, πορεύεσθαι προσκυνήσας καὶ εὐχαριστήσας ὑπὲρ ὧν ἤκουσας καὶ εἶδες;","st":"4.1"},{"sp":"N","t":"‘οὔ: ἀλλ᾽ ἔτι ἑορτάζειν ἤθελον.’ καὶ γὰρ οἱ μύσται μυεῖσθαι; τάχα καὶ οἱ ἐν Ὀλυμπίᾳ ἄλλους ἀθλητὰς βλέπειν: ἀλλὰ ἡ πανήγυρις πέρας ἔχει: ἔξελθε, ἀπαλλάγηθι ὡς εὐχάριστος, ὡς αἰδήμων: δὸς ἄλλοις τόπον: δεῖ γενέσθαι καὶ ἄλλους, καθάπερ καὶ σὺ ἐγένου, καὶ γενομένους ἔχειν χώραν καὶ οἰκήσεις, τὰ ἐπιτήδεια. ἂν δ᾽ οἱ πρῶτοι μὴ ὑπεξάγωσιν, τί ὑπολείπεται; τί ἄπληστος εἶ; τί ἀνίκανος; τί στενοχωρεῖς τὸν κόσμον;","st":"4.1"},{"sp":"N","t":"— ναί: ἀλλὰ τὰ τεκνία μετ᾽ ἐμαυτοῦ εἶναι θέλω καὶ τὴν γυναῖκα. — σὰ γάρ ἐστιν; οὐχὶ τοῦ δόντος; οὐχὶ καὶ τοῦ σὲ πεποιηκότος; εἶτα οὐκ ἐκστήσῃ τῶν ἀλλοτρίων; οὐ παραχωρήσεις τῷ κρείσσονι;","st":"4.1"},{"sp":"N","t":"— τί οὖν μ᾽ εἰσῆγεν ἐπὶ τούτοις; — καὶ εἰ μὴ ποιεῖ σοι, ἔξελθε: οὐκ ἔχει χρείαν θεατοῦ μεμψιμοίρου. τῶν συνεορταζόντων δεῖται, τῶν συγχορευόντων, ἵν᾽ ἐπικροτῶσι μᾶλλον, ἐπιθειάζωσιν, ὑμνῶσι δὲ τὴν πανήγυριν.","st":"4.1"},{"sp":"N","t":"τοὺς ἀταλαιπώρους δὲ καὶ δειλοὺς οὐκ ἀηδῶς ὄψεται ἀπολελειμμένους τῆς πανηγύρεως: οὐδὲ γὰρ παρόντες ὡς ἐν ἑορτῇ διῆγον οὐδ᾽ ἐξεπλήρουν τὴν χώραν τὴν πρέπουσαν, ἀλλ᾽ ὠδυνῶντο, ἐμέμφοντο τὸν δαίμονα, τὴν τύχην, τοὺς συνόντας: ἀναίσθητοι καὶ ὧν ἔτυχον καὶ τῶν ἑαυτῶν δυνάμεων, ἃς εἰλήφασι πρὸς τὰ ἐναντία, μεγαλοψυχίας, γενναιότητος, ἀνδρείας, αὐτῆς τῆς νῦν ζητουμένης ἐλευθερίας.","st":"4.1"},{"sp":"N","t":"— ἐπὶ τί οὖν εἴληφα ταῦτα; — χρησόμενος. — μέχρι τίνος; — μέχρις ἂν ὁ χρήσας θέλῃ. — ἂν οὖν ἀναγκαῖά μοι ᾖ; — μὴ πρόσπασχε αὐτοῖς καὶ οὐκ ἔσται. σὺ αὐτὰ αὑτῷ μὴ εἴπῃς ἀναγκαῖα καὶ οὐκ ἔστιν.","st":"4.1"},{"sp":"N","t":"ταύτην τὴν μελέτην ἕωθεν εἰς ἑσπέραν μελετᾶν ἔδει. ἀπὸ τῶν μικροτάτων, ἀπὸ τῶν εὐεπηρεαστοτάτων ἀρξάμενος, ἀπὸ χύτρας, ἀπὸ ποτηρίου, εἶθ᾽ οὕτως ἐπὶ χιτωνάριον πρόσελθε, ἐπὶ κυνάριον, ἐπὶ ἱππάριον, ἐπὶ ἀγρίδιον: ἔνθεν ἐπὶ σαυτόν, τὸ σῶμα, τὰ μέρη τοῦ σώματος, τὰ τέκνα, τὴν γυναῖκα, τοὺς ἀδελφούς.","st":"4.1"},{"sp":"N","t":"πανταχοῦ περιβλέψας ἀπόρριψον ἀπὸ σεαυτοῦ: κάθηρον τὰ δόγματα, μή τι προσήρτηταί σοι τῶν οὐ σῶν, μή τι συμπέφυκεν, μή τι ὀδυνήσει σ᾽ ἀποσπώμενον.","st":"4.1"},{"sp":"N","t":"καὶ λέγε γυμναζόμενος καθ᾽ ἡμέραν, ὡς ἐκεῖ, μὴ ὅτι φιλοσοφεῖς （ ἔστω φορτικὸν τὸ ὄνομα ） , ἀλλ᾽ ὅτι καρπιστὴν δίδως. τοῦτο γάρ ἐστιν ἡ ταῖς ἀληθείαις ἐλευθερία.","st":"4.1"},{"sp":"N","t":"ταύτην ἠλευθερώθη Διογένης παρ᾽ Ἀντισθένους καὶ οὐκέτι ἔφη καταδουλωθῆναι δύνασθαι ὑπ᾽ οὐδενός.","st":"4.1"},{"sp":"N","t":"διὰ τοῦτο πῶς ἑάλω, πῶς τοῖς πειραταῖς ἐχρῆτο: μή τι κύριον εἶπέν τινα αὐτῶν; καὶ οὐ λέγω τὸ ὄνομα: οὐ γὰρ τὴν φωνὴν φοβοῦμαι, ἀλλὰ τὸ πάθος, ἀφ᾽ οὗ ἡ φωνὴ ἐκπέμπεται.","st":"4.1"},{"sp":"N","t":"πῶς ἐπιτιμᾷ αὐτοῖς, ὅτι κακῶς ἔτρεφον τοὺς ἑαλωκότας: πῶς ἐπράθη: μή τι κύριον ἐζήτει; ἀλλὰ δοῦλον. πῶς δὲ πραθεὶς ἀνεστρέφετο πρὸς τὸν δεσπότην: εὐθὺς διελέγετο πρὸς αὐτόν, ὅτι οὐχ οὕτως ἐστολίσθαι δεῖ αὐτόν, οὐχ οὕτως κεκάρθαι, περὶ τῶν υἱῶν, πῶς δεῖ αὐτοὺς διάγειν.","st":"4.1"},{"sp":"N","t":"καὶ τί θαυμαστόν; εἰ γὰρ παιδοτρίβην ἐώνητο, ἐν τοῖς παλαιστρικοῖς ὑπηρέτῃ ἂν αὐτῷ ἐχρῆτο ἢ κυρίῳ; εἰ δ᾽ ἰατρόν, ὡσαύτως, εἰ δ᾽ ἀρχιτέκτονα. καὶ οὕτως ἐφ᾽ ἑκάστης ὕλης τὸν ἔμπειρον τοῦ ἀπείρου κρατεῖν πᾶσα ἀνάγκη.","st":"4.1"},{"sp":"N","t":"ὅστις οὖν καθόλου τὴν περὶ βίον ἐπιστήμην κέκτηται, τί ἄλλο ἢ τοῦτον εἶναι δεῖ τὸν δεσπότην; τίς γάρ ἐστιν ἐν νηὶ κύριος; — ὁ κυβερνήτης. — διὰ τί; ὅτι ὁ ἀπειθῶν αὐτῷ ζημιοῦται.","st":"4.1"},{"sp":"N","t":"— ἀλλὰ δεῖραί με δύναται. — μή τι οὖν ἀζημίως; — οὕτως μὲν κἀγὼ ἔκρινον. — ἀλλ᾽ ὅτι οὐκ ἀζημίως, διὰ τοῦτο οὐκ ἔξεστιν: οὐδενὶ δ᾽ ἀζήμιόν ἐστι τὸ ποιεῖν τὰ ἄδικα.","st":"4.1"},{"sp":"N","t":"— καὶ τίς ἡ ζημία τῷ δήσαντι τὸν αὑτοῦ δοῦλον, ἣν δοκεῖς; — τὸ δῆσαι: τοῦτο ὃ καὶ σὺ ὁμολογήσεις, ἂν θέλῃς σῴζειν, ὅτι ἄνθρωπος οὐκ ἔστι θηρίον, ἀλλ᾽ ἥμερον ζῷον.","st":"4.1"},{"sp":"N","t":"ἐπεὶ πότ᾽ ἄμπελος πράσσει κακῶς; ὅταν παρὰ τὴν ἑαυτῆς φύσιν πράσσῃ. πότ᾽ ἀλεκτρυών;","st":"4.1"},{"sp":"N","t":"ὡσαύτως. οὐκοῦν καὶ ἄνθρωπος. τίς οὖν αὐτοῦ ἡ φύσις; δάκνειν καὶ λακτίζειν καὶ εἰς φυλακὴν βάλλειν καὶ ἀποκεφαλίζειν; οὔ: ἀλλ᾽ εὖ ποιεῖν, συνεργεῖν, ἐπεύχεσθαι. τότ᾽ οὖν κακῶς πράσσει, ἄν τε θέλῃς ἄν τε μή, ὅταν ἀγνωμονῇ. ὥστε Σωκράτης οὐκ ἔπραξε κακῶς;","st":"4.1"},{"sp":"N","t":"— οὔ, ἀλλ᾽ οἱ δικασταὶ καὶ οἱ κατήγοροι. — οὐδ᾽ ἐν Ῥώμῃ Ἑλουίδιος; — οὔ, ἀλλ᾽ ὁ ἀποκτείνας αὐτόν. — πῶς λέγεις;","st":"4.1"},{"sp":"N","t":"— ὡς καὶ σὺ ἀλεκτρυόνα οὐ λέγεις κακῶς πρᾶξαι τὸν νικήσαντα καὶ κατακοπέντα, ἀλλὰ τὸν ἀπλῆγα ἡττηθέντα: οὐδὲ κύνα εὐδαιμονίζεις τὸν μήτε διώκοντα μήτε πονοῦντα, ἀλλ᾽ ὅταν ἱδρῶντα ἴδῃς, ὅταν ὀδυνώμενον, ὅταν ῥηγνύμενον ὑπὸ τοῦ δρόμου.","st":"4.1"},{"sp":"N","t":"τί παραδοξολογοῦμεν, εἰ λέγομεν παντὸς κακὸν εἶναι τὸ παρὰ τὴν ἐκείνου φύσιν; τοῦτο παράδοξόν ἐστιν; σὺ γὰρ αὐτὸ ἐπὶ πάντων τῶν ἄλλων οὐ λέγεις; διὰ τί ἐπὶ μόνου οὖν τοῦ ἀνθρώπου ἄλλως φέρῃ;","st":"4.1"},{"sp":"N","t":"ἀλλ᾽ ὅτι λέγομεν ἥμερον εἶναι τοῦ ἀνθρώπου τὴν φύσιν καὶ φιλάλληλον καὶ πιστήν, τοῦτο παράδοξον οὐκ ἔστιν; — οὐδὲ τοῦτο.","st":"4.1"},{"sp":"N","t":"— πῶς οὖν ἔτι οὐ δερόμενος βλάπτεται ἢ δεσμευόμενος ἢ ἀποκεφαλιζόμενος; οὐχὶ οὕτως μέν: εἰ γενναίως πάσχει, καὶ προσκερδαίνων καὶ προσωφελούμενος ἀπέρχεται, ἐκεῖνος δὲ βλαπτόμενός ἐστιν ὁ τὰ οἰκτρότατα πάσχων καὶ αἴσχιστα, ὁ ἀντὶ ἀνθρώπου λύκος γινόμενος ἢ ἔχις ἢ σφήξ;","st":"4.1"},{"sp":"N","t":"ἄγε οὖν ἐπέλθωμεν τὰ ὡμολογημένα. ὁ ἀκώλυτος ἄνθρωπος ἐλεύθερος, ᾧ πρόχειρα τὰ πράγματα ὡς βούλεται. ὃν δ᾽ ἔστιν ἢ κωλῦσαι ἢ ἀναγκάσαι ἢ ἐμποδίσαι ἢ ἄκοντα εἴς τι ἐμβαλεῖν, δοῦλός ἐστιν.","st":"4.1"},{"sp":"N","t":"τίς δ᾽ ἀκώλυτος; ὁ μηδενὸς τῶν ἀλλοτρίων ἐφιέμενος. τίνα δ᾽ ἀλλότρια; ἃ οὐκ ἔστιν ἐφ᾽ ἡμῖν οὔτ᾽ ἔχειν οὔτε μὴ ἔχειν οὔτε ποιὰ ἔχειν ἢ πῶς ἔχοντα.","st":"4.1"},{"sp":"N","t":"οὐκοῦν τὸ σῶμα ἀλλότριον, τὰ μέρη αὐτοῦ ἀλλότρια, ἡ κτῆσις ἀλλοτρία. ἂν οὖν τινι τούτων ὡς ἰδίῳ προσπαθῇς, δώσεις δίκας ἃς ἄξιον τὸν τῶν ἀλλοτρίων ἐφιέμενον.","st":"4.1"},{"sp":"N","t":"αὕτη ἡ ὁδὸς ἐπ᾽ ἐλευθερίαν ἄγει, αὕτη μόνη ἀπαλλαγὴ δουλείας, μόνῃ τὸ δυνηθῆναί ποτ᾽ εἰπεῖν ἐξ ὅλης ψυχῆς τὸ ἄγου δέ μ᾽, ὦ Ζεῦ, καὶ σύ γ᾽ ἡ Πεπρωμένη, ὅποι ποθ᾽ ὑμῖν εἰμι διατεταγμένος.","st":"4.1"},{"sp":"N","t":"ἀλλὰ τί λέγεις, φιλόσοφε; καλεῖ σε ὁ τύραννος ἐροῦντά τι ὧν οὐ πρέπει σοι. λέγεις ἢ οὐ λέγεις; εἰπέ μοι. — ἄφες σκέψωμαι. — νῦν σκέψῃ; ὅτε δ᾽ ἐν τῇ σχολῇ ἦς, τί ἐσκέπτου; οὐκ ἐμελέτας, τίνα ἐστὶ τὰ ἀγαθὰ καὶ τὰ κακὰ καὶ τίνα οὐδέτερα; — Ἐσκεπτόμην. — τίνα οὖν ἤρεσκεν ὑμῖν;","st":"4.1"},{"sp":"N","t":"— τὰ δίκαια καὶ καλὰ ἀγαθὰ εἶναι, τὰ ἄδικα καὶ αἰσχρὰ κακά. — μή τι τὸ ζῆν ἀγαθόν; — οὔ. — μή τι τὸ ἀποθανεῖν κακόν; — οὔ. — μή τι φυλακή; — οὔ. — λόγος δ᾽ ἀγεννὴς καὶ ἄπιστος καὶ φίλου προδοσία καὶ κολακεία τυράννου τί ὑμῖν ἐφαίνετο;","st":"4.1"},{"sp":"N","t":"— κακά. — τί οὖν; οὐχὶ σκέπτῃ, οὐχὶ δ᾽ ἔσκεψαι καὶ βεβούλευσαι. ποία γὰρ σκέψις, εἰ καθήκει μοὶ δυναμένῳ τὰ μέγιστα ἀγαθὰ ἐμαυτῷ περιποιῆσαι, τὰ μέγιστα κακὰ μὴ περιποιῆσαι; καλὴ σκέψις καὶ ἀναγκαία, πολλῆς βουλῆς δεομένη. τί ἡμῖν ἐμπαίζεις, ἄνθρωπε;","st":"4.1"},{"sp":"N","t":"οὐδέποτε τοιαύτη σκέψις γίνεται. οὐδ᾽ εἰ ταῖς ἀληθείαις κακὰ μὲν ἐφαντάζου τὰ αἰσχρά, τὰ δ᾽ ἄλλα οὐδέτερα, ἦλθες ἂν ἐπὶ ταύτην τὴν ἐπίστασιν, οὐδ᾽ ἐγγύς: ἀλλ᾽ αὐτόθεν διακρίνειν εἶχες, ὥσπερ ὄψει τῇ διανοίᾳ.","st":"4.1"},{"sp":"N","t":"πότε γὰρ σκέπτῃ, εἰ τὰ μέλανα λευκά ἐστιν, εἰ τὰ βαρέα κοῦφα; οὐχὶ δὲ τοῖς ἐναργῶς φαινομένοις ἐπακολουθεῖς; πῶς οὖν νῦν σκέπτεσθαι λέγεις, εἰ τὰ οὐδέτερα τῶν κακῶν φευκτότερα;","st":"4.1"},{"sp":"N","t":"ἀλλ᾽ οὐκ ἔχεις τὰ δόγματα ταῦτα, ἀλλὰ φαίνεταί σοι οὔτε ταῦτα οὐδέτερα, ἀλλὰ τὰ μέγιστα κακά, οὔτ᾽ ἐκεῖνα κακά, ἀλλ᾽ οὐδὲν πρὸς ἡμᾶς.","st":"4.1"},{"sp":"N","t":"οὕτως γὰρ ἐξ ἀρχῆς εἴθισας σεαυτόν: ‘ποῦ εἰμι; ἐν σχολῇ. καὶ ἀκούουσί μου τίνες; λέγω μετὰ τῶν φιλοσόφων. ἀλλ᾽ ἐξελήλυθα τῆς σχολῆς: ἆρον ἐκεῖνα τὰ τῶν σχολαστικῶν καὶ τῶν μωρῶν.’ οὕτως καταμαρτυρεῖται φίλος ὑπὸ φιλοσόφου, οὕτως παρασιτεῖ φιλόσοφος,","st":"4.1"},{"sp":"N","t":"οὕτως ἐπ᾽ ἀργυρίῳ ἐκμισθοῖ ἑαυτόν, οὕτως ἐν συγκλήτῳ τις οὐ λέγει τὰ φαινόμενα: ἔνδοθεν τὸ δόγμα αὐτοῦ βοᾷ,","st":"4.1"},{"sp":"N","t":"οὐ ψυχρὸν καὶ ταλαίπωρον ὑποληψείδιον ἐκ λόγων εἰκαίων ὡς ἐκ τριχὸς ἠρτημένον, ἀλλὰ ἰσχυρὸν καὶ χρηστικὸν καὶ ὑπὸ τοῦ διὰ τῶν ἔργων γεγυμνάσθαι μεμυημένον.","st":"4.1"},{"sp":"N","t":"παραφύλαξον σαυτόν, πῶς ἀκούεις — οὐ λέγω, ὅτι τὸ παιδίον σου ἀπέθανεν: πόθεν σοι; ἀλλ᾽ ὅτι σου τὸ ἔλαιον ἐξεχέθη, ὁ οἶνος ἐξεπόθη,","st":"4.1"},{"sp":"N","t":"ἵνα τις ἐπιστὰς διατεινομένῳ σοι τοῦτ᾽ αὐτὸ μόνον εἴπῃ ‘φιλόσοφε, ἄλλα λέγεις ἐν τῇ σχολῇ: τί ἡμᾶς ἐξαπατᾷς; τί σκώληξ ὢν λέγεις, ὅτι ἄνθρωπος εἶ;’","st":"4.1"},{"sp":"N","t":"ἤθελον ἐπιστῆναί τινι αὐτῶν συνουσιάζοντι, ἵνα ἴδω, πῶς τείνεται καὶ ποίας φωνὰς ἀφίησιν, εἰ μέμνηται τοῦ ὀνόματος αὐτοῦ, τῶν λόγων οὓς ἀκούει ἢ λέγει ἢ ἀναγιγνώσκει. καὶ τί ταῦτα πρὸς ἐλευθερίαν;","st":"4.1"},{"sp":"N","t":"— οὐκ ἄλλα μὲν οὖν ἢ ταῦτ᾽, ἄν τε θέλητε ὑμεῖς οἱ πλούσιοι ἄν τε μή.","st":"4.1"},{"sp":"N","t":"— καὶ τίς σοι μαρτυρεῖ ταῦτα; — τί γὰρ ἄλλο ἢ αὐτοὶ ὑμεῖς οἱ τὸν κύριον τὸν μέγαν ἔχοντες καὶ πρὸς τὸ ἐκείνου νεῦμα καὶ κίνημα ζῶντες, κἄν τινα ὑμῶν ἴδῃ μόνον συνεστραμμένῳ βλέμματι, ἀποψυχόμενοι, τὰς γραίας θεραπεύοντες καὶ τοὺς γέροντας καὶ λέγοντες ὅτι","st":"4.1"},{"sp":"N","t":"‘οὐ δύναμαι τοῦτο ποιῆσαι: οὐκ ἐξεστί μοι;’ διὰ τί οὐκ ἔξεστίν σοι; οὐκ ἄρτι ἐμάχου μοι λέγων ἐλεύθερος εἶναι; ‘ἀλλὰ Ἄπρυλλά με κεκώλυκεν.’ λέγε οὖν τὰς ἀληθείας, δοῦλε, καὶ μὴ δραπέτευέ σου τοὺς κυρίους μηδ᾽ ἀπαρνοῦ μηδὲ τόλμα καρπιστὴν διδόναι τοσούτους ἔχων τῆς δουλείας ἐλέγχους.","st":"4.1"},{"sp":"N","t":"καίτοι τὸν μὲν ὑπ᾽ ἔρωτος ἀναγκαζόμενόν τι ποιεῖν παρὰ τὸ φαινόμενον καὶ ἅμα μὲν ὁρῶντα τὸ ἄμεινον, ἅμα δ᾽ οὐκ ἐξευτονοῦντα ἀκολουθῆσαι αὐτῷ ἔτι μᾶλλον ἄν τις συγγνώμης ἄξιον ὑπολάβοι, ἅθ᾽ ὑπό τινος βιαίου καὶ τρόπον τινὰ θείου κατεσχημένον.","st":"4.1"},{"sp":"N","t":"σοῦ δὲ τίς ἀνάσχοιτο τῶν γραῶν ἐρῶντος καὶ τῶν γερόντων καὶ ἐκείνας ἀπομύσσοντος καὶ ἀποπλύνοντος καὶ δωροδοκοῦντος καὶ ἅμα μὲν νοσούσας θεραπεύοντος ὡς δούλου, ἅμα δ᾽ ἀποθανεῖν εὐχομένου καὶ τοὺς ἰατροὺς διακρίνοντος, εἰ ἤδη θανασίμως ἔχουσιν; ἢ πάλιν ὅταν ὑπὲρ τῶν μεγάλων τούτων καὶ σεμνῶν ἀρχῶν καὶ τιμῶν τὰς χεῖρας τῶν ἀλλοτρίων δούλων καταφιλῇς, ἵνα μηδ᾽ ἐλευθέρων δοῦλος ᾖς;","st":"4.1"},{"sp":"N","t":"εἶτά μοι σεμνὸς περιπατεῖς στρατηγῶν, ὑπατεύων, οὐκ οἶδα, πῶς ἐστρατήγησας, πόθεν τὴν ὑπατείαν ἔλαβες, τίς σοι αὐτὴν ἔδωκεν;","st":"4.1"},{"sp":"N","t":"ἐγὼ μὲν οὐδὲ ζῆν ἤθελον, εἰ διὰ Φηλικίωνα ἔδει ζῆσαι τῆς ὀφρύος αὐτοῦ καὶ τοῦ δουλικοῦ φρυάγματος ἀνασχόμενον. οἶδα γάρ, τί ἐστι δοῦλος εὐτυχῶν ὡς δοκεῖ καὶ τετυφλωμένος. σὺ οὖν, φησίν, ἐλεύθερος εἶ;","st":"4.1"},{"sp":"N","t":"— θέλω νὴ τοὺς θεοὺς καὶ εὔχομαι, ἀλλ᾽ οὔπω δύναμαι ἀντιβλέψαι τοῖς κυρίοις, ἔτι τιμῶ τὸ σωμάτιον, ὁλόκληρον αὐτὸ ἔχειν ἀντὶ πολλοῦ ποιοῦμαι καίτοι μηδ᾽ ὁλόκληρον ἔχων.","st":"4.1"},{"sp":"N","t":"ἀλλὰ δύναμαί σοι δεῖξαι ἐλεύθερον, ἵνα μηκέτι ζητῇς τὸ παράδειγμα. Διογένης ἦν ἐλεύθερος. πόθεν τοῦτο; οὐχ ὅτι ἐξ ἐλευθέρων ἦν （ οὐ γὰρ ἦν ） , ἀλλ᾽ ὅτι αὐτὸς ἦν, ὅτι ἀποβεβλήκει πάσας τὰς τῆς δουλείας βλαβὰς οὐδ᾽ ἦν, ὅπως τις προσέλθῃ πρὸς αὐτὸν οὐδ᾽ ὅθεν λάβηται πρὸς τὸ καταδουλώσασθαι.","st":"4.1"},{"sp":"N","t":"πάντα εὔλυτα εἶχεν, πάντα μόνον προσηρτημένα. εἰ τῆς κτήσεως ἐπελάβου, αὐτὴν ἀφῆκεν ἄν σοι μᾶλλον ἢ ἠκολούθησεν δι᾽ αὐτήν: εἰ τοῦ σκέλους, τὸ σκέλος: εἰ ὅλου τοῦ σωματίου, ὅλον τὸ σωμάτιον: οἰκείους, φίλους, πατρίδα ὡσαύτως. ᾔδει, πόθεν ἔχει καὶ παρὰ τίνος καὶ ἐπὶ τίσιν λαβών. τοὺς μέν γ᾽ ἀληθεινοὺς προγόνους,","st":"4.1"},{"sp":"N","t":"τοὺς θεούς, καὶ τὴν τῷ ὄντι πατρίδα οὐδεπώποτ᾽ ἂν ἐγκατέλειπεν οὐδὲ παρεχώρησεν ἄλλῳ μᾶλλον πείθεσθαι αὐτοῖς καὶ ὑπακούειν οὐδ᾽ ὑπεραπέθανεν ἂν εὐκολώτερον τῆς πατρίδος ἄλλος.","st":"4.1"},{"sp":"N","t":"οὐ γὰρ ἐζήτει ποτὲ δόξαι τι ποιεῖν ὑπὲρ τῶν ὅλων, ἀλλ᾽ ἐμέμνητο, ὅτι πᾶν τὸ γενόμενον ἐκεῖθέν ἐστιν καὶ ὑπὲρ ἐκείνης πράττεται καὶ ὑπὸ τοῦ διοικοῦντος αὐτὴν παρεγγυᾶται.","st":"4.1"},{"sp":"N","t":"τοιγαροῦν ὅρα, τί λέγει αὐτὸς καὶ γράφει: ‘διὰ τοῦτό σοι,’ φησίν, ‘ἔξεστιν, ὦ Διόγενες, καὶ τῷ Περσῶν βασιλεῖ καὶ Ἀρχιδάμῳ τῷ Λακεδαιμονίων ὡς βούλει διαλέγεσθαι.’","st":"4.1"},{"sp":"N","t":"ἆρά γ᾽ ὅτι ἐξ ἐλευθέρων ἦν; πάντες γὰρ Ἀθηναῖοι καὶ πάντες Λακεδαιμόνιοι καὶ Κορίνθιοι διὰ τὸ ἐκ δούλων εἶναι οὐκ ἠδύναντο αὐτοῖς ὡς ἠβούλοντο διαλέγεσθαι, ἀλλ᾽ ἐδεδοίκεσαν καὶ ἐθεράπευον;","st":"4.1"},{"sp":"N","t":"διὰ τί οὖν, φησίν, ἔξεστιν; ‘ὅτι τὸ σωμάτιον ἐμὸν οὐχ ἡγοῦμαι, ὅτι οὐδενὸς δέομαι, ὅτι ὁ νόμος μοι πάντα ἐστὶ καὶ ἄλλο οὐδέν.’ ταῦτα ἦν τὰ ἐλεύθερον ἐκεῖνον ἐάσαντα.","st":"4.1"},{"sp":"N","t":"καὶ ἵνα μὴ δόξῃς, ὅτι παράδειγμα δείκνυμι ἀνδρὸς ἀπεριστάτου μήτε γυναῖκα ἔχοντος μήτε τέκνα μήτε πατρίδα ἢ φίλους ἢ συγγενεῖς, ὑφ᾽ ὧν κάμπτεσθαι καὶ περισπᾶσθαι ἠδύνατο, λάβε Σωκράτη καὶ θέασαι γυναῖκα καὶ παιδία ἔχοντα, ἀλλὰ ὡς ἀλλότριαν, πατρίδα, ἐφ᾽ ὅσον ἔδει καὶ ὡς ἔδει, φίλους, συγγενεῖς, πάντα ταῦτα ὑποτεταχότα τῷ νόμῳ καὶ τῇ πρὸς ἐκεῖνον εὐπειθ","st":"4.1"},{"sp":"N","t":"είᾳ. διὰ τοῦτο, στρατεύεσθαι μὲν ὁπότ᾽ ἔδει, πρῶτος ἀπῄει κἀκεῖ ἐκινδύνευεν ἀφειδέστατα: ἐπὶ Λέοντα δ᾽ ὑπὸ τῶν τυράννων πεμφθείς, ὅτι αἰσχρὸν ἡγεῖτο, οὐδ᾽ ἐπεβουλεύσατο εἰδώς, ὅτι ἀποθανεῖν δεήσει, ἂν οὕτως τύχῃ.","st":"4.1"},{"sp":"N","t":"καὶ τί αὐτῷ διέφερεν; ἄλλο γάρ τι σῴζειν ἤθελεν: οὐ τὸ σαρκίδιον, ἀλλὰ τὸν πιστόν, τὸν αἰδήμονα.","st":"4.1"},{"sp":"N","t":"ταῦτα ἀπαρεγχείρητα, ἀνυπότακτα. εἶθ᾽ ὅτ᾽ ἀπολογεῖσθαι ἔδει ὑπὲρ τοῦ ζῆν, μή τι ὡς τέκνα ἔχων ἀναστρέφεται, μή τι ὡς γυναῖκα; ἀλλ᾽ ὡς μόνος. τί δ᾽, ὅτε πιεῖν ἔδει τὸ φάρμακον, πῶς ἀναστρέφεται;","st":"4.1"},{"sp":"N","t":"δυνάμενος διασωθῆναι καὶ τοῦ Κρίτωνος αὐτῷ λέγοντος ὅτι ‘ἔξελθε διὰ τὰ παιδία’ τί λέγει; ἕρμαιον ἡγεῖτο αὐτό; πόθεν; ἀλλὰ τὸ εὔσχημον σκοπεῖ, τἆλλα δ᾽ οὐδ᾽ ὁρᾷ, οὐδ᾽ ἐπιλογίζεται. οὐ γὰρ ἤθελεν, φησίν, σῶσαι τὸ σωμάτιον, ἀλλ᾽ ἐκεῖνο, ὃ τῷ δικαίῳ μὲν αὔξεται καὶ σῴζεται, τῷ δ᾽ ἀδίκῳ μειοῦται καὶ ἀπόλλυται. Σωκράτης δ᾽ αἰσχρῶς οὐ σῴζεται,","st":"4.1"},{"sp":"N","t":"ὁ μὴ ἐπιψηφίσας Ἀθηναίων κελευόντων, ὁ τοὺς τυράννους ὑπεριδών, ὁ τοιαῦτα περὶ ἀρετῆς καὶ καλοκἀγαθίας διαλεγόμενος: τοῦτον οὐκ ἔστι σῶσαι αἰσχρῶς,","st":"4.1"},{"sp":"N","t":"ἀλλ᾽ ἀποθνῄσκων σῴζεται, οὐ φεύγων. καὶ γὰρ ὁ ἀγαθὸς ὑποκριτὴς παυόμενος ὅτε δεῖ σῴζεται μᾶλλον ἢ ὑποκρινόμενος παρὰ καιρόν.","st":"4.1"},{"sp":"N","t":"τί οὖν ποιήσει τὰ παιδία; ‘εἰ μὲν εἰς Θετταλίαν ἀπῄειν, ἐπεμελήθητε αὐτῶν: εἰς Ἅιδου δέ μου ἀποδημήσαντος οὐδεὶς ἔσται ὁ ἐπιμελησόμενος;’ ὅρα, πῶς ὑποκορίζεται καὶ σκώπτει τὸν θάνατον.","st":"4.1"},{"sp":"N","t":"εἰ δ᾽ ἐγὼ καὶ σὺ ἦμεν, εὐθὺς ἂν καταφιλοσοφήσαντες ὅτι ‘τοὺς ἀδικοῦντας δεῖ τοῖς ἴσοις ἀμύνεσθαι’ καὶ προσθέντες ὅτι ‘ὄφελος ἔσομαι πολλοῖς ἀνθρώποις σωθείς, ἀποθανὼν δ᾽ οὐδενί,’ εἰ γἄρ᾽ ἔδει διὰ τρώγλης ἐκδύντας, ἐξήλθομεν ἄν.","st":"4.1"},{"sp":"N","t":"καὶ πῶς ἂν ὠφελήσαμέν τινα; ποῦ γὰρ ἂν ἔτι ἔμενον ἐκεῖνοι; ἢ οἳ ὄντες ἦμεν ὠφέλιμοι, οὐχὶ πολὺ μᾶλλον ἀποθανόντες ἂν ὅτε ἔδει καὶ ὡς ἔδει ὠφελήσαμεν ἀνθρώπους;","st":"4.1"},{"sp":"N","t":"καὶ νῦν Σωκράτους ἀποθανόντος οὐθὲν ἧττον ἢ καὶ πλεῖον ὠφέλιμός ἐστιν ἀνθρώποις ἡ μνήμη ὧν ἔτι ζῶν ἔπραξεν ἢ εἶπεν.","st":"4.1"},{"sp":"N","t":"ταῦτα μελέτα, ταῦτα τὰ δόγματα, τούτους τοὺς λόγους, εἰς ταῦτα ἀφόρα τὰ παραδείγματα, εἰ θέλεις ἐλεύθερος εἶναι, εἰ ἐπιθυμεῖς κατ᾽ ἀξίαν τοῦ πράγματος. καὶ τί θαυμαστόν,","st":"4.1"},{"sp":"N","t":"εἰ τηλικοῦτο πρᾶγμα τοσούτων καὶ τηλικούτων ὠνῇ; ὑπὲρ τῆς νομιζομένης ἐλευθερίας ταύτης οἱ μὲν ἀπάγχονται, οἱ δὲ κατακρημνίζουσιν αὑτούς, ἔστι δ᾽ ὅτε καὶ πόλεις ὅλαι ἀπώλοντο:","st":"4.1"},{"sp":"N","t":"ὑπὲρ τῆς ἀληθεινῆς καὶ ἀνεπιβουλεύτου καὶ ἀσφαλοῦς ἐλευθερίας ἀπαιτοῦντι τῷ θεῷ ἃ δέδωκεν οὐκ ἐκστήσῃ; οὐχ, ὡς Πλάτων λέγει, μελετήσεις οὐχὶ ἀποθνῄσκειν μόνον, ἀλλὰ καὶ στρεβλοῦσθαι καὶ φεύγειν καὶ δέρεσθαι καὶ πάνθ᾽ ἁπλῶς ἀποδιδόναι τἀλλότρια;","st":"4.1"},{"sp":"N","t":"ἔσει τοίνυν δοῦλος ἐν δούλοις, κἂν μυριάκις ὑπατεύσῃς, κἂν εἰς τὸ παλάτιον ἀναβῇς, οὐδὲν ἧττον: καὶ αἰσθήσει, ὅτι παράδοξα μὲν ἴσως φασὶν οἱ φιλόσοφοι, καθάπερ καὶ ὁ Κλεάνθης ἔλεγεν, οὐ μὴν παράλογα.","st":"4.1"},{"sp":"N","t":"ἔργῳ γὰρ εἴσῃ, ὅτι ἀληθῆ ἐστι καὶ τούτων τῶν θαυμαζομένων καὶ σπουδαζομένων ὄφελος οὐδέν ἐστι τοῖς τυχοῦσι: τοῖς δὲ μηδέπω τετευχόσι φαντασία γίνεται, ὅτι παραγενομένων αὐτῶν ἅπαντα παρέσται αὐτοῖς τὰ ἀγαθά: εἶθ᾽ ὅταν παραγένηται, τὸ καῦμα ἴσον, ὁ ῥιπτασμὸς ὁ αὐτός, ἡ ἄση,","st":"4.1"},{"sp":"N","t":"ἡ τῶν οὐ παρόντων ἐπιθυμία. οὐ γὰρ ἐκπληρώσει τῶν ἐπιθυμουμένων ἐλευθερία παρασκευάζεται, ἀλλὰ ἀνασκευῇ τῆς ἐπιθυμίας.","st":"4.1"},{"sp":"N","t":"καὶ ἵν᾽ εἰδῇς, ὅτι ἀληθῆ ταῦτά ἐστιν, ὡς ἐκείνων ἕνεκα πεπόνηκας, οὕτως καὶ ἐπὶ ταῦτα μετάθες τὸν πόνον: ἀγρύπνησον ἕνεκα τοῦ δόγμα περιποιήσασθαι ἐλευθεροποιόν,","st":"4.1"},{"sp":"N","t":"θεράπευσον ἀντὶ γέροντος πλουσίου φιλόσοφον, περὶ θύρας ὄφθηται τὰς τούτου: οὐκ ἀσχημονήσεις ὀφθείς, οὐκ ἀπελεύσῃ κενὸς οὐδ᾽ ἀκερδής, ἂν ὡς δεῖ προσέλθῃς. εἰ δὲ μή, πείρασόν γ᾽: οὐκ ἔστιν αἰσχρὰ ἡ πεῖρα. περὶ συμπεριφορᾶς. τούτῳ τῷ τόπῳ πρὸ πάντων σε δεῖ προσέχειν, μή ποτε ἄρα τῶν προτέρων συνήθων ἢ φίλων ἀνακραθῇς τινι οὕτως, ὥστ᾽ εἰς τὰ αὐτὰ συγκαταβῆναι αὐτῷ: εἰ δὲ μή, ἀπολεῖς σεαυτόν.","st":"4.1"},{"sp":"N","t":"ἂν δέ σ᾽ ὑποτρέχῃ ὅτι ‘ἀδέξιος αὐτῷ φανοῦμαι καὶ οὐχ ὁμοίως ἕξει ὡς πρότερον,’ μέμνησο, ὅτι προῖκα οὐδὲν γίνεται οὐδ᾽ ἔστι δυνατὸν μὴ τὰ αὐτὰ ποιοῦντα μὴ τὸν αὐτὸν εἶναι τῷ ποτέ. ἐλοῦ οὖν πότερον θέλεις,","st":"4.2"},{"sp":"N","t":"ὁμοίως φιλεῖσθαι ὑφ᾽ ὧν πρότερον ὅμοιος ὢν τῷ πρότερον σεαυτῷ ἢ κρείσσων ὢν μὴ τυγχάνειν τῶν ἴσων.","st":"4.2"},{"sp":"N","t":"εἰ γὰρ τοῦτο κρεῖσσον, αὐτόθεν ἀπόνευσον ἐπὶ τοῦτο μηδέ σε περισπάτωσαν οἱ ἕτεροι διαλογισμοί. οὐδεὶς γὰρ ἐπαμφοτερίζων δύναται προκόψαι, ἀλλ᾽ εἰ τοῦτο πάντων προκέκρικας, εἰ πρὸς τούτῳ μόνῳ θέλεις εἶναι, εἰ τοῦτο ἐκπονῆσαι, ἄφες ἅπαντα τἆλλα:","st":"4.2"},{"sp":"N","t":"εἰ δὲ μή, οὗτος ὁ ἐπαμφοτερισμὸς ἑκάτερόν σοι ποιήσει, οὔτε προκόψεις κατ᾽ ἀξίαν οὔτ᾽ ἐκείνων τεύξῃ, ὧν πρότερον ἐτύγχανες.","st":"4.2"},{"sp":"N","t":"πρότερον γὰρ εἰλικρινῶς ἐφιέμενος τῶν οὐδενὸς ἀξίων ἡδὺς ἦς τοῖς συνοῦσιν.","st":"4.2"},{"sp":"N","t":"οὐ δύνασαι δ᾽ ἐν ἀμφοτέρῳ τῷ εἴδει διενεγκεῖν: ἀλλ᾽ ἀνάγκη, καθόσον ἂν τοῦ ἑτέρου κοινωνῇς, ἀπολείπεσθαί σ᾽ ἐν θατέρῳ. οὐ δύνασαι μὴ πίνων μεθ᾽ ὧν ἔπινες ὁμοίως ἡδὺς αὐτοῖς φαίνεσθαι: ἑλοῦ οὖν, πότερον μεθυστὴς εἶναι θέλεις καὶ ἡδὺς ἐκείνοις ἢ νήφων ἀηδής. οὐ δύνασαι μὴ ᾁδων μεθ᾽ ὧν ᾖδες ὁμοίως φιλεῖσθαι ὑπ᾽ αὐτῶν: ἑλοῦ οὖν καὶ ἐνταῦθα, πότερον θέλεις.","st":"4.2"},{"sp":"N","t":"εἰ γὰρ κρεῖσσον τὸ αἰδήμονα εἶναι καὶ κόσμιον τοῦ εἰπεῖν τινα ‘ἡδὺς ἄνθρωπος,’ ἄφες τὰ ἕτερα, ἀπόγνωθι, ἀποστράφηθι, μηδὲν σοὶ καὶ αὐτοῖς.","st":"4.2"},{"sp":"N","t":"εἰ δὲ μὴ ἀρέσει ταῦτα, ὅλος ἀπόκλινον ἐπὶ τἀναντία: γενοῦ εἷς τῶν κιναίδων, εἷς τῶν μοιχῶν καὶ ποίει τὰ ἑξῆς καὶ τεύξῃ ὧν θέλεις. καὶ ἀναπηδῶν ἐπικραύγαζε τῷ ὀρχηστῇ.","st":"4.2"},{"sp":"N","t":"διάφορα δ᾽ οὕτως πρόσωπα οὐ μίγνυται: οὐ δύνασαι καὶ Θερσίτην ὑποκρίνασθαι καὶ Ἀγαμέμνονα. ἂν Θερσίτης εἶναι θέλῃς, κυρτόν σε εἶναι δεῖ, φαλακρόν: ἂν Ἀγαμέμνων, μέγαν καὶ καλὸν καὶ τοὺς ὑποτεταγμένους φιλοῦντα. τίνα τίνων ἀντικαταλλακτέον. ἐκεῖνο πρόχειρον ἔχε, ὅταν τινὸς ἀπολείπῃ τῶν ἐκτός, τί ἀντ᾽ αὐτοῦ περιποιῇ: κἂν ᾖ πλείονος ἄξιον, μηδέποτ᾽ εἴπῃς ὅτι","st":"4.2"},{"sp":"N","t":"‘ἐζημίωμαι:’ οὐδ᾽ ἂν ἀντὶ ὄνου ἵππον, οὐδ᾽ ἀντὶ προβάτου βοῦν, οὐδ᾽ ἀντὶ κέρματος πρᾶξιν καλήν, οὐδ᾽ ἀντὶ ψυχρολογίας ἡσυχίαν οἵαν δεῖ, οὐδ᾽ ἀντὶ αἰσχρολογίας αἰδῶ.","st":"4.3"},{"sp":"N","t":"τούτων μεμνημένος πανταχοῦ διασώσεις τὸ σαυτοῦ πρόσωπον οἷον ἔχειν σε δεῖ. εἰ δὲ μή, σκόπει, ὅτι ἀπόλλυνται οἱ χρόνοι εἰκῇ καὶ ὅσα νῦν προσέχεις σεαυτῷ, μέλλεις ἐκχεῖν ἅπαντα ταῦτα καὶ ἀνατρέπειν.","st":"4.3"},{"sp":"N","t":"ὀλίγου δὲ χρεία ἐστὶ πρὸς τὴν ἀπώλειαν τὴν πάντων καὶ ἀνατροπήν, μικρᾶς ἀποστροφῆς τοῦ λόγου.","st":"4.3"},{"sp":"N","t":"ἵνα ὁ κυβερνήτης ἀνατρέψῃ τὸ πλοῖον, οὐ χρείαν ἔχει τῆς αὐτῆς παρασκευῆς, ὅσης εἰς τὸ σῶσαι: ἀλλὰ μικρὸν πρὸς τὸν ἄνεμον ἂν ἐπιστρέψῃ, ἀπώλετο: κἂν μὴ αὐτὸς ἑκών, ὑποπαρενθυμηθῇ δ᾽, ἀπώλετο.","st":"4.3"},{"sp":"N","t":"τοιοῦτόν ἐστί τι καὶ ἐνθάδε: μικρὸν ἂν ἀπονυστάξῃς, ἀπῆλθεν πάντα τὰ μέχρι νῦν συνειλεγμένα. πρόσεχε οὖν ταῖς φαντασίαις, ἐπαγρύπνει.","st":"4.3"},{"sp":"N","t":"οὐ γὰρ μικρὸν τὸ τηρούμενον, ἀλλ᾽ αἰδὼς καὶ πίστις καὶ εὐστάθεια,","st":"4.3"},{"sp":"N","t":"ἀπάθεια, ἀλυπία, ἀφοβία, ἀταραξία, ἁπλῶς ἐλευθερία. τίνων μέλλεις ταῦτα πωλεῖν; βλέπε, πόσου ἀξίων. — ἀλλ᾽ οὐ τεύξομαι τοιούτου τινὸς ἀντ᾽ αὐτοῦ. — βλέπε καὶ τυγχάνων πάλιν ἐκείνου, τί ἀντ᾽ αὐτοῦ λαμβάνεις.","st":"4.3"},{"sp":"N","t":"‘ἐγὼ εὐκοσμίαν, ἐκεῖνος δημαρχίαν: ἐκεῖνος στρατηγίαν, ἐγὼ αἰδῶ. ἀλλ᾽ οὐ κραυγάζω, ὅπου ἀπρεπές: ἀλλ᾽ οὐκ ἀναστήσομαι, ὅπου μὴ δεῖ. ἐλεύθερος γάρ εἰμι καὶ φίλος τοῦ θεοῦ, ἵν᾽ ἑκὼν πείθωμαι αὐτῷ.","st":"4.3"},{"sp":"N","t":"τῶν δ᾽ ἄλλων οὐδενὸς ἀντιποιεῖσθαί με δεῖ, οὐ σώματος, οὐ κτήσεως, οὐκ ἀρχῆς, οὐ φήμης, ἁπλῶς οὐδενός: οὐδὲ γὰρ ἐκεῖνος βούλεταί μ᾽ ἀντιποιεῖσθαι αὐτῶν. εἰ γὰρ ἤθελεν, ἀγαθὰ πεποιήκει αὐτὰ ἂν ἐμοί. νῦν δ᾽ οὐ πεποίηκεν: διὰ τοῦτο οὐδὲν δύναμαι παραβῆναι τῶν ἐντολῶν.’","st":"4.3"},{"sp":"N","t":"τήρει τὸ ἀγαθὸν τὸ σαυτοῦ ἐν παντί, τῶν δ᾽ ἄλλων κατὰ τὸ διδόμενον μέχρι τοῦ εὐλογιστεῖν ἐν αὐτοῖς, τούτῳ μόνῳ ἀρκούμενος. εἰ δὲ μή, δυστυχήσεις, ἀτυχήσεις, κωλυθήσῃ, ἐμποδισθήσῃ.","st":"4.3"},{"sp":"N","t":"οὗτοί εἰσιν οἱ ἐκεῖθεν ἀπεσταλμένοι νόμοι, ταῦτα τὰ διατάγματα: τούτων ἐξηγητὴν δεῖ γενέσθαι, τούτοις ὑποτεταγμένον, οὐ τοῖς Μασουρίου καὶ Κασσίου. πρὸς τοὺς περὶ τὸ ἐν ἡσυχίᾳ διάγειν ἐσπουδακότας. μέμνησο, ὅτι οὐ μόνον ἐπιθυμία ἀρχῆς καὶ πλούτου ταπεινοὺς ποιεῖ καὶ ἄλλοις ὑποτεταγμένους, ἀλλὰ καὶ ἡσυχίας καὶ σχολῆς καὶ ἀποδημίας καὶ φιλολογίας. ἁπλῶς γὰρ οἷον εἂν ᾖ τὸ ἐκτός, ἡ τιμὴ αὐτοῦ ὑποτάσσει ἄλλῳ.","st":"4.3"},{"sp":"N","t":"τί οὖν διαφέρει συγκλήτου ἐπιθυμεῖν ἢ τοῦ μὴ εἶναι συγκλητικόν; τί διαφέρει ἀρχῆς ἐπιθυμεῖν ἢ ἀναρχίας; τί διαφέρει λέγειν ὅτι ‘κακῶς μοί ἐστιν, οὐδὲν ἔχω τί πράξω, ἀλλὰ τοῖς βιβλίοις προσδέδεμαι ὡς νεκρὸς’ ἢ λέγειν ‘κακῶς μοί ἐστιν, οὐκ εὐσχολῶ ἀναγνῶναι;’","st":"4.4"},{"sp":"N","t":"ὡς γὰρ ἀσπασμοὶ καὶ ἀρχὴ τῶν ἐκτός ἐστι καὶ ἀπροαιρέτων, οὕτως καὶ βιβλίον.","st":"4.4"},{"sp":"N","t":"ἢ τίνος ἕνεκα θέλεις ἀναγνῶναι; εἰπέ μοι. εἰ μὲν γὰρ ἐπ᾽ αὐτὸυ καταστρέφεις ἐπ᾽ αὐτὸ τὸ ψυχαγωγηθῆναι ἢ μαθεῖν τι, ψυχρὸς εἶ καὶ ταλαίπωρος. εἰ δ᾽ ἐφ᾽ ὃ δεῖ ἀναφέρεις, τί τοῦτ᾽ ἔστιν ἄλλο ἢ εὔροια; εἰ δέ σοι τὸ ἀναγιγνώσκειν εὔροιαν μὴ περιποιῇ, τί ὄφελος αὐτοῦ;","st":"4.4"},{"sp":"N","t":"— ἀλλὰ περιποιεῖ, φησίν, καὶ διὰ τοῦτο ἀγανακτῶ ὡς ἀπολειπόμενος αὐτοῦ. — καὶ τίς αὕτη ἡ εὔροια, ἣν ὁ τυχὼν ἐμποδίσαι δύναται, οὐ λέγω Καῖσαρ ἢ Καίσαρος φίλος, ἀλλὰ κόραξ, αὐλητής, πυρετός, ἄλλα τρισμύρια; ἡ δ᾽ εὔροια οὐδὲν οὕτως ἔχει ὡς τὸ διηνεκὲς καὶ ἀνεμπόδιστον.","st":"4.4"},{"sp":"N","t":"νῦν καλοῦμαι πράξων τι, ἄπειμι νῦν προσέξων τοῖς μέτροις ἃ δεῖ τηρεῖν, ὅτι αἰδημόνως, ὅτι ἀσφαλῶς, ὅτι δίχα ὀρέξεως καὶ ἐκκλίσεως τῆς πρὸς τὰ ἐκτός,","st":"4.4"},{"sp":"N","t":"καὶ λοιπὸν προσέχω τοῖς ἀνθρώποις, τίνα φασί, πῶς κινοῦνται, καὶ τοῦτο οὐ κακοήθως οὐδ᾽ ἵνα ἔχω ψέγειν ἢ καταγελῶ, ἀλλ᾽ ἐπ᾽ ἐμαυτὸν ἐπιστρέφω, εἰ ταὐτὰ κἀγὼ ἁμαρτάνω. ‘πῶς οὖν παύσωμαι; τότε καὶ ἐγὼ ἡμάρτανον: νῦν δ᾽ οὐκέτι, χάρις τῷ θεῷ.’","st":"4.4"},{"sp":"N","t":"ἄγε, ταῦτα ποιήσας καὶ πρὸς τούτοις γενόμενος χεῖρον ἔργον πεποίηκας ἢ χιλίους στίχους ἀναγνοὺς ἢ γράψας ἄλλους τοσούτους; ὅταν γὰρ ἐσθίῃς, ἄχθῃ, ὅτι μὴ ἀναγιγνώσκεις; οὐκ ἀρκῇ τῷ καθ᾽ ἃ ἀνέγνωκας ἐσθίειν;","st":"4.4"},{"sp":"N","t":"ὅταν λούῃ; ὅταν γυμνάζῃ; διὰ τί οὖν ἐπὶ πάντων οὐχ ὁμαλίζεις, καὶ ὅταν Καίσαρι προσίῃς καὶ ὅταν τῷ δεῖνι; εἰ τὸν ἀπαθῆ τηρεῖς, εἰ τὸν ἀκατάπληκτον,","st":"4.4"},{"sp":"N","t":"εἰ τὸν κατεσταλμένον, εἰ βλέπεις μᾶλλον τὰ γινόμενα ἢ βλέπῃ, εἰ μὴ φθονεῖς τοῖς προτιμωμένοις, εἰ μὴ ἐκπλήσσουσίν σε αἱ ὗλαι, τί σοι λείπει; βιβλία; πῶς ἢ ἐπὶ τί;","st":"4.4"},{"sp":"N","t":"οὐχὶ γὰρ ἐπὶ τὸ βιοῦν παρασκευή τίς ἐστιν αὕτη; τὸ βιοῦν δ᾽ ἐξ ἄλλων τινῶν ἢ τούτων συμπληροῦται. οἷον ἂν εἰ ὁ ἀθλητὴς κλαίῃ εἰς τὸ στάδιον εἰσιών, ὅτι μὴ ἔξω γυμνάζεται.","st":"4.4"},{"sp":"N","t":"τούτων ἕνεκα ἐγυμνάζου, ἐπὶ τοῦτο οἱ ἁλτῆρες, ἡ ἁφή, οἱ νεανίσκοι. καὶ νῦν ἐκεῖνα ζητεῖς, ὅτε τοῦ ἔργου καιρός ἐστιν;","st":"4.4"},{"sp":"N","t":"οἷον εἰ ἐπὶ τοῦ συγκαταθετικοῦ τόπου παρισταμένων φαντασιῶν τῶν μὲν καταληπτικῶν, τῶν δ᾽ ἀκαταλήπτων μὴ ταύτας διακρίνειν θέλοιμεν, ἀλλ᾽ ἀναγιγνώσκειν τὰ Περὶ καταλήψεως.","st":"4.4"},{"sp":"N","t":"τί οὖν τὸ αἴτιον; ὅτι οὐδέποτε τούτου ἕνεκα ἀνέγνωμεν, οὐδέποτε τούτου ἕνεκα ἐγράψαμεν, ἵν᾽ ἐπὶ τῶν ἔργων κατὰ φύσιν χρώμεθα ταῖς προσπιπτούσαις φαντασίαις, ἀλλ᾽ αὐτοῦ καταλήγομεν μαθεῖν, τί λέγεται, καὶ ἄλλῳ δύνασθαι ἐξηγήσασθαι, τὸν συλλογισμὸν ἀναλῦσαι καὶ τὸν ὑποθετικὸν ἐφοδεῦσαι.","st":"4.4"},{"sp":"N","t":"διὰ τοῦτο ὅπου ἡ σπουδή, ἐκεῖ καὶ ὁ ἐμποδισμός. θέλεις τὰ μὴ ἐπὶ σοὶ ἐξ ἅπαντος; κωλύου τοίνυν, ἐμποδίζου, ἀποτύγχανε.","st":"4.4"},{"sp":"N","t":"εἰ δὲ τὰ Περὶ ὁρμῆς τούτου ἕνεκα ἀναγιγνώσκοιμεν, οὐχ ἵνα ἴδωμεν, τί λέγεται περὶ ὁρμῆς, ἀλλ᾽ ἵνα ὁρμῶμεν †: τὰ Περὶ ὀρέξεως δὲ καὶ ἐκκλίσεως, ἵνα μήποτ᾽ ὀρεγόμενοι ἀποτυγχάνωμεν μήτ᾽ ἐκκλίνοντες περιπίπτωμεν: τὰ Περὶ καθήκοντος δ᾽, ἵνα μεμνημένοι τῶν σχέσεων μηδὲν ἀλογίστως μηδὲ παρ᾽ αὐτὰ ποιῶμεν:","st":"4.4"},{"sp":"N","t":"οὐκ ἂν ἠγανακτοῦμεν πρὸς τὰ ἀναγνώσματα ἐμποδιζόμενοι, ἀλλὰ τῷ τὰ ἔργα ἀποδιδόναι τὰ καταάλληλα ἠρκούμεθα καὶ ἠριθμοῦμεν ἂν οὐ ταῦτα, ἃ μέχρι νῦν ἀριθμεῖν εἰθίσμεθα ‘σήμερον ἀνέγνων στίχους τοσούσδε, ἔγραψα τοσούσδε,’","st":"4.4"},{"sp":"N","t":"ἀλλὰ ‘σήμερον ὁρμῇ ἐχρησάμην, ὡς παραγγέλλεται ὑπὸ τῶν φιλοσόφων, ὀρέξει οὐκ ἐχρησάμην, ἐκκλίσει πρὸς μόνα τὰ προαιρετικά, οὐ κατεπλάγην τὸν δεῖνα, οὐκ ἐδυσωπήθην ὑπὸ τοῦ δεῖνος, τὸ ἀνεκτικὸν ἐγύμνασα, τὸ ἀφεκτικόν, τὸ συνεργητικόν’ καὶ οὕτως ἂν ηὐχαριστοῦμεν τῷ θεῷ ἐφ᾽ οἷς δεῖ εὐχαριστεῖν.","st":"4.4"},{"sp":"N","t":"νῦν δ᾽ ἡμεῖς οὐκ ἴσμεν, ὅτι καὶ αὐτοὶ ἄλλον τρόπον ὅμοιοι τοῖς πολλοῖς γινόμεθα. ἄλλος φοβεῖται, μὴ οὐκ ἄρξῃ: σύ, μὴ ἄρξῃς.","st":"4.4"},{"sp":"N","t":"μηδαμῶς, ἄνθρωπε. ἀλλ᾽ ὡς καταγελᾷς τοῦ φοβουμένου μὴ ἄρξαι, οὕτως καὶ σαυτοῦ καταγέλα. οὐδὲν γὰρ διαφέρει ἢ διψῆν πυρέσσοντα ἢ ὡς λυσσώδη ὑδροφόβον εἶναι.","st":"4.4"},{"sp":"N","t":"ἢ πῶς ἔτι δυνήσῃ εἰπεῖν τὸ τοῦ Σωκράτους ‘εἰ ταύτῃ φίλον τῷ θεῷ, ταύτῃ γινέσθω;’ δοκεῖς, Σωκράτης εἰ ἐπεθύμει ἐν Λυκείῳ ἢ ἐν Ἀκαδημείᾳ σχολάζειν καὶ διαλέγεσθαι καθ᾽ ἡμέραν τοῖς νέοις, εὐκόλως ἂν ἐστρατεύσατο ὁσάκις ἐστρατεύσατο; οὐχὶ δ᾽ ὠδύρετ᾽ ἂν καὶ ἔστενεν ‘τάλας ἐγώ, νῦν ἐνθάδ᾽ ἀτυχῶ ἄθλιος δυνάμενος ἐν Λυκείῳ ἡλιάζεσθαι;’","st":"4.4"},{"sp":"N","t":"τοῦτο γάρ σου τὸ ἔργον ἦν, ἡλιάζεσθαι; οὐχὶ δὲ τὸ εὐροεῖν, τὸ ἀκώλυτον εἶναι, τὸ ἀπαραπόδιστον; καὶ πῶς ἂν ἔτι ἦν Σωκράτης, εἰ ταῦτα ὠδύρετο; πῶς ἂν ἔτι ἐν τῇ φυλακῇ παιᾶνας ἔγραφεν;","st":"4.4"},{"sp":"N","t":"ἁπλῶς οὖν ἐκείνου μέμνησο, ὅτι, πᾶν ὃ ἔξω τῆς προαιρέσεως τῆς σαυτοῦ τιμήσεις, ἀπώλεσας τὴν προαίρεσιν. ἔξω δ᾽ ἐστὶν οὐ μόνον ἀρχή, ἀλλὰ καὶ ἀναρχία, οὐ μόνον ἀσχολία, ἀλλὰ καὶ σχολή.","st":"4.4"},{"sp":"N","t":"‘νῦν οὖν ἐμὲ ἐν τῷ θορύβῳ τούτῳ διεξάγειν.’ τί λέγεις θορύβῳ; ἐν πολλοῖς ἀνθρώποις; καὶ τί χαλεπόν; δόξον ἐν Ὀλυμπίᾳ εἶναι, πανήγυριν αὐτὸν ἥγησαι. κἀκεῖ ἄλλος ἄλλο τι κέκραγεν, ἄλλος ἄλλο τι πράσσει, ἄλλος τῷ ἄλλῳ ἐνσείεται. ἐν τοῖς βαλανείοις ὄχλος: καὶ τίς ἡμῶν οὐ χαίρει τῇ πανηγύρει ταύτῃ καὶ ὀδυνώμενος αὐτῆς ἀπαλλάσσεται;","st":"4.4"},{"sp":"N","t":"μὴ γίνου δυσάρεστος μηδὲ κακοστόμαχος πρὸς τὰ γινόμενα. ‘τὸ ὄξος σαπρόν, δριμὺ γάρ:’ ‘τὸ μέλι σαπρόν, ἀνατρέπει γάρ μου τὴν ἕξιν:’ ‘λάχανα οὐ θέλω.’ οὕτως καὶ ‘σχολὴν οὐ θέλω, ἐρημία ἐστίν,’ ‘ὄχλον οὐ θέλω, θόρυβός ἐστιν.’","st":"4.4"},{"sp":"N","t":"ἀλλ᾽ ἂν μὲν οὕτως φέρῃ τὰ πράγματα, ὥστε μόνον ἢ μετ᾽ ὀλίγων διεξαγαγεῖν, ἡσυχίαν αὐτὸ κάλει καὶ χρῶ τῷ πράγματι, εἰς ὃ δεῖ: λάλει σεαυτῷ, γύμναζε τὰς φαντασίας, ἐξεργάζου τὰς προλήψεις. ἂν δ᾽ εἰς ὄχλον ἐμπέσῃς, ἀγῶνα αὐτὸ λέγε, πανήγυριν, ἑορτήν, συνεορτάζειν πειρῶ τοῖς ἀνθρώποις.","st":"4.4"},{"sp":"N","t":"τί γάρ ἐστιν ἥδιον θέαμα τῷ φιλανθρώπῳ ἢ ἄνθρωποι πολλοί; ἵππων ἀγέλας ἢ βοῶν ἡδέως ὁρῶμεν, πλοῖα πολλὰ ὅταν ἴδωμεν, διαχεόμεθα: ἀνθρώπους πολλοὺς βλέπων τις ἀνιᾶται;","st":"4.4"},{"sp":"N","t":"‘ἀλλὰ κατακραυγάζουσί μου.’ οὐκοῦν ἡ ἀκοή σου ἐμποδίζεται. τί οὖν πρὸς σέ; μή τι καὶ δύναμις ἡ ταῖς φαντασίαις χρηστική; καὶ τίς σε κωλύει ὀρέξει καὶ ἐκκλίσει χρῆσθαι κατὰ φύσιν, ὁρμῇ καὶ ἀφορμῇ; ποῖος θόρυβος πρὸς τοῦτο ἱκανός; σὺ μόνον μέμνησο τῶν καθολικῶν:","st":"4.4"},{"sp":"N","t":"‘τί ἐμόν, τί οὐκ ἐμόν; τί μοι δίδοται; τί θέλει με ποιεῖν ὁ θεὸς νῦν, τί οὐ θέλει;’","st":"4.4"},{"sp":"N","t":"πρὸ ὀλίγου χρόνου ἤθελέν σε σχολάζειν, σαυτῷ λαλεῖν, γράφειν περὶ τούτων, ἀναγιγνώσκειν, ἀκούειν, παρασκευάζεσθαι: ἔσχες εἰς τοῦτο ἱκανὸν χρόνον. νῦν σοι λέγει ‘ἐλθὲ ἤδη ἐπὶ τὸν ἀγῶνα, δεῖξον ἡμῖν, τί ἔμαθες, πῶς ἤθλησας. μέχρι τίνος γυμνασθήσῃ μόνος; ἤδη καιρὸς γνῶναί σε, πότερον τῶν ἀξιονίκων εἶ τις ἀθλητῶν ἢ ἐκείνων, οἳ τὴν οἰκουμένην περιέρχονται νικώμενοι.’","st":"4.4"},{"sp":"N","t":"τί οὖν ἀγανακτεῖς; οὐδεὶς ἀγὼν δίχα θορύβου γίνεται. πολλοὺς δεῖ προγυμναστὰς εἶναι, πολλοὺς τοὺς ἐπικραυγάζοντας, πολλοὺς ἐπιστάτας, πολλοὺς θεατάς.","st":"4.4"},{"sp":"N","t":"— ἀλλ᾽ ἐγὼ ἤθελον ἐφ᾽ ἡσυχίας διάγειν. — οἴμωζε τοίνυν καὶ στένε, ὥσπερ ἄξιος εἶ. τίς γὰρ ἄλλη μείζων ταύτης ζημία τῷ ἀπαιδεύτῳ καὶ ἀπειθοῦντι τοῖς θείοις διατάγμασιν ἢ τὸ λυπεῖσθαι, τὸ πενθεῖν, τὸ φθονεῖν, ἁπλῶς τὸ ἀτυχεῖν καὶ δυστυχεῖν; τούτων οὐ θέλεις ἀπαλλάξαι σεαυτόν; καὶ πῶς ἀπαλλάξω;","st":"4.4"},{"sp":"N","t":"— οὐ πολλάκις ἤκουσας, ὅτι ὄρεξιν ἆραί σε δεῖ παντελῶς, τὴν ἔκκλισιν ἐπὶ μόνα τρέψαι τὰ προαιρετικά, ἀφεῖναί σε δεῖ πάντα, τὸ σῶμα, τὴν κτῆσιν, τὴν φήμην, τὰ βιβλία, θόρυβον, ἀρχάς, ἀναρχίαν; ὅπου γὰρ ἂν κλίνῃς, ἐδούλευσας, ὑπετάγης, κωλυτὸς ἐγένου, ἀναγκαστός, ὅλος ἐπ᾽ ἄλλοις.","st":"4.4"},{"sp":"N","t":"ἀλλὰ τὸ Κλεάνθους πρόχειρον ἄγου δέ μ᾽, ὦ Ζεῦ, καὶ σύ γ᾽ ἡ Πεπρωμένη. θέλετ᾽ εἰς Ῥώμην; εἰς Ῥώμην. εἰς Γύαρα; εἰς Γύαρα. εἰς Ἀθήνας; εἰς Ἀθήνας. εἰς φυλακήν; εἰς φυλακήν. ἂν ἅπαξ εἴπῃ","st":"4.4"},{"sp":"N","t":"ς ‘πότε τις εἰς Ἀθήνας ἀπέλθῃ;,’ ἀπώλου. ἀνάγκη γε ταύτην τὴν ὄρεξιν ἀτελῆ μὲν οὖσαν ἀτυχῆ σε ποιεῖν, τελειωθεῖσαν δὲ κενόν, ἐφ᾽ οἷς οὐ δεῖ ἐπαιρόμενον: πάλιν ἂν ἐμποδισθῇς, δυστυχῆ, περιπίπτοντα οἷς οὐ θέλεις.","st":"4.4"},{"sp":"N","t":"ἄφες οὖν ταῦτα πάντα. ‘καλαὶ αἱ Ἀθῆναι.’ ἀλλὰ τὸ εὐδαιμονεῖν κάλλιον πολύ, τὸ ἀπαθῆ εἶναι, τὸ ἀτάραχον, τὸ ἐπὶ μηδενὶ κεῖσθαι τὰ σὰ πράγματα.","st":"4.4"},{"sp":"N","t":"‘θόρυβος ἐν Ῥώμῃ καὶ ἀσπασμοί.’ ἀλλὰ τὸ εὐροεῖν ἀντὶ πάντων τῶν δυσκόλων. εἰ οὖν τούτων καιρός ἐστιν, διὰ τί οὐκ αἴρεις αὐτῶν τὴν ἔκκλισιν; τίς ἀνάγκη ὡς ὄνον ξυλοκοπούμενον ἀχθοφορεῖν;","st":"4.4"},{"sp":"N","t":"εἰ δὲ μή, ὅρα ὅτι δεῖ σε δουλεύειν ἀεὶ τῷ δυναμένῳ σοι διαπράξασθαι τὴν ἔξοδον, τῷ πᾶν ἐμποδίσαι δυναμένῳ κἀκεῖνον θεραπεύειν ὡς Κακοδαίμονα.","st":"4.4"},{"sp":"N","t":"μία ὁδὸς ἐπὶ εὔροιαν （ τοῦτο καὶ ὄρθρου καὶ μεθ᾽ ἡμέραν καὶ νύκτωρ ἔστω πρόχειρον ） , ἀπόστασις τῶν ἀπροαιρέτων, τὸ μηδὲν ἴδιον ἡγεῖσθαι, τὸ παραδοῦναι πάντα τῷ δαιμονίῳ, τῇ τύχῃ, ἐκείνους ἐπιτρόπους αὐτῶν ποιήσασθαι,","st":"4.4"},{"sp":"N","t":"οὓς καὶ ὁ Ζεὺς πεποίηκεν, αὐτὸν δὲ πρὸς ἑνὶ εἶναι μόνῳ, τῷ ἰδίῳ, τῷ ἀκωλύτῳ, καὶ ἀναγιγνώσκειν ἐπὶ τοῦτο ἀναφέροντα τὴν ἀνάγνωσιν καὶ γράφειν καὶ ἀκούειν.","st":"4.4"},{"sp":"N","t":"διὰ τοῦτο οὐ δύναμαι εἰπεῖν φιλόπονον, ἂν ἀκούσω τοῦτο μόνον, ὅτι ἀναγιγνώσκει ἢ γράφει, κἂν προσθῇ τις, ὅτι ὅλας τὰς νύκτας, οὔπω λέγω, ἂν μὴ γνῶ τὴν ἀναφοράν. οὐδὲ γὰρ σὺ λέγεις φιλόπονον τὸν διὰ παιδισκάριον ἀγρυπνοῦντα: οὐ τοίνυν οὐδ᾽ ἐγώ.","st":"4.4"},{"sp":"N","t":"ἀλλ᾽ ἐὰν μὲν ἕνεκα δόξης αὐτὸ ποιῇ, λέγω φιλόδοξον, ἂν δ᾽ ἕνεκα ἀργυρίου, φιλάργυρον, οὐ φιλόπονον.","st":"4.4"},{"sp":"N","t":"ἂν δ᾽ ἐπὶ τὸ ἴδιον ἡγεμονικὸν ἀναφέρῃ τὸν πόνον, ἵν᾽ ἐκεῖνο κατὰ φύσιν ἔχῃ καὶ διεξάγῃ, τότε λέγω μόνον φιλόπονον.","st":"4.4"},{"sp":"N","t":"μηδέποτε γὰρ ἀπὸ τῶν κοινῶν μήτ᾽ ἐπαινεῖτε μήτε ψέγετε, ἀλλὰ ἀπὸ δογμάτων. ταῦτα γάρ ἐστι τὰ ἴδια ἑκάστου, τὰ καὶ τὰς πράξεις αἰσχρὰς ἢ καλὰς ποιοῦντα:","st":"4.4"},{"sp":"N","t":"τούτων μεμνημένος χαῖρε τοῖς παροῦσιν καὶ ἀγάπα ταῦτα, ὧν καιρός ἐστιν.","st":"4.4"},{"sp":"N","t":"εἴ τινα ὁρᾷς, ὧν ἔμαθες καὶ διεσκέψω, ἀπαντῶντά σοι εἰς τὰ ἔργα, εὐφραίνου ἐπ᾽ αὐτοῖς. εἰ τὸ κακόηθες καὶ λοίδορον ἀποτέθεισαι, μεμείωκας, εἰ τὸ προπετές, εἰ τὸ αἰσχρολόγον, εἰ τὸ εἰκαῖον, εἰ τὸ ἐπισεσυρμένον, εἰ οὐ κινῇ ἐφ᾽ οἷς πρότερον, εἰ οὐχ ὁμοίως γ᾽ ὡς πρότερον, ἑορτὴν ἄγειν δύνασαι καθ᾽ ἡμέραν, σήμερον, ὅτι καλῶς ἀνεστράφης ἐν τῷδε τῷ ἔργῳ, αὔριον, ὅτι ἐν ἑτέρῳ. πόσῳ μείζων αἰτία θυσίας ἢ ὑπατ","st":"4.4"},{"sp":"N","t":"εία ἢ ἐπαρχία. ταῦτα ἐκ σοῦ αὐτοῦ γίνεταί σοι καὶ ἀπὸ τῶν θεῶν. ἐκεῖνο μέμνησο, τίς ὁ διδούς ἐστι καὶ τίσιν καὶ διὰ τίνα.","st":"4.4"},{"sp":"N","t":"τούτοις τοῖς διαλογισμοῖς ἐντρεφόμενος ἔτι διαφέρῃ, ποῦ ὢν εὐδαιμονήσεις, ποῦ ὢν ἀρέσεις τῷ θεῷ; οὐ πανταχόθεν τὸ ἴσον ἀπέχουσιν; οὐ πανταχόθεν ὁμοίως ὁρῶσιν τὰ γινόμενα; πρὸς τοὺς μαχίμους καὶ θηριώδεις. ὁ καλὸς καὶ ἀγαθὸς οὔτ᾽ αὐτὸς μάχεταί τινι οὔτ᾽ ἄλλον ἐᾷ κατὰ δύναμιν.","st":"4.4"},{"sp":"N","t":"παράδειγμα δὲ καὶ τούτου καθάπερ καὶ τῶν ἄλλων ἔκκειται ἡμῖν ὁ βίος ὁ Σωκράτους, ὃς οὐ μόνον αὐτὸς πανταχοῦ ἐξέφυγεν μάχην, ἀλλ᾽ οὐδ᾽ ἄλλους μάχεσθαι εἴα.","st":"4.5"},{"sp":"N","t":"ὅρα παρὰ Ξενοφῶντι ἐν τῷ Συμποσίῳ πόσας μάχας λέλυκεν, πῶς πάλιν ἠνέσχετο Θρασυμάχου, πῶς Πώλου, πῶς Καλλικλέους, πῶς τῆς γυναικὸς ἠνείχετο, πῶς τοῦ υἱοῦ ἐξελεγχόμενος ὑπ᾽ αὐτοῦ, σοφιζόμενος.","st":"4.5"},{"sp":"N","t":"λίαν γὰρ ἀσφαλῶς ἐμέμνητο, ὅτι οὐδεὶς ἀλλοτρίου ἡγεμονικοῦ κυριεύει. οὐδὲν οὖν ἄλλο ἤθελεν ἢ τὸ ἴδιον.","st":"4.5"},{"sp":"N","t":"τί δ᾽ ἔστι τοῦτο; οὐχ † ἱκ ... ος οὗτος ... κατὰ φύσιν: τοῦτο γὰρ ἀλλότριον: ἀλλ᾽ ὅπως ἐκείνων τὰ ἴδια ποιούντων, ὡς αὐτοῖς δοκεῖ, αὐτὸς μηδὲν ἧττον κατὰ φύσιν ἕξει καὶ διεξάξει μόνον τὰ αὑτοῦ ποιῶν πρὸς τὸ κἀκείνους ἔχειν κατὰ φύσιν.","st":"4.5"},{"sp":"N","t":"τοῦτο γάρ ἐστιν, ὃ ἀεὶ πρόκειται τῷ καλῷ καὶ ἀγαθῷ. στρατηγῆσαι; οὔ: ἀλλ᾽, ἂν διδῶται, ἐπὶ ταύτης τῆς ὕλης τὸ ἴδιον ἡγεμονικὸν τηρῆσαι. γῆμαι; οὔ: ἄλλ᾽, ἂν διδῶται γάμος, ἐν ταύτῃ τῇ ὕλῃ κατὰ φύσιν ἔχοντα αὑτὸν τηρῆσαι.","st":"4.5"},{"sp":"N","t":"ἂν δὲ θέλῃ τὸν υἱὸν μὴ ἁμαρτάνειν ἢ τὴν γυναῖκα, θέλει τὰ ἀλλότρια μὴ εἶναι ἀλλότρια. καὶ τὸ παιδεύεσθαι, τοῦτ᾽ ἔστιν μανθάνειν τὰ ἴδια καὶ τὰ ἀλλότρια.","st":"4.5"},{"sp":"N","t":"ποῦ οὖν ἔτι μάχης τόπος τῷ οὕτως ἔχοντι; μὴ γὰρ θαυμάζει τι τῶν γινομένων; μὴ γὰρ καινὸν αὐτῷ φαίνεται; μὴ γὰρ οὐ χείρονα καὶ χαλεπώτερα προσδέχεται τὰ παρὰ τῶν φαύλων ἢ ἀποβαίνει αὐτῷ; μὴ γὰρ οὐ κέρδος λογίζεται πᾶν ὅ τι ἀπολείπουσιν τοῦ ἐσχάτου;","st":"4.5"},{"sp":"N","t":"‘ἐλοιδόρησέν σε ὁ δεῖνα.’ πολλὴ χάρις αὐτῷ, ὅτι μὴ ἔπληξεν. ‘ἀλλὰ καὶ ἔπληξεν.’ πολλὴ χάρις, ὅτι μὴ ἔτρωσεν. ‘ἀλλὰ καὶ ἔτρωσεν.’ πολλὴ χάρις, ὅτι μὴ ἀπέκτεινεν.","st":"4.5"},{"sp":"N","t":"πότε γὰρ ἔμαθεν ἢ παρὰ τίνι, ὅτι ἥμερόν ἐστι ζῷον, ὅτι φιλάλληλον, ὅτι μεγάλη βλάβη τῷ ἀδικοῦντι αὐτὴ ἡ ἀδικία; ταῦτα οὖν μὴ μεμαθηκὼς μηδὲ πεπεισμένος, διὰ τί μὴ ἀκολουθήσῃ τῷ φαινομένῳ συμφέροντι;","st":"4.5"},{"sp":"N","t":"‘βέβληκεν ὁ γείτων λίθους.’ μή τι οὖν σὺ ἡμάρτηκας; ‘ἀλλὰ τὰ ἐν οἴκῳ κατεάγη.’ σὺ οὖν σκευάριον εἶ;","st":"4.5"},{"sp":"N","t":"οὔ, ἀλλὰ προαίρεσις. τί οὖν σοι δίδοται πρὸς τοῦτο; ὡς μὲν λύκῳ ἀντιδάκνειν καὶ ἄλλους πλείονας λίθους βάλλειν: ἀνθρώπῳ δ᾽ ἐὰν ζητῇς, ἐπίσκεψαί σου τὸ ταμιεῖον, ἴδε τίνας δυνάμεις ἔχων ἐλήλυθας: μή τι τὴν θηριώδη; μή τι τὴν μνησικακητικήν;","st":"4.5"},{"sp":"N","t":"ἵππος οὖν πότ᾽ ἄθλιός ἐστιν; ὅταν τῶν φυσικῶν δυνάμεων στέρηται: οὐχ ὅταν μὴ δύνηται κοκκύζειν, ἀλλ᾽ ὅταν μὴ τρέχειν. ὁ δὲ κύων; ὅταν πέτεσθαι μὴ δύνηται;","st":"4.5"},{"sp":"N","t":"ἀλλ᾽ ὅταν μὴ ἰχνεύειν. μή ποτ᾽ οὖν οὕτως καὶ ἄνθρωπος δυστυχής ἐστιν οὐχ ὁ μὴ δυνάμενος λέοντας πνίγειν ἢ ἀνδριάντας περιλαμβάνειν （ οὐ γὰρ πρὸς τοῦτο δυνάμεις τινὰς ἔχων ἐλήλυθεν παρὰ τῆς φύσεως ） , ἀλλ᾽ ὁ ἀπολωλεκὼς τὸ εὔγνωμον, ὁ τὸ πιστόν;","st":"4.5"},{"sp":"N","t":"τοῦτον ἔδει συνελθόντας θρηνεῖν, εἰς ὅσα κακὰ ἐλήλυθεν: οὐχὶ μὰ Δία τὸν φύντα ἢ τὸν ἀποθανόντα, ἀλλ᾽ ᾧ ζῶντι συμβεβήκει ἀπολέσαι τὰ ἴδια, οὐ τὰ πατρῷα, τὸ ἀγρίδιον καὶ τὸ οἰκίδιον καὶ τὸ πανδοκεῖον καὶ τὰ δουλάρια （ τούτων γὰρ οὐδὲν ἴδιον τῷ ἀνθρώπῳ ἐστίν, ἀλλὰ πάντα ἀλλότρια, δοῦλα, ὑπεύθυνα ἄλλοτε ἄλλοις διδόμενα ὑπὸ τῶν κυρίων ） , ἀλλὰ τὰ ἀνθρωπικά,","st":"4.5"},{"sp":"N","t":"τοὺς χαρακτῆρας, οὓς ἔχων ἐν τῇ διανοίᾳ ἐλήλυθεν, οἵους καὶ ἐπὶ τῶν νομισμάτων ζητοῦντες, ἂν μὲν εὕρωμεν, δοκιμάζομεν, ἂν δὲ μὴ εὕρωμεν, ῥιπτοῦμεν.","st":"4.5"},{"sp":"N","t":"‘τίνος ἔχει τὸν χαρακτῆρα τοῦτο τὸ τετράσσαρον;’ ‘Τραιανοῦ;’ ‘φέρε.’ ‘Νέρωνος;’ ‘ῥῖψον ἔξω, ἀδόκιμόν ἐστιν, σαπρόν.’ οὕτως καὶ ἐνθάδε. τίνα ἔχει χαρακτῆρα τὰ δόγματα αὐτοῦ; ‘ἥμερον, κοινωνικόν, ἀνεκτικόν, φιλάλληλον.’ φέρε, παραδέχομαι, ποιῶ πολίτην τοῦτον, παραδέχομαι γείτονα, σύμπλουν.","st":"4.5"},{"sp":"N","t":"ὅρα μόνον, μὴ Νερωνιανὸν ἔχει χαρακτῆρα. μή τι ὀργίλος ἐστίν, μή τι μηνιτής, μή τι μεμψίμοιρος; ‘ἂν αὐτῷ φανῇ, πατάσσει τὰς κεφαλὰς τῶν ἀπαντώντων.’","st":"4.5"},{"sp":"N","t":"τί οὖν ἔλεγες, ὅτι ἄνθρωπός ἐστιν; μὴ γὰρ ἐκ ψιλῆς μορφῆς κρίνεται τῶν ὄντων ἕκαστον; ἐπεὶ οὕτως λέγε καὶ τὸ κήρινον μῆλον εἶναι.","st":"4.5"},{"sp":"N","t":"καὶ ὀδμὴν ἔχειν αὐτὸ δεῖ καὶ γεῦσιν: οὐκ ἀρκεῖ ἡ ἐκτὸς περιγραφή. οὐκοῦν οὐδὲ πρὸς τὸν ἄνθρωπον ἡ ῥὶς ἐξαρκεῖ καὶ οἱ ὀφθαλμοί, ἀλλ᾽ ἂν τὰ δόγματα ἔχῃ ἀνθρωπικά.","st":"4.5"},{"sp":"N","t":"οὗτος οὐκ ἀκούει λόγου, οὐ παρακολουθεῖ ἐλεγχόμενος: ὄνος ἐστίν. τούτου τὸ αἰδῆμον ἀπονενέκρωται: ἄχρηστός ἐστιν, πάντα μᾶλλον ἢ ἄνθρωπος. οὗτος ζητεῖ, τίνα ἀπαντήσας λακτίσῃ ἢ δάκῃ: ὥστε οὐδὲ πρόβατον ἢ ὄνος, ἀλλά τί ποτε ἄγριον θηρίον.","st":"4.5"},{"sp":"N","t":"τί οὖν; θέλεις με καταφρονεῖσθαι; — ὑπὸ τίνων; ὑπὸ εἰδότων; καὶ πῶς καταφρονήσουσιν εἰδότες τοῦ πρᾴου, τοῦ αἰδήμονος; ἀλλ᾽ ὑπὸ τῶν ἀγνοούντων; τί σοι μέλει; οὔ τινι γὰρ ἄλλῳ τεχνίτῃ τῶν ἀτέχνων. — ἀλλὰ πολὺ μᾶλλον ἐπιφυήσονταί μοι.","st":"4.5"},{"sp":"N","t":"— τί λέγεις τὸ ἐμοί; δύναταί τις τὴν προαίρεσιν τὴν σὴν βλάψαι ἢ κωλῦσαι ταῖς προσπιπτούσαις φαντασίαις χρῆσθαι ὡς πέφυκεν;","st":"4.5"},{"sp":"N","t":"— οὔ. — τί οὖν ἔτι ταράσσῃ καὶ φοβερὸν σαυτὸν θέλεις ἐπιδεικνύειν; οὐχὶ δὲ παρελθὼν εἰς μέσον κηρύσσεις, ὅτι εἰρήνην ἄγεις πρὸς πάντας ἀνθρώπους, ὅ τι ἂν ἐκεῖνοι ποιῶσι, καὶ μάλιστ᾽ ἐκείνων καταγελᾷς, ὅσοι σε βλάπτειν δοκοῦσιν; ‘ἀνδράποδα ταῦτα οὐκ οἶδεν οὐδὲ τίς εἰμὶ οὐδὲ ποῦ μου τὸ ἀγαθὸν καὶ τὸ κακόν: οὐ πρόσοδος αὐτοῖς πρὸς τὰ ἐμά.’","st":"4.5"},{"sp":"N","t":"οὕτως καὶ ἐχυρὰν πόλιν οἱ οἰκοῦντες καταγελῶσι τῶν πολιορκούντων: ‘νῦν οὗτοι τί πρᾶγμα ἔχουσιν ἐπὶ τῷ μηδενί; ἀσφαλές ἐστιν ἡμῶν τὸ τεῖχος, τροφὰς ἔχομεν ἐπὶ πάμπολυν χρόνον, τὴν ἄλλην ἅπασαν παρασκευήν.’","st":"4.5"},{"sp":"N","t":"ταῦτά ἐστι τὰ πόλιν ἐχυρὰν καὶ ἀνάλωτον ποιοῦντα, ἀνθρώπου δὲ ψυχὴν οὐδὲν ἄλλο ἢ δόγματα. ποῖον γὰρ τεῖχος οὕτως ἰσχυρὸν ἢ ποῖον σῶμα οὕτως ἀδαμάντινον ἢ ποία κτῆσις ἀναφαίρετος ἢ ποῖον ἀξίωμα οὕτως ἀνεπιβούλευτον;","st":"4.5"},{"sp":"N","t":"πάντα πανταχοῦ θνητά, εὐάλωτα, οἷς τισιν τὸν ὁπωσοῦν προσέχοντα πᾶσα ἀνάγκη ταράσσεσθαι, κακελπιστεῖν, φοβεῖσθαι, πενθεῖν, ἀτελεῖς ἔχειν τὰς ὀρέξεις, περιπτωτικὰς ἔχειν τὰς ἐκκλίσεις.","st":"4.5"},{"sp":"N","t":"εἶτα οὐ θέλομεν τὴν μόνην δεδομένην ἡμῖν ἀσφάλειαν ἐχυρὰν ποιεῖν; οὐδ᾽ ἀποστάντες τῶν θνητῶν καὶ δούλων τὰ ἀθάνατα καὶ φύσει ἐλεύθερα ἐκπονεῖν; οὐδὲ μεμνήμεθα, ὅτι οὔτε βλάπτει ἄλλος ἄλλον οὔτε ὠφελεῖ, ἀλλὰ τὸ περὶ ἑκάστου τούτων δόγμα, τοῦτό ἐστι τὸ βλάπτον, τοῦτο τὸ ἀνατρέπον, τοῦτο μάχη, τοῦτο στάσις, τοῦτο πόλεμος;","st":"4.5"},{"sp":"N","t":"Ἐτεοκλέα καὶ Πολυνείκη τὸ πεποιηκὸς οὐκ ἄλλο ἢ τοῦτο, τὸ δόγμα τὸ περὶ τυραννίδος, τὸ δόγμα τὸ περὶ φυγῆς, ὅτι τὸ μὲν ἔσχατον τῶν κακῶν, τὸ δὲ μέγιστον τῶν ἀγαθῶν.","st":"4.5"},{"sp":"N","t":"φύσις δ᾽ αὕτη παντός, τὸ διώκειν τὸ ἀγαθόν, φεύγειν τὸ κακόν: τὸν ἀφαιρούμενον θατέρου καὶ περιβάλλοντα τῷ ἐναντίῳ, τοῦτον ἡγεῖσθαι πολέμιον, ἐπίβουλον, κἂν ἀδελφὸς ᾖ, κἂν υἱός, κἂν πατήρ.","st":"4.5"},{"sp":"N","t":"τοῦ γὰρ ἀγαθοῦ συγγενέστερον οὐδέν: λοιπὸν εἰ ταῦτα ἀγαθὰ καὶ κακά, οὔτε πατὴρ υἱοῖς φίλος οὔτ᾽ ἀδελφὸς ἀδελφῷ, πάντα δὲ πανταχοῦ μεστὰ πολεμίων, ἐπιβούλων, συκοφαντῶν.","st":"4.5"},{"sp":"N","t":"εἰ δ᾽ οἵα δεῖ προαίρεσις, τοῦτο μόνον ἀγαθόν ἐστιν, καὶ οἵα μὴ δεῖ, τοῦτο μόνον κακόν, ποῦ ἔτι μάχη, ποῦ λοιδορία; περὶ τίνων; περὶ τῶν οὐδὲν πρὸς ἡμᾶς; πρὸς τίνας; πρὸς τοὺς ἀγνοοῦντας, πρὸς τοὺς δυστυχοῦντας, πρὸς τοὺς ἠπατημένους περὶ τῶν μεγίστων;","st":"4.5"},{"sp":"N","t":"τούτων Σωκράτης μεμνημένος τὴν οἰκείαν τὴν αὑτοῦ ᾤκει γυναικὸς ἀνεχόμενος τραχυτάτης, υἱοῦ ἀγνώμονος. τραχεῖα γὰρ πρὸς τί ἦν; ἵν᾽ ὕδωρ καταχέῃ τῆς κεφαλῆς ὅσον καὶ θέλει, ἵνα καταπατήσῃ τὸν πλακοῦντα: καὶ τί πρὸς ἐμέ, ἂν ὑπολάβω, ὅτι ταῦτα οὐκ ἔστι πρὸς ἐμέ;","st":"4.5"},{"sp":"N","t":"τοῦτο δ᾽ ἐμὸν ἔργον ἐστὶ καὶ οὔτε τύραννος κωλύσει με θέλοντα οὔτε δεσπότης οὔτε οἱ πολλοὶ τὸν ἕνα οὔθ᾽ ὁ ἰσχυρότερος τὸν ἀσθενέστερον: τοῦτο γὰρ ἀκώλυτον δέδοται ὑπὸ τοῦ θεοῦ ἑκάστῳ.","st":"4.5"},{"sp":"N","t":"ταῦτα τὰ δόγματα ἐν οἰκίᾳ φιλίαν ποιεῖ, ἐν πόλει ὁμόνοιαν, ἐν ἔθνεσιν εἰρήνην, πρὸς θεὸν εὐχάριστον, πανταχοῦ θαρροῦντα, ὡς περὶ τῶν ἀλλοτρίων, ὡς περὶ οὐδενὸς ἀξίων.","st":"4.5"},{"sp":"N","t":"ἀλλ᾽ ἡμεῖς γράψαι μὲν καὶ ἀναγνῶναι ταῦτα καὶ ἀναγιγνωσκόμενα ἐπαινέσαι ἱκανοί, πεισθῆναι δ᾽ οὐδ᾽ ἐγγύς.","st":"4.5"},{"sp":"N","t":"τοιγαροῦν τὸ περὶ τῶν Λακεδαιμονίων λεγόμενον οἴκοι λέοντες, ἐν Ἐφέσῳ δ᾽ ἀλώπεκες καὶ ἐφ᾽ ἡμῶν ἁρμόσει: ἐν σχολῇ λέοντες, ἔξω δ᾽ ἀλώπεκες. πρὸς τοὺς ἐπὶ τῷ ἐλεεῖσθαι ὀδυνωμένους. ἀνιῶμαι, φησίν, ἐλεούμενος. — πότερον οὖν σὸν ἔργον ἐστὶ τὸ ἐλεεῖσθαί σε ἢ τῶν ἐλεούντων; τί δ᾽; ἐπὶ σοί ἐστι τὸ παῦσαι αὐτό; — ἐπ᾽ ἐμοί, ἂν δεικνύω αὐτοῖς μῆ ἄξιον ἐλέου ὄντα ἐμαυτόν.","st":"4.5"},{"sp":"N","t":"— πότερον δ᾽ ἤδη σοι ὑπάρχει τοῦτο, τὸ μὴ εἶναι ἐλέου ἄξιον ἢ οὐχ ὑπάρχει; — δοκῶ ἔγωγε, ὅτι ὑπάρχει. ἀλλ᾽ οὗτοί γ᾽ οὐκ ἐπὶ τούτοις ἐλεοῦσιν, ἐφ᾽ οἷς, εἴπερ ἄρα, ἦν ἄξιον, ἐπὶ τοῖς ἁμαρτανομένοις, ἀλλ᾽ ἐπὶ πενίᾳ καὶ ἀναρχίᾳ καὶ νόσοις καὶ θανάτοις καὶ ἄλλοις τοιούτοις.","st":"4.6"},{"sp":"N","t":"— πότερον οὖν πείθειν παρεσκεύασαι τοὺς πολλούς, ὡς ἄρα οὐδὲν τούτων κακόν ἐστιν, ἀλλ᾽ οἷόν τε καὶ πένητι καὶ † ἄρχοντι καὶ ἀτίμῳ εὐδαιμονεῖν, ἢ σαυτὸν ἐπιδεικνύειν αὐτοῖς πλουτοῦντα καὶ ἄρχοντα;","st":"4.6"},{"sp":"N","t":"τούτων γὰρ τὰ μὲν δεύτερα ἀλαζόνος καὶ ψυχροῦ καὶ οὐδενὸς ἀξίου. καὶ ἡ προσποίησις ὅρα δι᾽ οἵων ἂν γένοιτο: δουλάριά σε χρήσασθαι δεήσει καὶ ἀργυρωμάτια ὀλίγα κεκτῆσθαι καὶ ταῦτα ἐν φανερῷ δεικνύειν, εἰ οἷόν τε, ταὐτὰ πολλάκις καὶ λανθάνειν πειρᾶσθαι ὅτι ταὐτά ἐστιν, καὶ ἱματίδια στιλπνὰ καὶ τὴν ἄλλην πομπὴν καὶ τὸν τιμώμενον ἐπιφαίνειν ὑπὸ τῶν ἐπιφανῶν τούτων καὶ δειπνεῖν πειρᾶσθαι παρ᾽ αὐτοῖς ἢ δοκεῖν γε, ὅτι δειπνεῖς, καὶ περὶ τὸ σῶμα δέ τινα κακοτεχνεῖν, ὡς εὐμορφότερον φαίνεσθαι καὶ γενναιότερον τοῦ ὄντος:","st":"4.6"},{"sp":"N","t":"ταῦτά σε δεῖ μηχανᾶσθαι, εἰ τὴν δευτέραν ὁδὸν ἀπιέναι θέλεις ὥστε μὴ ἐλεεῖσθαι. ἡ πρώτη δὲ καὶ ἀνήνυτος καὶ μακρά, ὃ ὁ Ζεὺς οὐκ ἠδυνήθη ποιῆσαι, τοῦτο αὐτὸ ἐπιχειρεῖν, πάντας ἀνθρώπους πεῖσαι, τίνα ἐστὶν ἀγαθὰ καὶ κακά.","st":"4.6"},{"sp":"N","t":"μὴ γὰρ δέδοταί σοι τοῦτο; ἐκεῖνο μόνον σοι δέδοται, σαυτὸν πεῖσαι. καὶ οὔπω πέπεικας: εἶτά μοι νῦν ἐπιχειρεῖς πείθειν τοὺς ἄλλους;","st":"4.6"},{"sp":"N","t":"καὶ τίς σοι τοσούτῳ χρόνῳ σύνεστιν ὡς σὺ σαυτῷ; τίς δὲ οὕτως πιθανός ἐστί σοι πρὸς τὸ πεῖσαι ὡς σὺ σαυτῷ; τίς δ᾽ εὐνούστερον καὶ οἰκειότερον ἔχων ἢ σὺ σαυτῷ;","st":"4.6"},{"sp":"N","t":"πῶς οὖν οὔπω πέπεικας σαυτὸν μαθεῖν; νῦν οὐχὶ ἄνω κάτω; τοῦτ᾽ ἔστι περὶ ὃ ἐσπούδακας; οὐ μανθάνειν, ὥστε ἄλυπος εἶναι καὶ ἀτάραχος καὶ ἀταπείνωτος καὶ ἐλεύθερος;","st":"4.6"},{"sp":"N","t":"πρὸς ταῦτα οὖν οὐκ ἀκήκοας, ὅτι μία ἐστὶν ἡ ὁδὸς ἡ φέρουσα, ἀφεῖναι τὰ ἀπροαίρετα καὶ ἐκστῆναι αὐτῶν καὶ ὁμολογῆσαι αὐτὰ ἀλλότρια;","st":"4.6"},{"sp":"N","t":"τὸ οὖν ἄλλον τι ὑπολαβεῖν περὶ σοῦ ποίου εἴδους ἐστίν; — τοῦ ἀπροαιρέτου. — οὐκοῦν οὐδὲν πρὸς σέ; — οὐδέν. — ἔτι οὖν δακνόμενος ἐπὶ τούτῳ καὶ ταρασσόμενος οἴει πεπεῖσθαι περὶ ἀγαθῶν καὶ κακῶν;","st":"4.6"},{"sp":"N","t":"οὐ θέλεις οὖν ἀφεὶς τοὺς ἄλλους αὐτὸς σαυτῷ γενέσθαι καὶ μαθητὴς καὶ διδάσκαλος; ‘ὄψονται οἱ ἄλλοι, εἰ λυσιτελεῖ αὐτοῖς παρὰ φύσιν ἔχειν καὶ διεξάγειν, ἐμοὶ δ᾽ οὐδείς ἐστιν ἐγγίων ἐμοῦ.","st":"4.6"},{"sp":"N","t":"τί οὖν τοῦτό ἐστιν, ὅτι τοὺς μὲν λόγους ἀκήκοα τοὺς τῶν φιλοσόφων καὶ συγκατατίθεμαι αὐτοῖς, ἔργῳ δ᾽ οὐδὲν γέγονα κουφότερος; μή τι οὕτως ἀφυής εἰμι; καὶ μὴν περὶ τὰ ἄλλα, ὅσα ἐβουλήθην, οὐ λίαν ἀφυὴς εὑρέθην, ἀλλὰ καὶ γράμματα ταχέως ἔμαθον καὶ παλαίειν καὶ γεωμετρεῖν καὶ συλλογισμοὺς ἀναλύειν.","st":"4.6"},{"sp":"N","t":"μή τι οὖν οὐ πέπεικέ με ὁ λόγος; καὶ μὴν οὐκ ἄλλα τινὰ οὕτως ἐξ ἀρχῆς ἐδοκίμασα ἣ εἱλόμην καὶ νῦν περὶ τούτων ἀναγιγνώσκω, ταῦτα ἀκούω, ταῦτα γράφω: ἄλλον οὐχ εὑρήκαμεν μέχρι νῦν ἰσχυρότερον τούτου λόγον.","st":"4.6"},{"sp":"N","t":"τί οὖν τὸ λεῖπόν μοι ἐστίν; μὴ οὐκ ἐξῄρηται τἀναντία δόγματα; μὴ αὐταὶ αἱ ὑπολήψεις ἀγύμναστοί εἰσιν οὐδ᾽ εἰθισμέναι ἀπαντᾶν ἐπὶ τὰ ἔργα, ἀλλ᾽ ὡς ὁπλάρια ἀποκείμενα κατίωται καὶ οὐδὲ περιαρμόσαι μοι δύναται;","st":"4.6"},{"sp":"N","t":"καίτοι οὔτ᾽ ἐπὶ τοῦ παλαίειν οὔτ᾽ ἐπὶ τοῦ γράφειν ἢ ἀναγιγνώσκειν ἀρκοῦμαι τῷ μαθεῖν, ἀλλ᾽ ἄνω κάτω στρέφω τοὺς προτεινομένους καὶ ἄλλους πλέκω καὶ μεταπίπτοντας ὡσαύτως.","st":"4.6"},{"sp":"N","t":"τὰ δ᾽ ἀναγκαῖα θεωρήματα, ἀφ᾽ ὧν ἔστιν ὁρμώμενον ἄλυπον γενέσθαι, ἄφοβον ἀπαθῆ, ἀκώλυτον, ἐλεύθερον, ταῦτα δ᾽ οὐ γυμνάζω οὐδὲ μελετῶ κατὰ ταῦτα τὴν προσήκουσαν μελέτην.","st":"4.6"},{"sp":"N","t":"εἶτά μοι μέλει, τί οἱ ἄλλοι περὶ ἐμοῦ ἐροῦσιν, εἰ φανοῦμαι αὐτοῖς ἀξιόλογος, εἰ φανοῦμαι εὐδαίμων;’","st":"4.6"},{"sp":"N","t":"ταλαίπωρε, οὐ θέλεις βλέπειν, τί σὺ λέγεις περὶ σαυτοῦ; τίς φαίνῃ σαυτῷ; τίς ἐν τῷ ὑπολαμβάνειν, τίς ἐν τῷ ὀρέγεσθαι, τίς ἐν τῷ ἐκκλίνειν: τίς ἐν ὁρμῇ, παρασκευῇ, ἐπιβολῇ, τοῖς ἄλλοις τοῖς ἀνθρωπικοῖς ἔργοις;","st":"4.6"},{"sp":"N","t":"ἀλλὰ μέλει σοι, εἴ σε ἐλεοῦσιν οἱ ἄλλοι; — ναί: ἀλλὰ παρὰ τὴν ἀξίαν ἐλεοῦμαι. — οὐκοῦν ἐπὶ τούτῳ ὀδυνᾷ; ὁ δέ γε ὀδυνώμενος ἐλεεινός ἐστιν; — ναί. — πῶς οὖν ἔτι παρὰ ἀξίαν ἐλεῇ; αὐτοῖς γὰρ οἷς περὶ τὸν ἔλεον πάσχεις κατασκευάζεις σεαυτὸν ἄξιον τοῦ ἐλεεῖσθαι.","st":"4.6"},{"sp":"N","t":"τί οὖν λέγει Ἀντισθένης; οὐδέποτ᾽ ἤκουσας; ‘βασιλικόν, ὦ Κῦρε, πράττειν μὲν εὖ, κακῶς δ᾽ ἀκούειν.’","st":"4.6"},{"sp":"N","t":"τὴν κεφαλὴν ὑγιᾶ ἔχω καὶ πάντες οἴονται ὅτι κεφαλαλγῶ. τί μοι μέλει; ἀπύρετός εἰμι καὶ ὡς πυρέσσοντί μοι συνάχθονται: ‘τάλας, ἐκ τοσούτου χρόνου οὐ διέλειπες πυρέσσων.’ λέγω καὶ ἐγὼ σκυθρωπάσας ὅτι ‘ναί: ταῖς ἀληθείαις πολὺς ἤδη χρόνος, ἐξ οὗ μοι κακῶς ἐστιν.’ ‘τί οὖν γένηται;’ ὡς ἂν ὁ θεὸς θέλῃ. καὶ ἅμα ὑποκαταγελῶ τῶν οἰκτειρόντων με.","st":"4.6"},{"sp":"N","t":"τί οὖν κωλύει καὶ ἐνταῦθα ὁμοίως; πένης εἰμί, ἀλλὰ ὀρθὸν δόγμα ἔχω περὶ πενίας. τί οὖν μοι μέλει, εἴ μ᾽ ἐπὶ τῇ πενίᾳ ἐλεοῦσιν; οὐκ ἄρχω, ἄλλοι δ᾽ ἄρχουσιν. ἀλλ᾽ ὃ δεῖ ὑπειληφέναι, ὑπείληφα περὶ τοῦ ἄρχειν καὶ μὴ ἄρχειν. ὄψονται οἱ ἐλεοῦντές με,","st":"4.6"},{"sp":"N","t":"ἐγὼ δ᾽ οὔτε πεινῶ οὔτε διψῶ οὔτε ῥιγῶ, ἀλλ᾽ ἀφ᾽ ὧν αὐτοὶ πεινῶσιν ἢ διψῶσιν οἴονται κἀμέ. τί οὖν αὐτοῖς ποιήσω; περιερχόμενος κηρύσσω καὶ λέγω ‘μὴ πλανᾶσθε, ἄνδρες, ἐμοὶ καλῶς ἐστιν: οὔτε πενίας ἐπιστρέφομαι οὔτε ἀναρχίας οὔτε ἁπλῶς ἄλλου οὐδενὸς ἢ δογμάτων ὀρθῶν: ταῦτα ἔχω ἀκώλυτα, οὐδενὸς πεφρόντικα ἔτι;’","st":"4.6"},{"sp":"N","t":"καὶ τίς αὕτη φλυαρία; πῶς ἔτι ὀρθὰ δόγματα ἔχω μὴ ἀρκούμενος τῷ εἶναι ὅς εἰμι, ἀλλ᾽ ἐπτοημένος ὑπὲρ τοῦ δοκεῖν;","st":"4.6"},{"sp":"N","t":"ἀλλ᾽ ἄλλοι πλειόνων τεύξονται καὶ προτιμηθήσονται. — τί οὖν εὐλογώτερον ἢ τοὺς περί τι ἐσπουδακότας ἐν ἐκείνῳ πλεῖον ἔχειν, ἐν ᾧ ἐσπουδάκασιν; περὶ ἀρχὰς ἐσπουδάκασιν, σὺ περὶ δόγματα: καὶ περὶ πλοῦτον, σὺ περὶ τὴν χρῆσιν τῶν φαντασιῶν.","st":"4.6"},{"sp":"N","t":"ὅρα, εἰ ἐν τούτῳ σου πλέον ἔχουσιν, περὶ ὃ σὺ μὲν ἐσπούδακας, ἐκεῖνοι δ᾽ ἀμελοῦσιν: εἰ συγκατατίθενται μᾶλλον περὶ τὰ φυσικὰ μέτρα, εἰ ὀρέγονταί σου ἀναποτευκτότερον, εἰ ἐκκλίνουσιν ἀπεριπτωτότερον, εἰ ἐν ἐπιβολῇ, ἐν προθέσει, εἰ ἐν ὁρμῇ μᾶλλον εὐστοχοῦσιν, εἰ τὸ πρέπον σῴζουσιν ὡς ἄνδρες, ὡς υἱοί, ὡς γονεῖς, εἶθ᾽ ἑξῆς κατὰ τὰ ἄλλα τῶν σχέσεων ὀνόματα.","st":"4.6"},{"sp":"N","t":"εἰ δ᾽ ἄρχουσιν ἐκεῖνοι, σὺ δ᾽ οὐ θέλεις σαυτῷ τὰς ἀληθείας εἰπεῖν, ὅτι σὺ μὲν οὐδὲν τούτου ἕνεκα ποιεῖς, ἐκεῖνοι δὲ πάντα, ἀλογώτατον δὲ τὸν ἐπιμελούμενόν τινος ἔλαττον φέρεσθαι οὐ ἢ τὸν ἀμελοῦντα;","st":"4.6"},{"sp":"N","t":"οὔ, ἀλλ᾽ ἐπειδὴ φροντίζω ἐγὼ δογμάτων ὀρθῶν, εὐλογώτερόν μέ ἐστιν ἄρχειν. — ἐν ᾧ φροντίζεις, ἐν δόγμασιν: ἐν ᾧ δ᾽ ἄλλοι μᾶλλόν σου πεφροντίκασιν, ἐκείνοις παραχώρει. οἷον εἰ διὰ τὸ δόγματα ἔχειν ὀρθὰ ἠξίους τοξεύων μᾶλλον ἐπιτυγχάνειν τῶν τοξοτῶν ἢ χαλκεύων μᾶλλον τῶν χαλκέων.","st":"4.6"},{"sp":"N","t":"ἄφες οὖν τὴν περὶ τὰ δόγματα σπουδὴν καὶ περὶ ἐκεῖνα ἀναστρέφου, ἃ κτήσασθαι θέλεις, καὶ τότε κλαῖε, ἐάν σοι μὴ προχωρῇ: κλαίειν γὰρ ἄξιος εἶ.","st":"4.6"},{"sp":"N","t":"νῦν δὲ πρὸς ἄλλοις γίνεσθαι λέγεις, ἄλλων ἐπιμελεῖσθαι, οἱ πολλοὶ δὲ τοῦτο καλῶς λέγουσιν, ὅτι ἔργον ἔργῳ οὐ κοινωνεῖ.","st":"4.6"},{"sp":"N","t":"ὁ μὲν ἐξ ὄρθρου ἀναστὰς ζητεῖ, τίνα ἐξ οἴκου ἀσπάσηται, τίνι κεχαρισμένον λόγον εἴπῃ, τίνι δῶρον πέμψῃ, πῶς τῷ ὀρχηστῇ ἀρέσῃ, πῶς κακοηθισάμενος ἄλλον ἄλλῳ χαρίσηται.","st":"4.6"},{"sp":"N","t":"ὅταν εὔχηται, περὶ τούτων εὔχεται: ὅταν θύῃ, ἐπὶ τούτοις θύει: τὸ τοῦ Πυθαγόρου μὴ δ᾽ ὕπνον μαλακοῖσιν ἐπ᾽ ὄμμασι προσδέξασθαι ἐνταῦθα παρατέθεικεν.","st":"4.6"},{"sp":"N","t":"‘πῇ παρέβην;’ τῶν πρὸς κολακείαν. ‘τί ἔρεξα;’ μή τι ὡς ἐλεύθερος, μή τι ὡς γενναῖος; κἂν εὕρῃ τι τοιοῦτον, ἐπιτιμᾷ ἑαυτῷ καὶ ἐγκαλεῖ ‘τί γάρ σοι καὶ τοῦτο εἰπεῖν; οὐ γὰρ ἐνῆν ψεύσασθαι; λέγουσιν καὶ οἱ φιλόσοφοι, ὅτι οὐδὲν κωλύει ψεῦδος εἰπεῖν.’","st":"4.6"},{"sp":"N","t":"σὺ δ᾽ εἴπερ ταῖς ἀληθείαις οὐδενὸς ἄλλου πεφρόντικας ἢ χρήσεως οἵας δεῖ φαντασιῶν, εὐθὺς ἀναστὰς ἕωθεν ἐνθυμοῦ ‘τίνα μοι λείπει πρὸς ἀπάθειαν; τίνα πρὸς ἀταραξίαν; τίς εἰμι; μή τι σωμάτιον, μή τι κτῆσις, μή τι φήμη; οὐδὲν τούτων. ἀλλὰ τί;","st":"4.6"},{"sp":"N","t":"λογικόν εἰμι ζῷον.’ τίνα οὖν τὰ ἀπαιτήματα; ἀναπόλει τὰ πεπραγμένα. ‘πῇ παρέβην τῶν πρὸς εὔροιαν; τί ἔρεξα ἢ ἄφιλον ἢ ἀκοινώνητον ἢ ἄγνωμον; τί μοι δέον οὐκ ἐτελέσθη πρὸς ταῦτα;’","st":"4.6"},{"sp":"N","t":"τοσαύτης οὖν διαφορᾶς οὔσης τῶν ἐπιθυμουμένων, τῶν ἔργων, τῶν εὐχῶν ἔτι θέλεις τὸ ἴσον ἔχειν ἐκείνοις, περὶ ἃ σὺ μὲν οὐκ ἐσπούδακας, ἐκεῖνοι δ᾽ ἐσπουδάκασιν;","st":"4.6"},{"sp":"N","t":"εἶτα θαυμάζεις, εἴ σ᾽ ἐλεοῦσιν, καὶ ἀγανακτεῖς; ἐκεῖνοι δ᾽ οὐκ ἀγανακτοῦσιν, εἰ σὺ αὐτοὺς ἐλεεῖς. διὰ τί; ὅτι ἐκεῖνοι μὲν πεπεισμένοι εἰσίν, ὅτι ἀγαθῶν τυγχάνουσιν, σὺ δ᾽ οὐ πέπεισαι.","st":"4.6"},{"sp":"N","t":"διὰ τοῦτο σὺ μὲν οὐκ ἀρκῇ τοῖς σοῖς, ἀλλ᾽ ἐφίεσαι τῶν ἐκείνων: ἐκεῖνοι δ᾽ ἀρκοῦνται τοῖς ἑαυτῶν καὶ οὐκ ἐφίενται τῶν σῶν. ἐπεί τοι εἰ ταῖς ἀληθείαις ἐπέπεισο, ὅτι περὶ τὰ ἀγαθὰ σὺ ὁ ἐπιτυγχάνων εἶ, ἐκεῖνοι δ᾽ ἀποπεπλάνηνται, οὐδ᾽ ἂν ἐνεθυμοῦ, τί λέγουσι περὶ σοῦ. περὶ ἀφοβίας. τί ποιεῖ φοβερὸν τὸν τύραννον; — οἱ δορυφόροι, φησίν, καὶ αἱ μάχαιραι αὐτῶν καὶ ὁ ἐπὶ τοῦ κοιτῶνος καὶ οἱ ἀποκλείοντες τοὺς εἰσιόντας.","st":"4.6"},{"sp":"N","t":"— διὰ τί οὖν, ἂν παιδίον αὐτῷ προσαγάγῃς μετὰ τῶν δορυφόρων ὄντι, οὐ φοβεῖται; ἢ ὅτι οὐκ αἰσθάνεται τούτων τὸ παιδίον;","st":"4.7"},{"sp":"N","t":"ἂν οὖν τῶν δορυφόρων τις αἰσθάνηται καὶ ὅτι μαχαίρας ἔχουσιν, ἐπ᾽ αὐτὸ δὲ τοῦτο προσέρχηται αὐτῷ θέλων ἀποθανεῖν διά τινα περίστασιν καὶ ζητῶν ὑπ᾽ ἄλλου παθεῖν αὐτὸ εὐκόλως, μή τι φοβεῖται τοὺς δορυφόρους; — θέλει γὰρ τοῦτο, δι᾽ ὃ φοβεροί εἰσιν. —","st":"4.7"},{"sp":"N","t":"ἂν οὖν τις μήτ᾽ ἀποθανεῖν μήτε ζῆν θέλων ἐξ ἅπαντος ἀλλ᾽ ὡς ἂν διδῶται, προσέρχηται αὐτῷ, τί κωλύει μὴ δεδοικότα προσέρχεσθαι αὐτόν;","st":"4.7"},{"sp":"N","t":"— οὐδέν. — ἄν τις οὖν καὶ πρὸς τὴν κτῆσιν ὡσαύτως ἔχῃ καθάπερ οὗτος πρὸς τὸ σῶμα καὶ πρὸς τὰ τέκνα καὶ τὴν γυναῖκα καὶ ἁπλῶς ὑπό τινος μανίας καὶ ἀπονοίας οὕτως ᾖν διακείμενος, ὥστ᾽ ἐν μηδενὶ ποιεῖσθαι τὸ ἔχειν ταῦτα ἢ μὴ ἔχειν, ἀλλ᾽ ὡς ὀστρακίοις τὰ παιδία παίζοντα περὶ μὲν τῆς παιδιᾶς διαφέρεται, τῶν ὀστρακίων δ᾽ οὐ πεφρόντικεν, οὕτως δὲ καὶ οὗτος τὰς μὲν ὕλας παρ᾽ οὐδὲν ᾖν πεποιημένος, τὴν παιδιὰν δὲ τὴν περὶ αὐτὰς καὶ ἀναστροφὴν ἀσπάζηται: ποῖος ἔτι τούτῳ τύραννος φοβερὸς ἢ ποῖοι δορυφόροι ἢ ποῖαι μάχαιραι αὐτῶν;","st":"4.7"},{"sp":"N","t":"εἶτα ὑπὸ μανίας μὲν δύναταί τις οὕτως διατεθῆναι πρὸς ταῦτα καὶ ὑπὸ ἔθους οἱ Γαλιλαῖοι: ὑπὸ λόγου δὲ καὶ ἀποδείξεως οὐδεὶς δύναται μαθεῖν, ὅτι ὁ θεὸς πάντα πεποίηκεν τὰ ἐν τῷ κόσμῳ καὶ αὐτὸν τὸν κόσμον ὅλον μὲν ἀκώλυτον καὶ αὐτοτελῆ, τὰ ἐν μέρει δ᾽ αὐτοῦ πρὸς χρείαν τῶν ὅλων;","st":"4.7"},{"sp":"N","t":"τὰ μὲν οὖν ἄλλα πάντα ἀπήλλακται τοῦ δύνασθαι παρακολουθεῖν τῇ διοικήσει αὐτοῦ: τὸ δὲ λογικὸν ζῷον ἀφορμὰς ἔχει πρὸς ἀναλογισμὸν τούτων ἁπάντων, ὅτι τε μέρος ἐστὶ καὶ ποῖόν τι μέρος καὶ ὅτι τὰ μέρη τοῖς ὅλοις εἴκειν ἔχει καλῶς.","st":"4.7"},{"sp":"N","t":"πρὸς τούτοις δὲ φύσει γενναῖον καὶ μεγαλόψυχον καὶ ἐλεύθερον γενόμενον ὁρᾷ, διότι τῶν περὶ αὐτὸ τὰ μὲν ἀκώλυτα ἔχει καὶ ἐπ᾽ αὐτῷ, τὰ δὲ κωλυτὰ καὶ ἐπ᾽ ἄλλοις: ἀκώλυτα μὲν τὰ προαιρετικά, κωλυτὰ δὲ τὰ ἀπροαίρετα. καὶ διὰ τοῦτο,","st":"4.7"},{"sp":"N","t":"ἐὰν μὲν ἐν τούτοις μόνοις ἡγήσηται τὸ ἀγαθὸν τὸ αὑτοῦ καὶ συμφέρον, τοῖς ἀκωλύτοις καὶ ἐφ᾽ ἑαυτῷ, ἐλεύθερον ἔσται, εὔρουν, εὔδαιμον, ἀβλαβές, μεγαλόφρον, εὐσεβές, χάριν ἔχον ὑπὲρ πάντων τῷ θεῷ, μηδαμοῦ μεμφόμενον μηδενὶ τῶν γενομένων, μηδενὶ ἐγκαλοῦν:","st":"4.7"},{"sp":"N","t":"ἂν δ᾽ ἐν τοῖς ἐκτὸς καὶ ἀπροαιρέτοις, ἀνάγκη κωλύεσθαι αὐτό, ἐμποδίζεσθαι, δουλεύειν τοῖς ἐκείνων ἔχουσιν ἐξουσίαν,","st":"4.7"},{"sp":"N","t":"ἃ τεθαύμακεν καὶ φοβεῖται, ἀνάγκη δ᾽ ἀσεβὲς εἶναι ἅτε βλάπτεσθαι οἰόμενον ὑπὸ τοῦ θεοῦ καὶ ἄνισον, ἀεὶ αὑτῷ τοῦ πλείονος περιποιητικόν, ἀνάγκη δὲ καὶ ταπεινὸν εἶναι καὶ μικροπρεπές.","st":"4.7"},{"sp":"N","t":"ταῦτα τί κωλύει διαλαβόντα ζῆν κούφως καὶ εὐηνίως, πάντα τὰ συμβαίνειν δυνάμενα πρᾴως ἐκδεχόμενον, τὰ δ᾽ ἤδη συμβεβηκότα φέροντα;","st":"4.7"},{"sp":"N","t":"‘θέλεις πενίαν;’ φέρε καὶ γνώσῃ, τί ἐστι πενία τυχοῦσα καλοῦ ὑποκριτοῦ.","st":"4.7"},{"sp":"N","t":"‘θέλεις ἀρχάς;’ φέρε, καὶ πόνους. ‘ἀλλ᾽ ἐξορισμόν;’ ὅπου ἂν ἀπέλθω, ἐκεῖ μοι καλῶς ἔσται: καὶ γὰρ ἐνθάδε οὐ διὰ τὸν τόπον ἦν μοι καλῶς, ἀλλὰ διὰ τὰ δόγματα, ἃ μέλλω μετ᾽ ἐμαυτοῦ ἀποφέρειν. οὐδὲ γὰρ δύναταί τις ἀφελέσθαι αὐτά, ἀλλὰ ταῦτα μόνα ἐμά ἐστι καὶ ἀναφαίρετα καὶ ἀρκεῖ μοι παρόντα, ὅπου ἂν ὦ καὶ ὅ τι ἂν ποιῶ.","st":"4.7"},{"sp":"N","t":"‘ἀλλ᾽ ἤδη καιρὸς ἀποθανεῖν.’ τί λέγεις ἀποθανεῖν; μὴ τραγῴδει τὸ πρᾶγμα, ἀλλ᾽ εἰπὲ ὡς ἔχει ‘ἤδη καιρὸς τὴν ὕλην, ἐξ ὧν συνῆλθεν, εἰς ἐκεῖνα πάλιν ἀποκαταστῆναι.’ καὶ τί δεινόν; τί μέλλει ἀπόλλυσθαι τῶν ἐν τῷ κόσμῳ, τί γενέσθαι καινόν, παράλογον; τούτων ἕνεκα φοβερός ἐστιν ὁ τύραννος;","st":"4.7"},{"sp":"N","t":"διὰ ταῦτα οἱ δορυφόροι μεγάλας δοκοῦσιν ἔχειν τὰς μαχαίρας καὶ ὀξείας; ἄλλοις ταῦτα: ἐμοὶ δ᾽ ἔσκεπται περὶ πάντων, εἰς ἐμὲ οὐδεὶς ἐξουσίαν ἔχει.","st":"4.7"},{"sp":"N","t":"ἠλευθέρωμαι ὑπὸ τοῦ θεοῦ, ἔγνωκα αὐτοῦ τὰς ἐντολάς, οὐκέτι οὐδεὶς δουλαγωγῆσαί με δύναται, καρπιστὴν ἔχω οἷον δεῖ, δικαστὰς οἵους δεῖ.","st":"4.7"},{"sp":"N","t":"‘οὐχὶ τοῦ σώματός σου κύριός εἰμι;’ τί οὖν πρὸς ἐμέ; ‘οὐχὶ τοῦ κτησιδίου;’ τί οὖν πρὸς ἐμέ; ‘οὐχὶ φυγῆς ἢ δεσμῶν;’ πάλιν τούτων πάντων καὶ τοῦ σωματίου ὅλου σοι αὐτοῦ ἐξίσταμαι, ὅταν θέλῃς. πείρασαί μοί σου τῆς ἀρχῆς καὶ γνώσῃ, μέχρι τίνος αὐτὴν ἔχεις.","st":"4.7"},{"sp":"N","t":"τίνα οὖν ἔτι φοβηθῆναι δύναμαι; τοὺς ἐπὶ τοῦ κοιτῶνος; μὴ τί ποιήσωσιν; ἀποκλείσωσί με; ἄν με εὕρωσι θέλοντα εἰσελθεῖν, ἀποκλεισάτωσαν. — τί οὖν ἔρχῃ ἐπὶ θύρας; — ὅτι καθήκειν ἐμαυτῷ δοκῶ μενούσης τῆς παιδιᾶς συμπαίζειν.","st":"4.7"},{"sp":"N","t":"— πῶς οὖν οὐκ ἀποκλείῃ; — ὅτι ἂν μή τίς με δέχηται, οὐ θέλω εἰσελθεῖν, ἀλλ᾽ ἀεὶ μᾶλλον ἐκεῖνο θέλω τὸ γινόμενον. κρεῖττον γὰρ ἡγοῦμαι ὃ ὁ θεὸς θέλει ἢ ὃ ἐγώ. προσκείσομαι διάκονος καὶ ἀκόλουθος ἐκείνῳ, συνορμῶ, συνορέγομαι, ἁπλῶς συνθέλω. ἀποκλεισμὸς ἐμοὶ οὐ γίνεται, ἀλλὰ τοῖς βιαζομένοις.","st":"4.7"},{"sp":"N","t":"διὰ τί οὖν οὐ βιάζομαι; οἶδα γάρ, ὅτι ἔσω ἀγαθὸν οὐδὲν διαδίδοται τοῖς εἰσελθοῦσιν. ἀλλ᾽ ὅταν ἀκούσω τινὰ μακαριζόμενον, ὅτι τιμᾶται ὑπὸ τοῦ Καίσαρος, λέγω ‘τί αὐτῷ συμβαίνει; μή τι οὖν καὶ δόγμα, οἷον δεῖ ἐπαρχίαν; μή τι οὖν καὶ τὸ χρῆσθαι ἐπιτροπῇ;","st":"4.7"},{"sp":"N","t":"τί ἔτι διωθοῦμαι; ἰσχαδοκάρυά τις διαρριπτεῖ: τὰ παιδία ἁρπάζει καὶ ἀλλήλοις διαμάχεται: οἱ ἄνδρες οὐχί, μικρὸν γὰρ αὐτὸ ἡγοῦνται. ἂν δ᾽ ὀστράκια διαρριπτῇ τις, οὐδὲ τὰ παιδία ἁρπάζει.","st":"4.7"},{"sp":"N","t":"ἐπαρχίαι διαδίδονται: ὄψεται τὰ παιδία. ἀργύριον: ὄψεται τὰ παιδία. στρατηγία, ὑπατεία: διαρπαζέτω τὰ παιδία: ἐκκλειέσθω, τυπτέσθω, καταφιλείτω τὰς χεῖρας τοῦ διδόντος, τῶν δούλων: ἐμοὶ δ᾽ ἰσχαδοκάρυόν ἐστιν.’","st":"4.7"},{"sp":"N","t":"τί οὖν, ἂν ἀπὸ τύχης ῥιπτοῦντος αὐτοῦ ἔλθῃ εἰς τὸν κόλπον ἰσχάς; ἄρας κατάφαγε: μέχρι τοσούτου γὰρ ἔστι καὶ ἰσχάδα τιμῆσαι. ἵνα δὲ κρύψω καὶ ἄλλον ἀνατρέψω ἢ ὑπ᾽ ἄλλου ἀνατραπῶ καὶ κολακεύσω τοὺς εἰσιόντας, οὐκ ἀξία οὔτ᾽ ἰσχὰς οὔτ᾽ ἄλλο τι τῶν οὐκ ἀγαθῶν, ἅ με ἀναπεπείκασιν οἱ φιλόσοφοι μὴ δοκεῖν ἀγαθὰ εἶναι. δείκνυέ μοι τὰς μαχαίρας τῶν δορυφόρων.","st":"4.7"},{"sp":"N","t":"‘ἰδοῦ, ἡλίκαι εἰσὶ καὶ πῶς ὀξεῖαι.’ τί οὖν ποιοῦσιν αἱ μεγάλαι αὗται μάχαιραι καὶ ὀξεῖαι;","st":"4.7"},{"sp":"N","t":"‘ἀποκτειννύουσιν.’ πυρετὸς δὲ τί ποιεῖ; ‘ἄλλο οὐδέν.’ κεραμὶς δὲ τί ποιεῖ; ‘ἄλλο οὐδέν.’ θέλεις οὖν πάντα ταῦτα θαυμάζω καὶ προσκυνῶ καὶ δοῦλος πάντων περιέρχωμαι;","st":"4.7"},{"sp":"N","t":"μὴ γένοιτο: ἀλλ᾽ ἅπαξ μαθών, ὅτι τὸ γενόμενον καὶ φθαρῆναι δεῖ, ἵνα ὁ κόσμος μὴ ἵστηται μηδ᾽ ἐμποδίζηται, οὐκέτι διαφέρομαι, πότερον πυρετὸς αὐτὸ ποιήσει ἢ κεραμὶς ἢ στρατιώτης, ἀλλ᾽ εἰ δεῖ συγκρῖναι, οἶδ᾽ ὅτι ἀπονώτερον αὐτὸ καὶ ταχύτερον ὁ στρατιώτης ποιήσει.","st":"4.7"},{"sp":"N","t":"ὅταν οὖν μήτε φοβῶμαί τι ὧν διαθεῖναί με δύναται μήτ᾽ ἐπιθυμῶ τινος ὧν παρασχεῖν, τί ἔτι θαυμάζω αὐτόν, τί ἔτι τέθηπα; τί φοβοῦμαι τοὺς δορυφόρους; τί χαίρω, ἄν μοι φιλανθρώπως λαλήσῃ καὶ ἀποδέξηταί με, καὶ ἄλλοις διηγοῦμαι, πῶς μοι ἐλάλησεν;","st":"4.7"},{"sp":"N","t":"μὴ γὰρ Σωκράτης ἐστίν, μὴ γὰρ Διογένης, ἵν᾽ ὁ ἔπαινος αὐτοῦ ἀπόδειξις ᾖ περὶ ἐμοῦ;","st":"4.7"},{"sp":"N","t":"μὴ γὰρ τὸ ἦθος ἐζήλωκα αὐτοῦ; ἀλλὰ τὴν παιδιὰν σῴζων ἔρχομαι πρὸς εμαὐτὸν καὶ ὑπηρετῶ, μέχρις ἂν ὅτου μηδὲν ἀβέλτερον κελεύῃ μηδ᾽ ἄρρυθμον. ἂν δέ μοι λέγῃ ‘ἄπελθε ἐπὶ Λέοντα τὸν Σαλαμίνιον,’ λέγω αὐτῷ","st":"4.7"},{"sp":"N","t":"‘ζήτει ἄλλον: ἐγὼ γὰρ οὐκέτι παίζω.’ ‘ἄπαγε αὐτόν.’ ἀκολουθῶ ἐν παιδιᾷ. ‘ἀλλ᾽ ἀφαιρεῖταί σου ὁ τράχηλος.’ ἐκείνου δ᾽ αὐτοῦ ἀεὶ ἐπιμένει, ὑμῶν δὲ τῶν πειθομένων; ‘ἀλλ᾽ ἄταφος ῥιφήσῃ.’ εἰ ἐγώ εἰμι ὁ νεκρός, ῥιφήσομαι: εἰ δ᾽ ἄλλος εἰμὶ τοῦ νεκροῦ, κομψότερον λέγε, ὡς ἔχει τὸ πρᾶγμα, καὶ μὴ ἐκφόβει με.","st":"4.7"},{"sp":"N","t":"τοῖς παιδίοις ταῦτα φοβερά ἐστι καὶ τοῖς ἀνοήτοις. εἰ δέ τις εἰς φιλοσόφου σχολὴν ἅπαξ εἰσελθὼν οὐκ οἶδεν, τί ἐστιν αὐτός, ἄξιός ἐστι φοβεῖσθαι καὶ κολακεύειν ὃ † ὕστερον ἐκολάκευεν: εἰ μήπω μεμάθηκεν, ὅτι οὐκ ἔστι σὰρξ οὐδ᾽ ὀστᾶ οὐδὲ νεῦρα, ἀλλὰ τὸ τούτοις χρώμενον, τὸ καὶ διοικοῦν καὶ παρακολουθοῦν ταῖς φαντασίαις.","st":"4.7"},{"sp":"N","t":"ναί: ἀλλ᾽ οἱ λόγοι οὗτοι καταφρονητὰς ποιοῦσι τῶν νόμων. — καὶ ποῖοι μᾶλλον λόγοι πειθομένους παρέχουσι τοῖς νόμοις τοὺς χρωμένους; νόμος δ᾽ οὐκ ἔστι τὰ ἐπὶ μωρῷ.","st":"4.7"},{"sp":"N","t":"καὶ ὅμως ὅρα, πῶς καὶ πρὸς τούτους ὡς δεῖ ἔχοντας παρασκευάζουσιν, οἵ γε διδάσκουσιν μηδενὸς ἀντιποιεῖσθαι πρὸς αὐτούς, ἐν οἷς ἂν ἡμᾶς νικῆσαι δύνωνται.","st":"4.7"},{"sp":"N","t":"περὶ τὸ σωμάτιον διδάσκουσιν ἐξίστασθαι, περὶ τὴν κτῆσιν ἐξίστασθαι, περὶ τὰ τέκνα, γονεῖς δ᾽, ἀδελφούς, πάντων παραχωρεῖν, πάντα ἀφιέναι: μόνα τὰ δόγματα ὑπεξαιροῦνται, ἃ καὶ ὁ Ζεὺς ἐξαίρετα ἑκάστου εἶναι ἠθέλησεν.","st":"4.7"},{"sp":"N","t":"ποία ἐνθάδε παρανομία, ποία ἀβελτερία; ὅπου κρείττων εἶ καὶ ἰσχυρότερος, ἐκεῖ σοι ἐξίσταμαι: ὅπου πάλιν ἐγὼ κρείττων, σὺ παραχώρει μοι. ἐμοὶ γὰρ μεμέληκεν, σοὶ δ᾽ οὔ.","st":"4.7"},{"sp":"N","t":"σοὶ μέλει, πῶς ἐν ὀρθοστρώτοις οἰκῇς, ἔτι πῶς παῖδές σοι καὶ πιλλᾶτοι διακονῶσιν, πῶς ἐσθῆτα περίβλεπτον φορῇς, πῶς κυνηγοὺς πολλοὺς ἔχῃς, πῶς κιθαρῳδούς, τραγῳδούς.","st":"4.7"},{"sp":"N","t":"μή τι ἀντιποιοῦμαι; μή τι οὖν δογμάτων σοι μεμέληκε; μή τι τοῦ λόγου τοῦ σεαυτοῦ; μή τι οἶδας, ἐκ τίνων μορίων συνέστηκεν, πῶς συνάγεται, τίς ἡ διάρθρωσις αὐτοῦ, τίνας ἔχει δυνάμεις καὶ ποίας τινάς;","st":"4.7"},{"sp":"N","t":"τί οὖν ἀγανακτεῖς, εἰ ἄλλος ἐν τούτοις σου πλέον ἔχει ὁ μεμελετηκώς; — ἀλλὰ ταῦτ᾽ ἔστι τὰ μέγιστα. — καὶ τίς σε κωλύει περὶ ταῦτ᾽ ἀναστρέφεσθαι καὶ τούτων ἐπιμελεῖσθαι; τίς δὲ μείζονα ἔχει παρασκευὴν βιβλίων, εὐσχολίας, τῶν ὠφελησόντων; μόνον ἀπόνευσόν ποτε ἐπὶ ταῦτα,","st":"4.7"},{"sp":"N","t":"ἀπόνειμον κἂν ὀλίγον χρόνον τῷ σαυτοῦ ἡγεμονικῷ: σκέψαι τί ποτ᾽ ἔχεις τοῦτο καὶ πόθεν ἐληλυθός, τὸ πᾶσιν τοῖς ἄλλοις χρώμενον, πάντα τἆλλα δοκιμάζον, ἐκλεγόμενον, ἀπεκλεγόμενον.","st":"4.7"},{"sp":"N","t":"μέχρι δ᾽ ἂν οὗ περὶ τὰ ἐκτὸς ἀναστρέφῃ, ἐκεῖνα ἕξεις οἷα οὐδείς, τοῦτο δ᾽ οἷον αὐτὸ ἔχειν θέλεις, ῥυπαρὸν καὶ ἀτημέλητον. πρὸς τοὺς ταχέως ἐπὶ τὸ σχῆμα τῶν φιλοσόφων ἐπιπηδῶντας. μηδέποτ᾽ ἀπὸ τῶν κοινῶν τινα μήτ᾽ ἐπαινέσητε μήτε ψέξητε μήτε τέχνην τινὰ ἢ ἀτεχνίαν προσμαρτυρήσητε: καὶ ἅμα μὲν προπετείας ἑαυτοὺς ἀπαλλάξετε, ἅμα δὲ κακοηθείας.","st":"4.7"},{"sp":"N","t":"‘οὗτος ταχέως λούεται.’ κακῶς οὖν ποιεῖ; οὐ πάντως.","st":"4.8"},{"sp":"N","t":"ἀλλὰ τί; ταχέως λούεται. — πάντα οὖν καλῶς γίνεται; — οὐδαμῶς: ἀλλὰ τὰ μὲν ἀπὸ δογμάτων ὀρθῶν καλῶς, τὰ δ᾽ ἀπὸ μοχθηρῶν μοχθηρῶς. σὺ δὲ μέχρις ἂν καταμάθῃς τὸ δόγμα, ἀφ᾽ οὗ τις ποιεῖ ἕκαστα, μήτ᾽ ἐπαίνει τὸ ἔργον μήτε ψέγε.","st":"4.8"},{"sp":"N","t":"δόγμα δ᾽ ἐκ τῶν ἐκτὸς οὐ ῥᾳδίως κρίνεται. ‘οὗτος τέκτων ἐστίν.’ διὰ τί; ‘χρῆται σκεπάρνῳ.’ τί οὖν τοῦτο; ‘οὗτος μουσικός: ᾁδει γάρ.’ καὶ τί τοῦτο; ‘οὗτος φιλόσοφος.’ διὰ τί;","st":"4.8"},{"sp":"N","t":"‘τρίβωνα γὰρ ἔχει καὶ κόμην.’ οἱ δ᾽ ἀγύρται τί ἔχουσιν; διὰ τοῦτο, ἂν ἀσχημονοῦντά τις ἴδῃ τινὰ αὐτῶν, εὐθὺς λέγει ‘ἰδοὺ ὁ φιλόσοφος τί ποιεῖ.’ ἔδει δ᾽ ἀφ᾽ ὧν ἠσχημόνει μᾶλλον λέγειν αὐτὸν μὴ εἶναι φιλόσοφον.","st":"4.8"},{"sp":"N","t":"εἰ μὲν γὰρ αὕτη ἐστὶν ἡ τοῦ φιλοσόφου πρόληψις καὶ ἐπαγγελία, ἔχειν τρίβωνα καὶ κόμην, καλῶς ἂν ἔλεγον: εἰ δ᾽ ἐκείνη μᾶλλον, ἀναμάρτητον εἶναι, διὰ τί οὐχὶ διὰ τὸ μὴ πληροῦν τὴν ἐπαγγελίαν ἀφαιροῦνται αὐτὸν τῆς προσηγορίας;","st":"4.8"},{"sp":"N","t":"οὕτως γὰρ καὶ ἐπὶ τῶν ἄλλων τεχνῶν. ὅταν ἴδῃ τις κακῶς πελεκῶντα, οὐ λέγει ‘τί ὄφελος τεκτονικῆς; ἰδοὺ οἱ τέκτονες οἷα ποιοῦσι κακά,’ ἀλλὰ πᾶν τοὐναντίον λέγει ‘οὗτος οὐκ ἔστι τέκτων, πελεκᾷ γὰρ κακῶς.’","st":"4.8"},{"sp":"N","t":"ὁμοίως κἂν ᾁδοντός τινος ἀκούσῃ κακῶς, οὐ λέγει ‘ἰδοὺ πῶς ᾁδουσιν οἱ μουσικοί,’ ἀλλὰ μᾶλλον","st":"4.8"},{"sp":"N","t":"‘οὗτος ὅτι οὐκ ἔστι μουσικός.’ ἐπὶ φιλοσοφίας δὲ μόνης τοῦτο πάσχουσιν: ὅταν τινὰ ἴδωσι παρὰ τὸ ἐπάγγελμα τὸ τοῦ φιλοσόφου ποιοῦντα, οὐχὶ τῆς προσηγορίας ἀφαιροῦνται αὐτόν, ἀλλὰ θέντες εἶναι φιλόσοφον, εἶτ᾽ ἀπ᾽ αὐτοῦ τοῦ γινομένου λαβόντες, ὅτι ἀσχημονεῖ, ἐπάγουσι μηδὲν ὄφελος εἶναι τοῦ φιλοσοφεῖν. τί οὖν τὸ αἴτιον;","st":"4.8"},{"sp":"N","t":"ὅτι τὴν μὲν τοῦ τέκτονος πρόληψιν πρεσβεύομεν καὶ τὴν τοῦ μουσικοῦ καὶ ὡσαύτως τῶν ἄλλων τεχνιτῶν, τὴν τοῦ φιλοσόφου δ᾽ οὔ, ἀλλ᾽ ἅτε συγκεχυμένην καὶ ἀδιάρθρωτον ἀπὸ τῶν ἐκτὸς μόνον κρίνομεν.","st":"4.8"},{"sp":"N","t":"καὶ ποία ἄλλη τέχνη ἀπὸ σχήματος ἀναλαμβάνεται καὶ κόμης, οὐχὶ δὲ καὶ θεωρήματα ἔχει καὶ ὕλην καὶ τέλος;","st":"4.8"},{"sp":"N","t":"τίς οὖν ὕλη τοῦ φιλοσόφου; μὴ τρίβων; οὔ, ἀλλὰ ὁ λόγος. τί τέλος; μή τι φορεῖν τρίβωνα; οὔ, ἀλλὰ τὸ ὀρθὸν ἔχειν τὸν λόγον. ποῖα θεωρήματα; μή τι τὰ περὶ τοῦ πῶς πώγων μέγας γίνεται ἢ κόμη βαθεῖα; ἀλλὰ μᾶλλον ἃ Ζήνων λέγει, γνῶναι τὰ τοῦ λόγου στοιχεῖα, ποῖόν τι ἕκαστον αὐτῶν ἐστι καὶ πῶς ἁρμόττεται πρὸς ἄλληλα καὶ ὅσα τούτοις ἀκόλουθά ἐστιν.","st":"4.8"},{"sp":"N","t":"οὐ θέλεις οὖν ἰδεῖν πρῶτον, εἰ πληροῖ τὴν ἐπαγγελίαν ἀσχημονῶν, καὶ οὕτως τῷ ἐπιτηδεύματι ἐγκαλεῖν; νῦν δ᾽, αὐτὸς ὅταν σωφρονῇς, ἐξ ὧν ποιεῖν σοι δοκεῖ κακῶς, λέγεις ‘ὅρα τὸν φιλόσοφον’ （ ὡς οὐ πρέποντος λέγειν τὸν ταῦτα ποιοῦντα φιλόσοφον ） καὶ πάλιν ‘τοῦτο φιλόσοφός ἐστιν.’ ‘ὅρα’ δὲ ‘τὸν τέκτονα’ οὐ λέγεις, ὅταν μοιχεύοντά τινα γνῷς ἢ λιχνεύοντα ἴδῃς, οὐδὲ","st":"4.8"},{"sp":"N","t":"‘ὅρα τὸν μουσικόν.’ οὕτως ἐπὶ ποσὸν αἰσθάνῃ καὶ αὐτὸς τῆς ἐπαγγελίας τοῦ φιλοσόφου, ἀπολισθάνεις δὲ καὶ συγχέῃ ὑπὸ ἀμελετησίας.","st":"4.8"},{"sp":"N","t":"ἀλλὰ καὶ αὐτοὶ οἱ καλούμενοι φιλόσοφοι ἀπὸ τῶν κοινῶν τὸ πρᾶγμα μετίασιν: εὐθὺς ἀναλαβόντες τρίβωνα καὶ πώγωνα καθέντες φασὶν ‘ἐγὼ φιλόσοφός εἰμι.’","st":"4.8"},{"sp":"N","t":"οὐδεὶς δ᾽ ἐρεῖ ‘ἐγὼ μουσικός εἰμι,’ ἂν πλῆκτρον καὶ κιθάραν ἀγοράσῃ, οὐδ᾽ ‘ἐγὼ χαλκεύς εἰμι,’ ἂν πιλίον καὶ περίζωμα περιθῆται, ἀλλ᾽ ἁρμόζεται μὲν τὸ σχῆμα πρὸς τὴν τέχνην, ἀπὸ τῆς τέχνης δὲ τὸ ὄνομα, οὐκ ἀπὸ τοῦ σχήματος ἀναλαμβάνουσιν.","st":"4.8"},{"sp":"N","t":"διὰ τοῦτο καλῶς Εὐφράτης ἔλεγεν ὅτι ‘ἐπὶ πολὺ ἐπειρώμην λανθάνειν φιλοσοφῶν καὶ ἦν μοι,’ φησίν, ‘τοῦτο ὠφέλιμον. πρῶτον μὲν γὰρ ᾔδειν, ὅσα καλῶς ἐποίουν, ὅτι οὐ διὰ τοὺς θεατὰς ἐποίουν, ἀλλὰ δι᾽ ἐμαυτόν: ἤσθιον ἐμαυτῷ καλῶς, κατεσταλμένον εἶχον τὸ βλέμμα, τὸν περίπατον: πάντα ἐμαυτῷ καὶ θεῷ.","st":"4.8"},{"sp":"N","t":"εἶτα ὥσπερ μόνος ἠγωνιζόμην, οὕτως μόνος καὶ ἐκινδύνευον: οὐδὲν ἐμοὶ δράσαντι τὸ αἰσχρὸν ἢ ἀπρεπὲς τὸ τῆς φιλοσοφίας ἐκινδυνεύετο, οὐδ᾽ ἔβλαπτον τοὺς πολλοὺς ὡς φιλόσοφος ἁμαρτάνων.","st":"4.8"},{"sp":"N","t":"διὰ τοῦτο οἱ μὴ εἰδότες μου τὴν ἐπιβολὴν ἐθαύμαζον, πῶς πᾶσι φιλοσόφοις χρώμενος καὶ συζῶν αὐτὸς οὐκ ἐφιλοσόφουν.","st":"4.8"},{"sp":"N","t":"καὶ τί κακόν, ἐν οἷς ἐποίουν ἐπιγιγνώσκεσθαι τὸν φιλόσοφον, ἐν δὲ τοῖς συμβόλοις μή;’ βλέπε, πῶς ἐσθίω, πῶς πίνω, πῶς καθεύδω, πῶς ἀνέχομαι, πῶς ἀπέχομαι, πῶς συνεργῶ, πῶς ὀρέξει χρῶμαι, πῶς ἐκκλίσει, πῶς τηρῶ τὰς σχέσεις τὰς φυσικὰς ἢ ἐπιθέτους ἀσυγχύτως καὶ ἀπαραποδίστως: ἐκεῖθέν με κρῖνε, εἰ δύνασαι.","st":"4.8"},{"sp":"N","t":"εἰ δ᾽ οὕτως κωφὸς εἶ καὶ τυφλός, ἵνα μηδὲ τὸν Ἥφαιστον ὑπολαμβάνῃς καλὸν χαλκέα, ἂν μὴ τὸ πιλίον ἴδῃς περὶ τὴν κεφαλὴν περικείμενον, τί κακὸν ὑφ᾽ οὕτως ἠλιθίου κριτοῦ ἀγνοεῖσθαι;","st":"4.8"},{"sp":"N","t":"οὕτως ἐλάνθα νε παρὰ τοῖς πλείστοις Σωκράτης καὶ ἤρχοντο πρὸς αὐτὸν ἀξιοῦντες φιλοσόφοις συσταθῆναι.","st":"4.8"},{"sp":"N","t":"μή τι οὖν ἠγανάκτει ὡς ἡμεῖς καὶ ἔλεγεν ‘ἐγὼ δέ σοι οὐ φαίνομαι φιλόσοφος;;’ ἀλλ᾽ ἀπῆγεν καὶ συνίστα ἑνὶ ἀρκούμενος τῷ εἶναι φιλόσοφος, χαίρων δὲ καί, ὅτι μὴ δοκῶν οὐκ ἐδάκνετο: ἐμέμνητο γὰρ τοῦ ἰδίου ἔργου.","st":"4.8"},{"sp":"N","t":"τί ἔργον καλοῦ καὶ ἀγαθοῦ; μαθητὰς πολλοὺς ἔχειν; οὐδαμῶς. ὄψονται οἱ περὶ τοῦτο ἐσπουδακότες. ἀλλὰ θεωρήματα δύσκολα ἀκριβοῦν; ὄψονται καὶ περὶ τούτων ἄλλοι.","st":"4.8"},{"sp":"N","t":"ποῦ οὖν αὐτὸς καὶ ἦν τις καὶ εἶναι ἤθελεν; ὅπου βλάβη καὶ ὠφέλεια. ‘εἴ μέ τις,’ φησίν, ‘βλάψαι δύναται, ἐγὼ οὐδὲν ποιῶ: εἰ ἄλλον περιμένω, ἵνα με ὠφελήσῃ, ἐγὼ οὐδέν εἰμι. θέλω τι καὶ οὐ γίνεται: ἐγὼ ἀτυχής εἰμι.’","st":"4.8"},{"sp":"N","t":"εἰς τοσοῦτο σκάμμα προεκαλεῖτο πάντα ὁντιναοῦν καὶ οὐκ ἄν μοι δοκεῖ ἐκστῆναι οὐδενί — τί δοκεῖτε; καταγγέλλων καὶ λέγων ‘ἐγὼ τοιοῦτός εἰμι;’ μὴ γένοιτο, ἀλλὰ ὢν τοιοῦτος.","st":"4.8"},{"sp":"N","t":"πάλιν γὰρ τοῦτο μωροῦ καὶ ἀλαζόνος ‘ἐγὼ ἀπαθής εἰμι καὶ ἀτάραχος: μὴ ἀγνοεῖτε, ὦ ἄνθρωποι, ὅτι ὑμῶν κυκωμένων καὶ θορυβουμένων περὶ τὰ μηδενὸς ἄξια μόνος ἐγὼ ἀπήλλαγμαι πάσης ταραχῆς.’","st":"4.8"},{"sp":"N","t":"οὕτως οὐκ ἀρκεῖ σοι τὸ μηδὲν ἀλγεῖν, ἂν μὴ κηρύσσῃς ‘συνέλθετε πάντες οἱ ποδαγρῶντες, οἱ κεφαλαλγοῦντες, οἱ πυρέσσοντες, οἱ χωλοί, οἱ τυφλοί, καὶ ἴδετέ με ἀπὸ παντὸς πάθους ὑγιᾶ;’","st":"4.8"},{"sp":"N","t":"τοῦτο κενὸν καὶ φορτικόν, εἰ μή τις ὡς ὁ Ἀσκληπιὸς εὐθὺς ὑποδεῖξαι δύνασαι, πῶς θεραπεύοντες εὐθὺς ἔσονται ἄνοσοι κἀκεῖνοι, καὶ εἰς τοῦτο φέρεις παράδειγμα τὴν ὑγίειαν τὴν σεαυτοῦ.","st":"4.8"},{"sp":"N","t":"τοιοῦτος γάρ τίς ἐστιν ὁ Κυνικὸς τοῦ σκήπτρου καὶ διαδήματος ἠξιωμένος παρὰ τοῦ Διὸς καὶ λέγων ‘ἵν᾽ ἴδητε, ὦ ἄνθρωποι, ὅτι τὴν εὐδαιμονίαν καὶ ἀταραξίαν οὐχ ὅπου ἐστὶ ζητεῖτε,","st":"4.8"},{"sp":"N","t":"ἀλλ᾽ ὅπου μή ἐστιν, ἰδοὺ ἐγὼ ὑμῖν παράδειγμα ὑπὸ τοῦ θεοῦ ἀπέσταλμαι μήτε κτῆσιν ἔχων μήτε οἶκον μήτε γυναῖκα μήτε τέκνα, ἀλλὰ μηδ᾽ ὑπόστρωμα μηδὲ χιτῶνα μηδὲ σκεῦος: καὶ ἴδετε, πῶς ὑγιαίνω: πειράθητέ μου κἂν ἴδητε ἀτάραχον, ἀκούσατε τὰ φάρμακα καὶ ὑφ᾽ ὧν ἐθεραπεύθην.’","st":"4.8"},{"sp":"N","t":"τοῦτο γὰρ ἤδη καὶ φιλάνθρωπον καὶ γενναῖον. ἀλλ᾽ ὁρᾶτε, τίνος ἔργον ἐστίν: τοῦ Διὸς ἢ ὃν ἂν ἐκεῖνος ἄξιον κρίνῃ ταύτης τῆς ὑπηρεσίας, ἵνα μηδαμοῦ μηδὲν παραγυμνώσῃ πρὸς τοὺς πολλούς, δι᾽ οὗ τὴν μαρτυρίαν τὴν αὑτοῦ, ἣν τῇ ἀρετῇ μαρτυρεῖ καὶ τῶν ἐκτὸς καταμαρτυρεῖ, αὐτὸς ἄκυρον ποιήσῃ: οὔτ᾽ ὠχρήσαντα χρόα κάλλιμον οὔτε παρειῶν δάκρυ᾽ ὀμορξάμενον.","st":"4.8"},{"sp":"N","t":"καὶ οὐ μόνον ταῦτα, ἀλλ᾽ οὐδὲ ποθοῦντά τι ἢ ἐπιζητοῦντα, ἄνθρωπον ἢ τόπον ἢ διαγωγήν, ὡς τὰ παιδία τὸν τρυγητὸν ἢ τὰς ἀργίας, αἰδοῖ πανταχοῦ κεκοσμημένον, ὡς οἱ ἄλλοι τοίχοις καὶ θύραις καὶ θυρωροῖς.","st":"4.8"},{"sp":"N","t":"νῦν δ᾽ αὐτὸ μόνον κινηθέντες πρὸς φιλοσοφίαν, ὡς οἱ κακοστόμαχοι πρός τι βρωμάτιον, ὃ μετὰ μικρὸν σικχαίνειν μέλλουσιν, εὐθὺς ἐπὶ τὸ σκῆπτρον, ἐπὶ τὴν βασιλείαν. καθεῖκε τὴν κόμην, ἀνείληφε τρίβωνα, γυμνὸν δεικνύει τὸν ὦμον, μάχεται τοῖς ἀπαντῶσιν κἂν ἐν φαινόλῃ τινὰ ἴδῃ, μάχεται αὐτῷ.","st":"4.8"},{"sp":"N","t":"ἄνθρωπε, χειμάσκησον πρῶτον: ἰδοῦ σου τὴν ὁρμήν, μὴ κακοστομάχου ἢ κισσώσης γυναικός ἐστιν. ἀγνοεῖσθαι μελέτησον πρῶτον, τίς εἶ: σαυτῷ φιλοσόφησον ὀλίγον χρόνον.","st":"4.8"},{"sp":"N","t":"οὕτως καρπὸς γίνεται: κατορυγῆναι δεῖ εἰς χρόνον τὸ σπέρμα, κρυφθῆναι, κατὰ μικρὸν αὐξηθῆναι, ἵνα τελεσφορήσῃ. ἂν δὲ πρὸ τοῦ γόνυ φῦσαι τὸν στάχυν ἐξενέγκῃ, ἀτελές ἐστιν, ἐκ κήπου Ἀδωνιακοῦ.","st":"4.8"},{"sp":"N","t":"τοιοῦτον εἶ καὶ σὺ φυτάριον: θᾶττον τοῦ δέοντος ἤνθηκας, ἀποκαύσει σε ὁ χειμών.","st":"4.8"},{"sp":"N","t":"ἰδοῦ, τί λέγουσιν οἱ γεωργοὶ περὶ τῶν σπερμάτων, ὅταν πρὸ ὥρας θερμασίαι γένωνται. ἀγωνιῶσιν, μὴ ἐξυβρίσῃ τὰ σπέρματα, εἶτα αὐτὰ πάγος εἷς λαβὼν ἐξελέγξῃ.","st":"4.8"},{"sp":"N","t":"ὅρα καὶ σύ, ἄνθρωπε: ἐξύβρικας, ἐπιπεπήδηκας δοξαρίῳ πρὸ ὥρας: δοκεῖς τις εἶναι, μωρὸς παρὰ μωροῖς: ἀποπαγήσῃ, μᾶλλον δ᾽ ἀποπέπηγας ἤδη ἐν τῇ ῥίζῃ κάτω, τὰ δ᾽ ἄνω σου μικρὸν ἔτι ἀνθεῖ καὶ διὰ τοῦτο δοκεῖς ἔτι ζῆν καὶ θάλλειν.","st":"4.8"},{"sp":"N","t":"ἄφες ἡμᾶς γε κατὰ φύσιν πεπανθῆναι. τί ἡμᾶς ἀποδύεις, τί βιάζῃ; οὔπω δυνάμεθα ἐνεγκεῖν τὸν ἀέρα. ἔασον τὴν ῥίζαν αὐξηθῆναι, εἶτα γόνυ λαβεῖν τὸ πρῶτον, εἶτα τὸ δεύτερον, εἶτα τὸ τρίτον: εἶθ᾽ οὕτως ὁ καρπὸς ἐκβιάσεται τὴν φύσιν, κἂν ἐγὼ μὴ θέλω.","st":"4.8"},{"sp":"N","t":"τίς γὰρ ἐγκύμων γενόμενος καὶ πλήρης τηλικούτων δογμάτων οὐχὶ αἰσθάνεταί τε τῆς αὑτοῦ παρασκευῆς καὶ ἐπὶ τὰ κατάλληλα ἔργα ὁρμᾷ;","st":"4.8"},{"sp":"N","t":"ἀλλὰ ταῦρος μὲν οὐκ ἀγνοεῖ τὴν αὑτοῦ φύσιν καὶ παρασκευήν, ὅταν ἐπιφανῇ τι θηρίον, οὐδ᾽ ἀναμένει τὸν προτρεψόμενον, οὐδὲ κύων, ὅταν ἴδῃ τι τῶν ἀγρίων ζῴων:","st":"4.8"},{"sp":"N","t":"ἐγὼ δ᾽ ἂν ἴσχω τὴν ἀνδρὸς ἀγαθοῦ παρασκευήν, ἐκδέξομαι, ἵνα με σὺ παρασκευάσῃς ἐπὶ τὰ οἰκεῖα ἔργα; νῦν δ᾽ οὔπω ἔχω, πίστευσόν μοι. τί οὖν με πρὸ ὥρας ἀποξηρᾶναι θέλεις, ὡς αὐτὸς ἐξηράνθης; πρὸς τὸν εἰς ἀναισχυντίαν μεταβληθέντα. ὅταν ἄλλον ἴδῃς ἄρχοντα, ἀντίθες, ὅτι σὺ ἔχεις τὸ μὴ δεῖσθαι ἀρχῆς: ὅταν ἄλλον πλουτοῦντα, ἰδοῦ, τί ἀντὶ τούτου ἔχεις.","st":"4.8"},{"sp":"N","t":"εἰ μὲν γὰρ μηδὲν ἔχεις ἀντ᾽ αὐτοῦ, ἄθλιος εἶ: εἰ δ᾽ ἔχεις τὸ μὴ χρείαν ἔχειν πλούτου, γίγνωσκε, ὅτι πλεῖον ἔχεις καὶ πολλῷ πλείονος ἄξιον. ἄλλος γυναῖκα εὔμορφον,","st":"4.9"},{"sp":"N","t":"σὺ τὸ μὴ ἐπιθυμεῖν εὐμόρφου γυναικός. μικρά σοι δοκεῖ ταῦτα; καὶ πόσου ἂν τιμήσαιντο οὗτοι αὐτοὶ οἱ πλουτοῦντες καὶ ἄρχοντες καὶ μετ᾽ εὐμόρφων διαιτώμενοι δύνασθαι πλούτου καταφρονεῖν καὶ ἀρχῶν καὶ αὐτῶν τούτων τῶν γυναικῶν, ὧν ἐρῶσιν καὶ ὧν τυγχάνουσιν;","st":"4.9"},{"sp":"N","t":"ἀγνοεῖς οἷόν τί ἐστι δίψος πυρέσσοντος; οὐδὲν ὅμοιον ἔχει τῷ τοῦ ὑγιαίνοντος. ἐκεῖνος πιὼν ἀποπέπαυται: ὁ δὲ πρὸς ὀλίγον ἡσθεὶς ναυτιᾷ, χολὴν αὐτὸ ποιεῖ ἀντὶ ὕδατος, ἐμεῖ, στροφοῦται, διψῇ σφοδρότερον.","st":"4.9"},{"sp":"N","t":"τοιοῦτόν ἐστι μετ᾽ ἐπιθυμίας πλουτεῖν, μετ᾽ ἐπιθυμίας ἄρχειν, μετ᾽ ἐπιθυμίας καλῇ συγκαθεύδειν: ζηλοτυπία πρόσεστιν, φόβος τοῦ στερηθῆναι, αἰσχροὶ λόγοι, αἰσχρὰ ἐνθυμήματα, ἔργα ἀσχήμονα. καὶ τί, φησίν, ἀπολλύω;","st":"4.9"},{"sp":"N","t":"— ἄνθρωπε, ὑπῆρχες αἰδήμων καὶ νῦν οὐκέτι εἶ: οὐδὲν ἀπολώλεκας; ἀντὶ Χρυσίππου καὶ Ζήνωνος Ἀριστείδην ἀναγιγνώσκεις καὶ Εὐηνόν: οὐδὲν ἀπολώλεκας; ἀντὶ Σωκράτους καὶ Διογένους τεθαύμακας τὸν πλείστας διαφθεῖραι καὶ ἀναπεῖσαι δυνάμενον.","st":"4.9"},{"sp":"N","t":"καλὸς εἶναι θέλεις καὶ πλάσσεις σεαυτὸν μὴ ὢν καὶ ἐσθῆτα ἐπιδεικνύειν θέλεις στιλπνήν, ἵνα τὰς γυναῖκας ἐπιστρέφῃς, κἄν που μυραφίου ἐπιτύχῃς, μακάριος εἶναι δοκεῖς.","st":"4.9"},{"sp":"N","t":"πρότερον δ᾽ οὐδὲ ἐνεθυμοῦ τι τούτων, ἀλλὰ ποῦ εὐσχήμων λόγος, ἀνὴρ ἀξιόλογος, ἐνθύμημα γενναῖον. τοιγαροῦν ἐκάθευδες ὡς ἀνήρ, προῄεις ὡς ἀνήρ, ἐσθῆτα ἐφόρεις ἀνδρικήν, λόγους ἐλάλεις πρέποντας ἀνδρὶ ἀγαθῷ: εἶτά μοι λέγεις","st":"4.9"},{"sp":"N","t":"‘οὐδὲν ἀπώλεσα;’ οὕτως οὐδὲν ἄλλο ἢ κέρμα ἀπολλύουσιν ἄνθρωποι; αἰδὼς οὐκ ἀπόλλυται, εὐσχημοσύνη οὐκ ἀπόλλυται; ἢ οὐκ ἔστι ζημιωθῆναι ταῦτα ἀπολέσαντα; σοὶ μὲν οὖ","st":"4.9"},{"sp":"N","t":"ν δοκεῖ τάχα τούτων οὐδὲν οὐκέτι εἶναι ζημία: ἦν δέ ποτε χρόνος, ὅτε μόνην αὐτὴν ὑπελογίζου καὶ ζημίαν καὶ βλάβην, ὅτε ἠγωνίας, μή τις ἐκσείσῃ σε τούτων τῶν λόγων καὶ ἔργων.","st":"4.9"},{"sp":"N","t":"ἰδού, ἐκσέσεισαι ὑπ᾽ ἄλλου μὲν οὐδενός, ὑπὸ σαυτοῦ δέ. μαχέσθητι σαυτῷ, ἀφελοῦ σαυτὸν εἰς εὐσχημοσύνην, εἰς αἰδῶ, εἰς ἐλευθερίαν.","st":"4.9"},{"sp":"N","t":"εἴ σοί τίς που ἔλεγεν περὶ ἐμοῦ ταῦτα, ὅτι μέ τις μοιχεύειν ἀναγκάζει, ὅτι ἐσθῆτα φορεῖν τοιαύτην, ὅτι μυρίζεσθαι, οὐκ ἂν ἀπελθὼν αὐτόχειρ ἐγένου τούτου τοῦ ἀνθρώπου τοῦ οὕτως μοι παραχρωμένου;","st":"4.9"},{"sp":"N","t":"νῦν οὖν οὐ θέλεις σαυτῷ βοηθῆσαι; καὶ πόσῳ ῥᾴων αὕτη ἡ βοήθεια; οὐκ ἀποκτεῖναί τινα δεῖ, οὐ δῆσαι, οὐχ ὑβρίσαι, οὐκ εἰς ἀγορὰν προελθεῖν, ἀλλ᾽ αὐτὸν αὑτῷ λαλῆσαι, τῷ μάλιστα πεισθησομένῳ, πρὸς ὃν οὐδείς ἐστί σου πιθανώτερος.","st":"4.9"},{"sp":"N","t":"καὶ πρῶτον μὲν κατάγνωθι τῶν γιγνομένων, εἶτα καταγνοὺς μὴ ἀπογνῷς σεαυτοῦ μηδὲ πάθῃς τὸ τῶν ἀγεννῶν ἀνθρώπων, οἳ ἅπαξ ἐνδόντες εἰσάπαν ἐπέδωκαν ἑαυτοὺς καὶ ὡς ὑπὸ ῥεύματος παρεσύρησαν, ἀλλὰ μάθε τὸ τῶν παιδοτριβῶν.","st":"4.9"},{"sp":"N","t":"πέπτωκε τὸ παιδίον: ‘ἀναστάς,’ φησίν, ‘πάλιν πάλαιε, μέχρις ἂν ἰσχυροπο","st":"4.9"},{"sp":"N","t":"ιηθῇς.’ τοιοῦτόν τι καὶ σὺ πάθε: ἴσθι γάρ, ὅτι οὐδέν ἐστιν εὐαγωγότερον ἀνθρωπίνης ψυχῆς. θελῆσαι δεῖ καὶ γέγονεν, διώρθωται: ὡς πάλιν ἀπονυστάσαι καὶ ἀπόλωλεν. ἔσωθεν γάρ ἐστι καὶ ἀπώλεια καὶ βοήθεια.","st":"4.9"},{"sp":"N","t":"— εἶτα τί μοι ἀγαθόν; — καὶ τί ζητεῖς τούτου μεῖζον; ἐξ ἀναισχύντου αἰδήμων ἔσῃ, ἐξ ἀκόσμου κόσμιος, ἐξ ἀπίστου πιστός, ἐξ ἀκολάστου σώφρων.","st":"4.9"},{"sp":"N","t":"εἴ τινα ἄλλα τούτων μείζονα ζητεῖς, ποίει ἃ ποιεῖς: οὐδὲ θεῶν σέ τις ἔτι σῶσαι δύναται. τίνων δεῖ καταφρονεῖν καὶ πρὸς τίνα διαφέρεσθαι. ἀπορία πᾶσι τοῖς ἀνθρώποις περὶ τὰ ἐκτὸς γίνεται, ἀμηχανία περὶ τὰ ἐκτός. ‘τί ποιήσω; πῶς γένηται; πῶς ἀποβῇ;","st":"4.9"},{"sp":"N","t":"μὴ τόδε ἀπαντήσῃ, μὴ τόδε.’ πᾶσαι αὗται αἱ φωναὶ περὶ τὰ ἀπροαίρετα στρεφομένων εἰσίν: τίς γὰρ λέγει ‘πῶς μὴ συγκατατιθῶμαι τῷ ψεύδει; πῶς μὴ ἀπονεύσω ἀπὸ τοῦ ἀληθοῦς;’","st":"4.10"},{"sp":"N","t":"ἐὰν οὕτως ᾖ εὐφυής, ὥστε περὶ τούτων ἀγωνιᾶν, ὑπομνήσω αὐτὸν ὅτι ‘τί ἀγωνιᾷς; ἐπὶ σοί ἐστιν: ἀσφαλὴς ἴσθι: μὴ πρὸ τοῦ ἐπάγειν τὸν φυσικὸν κανόνα προπήδα ἐν τῷ συγκατατίθεσθαι.’","st":"4.10"},{"sp":"N","t":"πάλιν ἂν περὶ ὀρέξεως μὴ ἀγωνιᾷ, μὴ ἀτελὴς γένηται καὶ ἀποτευκτική,","st":"4.10"},{"sp":"N","t":"περὶ ἐκκλίσεως, μὴ περιπτωτική, πρῶτον μὲν αὐτὸν καταφιλήσω, ὅτι ἀφεὶς περὶ ἃ οἱ ἄλλοι ἐπτόηνται καὶ τοὺς ἐκείνων φόβους περὶ τῶν ἰδίων ἔργων πεφρόντικεν, ὅπου αὐτός ἐστιν: εἶτα ἐρῶ αὐτῷ","st":"4.10"},{"sp":"N","t":"‘εἰ μὴ θέλῃς ὀρέγεσθαι ἀποτευκτικῶς μηδ᾽ ἐκκλίνειν περιπτωτικῶς, μηδενὸς ὀρέγου τῶν ἀλλοτρίων, μηδὲν ἔκκλινε τῶν μὴ ἐπὶ σοί. εἰ δὲ μή, καὶ ἀποτυχεῖν καὶ περιπεσεῖν ἀνάγκη.’","st":"4.10"},{"sp":"N","t":"ποία ἐνθάδ᾽ ἀπορία; ποῦ τόπον ἔχει ‘πῶς γένηται;’ καὶ ‘πῶς ἀποβῇ;’ καὶ ‘μὴ ἀπαντήσῃ τόδε ἢ τόδε;’ νῦν οὐχὶ τὸ ἐκβησόμενον ἀπροαίρετον;","st":"4.10"},{"sp":"N","t":"— ναί. — ἡ δ᾽ οὐσία τοῦ ἀγαθοῦ καὶ κακοῦ ἐστιν ἐν τοῖς προαιρετικοῖς; — ναί. — ἔξεστιν οὖν σοι παντὶ τῷ ἀποβάντι χρῆσθαι κατὰ φύσιν; μή τις σε κωλῦσαι δύναται;","st":"4.10"},{"sp":"N","t":"— οὐδείς. — μηκέτι οὖν μοι λέγε ‘πῶς γένηται;’ ὅπως γὰρ ἂν γένηται, σὺ αὐτὸ θήσεις καλῶς καὶ ἔσται σοι τὸ ἀποβὰν εὐτύχημα.","st":"4.10"},{"sp":"N","t":"ἢ τίς ἂν ἦν ὁ Ἡρακλῆς λέγων ‘πῶς μοι μὴ μέγας λέων ἐπιφανῇ μηδὲ μέγας σῦς μηδὲ θηριώδεις ἄνθρωποι;’ καὶ τί σοι μέλει; ἂν μέγας σῦς ἐπιφανῇ, μεῖζον ἆθλον ἀθλήσεις: ἂν κακοὶ ἄνθρωποι, κακῶν ἀπαλλάξεις τὴν οἰκουμένην.","st":"4.10"},{"sp":"N","t":"— ἂν οὖν οὕτως ἀποθάνω; — ἀγαθὸς ὢν ἀποθανῇ, γενναίαν πρᾶξιν ἐπιτελῶν ἐπεὶ γὰρ δεῖ πάντως ἀποθανεῖν, ἀνάγκη τί ποτε ποιοῦντα εὑρεθῆναι, ἢ γεωργοῦντα ἢ σκάπτοντα ἢ ἐμπορευόμενον ἢ ὑπατεύοντα ἢ ἀπεπτοῦντα ἢ διαρροιζόμενον.","st":"4.10"},{"sp":"N","t":"τί οὖν θέλεις ποιῶν εὑρεθῆναι ὑπὸ τοῦ θανάτου; ἐγὼ μὲν τὸ ἐμὸν μέρος ἔργον τί ποτε ἀνθρωπικόν, εὐεργετικόν, κοινωφελές, γενναῖον.","st":"4.10"},{"sp":"N","t":"εἰ δὲ μὴ δύναμαι τὰ τηλικαῦτα ποιῶν εὑρεθῆναι, ἐκεῖνό γε τὸ ἀκώλυτον, τὸ διδόμενον, ἐμαυτὸν ἐπανορθῶν, ἐξεργαζόμενος τὴν δύναμιν τὴν χρηστικὴν τῶν φαντασιῶν, ἀπάθειαν ἐκπονῶν, ταῖς σχέσεσι τὰ οἰκεῖα ἀποδιδούς: εἰ οὕτως εὐτυχής εἰμι, καὶ τοῦ τρίτου τόπου παραπτόμενος, τοῦ περὶ τὴν τῶν κριμάτων ἀσφάλειαν.","st":"4.10"},{"sp":"N","t":"ἂν μετὰ τούτων με ὁ θάνατος καταλάβῃ, ἀρκεῖ μοι ἂν δύνωμαι πρὸς τὸν θεὸν ἀνατεῖναι τὰς χεῖρας, εἰπεῖν ὅτι ‘ἃς ἔλαβον ἀφορμὰς παρὰ σοῦ πρὸς τὸ αἰσθέσθαι σου τῆς διοικήσεως καὶ ἀκολουθῆσαι αὐτῇ, τούτων οὐκ ἠμέλησα: οὐ κατῄσχυνά σε τὸ ἐμὸν μέρος.","st":"4.10"},{"sp":"N","t":"ἰδοῦ, πῶς κέχρημαι ταῖς αἰσθήσεσιν, ἰδοῦ, πῶς ταῖς προλήψεσιν. μή ποτέ σε ἐμεμψάμην, μή τι τῶν γινομένων τινὶ δυσηρέστησα ἢ ἄλλως γενέσθαι ἠθέλησα, μή τι τὰς σχέσεις παρέβηναι;","st":"4.10"},{"sp":"N","t":"† ὅ με σὺ ἐγέννησας, χάριν ἔχω, ὧν ἔδωκας: ἐφ᾽ ὅσον ἐχρησάμην τοῖς σοῖς, ἀρκεῖ μοι. πάλιν αὐτὰ ἀπόλαβε καὶ κατάταξον εἰς ἣν θέλεις χώραν. σὰ γὰρ ἦν πάντα, σύ μοι αὐτὰ δέδωκας.’","st":"4.10"},{"sp":"N","t":"οὐκ ἀρκεῖ οὕτως ἔχοντα ἐξελθεῖν; καὶ τίς βίων κρείττων ἢ εὐσχημονέστερος τοῦ οὕτως ἔχοντος, ποία δὲ καταστροφὴ εὐδαιμονεστέρα;","st":"4.10"},{"sp":"N","t":"ἵνα δὲ ταῦτα γένηται, οὐ μικρὰ δέξασθαι οὐδὲ μικρῶν ἀποτυχεῖν. οὐ δύνασαι καὶ ὑπατεῦσαι θέλειν καὶ ταῦτα καὶ ἀγροὺς ἔχειν ἐσπουδακέναι καὶ ταῦτα καὶ τῶν δουλαρίων φροντίζειν καὶ σεαυτοῦ.","st":"4.10"},{"sp":"N","t":"ἀλλ᾽ ἄν τι τῶν ἀλλοτρίων θέλῃς, τὰ σὰ ἀπώλετο. αὕτη τοῦ πράγματος ἡ φύσις: προῖκα οὐδὲν γίνεται.","st":"4.10"},{"sp":"N","t":"καὶ τί θαυμαστόν; ἂν ὑπατεῦσαι θέλῃς, ἀγρυπνῆσαί σε δεῖ, περιδραμεῖν, τὰς χεῖρας καταφιλῆσαι, πρὸς ταῖς ἀλλοτρίαις θύραις κατασαπῆναι, πολλὰ μὲν εἰπεῖν, πολλὰ δὲ πρᾶξαι ἀνελεύθερα, δῶρα πέμψαι πολλοῖς, ξένια καθ᾽ ἡμέραν ἐνίοις: καὶ τί τὸ γινόμενόν ἐστιν;","st":"4.10"},{"sp":"N","t":"δώδεκα δεσμὰ ῥάβδων καὶ τρὶς ἢ τετράκις ἐπὶ βῆμα καθίσαι καὶ κιρκήσια δοῦναι καὶ σπυρίσιν δειπνίσαι. ἢ δειξάτω μοί τις, τί ἐστι παρὰ ταῦτα.","st":"4.10"},{"sp":"N","t":"ὑπὲρ ἀπαθείας οὖν, ὑπὲρ ἀταραξίας, ὑπὲρ τοῦ καθεύδοντα καθεύδειν, ἐγρηγορότα ἐγρηγορέναι, μὴ φοβεῖσθαι μηδέν, μὴ ἀγωνιᾶν ὑπὲρ μηδενὸς οὐδὲν ἀναλῶσαι θέλεις, οὐδὲν πονῆσαι;","st":"4.10"},{"sp":"N","t":"ἀλλ᾽ ἄν τι ἀπόληταί σου περὶ ταῦτα γινομένου ἢ ἀναλωθῇ κακῶς ἢ ἄλλος τύχῃ ὧν ἔδει σε τυχεῖν, εὐθὺς μὴ δηχθήσῃ ἐπὶ τῷ γενομένῳ;","st":"4.10"},{"sp":"N","t":"οὐκ ἀντιθήσεις, τί ἀντὶ τίνος λαμβάνεις, πόσον ἀντὶ πόσου; ἀλλὰ προῖκα θέλεις τὰ τηλικαῦτα λαβεῖν; καὶ πῶς δύνασαι;","st":"4.10"},{"sp":"N","t":"ἔργον ἔργῳ. οὐ δύνασαι καὶ τὰ ἐκτὸς ἔχειν ἐπιμελείας τετυχηκότα καὶ τὸ σαυτοῦ ἡγεμονικόν. εἰ δ᾽ ἐκεῖνα θέλεις, τοῦτο ἄφες: εἰ δὲ μή, οὔτε τοῦτο ἕξεις οὔτ᾽ ἐκεῖνα, περισπώμενος ἐπ᾽ ἀμφότερα. εἰ τοῦτο θέλεις, ἐκεῖνά σε ἀφεῖναι δεῖ.","st":"4.10"},{"sp":"N","t":"ἐκχεθήσεται τὸ ἔλαιον, ἀπολεῖται τὰ σκευάρια, ἀλλ᾽ ἐγὼ ἀπαθὴς ἔσομαι. ἐμπρησμὸς ἔσται ἐμοῦ μὴ παρόντος καὶ ἀπολεῖται τὰ βιβλία, ἀλλ᾽ ἐγὼ χρήσομαι ταῖς φαντασίαις κατὰ φύσιν. ἀλλ᾽ οὐχ ἕξω φαγεῖν.","st":"4.10"},{"sp":"N","t":"εἰ οὕτως τάλας εἰμί, λιμὴν τὸ ἀποθανεῖν. οὗτος δ᾽ ἐστὶν ὁ λιμὴν πάντων, ὁ θάνατος, αὕτη ἡ καταφυγή. διὰ τοῦτο οὐδὲν τῶν ἐν τῷ βίῳ χαλεπόν ἐστιν.","st":"4.10"},{"sp":"N","t":"ὅταν θέλῃς, ἐξῆλθες καὶ οὐ καπνίζῃ. τί οὖν ἀγωνιᾷς, τί ἀγρυπνεῖς; οὐχὶ δὲ εὐθὺς ἀναλογισάμενος, ποῦ σου τὸ ἀγαθόν ἐστι καὶ τὸ κακόν, λέγεις ὅτι ‘ἐπ᾽ ἐμοὶ ἀμφότερα: οὔτε τούτου τις ἀφελέσθαι με δύναται οὔτ᾽ ἐκείνῳ ἄκοντα περιβαλεῖν.","st":"4.10"},{"sp":"N","t":"τί οὖν οὐ ῥέγχω βαλών; τὰ ἐμὰ ἀσφαλῶς ἔχει: τὰ ἀλλότρια ὄψεται αὐτὰ ὃς ἂν φέρῃ, ὡς ἂν διδῶται παρὰ τοῦ ἔχοντος ἐξουσίαν.","st":"4.10"},{"sp":"N","t":"τίς εἰμι ὁ θέλων αὐτὰ οὕτως ἔχειν ἢ οὕτως; μὴ γάρ μοι δέδοται ἐκλογὴ αὐτῶν; μὴ γὰρ ἐμέ τις αὐτῶν διοικητὴν πεποίηκεν; ἀρκεῖ μοι ὧν ἔχω ἐξουσίαν. ταῦτά με δεῖ κάλλιστα παρασκευάσαι, τὰ δ᾽ ἄλλα ὡς ἂν θέλῃ ὁ ἐκείνων κύριος.’","st":"4.10"},{"sp":"N","t":"ταῦτά τις ἔχων πρὸ ὀφθαλμῶν ἀγρυπνεῖ, καὶ στρέφεται ἔνθα καὶ ἔνθα; τί θέλων ἢ τί ποθῶν; Πάτροκλον ἢ Ἀντίλοχον ἢ Μενέλαον; πότε γὰρ ἡγήσατο ἀθάνατόν τινα τῶν φίλων; πότε γὰρ οὐκ εἶχεν πρὸ ὀφθαλμῶν, ὅτι αὔριον ἢ εἰς τρίτην δεῖ ἢ αὐτὸν ἀποθανεῖν ἢ ἐκεῖνον;","st":"4.10"},{"sp":"N","t":"‘ναί,’ φησίν, ‘ἀλλ᾽ ᾤμην, ὅτι ἐκεῖνος ἐπιβιώσεταί μοι καὶ αὐξήσει μου τὸν υἱόν.’ μωρὸς γὰρ ἦς καὶ τὰ ἄδηλα ᾤου. τί οὖν οὐκ ἐγκαλεῖς σεαυτῷ, ἀλλὰ κλαίων κάθησαι ὡς τὰ κοράσια;","st":"4.10"},{"sp":"N","t":"‘ἀλλ᾽ ἐκεῖνός μοι φαγεῖν παρετίθει.’ ἔζη γάρ, μωρέ: νῦν δ᾽ οὐ δύναται. ἀλλ᾽ Αὐτομέδων σοι παραθήσει: ἂν δὲ καὶ Αὐτομέδων ἀποθάνῃ, ἄλλον εὑρήσεις.","st":"4.10"},{"sp":"N","t":"ἂν δ᾽ ἡ χύτρα, ἐν ᾗ ἥψετό σοι τὸ κρέας, καταγῇ, λιμῷ σε δεῖ ἀποθανεῖν, ὅτι μὴ ἔχεις τὴν συνήθη χύτραν; οὐ πέμπεις καὶ ἄλλην καινὴν ἀγοράζεις; οὐ μὲν γάρ τι,","st":"4.10"},{"sp":"N","t":"φησίν, κακώτερον ἄλλο πάθοιμι. τοῦτο γάρ σοι κακόν ἐστιν; εἶτ᾽ ἀφεὶς τοῦτο ἐξελεῖν αἰτιᾷ τὴν μητέρα, ὅτι σοι οὐ προεῖπεν, ἵν᾽ ὀδυνώμενος ἐξ ἐκείνου διατελῇς;","st":"4.10"},{"sp":"N","t":"τί δοκεῖτε; μὴ ἐπίτηδες ταῦτα συνθεῖναι Ὅμηρον, ἵν᾽ ἴδωμεν, ὅτι οἱ εὐγενέστατοι, οἱ ἰσχυρότατοι, οἱ πλουσιώτατοι, οἱ εὐμορφότατοι, ὅταν οἷα δεῖ δόγματα μὴ ἔχωσιν, οὐδὲν κωλύονται ἀθλιώτατοι εἶναι καὶ δυστυχέστατοι; περὶ καθαριότητος. ἀμφισβητοῦσί τινες, εἰ ἐν τῇ φύσει τοῦ ἀνθρώπου περιέχεται τὸ κοινωνικόν: ὅμως δ᾽ αὐτοὶ οὗτοι οὐκ ἄν μοι δοκοῦσιν ἀμφισβητῆσαι, ὅτι τό γε καθάριον πάντως περιέχεται καὶ εἴ τινι ἄλλῳ καὶ τούτῳ τῶν ζῴων χωρίζεται.","st":"4.10"},{"sp":"N","t":"ὅταν οὖν ἄλλο τι ζῷον ἴδωμεν ἀποκαθαῖρον ἑαυτό, ἐπιλέγειν εἰώθαμεν θαυμάζοντες ὅτι ‘ὡς ἄνθρωπος.’ καὶ πάλιν ἄν τις ἐγκαλῇ τινι ζῴῳ, εὐθὺς εἰώθαμεν ὥσπερ ἀπολογούμενοι λέγειν ὅτι ‘οὐ δήπου ἄνθρωπός ἐστιν.’","st":"4.11"},{"sp":"N","t":"οὕτως ἐξαίρετόν τι περὶ τὸν ἄνθρωπον εἶναι οἰόμεθα ἀπὸ τῶν θεῶν αὐτὸ πρῶτον λαμβάνοντες. ἐπεὶ γὰρ ἐκεῖνοι φύσει καθαροὶ καὶ ἀκήρατοι, ἐφ᾽ ὅσον ἠγγίκασιν αὐτοῖς οἱ ἄνθρωποι κατὰ τὸν λόγον, ἐπὶ τοσοῦτον καὶ τοῦ καθαροῦ καὶ τοῦ καθαρίου εἰσὶν ἀνθεκτικοί.","st":"4.11"},{"sp":"N","t":"ἐπεὶ δ᾽ ἀμήχανον τὴν οὐσίαν αὐτῶν παντάπασιν εἶναι καθαρὰν ἐκ τοιαύτης ὕλης κεκραμένην, ὁ λόγος παραληφθεὶς εἰς τὸ ἐνδεχόμενον ταύτην καθάριον ἀποτελεῖν πειρᾶται.","st":"4.11"},{"sp":"N","t":"πρώτη οὖν καὶ ἀνωτάτω καθαρότης ἡ ἐν ψυχῇ γενομένη καὶ ὁμοίως ἀκαθαρσία. ψυχῆς δ᾽ ὡς σώματος μὲν ἀκαθαρσίαν οὐκ ἂν εὕροις, ὡς ψυχῆς δὲ τί ἂν ἄλλο εὕροις ἢ τὸ παρέχον αὐτὴν ῥυπαρὰν πρὸς τὰ ἔργα τὰ αὑτῆς;","st":"4.11"},{"sp":"N","t":"ἔργα δὲ ψυχῆς ὁρμᾶν, ἀφορμᾶν, ὀρέγεσθαι, ἐκκλίνειν, παρασκευάζεσθαι, ἐπιβάλλεσθαι, συγκατατίθεσθαι.","st":"4.11"},{"sp":"N","t":"τί ποτ᾽ οὖν ἐστι τὸ ἐν τούτοις τοῖς ἔργοις ῥυπαρὰν παρέχον αὐτὴν καὶ ἀκάθαρτον; οὐδὲν ἄλλο ἢ τὰ μοχθηρὰ κρίματα αὐτῆς.","st":"4.11"},{"sp":"N","t":"ὥστε ψυχῆς μὲν ἀκαθαρσία δόγματα πονηρά, κάθαρσις δ᾽ ἐμποίησις οἵων δεῖ δογμάτων. καθαρὰ δ᾽ ἡ ἔχουσα οἷα δεῖ δόγματα: μόνη γὰρ αὕτη ἐν τοῖς ἔργοις τοῖς αὑτῆς ἀσύγχυτος καὶ ἀμόλυντος.","st":"4.11"},{"sp":"N","t":"δεῖ δέ τι ἐοικὸς τούτῳ καὶ ἐπὶ σώματος φιλοτεχνεῖν κατὰ τὸ ἐνδεχόμενον. ἀμήχανον ἦν μύξας μὴ ῥεῖν τοῦ ἀνθρώπου τοιοῦτον ἔχοντος τὸ σύγκραμα: διὰ τοῦτο χεῖρας ἐποίησεν ἡ φύσις καὶ αὐτὰς τὰς ῥῖνας ὡς σωλῆνας πρὸς τὸ ἐκδιδόναι τὰ ὑγρά. ἂν οὖν ἀναρροφῇ τις αὐτάς, λέγω ὅτι οὐ ποιεῖ ἔργον ἀνθρωπικόν.","st":"4.11"},{"sp":"N","t":"ἀμήχανον ἦν μὴ πηλοῦσθαι τοὺς πόδας μηδὲ ὅλως μολύνεσθαι διὰ τοιούτων τινῶν πορευομένους: διὰ τοῦτο ὕδωρ παρεσκεύασεν, διὰ τοῦτο χεῖρας.","st":"4.11"},{"sp":"N","t":"ἀμήχανον ἦν ἀπὸ τοῦ τρώγειν μὴ ῥυπαρόν τι προσμένειν τοῖς ὀδοῦσι: διὰ τοῦτο ‘πλῦνον,’ φησίν, ‘τοὺς ὀδόντας.’ διὰ τί; ἵν᾽ ἄνθρωπος ᾖς καὶ μὴ θηρίον μηδὲ συίδιον.","st":"4.11"},{"sp":"N","t":"ἀμήχανον μὴ ἀπὸ τοῦ ἱδρῶτος καὶ τῆς κατὰ τὴν ἐσθῆτα συνοχῆς ὑπολείπεσθαί τι περὶ τὸ σῶμα ῥυπαρὸν καὶ δεόμενον ἀποκαθάρσεως: διὰ τοῦτο ὕδωρ, ἔλαιον, χεῖρες, ὀθόνιον, ξύστρα, νίτρον, ἔσθ᾽ ὅθ᾽ ἡ ἄλλη πᾶσα παρασκευὴ πρὸς τὸ καθῆραι αὐτό.","st":"4.11"},{"sp":"N","t":"οὔ: ἀλλ᾽ ὁ μὲν χαλκεὺς ὡς χαλκεὺς ἐξιώσει τὸ σιδήριον καὶ ὄργανα πρὸς τοῦτο ἕξει κατεσκευασμένα καὶ τὸ πινάκιον αὐτὸς σὺ πλυνεῖς, ὅταν μέλλῃς ἐσθίειν, ἐὰν μὴ ᾖς παντελῶς ἀκάθαρτος καὶ ῥυπαρός: τὸ σωμάτιον δ᾽ οὐ πλυνεῖς οὐδὲ καθαρὸν ποιήσεις;","st":"4.11"},{"sp":"N","t":"— διὰ τί; φησίν. — πάλιν ἐρῶ σοι: πρῶτον μὲν ἵνα τὰ ἀνθρώπου ποιῇς, εἶτα ἵνα μὴ ἀνιᾷς τοὺς ἐντυγχάνοντας.","st":"4.11"},{"sp":"N","t":"τοιοῦτόν τι καὶ ἐνθάδε ποιεῖς καὶ οὐκ αἰσθάνῃ. σαυτὸν ἄξιον ἡγῇ τοῦ ὄζειν: ἔστω, ἴσθι ἄξιος. μή τι καὶ τοὺς παρακαθίζοντας, μή τι καὶ τοὺς συγκατακλινομένους, μή τι καὶ τοὺς καταφιλοῦντας;","st":"4.11"},{"sp":"N","t":"ἢ ἄπελθ᾽ εἰς ἐρημίαν πού ποτε, ἧς ἄξιος εἶ, καὶ μόνος δίαγε κατόζων σεαυτοῦ. δίκαιον γάρ ἐστι τῆς σῆς ἀκαθαρσίας σὲ μόνον ἀπολαύειν. ἐν πόλει δ᾽ ὄντα οὕτως ἀπερισκέπτως καὶ ἀγνωμόνως ἀναστρέφεσθαι τίνος σοι φαίνεται;","st":"4.11"},{"sp":"N","t":"εἰ δ᾽ ἵππον σοι πεπιστεύκει ἡ φύσις, περιεώρας αὐτὸν καὶ ἀτημέλητον; καὶ νῦν οἴου σου τὸ σῶμα ὡς ἵππον ἐγκεχειρίσθαι: πλῦνον αὐτό, ἀπόσμηξον, ποίησον, ἵνα σε μηδεὶς ἀποστρέφηται, μηδεὶς ἐκτρέπηται.","st":"4.11"},{"sp":"N","t":"τίς δ᾽ οὐκ ἐκτρέπεται ῥυπαρὸν ἄνθρωπον, ὄζοντα, κακόχρουν μᾶλλον ἢ τὸν κεκοπρωμένον; ἐκείνη ἡ ὀσμὴ ἔξωθέν ἐστιν ἐπίθετος, ἡ δ᾽ ἐξ ἀθεραπευσίας ἔσωθεν καὶ οἱονεὶ διασεσηπότος. ἀλλὰ Σωκράτης ὀλιγάκις ἐλούετο.","st":"4.11"},{"sp":"N","t":"— ἀλλὰ ἔστιλβεν αὐτοῦ τὸ σῶμα, ἀλλ᾽ ἦν οὕτως ἐπίχαρι καὶ ἡδύ, ὥστ᾽ ἤρων αὐτοῦ οἱ ὡραιότατοι καὶ εὐγενέστατοι καὶ ἐπεθύμουν ἐκείνῳ παρακατακλίνεσθαι μᾶλλον ἢ τοῖς εὐμορφοτάτοις. ἐξῆν ἐκείνῳ μήτε λούεσθαι μήτε πλύνεσθαι, εἰ ἤθελεν: καίτοι καὶ τὸ ὀλιγάκις ἰσχὺν εἶχεν. κἂν θερμῷ μὴ θέλῃς, ψυχρῷ.","st":"4.11"},{"sp":"N","t":"— ἀλλὰ λέγει Ἀριστοφάνης τοὺς ὠχριῶντας, τοὺς ἀνυποδήτους λέγω. — Λέγει γὰρ καὶ ἀεροβατεῖν αὐτὸν καὶ ἐκ τῆς παλαίστρας κλέπτειν τὰ ἱμάτια.","st":"4.11"},{"sp":"N","t":"ἐπεί τοι πάντες οἱ γεγραφότες περὶ Σωκράτους πάντα τἀναντία αὐτῷ προσμαρτυροῦσιν, ὅτι ἡδὺς οὐ μόνον ἀκοῦσαι, ἀλλὰ καὶ ἰδεῖν ἦν. πάλιν περὶ Διογένους ταὐτὰ γράφουσι.","st":"4.11"},{"sp":"N","t":"δεῖ γὰρ μηδὲ κατὰ τὴν ἀπὸ τοῦ σώματος ἔμφασιν ἀπὸ φιλοσοφίας ἀποσοβεῖν τοὺς πολλούς, ἀλλ᾽ ὥσπερ τὰ ἄλλα εὔθυμον καὶ ἀτάραχον ἐπιδεικνύειν αὑτὸν οὕτως καὶ ἀπὸ τοῦ σώματος.","st":"4.11"},{"sp":"N","t":"‘ἴδετε, ὦ ἄνθρωποι, ὅτι οὐδὲν ἔχω, οὐδενὸς δέομαι: ἴδετε, πῶς ἄοικος ὢν καὶ ἄπολις καὶ φυγάς, ἂν οὕτως τύχῃ, καὶ ἀνέστιος πάντων τῶν εὐπατριδῶν καὶ πλουσίων ἀταραχώτερον διάγω καὶ εὐρούστερον. ἀλλὰ καὶ τὸ σωμάτιον ὁρᾶτε ὅτι οὐ κακοῦται ὑπὸ τῆς αὐστηρᾶς διαίτης.’","st":"4.11"},{"sp":"N","t":"ἂν δέ μοι ταῦτα λέγῃ τις ἀνθρώπου σχῆμα καταδίκου ἔχων καὶ πρόσωπον, τίς με πείσει θεῶν προσελθεῖν φιλοσοφίᾳ, ἥ γε τοιούτους ποιεῖ; μὴ γένοιτο: οὐδ᾽, εἰ σοφὸς ἔμελλον εἶναι, ἤθελον.","st":"4.11"},{"sp":"N","t":"ἐγὼ μὲν νὴ τοὺς θεοὺς τὸν νέον τὸν πρώτως κινούμενον θέλω μᾶλλον ἐλθεῖν πρός με πεπλασμένον τὴν κόμην ἢ κατεφθινηκότα καὶ ῥυπαρόν. βλέπεται γάρ τις ἐν ἐκείνῳ τοῦ καλοῦ φαντασία, ἔφεσις δὲ τοῦ εὐσχήμονος. ὅπου δ᾽ αὐτὸν εἶναι φαντάζεται, ἐκεῖ καὶ φιλοτεχνεῖ.","st":"4.11"},{"sp":"N","t":"λοιπὸν ὑποδεῖξαι μόνον αὐτῷ δεῖ καὶ εἰπεῖν ‘νεανίσκε, τὸ καλὸν ζητεῖς καὶ εὖ ποιεῖς. ἴσθι οὖν, ὅτι ἐκεῖ φύεται, ὅπου τὸν λόγον ἔχεις: ἐκεῖ αὐτὸ ζήτει, ὅπου τὰς ὁρμὰς καὶ τὰς ἀφορμάς, ὅπου τὰς ὀρέξεις, τὰς ἐκκλίσεις.","st":"4.11"},{"sp":"N","t":"τοῦτο γὰρ ἔχεις ἐν σεαυτῷ ἐξαίρετον, τὸ σωμάτιον δὲ φύσει πηλός ἐστιν. τί πονεῖς εἰκῇ περὶ αὐτό; εἰ μηδὲν ἕτερον, τῷ χρόνῳ γνώσῃ, ὅτι οὐδέν ἐστιν.’ ἂν δέ μοι ἔλθῃ κεκοπρωμένος,","st":"4.11"},{"sp":"N","t":"ῥυπαρός, μύστακα ἔχων μέχρι τῶν γονάτων, τί αὐτῷ εἰπεῖν ἔχω, ἀπὸ ποίας αὐτὸν ὁμοιότητος ἐπαγαγεῖν;","st":"4.11"},{"sp":"N","t":"περὶ τί γὰρ ἐσπούδακεν ὅμοιον τῷ καλῷ, ἵν᾽ αὐτὸν μεταθῶ καὶ εἴπω ‘οὐκ ἔστιν ἐνθάδε τὸ καλόν, ἀλλ᾽ ἐνθάδε;’ θέλεις αὐτῷ λέγω ‘οὐκ ἔστιν ἐν τῷ κεκοπρῶσθαι τὸ καλόν, ἀλλ᾽ ἐν τῷ λόγῳ;’ ἐφίεται γὰρ τοῦ καλοῦ; ἔμφασιν γάρ τινα αὐτοῦ ἔχει; ἄπελθε καὶ χοίρῳ διαλέγου, ἵν᾽ ἐν βορβόρῳ μὴ κυλίηται.","st":"4.11"},{"sp":"N","t":"διὰ τοῦτο καὶ Πολέμωνος ἥψαντο οἱ λόγοι οἱ Ξενοκράτους ὡς φιλοκάλου νεανίσκου: εἰσῆλθεν γὰρ ἔχων ἐναύσματα τῆς περὶ τὸ καλὸν σπουδῆς, ἀλλαχοῦ δ᾽ αὐτὸ ζητῶν.","st":"4.11"},{"sp":"N","t":"ἐπεί τοι οὐδὲ τὰ ζῷα τὰ ἀνθρώποις σύντροφα ῥυπαρὰ ἐποίησεν ἡ φύσις. μή τι ἵππος κυλίεται ἐν βορβόρῳ, μή τι κύων γενναῖος; ἀλλ᾽ ὁ ὗς καὶ τὰ σαπρὰ χηνίδια καὶ σκώληκες καὶ ἀράχναι, τὰ μακροτάτω τῆς ἀνθρωπίνης συναναστροφῆς ἀπεληλασμένα.","st":"4.11"},{"sp":"N","t":"σὺ οὖν ἄνθρωπος ὢν οὐδὲ ζῷον εἶναι θέλεις τῶν ἀνθρώποις συντρόφων, ἀλλὰ σκώληξ μᾶλλον ἢ ἀράχνιον; οὐ λούσῃ πού ποτε ὡς θέλεις, οὐκ ἀποπλυνεῖς σεαυτόν, οὐχ ἥξεις καθαρός, ἵνα σοι χαίρωσιν οἱ συνόντες; ἀλλὰ καὶ εἰς τὰ ἱερὰ ἡμῖν συνέρχῃ τοιοῦτος, ὅπου πτῦσαι οὐ νενόμισται οὐδ᾽ ἀπομύξασθαι, ὅλος ὢν πτύσμα καὶ μύξα;","st":"4.11"},{"sp":"N","t":"τί οὖν; καλλωπίζεσθαί τις ἀξιοῖ; μὴ γένοιτο, εἰ μὴ ἐκεῖνο ὃ πεφύκαμεν, τὸν λόγον, τὰ δόγματα, τὰς ἐνεργείας, τὸ δὲ σῶμα μέχρι τοῦ καθαρίου, μέχρι τοῦ μὴ προσκόπτειν.","st":"4.11"},{"sp":"N","t":"ἀλλ᾽ ἂν ἀκούσῃς, ὅτι οὐ δεῖ φορεῖν κόκκινα, ἀπελθὼν κόπρωσόν σου τὸν τρίβωνα ἢ κατάρρηξον. — ἀλλὰ πόθεν ἔχω καλὸν τρίβωνα; — ἄνθρωπε, ὕδωρ ἔχεις, πλῦνον αὐτόν.","st":"4.11"},{"sp":"N","t":"ἰδοὺ νέος ἀξιέραστος, ἰδοὺ πρεσβύτης ἄξιος τοῦ ἐρᾶν καὶ ἀντερᾶσθαι, ᾧ τις υἱον αὑτοῦ παραδῷ ... θησόμενον, ᾧ θυγατέρες, ᾧ νέοι προσελεύσονται, ἂν οὕτως τύχῃ, ἵνα ἐν κοπρῶνι λέγῃ τὰς σχολάς.","st":"4.11"},{"sp":"N","t":"μὴ γένοιτο. πᾶσα ἐκτροπὴ ἀπό τινος ἀνθρωπικοῦ γίνεται, αὕτη ἐγγύς ἐστι τῷ μὴ ἀνθρωπικὴ εἶναι. περὶ προσοχῆς. ὅταν ἀφῇς πρὸς ὀλίγον τὴν προσοχήν, μὴ τοῦτο φαντάζου, ὅτι, ὁπόταν θέλῃς, ἀναλήψῃ αὐτήν, ἀλλ᾽ ἐκεῖνο πρόχειρον ἔστω σοι, ὅτι παρὰ τὸ σήμερον ἁμαρτηθὲν εἰς τἆλλα χεῖρον ἀνάγκη σοι τὰ πράγματα ἔχειν.","st":"4.11"},{"sp":"N","t":"πρῶτον μὲν γὰρ τὸ πάντων χαλεπώτατον ἔθος τοῦ μὴ προσέχειν ἐγγίνεται, εἶτα ἔθος τοῦ ἀναβάλλεσθαι τὴν προσοχήν: ἀιεὶ δ᾽ εἰς ἄλλον καὶ ἄλλον χρόνον εἴωθας ὑπερτίθεσθαι τὸ εὐροεῖν, τὸ εὐσχημονεῖν, τὸ κατὰ φύσιν ἔχειν καὶ διεξάγειν.","st":"4.12"},{"sp":"N","t":"εἰ μὲν οὖν λυσιτελὴς ἡ ὑπέρθεσίς ἐστιν, ἡ παντελὴς ἀπόστασις αὐτῆς ἐστι λυσιτελεστέρα: εἰ δ᾽ οὐ λυσιτελεῖ, τί οὐχὶ διηνεκῆ τὴν προσοχὴν φυλάσσεις;","st":"4.12"},{"sp":"N","t":"‘σήμερον παῖξαι θέλω.’ τί οὖν κωλύει προσέχοντα; ‘ᾆσαι.’ τί οὖν κωλύει προσέχοντα; μὴ γὰρ ἐξαιρεῖταί τι μέρος τοῦ βίου, ἐφ᾽ ὃ οὐ διατείνει τὸ προσέχειν; χεῖρον γὰρ αὐτὸ προσέχων ποιήσεις, βέλτιον δὲ μὴ προσέχων;","st":"4.12"},{"sp":"N","t":"καὶ τί ἄλλο τῶν ἐν τῷ βίῳ κρεῖσσον ὑπὸ τῶν μὴ προσεχόντων γίνεται; ὁ τέκτων μὴ προσέχων ... ; ὁ κυβερνήτης μὴ προσέχων κυβερνᾷ ἀσφαλέστερον; ἄλλο δέ τι τῶν μικροτέρων ἔργων ὑπὸ ἀπροσεξίας ἐπιτελεῖται κρεῖσσον;","st":"4.12"},{"sp":"N","t":"οὐκ αἰσθάνῃ, ὅτι, ἐπειδὰν ἀφῇς τὴν γνώμην, οὐκ ἔτι ἐπὶ σοί ἐστιν ἀνακαλέσασθαι αὐτήν, οὐκ ἐπὶ τὸ εὔσχημον, οὐκ ἐπὶ τὸ αἰδῆμον, οὐκ ἐπὶ τὸ κατεσταλμένον; ἀλλὰ πᾶν τὸ ἐπελθὸν ποιεῖς, ταῖς προθυμίαις ἐπακολουθεῖς. τίσιν οὖν δεῖ με προσέχειν;","st":"4.12"},{"sp":"N","t":"— πρῶτον μὲν ἐκείνοις τοῖς καθολικοῖς καὶ ἐκεῖνα πρόχειρα ἔχειν καὶ χωρὶς ἐκείνων μὴ καθεύδειν, μὴ ἀνίστασθαι, μὴ πίνειν, μὴ ἐσθίειν, μὴ συμβάλλειν ἀνθρώποις: ὅτι προαιρέσεως ἀλλοτρίας κύριος οὐδείς, ἐν ταύτῃ δὲ μόνῃ τἀγαθὸν καὶ κακόν.","st":"4.12"},{"sp":"N","t":"οὐδεὶς οὖν κύριος οὔτ᾽ ἀγαθόν μοι περιποιῆσαι οὔτε κακῷ με περιβαλεῖν, ἀλλ᾽ ἐγὼ αὐτὸς ἐμαυτοῦ κατὰ ταῦτα ἐξουσίαν ἔχω μόνος.","st":"4.12"},{"sp":"N","t":"ὅταν οὖν ταῦτα ἀσφαλῆ μοι ᾖ, τί ἔχω περὶ τὰ ἐκτὸς ταράσσεσθαι; ποῖος τύραννος φοβερός, ποία νόσος, ποία πενία, ποῖον πρόσκρουσμα;","st":"4.12"},{"sp":"N","t":"— ἀλλ᾽ οὐκ ἤρεσα τῷ δεῖνι. — μὴ οὖν ἐκεῖνος ἐμόν ἐστιν ἔργον, μή τι ἐμὸν κρίμα; — οὔ. — τί οὖν ἔτι μοι μέλει; — ἀλλὰ δοκεῖ τις εἶναι. — ὄψεται αὐτὸς καὶ οἷς δοκεῖ,","st":"4.12"},{"sp":"N","t":"ἐγὼ δ᾽ ἔχω, τίνι με δεῖ ἀρέσκειν, τίνι ὑποτετάχθαι, τίνι πείθεσθαι: τῷ θεῷ καὶ","st":"4.12"},{"sp":"N","t":"μετ᾽ ἐκεῖνον ... ἐμὲ ἐκεῖνος συνέστησεν ἐμαυτῷ καὶ τὴν ἐμὴν προαίρεσιν ὑπέταξεν ἐμοὶ μόνῳ δοὺς κανόνας εἰς χρῆσιν αὐτῆς τὴν ὀρθήν, οἷς ὅταν κατακολουθήσω, ἐν συλλογισμοῖς οὐκ ἐπιστρέφομαι οὐδενὸς τῶν ἄλλο τι λεγόντων, ἐν μεταπίπτουσιν οὐ φροντίζω οὐδενός. διὰ τί οὖν ἐν τοῖς μείζοσιν ἀνιῶσί με οἱ ψέγοντες;","st":"4.12"},{"sp":"N","t":"τί τὸ αἴτιον ταύτης τῆς ταραχῆς; οὐδὲν ἄλλο ἢ ὅτι ἐν τούτῳ τῷ τόπῳ ἀγύμναστός εἰμι.","st":"4.12"},{"sp":"N","t":"ἐπεί τοι πᾶσα ἐπιστήμη καταφρονητική ἐστι τῆς ἀγνοίας καὶ τῶν ἀγνοούντων καὶ οὐ μόνον αἱ ἐπιστῆμαι, ἀλλὰ καὶ αἱ τέχναι. φέρε ὃν θέλεις σκυτέα καὶ τῶν πολλῶν καταγελᾷ περὶ τὸ αὑτοῦ ἔργον: φέρε ὃν θέλεις τέκτονα.","st":"4.12"},{"sp":"N","t":"πρῶτον μὲν οὖν ταῦτα ἔχειν πρόχειρα καὶ μηδὲν δίχα τούτων ποιεῖν, ἀλλὰ τετάσθαι τὴν ψυχὴν ἐπὶ τοῦτον τὸν σκοπόν, μηδὲν τῶν ἔξω διώκειν, μηδὲν τῶν ἀλλοτρίων, ἀλλ᾽ ὡς διέταξεν ὁ δυνάμενος, τὰ προαιρετικὰ ἐξ ἅπαντος, τὰ δ᾽ ἄλλα ὡς ἂν διδῶται.","st":"4.12"},{"sp":"N","t":"ἐπὶ τούτοις δὲ μεμνῆσθαι, τίνες ἐσμὲν καὶ τί ἡμῖν ὄνομα, καὶ πρὸς τὰς δυνάμεις τῶν σχέσεων πειρᾶσθαι τὰ καθήκοντα ἀπευθύνειν:","st":"4.12"},{"sp":"N","t":"τίς καιρὸς ᾠδῆς, τίς καιρὸς παιδειᾶς, τίνων παρόντων: τί ἔσται ἀπὸ τοῦ πράγματος: μή τι καταφρονήσωσιν ἡμῶν οἱ συνόντες, μή τι ἡμεῖς αὐτῶν: πότε σκῶψαι καὶ τίνας ποτὲ καταγελάσαι καὶ ἐπὶ τίνι ποτὲ συμπεριενεχθῆναι καὶ τίνι, καὶ λοιπὸν ἐν τῇ συμπεριφορᾷ πῶς τηρῆσαι τὸ αὑτοῦ. ὅπου δ᾽ ἂν ἀπονεύσῃς ἀπό τινος τούτων,","st":"4.12"},{"sp":"N","t":"εὐθὺς ζημία, οὐκ ἔξωθέν ποθεν, ἀλλ᾽ ἐξ αὐτῆς τῆς ἐνεργείας.","st":"4.12"},{"sp":"N","t":"τί οὖν; δυνατὸν ἀναμάρτητον ἤδη εἶναι; ἀμήχανον, ἀλλ᾽ ἐκεῖνο δυνατὸν πρὸς τὸ μὴ ἁμαρτάνειν τετάσθαι διηνεκῶς. ἀγαπητὸν γάρ, εἰ μηδέποτ᾽ ἀνιέντες ταύτην τὴν προσοχὴν ὀλίγων γε ἁμαρτημάτων ἐκτὸς ἐσόμεθα. νῦν δ᾽ ὅταν εἴπῃς","st":"4.12"},{"sp":"N","t":"‘ἀπαύριον προσέξω,’ ἴσθι ὅτι τοῦτο λέγεις ‘σήμερον ἔσομαι ἀναίσχυντος, ἄκαιρος, ταπεινός: ἐπ᾽ ἄλλοις ἔσται τὸ λυπεῖν με: ὀργισθήσομαι σήμερον, φθονήσω.’","st":"4.12"},{"sp":"N","t":"βλέπε, ὅσα κακὰ σεαυτῷ ἐπιτρέπεις. ἀλλ᾽ εἴ σοι αὔριον καλῶς ἔχει, πόσῳ κρεῖττον σήμερον: εἰ αὔριον συμφέρει, πολὺ μᾶλλον σήμερον, ἵνα καὶ αὔριον δυνηθῇς καὶ μὴ πάλιν ἀναβάλῃ εἰς τρίτην. πρὸς τοὺς εὐκόλως ἐκφέροντας τὰ αὑτῶν. ὅταν τις ἡμῖν ἁπλῶς δόξῃ διειλέχθαι περὶ τῶν ἑαυτοῦ πραγμάτων, πώς ποτε ἐξαγόμεθα καὶ αὐτοὶ πρὸς τὸ ἐκφέρειν πρὸς αὐτὸν τὰ ἑαυτῶν ἀπόρρητα καὶ τοῦτο ἁπλοῦν οἰόμεθα εἶναι:","st":"4.12"},{"sp":"N","t":"πρῶτον μὲν ὅτι ἄνισον εἶναι δοκεῖ αὐτὸν μὲν ἀκηκοέναι τὰ τοῦ πλησίον, μὴ μέντοι μεταδιδόναι κἀκείνῳ ἐν τῷ μέρει τῶν ἡμετέρων. εἶθ᾽ ὅτι οἰόμεθα οὐχ ἁπλῶν ἀνθρώπων παρέξειν αὐτοῖς φαντασίαν σιωπῶντες τὰ ἴδια.","st":"4.13"},{"sp":"N","t":"ἀμέλει πολλάκις εἰώθασιν λέγειν ‘ἐγώ σοι πάντα τἀμαυτοῦ εἴρηκα, σύ μοι οὐδὲν τῶν σῶν εἰπεῖν θέλεις;","st":"4.13"},{"sp":"N","t":"ποῦ γίνεται τοῦτο;’ πρόσεστι δὲ καὶ τὸ οἴεσθαι ἀσφαλῶς πιστεύειν τῷ ἤδη τὰ αὑτοῦ πεπιστευκότι: ὑπέρχεται γὰρ ἡμᾶς, ὅτι οὐκ ἄν ποτε οὗτος ἐξείποι τὰ ἡμέτερα εὐλαβούμενος, μήποτε καὶ ἡμεῖς ἐξείπωμεν τὰ ἐκείνου.","st":"4.13"},{"sp":"N","t":"οὕτως καὶ ὑπὸ τῶν στρατιωτῶν ἐν Ῥώμῃ οἱ προπετεῖς λαμβάνονται. παρακεκάθικέ σοι στρατιώτης ἐν σχήματι ἰδιωτικῷ καὶ ἀρξάμενος κακῶς λέγει τὸν Καίσαρα, εἶτα σὺ ὥσπερ ἐνέχυρον παρ᾽ αὐτοῦ λαβὼν τῆς πίστεως τὸ αὐτὸν τῆς λοιδορίας κατῆρχθαι λέγεις καὶ αὐτὸς ὅσα φρονεῖς, εἶτα δεθεὶς ἀπάγῃ.","st":"4.13"},{"sp":"N","t":"τοιοῦτόν τι καὶ ἐν τῷ καθόλου πάσχομεν. οὐ γὰρ ὡς ἐμοὶ ἐκεῖνος ἀσφαλῶς πεπίστευκεν τὰ ἑαυτοῦ, οὕτως κἀγὼ τῷ ἐπιτυχόντι:","st":"4.13"},{"sp":"N","t":"ἀλλ᾽ ἐγὼ μὲν ἀκούσας σιωπῶ, ἄν γε ὦ τοιοῦτος, ὁ δ᾽ ἐξελθὼν ἐκφέρει πρὸς πάντας. εἶτ᾽ ἂν γνῶ τὸ γενόμενον, ἂν μὲν ὦ καὶ αὐτὸς ἐκείνῳ ὅμοιος, ἀμύνασθαι θέλων ἐκφέρω τὰ ἐκείνου καὶ φύρω καὶ φύρομαι.","st":"4.13"},{"sp":"N","t":"ἂν δὲ μνημονεύω, ὅτι ἄλλος ἄλλον οὐ βλάπτει, ἀλλὰ τὰ αὑτοῦ ἔργα ἕκαστον καὶ βλάπτει καὶ ὠφελεῖ, τούτου μὲν κρατῶ τοῦ μὴ ὅμοιόν τι ποιῆσαι ἐκείνῳ, ὅμως δ᾽ ὑπὸ φλυαρίας τῆς ἐμαυτοῦ πέπονθα ἃ πέπονθα.","st":"4.13"},{"sp":"N","t":"ναί: ἀλλ᾽ ἄνισόν ἐστιν ἀκούσαντα τὰ τοῦ πλησίον ἀπόρρητα αὐτὸν ἐν τῷ μέρει μηδενὸς μεταδιδόναι αὐτῷ.","st":"4.13"},{"sp":"N","t":"— μὴ γάρ σε παρεκάλουν, ἄνθρωπε; μὴ γὰρ ἐπὶ συνθήκαις τισὶν ἐξήνεγκας τὰ σαυτοῦ, ἵν᾽ ἀκούσῃς ἐν τῷ μέρει καὶ τὰ ἐμά;","st":"4.13"},{"sp":"N","t":"εἰ σὺ φλύαρος εἶ καὶ πάντας τοὺς ἀπαντήσαντας φίλους εἶναι δοκεῖς, θέλεις καὶ ἐμὲ ὅμοιόν σοι γενέσθαι; τί δ᾽, εἰ σὺ καλῶς μοι πεπίστευκας τὰ σαυτοῦ, σοὶ δ᾽ οὐκ ἔστι καλῶς πιστεῦσαι, θέλεις με προσπεσεῖν;","st":"4.13"},{"sp":"N","t":"οἷον εἰ πίθον εἶχον ἐγὼ μὲν στεγνόν, σὺ δὲ τετρυπημένον καὶ ἐλθὼν παρακατέθου μοι τὸν σαυτοῦ οἶνον, ἵνα βάλω εἰς τὸν ἐμὸν πίθον, εἶτ᾽ ἠγανάκτεις ὅτι μὴ κἀγὼ σοὶ πιστεύω τὸν ἐμαυτοῦ οἶνον: σὺ γὰρ τετρυπημένον ἔχεις τὸν πίθον.","st":"4.13"},{"sp":"N","t":"πῶς οὖν ἔτι ἴσον γίνεται; σὺ πιστῷ παρακατέθου, σὺ αἰδήμονι, τὰς ἑαυτοῦ ἐνεργείας μόνας βλαβερὰς ἡγουμένῳ καὶ ὠφελίμους, τῶν δ᾽ ἐκτὸς οὐδέν:","st":"4.13"},{"sp":"N","t":"ἐγὼ σοὶ θέλεις παρακαταθῶμαι, ἀνθρώπῳ τὴν ἑαυτοῦ προαίρεσιν ἠτιμακότι, θέλοντι δὲ κερματίου τυχεῖν ἢ ἀρχῆς τινος ἢ προαγωγῆς ἐν τῇ αὐλῇ, κἂν μέλλῃς τὰ τέκνα σου κατασφάζειν, ὡς ἡ Μήδεια;","st":"4.13"},{"sp":"N","t":"ποῦ τοῦτο ἴσον ἐστίν; ἀλλὰ δεῖξόν μοι σαυτὸν πιστόν, αἰδήμονα, βέβαιον, δεῖξον, ὅτι δόγματα ἔχεις φιλικά, δεῖξόν σου τὸ ἀγγεῖον ὅτι οὐ τέτρηται καὶ ὄψει, πῶς οὐκ ἀναμένω ἵνα μοι σὺ πιστεύσῃς τὰ σαυτοῦ, ἀλλ᾽ αὐτὸς ἐλθὼν σὲ παρακαλῶ ἀκοῦσαι τῶν ἐμῶν.","st":"4.13"},{"sp":"N","t":"τίς γὰρ οὐ θέλει χρήσασθαι ἀγγείῳ καλῷ, τίς ἀτιμάζει σύμβουλον εὔνουν καὶ πιστόν, τίς οὐκ ἄσμενος δέξηται τὸν ὥσπερ φορτίου μεταληψόμενον τῶν αὐτοῦ περιστάσεων καὶ αὐτῷ τούτῳ κουφιοῦντα αὐτὸν τῷ μεταλαβεῖν; ναί: ἀλλ᾽ ἐγὼ σοὶ πιστεύω, σὺ ἐμοὶ οὐ πιστεύεις.","st":"4.13"},{"sp":"N","t":"— πρῶτον μὲν οὐδὲ σὺ ἐμοὶ πιστεύεις, ἀλλὰ φλύαρος εἶ καὶ διὰ τοῦτο οὐδὲν δύνασαι κατασχεῖν. ἐπεί τοι εἰ τοῦτό ἐστιν, ἐμοὶ μόνῳ αὐτὰ πίστευσον:","st":"4.13"},{"sp":"N","t":"νῦν δ᾽ ὃν ἂν εὐσχολοῦντα ἴδῃς, παρακαθίσας αὐτῷ λέγεις ‘ἀδελφέ, οὐδένα σου ἔχω εὐνούστοτερον οὐδὲ φίλτερον, παρακαλῶ σε ἀκοῦσαι τὰ ἐμά:’ καὶ τοῦτο πρὸς τοὺς οὐδέ τι ὀλίγον ἐγνωσμένους ποιεῖς.","st":"4.13"},{"sp":"N","t":"εἰ δὲ καὶ πιστεύεις ἐμοί, δῆλον ὅτι ὡς πιστῷ καὶ αἰδήμονι, οὐχ ὅτι σοὶ τὰ ἐμαυτοῦ ἐξεῖπον.","st":"4.13"},{"sp":"N","t":"ἄφες οὖν, ἵνα κἀγὼ ταὐτὰ ὑπολάβω. δεῖξόν μοι, ὅτι, ἄν τις τινὶ τὰ αὑτοῦ ἐξείπῃ, ἐκεῖνος πιστός ἐστι καὶ αἰδήμων. εἰ γὰρ τοῦτο ἦν, ἐγὼ περιερχόμενος πᾶσιν ἀνθρώποις τὰ ἐμαυτοῦ ἂν ἔλεγον, εἰ τούτου ἕνεκα ἔμελλον πιστὸς καὶ αἰδήμων ἔσεσθαι. τὸ δ᾽ ἐστὶν οὐ τοιοῦτον, ἀλλὰ δογμάτων δεῖ οὐχ ὧν ἔτυχεν.","st":"4.13"},{"sp":"N","t":"ἂν γοῦν τινα ἴδῃς περὶ τὰ ἀπροαίρετα ἐσπουδακότα καὶ τούτοις ὑποτεταχότα τὴν αὑτοῦ προαίρεσιν, ἴσθι ὅτι ὁ ἄνθρωπος οὗτος μυρίους ἔχει τοὺς ἀναγκάζοντας, τοὺς κωλύοντας.","st":"4.13"},{"sp":"N","t":"οὐκ ἔστιν αὐτῷ χρεία πίσσης ἢ τροχοῦ πρὸς τὸ ἐξειπεῖν ἃ οἶδεν, ἀλλὰ παιδισκαρίου νευμάτιον, ἂν οὕτως τύχῃ, ἐκσείσει αὐτόν, Καισαριανοῦ φιλοφροσύνη, ἀρχῆς ἐπιθυμία, κληρονομίας, ἄλλα τούτοις ὅμοια τρισμύρια.","st":"4.13"},{"sp":"N","t":"μεμνῆσθαι οὖν ἐν τοῖς καθόλου, ὅτι οἱ ἀπόρρητοι λόγοι πίστεως χρείαν ἔχουσι καὶ δογμάτων τοιούτων: ταῦτα δὲ ποῦ νῦν εὑρεῖν ῥᾳδίως;","st":"4.13"},{"sp":"N","t":"ἢ δειξάτω μοί τις τὸν οὕτως ἔχοντα, ὥστε λέγειν ‘ἐμοὶ μόνων μέλει τῶν ἐμῶν, τῶν ἀκωλύτων, τῶν φύσει ἐλευθέρων. ταύτην οὐσίαν ἔχω τοῦ ἀγαθοῦ, τὰ δὲ ἄλλα γινέσθω ὡς ἂν διδῶται: οὐ διαφέρομαι.’","st":"4.13"}],[]);})();
